CREATE OR REPLACE FUNCTION public.abort_fakturoid_ticket_order_v1(p_order_id bigint, p_command_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_state text;
  v_occasion bigint;
  v_queue_id bigint;
  v_before_users uuid[];
  v_abort_command uuid := extensions.gen_random_uuid();
  v_hash text;
BEGIN
  PERFORM public.require_client_sync_service_role_v1();
  PERFORM public.lock_order_capacity_scope_internal(ARRAY[p_order_id]);
  IF EXISTS(SELECT 1 FROM eshop.waitlist_acceptance_attempts WHERE command_id=p_command_id AND target_order_id=p_order_id AND state='aborted') THEN RETURN; END IF;
  SELECT o.state,o.occasion INTO v_state,v_occasion
  FROM eshop.orders o WHERE o.id=p_order_id FOR UPDATE;
  IF v_state='storno' THEN RETURN; END IF;
  IF v_state IS DISTINCT FROM 'preparing_payment' OR p_command_id IS NULL THEN
    RAISE check_violation USING MESSAGE='Fakturoid order is not pending';
  END IF;
  SELECT q.id INTO v_queue_id FROM public.email_messages q
  WHERE q.code='TICKET_ORDER_CONFIRMATION'
    AND q.data->>'command_id'=p_command_id::text
    AND (q.data#>>'{ticket_order,order,id}')::bigint=p_order_id
    AND q.data->>'fakturoid_pending'='true'
  FOR UPDATE;
  IF v_queue_id IS NULL THEN
    RAISE check_violation USING MESSAGE='Fakturoid order confirmation claim missing';
  END IF;
  SELECT coalesce(array_agg(ou."user"),'{}'::uuid[]) INTO v_before_users
  FROM public.occasion_users ou WHERE ou.occasion=v_occasion;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'order',p_order_id,'reason','fakturoid_failed')::text,'UTF8'),'sha256'),'hex');
  PERFORM public.begin_anonymous_client_mutation_v1(v_abort_command,
    'inventory.order.fakturoid_abort',v_occasion,extensions.gen_random_uuid(),v_hash);
  UPDATE public.email_messages SET workflow_state='cancelled',last_error='fakturoid_aborted' WHERE id=v_queue_id;
  IF NOT public.abort_waitlist_acceptance_internal(p_order_id,p_command_id) THEN
    UPDATE eshop.orders SET state='ordered' WHERE id=p_order_id;
    PERFORM public.cancel_order_domain_internal_v1(p_order_id,false);
  END IF;
  PERFORM public.complete_profile_inventory_membership_mutation_v1(
    v_abort_command,v_occasion,'inventory.order.fakturoid_abort',
    jsonb_build_array(jsonb_build_object('entityType','order',
      'entityId',p_order_id,'operation','update','safeLabel','Failed order',
      'changedFields',jsonb_build_array('state','tickets','allocations'))),
    v_before_users,jsonb_build_object('orderId',p_order_id),'service');
END;
$function$

CREATE OR REPLACE FUNCTION public.abort_waitlist_acceptance_internal(p_order bigint, p_command uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE a eshop.waitlist_acceptance_attempts; s jsonb; p jsonb; expiry timestamptz;
 original_ticket eshop.tickets; restored_outcome text; original_id bigint;
BEGIN
 SELECT * INTO a FROM eshop.waitlist_acceptance_attempts WHERE command_id=p_command AND target_order_id=p_order;
 IF a.command_id IS NULL THEN RETURN false; END IF;
 PERFORM public.lock_order_capacity_scope_internal(ARRAY[a.source_order_id,a.target_order_id]);
 SELECT * INTO STRICT a FROM eshop.waitlist_acceptance_attempts WHERE command_id=p_command FOR UPDATE;
 IF a.state='aborted' THEN RETURN true; END IF;
 IF a.state<>'preparing' THEN RAISE EXCEPTION 'Acceptance attempt already completed'; END IF;
 SELECT expires_at INTO expiry FROM eshop.waitlist_offers WHERE id=a.offer_id FOR UPDATE;
 PERFORM public.cancel_order_email_intents(p_order);
 PERFORM public.internal_storno_tickets_221(a.ticket_ids);
 DELETE FROM eshop.order_product_ticket WHERE "order"=a.target_order_id AND ticket=ANY(a.ticket_ids);
 IF a.conversion='in_place' THEN
  UPDATE eshop.orders SET state='waitlisted',price=NULL,payment_info=NULL,data=a.previous_order_data->'data',updated_at=clock_timestamp() WHERE id=a.target_order_id;
 ELSE
  UPDATE eshop.orders SET state='storno',price=0,payment_info=NULL,updated_at=clock_timestamp() WHERE id=a.target_order_id;
 END IF;
 -- Only the selected tickets are fenced by the preparing target. Never restore
 -- unselected/displaced answers or resurrect a concurrently withdrawn remainder.
 FOR p IN SELECT * FROM jsonb_array_elements(a.previous_tickets) LOOP
  IF NOT (p->>'id')::bigint=ANY(a.ticket_ids) THEN CONTINUE; END IF;
  UPDATE eshop.tickets SET state=p->>'state',ticket_symbol=p->>'ticket_symbol',data=p->'data',note=p->>'note',
   note_hidden=p->>'note_hidden',waitlist_queue_at=(p->>'waitlist_queue_at')::timestamptz,updated_at=clock_timestamp() WHERE id=(p->>'id')::bigint;
 END LOOP;
 INSERT INTO eshop.order_product_ticket SELECT * FROM jsonb_populate_recordset(NULL::eshop.order_product_ticket,a.previous_links);
 UPDATE eshop.waitlist_offer_slots SET outcome='accepted' WHERE id=ANY(a.slot_ids);
 FOR s IN SELECT * FROM jsonb_array_elements(a.previous_slots) LOOP
  original_id:=(s->>'ticket_id')::bigint;
  SELECT * INTO STRICT original_ticket FROM eshop.tickets WHERE id=original_id FOR UPDATE;
  restored_outcome:=CASE
   WHEN original_ticket.state<>'waitlisted' OR NOT EXISTS(SELECT 1 FROM eshop.order_product_ticket x WHERE x.ticket=original_id AND x."order"=a.source_order_id)
    OR EXISTS(SELECT 1 FROM eshop.waitlist_offer_slots other WHERE other.ticket_id=original_id AND other.outcome='pending' AND NOT other.id=ANY(a.slot_ids)) THEN 'cancelled'
   WHEN EXISTS(SELECT 1 FROM eshop.waitlist_offer_slots other JOIN eshop.waitlist_offers ow ON ow.id=other.offer_id
     WHERE other.ticket_id=original_id AND other.outcome IN ('declined','cancelled')
     AND ow.created_at>(SELECT created_at FROM eshop.waitlist_offers WHERE id=a.offer_id)) THEN 'cancelled'
   WHEN expiry<=clock_timestamp() THEN 'expired' ELSE 'pending' END;
  UPDATE eshop.waitlist_offer_slots SET ticket_id=original_id,outcome=restored_outcome,resulting_order_id=NULL,updated_at=clock_timestamp() WHERE id=(s->>'id')::uuid;
  IF restored_outcome='expired' AND original_ticket.state='waitlisted' THEN
   UPDATE eshop.tickets SET waitlist_queue_at=clock_timestamp(),updated_at=clock_timestamp() WHERE id=original_id;
  END IF;
 END LOOP;
 UPDATE eshop.waitlist_acceptance_attempts SET state='aborted',updated_at=clock_timestamp() WHERE command_id=p_command;
 UPDATE public.forms SET capacity_revision=capacity_revision+1 WHERE id=(SELECT form FROM eshop.orders WHERE id=a.source_order_id);
 INSERT INTO eshop.orders_history("order",state,data) VALUES(a.source_order_id,'waitlisted',jsonb_build_object('action','acceptance_aborted','commandId',p_command,'targetOrderId',a.target_order_id));
 RETURN true;
END $function$

CREATE OR REPLACE FUNCTION public.abuse_charge_v1(p_policy jsonb, p_scopes jsonb, p_costs jsonb DEFAULT '{}'::jsonb, p_attempt boolean DEFAULT false)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE r jsonb; s text; n bigint; used bigint; lim bigint; bucket timestamptz;
 t timestamptz:=statement_timestamp(); allowed boolean:=true; cost bigint; failed_rule text;
 retry_seconds integer:=0; needs_change boolean:=false; release_at timestamptz;
BEGIN
 IF p_policy IS NULL OR jsonb_array_length(p_policy->'rules')=0 THEN
  RAISE configuration_limit_exceeded USING MESSAGE='abuse_policy_missing'; END IF;
 FOR r IN SELECT value FROM jsonb_array_elements(p_policy->'rules') ORDER BY value->>'rule_key' LOOP
  s:=p_scopes->>(r->>'scope_kind');
  IF s IS NULL THEN RAISE invalid_parameter_value USING MESSAGE='abuse_scope_missing'; END IF;
  IF r->>'kind' IN ('bytes','duration','items') THEN CONTINUE; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('abuse:'||(r->>'rule_key')||':'||s,0));
 END LOOP;
 -- Check every rule before changing any accepted-operation counter.
 FOR r IN SELECT value FROM jsonb_array_elements(p_policy->'rules') ORDER BY value->>'rule_key' LOOP
  s:=p_scopes->>(r->>'scope_kind');
  cost:=coalesce((p_costs->>(r->>'rule_key'))::bigint,1);
  IF cost<0 THEN RAISE invalid_parameter_value USING MESSAGE='negative abuse cost'; END IF;
  lim:=least((r->>'hard_cap')::bigint,(r->>'base_limit')::bigint+
   least(coalesce((p_costs->>'growth')::bigint,0),1000000000)*(r->>'growth_increment')::bigint);
  IF r->>'kind'='rolling' THEN
   bucket:=to_timestamp(floor(extract(epoch FROM t)/(r->>'bucket_seconds')::int)*(r->>'bucket_seconds')::int);
   SELECT coalesce(sum(amount),0) INTO used FROM public.abuse_budget_usage
    WHERE rule_key=r->>'rule_key' AND scope_id=s
     AND bucket_at>=bucket-make_interval(secs=>(r->>'window_seconds')::int);
  ELSIF r->>'kind'='cumulative' THEN
   bucket:='epoch'::timestamptz;
   SELECT coalesce(sum(amount),0) INTO used FROM public.abuse_budget_usage WHERE rule_key=r->>'rule_key' AND scope_id=s;
  ELSE used:=0; END IF;
  IF used+cost>lim THEN
   allowed:=false; failed_rule:=coalesce(failed_rule,r->>'rule_key');
   IF NOT p_attempt AND r->>'kind'='rolling' AND cost<=lim THEN
    SELECT q.bucket_at INTO release_at FROM (
     SELECT bucket_at,sum(amount) OVER(ORDER BY bucket_at) AS released FROM public.abuse_budget_usage
     WHERE rule_key=r->>'rule_key' AND scope_id=s AND bucket_at>=bucket-make_interval(secs=>(r->>'window_seconds')::int)
    ) q WHERE q.released>=used+cost-lim ORDER BY q.bucket_at LIMIT 1;
    retry_seconds:=greatest(retry_seconds,ceil(extract(epoch FROM release_at+make_interval(secs=>(r->>'window_seconds')::int+(r->>'bucket_seconds')::int)-t))::integer);
   ELSIF r->>'kind'='cumulative' OR (cost>lim AND r->>'kind' IN ('bytes','items','duration')) THEN needs_change:=true;
   ELSE retry_seconds:=greatest(retry_seconds,60); END IF;
  END IF;
 END LOOP;
 IF NOT allowed AND NOT p_attempt THEN RAISE SQLSTATE 'PT429' USING MESSAGE='abuse_limit_exceeded',DETAIL=jsonb_build_object('retryAfterSeconds',CASE WHEN needs_change THEN NULL ELSE greatest(retry_seconds,1) END,'needsPolicyChange',needs_change,'policyRevision',p_policy->'revision','ruleKey',failed_rule)::text,HINT='Capacity is limited. Retry later or request a reviewed policy increase.'; END IF;
 FOR r IN SELECT value FROM jsonb_array_elements(p_policy->'rules') ORDER BY value->>'rule_key' LOOP
  IF r->>'kind' NOT IN ('rolling','cumulative') THEN CONTINUE; END IF;
  s:=p_scopes->>(r->>'scope_kind'); cost:=coalesce((p_costs->>(r->>'rule_key'))::bigint,1);
  IF cost=0 THEN CONTINUE; END IF;
  bucket:=CASE WHEN r->>'kind'='cumulative' THEN 'epoch'::timestamptz ELSE to_timestamp(floor(extract(epoch FROM t)/(r->>'bucket_seconds')::int)*(r->>'bucket_seconds')::int) END;
  INSERT INTO public.abuse_budget_usage VALUES(r->>'rule_key',s,bucket,cost,
   CASE WHEN r->>'kind'='cumulative' THEN 'infinity'::timestamptz ELSE bucket+make_interval(secs=>(r->>'window_seconds')::int+(r->>'bucket_seconds')::int) END)
  ON CONFLICT(rule_key,scope_id,bucket_at) DO UPDATE SET amount=least(1000000000001,public.abuse_budget_usage.amount+excluded.amount);
 END LOOP;
 RETURN allowed;
END $function$

CREATE OR REPLACE FUNCTION public.abuse_request_source_v1()
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE source text;
BEGIN
 BEGIN source:=((nullif(current_setting('request.headers',true),'')::jsonb)->>'x-festapp-client-ip')::inet::text;
 EXCEPTION WHEN invalid_text_representation THEN source:=NULL; END;
 RETURN public.abuse_recipient_key_v1(coalesce(source,'unknown'));
END $function$

CREATE OR REPLACE FUNCTION public.accept_occasion_team_invitation(p_token text, p_password text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE invitation public.occasion_team_invitations; recipient uuid; new_account boolean:=false; before_row jsonb; version bigint;
BEGIN
 IF p_token IS NULL OR p_token !~ '^[0-9a-f]{64}$' THEN RAISE invalid_parameter_value USING MESSAGE='Invalid invitation'; END IF;
 SELECT * INTO invitation FROM public.occasion_team_invitations
 WHERE token_hash=encode(extensions.digest(p_token,'sha256'),'hex') FOR UPDATE;
 IF NOT FOUND OR invitation.expires_at<=now() OR NOT EXISTS(SELECT 1 FROM public.unit_users uu
   WHERE uu.unit=invitation.unit AND uu."user"=invitation.created_by AND uu.is_manager)
 OR NOT EXISTS(SELECT 1 FROM public.occasions WHERE id=invitation.occasion AND unit=invitation.unit AND organization=invitation.organization) THEN
  RAISE invalid_parameter_value USING MESSAGE='Invalid invitation'; END IF;
 PERFORM public.check_occasion_writable(invitation.occasion);
 -- Serialize identity creation with every canonical tenant account writer.
 PERFORM pg_advisory_xact_lock(hashtextextended('user-sign-in-email:'||invitation.organization::text,0));
 SELECT id INTO recipient FROM public.user_info WHERE organization=invitation.organization
  AND lower(btrim(email_readonly))=invitation.email;
 IF invitation.accepted_at IS NOT NULL THEN
  IF auth.uid() IS DISTINCT FROM invitation.accepted_by THEN RAISE insufficient_privilege USING MESSAGE='Invitation already accepted'; END IF;
  RETURN jsonb_build_object('accepted',true,'newAccount',false,'link',(SELECT link FROM public.occasions WHERE id=invitation.occasion));
 END IF;
 IF recipient IS NOT NULL THEN
  IF auth.uid() IS DISTINCT FROM recipient THEN RAISE insufficient_privilege USING MESSAGE='Sign in with the invited account'; END IF;
 ELSE
  IF auth.uid() IS NOT NULL THEN RAISE insufficient_privilege USING MESSAGE='Sign out before creating the invited account'; END IF;
  IF p_password IS NULL OR length(p_password)<8 OR octet_length(p_password)>1024 THEN
   RAISE invalid_parameter_value USING MESSAGE='Password must have at least 8 characters'; END IF;
  recipient:=public.create_user_in_organization_with_data_pure(invitation.organization,invitation.email,p_password,'{}'::jsonb);
  new_account:=true;
 END IF;
 -- A token confers only this event's selected team role. It cannot create unit roles,
 -- change an existing account, reset credentials or downgrade other permissions.
 SELECT to_jsonb(ou) INTO before_row FROM public.occasion_users ou
 WHERE occasion=invitation.occasion AND "user"=recipient FOR UPDATE;
 INSERT INTO public.occasion_users(occasion,"user",is_editor,is_editor_view,data)
 SELECT invitation.occasion,recipient,invitation.role='editor',true,jsonb_build_object('name',ui.name,'surname',ui.surname,'email',ui.email_readonly)
 FROM public.user_info ui WHERE ui.id=recipient
 ON CONFLICT(occasion,"user") DO UPDATE SET
  is_editor=public.occasion_users.is_editor OR excluded.is_editor,
  is_editor_view=public.occasion_users.is_editor_view OR excluded.is_editor_view;
 UPDATE public.occasion_team_invitations SET accepted_by=recipient,accepted_at=now() WHERE id=invitation.id;
 INSERT INTO public.client_aggregate_versions(aggregate_type,scope_type,scope_id,aggregate_id,version)
 VALUES('occasion_user','occasion',invitation.occasion,recipient::text,1)
 ON CONFLICT(aggregate_type,scope_type,scope_id,aggregate_id) DO UPDATE SET version=public.client_aggregate_versions.version+1,updated_at=clock_timestamp()
 RETURNING public.client_aggregate_versions.version INTO version;
 -- Token acceptance is the command owner. Publish the normal profile revision
 -- and private impact, with the invitation record retaining the proved actor.
 PERFORM public.record_client_sync_commit_v1(invitation.occasion,'profile.team_invitation.accept','profile',
  jsonb_build_array(jsonb_build_object('entityType','occasion_user','entityId',recipient,'operation',CASE WHEN before_row IS NULL THEN 'insert' ELSE 'update' END,
    'safeLabel','Team invitation accepted','changedFields',jsonb_build_array('membership','rights'))),'{}'::text[],
  jsonb_build_array(jsonb_build_object('component','private_profile','userId',recipient)),'[]'::jsonb,
  CASE WHEN auth.uid() IS NULL THEN 'unknown' ELSE 'user' END,'Invited event team member accepted');
 RETURN jsonb_build_object('accepted',true,'newAccount',new_account,'link',(SELECT link FROM public.occasions WHERE id=invitation.occasion));
END $function$

CREATE OR REPLACE FUNCTION public.accept_waitlist_offer_internal(p_payload jsonb, p_command uuid, p_actor uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE w eshop.waitlist_offers; o eshop.orders; fid bigint; target bigint; ids bigint[]; selected_slots uuid[];
 n integer; remaining integer; result jsonb; input jsonb; old_tickets jsonb; old_slots jsonb; old_links jsonb; conversion text;
 original_group jsonb; remaining_group jsonb; accepted_group jsonb; history_snapshot jsonb;
BEGIN
 SELECT * INTO STRICT w FROM eshop.waitlist_offers WHERE id=(p_payload->>'offerId')::uuid;
 fid:=public.check_waitlist_scope_internal(w.order_id,w.id,p_payload->>'token',p_actor,'accept');
 PERFORM public.lock_blueprint_scope_internal(ARRAY[(SELECT occasion FROM eshop.orders WHERE id=w.order_id)]);
 PERFORM public.lock_order_capacity_scope_internal(ARRAY[w.order_id]);
 SELECT * INTO STRICT w FROM eshop.waitlist_offers WHERE id=w.id FOR UPDATE;
 SELECT * INTO STRICT o FROM eshop.orders WHERE id=w.order_id;
 PERFORM public.expire_waitlist_form_internal(fid);
 IF w.expires_at<=clock_timestamp() THEN RAISE EXCEPTION 'OFFER_EXPIRED'; END IF;
 IF o.state<>'waitlisted' THEN RAISE EXCEPTION 'OFFER_SLOT_ALREADY_RESOLVED'; END IF;
 SELECT array_agg(x::bigint) INTO ids FROM jsonb_array_elements_text(p_payload->'ticketIds') x;
 n:=coalesce(cardinality(ids),0);
 IF n<1 OR n<>(SELECT count(DISTINCT x) FROM unnest(ids) x) THEN RAISE EXCEPTION 'Invalid selected persons'; END IF;
 PERFORM 1 FROM eshop.tickets WHERE id IN(SELECT ticket FROM eshop.order_product_ticket WHERE "order"=o.id) ORDER BY id FOR UPDATE;
 original_group:=public.snapshot_waitlist_tickets_internal(o.id);
 IF n<>(SELECT count(*) FROM public.get_order_tickets_internal(o.id) p WHERE p.id=ANY(ids) AND state='waitlisted'
 AND NOT EXISTS(SELECT 1 FROM eshop.waitlist_offer_slots s WHERE s.ticket_id=p.id AND s.outcome='pending' AND s.offer_id<>w.id)) THEN
  RAISE EXCEPTION 'INVALID_CAPABILITY'; END IF;
 -- Preserve slots already attached to selected people, then exchange only the necessary unused bindings.
 SELECT array_agg(id ORDER BY CASE WHEN ticket_id=ANY(ids) THEN 0 ELSE 1 END,id) INTO selected_slots
 FROM (SELECT * FROM eshop.waitlist_offer_slots WHERE offer_id=w.id AND outcome='pending'
 ORDER BY CASE WHEN ticket_id=ANY(ids) THEN 0 ELSE 1 END,id LIMIT n FOR UPDATE) s;
 IF coalesce(cardinality(selected_slots),0)<>n THEN RAISE EXCEPTION 'OFFER_SLOT_ALREADY_RESOLVED'; END IF;
 -- Journal the exact pre-swap bindings, including displaced offered people.
 SELECT jsonb_agg(to_jsonb(p)) INTO old_tickets FROM eshop.tickets p
 WHERE id=ANY(ids) OR id IN(SELECT ticket_id FROM eshop.waitlist_offer_slots WHERE id=ANY(selected_slots));
 SELECT jsonb_agg(to_jsonb(s)) INTO old_slots FROM eshop.waitlist_offer_slots s WHERE id=ANY(selected_slots);
 SELECT coalesce(jsonb_agg(to_jsonb(x)),'[]') INTO old_links FROM eshop.order_product_ticket x WHERE x."order"=o.id AND x.ticket=ANY(ids);
 -- Release temporary bindings using a terminal outcome so the pending uniqueness invariant never needs deferral.
 UPDATE eshop.waitlist_offer_slots SET outcome='accepted' WHERE id=ANY(selected_slots);
 WITH persons AS(SELECT id,row_number() OVER(ORDER BY id) n FROM unnest(ids) id), slots AS(SELECT id,row_number() OVER(ORDER BY id) n FROM unnest(selected_slots) id)
 UPDATE eshop.waitlist_offer_slots s SET ticket_id=p.id FROM persons p JOIN slots x USING(n) WHERE s.id=x.id;
 SELECT count(*) INTO remaining FROM public.get_order_tickets_internal(o.id) WHERE state='waitlisted';
 conversion:=CASE WHEN remaining=n THEN 'in_place' ELSE 'split' END;
 target:=CASE WHEN conversion='in_place' THEN o.id ELSE public.allocate_ticket_order_identity_internal(fid) END;
 IF conversion='split' THEN UPDATE eshop.orders SET source_waitlist_order_id=o.id WHERE id=target; END IF;
 input:=p_payload->'orderDetails';
 input:=jsonb_set(input,'{ticket}',public.normalize_form_ticket_answers_internal(fid,input->'ticket'));
 IF (input->>'form')::uuid IS DISTINCT FROM (SELECT key FROM public.forms WHERE id=fid) THEN RAISE EXCEPTION 'INVALID_CAPABILITY'; END IF;
 IF jsonb_array_length(input->'ticket')<>n THEN RAISE EXCEPTION 'Selected people and tickets differ'; END IF;
 -- Each selected person must explicitly bind their stable ID to their submitted ticket.
 IF n<>(SELECT count(DISTINCT (t->>'ticketId')::bigint) FROM jsonb_array_elements(input->'ticket') t WHERE (t->>'ticketId')::bigint=ANY(ids)) THEN
  RAISE EXCEPTION 'Invalid participant ticket binding'; END IF;
 PERFORM public.validate_waitlist_answers_internal(fid,input,input->'ticket',false);
 UPDATE eshop.order_product_ticket SET "order"=target WHERE "order"=o.id AND ticket=ANY(ids);
 result:=public.finalize_ticket_order_internal_v1(target,input,true);
 IF coalesce((result->>'code')::integer,500)<>200 THEN RAISE EXCEPTION '%',result::text; END IF;
 UPDATE eshop.waitlist_offer_slots SET outcome='accepted',resulting_order_id=target,updated_at=clock_timestamp() WHERE id=ANY(selected_slots);
 PERFORM public.enqueue_ticket_order_confirmation_v1(p_command,o.occasion,result,input->>'lang');
 IF (SELECT state='preparing_payment' FROM eshop.orders WHERE id=target) THEN
  INSERT INTO eshop.waitlist_acceptance_attempts(command_id,source_order_id,target_order_id,offer_id,conversion,ticket_ids,slot_ids,previous_order_data,previous_tickets,previous_links,previous_slots)
  VALUES(p_command,o.id,target,w.id,conversion,ids,selected_slots,to_jsonb(o),old_tickets,old_links,old_slots);
 ELSE
  UPDATE eshop.waitlist_capabilities SET revoked_at=clock_timestamp() WHERE offer_id=w.id
   AND NOT EXISTS(SELECT 1 FROM eshop.waitlist_offer_slots WHERE offer_id=w.id AND outcome='pending');
 END IF;
 remaining_group:=CASE WHEN conversion='split' THEN public.snapshot_waitlist_tickets_internal(o.id) ELSE '[]'::jsonb END;
 accepted_group:=public.snapshot_waitlist_tickets_internal(target);
 history_snapshot:=jsonb_build_object('action','waitlist_accept','commandId',p_command,'sourceOrderId',o.id,
  'targetOrderId',target,'ticketIds',ids,'conversion',conversion,'ticketsBefore',original_group,
  'ticketsAfter',remaining_group,'acceptedTickets',accepted_group);
 INSERT INTO eshop.orders_history("order",state,data) VALUES(o.id,(SELECT state FROM eshop.orders WHERE id=o.id),history_snapshot);
 IF conversion='split' THEN
  INSERT INTO eshop.orders_history("order",state,data) VALUES(target,(SELECT state FROM eshop.orders WHERE id=target),history_snapshot);
 END IF;
 RETURN result||jsonb_build_object('sourceOrderId',o.id,'conversion',conversion,'waitlistSummary',public.get_waitlist_summary_internal(o.id));
END $function$

CREATE OR REPLACE FUNCTION public.ack_account_deletion_asset(p_request_id uuid, p_asset_id uuid, p_sha256 text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE job public.account_deletion_requests%ROWTYPE;
BEGIN
 PERFORM public.require_service_role();
 SELECT * INTO job FROM public.account_deletion_requests WHERE id=p_request_id FOR UPDATE;
 IF job.id IS NULL OR job.user_id IS NULL OR job.status NOT IN ('deletion_pending','failed') THEN
  RAISE object_not_in_prerequisite_state USING MESSAGE='account_deletion_request_state_conflict';
 END IF;
 UPDATE public.account_deletion_assets q SET deleted_at=COALESCE(q.deleted_at,clock_timestamp())
 FROM public.canonical_assets a WHERE q.request_id=job.id AND q.asset_id=p_asset_id
  AND a.id=q.asset_id AND (a.owner_id=job.user_id::text OR
    (q.deleted_at IS NOT NULL AND a.deleted_at IS NOT NULL)) AND a.sha256=p_sha256;
 IF NOT FOUND THEN RAISE insufficient_privilege USING MESSAGE='asset_cleanup_identity_mismatch'; END IF;
 UPDATE public.canonical_assets SET deleted_at=COALESCE(deleted_at,clock_timestamp()),
  owner_id=NULL,source_key=NULL,source_storage_record='{}'::jsonb
 WHERE id=p_asset_id;
END $function$

CREATE OR REPLACE FUNCTION public.acquire_existing_user_session_lease_v1(p_user uuid, p_owner uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_target jsonb; v_acquired uuid;
BEGIN
  PERFORM public.require_service_role();
  IF p_owner IS NULL THEN RAISE EXCEPTION 'invalid_lease_owner'; END IF;
  v_target := public.resolve_existing_user_session_v1(p_user);
  IF v_target IS NULL THEN RETURN NULL; END IF;
  INSERT INTO public.existing_user_session_leases(user_id,owner,expires_at)
    VALUES(p_user,p_owner,clock_timestamp()+interval '120 seconds')
  ON CONFLICT(user_id) DO UPDATE SET owner=excluded.owner,expires_at=excluded.expires_at
    WHERE existing_user_session_leases.expires_at <= clock_timestamp()
  RETURNING owner INTO v_acquired;
  IF v_acquired IS NULL THEN RETURN NULL; END IF;
  RETURN v_target;
END $function$

CREATE OR REPLACE FUNCTION public.activate_bank_sync_connection(p_connection_id bigint, p_manifest_sha256 text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_connection eshop.bank_sync_connections%ROWTYPE;
BEGIN
  PERFORM public.require_service_role();
  SELECT * INTO STRICT v_connection FROM eshop.bank_sync_connections WHERE id=p_connection_id;
  IF v_connection.manifest_sha256 IS DISTINCT FROM p_manifest_sha256 OR v_connection.pairing_code IS NULL THEN
    RAISE EXCEPTION 'BANK_SYNC_MANIFEST_OR_PAIRING_MISMATCH';
  END IF;
  IF EXISTS(SELECT 1 FROM eshop.bank_sync_account_aliases WHERE bank_account_id=v_connection.bank_account_id AND connection_id<>p_connection_id)
    OR EXISTS(SELECT 1 FROM eshop.bank_sync_connections c JOIN eshop.bank_sync_account_aliases a ON a.bank_account_id=c.bank_account_id WHERE a.connection_id=p_connection_id AND c.id<>p_connection_id) THEN
    RAISE EXCEPTION 'BANK_SYNC_ALIAS_AUTHORITY_CONFLICT';
  END IF;
  PERFORM 1 FROM eshop.bank_accounts WHERE id=v_connection.bank_account_id OR id IN
    (SELECT bank_account_id FROM eshop.bank_sync_account_aliases WHERE connection_id=p_connection_id)
    ORDER BY id FOR UPDATE;
  -- Adopt known bank movement IDs before the first replay. Historical ledger
  -- rows and manual pairing decisions remain unchanged; the receiver compares
  -- bank facts and quarantines a mismatch instead of crediting history twice.
  IF v_connection.provider='FIO' THEN
    INSERT INTO eshop.bank_transaction_identities(instance_id,provider,physical_account,identity_kind,identity_value,transaction_id)
      SELECT v_connection.instance_id,'FIO',v_connection.physical_account,'movement',t.transaction_id::text,t.id
      FROM eshop.transactions t
      WHERE (t.bank_account_id=v_connection.bank_account_id OR t.bank_account_id IN
        (SELECT bank_account_id FROM eshop.bank_sync_account_aliases WHERE connection_id=p_connection_id))
        AND t.ingest_source IN ('fio_api','legacy_api','legacy') AND t.transaction_id IS NOT NULL
      ON CONFLICT(instance_id,provider,physical_account,identity_kind,identity_value) DO UPDATE
        SET transaction_id=eshop.bank_transaction_identities.transaction_id
        WHERE eshop.bank_transaction_identities.transaction_id=EXCLUDED.transaction_id;
    IF EXISTS(SELECT 1 FROM eshop.transactions t JOIN eshop.bank_transaction_identities i
      ON i.instance_id=v_connection.instance_id AND i.provider='FIO' AND i.physical_account=v_connection.physical_account
        AND i.identity_kind='movement' AND i.identity_value=t.transaction_id::text
      WHERE t.bank_account_id=v_connection.bank_account_id AND t.ingest_source IN ('fio_api','legacy_api','legacy')
        AND i.transaction_id<>t.id) THEN RAISE EXCEPTION 'BANK_SYNC_HISTORICAL_IDENTITY_CONFLICT'; END IF;
  END IF;
  UPDATE eshop.bank_accounts SET is_fetch_enabled=false WHERE id=v_connection.bank_account_id OR id IN
    (SELECT bank_account_id FROM eshop.bank_sync_account_aliases WHERE connection_id=p_connection_id);
  UPDATE eshop.bank_sync_connections SET state='connected',legacy_blocked_at=COALESCE(legacy_blocked_at,now())
    WHERE id=p_connection_id AND manifest_sha256=p_manifest_sha256;
END;
$function$

CREATE OR REPLACE FUNCTION public.activity_history_graph_internal_v1(p_occasion bigint, p_history jsonb, p_validate boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE graph jsonb;
BEGIN
 IF p_history IS NULL OR jsonb_typeof(p_history)<>'object' OR octet_length(p_history::text)>2097152 OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_history) k WHERE k NOT IN('id','parent_history_id','aggregate_version','activities','activity_assignments','assignmentPlaceLinks','assignmentEventLinks','schemaVersion','timeBasis')) OR (p_history ? 'schemaVersion' AND (p_history->>'schemaVersion'<>'1' OR p_history->>'timeBasis'<>'UTC')) THEN RAISE invalid_parameter_value USING MESSAGE='invalid activity history'; END IF;
 IF p_validate THEN
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(COALESCE(p_history->'activities','[]')) a,LATERAL jsonb_object_keys(a) k WHERE k NOT IN('id','created_at','updated_at','title','description','type','occasion','unit','is_hidden','order','data','activity_assignments')) OR EXISTS(SELECT 1 FROM jsonb_array_elements(COALESCE(p_history->'activity_assignments','[]')) x,LATERAL jsonb_object_keys(x) k WHERE k NOT IN('id','activity_id','user','start_time','end_time','title','description','data','user_info','activity_assignment_places','activity_assignment_events','created_at','updated_at')) THEN RAISE invalid_parameter_value USING MESSAGE='unknown activity history field'; END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(COALESCE(p_history->'activities','[]')) a WHERE jsonb_typeof(a->'activity_assignments')='array' AND (
    jsonb_array_length(a->'activity_assignments')<>(SELECT count(*) FROM jsonb_array_elements(COALESCE(p_history->'activity_assignments','[]')) x WHERE x->>'activity_id'=a->>'id') OR EXISTS(
      SELECT 1 FROM jsonb_array_elements(a->'activity_assignments') nx WHERE EXISTS(SELECT 1 FROM jsonb_object_keys(nx) k WHERE k NOT IN('id','activity_id','user','start_time','end_time','title','description','data','user_info','activity_assignment_places','activity_assignment_events','created_at','updated_at')) OR NOT EXISTS(
        SELECT 1 FROM jsonb_array_elements(COALESCE(p_history->'activity_assignments','[]')) x WHERE x->>'id'=nx->>'id' AND x->>'activity_id'=a->>'id' AND (x->'user',x->'title',x->'description',x->'data') IS NOT DISTINCT FROM (nx->'user',nx->'title',nx->'description',nx->'data') AND public.activity_time_internal_v1(x->>'start_time',p_occasion,p_history->>'timeBasis'='UTC') IS NOT DISTINCT FROM public.activity_time_internal_v1(nx->>'start_time',p_occasion,p_history->>'timeBasis'='UTC') AND public.activity_time_internal_v1(x->>'end_time',p_occasion,p_history->>'timeBasis'='UTC') IS NOT DISTINCT FROM public.activity_time_internal_v1(nx->>'end_time',p_occasion,p_history->>'timeBasis'='UTC'))))) THEN RAISE invalid_parameter_value USING MESSAGE='inconsistent nested history assignments'; END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(COALESCE(p_history->'assignmentPlaceLinks','[]')) l WHERE EXISTS(SELECT 1 FROM jsonb_object_keys(l) k WHERE k NOT IN('assignment_id','place_id')) OR l->>'place_id' IS NULL OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(COALESCE(p_history->'activity_assignments','[]')) x WHERE x->>'id'=l->>'assignment_id')) OR EXISTS(SELECT 1 FROM jsonb_array_elements(COALESCE(p_history->'assignmentEventLinks','[]')) l WHERE EXISTS(SELECT 1 FROM jsonb_object_keys(l) k WHERE k NOT IN('assignment_id','event_id')) OR l->>'event_id' IS NULL OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(COALESCE(p_history->'activity_assignments','[]')) x WHERE x->>'id'=l->>'assignment_id')) THEN RAISE invalid_parameter_value USING MESSAGE='orphan or invalid history link'; END IF;
 END IF;
 SELECT COALESCE(jsonb_agg(jsonb_build_object('id',a->'id','title',a->'title','description',a->'description','type',a->'type','unit',a->'unit','is_hidden',a->'is_hidden','order',a->'order','data',a->'data','assignments',COALESCE((SELECT jsonb_agg(jsonb_build_object('id',x->'id','user',x->'user','start_time',x->'start_time','end_time',x->'end_time','title',x->'title','description',x->'description','data',x->'data','linked_place_ids',COALESCE((SELECT jsonb_agg(l->'place_id') FROM jsonb_array_elements(COALESCE(p_history->'assignmentPlaceLinks','[]')) l WHERE l->>'assignment_id'=x->>'id'),'[]'),'linked_event_ids',COALESCE((SELECT jsonb_agg(l->'event_id') FROM jsonb_array_elements(COALESCE(p_history->'assignmentEventLinks','[]')) l WHERE l->>'assignment_id'=x->>'id'),'[]'))) FROM jsonb_array_elements(COALESCE(p_history->'activity_assignments','[]')) x WHERE x->>'activity_id'=a->>'id'),'[]'))),'[]') INTO graph FROM jsonb_array_elements(COALESCE(NULLIF(p_history->'activities','null'),'[]')) a;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(COALESCE(p_history->'activity_assignments','[]')) x WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(COALESCE(p_history->'activities','[]')) a WHERE a->>'id'=x->>'activity_id')) THEN RAISE invalid_parameter_value USING MESSAGE='orphan history assignment'; END IF;
 RETURN public.normalize_activity_graph_internal_v1(p_occasion,graph,p_history->>'timeBasis'='UTC',p_validate);
END $function$

CREATE OR REPLACE FUNCTION public.activity_time_internal_v1(p_value text, p_occasion bigint, p_utc boolean)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE zone text; instant timestamptz;
BEGIN
 IF p_value IS NULL THEN RETURN NULL; END IF;
 SELECT COALESCE(data->>'timezone','Europe/Prague') INTO zone FROM public.occasions WHERE id=p_occasion;
 IF NOT EXISTS(SELECT 1 FROM pg_timezone_names WHERE name=zone) THEN zone:='Europe/Prague'; END IF;
 IF p_value ~ '(Z|[+-][0-9]{2}:[0-9]{2})$' THEN instant:=p_value::timestamptz;
 ELSE instant:=p_value::timestamp AT TIME ZONE CASE WHEN p_utc THEN 'UTC' ELSE zone END; END IF;
 RETURN to_char(instant AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"');
END $function$

CREATE OR REPLACE FUNCTION public.add_image_record(p_link text, p_occasion_id bigint, p_unit_id bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_image_id bigint;
BEGIN
    -- Permission Check
    IF p_unit_id IS NOT NULL THEN
        -- Unit Editor
        IF (SELECT public.get_is_editor_on_unit(p_unit_id)) IS NOT TRUE THEN
            RAISE EXCEPTION 'Permission denied: User is not an editor of this unit.';
        END IF;
    ELSIF p_occasion_id IS NOT NULL THEN
        -- Occasion Editor OR Occasion Order Editor
        IF (public.get_is_editor_on_occasion(p_occasion_id)) IS NOT TRUE 
           AND (public.get_is_editor_order_on_occasion(p_occasion_id)) IS NOT TRUE THEN
             RAISE EXCEPTION 'Permission denied: User is not an editor/order-editor of this occasion.';
        END IF;
    ELSE
        RAISE EXCEPTION 'Entity ID (unit or occasion) must be provided.';
    END IF;

    PERFORM public.add_image_record_internal(p_link,p_occasion_id,p_unit_id);

END;
$function$

CREATE OR REPLACE FUNCTION public.add_transaction_to_payment_info_ws(p_transaction_id bigint, p_payment_info_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
    bank_acc bigint;
    occasion_id bigint;
BEGIN
    -- Retrieve the associated order_id from payment_info
    SELECT pi.bank_account INTO bank_acc
    FROM eshop.payment_info pi
    WHERE pi.id = p_payment_info_id
    LIMIT 1;

    PERFORM public.check_is_admin_for_bank_account(bank_acc);

    SELECT o.occasion
    INTO occasion_id
    FROM eshop.orders o
    WHERE o.payment_info = p_payment_info_id
    LIMIT 1;

    PERFORM public.check_is_editor_order_on_occasion(occasion_id);

    PERFORM public.apply_transaction_pairing(
      p_transaction_id, p_payment_info_id, 'manual_attach', 'user'
    );

    -- Return success message
    RETURN jsonb_build_object(
        'code', 200,
        'message', 'Transaction added successfully.'
    );

END;
$function$

CREATE OR REPLACE FUNCTION public.add_user_group_members_client_sync_v1(p_occasion bigint, p_group bigint, p_users uuid[], p_command_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE actor uuid:=auth.uid(); begin_result jsonb; hash text; members jsonb; users uuid[]; v_version bigint; changed integer;
BEGIN
 PERFORM public.assert_canonical_mutation_write_release_internal_v1(p_occasion);
 IF cardinality(p_users)>5000 THEN RAISE invalid_parameter_value USING MESSAGE='too many members'; END IF;
 p_users:=ARRAY(SELECT DISTINCT id FROM unnest(p_users) id ORDER BY id);
 IF actor IS NULL OR cardinality(p_users) NOT BETWEEN 1 AND 5000 THEN
  RAISE invalid_parameter_value USING MESSAGE='invalid selected members'; END IF;
 IF NOT public.get_is_editor_on_occasion(p_occasion) AND NOT EXISTS(SELECT 1 FROM public.user_groups m
  JOIN public.user_group_info g ON g.id=m."group" WHERE g.id=p_group AND g.occasion=p_occasion AND m."user"=actor AND m.is_admin) THEN
  RAISE insufficient_privilege USING MESSAGE='group editor required'; END IF;
 hash:=encode(extensions.digest(convert_to(jsonb_build_object('occasion',p_occasion,'group',p_group,'users',p_users)::text,'UTF8'),'sha256'),'hex');
 begin_result:=public.begin_client_mutation_v1(p_command_id,'profile.group.members.add',p_occasion,actor,hash);
 PERFORM public.lock_group_occasion_internal_v1(p_occasion);
 IF begin_result->>'disposition'='replay' THEN RETURN begin_result->'response'; END IF;
 PERFORM 1 FROM public.user_group_info WHERE id=p_group AND occasion=p_occasion FOR UPDATE;
 IF NOT FOUND THEN RAISE insufficient_privilege USING MESSAGE='group unavailable'; END IF;
 IF NOT public.get_is_editor_on_occasion(p_occasion) AND NOT EXISTS(SELECT 1 FROM public.user_groups WHERE "group"=p_group AND "user"=actor AND is_admin) THEN
  RAISE insufficient_privilege USING MESSAGE='group editor required'; END IF;
 SELECT jsonb_agg(jsonb_build_object('user_id',id,'is_admin',false)) INTO members FROM unnest(p_users) id;
 changed:=public.write_user_group_members_internal_v1(p_occasion,p_group,members,false);
 INSERT INTO public.client_aggregate_versions(aggregate_type,scope_type,scope_id,aggregate_id,version)
 VALUES('user_group','occasion',p_occasion,p_group::text,0) ON CONFLICT DO NOTHING;
 UPDATE public.client_aggregate_versions SET version=version+CASE WHEN changed>0 THEN 1 ELSE 0 END,updated_at=clock_timestamp()
 WHERE aggregate_type='user_group' AND scope_type='occasion' AND scope_id=p_occasion AND aggregate_id=p_group::text RETURNING version INTO v_version;
 IF changed=0 THEN RETURN public.complete_client_mutation_outcome_v1(p_command_id,'unchanged',200,
  jsonb_build_object('version',v_version,'group',public.get_user_group_command_data_v1(p_group))); END IF;
 SELECT array_agg("user") INTO users FROM public.user_groups WHERE "group"=p_group;
 RETURN public.complete_private_profile_mutation_v1(p_command_id,p_occasion,'profile.group.members.add',
  jsonb_build_array(jsonb_build_object('entityType','user_group','entityId',p_group,'operation','update','safeLabel','Group members',
    'changedFields',jsonb_build_array('participants'))),users,'{}','[]',
  jsonb_build_object('version',v_version,'group',public.get_user_group_command_data_v1(p_group)));
END $function$

CREATE OR REPLACE FUNCTION public.add_user_to_occasion_client_sync_v1(p_occasion bigint, p_user uuid, p_command_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_begin jsonb; v_hash text; v_before jsonb;
  v_after jsonb; v_result jsonb; v_version bigint; v_replacements jsonb:='[]';
BEGIN
  IF v_actor IS NULL OR p_user IS NULL OR NOT (
    v_actor=p_user OR public.get_is_manager_on_occasion(p_occasion)
    OR public.get_is_admin_on_occasion(p_occasion)) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion membership permission required';
  END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'occasion',p_occasion,'userId',p_user)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,
    'profile.membership.ensure',p_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  SELECT to_jsonb(ou) INTO v_before FROM public.occasion_users ou
    WHERE ou.occasion=p_occasion AND ou."user"=p_user FOR UPDATE;
  v_result:=public.add_user_to_occasion_internal_v1(p_occasion,p_user);
  IF COALESCE((v_result->>'code')::integer,500)<>200 THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',
      COALESCE((v_result->>'code')::integer,400),v_result); END IF;
  SELECT to_jsonb(ou) INTO v_after FROM public.occasion_users ou
    WHERE ou.occasion=p_occasion AND ou."user"=p_user;
  SELECT COALESCE(v.version,0) INTO v_version FROM (SELECT 1) seed
    LEFT JOIN public.client_aggregate_versions v
      ON v.aggregate_type='occasion_user' AND v.scope_type='occasion'
      AND v.scope_id=p_occasion AND v.aggregate_id=p_user::text;
  IF v_before IS NOT DISTINCT FROM v_after THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'unchanged',200,
      jsonb_build_object('version',v_version,'userId',p_user)); END IF;
  INSERT INTO public.client_aggregate_versions
    (aggregate_type,scope_type,scope_id,aggregate_id,version)
  VALUES ('occasion_user','occasion',p_occasion,p_user::text,1)
  ON CONFLICT (aggregate_type,scope_type,scope_id,aggregate_id) DO UPDATE
    SET version=public.client_aggregate_versions.version+1,
      updated_at=clock_timestamp() RETURNING version INTO v_version;
  IF v_actor=p_user THEN v_replacements:=jsonb_build_array(jsonb_build_object(
    'component','private_profile','userId',p_user,
    'payload',public.get_private_profile_payload_v1(p_occasion,p_user))); END IF;
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'profile.membership.ensure','profile',jsonb_build_array(jsonb_build_object(
      'entityType','occasion_user','entityId',p_user,'operation',
      CASE WHEN v_before IS NULL THEN 'insert' ELSE 'update' END,
      'safeLabel','Occasion membership','changedFields',jsonb_build_array(
        'membership','rights'))),'{}',jsonb_build_array(jsonb_build_object(
          'component','private_profile','userId',p_user)),'[]',
    jsonb_build_object('version',v_version,'userId',p_user),
    '{}','[]','user',NULL,v_replacements);
END; $function$

CREATE OR REPLACE FUNCTION public.add_user_to_unit(unit_id bigint, usr uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
    unit_org BIGINT;
    user_org BIGINT;
    user_exists BOOLEAN;
BEGIN
    IF NOT public.is_service_role() AND public.get_is_manager_on_unit(unit_id) IS NOT TRUE THEN
        RAISE insufficient_privilege USING MESSAGE = 'Unit manager required';
    END IF;

    -- Get the organization ID of the unit
    SELECT organization INTO unit_org
    FROM public.units
    WHERE id = unit_id;

    IF unit_org IS NULL THEN
      RAISE EXCEPTION 'Unit % not found', unit_id;
    END IF;

    -- Get the organization ID of the user
    SELECT organization INTO user_org
    FROM public.user_info
    WHERE id = usr;

    IF user_org IS NULL THEN
      RAISE EXCEPTION 'User % not found', usr;
    END IF;

    -- Check if the user and unit belong to the same organization
    IF user_org IS DISTINCT FROM unit_org THEN
        RAISE EXCEPTION 'User does not belong to the same organization as the unit';
    END IF;

    -- Check if the user already exists in the unit_users table
    SELECT EXISTS (
        SELECT 1
        FROM public.unit_users
        WHERE unit = unit_id AND "user" = usr
    ) INTO user_exists;

    -- If the user already exists, update the existing row; otherwise, insert a new one
    IF NOT user_exists THEN
        INSERT INTO public.unit_users (
                    unit,
                    "user",
                    created_at,
                    is_editor,
                    is_manager
                )
                VALUES (
                    unit_id,
                    usr,
                    now(),    -- Set created_at to current timestamp
                    FALSE,    -- Default value for is_editor
                    FALSE    -- Default value for is_manager
                );
    END IF;

    -- Return a successful JSON response
    RETURN jsonb_build_object('code', 200, 'message', 'User added/updated successfully');
EXCEPTION WHEN OTHERS THEN
    RAISE;
END;
$function$

CREATE OR REPLACE FUNCTION public.adjust_spot_capacity_for_pool(p_inventory_pool_id bigint)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
    v_context RECORD;
    v_resource RECORD;
    v_spots_to_create BIGINT;
    v_spots_to_delete BIGINT;
    v_booked_spots_count BIGINT;
    v_total_spots_count BIGINT;
    v_deletable_spot_ids BIGINT[];
    v_net_change INTEGER := 0;
    v_pool_occasion_id BIGINT;
    v_total_pool_capacity BIGINT;
BEGIN
    PERFORM 1 FROM public.inventory_pools WHERE id=p_inventory_pool_id FOR UPDATE;
    PERFORM 1 FROM public.inventory_contexts WHERE inventory_pool=p_inventory_pool_id ORDER BY id FOR UPDATE;
    PERFORM 1 FROM eshop.spots WHERE inventory_context IN(SELECT id FROM public.inventory_contexts WHERE inventory_pool=p_inventory_pool_id) ORDER BY id FOR UPDATE;
    -- Step 0: Validate input and get occasion ID.
    SELECT occasion INTO v_pool_occasion_id FROM public.inventory_pools WHERE id = p_inventory_pool_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION '%', jsonb_build_object('code', 'P001', 'message', 'Inventory pool with ID ' || p_inventory_pool_id || ' not found.')::text;
    END IF;

    -- Calculate the total capacity for the entire pool once. This is the target for the generic pool.
    SELECT COALESCE(SUM(capacity), 0) INTO v_total_pool_capacity
    FROM public.resources
    WHERE inventory_pool = p_inventory_pool_id;

    -- =================================================================
    -- Main Synchronization Loop (per context)
    -- =================================================================
    FOR v_context IN
        SELECT id FROM public.inventory_contexts WHERE inventory_pool = p_inventory_pool_id
    LOOP
        -- =============================================================
        -- Part A: Cleanup of RESOURCE-SPECIFIC Spots for this context
        -- =============================================================
        FOR v_resource IN
            SELECT id, capacity FROM public.resources WHERE inventory_pool = p_inventory_pool_id
        LOOP
            -- Count spots for the current resource WITHIN the current context.
            SELECT count(*) INTO v_total_spots_count FROM eshop.spots WHERE inventory_context = v_context.id AND resource = v_resource.id;
            SELECT count(*) INTO v_booked_spots_count FROM eshop.spots WHERE inventory_context = v_context.id AND resource = v_resource.id AND (order_product_ticket IS NOT NULL OR (secret IS NOT NULL AND secret_expiration_time>clock_timestamp()));

            IF v_booked_spots_count > v_resource.capacity THEN
                RAISE EXCEPTION '%', jsonb_build_object(
                    'code', 'S001',
                    'message', 'Overbooking detected for specific resource. Manual intervention required.',
                    'details', jsonb_build_object(
                        'contextId', v_context.id,
                        'resourceId', v_resource.id,
                        'bookedSpots', v_booked_spots_count,
                        'capacity', v_resource.capacity
                    )
                )::text;
            END IF;

            IF v_total_spots_count > v_resource.capacity THEN
                v_spots_to_delete := v_total_spots_count - v_resource.capacity;
                SELECT array_agg(id) INTO v_deletable_spot_ids FROM (
                    SELECT id FROM eshop.spots
                    WHERE inventory_context = v_context.id AND resource = v_resource.id AND order_product_ticket IS NULL AND (secret IS NULL OR secret_expiration_time<=clock_timestamp())
                    ORDER BY created_at DESC
                    LIMIT v_spots_to_delete
                ) AS sub;

                IF coalesce(cardinality(v_deletable_spot_ids),0) < v_spots_to_delete THEN
                     RAISE EXCEPTION '%', jsonb_build_object(
                        'code', 'S002',
                        'message', 'Cannot delete excess resource-specific spots. Deletion would require removing a booked spot.',
                        'details', jsonb_build_object(
                            'contextId', v_context.id,
                            'resourceId', v_resource.id
                        )
                    )::text;
                END IF;

                DELETE FROM eshop.spots WHERE id = ANY(v_deletable_spot_ids);
                v_net_change := v_net_change - v_spots_to_delete;
            END IF;
        END LOOP;

        -- =============================================================
        -- Part B: Management of GENERIC Spot Pool for this context
        -- =============================================================
        -- Count total and booked spots for the GENERIC pool (resource IS NULL) within the current context.
        SELECT count(*) INTO v_total_spots_count FROM eshop.spots WHERE inventory_context = v_context.id;
        SELECT count(*) INTO v_booked_spots_count FROM eshop.spots WHERE inventory_context = v_context.id AND (order_product_ticket IS NOT NULL OR (secret IS NOT NULL AND secret_expiration_time>clock_timestamp()));

        IF v_booked_spots_count > v_total_pool_capacity THEN
            RAISE EXCEPTION '%', jsonb_build_object(
                'code', 'S003',
                'message', 'Overbooking detected for generic pool. Manual intervention required.',
                'details', jsonb_build_object(
                    'contextId', v_context.id,
                    'bookedSpots', v_booked_spots_count,
                    'capacity', v_total_pool_capacity
                )
            )::text;
        END IF;

        -- DELETION of generic spots
        IF v_total_spots_count > v_total_pool_capacity THEN
            v_spots_to_delete := v_total_spots_count - v_total_pool_capacity;
            SELECT array_agg(id) INTO v_deletable_spot_ids FROM (
                SELECT id FROM eshop.spots
                WHERE inventory_context = v_context.id AND resource IS NULL AND order_product_ticket IS NULL AND (secret IS NULL OR secret_expiration_time<=clock_timestamp())
                ORDER BY created_at DESC
                LIMIT v_spots_to_delete
            ) AS sub;

            IF coalesce(cardinality(v_deletable_spot_ids),0) < v_spots_to_delete THEN
                 RAISE EXCEPTION '%', jsonb_build_object(
                    'code', 'S004',
                    'message', 'Cannot delete excess generic spots. Deletion would require removing a booked spot.',
                    'details', jsonb_build_object(
                        'contextId', v_context.id
                    )
                )::text;
            END IF;

            DELETE FROM eshop.spots WHERE id = ANY(v_deletable_spot_ids);
            v_net_change := v_net_change - v_spots_to_delete;
        END IF;

        -- CREATION of generic spots
        -- Recount after potential deletion to get the current number.
        SELECT count(*) INTO v_total_spots_count FROM eshop.spots WHERE inventory_context = v_context.id;

        IF v_total_spots_count < v_total_pool_capacity THEN
            v_spots_to_create := v_total_pool_capacity - v_total_spots_count;

            -- Insert the required number of new generic spots.
            -- Per instructions, ONLY occasion and inventory_context are set.
            INSERT INTO eshop.spots (occasion, inventory_context)
            SELECT
                v_pool_occasion_id,
                v_context.id
            FROM generate_series(1, v_spots_to_create);

            v_net_change := v_net_change + v_spots_to_create;
        END IF;
    END LOOP;

    RETURN v_net_change;

END;
$function$

CREATE OR REPLACE FUNCTION public.admit_email_intent_v1(p_message bigint, p_recheck boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE m public.email_messages; policy jsonb; scopes jsonb; costs jsonb; r jsonb;
 is_auth boolean; unit_count bigint; org_count bigint; unit_bytes bigint; org_bytes bigint; growth bigint:=0; policies jsonb;
BEGIN
 SELECT * INTO STRICT m FROM public.email_messages WHERE id=p_message;
 policies:=public.abuse_policy_bundle_v1(ARRAY['email.payload','email.actor','email.backlog','email.auth.backlog','email.auth','email.ordinary'],m.unit,m.organization);
 IF m.unit IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.units WHERE id=m.unit AND organization=m.organization) THEN
  RAISE invalid_parameter_value USING MESSAGE='email_scope_mismatch'; END IF;
 scopes:=jsonb_build_object('unit',m.unit,'organization',m.organization,'global','all',
  'actor',m.producer_actor,'recipient',public.abuse_recipient_key_v1(coalesce(m.recipient,(SELECT email_readonly FROM public.user_info WHERE id=m.recipient_user))));
 PERFORM public.abuse_charge_v1(policies->'email.payload',scopes,
  jsonb_build_object('email.payload.bytes',octet_length(m.data::text)+coalesce(octet_length(m.prepared::text),0)));
 -- Neither caller priority nor request data can claim the reserved class.
 IF public.email_admission_class_v1(m)='commitment' THEN
  UPDATE public.email_messages SET admission_class='commitment',priority=5 WHERE id=m.id;
  RETURN;
 END IF;
 IF NOT p_recheck AND m.producer_actor IS NOT NULL THEN
  PERFORM public.abuse_charge_v1(policies->'email.actor',scopes);
 END IF;
 is_auth:=public.email_admission_class_v1(m)='auth';
 UPDATE public.email_messages SET admission_class=CASE WHEN is_auth THEN 'auth' ELSE 'ordinary' END WHERE id=m.id;
 policy:=policies->(CASE WHEN is_auth THEN 'email.auth.backlog' ELSE 'email.backlog' END);
 -- Null Unit auth has an explicit tenant/global class, never a synthetic Unit.
 IF m.unit IS NULL THEN policy:=jsonb_set(policy,'{rules}',(SELECT jsonb_agg(value) FROM jsonb_array_elements(policy->'rules') WHERE value->>'scope_kind'<>'unit')); END IF;
 FOR r IN SELECT value FROM jsonb_array_elements(policy->'rules') ORDER BY value->>'rule_key' LOOP
  IF r->>'kind' IN ('bytes','duration') THEN CONTINUE; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('abuse:'||(r->>'rule_key')||':'||(scopes->>(r->>'scope_kind')),0));
 END LOOP;
 -- Pending partial indexes exclude delivery history. Include blocked/future/unknown.
 SELECT count(*) FILTER(WHERE unit=m.unit),count(*),
  coalesce(sum(octet_length(data::text)+coalesce(octet_length(prepared::text),0)) FILTER(WHERE unit=m.unit),0),
  coalesce(sum(octet_length(data::text)+coalesce(octet_length(prepared::text),0)),0)
 INTO unit_count,org_count,unit_bytes,org_bytes FROM public.email_messages
 WHERE organization=m.organization AND admission_class=CASE WHEN is_auth THEN 'auth' ELSE 'ordinary' END AND workflow_state IN ('pending','blocked','preparing','sending','retry_wait','unknown');
 costs:=jsonb_build_object('email.auth.backlog.organization',org_count,'email.backlog.unit',unit_count,'email.backlog.organization',org_count,
  'email.backlog.unit.bytes',unit_bytes,'email.backlog.organization.bytes',org_bytes);
 PERFORM public.abuse_charge_v1(policy,scopes,costs);
 IF p_recheck THEN RETURN; END IF;
 policy:=policies->(CASE WHEN is_auth THEN 'email.auth' ELSE 'email.ordinary' END);
 IF NOT is_auth AND m.unit IS NULL THEN
  -- System producers without a Unit retain tenant and recipient bounds.
  policy:=jsonb_set(policy,'{rules}',(SELECT jsonb_agg(value) FROM jsonb_array_elements(policy->'rules') WHERE value->>'scope_kind'<>'unit'));
 END IF;
 IF NOT is_auth AND m.unit IS NOT NULL THEN
  SELECT coalesce(verified_orders,0) INTO growth FROM public.abuse_unit_evidence
   WHERE unit=m.unit AND measured_at>statement_timestamp()-interval '15 minutes';
  growth:=coalesce(growth,0);
 END IF;
 PERFORM public.abuse_charge_v1(policy,scopes,jsonb_build_object('growth',growth));
END $function$

CREATE OR REPLACE FUNCTION public.admit_external_image_fetch_v1(p_occasion_id bigint DEFAULT NULL::bigint, p_unit_id bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE un bigint; org bigint; policy jsonb; cap bigint;
BEGIN
 IF auth.uid() IS NULL OR (p_occasion_id IS NULL)=(p_unit_id IS NULL)
  OR public.check_upload_permission(p_occasion_id,p_unit_id) IS NOT TRUE THEN
  RAISE insufficient_privilege USING MESSAGE='image editor required'; END IF;
 IF p_occasion_id IS NOT NULL THEN SELECT unit,organization INTO un,org FROM public.occasions WHERE id=p_occasion_id;
 ELSE SELECT id,organization INTO un,org FROM public.units WHERE id=p_unit_id; END IF;
 policy:=public.abuse_effective_rules_v1('image.fetch',un,org);
 SELECT (r->>'base_limit')::bigint INTO cap FROM jsonb_array_elements(policy->'rules') r WHERE r->>'rule_key'='image.fetch.payload.bytes';
 IF cap IS NULL THEN RAISE configuration_limit_exceeded USING MESSAGE='abuse_policy_missing'; END IF;
 PERFORM public.abuse_charge_v1(policy,jsonb_build_object('actor',auth.uid(),'unit',un,'organization',org),jsonb_build_object('image.fetch.payload.bytes',cap));
 RETURN jsonb_build_object('allowed',true,'maxBytes',cap);
END $function$

CREATE OR REPLACE FUNCTION public.admit_image_record_budget_internal(p_link text, p_occasion bigint, p_unit bigint)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE un bigint; org bigint; policy jsonb; scopes jsonb; r jsonb; unit_count bigint; org_count bigint;
BEGIN
 IF p_link IS NULL OR p_link !~ '^https://(a\.)?img\.festapp\.net/images/[A-Za-z0-9_./-]+$' THEN
  RAISE invalid_parameter_value USING MESSAGE='canonical public image URL required'; END IF;
 IF p_occasion IS NOT NULL THEN SELECT unit,organization INTO un,org FROM public.occasions WHERE id=p_occasion;
 ELSE SELECT id,organization INTO un,org FROM public.units WHERE id=p_unit; END IF;
 policy:=public.abuse_effective_rules_v1('image.records',un,org);
 scopes:=jsonb_build_object('actor',auth.uid(),'unit',un,'organization',org);
 FOR r IN SELECT value FROM jsonb_array_elements(policy->'rules') ORDER BY value->>'rule_key' LOOP
  IF r->>'kind' IN ('rolling','occupancy') THEN
   PERFORM pg_advisory_xact_lock(hashtextextended('abuse:'||(r->>'rule_key')||':'||(scopes->>(r->>'scope_kind')),0));
  END IF;
 END LOOP;
 SELECT count(*) FILTER(WHERE coalesce(i.unit,o.unit)=un),count(*) INTO unit_count,org_count
 FROM public.images i LEFT JOIN public.occasions o ON o.id=i.occasion LEFT JOIN public.units u ON u.id=i.unit
 WHERE coalesce(o.organization,u.organization)=org;
 PERFORM public.abuse_charge_v1(policy,scopes,jsonb_build_object('image.records.link.bytes',octet_length(p_link),
  'image.records.stored.unit',unit_count+1,'image.records.stored.organization',org_count+1));
END $function$

