CREATE OR REPLACE FUNCTION public.allocate_ticket_order_identity_internal(p_form bigint)
 RETURNS bigint
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE o bigint; occ bigint; seq bigint; attempt integer;
BEGIN
 SELECT occasion INTO STRICT occ FROM public.forms WHERE id=p_form FOR UPDATE;
 PERFORM public.admit_order_creation_v1(occ);
 seq:=public.next_order_sequence(occ);
 FOR attempt IN 1..10 LOOP
  INSERT INTO eshop.orders(form,occasion,order_symbol,order_sequence,state)
   VALUES(p_form,occ,public.generate_order_symbol(),seq,'ordered')
   ON CONFLICT ON CONSTRAINT orders_order_symbol_key DO NOTHING RETURNING id INTO o;
  IF o IS NOT NULL THEN RETURN o; END IF;
 END LOOP;
 RAISE EXCEPTION 'Order symbol allocation exhausted';
END $function$

CREATE OR REPLACE FUNCTION public.allocate_user_sign_in_email(p_organization bigint, p_delivery_email text)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
    v_delivery_email text := lower(btrim(p_delivery_email));
    v_local_part text;
    v_domain_part text;
    v_candidate text;
    v_suffix integer := 0;
BEGIN
    IF v_delivery_email IS NULL OR v_delivery_email = ''
       OR position('@' IN v_delivery_email) <= 1 THEN
        RAISE EXCEPTION 'INVALID_DELIVERY_EMAIL';
    END IF;

    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended(
            'user-sign-in-email:' || p_organization::text, 0
        )
    );

    v_local_part := split_part(v_delivery_email, '@', 1);
    v_domain_part := substring(v_delivery_email FROM position('@' IN v_delivery_email) + 1);

    LOOP
        v_candidate := CASE WHEN v_suffix = 0 THEN v_delivery_email
            ELSE v_local_part || '+' || v_suffix::text || '@' || v_domain_part END;
        EXIT WHEN NOT EXISTS (
            SELECT 1 FROM public.user_info ui
             WHERE ui.organization = p_organization
               AND lower(btrim(ui.email_readonly)) = v_candidate
        );
        v_suffix := v_suffix + 1;
    END LOOP;

    RETURN v_candidate;
END;
$function$

CREATE OR REPLACE FUNCTION public.apply_email_post_actions(p_message uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE m record; v_result jsonb;
BEGIN
 PERFORM public.require_service_role();
 PERFORM 1 FROM public.email_capacity FOR UPDATE;
 FOR m IN SELECT * FROM public.email_messages WHERE workflow_state='accepted' AND post_action_state='pending'
 AND (p_message IS NULL OR message_id=p_message) ORDER BY id LIMIT 20 LOOP
  -- Domain producers lock order before message; follow that order before owning the projection.
  IF m.order_id IS NOT NULL THEN PERFORM 1 FROM eshop.orders WHERE id=m.order_id FOR UPDATE; END IF;
  SELECT * INTO m FROM public.email_messages WHERE id=m.id AND workflow_state='accepted' AND post_action_state='pending' FOR UPDATE SKIP LOCKED;
  IF NOT FOUND THEN CONTINUE; END IF;
  BEGIN
   IF m.message_kind='order_tickets' THEN
    -- Never resurrect a used/storno ticket or a reverted/cancelled order.
    UPDATE eshop.orders SET state='sent',updated_at=now() WHERE id=m.order_id AND state='paid' AND email_payment_version=m.source_version;
    IF FOUND THEN
     UPDATE eshop.tickets t SET state='sent',updated_at=now()
     FROM eshop.order_product_ticket opt WHERE opt.ticket=t.id AND opt."order"=m.order_id AND t.state='paid'
      AND t.id IN (SELECT jsonb_array_elements_text(m.post_action->'ticket_ids')::bigint);
     INSERT INTO eshop.orders_history("order",data,state,price,currency_code) SELECT id,data,state,price,currency_code FROM eshop.orders WHERE id=m.order_id;
    END IF;
   END IF;
   IF m.message_kind='app_links' AND m.recipient_user IS NOT NULL THEN PERFORM public.mark_app_links_sent(m.occasion,m.recipient_user); END IF;
   IF m.message_kind='deletion_confirm' AND m.post_action ? 'deletion_request' THEN PERFORM public.set_account_deletion_email_state((m.post_action->>'deletion_request')::uuid,true); END IF;
   IF m.post_action ? 'history_id' THEN PERFORM public.add_sent_to_customer_flag((m.post_action->>'history_id')::bigint); END IF;
   IF m.message_kind='order_reminder' THEN
    UPDATE eshop.payment_info SET data=coalesce(data,'{}')||'{"current_version_reminded":true}'::jsonb
    WHERE id=(m.post_action->>'payment_info_id')::bigint AND email_reminder_version=m.source_version;
   END IF;
   UPDATE public.email_messages SET post_action_state='done',last_error=CASE WHEN last_error='post_action_failed' THEN NULL ELSE last_error END WHERE id=m.id;
  EXCEPTION WHEN OTHERS THEN UPDATE public.email_messages SET last_error='post_action_failed' WHERE id=m.id; END;
 END LOOP;
END $function$

CREATE OR REPLACE FUNCTION public.apply_planned_changes_client_sync_v1()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_candidate record; v_change eshop.planned_changes%ROWTYPE;
  v_product eshop.products%ROWTYPE; v_occasion bigint; v_impacts jsonb; v_changed integer;
  v_failure text;
BEGIN
  PERFORM public.require_client_sync_service_role_v1();
  -- Serializes workers, including backlog across multiple instants of one product.
  IF NOT pg_try_advisory_xact_lock(7310420261004::bigint) THEN RETURN; END IF;
  FOR v_candidate IN SELECT id,subject_id,change_type FROM eshop.planned_changes
    WHERE NOT public.is_demo_occasion(occasion) AND change_time<=now() AND NOT applied AND failed_at IS NULL ORDER BY change_time,id
  LOOP
    -- Same lock order as editor commands: subject, then plan. Recheck after lock.
    IF v_candidate.change_type IN ('products.price','products.is_hidden') THEN
      PERFORM 1 FROM eshop.products WHERE id=v_candidate.subject_id FOR UPDATE;
    ELSIF v_candidate.change_type='forms.is_open' THEN
      PERFORM 1 FROM public.forms WHERE id=v_candidate.subject_id FOR UPDATE;
    END IF;
    SELECT * INTO v_change FROM eshop.planned_changes WHERE id=v_candidate.id FOR UPDATE;
    IF NOT FOUND OR v_change.applied OR v_change.failed_at IS NOT NULL OR v_change.change_time>now() THEN CONTINUE; END IF;
    BEGIN
      v_changed:=0; v_occasion:=NULL; v_impacts:='[]'::jsonb;
      IF v_change.change_type IN ('products.price','products.is_hidden') THEN
        SELECT * INTO v_product FROM eshop.products WHERE id=v_change.subject_id;
        IF NOT FOUND THEN RAISE EXCEPTION 'INVALID_SUBJECT'; END IF;
        SELECT occasion INTO v_occasion FROM eshop.product_types WHERE id=v_product.product_type;
        IF v_occasion IS NULL OR v_change.occasion IS DISTINCT FROM v_occasion
          OR v_product.occasion IS DISTINCT FROM v_occasion THEN RAISE EXCEPTION 'INVALID_OCCASION'; END IF;
        IF v_change.change_type='products.price' THEN
          PERFORM public.validate_product_price(v_change.new_value::numeric,v_product.data,v_product.currency_code);
          UPDATE eshop.products SET price=v_change.new_value::numeric,updated_at=now()
          WHERE id=v_change.subject_id AND price IS DISTINCT FROM v_change.new_value::numeric;
        ELSE
          UPDATE eshop.products SET is_hidden=v_change.new_value::boolean,updated_at=now()
          WHERE id=v_change.subject_id AND is_hidden IS DISTINCT FROM v_change.new_value::boolean;
        END IF;
        GET DIAGNOSTICS v_changed=ROW_COUNT;
      ELSIF v_change.change_type='forms.is_open' THEN
        SELECT occasion INTO v_occasion FROM public.forms WHERE id=v_change.subject_id;
        IF NOT FOUND THEN RAISE EXCEPTION 'INVALID_SUBJECT'; END IF;
        IF v_occasion IS NULL OR v_change.occasion IS DISTINCT FROM v_occasion THEN RAISE EXCEPTION 'INVALID_OCCASION'; END IF;
        UPDATE public.forms SET is_open=v_change.new_value::boolean WHERE id=v_change.subject_id AND is_open IS DISTINCT FROM v_change.new_value::boolean;
        GET DIAGNOSTICS v_changed=ROW_COUNT;
      ELSE RAISE EXCEPTION 'UNKNOWN_CHANGE_TYPE'; END IF;
      IF v_changed>0 THEN
        IF v_change.change_type='forms.is_open' THEN
          INSERT INTO public.client_aggregate_versions(aggregate_type,scope_type,scope_id,aggregate_id,version)
          VALUES('form','occasion',v_occasion,v_change.subject_id::text,1)
          ON CONFLICT(aggregate_type,scope_type,scope_id,aggregate_id) DO UPDATE
          SET version=public.client_aggregate_versions.version+1,updated_at=clock_timestamp();
          PERFORM public.record_client_sync_commit_v1(v_occasion,'inventory.form.planned','inventory',
            jsonb_build_array(jsonb_build_object('entityType','form','entityId',v_change.subject_id,
              'operation','update','safeLabel','Scheduled form change','changedFields',jsonb_build_array('is_open'))),
            '{}','[]','[]','service','planned_change:'||v_change.id::text);
        ELSE
        PERFORM public.advance_ticketing_authoring_version_internal_v1('product',v_occasion,v_change.subject_id);
        SELECT COALESCE(jsonb_agg(jsonb_build_object('component','private_inventory','userId',ou."user")),'[]'::jsonb)
          INTO v_impacts FROM eshop.order_product_ticket opt JOIN public.occasion_users ou
          ON ou.ticket=opt.ticket AND ou.occasion=v_occasion WHERE opt.product=v_change.subject_id;
        PERFORM public.record_client_sync_commit_v1(v_occasion,
          'inventory.product.planned','inventory',jsonb_build_array(jsonb_build_object(
          'entityType','product','entityId',v_change.subject_id,'operation','update',
          'safeLabel','Scheduled product change','changedFields',jsonb_build_array(split_part(v_change.change_type,'.',2)))),
          '{}',v_impacts,'[]','service','planned_change:'||v_change.id::text);
        END IF;
      END IF;
      UPDATE eshop.planned_changes SET applied=true,revision=revision+1 WHERE id=v_change.id;
    EXCEPTION WHEN OTHERS THEN
      -- This subtransaction rolls back price AND sync on any failure.
      v_failure := CASE WHEN SQLERRM IN ('INVALID_SUBJECT','INVALID_OCCASION','UNKNOWN_CHANGE_TYPE',
        'INVALID_PRODUCT_PRICE','DEPOSIT_AMOUNT_TOO_HIGH') THEN SQLERRM
        WHEN SQLSTATE IN ('22P02','22003') THEN 'INVALID_VALUE' ELSE 'APPLICATION_FAILED' END;
      UPDATE eshop.planned_changes SET failed_at=clock_timestamp(),failure_code=v_failure,revision=revision+1 WHERE id=v_change.id;
    END;
  END LOOP;
END; $function$

CREATE OR REPLACE FUNCTION public.apply_transaction_pairing(p_transaction_id bigint, p_payment_info_id bigint, p_method text, p_actor_kind text DEFAULT 'system'::text, p_details jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_transaction eshop.transactions%ROWTYPE;
  v_target eshop.payment_info%ROWTYPE;
  v_old_payment_info_id bigint;
  v_order_id bigint;
BEGIN
  PERFORM public.check_bank_account_writable((SELECT bank_account_id FROM eshop.transactions WHERE id=p_transaction_id));
  PERFORM public.check_bank_account_writable((SELECT bank_account FROM eshop.payment_info WHERE id=p_payment_info_id));
  IF p_method IS NULL OR p_method !~ '^[a-z0-9_]{1,64}$' THEN
    RAISE EXCEPTION 'PAIRING_INVALID_METHOD';
  END IF;
  IF p_actor_kind NOT IN ('service', 'user', 'system') THEN
    RAISE EXCEPTION 'PAIRING_INVALID_ACTOR_KIND';
  END IF;

  SELECT * INTO v_transaction
  FROM eshop.transactions
  WHERE id = p_transaction_id
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'PAIRING_TRANSACTION_NOT_FOUND'; END IF;
  v_old_payment_info_id := v_transaction.payment_info;

  IF p_actor_kind='user' THEN
    FOR v_order_id IN SELECT id FROM eshop.orders
      WHERE payment_info IN (v_old_payment_info_id,p_payment_info_id) ORDER BY id LOOP
      PERFORM public.check_order_is_mutable(v_order_id);
    END LOOP;
  END IF;

  IF v_old_payment_info_id IS NOT DISTINCT FROM p_payment_info_id THEN
    RETURN jsonb_build_object('status', 'unchanged', 'transaction_id', p_transaction_id,
      'payment_info_id', p_payment_info_id);
  END IF;

  IF p_payment_info_id IS NOT NULL THEN
    SELECT * INTO v_target FROM eshop.payment_info WHERE id = p_payment_info_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'PAIRING_PAYMENT_INFO_NOT_FOUND'; END IF;
    IF upper(trim(v_transaction.currency::text)) <> upper(trim(v_target.currency_code::text)) THEN
      RAISE EXCEPTION 'PAIRING_CURRENCY_MISMATCH';
    END IF;
    IF v_transaction.transaction_type IS DISTINCT FROM 'manual'
       AND v_transaction.bank_account_id <> v_target.bank_account
       AND NOT public.bank_sync_accounts_match(p_transaction_id,v_target.bank_account) THEN
      RAISE EXCEPTION 'PAIRING_BANK_ACCOUNT_MISMATCH';
    END IF;
  END IF;

  UPDATE eshop.transactions SET payment_info = p_payment_info_id WHERE id = p_transaction_id;

  IF v_old_payment_info_id IS NOT NULL THEN
    UPDATE eshop.payment_info pi SET
      paid = COALESCE((SELECT sum(t.amount) FROM eshop.transactions t
        WHERE t.payment_info = pi.id AND t.transaction_type IS DISTINCT FROM 'return'), 0),
      returned = COALESCE((SELECT abs(sum(t.amount)) FROM eshop.transactions t
        WHERE t.payment_info = pi.id AND t.transaction_type = 'return'), 0)
    WHERE pi.id = v_old_payment_info_id;
    SELECT o.id INTO v_order_id FROM eshop.orders o WHERE o.payment_info = v_old_payment_info_id;
    IF v_order_id IS NOT NULL THEN PERFORM public.recalculate_order_payment_status(v_order_id); END IF;
  END IF;

  IF p_payment_info_id IS NOT NULL THEN
    UPDATE eshop.payment_info pi SET
      paid = COALESCE((SELECT sum(t.amount) FROM eshop.transactions t
        WHERE t.payment_info = pi.id AND t.transaction_type IS DISTINCT FROM 'return'), 0),
      returned = COALESCE((SELECT abs(sum(t.amount)) FROM eshop.transactions t
        WHERE t.payment_info = pi.id AND t.transaction_type = 'return'), 0)
    WHERE pi.id = p_payment_info_id;
    SELECT o.id INTO v_order_id FROM eshop.orders o WHERE o.payment_info = p_payment_info_id;
    IF v_order_id IS NOT NULL THEN PERFORM public.recalculate_order_payment_status(v_order_id); END IF;
  END IF;

  INSERT INTO eshop.transaction_pairing_events (
    transaction_snapshot_id, transaction_id, old_payment_info_id,
    new_payment_info_id, action, method, actor_id, actor_kind, details
  ) VALUES (
    p_transaction_id, p_transaction_id, v_old_payment_info_id,
    p_payment_info_id, CASE WHEN p_payment_info_id IS NULL THEN 'unpaired' ELSE 'paired' END,
    p_method, auth.uid(), p_actor_kind, COALESCE(p_details, '{}'::jsonb)
  );

  RETURN jsonb_build_object('status', CASE WHEN p_payment_info_id IS NULL THEN 'unpaired' ELSE 'paired' END,
    'transaction_id', p_transaction_id, 'payment_info_id', p_payment_info_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.assert_canonical_mutation_write_release_internal_v1(p_occasion bigint)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE gate public.canonical_mutation_write_release_gate%ROWTYPE;
 client_build text; headers jsonb;
BEGIN
 SELECT * INTO gate FROM public.canonical_mutation_write_release_gate WHERE singleton FOR SHARE;
 IF NOT FOUND THEN RETURN; END IF;
 -- Preserve existing SQL operator/cron and signed service lanes. This grants no
 -- actor permission: the typed command still performs its own auth checks.
 IF (nullif(current_setting('request.method',true),'') IS NULL
 AND session_user IN ('postgres','supabase_admin')) OR auth.role()='service_role' THEN RETURN; END IF;
 BEGIN
  headers:=COALESCE(nullif(current_setting('request.headers',true),''),'{}')::jsonb;
  client_build:=substring(headers->>'x-client-info' FROM '^festapp/[0-9]+\.[0-9]+\.[0-9]+\+([0-9]{1,9})/(?:web|android|ios|macos|windows|linux|fuchsia|js|service)$');
 EXCEPTION WHEN OTHERS THEN
  RAISE insufficient_privilege USING MESSAGE='canonical editor requires valid release metadata';
 END;
 IF gate.paused OR client_build IS NULL OR client_build::bigint<gate.minimum_build
 OR NOT EXISTS(SELECT 1 FROM public.occasions WHERE id=p_occasion) THEN
  RAISE insufficient_privilege USING MESSAGE='canonical editor requires an enabled current release';
 END IF;
END $function$

