CREATE OR REPLACE FUNCTION public.assign_existing_companion_client_sync_v1(p_occasion bigint, p_owner uuid, p_companion uuid, p_command_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_policy jsonb; v_begin jsonb; v_hash text;
BEGIN
  v_policy:=public.get_companion_feature_policy_v1(p_occasion);
  IF NOT public.get_can_assign_companions_on_occasion(p_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion editor required';
  END IF;
  IF NOT COALESCE((v_policy->>'is_enabled')::boolean,false)
      OR NOT COALESCE((v_policy->>'allow_admin_assign')::boolean,false) THEN
    RAISE insufficient_privilege USING MESSAGE='admin companion assignment disabled';
  END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object('occasion',p_occasion,
    'owner',p_owner,'companion',p_companion)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'profile.companion.assign',
    p_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  PERFORM public.check_companion_relation_invariants_v1(p_occasion,p_owner,p_companion);
  IF EXISTS (SELECT 1 FROM public.user_companions uc WHERE uc.occasion=p_occasion
      AND uc."user"=p_owner AND uc.companion=p_companion) THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'unchanged',200,
      jsonb_build_object('owner',p_owner,'companion',p_companion));
  END IF;
  INSERT INTO public.user_companions(occasion,"user",companion,origin,created_by)
  VALUES(p_occasion,p_owner,p_companion,'admin_assigned',v_actor);
  RETURN public.complete_private_profile_mutation_v1(p_command_id,p_occasion,
    'profile.companion.assign',jsonb_build_array(jsonb_build_object(
      'entityType','companion_assignment','entityId',p_companion,'operation','insert',
      'safeLabel','Companion assignment','changedFields',jsonb_build_array('owner'))),
    ARRAY[p_owner],'{}','[]',jsonb_build_object('owner',p_owner,'companion',p_companion));
END $function$

CREATE OR REPLACE FUNCTION public.authorize_image_deletion(p_links text[])
 RETURNS TABLE(link text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_requested_count integer;
  v_found_count integer;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required.' USING ERRCODE = '42501';
  END IF;

  v_requested_count := cardinality(p_links);
  IF v_requested_count IS NULL OR v_requested_count < 1 OR v_requested_count > 50
     OR array_position(p_links, NULL) IS NOT NULL
     OR v_requested_count <> (SELECT count(DISTINCT requested) FROM unnest(p_links) AS requested) THEN
    RAISE EXCEPTION 'Image link batch must contain 1-50 unique non-null links.'
      USING ERRCODE = '22023';
  END IF;

  SELECT count(DISTINCT image.link) INTO v_found_count
  FROM public.images AS image
  WHERE image.link = ANY(p_links);

  IF v_found_count <> v_requested_count THEN
    RAISE EXCEPTION 'Every image link must exist.' USING ERRCODE = '42501';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.images AS image
    WHERE image.link = ANY(p_links)
      AND NOT (
        (image.unit IS NOT NULL AND public.get_is_editor_on_unit(image.unit))
        OR
        (image.occasion IS NOT NULL AND (
          public.get_is_editor_on_occasion(image.occasion)
          OR public.get_is_editor_order_on_occasion(image.occasion)
        ))
      )
  ) THEN
    RAISE EXCEPTION 'Permission denied for image deletion.' USING ERRCODE = '42501';
  END IF;

  IF EXISTS(SELECT 1 FROM public.blueprint_image_assets a WHERE a.url=ANY(p_links)) THEN
    RAISE insufficient_privilege USING MESSAGE='BLUEPRINT_IMAGE_IMMUTABLE'; END IF;

  RETURN QUERY
  SELECT DISTINCT image.link
  FROM public.images AS image
  WHERE image.link = ANY(p_links)
  ORDER BY image.link;
END;
$function$

CREATE OR REPLACE FUNCTION public.bank_sync_warning(p_bank_account_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_title text; v_type text; v_connection bigint; v_code text; v_contacts jsonb;
BEGIN
  SELECT title,type INTO v_title,v_type FROM eshop.bank_accounts WHERE id=p_bank_account_id;
  IF NOT FOUND OR v_type='CASH' THEN RETURN NULL; END IF;
  SELECT c.id INTO v_connection FROM eshop.bank_sync_connections c WHERE c.bank_account_id=p_bank_account_id
    OR c.id IN (SELECT connection_id FROM eshop.bank_sync_account_aliases WHERE bank_account_id=p_bank_account_id);
  v_code:=CASE WHEN v_connection IS NULL THEN 'not_configured' ELSE public.bank_sync_problem(v_connection) END;
  IF v_code IS NULL THEN RETURN NULL; END IF;
  SELECT COALESCE(jsonb_agg(jsonb_build_object('name',NULLIF(btrim(concat_ws(' ',ui.name,ui.surname)),''),
    'email',public.get_user_delivery_email(ui.id)) ORDER BY ui.name,ui.surname,ui.id),'[]'::jsonb)
    INTO v_contacts FROM eshop.bank_account_users bau JOIN public.user_info ui ON ui.id=bau."user"
    WHERE bau.bank_account=p_bank_account_id AND bau.is_admin;
  RETURN jsonb_build_object('code',v_code,'bank_account_title',v_title,'contacts',v_contacts,
    'bank_account_id',p_bank_account_id,'is_admin',EXISTS (
      SELECT 1 FROM eshop.bank_account_users bau WHERE bau.bank_account=p_bank_account_id
        AND bau."user"=auth.uid() AND bau.is_admin));
END;
$function$

CREATE OR REPLACE FUNCTION public.begin_anonymous_client_mutation_v1(p_command_id uuid, p_command_name text, p_occasion bigint, p_actor_client_id uuid, p_request_sha256 text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_receipt public.client_mutation_receipts%ROWTYPE; v_inserted integer;
BEGIN
  PERFORM public.check_occasion_writable(p_occasion);
  IF auth.uid() IS NOT NULL OR p_actor_client_id IS NULL OR p_command_id IS NULL
     OR p_occasion IS NULL OR p_command_name !~ '^[a-z][a-z0-9_.]{2,95}$'
     OR p_request_sha256 !~ '^[0-9a-f]{64}$' THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid anonymous mutation receipt claim';
  END IF;
  INSERT INTO public.client_mutation_receipts
    (command_id,command_name,occasion,actor_client_id,request_sha256)
  VALUES (p_command_id,p_command_name,p_occasion,p_actor_client_id,p_request_sha256)
  ON CONFLICT (command_id) DO NOTHING;
  GET DIAGNOSTICS v_inserted=ROW_COUNT;
  SELECT * INTO STRICT v_receipt FROM public.client_mutation_receipts
    WHERE command_id=p_command_id FOR UPDATE;
  IF v_receipt.command_name IS DISTINCT FROM p_command_name
     OR v_receipt.occasion IS DISTINCT FROM p_occasion OR v_receipt.actor_id IS NOT NULL
     OR v_receipt.actor_client_id IS DISTINCT FROM p_actor_client_id
     OR v_receipt.request_sha256 IS DISTINCT FROM p_request_sha256 THEN
    RAISE invalid_parameter_value USING MESSAGE='command id was already used with different request data';
  END IF;
  IF v_receipt.status='completed' THEN
    RETURN jsonb_build_object('disposition','replay','response',v_receipt.response);
  ELSIF v_receipt.status='expired' THEN
    RETURN jsonb_build_object('disposition','replay',
      'response',public.expired_client_mutation_response_v1(v_receipt));
  END IF;
  IF v_inserted<>1 THEN RAISE serialization_failure
    USING MESSAGE='incomplete mutation receipt cannot be resumed'; END IF;
  RETURN jsonb_build_object('disposition','claimed');
END; $function$

CREATE OR REPLACE FUNCTION public.begin_bank_sync_operation(p_id uuid, p_account_id bigint, p_operation text, p_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_operation eshop.bank_sync_operations%ROWTYPE; v_inserted integer;
BEGIN
  PERFORM public.check_is_admin_for_bank_account(p_account_id);
  INSERT INTO eshop.bank_sync_operations(id,bank_account_id,actor,operation,payload_sha256,state)
    VALUES(p_id,p_account_id,auth.uid(),p_operation,p_hash,'pending') ON CONFLICT DO NOTHING;
  GET DIAGNOSTICS v_inserted=ROW_COUNT;
  IF v_inserted>0 THEN
    PERFORM public.abuse_charge_v1(public.abuse_effective_rules_v1('bank.operation',NULL,NULL),
      jsonb_build_object('actor',auth.uid(),'recipient','bank:'||p_account_id,'global','all'));
  END IF;
  SELECT * INTO STRICT v_operation FROM eshop.bank_sync_operations WHERE id=p_id OR (bank_account_id=p_account_id AND actor=auth.uid() AND operation=p_operation
      AND payload_sha256=p_hash AND state IN ('pending','running','uncertain')) ORDER BY (id=p_id) DESC LIMIT 1 FOR UPDATE;
  IF v_operation.actor IS DISTINCT FROM auth.uid() OR v_operation.bank_account_id<>p_account_id
    OR v_operation.operation<>p_operation OR v_operation.payload_sha256<>p_hash THEN
    RAISE EXCEPTION 'BANK_SYNC_OPERATION_CONFLICT';
  END IF;
  RETURN jsonb_build_object('id',v_operation.id,'state',v_operation.state,'result',v_operation.result);
END;
$function$

