CREATE OR REPLACE FUNCTION public.blueprint_canonical_surface_projection_internal(p_node jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE surface jsonb:=p_node->'surface';ring jsonb;a jsonb;b jsonb;projected jsonb:='[]';rings jsonb;points jsonb;module numeric;area numeric; min_x numeric:=1e9;min_y numeric:=1e9;max_x numeric:=0;max_y numeric:=0;vertices int:=0;i int;j int;k int;other jsonb;c jsonb;d jsonb;
BEGIN
 IF jsonb_typeof(surface) IS DISTINCT FROM 'object' THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_SURFACE';END IF;
 IF surface->>'type' IN ('rect','circle') THEN
  IF surface-'type'<>'{}' OR (surface->>'type'='circle' AND (abs((p_node->>'width')::numeric-(p_node->>'height')::numeric)>1.0/1024 OR p_node->>'furniture'='bar')) THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_SURFACE';END IF;
  RETURN (p_node-'surface')||jsonb_build_object('shape',surface->'type');
 END IF;
 IF surface->>'type' IS DISTINCT FROM 'grid' OR EXISTS(SELECT 1 FROM jsonb_object_keys(surface) key WHERE key NOT IN ('type','moduleSize','outer','holes')) OR jsonb_typeof(surface->'moduleSize') IS DISTINCT FROM 'number' OR jsonb_typeof(surface->'outer') IS DISTINCT FROM 'array' OR jsonb_typeof(surface->'holes') IS DISTINCT FROM 'array' OR jsonb_array_length(surface->'holes')>128 THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_GRID';END IF;
 module:=(surface->>'moduleSize')::numeric;
 IF module<=0 OR module>1000000 THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_GRID';END IF;
 rings:=jsonb_build_array(surface->'outer')||(surface->'holes');
 FOR k IN 0..jsonb_array_length(rings)-1 LOOP
  ring:=rings->k;area:=0;points:='[]';
  IF jsonb_typeof(ring)<>'array' OR jsonb_array_length(ring)<4 THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_GRID_RING';END IF;
  PERFORM public.validate_blueprint_polygon_internal(ring,true);
  vertices:=vertices+jsonb_array_length(ring);
  FOR i IN 0..jsonb_array_length(ring)-1 LOOP
   a:=ring->i;b:=ring->((i+1)%jsonb_array_length(ring));
   IF (a->>0)::numeric<>trunc((a->>0)::numeric) OR (a->>1)::numeric<>trunc((a->>1)::numeric) OR abs((a->>0)::numeric)>16384 OR abs((a->>1)::numeric)>16384 OR ((a->0=b->0)=(a->1=b->1)) THEN RAISE check_violation USING MESSAGE='BLUEPRINT_NON_ORTHOGONAL_GRID';END IF;
   area:=area+(a->>0)::numeric*(b->>1)::numeric-(b->>0)::numeric*(a->>1)::numeric;
   IF k=0 THEN min_x:=least(min_x,(a->>0)::numeric);min_y:=least(min_y,(a->>1)::numeric);max_x:=greatest(max_x,(a->>0)::numeric);max_y:=greatest(max_y,(a->>1)::numeric);END IF;
   points:=points||jsonb_build_array(jsonb_build_array((a->>0)::numeric*module-(p_node->>'width')::numeric/2,(a->>1)::numeric*module-(p_node->>'height')::numeric/2));
  END LOOP;
  IF (k=0 AND area<=0) OR (k>0 AND area>=0) THEN RAISE check_violation USING MESSAGE='BLUEPRINT_GRID_WINDING';END IF;
  IF k>0 AND NOT public.blueprint_grid_contains_internal(rings->0,(ring#>>'{0,0}')::numeric,(ring#>>'{0,1}')::numeric) THEN RAISE check_violation USING MESSAGE='BLUEPRINT_GRID_HOLE_OUTSIDE';END IF;
  FOR j IN 0..k-1 LOOP
   other:=rings->j;
   IF j>0 AND (public.blueprint_grid_contains_internal(other,(ring#>>'{0,0}')::numeric,(ring#>>'{0,1}')::numeric) OR public.blueprint_grid_contains_internal(ring,(other#>>'{0,0}')::numeric,(other#>>'{0,1}')::numeric)) THEN RAISE check_violation USING MESSAGE='BLUEPRINT_GRID_HOLES_OVERLAP';END IF;
   FOR i IN 0..jsonb_array_length(ring)-1 LOOP
    a:=ring->i;b:=ring->((i+1)%jsonb_array_length(ring));
    FOR c,d IN SELECT value,other->((ordinality::int)%jsonb_array_length(other)) FROM jsonb_array_elements(other) WITH ORDINALITY LOOP
     IF greatest(least((a->>0)::numeric,(b->>0)::numeric),least((c->>0)::numeric,(d->>0)::numeric))<=least(greatest((a->>0)::numeric,(b->>0)::numeric),greatest((c->>0)::numeric,(d->>0)::numeric)) AND greatest(least((a->>1)::numeric,(b->>1)::numeric),least((c->>1)::numeric,(d->>1)::numeric))<=least(greatest((a->>1)::numeric,(b->>1)::numeric),greatest((c->>1)::numeric,(d->>1)::numeric)) THEN RAISE check_violation USING MESSAGE='BLUEPRINT_GRID_RINGS_TOUCH';END IF;
    END LOOP;
   END LOOP;
  END LOOP;
  projected:=projected||jsonb_build_array(points);
 END LOOP;
 IF vertices>512 OR min_x<>0 OR min_y<>0 OR max_x*max_y>16384 OR abs((p_node->>'width')::numeric-max_x*module)>1.0/1024 OR abs((p_node->>'height')::numeric-max_y*module)>1.0/1024 THEN RAISE check_violation USING MESSAGE='BLUEPRINT_GRID_DIMENSIONS';END IF;
 RETURN (p_node-'surface')||jsonb_build_object('shape','polygon','points',projected->0,'holes',projected-0);
END $function$

CREATE OR REPLACE FUNCTION public.blueprint_grid_contains_internal(p_ring jsonb, p_x numeric, p_y numeric)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE a jsonb;b jsonb; crossings int:=0;i int;size int:=jsonb_array_length(p_ring);
BEGIN
 FOR i IN 0..size-1 LOOP
  a:=p_ring->i;b:=p_ring->((i+1)%size);
  IF p_x BETWEEN least((a->>0)::numeric,(b->>0)::numeric) AND greatest((a->>0)::numeric,(b->>0)::numeric)
   AND p_y BETWEEN least((a->>1)::numeric,(b->>1)::numeric) AND greatest((a->>1)::numeric,(b->>1)::numeric) THEN RETURN false;END IF;
  IF ((a->>1)::numeric>p_y)<>((b->>1)::numeric>p_y) AND p_x<(a->>0)::numeric THEN crossings:=crossings+1;END IF;
 END LOOP;
 RETURN crossings%2=1;
END $function$

CREATE OR REPLACE FUNCTION public.blueprint_hold_admission_internal(p_form bigint, p_spots bigint[], p_secret uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE item record; counts jsonb; requested bigint; occupied bigint; physical bigint; cap bigint;
BEGIN
 PERFORM public.lock_blueprint_hold_scope_internal(p_spots);
 FOR item IN SELECT p.*,count(*) AS requested FROM eshop.spots s JOIN eshop.products p ON p.id=s.product
  WHERE s.id=ANY(p_spots) AND NOT coalesce(s.secret=p_secret AND s.secret_expiration_time>clock_timestamp(),false)
  GROUP BY p.id ORDER BY p.id LOOP
  IF item.is_hidden THEN RETURN jsonb_build_object('code',409,'reason','PRODUCT_HIDDEN'); END IF;
  IF NOT EXISTS(SELECT 1 FROM public.form_fields ff WHERE ff.form=p_form AND ff.product_type=item.product_type
   AND (ff.type='ticket' OR (ff.type='product_type' AND ff.is_ticket_field)) AND NOT ff.is_hidden) THEN
   RETURN jsonb_build_object('code',409,'reason','PRODUCT_NOT_IN_FORM'); END IF;
  IF coalesce(item.maximum,0)>0 THEN
   SELECT count(*) INTO occupied FROM eshop.order_product_ticket WHERE product=item.id;
   SELECT occupied+count(*) INTO occupied FROM eshop.spots WHERE product=item.id AND order_product_ticket IS NULL
    AND secret IS NOT NULL AND secret_expiration_time>clock_timestamp();
   IF occupied+item.requested>item.maximum THEN RETURN jsonb_build_object('code',409,'reason','PRODUCT_CAPACITY_EXCEEDED'); END IF;
  END IF;
  counts:=public.blueprint_product_availability_internal(item.id);
  IF (counts->>'available')::bigint<item.requested THEN RETURN jsonb_build_object('code',409,'reason',coalesce(counts->>'reason','PRODUCT_CAPACITY_EXCEEDED')); END IF;
 END LOOP;
 -- Two differently priced products can consume the same context. Sum their
 -- quantities before holding either member, rather than checking them alone.
 FOR item IN SELECT pic.inventory_context,ip.sellable_capacity,sum(pic.quantity)::bigint AS requested
  FROM eshop.spots s JOIN eshop.product_inventory_contexts pic ON pic.product=s.product
  JOIN public.inventory_contexts ic ON ic.id=pic.inventory_context JOIN public.inventory_pools ip ON ip.id=ic.inventory_pool
  WHERE s.id=ANY(p_spots) AND NOT coalesce(s.secret=p_secret AND s.secret_expiration_time>clock_timestamp(),false)
  GROUP BY pic.inventory_context,ip.sellable_capacity ORDER BY pic.inventory_context LOOP
  SELECT count(*),count(*) FILTER(WHERE order_product_ticket IS NOT NULL OR
   (secret IS NOT NULL AND secret_expiration_time>clock_timestamp())) INTO physical,occupied
   FROM eshop.spots WHERE inventory_context=item.inventory_context;
  -- Addressed seats usually have no inventory_context. Their existing spot
  -- holds nevertheless promise all PIC quantities at checkout. Count that
  -- same hold record, subtracting any physical occupancy already counted.
  SELECT occupied+coalesce(sum(greatest(pic.quantity-CASE
    WHEN held.inventory_context=item.inventory_context THEN 1 ELSE 0 END,0)),0)
   INTO occupied FROM eshop.spots held JOIN eshop.product_inventory_contexts pic ON pic.product=held.product
   WHERE pic.inventory_context=item.inventory_context AND held.blueprint IS NOT NULL
    AND held.order_product_ticket IS NULL AND held.secret IS NOT NULL
    AND held.secret_expiration_time>clock_timestamp();
  cap:=least(physical,coalesce(item.sellable_capacity,physical));
  IF occupied+item.requested>cap THEN RETURN jsonb_build_object('code',409,'reason','PRODUCT_CAPACITY_EXCEEDED'); END IF;
 END LOOP;
 RETURN jsonb_build_object('code',200);
END $function$

CREATE OR REPLACE FUNCTION public.blueprint_product_availability_internal(p_product bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE p eshop.products; c record; total bigint; occupied bigint; cap bigint; available bigint:=2147483647; capacity bigint:=2147483647;
BEGIN
 SELECT * INTO p FROM eshop.products WHERE id=p_product;
 IF NOT FOUND THEN RETURN jsonb_build_object('capacity',0,'available',0,'reason','PRODUCT_NOT_FOUND'); END IF;
 IF coalesce(p.maximum,0)>0 THEN
  capacity:=p.maximum;
  available:=greatest(0,p.maximum-(SELECT count(*) FROM eshop.order_product_ticket WHERE product=p.id));
 END IF;
 FOR c IN SELECT pic.inventory_context,pic.quantity,ip.sellable_capacity FROM eshop.product_inventory_contexts pic
  JOIN public.inventory_contexts ic ON ic.id=pic.inventory_context JOIN public.inventory_pools ip ON ip.id=ic.inventory_pool WHERE pic.product=p.id LOOP
  SELECT count(*),count(*) FILTER(WHERE order_product_ticket IS NOT NULL OR (secret IS NOT NULL AND secret_expiration_time>statement_timestamp()))
   INTO total,occupied FROM eshop.spots WHERE inventory_context=c.inventory_context;
  cap:=least(total,coalesce(c.sellable_capacity,total));
  capacity:=least(capacity,cap/greatest(c.quantity,1));
  available:=least(available,greatest(0,cap-occupied)/greatest(c.quantity,1));
 END LOOP;
 RETURN jsonb_build_object('capacity',capacity,'available',CASE WHEN p.is_hidden THEN 0 ELSE available END,
  'reason',CASE WHEN p.is_hidden THEN 'PRODUCT_HIDDEN' WHEN available=0 THEN 'PRODUCT_CAPACITY_EXCEEDED' ELSE NULL END);
END $function$

CREATE OR REPLACE FUNCTION public.blueprint_validate_assembly_internal(p_spec jsonb, p_node_kind text)
 RETURNS void
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE definition jsonb:=public.blueprint_contract_metadata_internal()->'assemblyKinds'->(p_spec->>'kind'); seats numeric;
BEGIN
 IF jsonb_typeof(p_spec) IS DISTINCT FROM 'object' OR definition IS NULL OR definition->>'nodeKind' IS DISTINCT FROM p_node_kind
  OR NOT(p_spec ?& ARRAY(SELECT jsonb_array_elements_text(definition->'required'))) THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_ASSEMBLY';END IF;
 PERFORM public.blueprint_validate_leaves_internal(p_spec-'kind',definition->'fields');
 CASE p_spec->>'kind'
  WHEN 'rows' THEN seats:=(p_spec->>'rows')::numeric*(p_spec->>'seatsPerRow')::numeric*(p_spec->>'blocks')::numeric;
  WHEN 'bus' THEN
   IF (p_spec->>'left')::numeric+(p_spec->>'right')::numeric=0 THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_ASSEMBLY_CAPACITY';END IF;
   seats:=(p_spec->>'rows')::numeric*((p_spec->>'left')::numeric+(p_spec->>'right')::numeric)+(p_spec->>'rear')::numeric;
   IF (p_spec->>'decks')::numeric=2 THEN seats:=seats+(p_spec->>'upperRows')::numeric*((p_spec->>'left')::numeric+(p_spec->>'right')::numeric)+(p_spec->>'upperRear')::numeric;END IF;
  WHEN 'compartments' THEN seats:=(p_spec->>'compartments')::numeric*(p_spec->>'seats')::numeric;
  ELSE seats:=(p_spec->>'seats')::numeric;
 END CASE;
 IF seats>(public.blueprint_contract_metadata_internal()->>'assemblySeatsMax')::numeric THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_ASSEMBLY_CAPACITY';END IF;
END $function$

CREATE OR REPLACE FUNCTION public.blueprint_validate_gradient_internal(p_gradient jsonb)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE key text; v jsonb; prev numeric:=-1; expected int;
BEGIN
 IF jsonb_typeof(p_gradient) IS DISTINCT FROM 'object' OR coalesce(p_gradient->>'type','') NOT IN ('linear','radial') OR coalesce(p_gradient->>'spread','') NOT IN ('pad','repeat','reflect') OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_gradient) k WHERE k NOT IN ('type','colors','stops','spread') AND (p_gradient->>'type'='linear' AND k NOT IN ('from','to') OR p_gradient->>'type'='radial' AND k NOT IN ('center','radius','focal','matrix'))) THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_GRADIENT';END IF;
 IF jsonb_typeof(p_gradient->'colors') IS DISTINCT FROM 'array' OR jsonb_typeof(p_gradient->'stops') IS DISTINCT FROM 'array' OR jsonb_array_length(p_gradient->'colors') NOT BETWEEN 2 AND 1024 OR jsonb_array_length(p_gradient->'colors')<>jsonb_array_length(p_gradient->'stops') OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(p_gradient->'colors') c WHERE c !~ '^#[0-9a-fA-F]{8}$') THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_GRADIENT';END IF;
 FOR v IN SELECT * FROM jsonb_array_elements(p_gradient->'stops') LOOP
  IF jsonb_typeof(v)<>'number' OR v::numeric<prev OR v::numeric NOT BETWEEN 0 AND 1 THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_GRADIENT';END IF;prev:=v::numeric;
 END LOOP;
 FOREACH key IN ARRAY CASE WHEN p_gradient->>'type'='linear' THEN ARRAY['from','to'] ELSE ARRAY['center','matrix','focal'] END LOOP
  IF key='focal' AND (NOT p_gradient ? key OR p_gradient->key='null') THEN CONTINUE;END IF;
  expected:=CASE WHEN key='matrix' THEN 6 ELSE 2 END;
  IF jsonb_typeof(p_gradient->key) IS DISTINCT FROM 'array' OR jsonb_array_length(p_gradient->key)<>expected THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_GRADIENT';END IF;
  FOR v IN SELECT * FROM jsonb_array_elements(p_gradient->key) LOOP IF jsonb_typeof(v)<>'number' OR abs(v::numeric)>1000000000 THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_GRADIENT';END IF;END LOOP;
 END LOOP;
 IF p_gradient->>'type'='radial' AND (jsonb_typeof(p_gradient->'radius') IS DISTINCT FROM 'number' OR (p_gradient->>'radius')::numeric<=0 OR (p_gradient->>'radius')::numeric>1000000000) THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_GRADIENT';END IF;
END $function$

CREATE OR REPLACE FUNCTION public.blueprint_validate_leaves_internal(p_value jsonb, p_rules jsonb)
 RETURNS void
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE entry record; rule jsonb; value jsonb;
BEGIN
 IF jsonb_typeof(p_value) IS DISTINCT FROM 'object' THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_DECLARATION'; END IF;
 FOR entry IN SELECT * FROM jsonb_each(p_value) LOOP
  rule:=p_rules->entry.key;value:=entry.value;
  IF rule IS NULL OR value='null'::jsonb THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_DECLARATION',DETAIL=entry.key;END IF;
  IF rule ? 'enum' AND NOT(rule->'enum' @> jsonb_build_array(value)) THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_DECLARATION',DETAIL=entry.key;END IF;
  IF rule ? 'type' AND jsonb_typeof(value) IS DISTINCT FROM (CASE WHEN rule->>'type'='integer' THEN 'number' ELSE rule->>'type' END) THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_DECLARATION',DETAIL=entry.key;END IF;
  IF rule->>'type' IN ('number','integer') THEN
   IF rule->>'type'='integer' AND value::numeric<>trunc(value::numeric) THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_DECLARATION',DETAIL=entry.key;END IF;
   IF (rule ? 'minimum' AND value::numeric<(rule->>'minimum')::numeric) OR (rule ? 'maximum' AND value::numeric>(rule->>'maximum')::numeric) OR (rule ? 'exclusiveMinimum' AND value::numeric<=(rule->>'exclusiveMinimum')::numeric) THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_DECLARATION',DETAIL=entry.key;END IF;
  ELSIF rule->>'type'='string' THEN
   IF (rule ? 'minLength' AND length(value#>>'{}')<(rule->>'minLength')::int) OR (rule ? 'pattern' AND (value#>>'{}') !~ (rule->>'pattern')) THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_DECLARATION',DETAIL=entry.key;END IF;
   IF entry.key='fontFamilyId' AND NOT EXISTS(SELECT 1 FROM public.ticket_font_families WHERE id=value#>>'{}') THEN RAISE check_violation USING MESSAGE='BLUEPRINT_FONT_FAMILY_UNAVAILABLE';END IF;
  END IF;
 END LOOP;
END $function$

CREATE OR REPLACE FUNCTION public.blueprint_validate_path_internal(p_path jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE command jsonb;arity int; coordinate jsonb;
BEGIN
 IF jsonb_typeof(p_path) IS DISTINCT FROM 'array' OR jsonb_array_length(p_path)>200000 THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_VECTOR_PATH';END IF;
 FOR command IN SELECT * FROM jsonb_array_elements(p_path) LOOP
  IF jsonb_typeof(command)<>'array' THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_VECTOR_PATH';END IF;
  arity:=(public.blueprint_contract_metadata_internal()->'pathArities'->>(command->>0))::int;
  IF arity IS NULL OR jsonb_array_length(command)<>arity+1 THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_VECTOR_PATH';END IF;
  FOR coordinate IN SELECT value FROM jsonb_array_elements(command) WITH ORDINALITY WHERE ordinality>1 LOOP
   IF jsonb_typeof(coordinate)<>'number' OR abs(coordinate::numeric)>1000000000 THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_VECTOR_PATH';END IF;
  END LOOP;
 END LOOP;
 RETURN jsonb_array_length(p_path);
END $function$

CREATE OR REPLACE FUNCTION public.blueprint_validate_style_internal(p_style jsonb, p_kind text)
 RETURNS void
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE meta jsonb:=public.blueprint_contract_metadata_internal(); pattern jsonb; value jsonb;
BEGIN
 IF jsonb_typeof(p_style) IS DISTINCT FROM 'object' OR (p_kind='group' AND p_style<>'{}') THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_STYLE';END IF;
 IF EXISTS(SELECT 1 FROM jsonb_object_keys(p_style) key WHERE NOT(meta->'styleSchemas'->p_kind->'properties' ? key)) THEN RAISE check_violation USING MESSAGE='BLUEPRINT_UNKNOWN_STYLE';END IF;
 PERFORM public.blueprint_validate_leaves_internal(p_style-ARRAY['label','strokePattern'],meta->'visual');
 IF p_style ? 'label' THEN PERFORM public.blueprint_validate_leaves_internal(p_style->'label',meta->'label');END IF;
 IF p_style ? 'strokePattern' THEN
  pattern:=p_style->'strokePattern';
  IF jsonb_typeof(pattern) IS DISTINCT FROM 'object' OR coalesce(pattern->>'type','') NOT IN ('solid','dashed','dotted','custom') OR EXISTS(SELECT 1 FROM jsonb_object_keys(pattern) key WHERE key<>'type' AND (pattern->>'type'<>'custom' OR key<>'lengths')) THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_STROKE_PATTERN';END IF;
  IF pattern->>'type'='custom' THEN
   IF jsonb_typeof(pattern->'lengths') IS DISTINCT FROM 'array' OR jsonb_array_length(pattern->'lengths') NOT BETWEEN 1 AND 32 THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_STROKE_PATTERN';END IF;
   FOR value IN SELECT * FROM jsonb_array_elements(pattern->'lengths') LOOP
    IF jsonb_typeof(value)<>'number' OR value::numeric<=0 OR value::numeric>1000000000 THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_STROKE_PATTERN';END IF;
   END LOOP;
  END IF;
 END IF;
END $function$

CREATE OR REPLACE FUNCTION public.blueprint_validate_vector_internal(p_graphic jsonb)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE command jsonb;depth int:=0;segments int:=0;key text; value jsonb;allowed text[];
BEGIN
 IF jsonb_typeof(p_graphic) IS DISTINCT FROM 'object' OR p_graphic->>'type' IS DISTINCT FROM 'vector' OR p_graphic->>'version' IS DISTINCT FROM '1' OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_graphic) k WHERE k NOT IN ('type','version','width','height','commands')) OR jsonb_typeof(p_graphic->'commands') IS DISTINCT FROM 'array' OR jsonb_array_length(p_graphic->'commands')>10000 OR octet_length(p_graphic::text)>8388608 THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_VECTOR';END IF;
 FOREACH key IN ARRAY ARRAY['width','height'] LOOP value:=p_graphic->key;IF jsonb_typeof(value) IS DISTINCT FROM 'number' OR value::numeric<=0 OR value::numeric>1000000 THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_VECTOR';END IF;END LOOP;
 FOR command IN SELECT * FROM jsonb_array_elements(p_graphic->'commands') LOOP
  IF jsonb_typeof(command)<>'object' THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_VECTOR_COMMAND';END IF;
  allowed:=CASE command->>'op' WHEN 'path' THEN ARRAY['op','path','fillRule','fill','stroke','strokeWidth','strokeCap','strokeJoin','miterLimit','fillGradient','strokeGradient'] WHEN 'clip' THEN ARRAY['op','path','fillRule'] WHEN 'layer' THEN ARRAY['op','opacity'] WHEN 'restore' THEN ARRAY['op'] ELSE NULL END;
  IF allowed IS NULL OR EXISTS(SELECT 1 FROM jsonb_object_keys(command) k WHERE NOT(k=ANY(allowed))) THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_VECTOR_COMMAND';END IF;
  IF command->>'op'='restore' THEN depth:=depth-1;
  ELSIF command->>'op'='layer' THEN
   value:=command->'opacity';IF jsonb_typeof(value) IS DISTINCT FROM 'number' OR value::numeric NOT BETWEEN 0 AND 1 THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_VECTOR_OPACITY';END IF;depth:=depth+1;
  ELSE
   segments:=segments+public.blueprint_validate_path_internal(command->'path');
   IF coalesce(command->>'fillRule','') NOT IN ('nonzero','evenodd') THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_VECTOR_FILL';END IF;
   IF command->>'op'='clip' THEN depth:=depth+1;
   ELSE
    FOREACH key IN ARRAY ARRAY['fill','stroke'] LOOP IF command ? key AND command->key<>'null' AND coalesce(command->>key,'') !~ '^#[0-9a-fA-F]{8}$' THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_VECTOR_PAINT';END IF;END LOOP;
    IF jsonb_typeof(command->'strokeWidth') IS DISTINCT FROM 'number' OR (command->>'strokeWidth')::numeric NOT BETWEEN 0 AND 1000000000 OR coalesce(command->>'strokeCap','') NOT IN ('butt','round','square') OR coalesce(command->>'strokeJoin','') NOT IN ('miter','round','bevel') OR jsonb_typeof(command->'miterLimit') IS DISTINCT FROM 'number' OR (command->>'miterLimit')::numeric NOT BETWEEN 1 AND 1000000 THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_VECTOR_PAINT';END IF;
    FOREACH key IN ARRAY ARRAY['fillGradient','strokeGradient'] LOOP IF command ? key AND command->key<>'null' THEN PERFORM public.blueprint_validate_gradient_internal(command->key);END IF;END LOOP;
   END IF;
  END IF;
  IF depth NOT BETWEEN 0 AND 32 OR segments>200000 THEN RAISE check_violation USING MESSAGE='BLUEPRINT_VECTOR_LIMIT';END IF;
 END LOOP;
 IF depth<>0 THEN RAISE check_violation USING MESSAGE='BLUEPRINT_UNBALANCED_VECTOR';END IF;
END $function$

CREATE OR REPLACE FUNCTION public.bound_document_data_v1(data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE policy jsonb; limits jsonb; cap bigint;
BEGIN
 policy:=public.abuse_effective_rules_v1('document.output',NULL,NULL);
 IF policy IS NULL THEN RAISE configuration_limit_exceeded USING MESSAGE='abuse_policy_missing'; END IF;
 SELECT jsonb_object_agg(r->>'rule_key',(r->>'base_limit')::bigint) INTO limits FROM jsonb_array_elements(policy->'rules') r;
 cap:=(limits->>'document.input.bytes')::bigint;
 IF octet_length(data::text)>cap THEN RAISE SQLSTATE 'PT429' USING MESSAGE='document_input_limit'; END IF;
 RETURN data||jsonb_build_object('abuseLimits',limits);
END $function$

CREATE OR REPLACE FUNCTION public.build_occasion_setup_configuration(p_unit bigint, p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE configuration jsonb; organization_id bigint;
  provisional_link text := 'draft-' || p_id::text;
BEGIN
  IF auth.uid() IS NULL OR NOT (public.get_is_editor_on_unit(p_unit) OR public.get_is_manager_on_unit(p_unit)) THEN
    RAISE EXCEPTION 'Draft access denied' USING ERRCODE = '42501';
  END IF;
  SELECT organization INTO organization_id FROM public.units WHERE id = p_unit;
  BEGIN
    PERFORM public.update_occasion_internal_v1(jsonb_build_object(
      'unit',p_unit,'organization',organization_id,'title','',
      'link',provisional_link,'is_hidden',true,'is_open',false,
      'start_time',now()+interval '30 days','end_time',now()+interval '33 days'));
    SELECT item INTO configuration
      FROM jsonb_array_elements(public.get_occasion_setup_sources(p_unit)) item
      WHERE item->'occasion'->>'link' = provisional_link;
    IF configuration IS NULL THEN RAISE EXCEPTION 'Creation configuration missing'; END IF;
    RAISE EXCEPTION 'Rollback provisional creation' USING ERRCODE = 'ZX001';
  EXCEPTION WHEN SQLSTATE 'ZX001' THEN
    -- Variables retain their values while all writes in the block roll back.
    NULL;
  END;
  configuration := jsonb_set(configuration,'{occasion,link}','""'::jsonb);
  configuration := jsonb_set(configuration,'{forms}',coalesce((SELECT jsonb_agg(jsonb_set(f,'{link}','""'::jsonb))
    FROM jsonb_array_elements(configuration->'forms') f),'[]'::jsonb));
  RETURN configuration;
END $function$

CREATE OR REPLACE FUNCTION public.cancel_order_domain_internal_v1(order_id bigint, p_notify boolean)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
    ticket_ids BIGINT[];
    updated_order_data jsonb;
    v_order eshop.orders;
    v_occasion public.occasions;
    v_notice jsonb;
BEGIN
    PERFORM public.lock_blueprint_scope_internal(ARRAY[(SELECT occasion FROM eshop.orders WHERE id=order_id)]);
    PERFORM public.lock_order_capacity_scope_internal(ARRAY[order_id]);
    SELECT * INTO v_order FROM eshop.orders WHERE id=order_id FOR UPDATE;
    IF v_order.id IS NULL THEN RAISE EXCEPTION 'Order not found'; END IF;
    IF v_order.state='storno' THEN RETURN; END IF;
    PERFORM public.check_order_is_mutable(order_id);
    PERFORM public.cancel_order_email_intents(order_id);
    -- Retrieve all ticket ids associated with the order
    SELECT ARRAY_AGG(t.id) INTO ticket_ids
    FROM eshop.tickets t
    JOIN eshop.order_product_ticket opt ON opt.ticket = t.id
    WHERE opt."order" = order_id;

    -- Check if the order exists and has associated tickets
    IF ticket_ids IS NULL THEN
        -- This is not an error, just an order with no tickets yet.
        -- But we can still storno the order itself.
        RAISE NOTICE 'No tickets found for order %, proceeding to storno order shell.', order_id;
    END IF;

    -- Call the helper to storno all tickets and their relations
    -- The helper function gracefully handles an empty/NULL array
    PERFORM internal_storno_tickets_221(ticket_ids);

    -- Set the order state to 'storno', price to 0, and update the data field
    UPDATE eshop.orders
    SET state = 'storno',
        price = 0,
        data = COALESCE(data, '{}'::jsonb) || jsonb_build_object('tickets', '[]'::jsonb),
        updated_at = NOW()
    WHERE id = order_id
    RETURNING data INTO updated_order_data;

    -- Save the change to orders_history by inserting the updated order row
    INSERT INTO eshop.orders_history (
        "order",
        state,
        price,
        data,
        created_at
    )
    VALUES (
        order_id,
        'storno',
        0,
        updated_order_data,
        NOW()
    );

    -- The full transition owns the durable automatic commitment for every caller.
    SELECT * INTO v_occasion FROM public.occasions WHERE id=v_order.occasion;
    IF p_notify AND position('@' in v_order.data->>'email')>0
      AND length(v_order.data->>'email')<=320 THEN
      v_notice:=public.enqueue_order_email('TICKET_ORDER_STORNO',
        jsonb_build_object('order_id',order_id),v_occasion.organization,
        v_occasion.id,v_occasion.unit);
    END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.cancel_product_price_change(p_product_id bigint, p_change_id bigint, p_expected_revision bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_occasion bigint; v_change eshop.planned_changes%ROWTYPE;
BEGIN
  SELECT pt.occasion INTO STRICT v_occasion FROM eshop.products p JOIN eshop.product_types pt
    ON pt.id=p.product_type WHERE p.id=p_product_id FOR UPDATE OF p;
  IF auth.uid() IS NULL OR NOT EXISTS (SELECT 1 FROM public.occasions o JOIN public.user_info ui
    ON ui.organization=o.organization WHERE o.id=v_occasion AND ui.id=auth.uid()) THEN
    RAISE insufficient_privilege USING MESSAGE='ORDER_EDITOR_REQUIRED'; END IF;
  PERFORM public.check_is_editor_order_on_occasion(v_occasion);
  SELECT * INTO v_change FROM eshop.planned_changes WHERE id=p_change_id FOR UPDATE;
  IF NOT FOUND OR v_change.subject_id<>p_product_id OR v_change.change_type<>'products.price'
    OR v_change.applied OR v_change.revision IS DISTINCT FROM p_expected_revision THEN
    RAISE serialization_failure USING MESSAGE='PRICE_CHANGE_CONFLICT'; END IF;
  DELETE FROM eshop.planned_changes WHERE id=p_change_id;
END; $function$

CREATE OR REPLACE FUNCTION public.cancel_product_price_wave(p_wave_id bigint, p_expected_revision bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_wave eshop.product_price_waves%ROWTYPE;
BEGIN
  SELECT * INTO STRICT v_wave FROM eshop.product_price_waves WHERE id=p_wave_id FOR UPDATE;
  PERFORM public.check_product_wave_editor(v_wave.occasion);
  IF v_wave.revision IS DISTINCT FROM p_expected_revision THEN RAISE serialization_failure USING MESSAGE='PRICE_CHANGE_CONFLICT'; END IF;
  PERFORM 1 FROM eshop.products WHERE id IN(SELECT subject_id FROM eshop.planned_changes
    WHERE wave_id=p_wave_id AND NOT applied) ORDER BY id FOR UPDATE;
  DELETE FROM eshop.planned_changes WHERE wave_id=p_wave_id AND NOT applied;
  DELETE FROM eshop.product_price_waves WHERE id=p_wave_id;
END; $function$

CREATE OR REPLACE FUNCTION public.cancel_reception_registration_v1(p_occasion bigint, p_user uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_r public.reception_registrations%rowtype; v_actor uuid:=auth.uid(); v_impacts jsonb;
BEGIN
  PERFORM public.lock_activity_aggregate_internal_v1(p_occasion);
  SELECT * INTO v_r FROM public.reception_registrations WHERE occasion=p_occasion AND "user"=p_user FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('code',404,'message','registration_unavailable'); END IF;
  IF NOT public.get_can_use_reception(p_occasion) OR NOT (public.get_is_manager_on_occasion(p_occasion) OR public.get_is_admin_on_occasion(p_occasion) OR (v_r.created_by=v_actor AND (v_r.status='cancelled' OR v_r.created_at>now()-interval '30 minutes'))) THEN
    RETURN jsonb_build_object('code',403,'message','registration_unavailable'); END IF;
  IF v_r.status='cancelled' THEN RETURN jsonb_build_object('code',200,'status',CASE WHEN v_r.auth_revoked_at IS NULL THEN 'domain_blocked_auth_revocation_pending' ELSE 'cancelled' END,'targetUser',p_user); END IF;
  IF NOT public.reception_rate_limit_v1('cancel') THEN RETURN jsonb_build_object('code',429,'message','rate_limited'); END IF;
  UPDATE public.reception_registrations SET status='cancelled',cancelled_by=v_actor,cancelled_at=now() WHERE occasion=p_occasion AND "user"=p_user;
  v_impacts:=public.remove_occasion_user_domain_internal_v1(p_occasion,p_user);
  INSERT INTO public.client_sync_private_scopes(component,occasion,user_id,source_revision)
  SELECT x->>'component',p_occasion,(x->>'userId')::uuid,1 FROM jsonb_array_elements(v_impacts) x ORDER BY x->>'component',x->>'userId'
  ON CONFLICT(component,occasion,user_id) DO UPDATE SET source_revision=public.client_sync_private_scopes.source_revision+1,updated_at=clock_timestamp();
  RETURN jsonb_build_object('code',200,'status','domain_blocked_auth_revocation_pending','targetUser',p_user);
END $function$

CREATE OR REPLACE FUNCTION public.canonical_payment_reference_account_internal(p_account text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE account text:=upper(regexp_replace(coalesce(p_account,''),'[[:space:]]','','g'));
 parts text[]; bban text; digits text; checksum integer;
BEGIN
 parts:=regexp_match(account,'^(?:([0-9]{1,6})-)?([0-9]{1,10})/([0-9]{4})$');
 IF parts IS NOT NULL THEN
  bban:=parts[3]||lpad(coalesce(parts[1],'0'),6,'0')||lpad(parts[2],10,'0');
  checksum:=98-mod((bban||'123500')::numeric,97)::integer;
  account:='CZ'||lpad(checksum::text,2,'0')||bban;
 END IF;
 IF account='' OR NOT public.is_valid_iban(account) THEN RAISE EXCEPTION 'PAYMENT_REFERENCE_ACCOUNT_INVALID'; END IF;
 RETURN account;
END $function$

CREATE OR REPLACE FUNCTION public.charge_notification_intent_v1(p_occasion bigint, p_actor uuid, p_to jsonb, p_heading text, p_content text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE o public.occasions; policy jsonb; cap bigint; targets bigint; recipients jsonb;
BEGIN
 SELECT * INTO STRICT o FROM public.occasions WHERE id=p_occasion;
 policy:=public.abuse_effective_rules_v1('push.delivery',o.unit,o.organization);
 SELECT (r->>'base_limit')::bigint INTO cap FROM jsonb_array_elements(policy->'rules') r WHERE r->>'rule_key'='push.delivery.targets';
 IF cap IS NULL THEN RAISE configuration_limit_exceeded USING MESSAGE='abuse_policy_missing'; END IF;
 IF p_to IS NOT NULL AND p_to<>'null'::jsonb THEN
  recipients:=CASE jsonb_typeof(p_to) WHEN 'array' THEN p_to WHEN 'string' THEN jsonb_build_array(p_to) ELSE NULL END;
  IF recipients IS NULL OR jsonb_array_length(recipients)=0 OR jsonb_array_length(recipients)>cap THEN RAISE invalid_parameter_value USING MESSAGE='invalid notification recipients'; END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements_text(recipients) r WHERE NOT EXISTS(SELECT 1 FROM public.occasion_users ou WHERE ou.occasion=o.id AND ou."user"::text=r)) THEN
   RAISE insufficient_privilege USING MESSAGE='notification recipient outside occasion'; END IF;
  SELECT count(DISTINCT r) INTO targets FROM jsonb_array_elements_text(recipients) r;
 ELSE
  SELECT count(*) INTO targets FROM (SELECT 1 FROM public.occasion_users WHERE occasion=o.id LIMIT cap+1) audience;
 END IF;
 PERFORM public.abuse_charge_v1(policy,jsonb_build_object('actor',p_actor,'unit',o.unit,'organization',o.organization,'global','all'),
  jsonb_build_object('push.targets.unit.day',targets,'push.targets.organization.day',targets,'push.targets.global.day',targets,
   'push.delivery.targets',targets,'push.payload.bytes',octet_length(jsonb_build_object('heading',p_heading,'content',p_content,'to',p_to)::text),'push.delivery.age.seconds',0));
END $function$

CREATE OR REPLACE FUNCTION public.check_access_to_occasion(oc bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
    exists_on_occasion boolean;
BEGIN
    -- If the occasion is closed, check if the user exists on the occasion
    IF EXISTS (SELECT 1 FROM public.occasions WHERE id = oc AND NOT is_open) THEN
        -- Use the existing function to check if the user exists on the occasion
        SELECT get_exists_on_occasion(oc) INTO exists_on_occasion;

        -- If the user does not exist on the occasion, raise an exception
        IF NOT exists_on_occasion THEN
            RAISE EXCEPTION 'User is not allowed to access this occasion as it is closed.';
        END IF;
    END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.check_blueprint_image_resource_internal(p_layout jsonb, p_occasion bigint)
 RETURNS void
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE b jsonb:=p_layout->'background'; a public.blueprint_image_assets; field text; value jsonb;
BEGIN
 IF b IS NULL OR b='null'::jsonb THEN RETURN; END IF;
 IF jsonb_typeof(b)<>'object' OR EXISTS(SELECT 1 FROM jsonb_object_keys(b) key WHERE key NOT IN ('assetRef','hash','x','y','rotation','width','height','scale','opacity','crop')) THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_BACKGROUND'; END IF;
 SELECT * INTO a FROM public.blueprint_image_assets WHERE occasion=p_occasion AND asset_ref=b->>'assetRef' AND organization=(SELECT organization FROM public.occasions WHERE id=p_occasion) AND state='ready';
 IF NOT FOUND THEN RAISE check_violation USING MESSAGE='BLUEPRINT_ASSET_RESOURCE_NOT_READY'; END IF;
 IF b->>'hash' IS DISTINCT FROM a.hash OR (b->>'width')::numeric IS DISTINCT FROM a.width::numeric OR (b->>'height')::numeric IS DISTINCT FROM a.height::numeric THEN RAISE check_violation USING MESSAGE='BLUEPRINT_ASSET_MANIFEST_MISMATCH'; END IF;
 FOREACH field IN ARRAY ARRAY['x','y','rotation','width','height','scale'] LOOP
  value:=b->field;
  IF jsonb_typeof(value) IS DISTINCT FROM 'number' OR abs(value::numeric)>1000000000 OR field IN ('width','height','scale') AND value::numeric<=0 THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_BACKGROUND'; END IF;
 END LOOP;
 IF b ? 'opacity' AND (jsonb_typeof(b->'opacity')<>'number' OR (b->>'opacity')::numeric NOT BETWEEN 0 AND 1) THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_BACKGROUND'; END IF;
 IF jsonb_typeof(b->'crop') IS DISTINCT FROM 'object' OR EXISTS(SELECT 1 FROM jsonb_object_keys(b->'crop') key WHERE key NOT IN ('x','y','width','height')) THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_BACKGROUND_CROP'; END IF;
 FOREACH field IN ARRAY ARRAY['x','y','width','height'] LOOP
  value:=b->'crop'->field;
  IF jsonb_typeof(value) IS DISTINCT FROM 'number' OR value::numeric NOT BETWEEN 0 AND 1 OR field IN ('width','height') AND value::numeric<=0 THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_BACKGROUND_CROP'; END IF;
 END LOOP;
 IF (b#>>'{crop,x}')::numeric+(b#>>'{crop,width}')::numeric>1 OR (b#>>'{crop,y}')::numeric+(b#>>'{crop,height}')::numeric>1 THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_BACKGROUND_CROP'; END IF;
END $function$

CREATE OR REPLACE FUNCTION public.check_companion_relation_invariants_v1(p_occasion bigint, p_owner uuid, p_companion uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_policy jsonb; v_count bigint;
BEGIN
  IF p_owner IS NULL OR p_companion IS NULL OR p_owner=p_companion THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid companion relation';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(
    'companion-member:'||p_occasion::text||':'||least(p_owner::text,p_companion::text),0));
  PERFORM pg_advisory_xact_lock(hashtextextended(
    'companion-member:'||p_occasion::text||':'||greatest(p_owner::text,p_companion::text),0));
  IF NOT EXISTS (SELECT 1 FROM public.occasion_users ou
      WHERE ou.occasion=p_occasion AND ou."user"=p_owner)
    OR NOT EXISTS (SELECT 1 FROM public.occasion_users ou
      WHERE ou.occasion=p_occasion AND ou."user"=p_companion) THEN
    RAISE invalid_parameter_value USING MESSAGE='both users must be occasion participants';
  END IF;
  IF EXISTS (SELECT 1 FROM public.user_companions uc WHERE uc.occasion=p_occasion
      AND (uc.companion=p_owner OR uc."user"=p_companion)) THEN
    RAISE check_violation USING MESSAGE='companion relations cannot be chained';
  END IF;
  IF EXISTS (SELECT 1 FROM public.user_companions uc WHERE uc.occasion=p_occasion
      AND uc.companion=p_companion AND uc."user"<>p_owner) THEN
    RAISE unique_violation USING MESSAGE='participant already has an owner';
  END IF;
  v_policy:=public.get_companion_feature_policy_v1(p_occasion);
  SELECT count(*) INTO v_count FROM public.user_companions uc
    WHERE uc.occasion=p_occasion AND uc."user"=p_owner;
  IF v_count >= (v_policy->>'max_companions')::integer
    AND NOT EXISTS (SELECT 1 FROM public.user_companions uc
      WHERE uc.occasion=p_occasion AND uc."user"=p_owner
        AND uc.companion=p_companion) THEN
    RAISE check_violation USING MESSAGE='maximum companions reached';
  END IF;
END $function$

CREATE OR REPLACE FUNCTION public.check_form_capacity_settings_internal(p_form bigint, p_input jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE f public.forms; c jsonb; n integer; enabled boolean; bp bigint;
BEGIN
 SELECT * INTO STRICT f FROM public.forms WHERE id=p_form FOR UPDATE;
 c:=public.get_form_capacity_snapshot_internal(p_form);
 n:=CASE WHEN p_input ? 'participant_capacity' THEN (p_input->>'participant_capacity')::integer ELSE f.participant_capacity END;
 enabled:=CASE WHEN p_input ? 'waitlist_enabled' THEN (p_input->>'waitlist_enabled')::boolean ELSE f.waitlist_enabled END;
 bp:=CASE WHEN p_input ? 'blueprint' THEN nullif(p_input->>'blueprint','')::bigint ELSE f.blueprint END;
 -- A retained blueprint is inactive when the occasion feature is disabled.
 IF NOT EXISTS (SELECT 1 FROM public.occasions o WHERE o.id=f.occasion
  AND jsonb_path_exists(o.features, '$[*] ? (@.code == "blueprint" && @.is_enabled == true)')) THEN bp:=NULL; END IF;
 IF n IS NOT NULL AND n<(c->>'occupiedPeople')::bigint+(c->>'offeredPlaces')::bigint+coalesce((c->>'heldForWaiting')::bigint,0) THEN
  RAISE EXCEPTION '%',jsonb_build_object('code',409,'errorCode','CAPACITY_BELOW_COMMITTED','capacity',c)::text; END IF;
 IF ((NOT enabled) OR n IS NULL OR bp IS NOT NULL) AND
 ((c->>'waitingPeople')::bigint>0 OR (c->>'offeredPlaces')::bigint>0) THEN
  RAISE EXCEPTION '%',jsonb_build_object('code',409,'errorCode','WAITLIST_HAS_ACTIVE_ENTRIES','capacity',c)::text; END IF;
 IF bp IS NOT NULL AND (n IS NOT NULL OR enabled) THEN
  RAISE EXCEPTION '%',jsonb_build_object('code',409,'errorCode','BLUEPRINT_CONFLICT')::text; END IF;
END $function$

