CREATE OR REPLACE FUNCTION public.check_occasion_link(link_txt text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
    occasionId bigint;
    is_open_bool BOOLEAN;
    occasion_user occasion_users%rowtype;
    is_admin_bool BOOLEAN;
BEGIN
    -- If no link is provided, get the first open and non-hidden occasion's link
    IF link_txt = '' THEN
        SELECT link INTO link_txt FROM occasions WHERE occasions.is_open = true AND occasions.is_hidden = false LIMIT 1;
    END IF;

    -- Get the occasion ID for the provided link
    SELECT id INTO occasionId FROM occasions WHERE occasions.id = public.resolve_occasion_link_internal(link_txt) AND occasions.is_hidden = false;

    -- If the occasion ID is not found, return a 404 response
    IF occasionId IS NULL THEN
        RETURN json_build_object('code', 404);
    END IF;

    -- Get the is_open status for the occasion
    SELECT is_open INTO is_open_bool FROM occasions WHERE occasions.id = public.resolve_occasion_link_internal(link_txt);

    -- Get the occasion user record if it exists
    SELECT * INTO occasion_user FROM occasion_users WHERE occasion = occasionId AND "user" = auth.uid();

    -- Check if the current user is an admin on the occasion
    is_admin_bool := get_is_admin_on_occasion(occasionId);

    -- If the occasion is not open, enforce access restrictions
    IF is_open_bool = FALSE THEN
        IF auth.uid() IS NULL THEN
            RETURN json_build_object('code', 403);
        END IF;
        IF occasion_user IS NULL AND NOT is_admin_bool THEN
            RETURN json_build_object('code', 403);
        END IF;
        RETURN json_build_object(
            'code', 200,
            'is_admin', is_admin_bool,
            'occasion_user', COALESCE(row_to_json(occasion_user)::jsonb, NULL),
            'occasion', occasionId
        );
    END IF;

    -- If the occasion user record is not found and the user is not an admin, return basic occasion data
    IF occasion_user IS NULL THEN
        RETURN json_build_object(
            'code', 200,
            'is_admin', is_admin_bool,
            'link', link_txt,
            'occasion', occasionId
        );
    END IF;

    -- Return full occasion data including the user and admin status
    RETURN json_build_object(
        'code', 200,
        'is_admin', is_admin_bool,
        'occasion_user', row_to_json(occasion_user)::jsonb,
        'link', link_txt,
        'occasion', occasionId
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.check_order_is_mutable(p_order bigint)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_state text;
BEGIN
  PERFORM public.check_occasion_writable((SELECT occasion FROM eshop.orders WHERE id=p_order));
  PERFORM public.lock_order_capacity_scope_internal(ARRAY[p_order]);
  SELECT state INTO v_state FROM eshop.orders WHERE id=p_order FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'ORDER_NOT_FOUND' USING ERRCODE='P0002'; END IF;
  IF v_state IN ('waitlisted','preparing_payment') THEN
    RAISE EXCEPTION 'ORDER_ACTION_NOT_ALLOWED' USING ERRCODE='55000';
  END IF;
  IF v_state='storno' THEN
    RAISE EXCEPTION 'ORDER_CANCELLED: Cancelled orders are read-only' USING ERRCODE='55000';
  END IF;
END $function$

CREATE OR REPLACE FUNCTION public.check_request_secret(p_secret text)
 RETURNS boolean
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_count integer;
BEGIN
  -- Clean up expired secrets first
  DELETE FROM public.request_secrets
  WHERE created_at < (now() - (interval '1 second' * ttl_seconds));

  SELECT COUNT(*) INTO v_count
  FROM public.request_secrets
  WHERE secret = p_secret;

  RETURN v_count > 0;
END;
$function$

CREATE OR REPLACE FUNCTION public.check_scan_attempt_budget_v1(p_occasion bigint DEFAULT NULL::bigint)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE policies jsonb; policy jsonb; family text; scopes jsonb;
BEGIN
 IF auth.uid() IS NOT NULL AND p_occasion IS NOT NULL AND public.get_is_editor_order_view_on_occasion(p_occasion) THEN RETURN true; END IF;
 policies:=public.abuse_policy_bundle_v1(ARRAY['scan.invalid.global','scan.invalid.source'],NULL,NULL);
 scopes:=jsonb_build_object('global','all','recipient',public.abuse_request_source_v1());
 FOREACH family IN ARRAY ARRAY['scan.invalid.global','scan.invalid.source'] LOOP
  policy:=policies->family;
  -- A zero-cost check must deny at the limit, not only after one more guess.
  policy:=jsonb_set(policy,'{rules}',(SELECT jsonb_agg(jsonb_set(r,'{base_limit}',to_jsonb((r->>'base_limit')::bigint-1))) FROM jsonb_array_elements(policy->'rules') r));
  IF NOT public.abuse_charge_v1(policy,scopes,(SELECT jsonb_object_agg(r->>'rule_key',0) FROM jsonb_array_elements(policy->'rules') r),true) THEN RETURN false; END IF;
 END LOOP;
 RETURN true;
END $function$

CREATE OR REPLACE FUNCTION public.check_ticket_is_mutable(p_ticket bigint)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_order bigint; v_state text;
BEGIN
  FOR v_order IN SELECT DISTINCT opt."order" FROM eshop.order_product_ticket opt
    WHERE opt.ticket=p_ticket ORDER BY opt."order" LOOP
    PERFORM public.check_order_is_mutable(v_order);
  END LOOP;
  SELECT state INTO v_state FROM eshop.tickets WHERE id=p_ticket FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'TICKET_NOT_FOUND' USING ERRCODE='P0002'; END IF;
  IF v_state='waitlisted' THEN RAISE EXCEPTION 'TICKET_ACTION_NOT_ALLOWED' USING ERRCODE='55000'; END IF;
  IF v_state='storno' THEN
    RAISE EXCEPTION 'TICKET_CANCELLED: Cancelled tickets are read-only' USING ERRCODE='55000';
  END IF;
END $function$

