CREATE OR REPLACE FUNCTION public.complete_client_mutation_applied_v1(p_command_id uuid, p_occasion bigint, p_source text, p_change_class text, p_items jsonb, p_public_components text[], p_private_impacts jsonb, p_dirty_keys jsonb, p_data jsonb, p_immediate_public_components text[] DEFAULT '{}'::text[], p_extra_replacements jsonb DEFAULT '[]'::jsonb, p_actor_kind text DEFAULT 'user'::text, p_reason text DEFAULT NULL::text, p_immediate_private_replacements jsonb DEFAULT '[]'::jsonb, p_unit_catalog_fanout_units bigint[] DEFAULT '{}'::bigint[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_commit jsonb;
  v_component text;
  v_component_data jsonb;
  v_private_replacement jsonb;
  v_private_revision bigint;
  v_replacements jsonb := COALESCE(p_extra_replacements, '[]'::jsonb);
  v_response jsonb;
  v_fanout_unit bigint;
BEGIN
  IF p_data IS NULL OR octet_length(p_data::text) > 4194304
    OR jsonb_typeof(v_replacements) <> 'array'
    OR jsonb_typeof(COALESCE(p_immediate_private_replacements, '[]')) <> 'array'
    OR NOT COALESCE(p_immediate_public_components, '{}')
      <@ COALESCE(p_public_components, '{}')
  THEN
    RAISE invalid_parameter_value USING MESSAGE = 'invalid applied mutation result';
  END IF;

  v_commit := public.record_client_sync_commit_v1(
    p_occasion,
    p_source,
    p_change_class,
    p_items,
    p_public_components,
    p_private_impacts,
    p_dirty_keys,
    p_actor_kind,
    p_reason
  );
  FOR v_fanout_unit IN
    SELECT DISTINCT id
    FROM unnest(COALESCE(p_unit_catalog_fanout_units, '{}')) id
  LOOP
    PERFORM public.fanout_unit_catalog_v1(
      (v_commit->>'commitId')::uuid,
      v_fanout_unit
    );
  END LOOP;

  FOREACH v_component IN ARRAY COALESCE(p_immediate_public_components, '{}')
  LOOP
    v_component_data := public.get_public_client_sync_component_core_v1(
      v_component,
      'occasion',
      p_occasion
    );
    v_replacements := v_replacements || jsonb_build_array(jsonb_build_object(
      'component', v_component,
      'revision', v_component_data->'revision',
      'payload', v_component_data->'payload'
    ));
  END LOOP;

  FOR v_private_replacement IN
    SELECT value
    FROM jsonb_array_elements(COALESCE(p_immediate_private_replacements, '[]'))
  LOOP
    IF v_private_replacement->>'component' NOT LIKE 'private\_%'
      OR NOT EXISTS (
        SELECT 1
        FROM jsonb_array_elements(COALESCE(p_private_impacts, '[]')) impact
        WHERE impact->>'component' = v_private_replacement->>'component'
          AND impact->>'userId' = v_private_replacement->>'userId'
      )
    THEN
      RAISE invalid_parameter_value
        USING MESSAGE = 'invalid immediate private replacement';
    END IF;
    SELECT s.source_revision INTO STRICT v_private_revision
    FROM public.client_sync_private_scopes s
    WHERE s.component = v_private_replacement->>'component'
      AND s.occasion = p_occasion
      AND s.user_id = (v_private_replacement->>'userId')::uuid;
    v_replacements := v_replacements || jsonb_build_array(jsonb_build_object(
      'component', v_private_replacement->>'component',
      'revision', v_private_revision,
      'payload', v_private_replacement->'payload'
    ));
  END LOOP;

  v_response := jsonb_build_object(
    'status', 'applied',
    'code', 200,
    'data', p_data,
    'mutation', jsonb_build_object(
      'commandId', p_command_id,
      'receiptId', p_command_id,
      'commitId', v_commit->>'commitId',
      'replayed', false,
      'occurredAt', v_commit->>'occurredAt'
    ),
    'sync', jsonb_build_object('replacements', v_replacements)
  );
  RETURN public.finish_client_mutation_v1(
    p_command_id,
    v_response,
    (v_commit->>'commitId')::uuid
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.complete_client_sync_publication_classes_v1(p_scope_type text, p_scope_id bigint, p_release_revision bigint, p_manifest jsonb, p_manifest_url text, p_manifest_sha256 text, p_manifest_bytes bigint, p_live jsonb, p_head_json jsonb, p_head_etag text, p_catalog_claim_tokens uuid[], p_live_claim_tokens uuid[])
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_head public.client_sync_public_heads%ROWTYPE; v_component record;
  v_next_catalog bigint := (p_head_json#>>'{catalog,revision}')::bigint;
  v_next_live bigint := (p_head_json#>>'{live,revision}')::bigint;
  v_content_revision bigint; v_notification uuid;
BEGIN
  PERFORM public.require_client_sync_service_role_v1();
  SELECT * INTO v_head FROM public.client_sync_public_heads
    WHERE scope_type=p_scope_type AND scope_id=p_scope_id FOR UPDATE;
  IF FOUND AND (v_next_catalog < COALESCE(v_head.release_revision,-1)
      OR COALESCE(v_next_live,-1) < COALESCE(v_head.live_revision,-1)
      OR (v_next_catalog = v_head.release_revision
          AND v_next_live IS NOT DISTINCT FROM v_head.live_revision
          AND v_head.head_json IS DISTINCT FROM p_head_json)) THEN
    RETURN false;
  END IF;
  IF p_release_revision IS NOT NULL THEN
    IF p_manifest IS NULL OR p_manifest_sha256 IS NULL
       OR p_release_revision <> v_next_catalog THEN RAISE EXCEPTION 'invalid catalog completion'; END IF;
    INSERT INTO public.client_sync_release_manifests
      (scope_type,scope_id,release_revision,manifest,artifact_url,sha256,byte_size)
    VALUES (p_scope_type,p_scope_id,p_release_revision,p_manifest,p_manifest_url,
      p_manifest_sha256,p_manifest_bytes) ON CONFLICT DO NOTHING;
    FOR v_component IN SELECT key,value FROM jsonb_each(p_manifest->'components') LOOP
      INSERT INTO public.client_sync_publications
        (component,scope_type,scope_id,published_revision,media_type,artifact_url,sha256,byte_size)
      VALUES (v_component.key,p_scope_type,p_scope_id,
        (v_component.value->>'revision')::bigint,v_component.value->>'mediaType',
        v_component.value->>'url',v_component.value->>'sha256',(v_component.value->>'bytes')::bigint)
      ON CONFLICT DO NOTHING;
    END LOOP;
  END IF;
  IF p_live IS NOT NULL THEN
    INSERT INTO public.client_sync_publications
      (component,scope_type,scope_id,published_revision,media_type,artifact_url,sha256,byte_size)
    VALUES ('live_public',p_scope_type,p_scope_id,(p_live->>'revision')::bigint,
      p_live->>'mediaType',p_live->>'url',p_live->>'sha256',(p_live->>'bytes')::bigint)
    ON CONFLICT DO NOTHING;
  END IF;
  INSERT INTO public.client_sync_public_heads
    (scope_type,scope_id,release_revision,manifest_sha256,live_revision,live_sha256,head_etag,head_json)
  VALUES (p_scope_type,p_scope_id,v_next_catalog,p_head_json#>>'{catalog,sha256}',
    v_next_live,p_head_json#>>'{live,sha256}',p_head_etag,p_head_json)
  ON CONFLICT (scope_type,scope_id) DO UPDATE SET
    release_revision=EXCLUDED.release_revision,manifest_sha256=EXCLUDED.manifest_sha256,
    live_revision=EXCLUDED.live_revision,live_sha256=EXCLUDED.live_sha256,
    head_etag=EXCLUDED.head_etag,head_json=EXCLUDED.head_json,updated_at=now();

  -- R2 artifacts and the accepted public head already exist at this point.
  -- Moving ready rows into log_notifications is atomic with recording that head;
  -- explicit dispatch therefore cannot outrun content_catalog.
  v_content_revision:=(p_manifest#>>'{components,content_catalog,revision}')::bigint;
  IF p_scope_type='occasion' AND v_content_revision IS NOT NULL THEN
    FOR v_notification IN WITH ready AS (
      DELETE FROM public.news_notification_outbox q
      WHERE q.occasion=p_scope_id
        AND q.required_content_revision<=v_content_revision
      RETURNING q.*
    )
    INSERT INTO public.log_notifications
      (id,occasion,organization,user_id,"to",heading,content,data,created_at,abuse_admitted_at)
    SELECT r.id,r.occasion,r.organization,r.user_id,r."to",r.heading,r.content,
      r.data,r.created_at,r.abuse_admitted_at
    FROM ready r
    ON CONFLICT (id) DO NOTHING RETURNING id LOOP
      PERFORM public.dispatch_log_notification_v1(v_notification);
    END LOOP;
  END IF;

  DELETE FROM public.client_projection_dirty_keys
    WHERE claim_token=ANY(COALESCE(p_catalog_claim_tokens,'{}')) AND component<>'live_public';
  DELETE FROM public.client_projection_dirty_keys
    WHERE claim_token=ANY(COALESCE(p_live_claim_tokens,'{}')) AND component='live_public';
  RETURN true;
END; $function$

CREATE OR REPLACE FUNCTION public.complete_fakturoid_ticket_order_v1(p_order_id bigint, p_command_id uuid, p_variable_symbol bigint)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_state text;
  v_currency text;
  v_payment_id bigint;
  v_existing_vs bigint;
  v_occasion bigint;
  v_queue_id bigint;
  v_impacts jsonb;
BEGIN
  PERFORM public.require_client_sync_service_role_v1();
  PERFORM public.lock_order_capacity_scope_internal(ARRAY[p_order_id]);
  IF EXISTS(SELECT 1 FROM eshop.waitlist_acceptance_attempts WHERE target_order_id=p_order_id AND command_id=p_command_id AND state='aborted') THEN
    RAISE EXCEPTION 'Acceptance attempt aborted'; END IF;
  SELECT o.state,trim(o.currency_code),o.payment_info,o.occasion,pi.variable_symbol
  INTO v_state,v_currency,v_payment_id,v_occasion,v_existing_vs
  FROM eshop.orders o JOIN eshop.payment_info pi ON pi.id=o.payment_info
  WHERE o.id=p_order_id FOR UPDATE OF o,pi;
  IF v_state IS NULL OR p_command_id IS NULL OR p_variable_symbol NOT BETWEEN 1 AND 9999999999 THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid Fakturoid completion';
  END IF;
  IF v_state IN ('ordered','paid') THEN
    RETURN v_existing_vs;
  END IF;
  IF v_state<>'preparing_payment' THEN
    RAISE check_violation USING MESSAGE='Fakturoid order is not pending';
  END IF;
  SELECT q.id INTO v_queue_id FROM public.email_messages q
  WHERE q.code='TICKET_ORDER_CONFIRMATION'
    AND q.data->>'command_id'=p_command_id::text
    AND (q.data#>>'{ticket_order,order,id}')::bigint=p_order_id
    AND q.data->>'fakturoid_pending'='true'
  FOR UPDATE;
  IF v_queue_id IS NULL THEN
    RAISE check_violation USING MESSAGE='Fakturoid order confirmation claim missing';
  END IF;
  IF v_currency NOT IN ('CZK','EUR') OR v_existing_vs IS DISTINCT FROM p_variable_symbol THEN
    RAISE check_violation USING MESSAGE='Fakturoid symbol differs from application payment reference';
  END IF;
  UPDATE eshop.waitlist_acceptance_attempts SET state='completed',updated_at=clock_timestamp()
   WHERE target_order_id=p_order_id AND command_id=p_command_id AND state='preparing';
  UPDATE eshop.orders SET state='ordered',updated_at=now() WHERE id=p_order_id;
  UPDATE public.email_messages SET target_time=now(),workflow_state='pending',
    data=jsonb_set(data-'fakturoid_pending','{ticket_order,order,payment_info,variable_symbol}',to_jsonb(p_variable_symbol))
  WHERE id=v_queue_id;
  PERFORM public.wake_email_worker();
  SELECT coalesce(jsonb_agg(jsonb_build_object('component',component,
    'userId',ou."user")),'[]'::jsonb) INTO v_impacts
  FROM public.occasion_users ou CROSS JOIN unnest(
    ARRAY['private_profile','private_inventory']) component
  WHERE ou.occasion=v_occasion;
  PERFORM public.record_client_sync_commit_v1(v_occasion,
    'fakturoid.order.complete','inventory',jsonb_build_array(jsonb_build_object(
      'entityType','order','entityId',p_order_id,'operation','update',
      'safeLabel','Order payment ready','changedFields',
      jsonb_build_array('state','payment_info'))),'{}',v_impacts,'[]',
    'service',NULL);
  RETURN p_variable_symbol;
END;
$function$

CREATE OR REPLACE FUNCTION public.complete_profile_inventory_membership_mutation_v1(p_command_id uuid, p_occasion bigint, p_source text, p_items jsonb, p_before_users uuid[], p_data jsonb, p_actor_kind text DEFAULT 'user'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_after_users uuid[]; v_removed uuid[];
  v_impacts jsonb; v_replacements jsonb:='[]'::jsonb;
  v_public text[]:='{}'; v_dirty jsonb:='[]'::jsonb;
BEGIN
  SELECT COALESCE(array_agg(ou."user"),'{}'::uuid[]) INTO v_after_users
    FROM public.occasion_users ou WHERE ou.occasion=p_occasion;
  SELECT ARRAY(SELECT id FROM unnest(COALESCE(p_before_users,'{}')) id
    WHERE NOT id=ANY(v_after_users)) INTO v_removed;
  DELETE FROM public.client_sync_private_scopes s WHERE s.occasion=p_occasion
    AND s.user_id=ANY(v_removed);
  DELETE FROM public.client_aggregate_versions v
    WHERE v.aggregate_type='occasion_user' AND v.scope_type='occasion'
      AND v.scope_id=p_occasion AND v.aggregate_id=ANY(
        ARRAY(SELECT id::text FROM unnest(v_removed) id));
  INSERT INTO public.client_aggregate_versions
    (aggregate_type,scope_type,scope_id,aggregate_id,version)
  SELECT 'occasion_user','occasion',p_occasion,id::text,1
    FROM unnest(v_after_users) id
  ON CONFLICT (aggregate_type,scope_type,scope_id,aggregate_id) DO UPDATE
    SET version=public.client_aggregate_versions.version+1,
      updated_at=clock_timestamp();
  SELECT COALESCE(jsonb_agg(jsonb_build_object('component',component,
    'userId',id) ORDER BY id,component),'[]'::jsonb) INTO v_impacts
  FROM unnest(v_after_users) id CROSS JOIN unnest(
    ARRAY['private_profile','private_inventory']) component;
  IF cardinality(v_removed)>0 THEN
    v_public:=ARRAY['live_public'];
    SELECT COALESCE(jsonb_agg(jsonb_build_object('component','live_public',
      'entityId',e.id)),'[]'::jsonb) INTO v_dirty
      FROM public.events e WHERE e.occasion=p_occasion;
  END IF;
  IF v_actor IS NOT NULL AND v_actor=ANY(v_after_users) THEN
    v_replacements:=jsonb_build_array(
      jsonb_build_object('component','private_profile','userId',v_actor,
        'payload',public.get_private_profile_payload_v1(p_occasion,v_actor)),
      jsonb_build_object('component','private_inventory','userId',v_actor,
        'payload',public.get_user_inventory_for_occasion_v1(p_occasion)));
  END IF;
  IF p_source='profile.tickets.import' AND cardinality(v_removed)>0 THEN
    v_impacts:=v_impacts||COALESCE((SELECT jsonb_agg(jsonb_build_object('component','private_activity','userId',id) ORDER BY id) FROM unnest(v_after_users) id),'[]'::jsonb);
  END IF;
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    p_source,'inventory',p_items,v_public,v_impacts,v_dirty,p_data,
    '{}','[]',p_actor_kind,NULL,v_replacements);
END; $function$

CREATE OR REPLACE FUNCTION public.configure_bank_sync_health_monitor(p_organization_id bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_url text;
BEGIN
  PERFORM public.require_service_role();
  IF NOT EXISTS(SELECT 1 FROM public.organizations WHERE id=p_organization_id) THEN RAISE EXCEPTION 'ORGANIZATION_NOT_FOUND'; END IF;
  SELECT regexp_replace(worker_url,'/process-email-queue$','/bank-sync-reconcile') INTO v_url FROM public.email_capacity;
  IF v_url IS NULL OR v_url !~ '^https://[^/]+/functions/v1/bank-sync-reconcile$' THEN RAISE EXCEPTION 'BANK_SYNC_MONITOR_URL_REQUIRED'; END IF;
  PERFORM cron.schedule('festapp_bank_sync_health_'||p_organization_id,'*/5 * * * *',
    format('SELECT net.http_post(url:=%L,body:=jsonb_build_object(''requestSecret'',public.generate_request_secret(3600),''monitor_organization_id'',%s),timeout_milliseconds:=360000)',v_url,p_organization_id));
END;
$function$

CREATE OR REPLACE FUNCTION public.confirm_blueprint_order_change_client_sync_v1(p_spot_ids bigint[], p_input_data jsonb, p_command_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_occasion bigint; v_begin jsonb; v_hash text;
  v_result jsonb; v_before_users uuid[];
BEGIN
  PERFORM public.lock_blueprint_scope_internal(ARRAY(SELECT DISTINCT occasion FROM eshop.spots WHERE id=ANY(p_spot_ids)));
  SELECT min(s.occasion) INTO v_occasion FROM eshop.spots s
    WHERE s.id=ANY(p_spot_ids);
  IF v_actor IS NULL OR v_occasion IS NULL OR cardinality(p_spot_ids)=0
    OR (SELECT count(*) FROM eshop.spots s
      WHERE s.id=ANY(p_spot_ids) AND s.occasion=v_occasion)
      <>cardinality(ARRAY(SELECT DISTINCT id FROM unnest(p_spot_ids) id))
    OR NOT public.get_is_editor_order_on_occasion(v_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='order editor required'; END IF;
  IF public.payment_reference_scope_enabled_internal((SELECT id FROM public.forms WHERE occasion=v_occasion ORDER BY id LIMIT 1)) THEN
    RETURN jsonb_build_object('status','rejected','code',409,'data',jsonb_build_object('errorCode','ATOMIC_REPLACEMENT_REQUIRED')); END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'spots',p_spot_ids,'input',p_input_data)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,
    'inventory.order.prepare_replace',v_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN public.project_local_payment_reference_order_internal(v_begin->'response'); END IF;
  SELECT COALESCE(array_agg(ou."user"),'{}'::uuid[]) INTO v_before_users
    FROM public.occasion_users ou WHERE ou.occasion=v_occasion;
  v_result:=public.confirm_blueprint_order_change_internal_v1(
    p_spot_ids,p_input_data);
  IF COALESCE((v_result->>'success')::boolean,false) IS NOT TRUE THEN
    RETURN public.complete_client_mutation_outcome_v1(
      p_command_id,'rejected',400,v_result); END IF;
  RETURN public.complete_profile_inventory_membership_mutation_v1(
    p_command_id,v_occasion,'inventory.order.prepare_replace',
    jsonb_build_array(jsonb_build_object('entityType','order','entityId',NULL,
      'operation','update','safeLabel','Blueprint order replacement',
      'changedFields',jsonb_build_array('cancellations','allocations'))),
    v_before_users,v_result);
END; $function$

CREATE OR REPLACE FUNCTION public.confirm_blueprint_order_change_internal_v1(p_spot_ids bigint[], p_input_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_analysis JSONB;
  v_ticket_ids_to_cancel BIGINT[];
  v_occasion_id BIGINT;
  v_form_key UUID;
  v_ticket_payloads JSONB := '[]'::JSONB;
  v_order_details JSONB;
  v_new_spot_rec RECORD;
  v_email TEXT;
BEGIN
  PERFORM public.lock_blueprint_scope_internal(ARRAY(SELECT DISTINCT occasion FROM eshop.spots WHERE id=ANY(p_spot_ids)));
  PERFORM public.check_blueprint_selection_units_internal(p_spot_ids);
  SELECT occasion INTO v_occasion_id FROM eshop.spots WHERE id=p_spot_ids[1];
  IF NOT coalesce(public.get_is_editor_order_on_occasion(v_occasion_id),false) THEN RAISE insufficient_privilege USING MESSAGE='order editor required'; END IF;
  IF EXISTS(SELECT 1 FROM eshop.spots WHERE id=ANY(p_spot_ids) AND secret IS NOT NULL
    AND secret_expiration_time>clock_timestamp()
    AND secret IS DISTINCT FROM (p_input_data->>'secret')::uuid) THEN
    RAISE check_violation USING MESSAGE='BLUEPRINT_SEAT_PROTECTED'; END IF;
  -- Extract Email for validation
  v_email := p_input_data->>'email';

  IF v_email IS NULL OR v_email = '' THEN
      RAISE EXCEPTION 'Email is required in input data.';
  END IF;

  -- 1. Analyze impacts
  v_analysis := public.analyze_new_order_spots(p_spot_ids);

  -- 2. Extract Ticket IDs for Storno
  SELECT ARRAY_AGG((elem->>'ticket_id')::BIGINT)
  INTO v_ticket_ids_to_cancel
  FROM jsonb_array_elements(v_analysis->'conflicts') elem
  WHERE elem->>'ticket_id' IS NOT NULL;

  -- 3. Perform Storno (if any conflicts exist)
  IF v_ticket_ids_to_cancel IS NOT NULL AND array_length(v_ticket_ids_to_cancel, 1) > 0 THEN
      PERFORM public.storno_tickets_bulk_internal_v1(v_ticket_ids_to_cancel);
  END IF;

  -- 4. Clean up Secrets on selected spots
  UPDATE eshop.spots
  SET secret = NULL, secret_expiration_time = NULL
  WHERE id = ANY(p_spot_ids);

  -- 5. Prepare Data for New Order

  -- Get occasion ID
  SELECT occasion INTO v_occasion_id FROM eshop.spots WHERE id = p_spot_ids[1];

  -- Security Check: User must be editor
  IF NOT public.get_is_editor_order_on_occasion(v_occasion_id) THEN
      RAISE EXCEPTION 'Permission denied. User is not an editor for occasion %', v_occasion_id;
  END IF;

  -- Validation: All spots must be on same occasion
  PERFORM 1 FROM eshop.spots
  WHERE id = ANY(p_spot_ids) AND occasion != v_occasion_id;

  IF FOUND THEN
      RAISE EXCEPTION 'All selected spots must belong to the same occasion.';
  END IF;

  -- Find a suitable Form
  v_form_key := (v_analysis->'order_form'->>'key')::uuid;
  IF p_input_data->>'form_key' IS NOT NULL AND p_input_data->>'form_key' IS DISTINCT FROM v_form_key::text THEN
    RAISE EXCEPTION 'The active order form changed. Reopen the order.';
  END IF;

  IF v_form_key IS NULL OR NOT EXISTS(SELECT 1 FROM public.forms f WHERE f.key=v_form_key
    AND f.blueprint=(SELECT blueprint FROM eshop.spots WHERE id=p_spot_ids[1]))
    OR EXISTS(SELECT 1 FROM eshop.spots WHERE id=ANY(p_spot_ids) AND blueprint IS DISTINCT FROM (SELECT blueprint FROM eshop.spots WHERE id=p_spot_ids[1])) THEN
      RAISE EXCEPTION 'No open form found for this occasion to create the new order.';
  END IF;

  -- Build "ticket" array for the payload
  FOR v_new_spot_rec IN
      SELECT s.id, s.product
      FROM eshop.spots s
      WHERE s.id = ANY(p_spot_ids)
  LOOP
      v_ticket_payloads := v_ticket_payloads || JSONB_BUILD_OBJECT(
          'spot', v_new_spot_rec.id,
          'fields', coalesce(p_input_data->'ticket_fields'->v_new_spot_rec.id::text,'[]'::jsonb)
      );
  END LOOP;

  -- Construct payload for Edge Function
  -- We start with basic fields, then MERGE (||) the p_input_data
  -- This allows passing 'name', 'surname', 'note' in input_data automatically.
  v_order_details := JSONB_BUILD_OBJECT(
      'form', v_form_key,
      'ticket', v_ticket_payloads,
      'lang', 'cs'
  ) || (p_input_data - 'ticket_fields' - 'form_key' - 'form' - 'ticket');

  -- Return Success + Payload
  RETURN JSONB_BUILD_OBJECT(
      'success', true,
      'message', 'Storno performed. Ready to create new order.',
      'orderDetails', v_order_details
  );

EXCEPTION WHEN OTHERS THEN
  RETURN JSONB_BUILD_OBJECT('success', false, 'message', SQLERRM);
END;
$function$

CREATE OR REPLACE FUNCTION public.consume_qr_login_attempt_v1(p_occasion bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE accepted boolean; policy jsonb; cap bigint;
BEGIN
 PERFORM public.require_service_role();
 IF p_occasion IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.occasions WHERE id=p_occasion) THEN
  RETURN jsonb_build_object('allowed',false); END IF;
 policy:=public.abuse_effective_rules_v1(CASE WHEN p_occasion IS NULL THEN 'qr.global' ELSE 'qr.proof' END,NULL,NULL);
 accepted:=public.abuse_charge_v1(policy,jsonb_build_object('global','all','recipient',p_occasion::text),'{}',true);
 SELECT base_limit INTO cap FROM public.abuse_policy_rules WHERE rule_key='qr.payload.bytes';
 IF cap IS NULL THEN RAISE configuration_limit_exceeded USING MESSAGE='abuse_policy_missing'; END IF;
 RETURN jsonb_build_object('allowed',accepted,'maxBodyBytes',cap);
END $function$

CREATE OR REPLACE FUNCTION public.consume_sign_in_code_v1(p_email text, p_organization bigint, p_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_code public.sign_in_codes; v_user uuid; v_email text;
BEGIN
 PERFORM public.require_service_role();
 IF p_code IS NULL OR p_code !~ '^[0-9]{6}$' THEN RETURN NULL; END IF;
 SELECT ui.id,au.email INTO v_user,v_email FROM public.user_info ui JOIN auth.users au ON au.id=ui.id
 WHERE ui.organization=p_organization AND lower(ui.email_readonly)=lower(trim(p_email));
 IF v_user IS NULL THEN RETURN NULL; END IF;
 SELECT * INTO v_code FROM public.sign_in_codes WHERE user_id=v_user FOR UPDATE;
 IF NOT FOUND OR v_code.expires_at<=now() OR v_code.consumed_at IS NOT NULL OR v_code.attempts>=5 THEN RETURN NULL; END IF;
 -- Return rather than raise: failed attempts must commit.
 UPDATE public.sign_in_codes SET attempts=attempts+1 WHERE user_id=v_user;
 IF extensions.crypt(p_code,v_code.code_hash) IS DISTINCT FROM v_code.code_hash THEN RETURN NULL; END IF;
 UPDATE public.sign_in_codes SET consumed_at=now() WHERE user_id=v_user;
 RETURN jsonb_build_object('userId',v_user,'authEmail',v_email);
END $function$

CREATE OR REPLACE FUNCTION public.copy_blueprint_canonical_bitmap_resources_internal(p_source bigint, p_unit bigint, p_target bigint, p_layout jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE ref record; asset public.blueprint_image_assets; target_org bigint; target_unit bigint;
BEGIN
 SELECT organization,unit INTO target_org,target_unit FROM public.occasions WHERE id=p_target;
 IF target_org IS NULL OR (p_source IS NOT NULL AND (SELECT organization FROM public.occasions WHERE id=p_source) IS DISTINCT FROM target_org)
  OR (p_unit IS NOT NULL AND p_unit IS DISTINCT FROM target_unit) THEN RAISE insufficient_privilege USING MESSAGE='BLUEPRINT_INVALID_ASSET_COPY_SCOPE';END IF;
 FOR ref IN SELECT * FROM public.blueprint_layout_asset_refs_internal(p_layout) LOOP
  SELECT * INTO asset FROM public.blueprint_image_assets a WHERE a.organization=target_org AND a.asset_ref=ref.asset_ref AND a.hash=ref.hash AND a.state='ready'
   AND (a.occasion=p_source OR a.unit=p_unit OR a.occasion=p_target) ORDER BY a.occasion NULLS LAST LIMIT 1;
  IF NOT FOUND THEN RAISE check_violation USING MESSAGE='BLUEPRINT_IMAGE_RESOURCE_NOT_READY';END IF;
  INSERT INTO public.blueprint_image_assets(occasion,organization,asset_ref,hash,url,width,height,mime_type,byte_length,state)
  VALUES(p_target,target_org,asset.asset_ref,asset.hash,asset.url,asset.width,asset.height,asset.mime_type,asset.byte_length,asset.state)
  ON CONFLICT(occasion,asset_ref) WHERE occasion IS NOT NULL DO NOTHING;
 END LOOP;
 PERFORM public.check_blueprint_bitmap_resources_internal(p_layout,p_target);
END $function$

CREATE OR REPLACE FUNCTION public.copy_blueprint_image_resources_internal(p_source_occasion bigint, p_target_occasion bigint, p_layout jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
BEGIN
 IF p_layout->>'schemaVersion'='2' THEN
  PERFORM public.copy_blueprint_canonical_bitmap_resources_internal(p_source_occasion,NULL,p_target_occasion,p_layout);RETURN;
 END IF;
 IF p_source_occasion=p_target_occasion THEN
  PERFORM public.check_blueprint_image_resource_internal(p_layout,p_source_occasion);RETURN;
 END IF;
 PERFORM public.check_blueprint_image_resource_internal(p_layout,p_source_occasion);
 IF (SELECT organization FROM public.occasions WHERE id=p_source_occasion) IS DISTINCT FROM (SELECT organization FROM public.occasions WHERE id=p_target_occasion) THEN RAISE insufficient_privilege USING MESSAGE='same organization image copy required';END IF;
 INSERT INTO public.blueprint_image_assets(occasion,organization,asset_ref,hash,url,width,height,mime_type,byte_length,state)
 SELECT p_target_occasion,o.organization,a.asset_ref,a.hash,a.url,a.width,a.height,a.mime_type,a.byte_length,a.state
 FROM public.blueprint_image_assets a JOIN public.occasions o ON o.id=p_target_occasion
 WHERE a.occasion=p_source_occasion AND a.asset_ref=p_layout#>>'{background,assetRef}'
 ON CONFLICT(occasion,asset_ref) WHERE occasion IS NOT NULL DO NOTHING;
 PERFORM public.check_blueprint_image_resource_internal(p_layout,p_target_occasion);
END $function$

CREATE OR REPLACE FUNCTION public.copy_blueprint_text_resources_internal(p_source_occasion bigint, p_source_draft uuid, p_target bigint, p_layout jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE entry record;old jsonb;scope text:='occasion:'||p_target::text;
BEGIN
 IF (p_source_occasion IS NULL)=(p_source_draft IS NULL) THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_TEXT_COPY_SCOPE';END IF;
 FOR entry IN SELECT DISTINCT r.resource_id,r.resource_kind,r.payload FROM public.blueprint_text_resources r JOIN public.blueprint_layout_text_requests_internal(p_layout,true) q
  ON r.payload->'descriptor' @> q.descriptor AND r.payload->'descriptor'=q.descriptor
  WHERE r.scope_key=CASE WHEN p_source_occasion IS NOT NULL THEN 'occasion:'||p_source_occasion::text ELSE 'setup:'||p_source_draft::text END LOOP
  SELECT payload INTO old FROM public.blueprint_text_resources WHERE scope_key=scope AND resource_id=entry.resource_id;
  IF FOUND AND old IS DISTINCT FROM entry.payload THEN RAISE check_violation USING MESSAGE='BLUEPRINT_TEXT_RESOURCE_IMMUTABLE';END IF;
  INSERT INTO public.blueprint_text_resources(scope_key,occasion,resource_id,resource_kind,payload) VALUES(scope,p_target,entry.resource_id,entry.resource_kind,entry.payload) ON CONFLICT DO NOTHING;
 END LOOP;
END $function$

CREATE OR REPLACE FUNCTION public.copy_blueprint_unit_image_resources_internal(p_source_unit bigint, p_target_occasion bigint, p_layout jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE a public.blueprint_image_assets;
BEGIN
 IF p_layout->>'schemaVersion'='2' THEN
  PERFORM public.copy_blueprint_canonical_bitmap_resources_internal(NULL,p_source_unit,p_target_occasion,p_layout);RETURN;
 END IF;
 IF p_layout->'background' IS NULL OR p_layout->'background'='null'::jsonb THEN RETURN;END IF;
 SELECT * INTO a FROM public.blueprint_image_assets WHERE unit=p_source_unit AND asset_ref=p_layout#>>'{background,assetRef}' AND state='ready';
 IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM public.occasions o WHERE o.id=p_target_occasion AND o.unit=p_source_unit AND o.organization=a.organization) THEN RAISE check_violation USING MESSAGE='BLUEPRINT_ASSET_RESOURCE_NOT_READY';END IF;
 INSERT INTO public.blueprint_image_assets(occasion,organization,asset_ref,hash,url,width,height,mime_type,byte_length,state)
 VALUES(p_target_occasion,a.organization,a.asset_ref,a.hash,a.url,a.width,a.height,a.mime_type,a.byte_length,a.state)
 ON CONFLICT(occasion,asset_ref) WHERE occasion IS NOT NULL DO NOTHING;
 PERFORM public.check_blueprint_image_resource_internal(p_layout,p_target_occasion);
END $function$

CREATE OR REPLACE FUNCTION public.copy_empty_inventory_spot_internal(p_source bigint, p_occasion bigint, p_product bigint, p_blueprint bigint, p_context bigint, p_resource bigint, p_slot bigint)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE source eshop.spots; new_id bigint;
BEGIN
 SELECT * INTO source FROM eshop.spots WHERE id=p_source;
 IF source.id IS NULL OR NOT public.can_copy_occasion_source(source.occasion)
  OR (SELECT organization FROM public.occasions WHERE id=p_occasion) IS DISTINCT FROM
     (SELECT organization FROM public.occasions WHERE id=source.occasion) THEN RAISE insufficient_privilege USING MESSAGE='Inventory copy source denied'; END IF;
 IF public.get_is_editor_order_on_occasion(p_occasion) IS NOT TRUE AND public.get_is_manager_on_unit((SELECT unit FROM public.occasions WHERE id=p_occasion)) IS NOT TRUE THEN RAISE insufficient_privilege USING MESSAGE='Inventory copy target denied'; END IF;
 IF (p_product IS NOT NULL AND NOT EXISTS(SELECT 1 FROM eshop.products WHERE id=p_product AND occasion=p_occasion))
  OR (p_blueprint IS NOT NULL AND NOT EXISTS(SELECT 1 FROM eshop.blueprints WHERE id=p_blueprint AND occasion=p_occasion))
  OR (p_context IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.inventory_contexts c JOIN public.inventory_pools p ON p.id=c.inventory_pool WHERE c.id=p_context AND p.occasion=p_occasion))
  OR (p_resource IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.resources WHERE id=p_resource AND occasion=p_occasion))
  OR (p_slot IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.resource_slots WHERE id=p_slot AND resource=p_resource)) THEN RAISE check_violation USING MESSAGE='Inventory copy target denied'; END IF;
 INSERT INTO eshop.spots(created_at,occasion,product,updated_at,secret,secret_expiration_time,title,order_product_ticket,blueprint,inventory_context,resource,resource_slot)
 VALUES(now(),p_occasion,p_product,now(),NULL,NULL,source.title,NULL,p_blueprint,p_context,p_resource,p_slot) RETURNING id INTO new_id;
 RETURN new_id;
END $function$

CREATE OR REPLACE FUNCTION public.copy_inventory_resource_configuration_internal(p_source bigint, p_pool bigint, p_place bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE r public.resources; target public.inventory_pools; target_unit bigint; target_org bigint; new_id bigint; slot record; new_slot bigint; slots jsonb:='{}';
BEGIN
 SELECT * INTO r FROM public.resources WHERE id=p_source;
 SELECT * INTO target FROM public.inventory_pools WHERE id=p_pool;
 SELECT unit,organization INTO target_unit,target_org FROM public.occasions WHERE id=target.occasion;
 IF r.id IS NULL OR target.id IS NULL OR NOT public.can_copy_occasion_source(r.occasion)
  OR target_org IS DISTINCT FROM (SELECT organization FROM public.occasions WHERE id=r.occasion) THEN RAISE insufficient_privilege USING MESSAGE='Inventory copy source denied'; END IF;
 IF public.get_is_editor_order_on_occasion(target.occasion) IS NOT TRUE AND public.get_is_manager_on_unit(target_unit) IS NOT TRUE THEN RAISE insufficient_privilege USING MESSAGE='Inventory copy target denied'; END IF;
 IF p_place IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.places WHERE id=p_place AND occasion=target.occasion) THEN RAISE check_violation USING MESSAGE='Inventory copy place denied'; END IF;
 INSERT INTO public.resources(title,description,capacity,booking_rules,inventory_pool,place,occasion,unit,data)
 VALUES(r.title,r.description,r.capacity,r.booking_rules,p_pool,p_place,target.occasion,target_unit,r.data) RETURNING id INTO new_id;
 FOR slot IN SELECT * FROM public.resource_slots WHERE resource=r.id ORDER BY id LOOP
  INSERT INTO public.resource_slots(resource,title,data) VALUES(new_id,slot.title,slot.data) RETURNING id INTO new_slot;
  slots:=slots||jsonb_build_object(slot.id::text,new_slot);
 END LOOP;
 RETURN jsonb_build_object('resourceId',new_id,'slotMap',slots);
END $function$

CREATE OR REPLACE FUNCTION public.copy_setup_area_inventory_internal(p_areas jsonb, p_products jsonb, p_source bigint, p_target bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE area jsonb; pool public.inventory_pools; resource_row public.resources; bundle jsonb; mapped jsonb:='{}';
 old_ids bigint[]; new_ids bigint[]; new_pool bigint; index integer; old_product bigint; new_product bigint; links jsonb; copied jsonb; resource_map jsonb; slot_map jsonb; source_spot record;
BEGIN
 PERFORM public.check_is_editor_order_on_occasion(p_target);
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_areas) a WHERE a->>'inventoryContextId' IS NOT NULL) THEN
  IF p_source IS NULL OR NOT public.can_copy_occasion_source(p_source) THEN RAISE insufficient_privilege USING MESSAGE='Copy source denied'; END IF;
 END IF;
 FOR area IN SELECT value FROM jsonb_array_elements(p_areas) WHERE value->>'inventoryContextId' IS NOT NULL LOOP
  IF NOT EXISTS(SELECT 1 FROM eshop.product_inventory_contexts pic JOIN public.inventory_contexts ic ON ic.id=pic.inventory_context
   JOIN public.inventory_pools ip ON ip.id=ic.inventory_pool JOIN eshop.products product ON product.id=pic.product
   WHERE pic.product=(area->>'productId')::bigint AND ic.id=(area->>'inventoryContextId')::bigint AND ip.occasion=p_source AND product.occasion=p_source) THEN
   RAISE check_violation USING MESSAGE='BLUEPRINT_SETUP_FOREIGN_CONTEXT'; END IF;
 END LOOP;
 FOR pool IN SELECT DISTINCT ip.* FROM public.inventory_pools ip JOIN public.inventory_contexts ic ON ic.inventory_pool=ip.id
  JOIN eshop.product_inventory_contexts pic ON pic.inventory_context=ic.id WHERE ip.occasion=p_source AND pic.product IN
   (SELECT (a->>'productId')::bigint FROM jsonb_array_elements(p_areas) a WHERE a->>'inventoryContextId' IS NOT NULL) ORDER BY ip.id LOOP
  bundle:=public.update_inventory_pool_bundle(jsonb_build_object('pool',(to_jsonb(pool)-'id'-'created_at'-'updated_at')||jsonb_build_object('occasion',p_target),
   'contexts',(SELECT jsonb_agg(to_jsonb(ic)-'id'-'inventory_pool' ORDER BY ic.id) FROM public.inventory_contexts ic WHERE ic.inventory_pool=pool.id)));
  new_pool:=(bundle#>>'{pool,id}')::bigint;
  SELECT array_agg(id ORDER BY id) INTO old_ids FROM public.inventory_contexts WHERE inventory_pool=pool.id;
  SELECT array_agg(id ORDER BY id) INTO new_ids FROM public.inventory_contexts WHERE inventory_pool=new_pool;
  FOR index IN 1..coalesce(array_length(old_ids,1),0) LOOP mapped:=mapped||jsonb_build_object(old_ids[index]::text,new_ids[index]); END LOOP;
  resource_map:='{}';slot_map:='{}';
  FOR resource_row IN SELECT * FROM public.resources WHERE inventory_pool=pool.id ORDER BY id LOOP
   copied:=public.copy_inventory_resource_configuration_internal(resource_row.id,new_pool,NULL);
   resource_map:=resource_map||jsonb_build_object(resource_row.id::text,copied->'resourceId');
   slot_map:=slot_map||(copied->'slotMap');
  END LOOP;
  FOR source_spot IN SELECT * FROM eshop.spots WHERE inventory_context=ANY(old_ids) ORDER BY id LOOP
   PERFORM public.copy_empty_inventory_spot_internal(source_spot.id,p_target,NULL,NULL,
     (mapped->>source_spot.inventory_context::text)::bigint,
     (resource_map->>source_spot.resource::text)::bigint,
     (slot_map->>source_spot.resource_slot::text)::bigint);
  END LOOP;
 END LOOP;
 FOR old_product IN SELECT DISTINCT (a->>'productId')::bigint FROM jsonb_array_elements(p_areas) a WHERE a->>'inventoryContextId' IS NOT NULL LOOP
  new_product:=(p_products->>old_product::text)::bigint;
  IF new_product IS NULL THEN RAISE check_violation USING MESSAGE='BLUEPRINT_SETUP_PRODUCT_NOT_IN_FORM'; END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_object('inventory_context_id',(mapped->>inventory_context::text)::bigint,'quantity',quantity)),'[]') INTO links
   FROM eshop.product_inventory_contexts WHERE product=old_product;
  PERFORM public.update_product_inventory_contexts_internal_v1(new_product,links);
 END LOOP;
 RETURN mapped;
END $function$

CREATE OR REPLACE FUNCTION public.create_account_deletion_request(p_user uuid, p_organization bigint, p_token_hash text, p_expires_at timestamp with time zone, p_masked_email text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_previous public.account_deletion_requests%ROWTYPE;
  v_request public.account_deletion_requests%ROWTYPE;
BEGIN
  PERFORM public.require_service_role();
  IF p_token_hash !~ '^[0-9a-f]{64}$' OR p_expires_at <= clock_timestamp() THEN
    RAISE EXCEPTION 'account_deletion_invalid_request' USING ERRCODE = '22023';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.user_info ui
    WHERE ui.id = p_user AND ui.organization = p_organization
  ) THEN
    RAISE EXCEPTION 'account_deletion_account_not_found' USING ERRCODE = 'P0002';
  END IF;

  SELECT * INTO v_previous
  FROM public.account_deletion_requests
  WHERE user_id = p_user
    AND status IN ('email_pending','email_sent','deletion_pending')
  ORDER BY created_at DESC LIMIT 1 FOR UPDATE;

  IF v_previous.status = 'deletion_pending' THEN
    RAISE EXCEPTION 'account_deletion_already_pending' USING ERRCODE = '55000';
  END IF;
  IF v_previous.id IS NOT NULL AND v_previous.cooldown_until > clock_timestamp() THEN
    RAISE EXCEPTION 'account_deletion_cooldown' USING ERRCODE = 'P0001';
  END IF;
  IF v_previous.id IS NOT NULL THEN
    UPDATE public.account_deletion_requests
    SET status = 'revoked', token_hash = NULL, masked_email = NULL,
        updated_at = clock_timestamp()
    WHERE id = v_previous.id;
  END IF;

  INSERT INTO public.account_deletion_requests(
    user_id, organization, token_hash, masked_email, expires_at, cooldown_until
  ) VALUES (
    p_user, p_organization, p_token_hash, p_masked_email, p_expires_at,
    clock_timestamp() + interval '5 minutes'
  ) RETURNING * INTO v_request;

  RETURN jsonb_build_object('requestId', v_request.id, 'expiresAt', v_request.expires_at);
END;
$function$

CREATE OR REPLACE FUNCTION public.create_companion_client_sync_v1(p_occasion bigint, p_name text, p_command_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_organization bigint; v_begin jsonb; v_hash text;
  v_result jsonb; v_before uuid[]; v_companion uuid; v_replacements jsonb;
BEGIN
  IF v_actor IS NULL OR nullif(btrim(p_name),'') IS NULL
    OR octet_length(p_name)>512 THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid companion'; END IF;
  SELECT o.organization INTO v_organization FROM public.occasions o
    JOIN public.occasion_users ou ON ou.occasion=o.id AND ou."user"=v_actor
    WHERE o.id=p_occasion;
  IF v_organization IS NULL THEN
    RAISE insufficient_privilege USING MESSAGE='occasion participant required'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'occasion',p_occasion,'name',p_name)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'profile.companion.create',
    p_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(
    'companion-owner:'||v_actor::text||':'||p_occasion::text,0));
  SELECT COALESCE(array_agg(uc.companion),'{}'::uuid[]) INTO v_before
    FROM public.user_companions uc WHERE uc.occasion=p_occasion AND uc."user"=v_actor;
  v_result:=public.create_companion_in_organization_internal_v1(
    v_organization,p_occasion,v_actor,p_name);
  IF COALESCE((v_result->>'code')::integer,500)<>200 THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',
      CASE WHEN (v_result->>'code')::integer=403 THEN 403 ELSE 400 END,
      jsonb_build_object('companion',NULL,'domainCode',v_result->'code'));
  END IF;
  SELECT uc.companion INTO v_companion FROM public.user_companions uc
    WHERE uc.occasion=p_occasion AND uc."user"=v_actor AND NOT uc.companion=ANY(v_before)
    ORDER BY uc.companion LIMIT 1;
  IF v_companion IS NULL THEN
    RAISE EXCEPTION 'companion handler did not create a companion'; END IF;
  v_replacements:=jsonb_build_array(jsonb_build_object(
    'component','private_profile','userId',v_actor,
    'payload',public.get_private_profile_payload_v1(p_occasion,v_actor)));
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'profile.companion.create','profile',jsonb_build_array(jsonb_build_object(
      'entityType','companion','entityId',v_companion,'operation','insert',
      'safeLabel','Companion','changedFields',jsonb_build_array('name'))),
    '{}',jsonb_build_array(jsonb_build_object('component','private_profile',
      'userId',v_actor)),'[]',jsonb_build_object('companion',jsonb_build_object(
        'id',v_companion,'name',p_name,'event_ids','[]'::jsonb)),
    '{}','[]','user',NULL,v_replacements);
END; $function$

CREATE OR REPLACE FUNCTION public.create_companion_in_organization(oc bigint, c_name text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_result jsonb;
BEGIN
 IF auth.uid() IS NULL OR NOT EXISTS (SELECT 1 FROM public.occasion_users
  WHERE occasion=oc AND "user"=auth.uid()) THEN RETURN jsonb_build_object('code',403); END IF;
 v_result:=public.create_companion_client_sync_v1(oc,c_name,extensions.gen_random_uuid());
 RETURN jsonb_build_object('code',v_result->'code');
END $function$

CREATE OR REPLACE FUNCTION public.create_companion_in_organization_internal_v1(org bigint, oc bigint, usr uuid, c_name text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE new_companion uuid:=gen_random_uuid(); user_email text;
  companion_email text; v_policy jsonb;
BEGIN
  v_policy:=public.get_companion_feature_policy_v1(oc);
  IF auth.uid() IS NULL OR auth.uid()<>usr
    OR NOT EXISTS (SELECT 1 FROM public.occasion_users ou
      WHERE ou.occasion=oc AND ou."user"=usr)
    OR NOT COALESCE((v_policy->>'is_enabled')::boolean,false)
    OR NOT COALESCE((v_policy->>'allow_user_create')::boolean,true) THEN
    RETURN jsonb_build_object('code',403);
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(
    'companion-member:'||oc::text||':'||usr::text,0));
  IF (SELECT count(*) FROM public.user_companions uc
      WHERE uc.occasion=oc AND uc."user"=usr)
      >= (v_policy->>'max_companions')::integer THEN
    RETURN jsonb_build_object('code',403);
  END IF;
  SELECT ui.email_readonly INTO user_email FROM public.user_info ui WHERE ui.id=usr;
  companion_email:=user_email||'+'||btrim(c_name);
  INSERT INTO auth.users(instance_id,id,aud,role,email,encrypted_password,
    email_confirmed_at,raw_app_meta_data,created_at,updated_at,
    confirmation_token,email_change,email_change_token_new,recovery_token)
  VALUES('00000000-0000-0000-0000-000000000000',new_companion,
    'authenticated','authenticated',format('%s+%s',org,companion_email),'',now(),
    '{"provider":"email","providers":["email"]}',now(),now(),'','','','');
  INSERT INTO auth.identities(id,provider_id,user_id,identity_data,provider,
    created_at,updated_at)
  VALUES(gen_random_uuid(),new_companion,new_companion,
    jsonb_build_object('sub',new_companion,'email',format('%s+%s',org,companion_email)),
    'email',now(),now());
  INSERT INTO public.user_info(id,email_readonly,name,organization)
    VALUES(new_companion,companion_email,btrim(c_name),org);
  PERFORM public.add_user_to_occasion_internal_v1(oc,new_companion);
  -- The target membership now exists; serialize and recheck the complete graph.
  PERFORM public.check_companion_relation_invariants_v1(oc,usr,new_companion);
  INSERT INTO public.user_companions(occasion,"user",companion,origin,created_by)
    VALUES(oc,usr,new_companion,'self_created',usr);
  RETURN jsonb_build_object('code',200);
END $function$

CREATE OR REPLACE FUNCTION public.create_counseling_slots_client_sync_v1(p_speaker bigint, p_start timestamp with time zone, p_end timestamp with time zone, p_slot_minutes integer, p_place bigint, p_capacity integer, p_title text, p_break_minutes integer, p_command_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_response jsonb; v_commit uuid; v_occasion bigint; v_ids bigint[];
BEGIN
  v_response:=public.create_counseling_slots_domain_command_internal_v1(
    p_speaker,p_start,p_end,p_slot_minutes,p_place,p_capacity,p_title,
    p_break_minutes,p_command_id);
  IF v_response->>'status'='applied' THEN
    v_commit:=NULLIF(v_response#>>'{mutation,commitId}','')::uuid;
    SELECT s.occasion INTO v_occasion FROM public.speakers s WHERE s.id=p_speaker;
    SELECT COALESCE(array_agg(value::bigint ORDER BY value::bigint),'{}') INTO v_ids
    FROM jsonb_array_elements_text(COALESCE(v_response#>'{data,event_ids}','[]'));
    IF v_commit IS NOT NULL AND cardinality(v_ids)>0
       AND EXISTS (SELECT 1 FROM public.occasions o WHERE o.id=v_occasion AND NOT o.is_hidden) THEN
      PERFORM public.attach_event_live_projection_v1(v_commit,v_occasion,v_ids);
    END IF;
  END IF;
  RETURN v_response;
END; $function$

CREATE OR REPLACE FUNCTION public.create_counseling_slots_domain_command_internal_v1(p_speaker bigint, p_start timestamp with time zone, p_end timestamp with time zone, p_slot_minutes integer, p_place bigint, p_capacity integer, p_title text, p_break_minutes integer, p_command_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_occasion bigint; v_begin jsonb; v_hash text;
  v_result jsonb; v_ids bigint[];
BEGIN
  SELECT s.occasion INTO v_occasion FROM public.speakers s WHERE s.id=p_speaker;
  IF v_actor IS NULL OR v_occasion IS NULL
    OR NOT public.get_is_editor_on_occasion(v_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion editor required'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object('speaker',p_speaker,
    'start',p_start,'end',p_end,'slotMinutes',p_slot_minutes,'place',p_place,
    'capacity',p_capacity,'title',p_title,'breakMinutes',p_break_minutes)::text,
    'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'program.counseling.create',
    v_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  PERFORM 1 FROM public.speakers s WHERE s.id=p_speaker FOR UPDATE;
  PERFORM pg_catalog.pg_advisory_xact_lock(p_speaker);
  v_result:=public.create_counseling_slots_internal_v1(p_speaker,p_start,p_end,
    p_slot_minutes,p_place,p_capacity,p_title,p_break_minutes);
  IF COALESCE((v_result->>'code')::integer,500)<>200 THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',
      COALESCE((v_result->>'code')::integer,400),COALESCE(v_result->'data','{}')); END IF;
  SELECT COALESCE(array_agg(value::bigint),'{}'::bigint[]) INTO v_ids
    FROM jsonb_array_elements_text(v_result#>'{data,event_ids}');
  IF cardinality(v_ids)=0 THEN RETURN public.complete_client_mutation_outcome_v1(
    p_command_id,'unchanged',200,v_result->'data'); END IF;
  INSERT INTO public.client_aggregate_versions
    (aggregate_type,scope_type,scope_id,aggregate_id,version)
  SELECT 'event','occasion',v_occasion,id::text,1 FROM unnest(v_ids) id;
  RETURN public.complete_client_mutation_applied_v1(p_command_id,v_occasion,
    'program.counseling.create','program',jsonb_build_array(jsonb_build_object(
      'entityType','counseling_slot','entityId',NULL,'operation','insert',
      'safeLabel','Counseling slots','changedFields',jsonb_build_array('events','speakers'))),
    ARRAY['program_catalog','content_catalog'],'[]','[]',v_result->'data');
END; $function$

CREATE OR REPLACE FUNCTION public.create_counseling_slots_internal_v1(p_speaker bigint, p_start timestamp with time zone, p_end timestamp with time zone, p_slot_minutes integer, p_place bigint DEFAULT NULL::bigint, p_capacity integer DEFAULT 1, p_title text DEFAULT NULL::text, p_break_minutes integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
    v_occasion      BIGINT;
    v_speaker_title TEXT;
    v_type          TEXT;
    v_title         TEXT;
    v_slot_start    TIMESTAMPTZ;
    v_slot_end      TIMESTAMPTZ;
    v_event_id      BIGINT;
    v_ids           BIGINT[] := ARRAY[]::BIGINT[];
    v_count         INT := 0;
BEGIN
    SELECT occasion, title INTO v_occasion, v_speaker_title
    FROM public.speakers
    WHERE id = p_speaker;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('code', 404);
    END IF;

    IF NOT public.get_is_editor_on_occasion(v_occasion) THEN
        RETURN jsonb_build_object('code', 403);
    END IF;

    -- Parameter validation.
    IF p_slot_minutes IS NULL OR p_slot_minutes < 5
       OR p_start IS NULL OR p_end IS NULL OR p_start >= p_end
       OR p_capacity IS NULL OR p_capacity < 1
       OR p_break_minutes IS NULL OR p_break_minutes < 0 THEN
        RETURN jsonb_build_object('code', 400);
    END IF;

    IF p_place IS NOT NULL THEN
        IF NOT EXISTS (
            SELECT 1 FROM public.places
            WHERE id = p_place AND occasion = v_occasion
        ) THEN
            RETURN jsonb_build_object('code', 400);
        END IF;
    END IF;

    -- Event type comes from the "counseling" feature config (default 'counseling').
    SELECT COALESCE(elem->>'counseling_event_type', 'counseling')
    INTO v_type
    FROM public.occasions o
    CROSS JOIN LATERAL jsonb_array_elements(COALESCE(o.features, '[]'::jsonb)) elem
    WHERE o.id = v_occasion AND elem->>'code' = 'counseling'
    LIMIT 1;

    IF v_type IS NULL THEN
        v_type := 'counseling';
    END IF;

    v_title := COALESCE(p_title, v_speaker_title);

    -- Generate slots: last slot must fully fit within [p_start, p_end].
    v_slot_start := p_start;
    WHILE v_slot_start + make_interval(mins => p_slot_minutes) <= p_end LOOP
        v_slot_end := v_slot_start + make_interval(mins => p_slot_minutes);

        INSERT INTO public.events (occasion, title, start_time, end_time, max_participants, place, type, is_hidden, data)
        VALUES (
            v_occasion,
            v_title,
            v_slot_start,
            v_slot_end,
            p_capacity,
            p_place,
            v_type,
            FALSE,
            jsonb_build_object('is_counseling_slot', true)
        )
        RETURNING id INTO v_event_id;

        INSERT INTO public.event_speakers (event, speaker) VALUES (v_event_id, p_speaker);

        v_ids := array_append(v_ids, v_event_id);
        v_count := v_count + 1;

        v_slot_start := v_slot_start + make_interval(mins => p_slot_minutes + p_break_minutes);
    END LOOP;

    RETURN jsonb_build_object(
        'code', 200,
        'data', jsonb_build_object(
            'created',   v_count,
            'event_ids', to_jsonb(v_ids)
        )
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.create_email_confirmation_receipt(p_command uuid, p_order bigint, p_hash text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_message uuid;
BEGIN
 PERFORM public.require_service_role();
 SELECT message_id INTO v_message FROM public.email_messages WHERE message_kind='order_confirmation' AND data->>'command_id'=p_command::text AND order_id=p_order;
 IF v_message IS NULL THEN RETURN false; END IF;
 INSERT INTO public.email_confirmation_receipts(token_hash,message_id,expires_at) VALUES(p_hash,v_message,now()+interval '15 minutes');
 RETURN true;
END $function$

CREATE OR REPLACE FUNCTION public.create_form_client_sync_v1(p_occasion_link text, p_link text, p_title text, p_command_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_occasion bigint; v_unit bigint;
  v_begin jsonb; v_hash text; v_form jsonb;
BEGIN
  SELECT o.id,o.unit INTO v_occasion,v_unit FROM public.occasions o
    WHERE o.id=public.resolve_occasion_link_internal(p_occasion_link);
  IF v_actor IS NULL OR v_occasion IS NULL
    OR length(p_link)>80 OR length(COALESCE(p_title,''))>500
    OR NOT (public.get_is_editor_on_unit(v_unit)
      OR public.get_is_editor_on_occasion(v_occasion)) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion editor required'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'occasion',v_occasion,'link',p_link,'title',p_title)::text,'UTF8'),
    'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,
    'inventory.form.create',v_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  v_form:=public.create_form_internal_v1(v_occasion,p_link,p_title);
  RETURN public.complete_private_inventory_mutation_v1(p_command_id,v_occasion,
    'inventory.form.create',jsonb_build_array(jsonb_build_object(
      'entityType','form','entityId',v_form->>'id','operation','insert',
      'safeLabel',left(p_title,240),'changedFields',jsonb_build_array(
        'configuration','fields','products'))),'{}'::uuid[],
    jsonb_build_object('form',v_form));
END; $function$

CREATE OR REPLACE FUNCTION public.create_form_internal_v1(p_occasion_id bigint, p_link text, p_title text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
    new_form_id BIGINT;
    new_form JSONB;
    new_product_type_id BIGINT;
    now TIMESTAMPTZ := NOW();
BEGIN
    PERFORM public.check_occasion_writable(p_occasion_id);
    IF auth.uid() IS NULL OR NOT (public.get_is_editor_on_occasion(p_occasion_id)
      OR public.get_is_editor_on_unit((SELECT unit FROM public.occasions WHERE id=p_occasion_id))) THEN
      RAISE insufficient_privilege USING MESSAGE='form editor required'; END IF;
    -- Create the new form
    INSERT INTO public.forms(
        title,
        is_open,
        link,
        occasion,
        created_at,
        updated_at,
        deadline_duration_seconds,
        data
    )
    VALUES (
        p_title,
        false,
        NULL,
        p_occasion_id,
        now,
        now,
        604800, -- Default to 7 days
        '{"is_reminder_enabled": true}'::jsonb -- Default reminder setting
    )
    RETURNING to_jsonb(public.forms.*) INTO new_form;

    new_form_id := (new_form->>'id')::BIGINT;

    UPDATE public.forms SET link=public.reserve_public_link_internal('form',new_form_id,p_link,true) WHERE id=new_form_id;
    SELECT to_jsonb(f) INTO new_form FROM public.forms f WHERE id=new_form_id;

    -- Create default 'email' and 'ticket' fields
    INSERT INTO public.form_fields(title, type, is_required, form, "order")
    VALUES ('', 'email', true, new_form_id, 0),
           ('', 'ticket', true, new_form_id, 1);

    -- Ensure 'spot' product type exists for the occasion
    IF NOT EXISTS (SELECT 1 FROM eshop.product_types WHERE occasion = p_occasion_id AND type = 'spot') THEN
        INSERT INTO eshop.product_types(title, type, occasion)
        VALUES ('Spot', 'spot', p_occasion_id)
        RETURNING id INTO new_product_type_id;
    ELSE
        SELECT id INTO new_product_type_id FROM eshop.product_types WHERE occasion = p_occasion_id AND type = 'spot' LIMIT 1;
    END IF;

    -- Ensure the 'spot' product type has at least one product
    IF NOT EXISTS (SELECT 1 FROM eshop.products WHERE occasion = p_occasion_id AND product_type = new_product_type_id) THEN
        INSERT INTO eshop.products(title, price, product_type, occasion, currency_code, "order")
        VALUES ('Variant 1', 100, new_product_type_id, p_occasion_id, 'CZK', 0);
    END IF;

    -- Create the 'product_type' form field linked to 'spot'
    INSERT INTO public.form_fields(title, type, is_required, form, "order", product_type, is_ticket_field)
    VALUES ('Spot', 'product_type', false, new_form_id, 2, new_product_type_id, true);

    -- Return the raw data of the newly created form
    RETURN new_form;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_occasion_domain_command_internal_v1(p_command_id uuid, p_config jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_unit bigint; v_organization bigint;
  v_occasion bigint; v_begin jsonb; v_hash text; v_commit public.client_commits%ROWTYPE;
  v_entity jsonb;
BEGIN
  IF p_config IS NULL OR jsonb_typeof(p_config)<>'object'
    OR octet_length(p_config::text)>1048576
    OR EXISTS (SELECT 1 FROM jsonb_object_keys(p_config) key WHERE key NOT IN
      ('id','start_time','end_time','is_open','is_hidden','is_promoted','link','title',
       'description','data','services','organization','unit','features','form_link',
       'has_orders','stats'))
    OR p_config->>'id' IS NOT NULL
    OR nullif(btrim(p_config->>'title'),'') IS NULL THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid occasion aggregate'; END IF;
  v_unit:=NULLIF(p_config->>'unit','')::bigint;
  v_organization:=NULLIF(p_config->>'organization','')::bigint;
  IF v_actor IS NULL OR v_unit IS NULL OR v_organization IS NULL
    OR NOT EXISTS (SELECT 1 FROM public.units u
      WHERE u.id=v_unit AND u.organization=v_organization)
    OR NOT (public.get_is_manager_on_unit(v_unit)
      OR public.get_is_editor_on_unit(v_unit)) THEN
    RAISE insufficient_privilege USING MESSAGE='unit editor required'; END IF;
  v_hash:=encode(extensions.digest(convert_to(p_config::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_unit_client_mutation_v1(p_command_id,
    'occasion.create',v_unit,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  PERFORM public.admit_occasion_creation_v1(v_actor,v_unit,v_organization);
  PERFORM public.update_occasion_internal_v1(p_config);
  SELECT o.id,to_jsonb(o)||jsonb_build_object('aggregate_version',1)
    INTO v_occasion,v_entity FROM public.occasions o
    WHERE o.id=currval(pg_get_serial_sequence('public.occasions','id'));
  IF v_occasion IS NULL THEN
    RAISE data_exception USING MESSAGE='occasion create returned no aggregate'; END IF;
  INSERT INTO public.client_aggregate_versions
    (aggregate_type,scope_type,scope_id,aggregate_id,version)
  VALUES ('occasion','occasion',v_occasion,v_occasion::text,1);
  INSERT INTO public.client_commits
    (unit,actor_id,actor_display,actor_kind,source,change_class)
  SELECT v_unit,v_actor,nullif(concat_ws(' ',ui.name,ui.surname),''),'user',
    'occasion.create','configuration' FROM public.user_info ui WHERE ui.id=v_actor
  RETURNING * INTO v_commit;
  INSERT INTO public.client_commit_items
    (commit_id,item_index,entity_type,entity_id,operation,safe_label,changed_fields)
  VALUES (v_commit.commit_id,0,'occasion',v_occasion::text,'insert',
    left(v_entity->>'title',240),ARRAY['aggregate']);
  PERFORM public.fanout_unit_catalog_v1(v_commit.commit_id,v_unit);
  RETURN public.finish_client_mutation_v1(p_command_id,jsonb_build_object(
    'status','applied','code',200,'data',jsonb_build_object(
      'occasionId',v_occasion,'occasion',v_entity),
    'mutation',jsonb_build_object('commandId',p_command_id,
      'receiptId',p_command_id,'commitId',v_commit.commit_id,'replayed',false,
      'occurredAt',v_commit.occurred_at),
    'sync',jsonb_build_object('replacements','[]'::jsonb)),v_commit.commit_id);
END; $function$

CREATE OR REPLACE FUNCTION public.create_occasion_setup_draft(p_id uuid, p_unit bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE d public.occasion_setup_drafts; configuration jsonb; is_new boolean; policy jsonb;
BEGIN
  IF auth.uid() IS NULL OR NOT (public.get_is_editor_on_unit(p_unit) OR public.get_is_manager_on_unit(p_unit)) THEN
    RAISE EXCEPTION 'Draft access denied' USING ERRCODE = '42501';
  END IF;
  -- Serialize identical UUIDs before inspecting existence, without charging retries.
  PERFORM pg_advisory_xact_lock(hashtextextended('draft:'||p_id::text,0));
  is_new:=NOT EXISTS(SELECT 1 FROM public.occasion_setup_drafts WHERE id=p_id);
  IF is_new THEN
    policy:=public.abuse_effective_rules_v1('occasion.draft',p_unit,(SELECT organization FROM public.units WHERE id=p_unit));
    PERFORM public.admit_occasion_draft_v1(auth.uid(),p_unit,
      (SELECT organization FROM public.units WHERE id=p_unit),0,true,true,policy);
  END IF;
  INSERT INTO public.occasion_setup_drafts(id,unit,organization,author)
    SELECT p_id,id,organization,auth.uid() FROM public.units WHERE id = p_unit
    ON CONFLICT (id) DO NOTHING;
  SELECT * INTO d FROM public.occasion_setup_drafts WHERE id = p_id FOR UPDATE;
  IF d.unit IS DISTINCT FROM p_unit OR d.author IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'Draft access denied' USING ERRCODE = '42501';
  END IF;
  IF NOT (d.data ? 'defaultConfiguration') THEN
    IF NOT is_new THEN
      policy:=public.abuse_effective_rules_v1('occasion.draft',p_unit,d.organization);
      PERFORM public.admit_occasion_draft_v1(auth.uid(),p_unit,d.organization,0,false,true,policy);
    END IF;
    configuration := public.build_occasion_setup_configuration(p_unit,p_id);
    UPDATE public.occasion_setup_drafts SET data =
      jsonb_build_object('defaultConfiguration',configuration,
        'formDraft',configuration->'forms'->0,'formDefaultsFollowEvent',true)
      || d.data WHERE id = p_id RETURNING * INTO d;
    PERFORM public.admit_occasion_draft_v1(auth.uid(),p_unit,d.organization,octet_length(d.data::text),false,false,policy);
  END IF;
  RETURN to_jsonb(d);
END $function$

CREATE OR REPLACE FUNCTION public.create_occasion_user_client_sync_v1(p_occasion bigint, p_command_id uuid, p_profile jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_user uuid; v_begin jsonb; v_hash text;
  v_version bigint;
  v_result jsonb; v_profile jsonb; v_entity jsonb;
BEGIN
  IF v_actor IS NULL OR NOT (public.get_is_manager_on_occasion(p_occasion)
    OR public.get_is_admin_on_occasion(p_occasion)) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion manager required'; END IF;
  IF p_profile IS NULL OR jsonb_typeof(p_profile)<>'object'
    OR octet_length(p_profile::text)>262144
    OR (p_profile->>'occasion')::bigint IS DISTINCT FROM p_occasion
    OR p_profile->>'user' IS NOT NULL THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid new occasion user profile'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object('occasion',p_occasion,
    'profile',p_profile)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'profile.user.create',
    p_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  BEGIN
  v_result:=public.update_user_internal_v1(jsonb_build_object(
    'occasion',p_occasion,'user',NULL,'data',p_profile->'data'));
  IF COALESCE((v_result->>'code')::integer,500) NOT IN (200,201) THEN
    RAISE SQLSTATE 'P0P01' USING MESSAGE='profile creation rejected'; END IF;
  v_user:=(v_result->>'user')::uuid;
  v_result:=public.add_user_to_occasion_internal_v1(p_occasion,v_user);
  IF COALESCE((v_result->>'code')::integer,500)<>200 THEN
    RAISE SQLSTATE 'P0P01' USING MESSAGE='profile creation rejected'; END IF;
  v_profile:=p_profile||jsonb_build_object('user',v_user);
  v_result:=public.save_occasion_user_for_edit_internal_v1(v_profile);
  IF COALESCE((v_result->>'code')::integer,500)<>200 THEN
    RAISE SQLSTATE 'P0P01' USING MESSAGE='profile creation rejected'; END IF;
  EXCEPTION WHEN SQLSTATE 'P0P01' THEN
    -- All domain writes, including an account/membership created earlier, rolled back.
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',
      coalesce((v_result->>'code')::integer,400),jsonb_build_object('version',0,'profile',NULL,'message',v_result->>'message'));
  END;
  INSERT INTO public.client_aggregate_versions
    (aggregate_type,scope_type,scope_id,aggregate_id,version)
  VALUES ('occasion_user','occasion',p_occasion,v_user::text,1)
  ON CONFLICT (aggregate_type,scope_type,scope_id,aggregate_id) DO UPDATE
    SET version=public.client_aggregate_versions.version+1,
      updated_at=clock_timestamp() RETURNING version INTO v_version;
  SELECT public.get_occasion_user_command_data_v1(p_occasion,v_user) INTO v_entity;
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'profile.user.create','profile',jsonb_build_array(jsonb_build_object(
      'entityType','occasion_user','entityId',v_user,'operation','insert',
      'safeLabel','Occasion user','changedFields',jsonb_build_array('profile','rights','services'))),
    '{}',jsonb_build_array(jsonb_build_object('component','private_profile',
    'userId',v_user)),'[]',jsonb_build_object('version',v_version,'userId',v_user,
      'profile',v_entity));
END; $function$

CREATE OR REPLACE FUNCTION public.create_product_price_wave(p_occasion_link text, p_change_time timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_occasion bigint; v_wave eshop.product_price_waves%ROWTYPE;
BEGIN
  SELECT o.id INTO STRICT v_occasion FROM public.occasions o JOIN public.user_info ui
    ON ui.organization=o.organization WHERE o.id=public.resolve_occasion_link_internal(p_occasion_link) AND ui.id=auth.uid();
  PERFORM public.check_product_wave_editor(v_occasion);
  IF p_change_time IS NULL OR NOT isfinite(p_change_time) OR p_change_time<=clock_timestamp() THEN
    RAISE invalid_parameter_value USING MESSAGE='FUTURE_TIME_REQUIRED'; END IF;
  INSERT INTO eshop.product_price_waves(occasion,change_time) VALUES(v_occasion,p_change_time)
    ON CONFLICT(occasion,change_time) DO NOTHING;
  SELECT * INTO STRICT v_wave FROM eshop.product_price_waves
    WHERE occasion=v_occasion AND change_time=p_change_time FOR UPDATE;
  -- Adopt existing unambiguous targets at this shared term without repricing.
  PERFORM 1 FROM eshop.products p WHERE p.occasion=v_occasion AND EXISTS(
    SELECT 1 FROM eshop.planned_changes pc WHERE pc.subject_id=p.id AND pc.occasion=v_occasion
      AND pc.change_time=p_change_time AND pc.change_type IN('products.price','products.is_hidden') AND NOT pc.applied)
    ORDER BY p.id FOR UPDATE;
  UPDATE eshop.planned_changes pc SET wave_id=v_wave.id
    WHERE pc.occasion=v_occasion AND pc.change_time=p_change_time AND NOT pc.applied AND pc.wave_id IS NULL
      AND pc.change_type IN('products.price','products.is_hidden') AND EXISTS(
        SELECT 1 FROM eshop.products p JOIN eshop.product_types pt ON pt.id=p.product_type
        WHERE p.id=pc.subject_id AND p.occasion=v_occasion AND pt.occasion=v_occasion)
      AND (SELECT count(*) FROM eshop.planned_changes other WHERE other.subject_id=pc.subject_id
        AND other.change_type=pc.change_type AND other.change_time=pc.change_time AND NOT other.applied)=1;
  IF p_change_time<=clock_timestamp() THEN RAISE invalid_parameter_value USING MESSAGE='FUTURE_TIME_REQUIRED'; END IF;
  RETURN to_jsonb(v_wave);
END; $function$

CREATE OR REPLACE FUNCTION public.create_reception_user_v1(p_occasion bigint, p_command_id uuid, p_profile jsonb, p_group_id bigint DEFAULT NULL::bigint, p_accommodation_code text DEFAULT NULL::text, p_confirm_same_name boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_org bigint; v_user uuid; v_hash text; v_existing public.reception_registrations%rowtype;
  v_name text:=btrim(p_profile->>'name'); v_surname text:=btrim(p_profile->>'surname'); v_email text:=lower(btrim(p_profile->>'email'));
  v_sex text:=p_profile->>'sex'; v_matches jsonb; v_services jsonb:='{}'::jsonb; v_catalog jsonb;
BEGIN
  IF NOT public.get_can_use_reception(p_occasion) THEN RETURN jsonb_build_object('code',403,'message','reception_unavailable'); END IF;
  IF NOT public.reception_rate_limit_v1('create') THEN RETURN jsonb_build_object('code',429,'message','rate_limited'); END IF;
  IF p_profile IS NULL OR jsonb_typeof(p_profile)<>'object' OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_profile) k WHERE k NOT IN('name','surname','email','sex','phone','birthDate'))
  THEN RETURN jsonb_build_object('code',400,'message','invalid_profile_fields'); END IF;
  IF COALESCE(v_name,'')='' OR COALESCE(v_surname,'')='' OR COALESCE(v_email,'')='' OR position('@' IN v_email)<=1 OR v_sex NOT IN('male','female','unspecified')
  THEN RETURN jsonb_build_object('code',400,'message','required_profile_fields'); END IF;
  v_hash:=encode(digest(jsonb_build_object('profile',p_profile,'group',p_group_id,'accommodation',p_accommodation_code)::text,'sha256'),'hex');
  SELECT * INTO v_existing FROM public.reception_registrations WHERE occasion=p_occasion AND created_by=v_actor AND command_id=p_command_id;
  IF FOUND THEN
    IF v_existing.request_hash<>v_hash THEN RETURN jsonb_build_object('code',409,'message','command_conflict'); END IF;
    SELECT ui.email_readonly INTO v_email FROM public.user_info ui WHERE ui.id=v_existing."user";
    RETURN jsonb_build_object('code',200,'userId',v_existing."user",'email',v_email,'replayed',true);
  END IF;
  SELECT o.organization,COALESCE(o.services,'{}'::jsonb) INTO v_org,v_catalog FROM public.occasions o WHERE o.id=p_occasion FOR SHARE;
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('reception-email:'||v_org::text||':'||v_email,0));
  SELECT ui.id INTO v_user
  FROM public.user_info ui
  WHERE ui.organization=v_org AND lower(btrim(ui.email_readonly))=v_email;
  IF v_user IS NOT NULL THEN
    IF (public.get_is_admin_on_occasion(p_occasion)
        OR public.get_is_manager_on_occasion(p_occasion))
      AND EXISTS(SELECT 1 FROM public.occasion_users ou
        WHERE ou.occasion=p_occasion AND ou."user"=v_user) THEN
      RETURN jsonb_build_object('code',200,'userId',v_user,'email',v_email,
        'existing',true,'replayed',false);
    END IF;
    RETURN jsonb_build_object('code',409,'message','email_already_exists');
  END IF;
  SELECT COALESCE(jsonb_agg(candidate),'[]'::jsonb) INTO v_matches FROM (
    SELECT jsonb_build_object('name',ui.name,'surname',ui.surname,'sex',ui.sex,
      'birthYear',CASE WHEN ui.birth_date IS NULL THEN NULL ELSE extract(year FROM ui.birth_date)::int END,
      'email',CASE WHEN position('@' IN ui.email_readonly)>2 THEN left(ui.email_readonly,1)||'***@'||split_part(ui.email_readonly,'@',2) ELSE '***' END,
      'onOccasion',EXISTS(SELECT 1 FROM public.occasion_users ou WHERE ou.occasion=p_occasion AND ou."user"=ui.id)) candidate
    FROM public.user_info ui WHERE ui.organization=v_org AND public.f_unaccent(btrim(ui.name))=public.f_unaccent(v_name)
      AND public.f_unaccent(btrim(ui.surname))=public.f_unaccent(v_surname) ORDER BY ui.created_at NULLS LAST LIMIT 10) q;
  IF jsonb_array_length(v_matches)>0 AND NOT p_confirm_same_name THEN RETURN jsonb_build_object('code',409,'message','same_name_confirmation_required','candidates',v_matches); END IF;
  IF p_group_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.user_group_info g WHERE g.id=p_group_id AND g.occasion=p_occasion AND g.type IS NULL FOR SHARE)
  THEN RETURN jsonb_build_object('code',400,'message','invalid_group'); END IF;
  IF p_accommodation_code IS NOT NULL AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(CASE WHEN jsonb_typeof(v_catalog->'accommodation')='array' THEN v_catalog->'accommodation' ELSE '[]'::jsonb END) x WHERE x->>'code'=p_accommodation_code)
  THEN RETURN jsonb_build_object('code',400,'message','invalid_accommodation'); END IF;
  v_user:=public.create_user_in_organization_with_data_pure(v_org,v_email,v_email,encode(gen_random_bytes(32),'hex'),p_profile-'email');
  IF p_accommodation_code IS NOT NULL THEN v_services:=jsonb_build_object('accommodation',jsonb_build_object(p_accommodation_code,'paid')); END IF;
  INSERT INTO public.occasion_users(occasion,"user",data,services) VALUES(p_occasion,v_user,p_profile,v_services);
  IF p_group_id IS NOT NULL THEN INSERT INTO public.user_groups("user","group",is_admin) VALUES(v_user,p_group_id,false); END IF;
  INSERT INTO public.reception_registrations(occasion,"user",created_by,command_id,request_hash) VALUES(p_occasion,v_user,v_actor,p_command_id,v_hash);
  RETURN jsonb_build_object('code',200,'userId',v_user,'email',v_email,'replayed',false);
EXCEPTION WHEN unique_violation THEN RETURN jsonb_build_object('code',409,'message','email_or_command_conflict');
END $function$

CREATE OR REPLACE FUNCTION public.create_service_item_client_sync_v1(p_occasion bigint, p_type text, p_code text, p_title text, p_reference bigint, p_command_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_begin jsonb; v_hash text; v_result jsonb;
  v_before jsonb; v_after jsonb;
BEGIN
  IF v_actor IS NULL OR p_type NOT IN ('food','accommodation')
    OR nullif(btrim(p_code),'') IS NULL OR length(p_code)>100
    OR length(COALESCE(p_title,''))>500
    OR NOT public.get_is_manager_on_occasion(p_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion manager required'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'occasion',p_occasion,'type',p_type,'code',p_code,'title',p_title,
    'reference',p_reference)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,
    'occasion.service.create',p_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  SELECT o.services INTO v_before FROM public.occasions o
    WHERE o.id=p_occasion FOR UPDATE;
  v_result:=public.create_service_item_internal_v1(
    p_occasion,p_type,p_code,p_title,p_reference);
  IF COALESCE((v_result->>'code')::integer,500)<>200 THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',
      400,v_result); END IF;
  SELECT o.services INTO v_after FROM public.occasions o WHERE o.id=p_occasion;
  IF v_before IS NOT DISTINCT FROM v_after THEN
    RETURN public.complete_client_mutation_outcome_v1(
      p_command_id,'unchanged',200,v_result); END IF;
  INSERT INTO public.client_aggregate_versions(aggregate_type,scope_type,scope_id,aggregate_id,version)
  VALUES('occasion','occasion',p_occasion,p_occasion::text,1)
  ON CONFLICT(aggregate_type,scope_type,scope_id,aggregate_id) DO UPDATE
  SET version=public.client_aggregate_versions.version+1,updated_at=clock_timestamp();
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'occasion.service.create','configuration',jsonb_build_array(jsonb_build_object(
      'entityType','occasion_service','entityId',p_code,'operation','insert',
      'safeLabel',left(p_title,240),'changedFields',jsonb_build_array('services'))),
    ARRAY['occasion_config'],'[]','[]',v_result);
END; $function$

CREATE OR REPLACE FUNCTION public.create_spots_for_inventory_pool(p_inventory_pool_id bigint)
 RETURNS integer
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_context RECORD;
    v_resource RECORD;
    v_spots_to_create BIGINT;
    v_spots_to_delete BIGINT;
    v_booked_spots_count BIGINT;
    v_total_spots_count BIGINT;
    v_deletable_spot_ids BIGINT[];
    v_net_change INTEGER := 0;
    v_pool_occasion_id BIGINT;
    v_total_pool_capacity BIGINT;
BEGIN
    -- Step 0: Validate input and get occasion ID.
    SELECT occasion INTO v_pool_occasion_id FROM public.inventory_pools WHERE id = p_inventory_pool_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Inventory pool with ID % not found.', p_inventory_pool_id;
    END IF;

    -- Calculate the total capacity for the entire pool once. This is the target for the generic pool.
    SELECT COALESCE(SUM(capacity), 0) INTO v_total_pool_capacity
    FROM public.resources
    WHERE inventory_pool = p_inventory_pool_id;

    -- =================================================================
    -- Main Synchronization Loop (per context)
    -- =================================================================
    FOR v_context IN
        SELECT id FROM public.inventory_contexts WHERE inventory_pool = p_inventory_pool_id
    LOOP
        -- =============================================================
        -- Part A: Cleanup of RESOURCE-SPECIFIC Spots for this context
        -- =============================================================
        FOR v_resource IN
            SELECT id, capacity FROM public.resources WHERE inventory_pool = p_inventory_pool_id
        LOOP
            -- Count spots for the current resource WITHIN the current context.
            SELECT count(*) INTO v_total_spots_count FROM eshop.spots WHERE inventory_context = v_context.id AND resource = v_resource.id;
            SELECT count(*) INTO v_booked_spots_count FROM eshop.spots WHERE inventory_context = v_context.id AND resource = v_resource.id AND order_product_ticket IS NOT NULL;

            IF v_booked_spots_count > v_resource.capacity THEN
                RAISE EXCEPTION 'Cannot synchronize. For Context ID % and Resource ID %, there are % booked spots, which exceeds resource capacity of %. Manual intervention required.', v_context.id, v_resource.id, v_booked_spots_count, v_resource.capacity;
            END IF;

            IF v_total_spots_count > v_resource.capacity THEN
                v_spots_to_delete := v_total_spots_count - v_resource.capacity;
                SELECT array_agg(id) INTO v_deletable_spot_ids FROM (
                    SELECT id FROM eshop.spots
                    WHERE inventory_context = v_context.id AND resource = v_resource.id AND order_product_ticket IS NULL
                    ORDER BY created_at DESC
                    LIMIT v_spots_to_delete
                ) AS sub;

                IF array_length(v_deletable_spot_ids, 1) < v_spots_to_delete THEN
                     RAISE EXCEPTION 'Cannot delete excess spots for Context ID % and Resource ID %. Deletion would require removing a booked spot.', v_context.id, v_resource.id;
                END IF;

                DELETE FROM eshop.spots WHERE id = ANY(v_deletable_spot_ids);
                v_net_change := v_net_change - v_spots_to_delete;
            END IF;
        END LOOP;

        -- =============================================================
        -- Part B: Management of GENERIC Spot Pool for this context
        -- =============================================================
        -- Count total and booked spots for the GENERIC pool (resource IS NULL) within the current context.
        SELECT count(*) INTO v_total_spots_count FROM eshop.spots WHERE inventory_context = v_context.id;
        SELECT count(*) INTO v_booked_spots_count FROM eshop.spots WHERE inventory_context = v_context.id AND order_product_ticket IS NOT NULL;

        IF v_booked_spots_count > v_total_pool_capacity THEN
            RAISE EXCEPTION 'Cannot synchronize. Inventory Context ID % has % booked generic spots, which exceeds the total pool capacity of %. Manual intervention required.', v_context.id, v_booked_spots_count, v_total_pool_capacity;
        END IF;

        -- DELETION of generic spots
        IF v_total_spots_count > v_total_pool_capacity THEN
            v_spots_to_delete := v_total_spots_count - v_total_pool_capacity;
            SELECT array_agg(id) INTO v_deletable_spot_ids FROM (
                SELECT id FROM eshop.spots
                WHERE inventory_context = v_context.id AND resource IS NULL AND order_product_ticket IS NULL
                ORDER BY created_at DESC
                LIMIT v_spots_to_delete
            ) AS sub;

            IF array_length(v_deletable_spot_ids, 1) < v_spots_to_delete THEN
                 RAISE EXCEPTION 'Cannot delete excess generic spots for Context ID %. Deletion would require removing a booked spot.', v_context.id;
            END IF;

            DELETE FROM eshop.spots WHERE id = ANY(v_deletable_spot_ids);
            v_net_change := v_net_change - v_spots_to_delete;
        END IF;

        -- CREATION of generic spots
        -- Recount after potential deletion to get the current number.
        SELECT count(*) INTO v_total_spots_count FROM eshop.spots WHERE inventory_context = v_context.id;

        IF v_total_spots_count < v_total_pool_capacity THEN
            v_spots_to_create := v_total_pool_capacity - v_total_spots_count;

            -- Insert the required number of new generic spots.
            -- Per instructions, ONLY occasion and inventory_context are set.
            INSERT INTO eshop.spots (occasion, inventory_context)
            SELECT
                v_pool_occasion_id,
                v_context.id
            FROM generate_series(1, v_spots_to_create);

            v_net_change := v_net_change + v_spots_to_create;
        END IF;
    END LOOP;

    RETURN v_net_change;

END;
$function$

CREATE OR REPLACE FUNCTION public.create_ticket_order_client_sync_v1(p_order jsonb, p_command_id uuid, p_client_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_occasion bigint; v_begin jsonb; v_hash text;
  v_result jsonb; v_symbol text; v_before_users uuid[]; v_actor_kind text;
BEGIN
  IF p_order IS NULL OR jsonb_typeof(p_order)<>'object'
    OR octet_length(p_order::text)>4194304 OR p_command_id IS NULL
    OR (v_actor IS NULL AND p_client_id IS NULL) THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid ticket order command'; END IF;
  SELECT f.occasion INTO v_occasion FROM public.forms f
    WHERE f.key=NULLIF(p_order->>'form','')::uuid;
  IF v_occasion IS NULL THEN
    RAISE invalid_parameter_value USING MESSAGE='ticket order form not found'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'occasion',v_occasion,'order',p_order)::text,'UTF8'),'sha256'),'hex');
  IF v_actor IS NULL THEN
    v_begin:=public.begin_anonymous_client_mutation_v1(p_command_id,
      'inventory.order.create',v_occasion,p_client_id,v_hash);
    v_actor_kind:='unknown';
  ELSE
    v_begin:=public.begin_client_mutation_v1(p_command_id,
      'inventory.order.create',v_occasion,v_actor,v_hash);
    v_actor_kind:='user';
  END IF;
  IF v_begin->>'disposition'='replay' THEN
    v_result := v_begin->'response';
    IF v_result#>'{data,order}' IS NOT NULL AND v_result#>>'{data,order,order_symbol}' IS NULL THEN
      v_symbol := public.read_order_identity((v_result#>>'{data,order,id}')::bigint,
        v_occasion, (SELECT organization FROM public.occasions WHERE id=v_occasion));
      IF v_symbol IS NOT NULL THEN
        v_result := jsonb_set(v_result, '{data,order,order_symbol}', to_jsonb(v_symbol));
      END IF;
    END IF;
    RETURN public.project_local_payment_reference_order_internal(v_result);
  END IF;
  SELECT COALESCE(array_agg(ou."user"),'{}'::uuid[]) INTO v_before_users
    FROM public.occasion_users ou WHERE ou.occasion=v_occasion;
  v_result:=public.create_ticket_order_internal_v1(p_order);
  IF COALESCE((v_result->>'code')::integer,500)<>200 THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',
      CASE WHEN COALESCE((v_result->>'code')::integer,500) BETWEEN 100 AND 599
        THEN (v_result->>'code')::integer ELSE 400 END,v_result); END IF;
  PERFORM public.enqueue_ticket_order_confirmation_v1(
    p_command_id,v_occasion,v_result,p_order->>'lang');
  RETURN public.complete_profile_inventory_membership_mutation_v1(
    p_command_id,v_occasion,'inventory.order.create',jsonb_build_array(jsonb_build_object(
      'entityType','order','entityId',v_result#>>'{order,id}','operation','insert',
      'safeLabel','Ticket order','changedFields',jsonb_build_array(
        'tickets','products','allocations','membership'))),v_before_users,v_result,
    v_actor_kind);
END; $function$

CREATE OR REPLACE FUNCTION public.create_ticket_order_internal_v1(input_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE f bigint; target bigint; result jsonb;
BEGIN
 PERFORM public.lock_blueprint_scope_internal(ARRAY[(SELECT occasion FROM public.forms WHERE key=(input_data->>'form')::uuid)]);
 PERFORM public.check_occasion_writable((SELECT occasion FROM public.forms WHERE key=(input_data->>'form')::uuid));
 BEGIN
  SELECT id INTO f FROM public.forms WHERE key=(input_data->>'form')::uuid FOR UPDATE;
  IF f IS NULL THEN RAISE EXCEPTION 'Form not found'; END IF;
  target:=public.allocate_ticket_order_identity_internal(f);
  result:=public.finalize_ticket_order_internal_v1(target,input_data,false);
  IF coalesce((result->>'code')::integer,500)<>200 THEN RAISE EXCEPTION '%',result::text; END IF;
  RETURN result;
 EXCEPTION WHEN SQLSTATE 'PT429' THEN
  RETURN jsonb_build_object('code',429,'errorCode','ABUSE_LIMIT_EXCEEDED','message','Capacity is temporarily limited. Try again later.');
 WHEN OTHERS THEN
  RETURN CASE WHEN left(SQLERRM,1)='{' THEN SQLERRM::jsonb ELSE jsonb_build_object('code',1013,'message',SQLERRM) END;
 END;
END $function$

CREATE OR REPLACE FUNCTION public.create_unit_and_assign_manager(title text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_user_id uuid;
  v_org_id bigint;
  v_email text;
  v_new_unit_id bigint;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('code', 401, 'message', 'Unauthorized');
  END IF;

  SELECT organization, email_readonly 
  INTO v_org_id, v_email
  FROM public.user_info 
  WHERE id = v_user_id;

  IF v_org_id IS NULL THEN
     RETURN jsonb_build_object('code', 404, 'message', 'User info or organization not found');
  END IF;

  -- Check if unit creation is enabled for organization
  DECLARE
      v_is_enabled boolean;
  BEGIN
      SELECT (data->>'IS_UNIT_CREATION_ENABLED')::boolean 
      INTO v_is_enabled
      FROM public.organizations 
      WHERE id = v_org_id;

      IF v_is_enabled IS NOT TRUE THEN
          RETURN jsonb_build_object('code', 403, 'message', 'Unit creation is disabled for this organization');
      END IF;
  END;

  PERFORM public.admit_unit_creation_v1(v_user_id,v_org_id);

  INSERT INTO public.units (title, organization, data)
  VALUES (
    title, 
    v_org_id,
    jsonb_build_object(
        'reply_to', lower(trim(COALESCE(v_email, ''))),
        'timezone', 'Europe/Prague'
    )
  )
  RETURNING id INTO v_new_unit_id;

  INSERT INTO public.unit_users (unit, "user", is_manager, is_editor, is_editor_view)
  VALUES (v_new_unit_id, v_user_id, true, true, true);

  RETURN jsonb_build_object(
    'code', 200, 
    'message', 'Unit created successfully', 
    'data', jsonb_build_object('id', v_new_unit_id)
  );

EXCEPTION WHEN SQLSTATE 'PT429' THEN
  RETURN jsonb_build_object('code',429,'message','Capacity is temporarily limited. Try again later.');
WHEN OTHERS THEN
  RETURN jsonb_build_object('code', 500, 'message', SQLERRM);
END;
$function$

CREATE OR REPLACE FUNCTION public.create_user_for_test(test_user_alias text, test_email text)
