CREATE OR REPLACE FUNCTION public.delete_empty_counseling_slots_client_sync_v1(p_speaker bigint, p_from timestamp with time zone, p_command_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_occasion bigint; v_begin jsonb; v_hash text;
  v_result jsonb; v_ids bigint[]; v_users uuid[]; v_impacts jsonb;
  v_publishable boolean;
BEGIN
  SELECT s.occasion,NOT o.is_hidden INTO v_occasion,v_publishable
    FROM public.speakers s JOIN public.occasions o ON o.id=s.occasion
    WHERE s.id=p_speaker;
  IF v_actor IS NULL OR v_occasion IS NULL
    OR NOT public.get_is_editor_on_occasion(v_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion editor required'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object('speaker',p_speaker,
    'from',p_from)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'program.counseling.delete_empty',
    v_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  SELECT COALESCE(array_agg(e.id ORDER BY e.id),'{}'::bigint[]) INTO v_ids
    FROM public.events e JOIN public.event_speakers es ON es.event=e.id
    WHERE es.speaker=p_speaker AND (e.data->>'is_counseling_slot')::boolean IS TRUE
      AND (p_from IS NULL OR e.start_time>=p_from)
      AND NOT EXISTS (SELECT 1 FROM public.event_users eu WHERE eu.event=e.id);
  PERFORM public.lock_event_deletion_scope_internal_v1(v_occasion,v_ids);
  PERFORM 1 FROM public.speakers WHERE id=p_speaker FOR NO KEY UPDATE;
  PERFORM pg_catalog.pg_advisory_xact_lock(p_speaker);
  IF EXISTS(SELECT 1 FROM public.events e JOIN public.event_speakers es ON es.event=e.id
    WHERE es.speaker=p_speaker AND (e.data->>'is_counseling_slot')::boolean IS TRUE
    AND (p_from IS NULL OR e.start_time>=p_from) AND NOT e.id=ANY(v_ids)
    AND NOT EXISTS(SELECT 1 FROM public.event_users WHERE event=e.id)) THEN
    RAISE serialization_failure USING MESSAGE='counseling slots changed; retry the same command'; END IF;
  -- A booking can commit while we wait for the event lock. Keep its metadata.
  v_ids:=ARRAY(SELECT id FROM public.events WHERE id=ANY(v_ids)
    AND NOT EXISTS(SELECT 1 FROM public.event_users WHERE event=events.id) ORDER BY id);
  PERFORM 1 FROM public.event_users_saved eus WHERE eus.event=ANY(v_ids)
    ORDER BY eus.event,eus."user" FOR UPDATE;
  SELECT COALESCE(array_agg(DISTINCT eus."user"),'{}'::uuid[]) INTO v_users
    FROM public.event_users_saved eus WHERE eus.event=ANY(v_ids);
  v_result:=public.delete_empty_counseling_slots_internal_v1(p_speaker,p_from);
  IF COALESCE((v_result->>'code')::integer,500)<>200 THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',
      COALESCE((v_result->>'code')::integer,400),COALESCE(v_result->'data','{}')); END IF;
  IF cardinality(v_ids)=0 THEN RETURN public.complete_client_mutation_outcome_v1(
    p_command_id,'unchanged',200,v_result->'data'); END IF;
  DELETE FROM public.client_aggregate_versions v WHERE v.aggregate_type='event'
    AND v.scope_type='occasion' AND v.scope_id=v_occasion
    AND v.aggregate_id=ANY(ARRAY(SELECT id::text FROM unnest(v_ids) id));
  SELECT COALESCE(jsonb_agg(jsonb_build_object('component','private_program',
    'userId',id)),'[]'::jsonb) INTO v_impacts FROM unnest(v_users) id
    JOIN public.occasion_users ou ON ou.occasion=v_occasion AND ou."user"=id;
  RETURN public.complete_client_mutation_applied_v1(p_command_id,v_occasion,
    'program.counseling.delete_empty','program',jsonb_build_array(jsonb_build_object(
      'entityType','counseling_slot','entityId',NULL,'operation','delete',
      'safeLabel','Empty counseling slots','changedFields',jsonb_build_array('events'))),
    CASE WHEN v_publishable THEN ARRAY['program_catalog','content_catalog','live_public']
      ELSE '{}'::text[] END,v_impacts,CASE WHEN v_publishable THEN COALESCE((
      SELECT jsonb_agg(jsonb_build_object('component','live_public','entityId',id))
      FROM unnest(v_ids) id),'[]'::jsonb) ELSE '[]'::jsonb END,v_result->'data');
END; $function$

CREATE OR REPLACE FUNCTION public.delete_empty_counseling_slots_internal_v1(p_speaker bigint, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
    v_occasion BIGINT;
    v_deleted INT;
    v_ids bigint[]; v_effects jsonb;
BEGIN
    SELECT occasion INTO v_occasion
    FROM public.speakers
    WHERE id = p_speaker;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('code', 404);
    END IF;

    IF NOT public.get_is_editor_on_occasion(v_occasion) THEN
        RETURN jsonb_build_object('code', 403);
    END IF;

    SELECT ARRAY(SELECT e.id FROM public.events e JOIN public.event_speakers es ON es.event=e.id
      WHERE es.speaker=p_speaker AND (e.data->>'is_counseling_slot')::boolean IS TRUE
      AND (p_from IS NULL OR e.start_time>=p_from)
      AND NOT EXISTS(SELECT 1 FROM public.event_users WHERE event=e.id) ORDER BY e.id) INTO v_ids;
    v_effects:=public.delete_events_domain_internal_v1(v_occasion,v_ids);
    v_deleted:=(v_effects->>'deleted')::integer;

    RETURN jsonb_build_object(
        'code', 200,
        'data', jsonb_build_object('deleted', v_deleted)
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.delete_entity_email_template(p_entity_type text, p_entity_id bigint, p_code text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
begin
    if p_entity_type = 'occasion' then
        if (public.get_is_editor_on_occasion(p_entity_id) IS NOT TRUE
            AND public.get_is_editor_order_on_occasion(p_entity_id) IS NOT TRUE) then
            perform public.raise_error('permission_denied');
        end if;

        delete from public.email_templates
        where occasion = p_entity_id
          and code = p_code;

    elsif p_entity_type = 'unit' then
        if (public.get_is_editor_on_unit(p_entity_id) IS NOT TRUE) then
            perform public.raise_error('permission_denied');
        end if;

        delete from public.email_templates
        where unit = p_entity_id
          and occasion is null
          and code = p_code;
    else
        raise exception 'Invalid entity type: %', p_entity_type;
    end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.delete_event(p_event bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE oc bigint; ver bigint; r jsonb;
BEGIN
 SELECT occasion INTO oc FROM public.events WHERE id=p_event;
 IF oc IS NULL THEN RETURN jsonb_build_object('code',404); END IF;
 IF auth.uid() IS NULL OR NOT public.get_is_editor_on_occasion(oc) THEN RETURN jsonb_build_object('code',403); END IF;
 PERFORM public.lock_event_deletion_scope_internal_v1(oc,ARRAY[p_event]);
 PERFORM 1 FROM public.events WHERE id=p_event AND occasion=oc FOR UPDATE;
 SELECT coalesce(v.version,0) INTO ver FROM (SELECT 1) seed LEFT JOIN public.client_aggregate_versions v
 ON v.aggregate_type='event' AND v.scope_type='occasion' AND v.scope_id=oc AND v.aggregate_id=p_event::text;
 r:=public.delete_event_client_sync_v1(oc,p_event,extensions.gen_random_uuid(),ver);
 RETURN jsonb_build_object('code',r->'code');
END $function$

CREATE OR REPLACE FUNCTION public.delete_event_client_sync_v1(p_occasion bigint, p_event_id bigint, p_command_id uuid, p_expected_version bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_begin jsonb; v_version bigint; v_event jsonb;
  v_commit jsonb; v_program jsonb; v_response jsonb; v_hash text;
  v_is_publishable boolean; v_users uuid[]; v_private_impacts jsonb;
  v_had_speakers boolean; v_effects jsonb;
BEGIN
  IF v_actor IS NULL OR NOT public.get_is_editor_on_occasion(p_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion editor required';
  END IF;
  SELECT NOT o.is_hidden INTO v_is_publishable
  FROM public.occasions o WHERE o.id=p_occasion;
  IF v_is_publishable IS NULL THEN
    RAISE invalid_parameter_value USING MESSAGE='occasion not found';
  END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object('occasion',p_occasion,
    'eventId',p_event_id,'expectedVersion',p_expected_version)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'event.delete',p_occasion,
    v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  PERFORM public.lock_event_deletion_scope_internal_v1(p_occasion,ARRAY[p_event_id]);
  PERFORM 1 FROM public.events e WHERE e.id=p_event_id AND e.occasion=p_occasion FOR UPDATE;
  IF NOT FOUND THEN
    v_response:=jsonb_build_object('status','unchanged','code',200,
      'data',jsonb_build_object('eventId',p_event_id,'deleted',false),
      'mutation',jsonb_build_object('commandId',p_command_id,'receiptId',p_command_id,
        'commitId',NULL,'replayed',false,'occurredAt',clock_timestamp()),
      'sync',jsonb_build_object('replacements','[]'::jsonb));
    RETURN public.finish_client_mutation_v1(p_command_id,v_response,NULL);
  END IF;
  INSERT INTO public.client_aggregate_versions
    (aggregate_type,scope_type,scope_id,aggregate_id,version)
  VALUES ('event','occasion',p_occasion,p_event_id::text,0) ON CONFLICT DO NOTHING;
  SELECT version INTO v_version FROM public.client_aggregate_versions
    WHERE aggregate_type='event' AND scope_type='occasion' AND scope_id=p_occasion
      AND aggregate_id=p_event_id::text FOR UPDATE;
  v_event:=public.get_event_command_data_v1(p_event_id);
  IF p_expected_version IS DISTINCT FROM v_version THEN
    v_response:=jsonb_build_object('status','conflict','code',409,
      'data',jsonb_build_object('version',v_version,'event',v_event),
      'mutation',jsonb_build_object('commandId',p_command_id,'receiptId',p_command_id,
        'commitId',NULL,'replayed',false,'occurredAt',clock_timestamp()),
      'sync',jsonb_build_object('replacements','[]'::jsonb));
    RETURN public.finish_client_mutation_v1(p_command_id,v_response,NULL);
  END IF;
  SELECT ARRAY(SELECT DISTINCT id FROM (
    SELECT eu."user" id FROM public.event_users eu WHERE eu.event=p_event_id
    UNION SELECT eus."user" FROM public.event_users_saved eus
      WHERE eus.event=p_event_id) users ORDER BY id) INTO v_users;
  v_effects:=public.delete_events_domain_internal_v1(p_occasion,ARRAY[p_event_id]);
  v_had_speakers:=(v_effects->>'hadSpeakers')::boolean;
  SELECT COALESCE(jsonb_agg(jsonb_build_object('component','private_program',
    'userId',id)),'[]'::jsonb) INTO v_private_impacts
    FROM unnest(COALESCE(v_users,'{}'::uuid[])) id
    JOIN public.occasion_users ou ON ou.occasion=p_occasion AND ou."user"=id;
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'event.delete','program',jsonb_build_array(jsonb_build_object(
      'entityType','event','entityId',p_event_id,'operation','delete',
      'safeLabel',left(v_event->>'title',240),
      'changedFields',jsonb_build_array('aggregate'))),
    CASE WHEN v_is_publishable THEN ARRAY['program_catalog','live_public']||
      CASE WHEN v_had_speakers THEN ARRAY['content_catalog'] ELSE '{}'::text[] END
      ELSE '{}'::text[] END,v_private_impacts,
    CASE WHEN v_is_publishable THEN jsonb_build_array(jsonb_build_object(
      'component','live_public','entityId',p_event_id))||coalesce((SELECT jsonb_agg(jsonb_build_object('component','live_public','entityId',value::bigint)) FROM jsonb_array_elements_text(v_effects->'childIds')),'[]'::jsonb) ELSE '[]'::jsonb END,
    jsonb_build_object('eventId',p_event_id,'deleted',true));
END; $function$

CREATE OR REPLACE FUNCTION public.delete_event_feedback(p_event bigint, p_client_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE p_occasion bigint; r jsonb;
BEGIN
 SELECT occasion INTO p_occasion FROM public.events WHERE id=p_event;
 IF p_occasion IS NULL THEN RETURN jsonb_build_object('code',404); END IF;
 r:=public.delete_event_feedback_client_sync_v1(p_occasion,p_event,p_client_id,extensions.gen_random_uuid());
 RETURN jsonb_build_object('code',r->'code','data',jsonb_build_object('deleted',CASE WHEN (r#>>'{data,deleted}')::boolean THEN 1 ELSE 0 END),'message',r#>'{data,message}');
END $function$

CREATE OR REPLACE FUNCTION public.delete_event_feedback_client_sync_v1(p_occasion bigint, p_event bigint, p_client_id uuid, p_command_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_client uuid; v_begin jsonb; v_hash text;
  v_before public.event_feedback%ROWTYPE; v_result jsonb;
  v_private_impacts jsonb:='[]'::jsonb; v_replacements jsonb:='[]'::jsonb;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.events e
    WHERE e.id=p_event AND e.occasion=p_occasion) THEN
    RAISE invalid_parameter_value USING MESSAGE='feedback event outside occasion'; END IF;
  v_client:=CASE WHEN v_actor IS NULL THEN p_client_id ELSE NULL END;
  IF v_actor IS NULL AND v_client IS NULL THEN
    RAISE invalid_parameter_value USING MESSAGE='anonymous client id required'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'occasion',p_occasion,'event',p_event,'clientId',v_client)::text,
    'UTF8'),'sha256'),'hex');
  IF v_actor IS NULL THEN
    v_begin:=public.begin_anonymous_client_mutation_v1(p_command_id,
      'feedback.delete',p_occasion,v_client,v_hash);
  ELSE
    v_begin:=public.begin_client_mutation_v1(p_command_id,'feedback.delete',
      p_occasion,v_actor,v_hash);
  END IF;
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  PERFORM 1 FROM public.events e WHERE e.id=p_event FOR UPDATE;
  IF v_actor IS NULL THEN
    SELECT * INTO v_before FROM public.event_feedback f
      WHERE f.event=p_event AND f."user" IS NULL AND f.client_id=v_client
      FOR UPDATE;
  ELSE
    SELECT * INTO v_before FROM public.event_feedback f
      WHERE f.event=p_event AND f."user"=v_actor FOR UPDATE;
  END IF;
  IF v_before.id IS NULL THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'unchanged',200,
      jsonb_build_object('deleted',false)); END IF;
  v_result:=public.delete_event_feedback_internal_v1(p_event,v_client);
  IF COALESCE((v_result->>'code')::integer,500)<>200 THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',
      CASE WHEN COALESCE((v_result->>'code')::integer,400) BETWEEN 100 AND 599
        THEN (v_result->>'code')::integer ELSE 400 END,
      jsonb_build_object('message',v_result->>'message'));
  END IF;
  IF v_actor IS NOT NULL AND EXISTS (SELECT 1 FROM public.occasion_users ou
    WHERE ou.occasion=p_occasion AND ou."user"=v_actor) THEN
    v_private_impacts:=jsonb_build_array(jsonb_build_object(
      'component','private_feedback','userId',v_actor));
    v_replacements:=jsonb_build_array(jsonb_build_object(
      'component','private_feedback','userId',v_actor,
      'payload',public.get_private_feedback_payload_v1(p_occasion,v_actor)));
  END IF;
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'feedback.delete','feedback',jsonb_build_array(jsonb_build_object(
      'entityType','event_feedback','entityId',v_before.id,'operation','delete',
      'safeLabel','Event feedback','changedFields',jsonb_build_array('aggregate'))),
    '{}',v_private_impacts,'[]',jsonb_build_object('deleted',true),
    '{}','[]',CASE WHEN v_actor IS NULL THEN 'unknown' ELSE 'user' END,NULL,
    v_replacements);
END; $function$

CREATE OR REPLACE FUNCTION public.delete_event_feedback_for_edit_client_sync_v1(p_occasion bigint, p_feedback bigint, p_command_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
    v_actor uuid := auth.uid();
    v_organization bigint;
    v_begin jsonb;
    v_hash text;
    v_feedback public.event_feedback%ROWTYPE;
    v_private_impacts jsonb := '[]'::jsonb;
    v_replacements jsonb := '[]'::jsonb;
BEGIN
    SELECT o.organization
    INTO v_organization
    FROM public.occasions o
    WHERE o.id = p_occasion;

    IF v_actor IS NULL
       OR v_organization IS NULL
       OR NOT public.check_is_admin_of_organization(v_organization) THEN
        RAISE insufficient_privilege
            USING MESSAGE = 'occasion admin required';
    END IF;

    v_hash := encode(extensions.digest(convert_to(jsonb_build_object(
        'occasion', p_occasion,
        'feedback', p_feedback
    )::text, 'UTF8'), 'sha256'), 'hex');
    v_begin := public.begin_client_mutation_v1(
        p_command_id,
        'feedback.admin_delete',
        p_occasion,
        v_actor,
        v_hash
    );
    IF v_begin->>'disposition' = 'replay' THEN
        RETURN v_begin->'response';
    END IF;

    SELECT f.*
    INTO v_feedback
    FROM public.event_feedback f
    WHERE f.id = p_feedback
      AND f.occasion = p_occasion
    FOR UPDATE;

    IF NOT FOUND THEN
        RETURN public.complete_client_mutation_outcome_v1(
            p_command_id,
            'unchanged',
            200,
            jsonb_build_object('deleted', false)
        );
    END IF;

    DELETE FROM public.event_feedback
    WHERE id = v_feedback.id;

    IF v_feedback."user" IS NOT NULL AND EXISTS (
        SELECT 1
        FROM public.occasion_users ou
        WHERE ou.occasion = p_occasion
          AND ou."user" = v_feedback."user"
    ) THEN
        v_private_impacts := jsonb_build_array(jsonb_build_object(
            'component', 'private_feedback',
            'userId', v_feedback."user"
        ));
        IF v_feedback."user" = v_actor THEN
            v_replacements := jsonb_build_array(jsonb_build_object(
                'component', 'private_feedback',
                'userId', v_actor,
                'payload', public.get_private_feedback_payload_v1(
                    p_occasion,
                    v_actor
                )
            ));
        END IF;
    END IF;

    RETURN public.complete_client_mutation_applied_v1(
        p_command_id,
        p_occasion,
        'feedback.admin_delete',
        'feedback',
        jsonb_build_array(jsonb_build_object(
            'entityType', 'event_feedback',
            'entityId', v_feedback.id,
            'operation', 'delete',
            'safeLabel', 'Event feedback',
            'changedFields', jsonb_build_array('aggregate')
        )),
        '{}'::text[],
        v_private_impacts,
        '[]'::jsonb,
        jsonb_build_object('deleted', true),
        '{}'::text[],
        '[]'::jsonb,
        'user',
        NULL,
        v_replacements
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.delete_event_feedback_internal_v1(p_event bigint, p_client_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
    v_user UUID := auth.uid();
    v_deleted INTEGER := 0;
BEGIN
    IF v_user IS NULL AND p_client_id IS NULL THEN
        RETURN jsonb_build_object('code', 401, 'message', 'Client id is required for anonymous feedback');
    END IF;

    IF v_user IS NOT NULL THEN
        DELETE FROM public.event_feedback
        WHERE event = p_event
          AND "user" = v_user;
    ELSE
        DELETE FROM public.event_feedback
        WHERE event = p_event
          AND "user" IS NULL
          AND client_id = p_client_id;
    END IF;

    GET DIAGNOSTICS v_deleted = ROW_COUNT;

    RETURN jsonb_build_object(
        'code', 200,
        'data', jsonb_build_object('deleted', v_deleted)
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.delete_events_domain_internal_v1(p_occasion bigint, p_ids bigint[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE children bigint[]; groups bigint[]; had_speakers boolean; deleted integer;
BEGIN
 IF EXISTS(SELECT 1 FROM public.events WHERE id=ANY(p_ids) AND occasion<>p_occasion) THEN
  RAISE insufficient_privilege USING MESSAGE='event deletion outside occasion'; END IF;
 children:=public.lock_event_deletion_scope_internal_v1(p_occasion,p_ids);
 SELECT ARRAY(SELECT DISTINCT "group" FROM public.exclusive_events WHERE event=ANY(p_ids) ORDER BY "group") INTO groups;
 IF EXISTS(SELECT 1 FROM public.exclusive_groups WHERE id=ANY(groups) AND occasion<>p_occasion) THEN RAISE insufficient_privilege USING MESSAGE='exclusive group outside occasion'; END IF;
 PERFORM 1 FROM public.exclusive_groups WHERE id=ANY(groups) ORDER BY id FOR UPDATE;
 SELECT EXISTS(SELECT 1 FROM public.event_speakers WHERE event=ANY(p_ids)) INTO had_speakers;
 DELETE FROM public.event_users WHERE event=ANY(p_ids);
 DELETE FROM public.event_users_saved WHERE event=ANY(p_ids);
 DELETE FROM public.exclusive_events WHERE event=ANY(p_ids);
 DELETE FROM public.event_roles WHERE event=ANY(p_ids);
 DELETE FROM public.event_groups WHERE event_parent=ANY(p_ids) OR event_child=ANY(p_ids);
 DELETE FROM public.event_speakers WHERE event=ANY(p_ids);
 DELETE FROM public.events WHERE id=ANY(p_ids) AND occasion=p_occasion;
 GET DIAGNOSTICS deleted=ROW_COUNT;
 INSERT INTO public.client_aggregate_versions(aggregate_type,scope_type,scope_id,aggregate_id,version)
 SELECT 'event','occasion',p_occasion,id::text,1 FROM unnest(children) id
 ON CONFLICT(aggregate_type,scope_type,scope_id,aggregate_id) DO UPDATE
 SET version=public.client_aggregate_versions.version+1,updated_at=clock_timestamp();
 INSERT INTO public.client_aggregate_versions(aggregate_type,scope_type,scope_id,aggregate_id,version)
 SELECT 'exclusive_group','occasion',p_occasion,id::text,1 FROM unnest(groups) id
 ON CONFLICT(aggregate_type,scope_type,scope_id,aggregate_id) DO UPDATE
 SET version=public.client_aggregate_versions.version+1,updated_at=clock_timestamp();
 DELETE FROM public.client_aggregate_versions WHERE aggregate_type='event' AND scope_type='occasion' AND scope_id=p_occasion AND aggregate_id=ANY(ARRAY(SELECT id::text FROM unnest(p_ids) id));
 RETURN jsonb_build_object('deleted',deleted,'childIds',to_jsonb(children),'exclusiveGroupIds',to_jsonb(groups),'hadSpeakers',had_speakers);
END $function$

CREATE OR REPLACE FUNCTION public.delete_exclusive_group_client_sync_v1(p_occasion bigint, p_group_id bigint, p_command_id uuid, p_expected_version bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_version bigint; v_begin jsonb; v_hash text;
  v_entity jsonb;
BEGIN
  IF v_actor IS NULL OR NOT public.get_is_editor_on_occasion(p_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion editor required'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'occasion',p_occasion,'groupId',p_group_id,
    'expectedVersion',p_expected_version)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'schedule.exclusive_group.delete',
    p_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  PERFORM 1 FROM public.exclusive_groups g WHERE g.id=p_group_id
    AND g.occasion=p_occasion FOR UPDATE;
  IF NOT FOUND THEN RETURN public.complete_client_mutation_outcome_v1(
    p_command_id,'unchanged',200,jsonb_build_object('version',0,'group',NULL)); END IF;
  INSERT INTO public.client_aggregate_versions
    (aggregate_type,scope_type,scope_id,aggregate_id,version)
  VALUES ('exclusive_group','occasion',p_occasion,p_group_id::text,0)
  ON CONFLICT DO NOTHING;
  SELECT version INTO v_version FROM public.client_aggregate_versions
    WHERE aggregate_type='exclusive_group' AND scope_type='occasion'
    AND scope_id=p_occasion AND aggregate_id=p_group_id::text FOR UPDATE;
  v_entity:=public.get_exclusive_group_command_data_v1(p_group_id);
  IF p_expected_version IS DISTINCT FROM v_version THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'conflict',409,
      jsonb_build_object('version',v_version,'group',v_entity)); END IF;
  DELETE FROM public.exclusive_events WHERE "group"=p_group_id;
  DELETE FROM public.exclusive_groups WHERE id=p_group_id;
  DELETE FROM public.client_aggregate_versions WHERE aggregate_type='exclusive_group'
    AND scope_type='occasion' AND scope_id=p_occasion AND aggregate_id=p_group_id::text;
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'schedule.exclusive_group.delete','schedule_constraints',
    jsonb_build_array(jsonb_build_object('entityType','exclusive_group',
      'entityId',p_group_id,'operation','delete','safeLabel',left(v_entity->>'title',240),
      'changedFields',jsonb_build_array('aggregate'))),
    '{}','[]','[]',jsonb_build_object('version',v_version,'group',NULL));
END; $function$

CREATE OR REPLACE FUNCTION public.delete_form_domain_command_internal_v1(p_form_id bigint, p_command_id uuid, p_expected_version bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE actor uuid:=auth.uid(); oc bigint; title text; begin_result jsonb; hash text; version bigint; used bigint; original_key uuid;
BEGIN
 SELECT occasion INTO oc FROM public.client_mutation_receipts WHERE command_id=p_command_id AND actor_id=actor AND command_name='inventory.form.delete';
 IF NOT FOUND THEN SELECT t.occasion INTO oc FROM public.forms t WHERE id=p_form_id; END IF;
 IF actor IS NULL OR oc IS NULL OR (public.get_is_editor_on_occasion(oc) OR public.get_is_editor_on_unit((SELECT unit FROM public.occasions WHERE id=oc))) IS NOT TRUE THEN RAISE insufficient_privilege USING MESSAGE='form editor required'; END IF;
 hash:=encode(extensions.digest(convert_to((jsonb_build_object('formId',p_form_id)||CASE WHEN p_expected_version IS NULL THEN '{}'::jsonb ELSE jsonb_build_object('expectedVersion',p_expected_version) END)::text,'UTF8'),'sha256'),'hex');
 begin_result:=public.begin_client_mutation_v1(p_command_id,'inventory.form.delete',oc,actor,hash);
 IF begin_result->>'disposition'='replay' THEN RETURN begin_result->'response'; END IF;
 PERFORM 1 FROM public.forms WHERE occasion=oc ORDER BY id FOR UPDATE;
 PERFORM 1 FROM eshop.product_types WHERE occasion=oc ORDER BY id FOR UPDATE;
 SELECT t.title,t.key INTO title,original_key FROM public.forms t WHERE id=p_form_id AND occasion=oc FOR UPDATE;
 IF NOT FOUND THEN RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',404,jsonb_build_object('formId',p_form_id)); END IF;
 SELECT coalesce(v.version,0) INTO version FROM (SELECT 1) seed LEFT JOIN public.client_aggregate_versions v
 ON v.aggregate_type='form' AND v.scope_type='occasion' AND v.scope_id=oc AND v.aggregate_id=p_form_id::text;
 IF p_expected_version IS NOT NULL AND p_expected_version IS DISTINCT FROM version THEN RETURN public.complete_client_mutation_outcome_v1(p_command_id,'conflict',409,jsonb_build_object('aggregate_version',version)); END IF;
 SELECT count(*) INTO used FROM eshop.orders WHERE form=p_form_id OR data->>'form'=original_key::text;
 IF used>0 THEN RETURN public.complete_client_mutation_outcome_v1(p_command_id,'conflict',409,jsonb_build_object('message','form is in use')); END IF;
 PERFORM public.delete_form_internal_v1(p_form_id);
 DELETE FROM public.client_aggregate_versions WHERE aggregate_type='form' AND scope_type='occasion' AND scope_id=oc AND aggregate_id=p_form_id::text;
 RETURN public.complete_private_inventory_mutation_v1(p_command_id,oc,'inventory.form.delete',jsonb_build_array(jsonb_build_object('entityType','form','entityId',p_form_id,'operation','delete','safeLabel',left(title,240),'changedFields',jsonb_build_array('aggregate'))),'{}'::uuid[],jsonb_build_object('formId',p_form_id));
END $function$

CREATE OR REPLACE FUNCTION public.delete_form_internal_v1(p_form_id bigint)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
    v_response_count INT;
    v_form_key UUID;
    v_product_type_ids_to_check BIGINT[];
    v_deletable_product_type_ids BIGINT[];
BEGIN
    -- Step 1: Check if the form has any responses. If so, prevent deletion.
    -- This part of the logic remains unchanged.
    SELECT key INTO v_form_key FROM public.forms WHERE id = p_form_id;

    IF v_form_key IS NOT NULL THEN
        SELECT COUNT(*)
        INTO v_response_count
        FROM eshop.orders
        WHERE (data->>'form')::uuid = v_form_key;

        IF v_response_count > 0 THEN
            RAISE EXCEPTION 'This form cannot be deleted because it has responses.';
        END IF;
    END IF;

    -- Step 2: Collect all product_type IDs associated with this form's fields.
    -- We need this list to attempt a cleanup after deleting the fields.
    SELECT ARRAY_AGG(DISTINCT product_type)
    INTO v_product_type_ids_to_check
    FROM public.form_fields
    WHERE form = p_form_id AND product_type IS NOT NULL;

    PERFORM 1 FROM public.occasions WHERE id=(SELECT occasion FROM public.forms WHERE id=p_form_id) FOR UPDATE;
    IF EXISTS(SELECT 1 FROM eshop.product_types pt WHERE pt.id=ANY(v_product_type_ids_to_check) AND public.ticket_layout_uses_product_type(pt.occasion,pt.id) AND NOT EXISTS(SELECT 1 FROM eshop.products p WHERE p.product_type=pt.id) AND NOT EXISTS(SELECT 1 FROM public.form_fields ff WHERE ff.product_type=pt.id AND ff.form<>p_form_id))
    THEN RAISE EXCEPTION 'ticket_product_type_in_use'; END IF;
    -- Step 3: Delete the form fields unconditionally (after the response check).
    -- This severs the link from the form to the product types, fulfilling the
    -- requirement to "delete field anyway".
    DELETE FROM public.form_fields WHERE form = p_form_id;

    -- Step 4: Attempt to clean up the product types that were associated with the form.
    -- We will only delete product types that are not referenced by any existing products.
    IF v_product_type_ids_to_check IS NOT NULL AND array_length(v_product_type_ids_to_check, 1) > 0 THEN
        -- From our list of candidates, find which ones are NOT used by any products.
        SELECT ARRAY_AGG(pt.id)
        INTO v_deletable_product_type_ids
        FROM unnest(v_product_type_ids_to_check) AS pt(id)
        WHERE NOT EXISTS (
            SELECT 1
            FROM eshop.products p
            WHERE p.product_type = pt.id
        ) AND NOT EXISTS(SELECT 1 FROM public.form_fields ff WHERE ff.product_type=pt.id);

        -- If we found any deletable product types, delete them.
        IF v_deletable_product_type_ids IS NOT NULL AND array_length(v_deletable_product_type_ids, 1) > 0 THEN
            DELETE FROM eshop.product_types
            WHERE id = ANY(v_deletable_product_type_ids);
        END IF;
    END IF;

    -- Step 5: Finally, delete the form itself.
    DELETE FROM public.forms WHERE id = p_form_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.delete_form_ws_obsolete_v1(p_form_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
    result jsonb;
    v_occasion_id bigint;
    v_unit_id bigint;
BEGIN
    BEGIN
        -- Fetch occasion and unit details to check permissions
        SELECT f.occasion, o.unit
        INTO v_occasion_id, v_unit_id
        FROM public.forms f
        JOIN public.occasions o ON f.occasion = o.id
        WHERE f.id = p_form_id;

        IF NOT FOUND THEN
             RAISE EXCEPTION '%',
                JSONB_BUILD_OBJECT('code', 4040, 'message', 'Form not found')::TEXT;
        END IF;

        -- Perform the required permission checks
        IF NOT (
            (SELECT get_is_editor_on_unit(v_unit_id)) OR
            (SELECT get_is_editor_on_occasion(v_occasion_id))
        ) THEN
            RAISE EXCEPTION '%',
                JSONB_BUILD_OBJECT('code', 4030, 'message', 'Permission denied to delete this form.')::TEXT;
        END IF;

        -- Call the internal function to perform the deletion
        PERFORM delete_form(p_form_id);

        -- Build the success response for the client
        result := JSONB_BUILD_OBJECT(
            'code', 200,
            'message', 'Form deleted successfully'
        );

    EXCEPTION WHEN OTHERS THEN
        -- Catch any exceptions and format them
        result := CASE
            WHEN left(SQLERRM, 1) = '{' THEN SQLERRM::JSONB
            ELSE JSONB_BUILD_OBJECT('code', 5000, 'message', SQLERRM)
        END;
    END;
    RETURN result;
END;
$function$

CREATE OR REPLACE FUNCTION public.delete_icon(p_icon_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE u bigint; r jsonb;
BEGIN
 SELECT unit INTO u FROM public.icons WHERE id=p_icon_id;
 IF NOT FOUND THEN RETURN jsonb_build_object('code',200); END IF;
 IF u IS NULL OR auth.uid() IS NULL OR NOT public.get_is_editor_on_unit(u) THEN RETURN jsonb_build_object('code',403); END IF;
 r:=public.delete_unit_icon_client_sync_v1(u,p_icon_id,extensions.gen_random_uuid());
 RETURN jsonb_build_object('code',r->'code','refs',r#>'{data,refs}');
END $function$

CREATE OR REPLACE FUNCTION public.delete_icon_client_sync_v1(p_occasion bigint, p_icon_id bigint, p_command_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE u bigint; old_receipt jsonb; old_hash text;
BEGIN
 SELECT unit INTO u FROM public.occasions WHERE id=p_occasion;
 IF u IS NULL THEN RAISE invalid_parameter_value USING MESSAGE='occasion unit required'; END IF;
 -- Preserve receipts produced by the former occasion-scoped command.
 IF EXISTS(SELECT 1 FROM public.client_mutation_receipts WHERE command_id=p_command_id
   AND command_name='map.icon.delete') THEN
  IF auth.uid() IS NULL OR NOT public.get_is_editor_on_unit(u) THEN
   RAISE insufficient_privilege USING MESSAGE='unit editor required'; END IF;
  old_hash:=encode(extensions.digest(convert_to(jsonb_build_object('occasion',p_occasion,'iconId',p_icon_id)::text,'UTF8'),'sha256'),'hex');
  old_receipt:=public.begin_client_mutation_v1(p_command_id,'map.icon.delete',p_occasion,auth.uid(),old_hash);
  IF old_receipt->>'disposition'='replay' THEN RETURN old_receipt->'response'; END IF;
  RAISE serialization_failure USING MESSAGE='incomplete legacy icon intent';
 END IF;
 RETURN public.delete_unit_icon_client_sync_v1(u,p_icon_id,p_command_id);
END $function$

CREATE OR REPLACE FUNCTION public.delete_information_client_sync_v1(p_occasion bigint, p_information_id bigint, p_command_id uuid, p_expected_version bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_actor uuid:=auth.uid(); v_version bigint; v_hidden_id bigint;
  v_entity jsonb; v_begin jsonb; v_hash text; v_commit jsonb; v_public jsonb;
  v_response jsonb; v_is_publishable boolean; v_is_hidden boolean;
BEGIN
  IF v_actor IS NULL OR NOT public.get_is_editor_on_occasion(p_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion editor required';
  END IF;
  SELECT NOT o.is_hidden INTO v_is_publishable FROM public.occasions o
    WHERE o.id=p_occasion;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object('occasion',p_occasion,
    'informationId',p_information_id,'expectedVersion',p_expected_version)::text,
    'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'content.information.delete',
    p_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  SELECT public.get_information_command_data_v1(i.id),i.information_hidden,i.is_hidden
    INTO v_entity,v_hidden_id,v_is_hidden FROM public.information i
    WHERE i.id=p_information_id AND i.occasion=p_occasion FOR UPDATE;
  IF v_entity IS NULL THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,
      'unchanged',200,jsonb_build_object('version',0,'information',NULL));
  END IF;
  INSERT INTO public.client_aggregate_versions
    (aggregate_type,scope_type,scope_id,aggregate_id,version)
  VALUES ('information','occasion',p_occasion,p_information_id::text,0)
  ON CONFLICT DO NOTHING;
  SELECT version INTO v_version FROM public.client_aggregate_versions
    WHERE aggregate_type='information' AND scope_type='occasion'
    AND scope_id=p_occasion AND aggregate_id=p_information_id::text FOR UPDATE;
  IF p_expected_version IS DISTINCT FROM v_version THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,
      'conflict',409,jsonb_build_object('version',v_version,
        'information',v_entity));
  END IF;
  DELETE FROM public.information WHERE id=p_information_id;
  IF v_hidden_id IS NOT NULL THEN
    DELETE FROM public.information_hidden WHERE id=v_hidden_id AND occasion=p_occasion;
  END IF;
  DELETE FROM public.client_aggregate_versions WHERE aggregate_type='information'
    AND scope_type='occasion' AND scope_id=p_occasion
    AND aggregate_id=p_information_id::text;
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'content.information.delete','content',jsonb_build_array(jsonb_build_object(
      'entityType','information','entityId',p_information_id,'operation','delete',
      'safeLabel',left(v_entity->>'title',240),
      'changedFields',jsonb_build_array('aggregate'))),
    CASE WHEN v_is_publishable AND NOT v_is_hidden THEN ARRAY['content_catalog']
      ELSE '{}'::text[] END,'[]','[]',
    jsonb_build_object('version',v_version,'information',NULL));
END; $function$

CREATE OR REPLACE FUNCTION public.delete_inventory_pool(p_inventory_pool_id bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE oc bigint; v bigint; result jsonb;
BEGIN
 SELECT occasion INTO oc FROM public.inventory_pools WHERE id=p_inventory_pool_id;
 PERFORM public.check_is_editor_order_on_occasion(oc);

 PERFORM public.lock_pool_product_dependencies_internal_v1(p_inventory_pool_id);
 PERFORM 1 FROM public.inventory_pools WHERE id=p_inventory_pool_id FOR UPDATE;
 SELECT coalesce((SELECT version FROM public.client_aggregate_versions WHERE aggregate_type='inventory_pool' AND scope_type='occasion' AND scope_id=oc AND aggregate_id=p_inventory_pool_id::text),0) INTO v;
 result:=public.delete_inventory_pool_client_sync_v1(oc,p_inventory_pool_id,extensions.gen_random_uuid(),v);
 IF result->>'code'<>'200' THEN RAISE serialization_failure USING MESSAGE='inventory deletion rejected'; END IF;
END $function$

CREATE OR REPLACE FUNCTION public.delete_inventory_pool_client_sync_v1(p_occasion bigint, p_pool bigint, p_command_id uuid, p_expected_version bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_version bigint; v_title text; v_begin jsonb;
  v_hash text; v_reserved bigint; v_impacts jsonb;
  v_product_ids bigint[]; v_product_id bigint;
  v_replacements jsonb:='[]'::jsonb;
BEGIN
  IF v_actor IS NULL OR NOT public.get_is_editor_order_on_occasion(p_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion order editor required'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object('occasion',p_occasion,
    'poolId',p_pool,'expectedVersion',p_expected_version)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'inventory.pool.delete',
    p_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  v_product_ids:=public.lock_pool_product_dependencies_internal_v1(p_pool);
  SELECT ip.title INTO v_title FROM public.inventory_pools ip WHERE ip.id=p_pool
    AND ip.occasion=p_occasion FOR UPDATE;
  IF v_title IS NULL THEN RETURN public.complete_client_mutation_outcome_v1(
    p_command_id,'unchanged',200,jsonb_build_object('version',0,'pool',NULL)); END IF;
  PERFORM 1 FROM public.inventory_contexts ic WHERE ic.inventory_pool=p_pool
    ORDER BY ic.id FOR UPDATE;
  PERFORM 1 FROM public.resources r WHERE r.inventory_pool=p_pool
    ORDER BY r.id FOR UPDATE;
  PERFORM 1 FROM eshop.spots s WHERE s.inventory_context IN (
    SELECT ic.id FROM public.inventory_contexts ic WHERE ic.inventory_pool=p_pool)
    OR s.resource IN (SELECT r.id FROM public.resources r WHERE r.inventory_pool=p_pool) OR s.resource_slot IN (SELECT rs.id FROM public.resource_slots rs JOIN public.resources r ON r.id=rs.resource WHERE r.inventory_pool=p_pool)
    ORDER BY s.id FOR UPDATE;
  INSERT INTO public.client_aggregate_versions
    (aggregate_type,scope_type,scope_id,aggregate_id,version)
  VALUES ('inventory_pool','occasion',p_occasion,p_pool::text,0) ON CONFLICT DO NOTHING;
  SELECT version INTO v_version FROM public.client_aggregate_versions
    WHERE aggregate_type='inventory_pool' AND scope_type='occasion'
      AND scope_id=p_occasion AND aggregate_id=p_pool::text FOR UPDATE;
  IF p_expected_version IS DISTINCT FROM v_version THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'conflict',409,
      jsonb_build_object('version',v_version,'poolId',p_pool)); END IF;
  SELECT count(*) INTO v_reserved FROM eshop.spots s
    WHERE (s.order_product_ticket IS NOT NULL OR (s.secret IS NOT NULL AND s.secret_expiration_time>clock_timestamp())) AND (s.inventory_context IN (
      SELECT ic.id FROM public.inventory_contexts ic WHERE ic.inventory_pool=p_pool)
      OR s.resource IN (SELECT r.id FROM public.resources r WHERE r.inventory_pool=p_pool) OR s.resource_slot IN (SELECT rs.id FROM public.resource_slots rs JOIN public.resources r ON r.id=rs.resource WHERE r.inventory_pool=p_pool));
  IF v_reserved>0 THEN RETURN public.complete_client_mutation_outcome_v1(
    p_command_id,'rejected',409,jsonb_build_object('version',v_version,
      'poolId',p_pool,'message','inventory pool has reserved spots')); END IF;
  DELETE FROM eshop.spots s WHERE s.order_product_ticket IS NULL AND (
    s.inventory_context IN (SELECT ic.id FROM public.inventory_contexts ic
      WHERE ic.inventory_pool=p_pool) OR s.resource IN (
      SELECT r.id FROM public.resources r WHERE r.inventory_pool=p_pool) OR s.resource_slot IN (
      SELECT rs.id FROM public.resource_slots rs JOIN public.resources r ON r.id=rs.resource WHERE r.inventory_pool=p_pool));
  DELETE FROM public.client_aggregate_versions v WHERE v.scope_type='occasion'
    AND v.scope_id=p_occasion AND ((v.aggregate_type='resource' AND v.aggregate_id IN (
      SELECT r.id::text FROM public.resources r WHERE r.inventory_pool=p_pool))
      OR (v.aggregate_type='inventory_pool' AND v.aggregate_id=p_pool::text));
  DELETE FROM public.resources WHERE inventory_pool=p_pool;
  DELETE FROM public.inventory_contexts WHERE inventory_pool=p_pool;
  DELETE FROM public.inventory_pools WHERE id=p_pool;
  FOREACH v_product_id IN ARRAY v_product_ids LOOP
    PERFORM public.advance_ticketing_authoring_version_internal_v1('product',p_occasion,v_product_id);
  END LOOP;
  SELECT COALESCE(jsonb_agg(jsonb_build_object('component','private_inventory',
    'userId',ou."user")),'[]'::jsonb) INTO v_impacts
    FROM public.occasion_users ou WHERE ou.occasion=p_occasion;
  IF EXISTS (SELECT 1 FROM public.occasion_users ou WHERE ou.occasion=p_occasion
    AND ou."user"=v_actor) THEN v_replacements:=jsonb_build_array(jsonb_build_object(
      'component','private_inventory','userId',v_actor,
      'payload',public.get_user_inventory_for_occasion_v1(p_occasion))); END IF;
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'inventory.pool.delete','inventory',jsonb_build_array(jsonb_build_object(
      'entityType','inventory_pool','entityId',p_pool,'operation','delete',
      'safeLabel',left(v_title,240),'changedFields',jsonb_build_array('aggregate'))),
    '{}',v_impacts,'[]',jsonb_build_object('version',v_version,'pool',NULL),
    '{}','[]','user',NULL,v_replacements);
END; $function$

CREATE OR REPLACE FUNCTION public.delete_manual_transaction_ws(p_transaction_id bigint, p_payment_info_id bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_bank_account_id bigint;
  v_occasion_id bigint;
BEGIN
  SELECT pi.bank_account, o.occasion INTO v_bank_account_id, v_occasion_id
  FROM eshop.payment_info pi
  JOIN eshop.orders o ON o.payment_info = pi.id
  WHERE pi.id = p_payment_info_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'PAYMENT_INFO_NOT_FOUND'; END IF;
  PERFORM public.check_is_admin_for_bank_account(v_bank_account_id);
  PERFORM public.check_is_editor_order_on_occasion(v_occasion_id);
  IF NOT EXISTS (SELECT 1 FROM eshop.transactions t
    WHERE t.id = p_transaction_id AND t.payment_info = p_payment_info_id
      AND t.transaction_type = 'manual') THEN
    RAISE EXCEPTION 'MANUAL_TRANSACTION_PAIRING_MISMATCH';
  END IF;

  PERFORM public.apply_transaction_pairing(
    p_transaction_id, NULL, 'manual_delete_unlink', 'user'
  );
  INSERT INTO eshop.transaction_pairing_events (
    transaction_snapshot_id, transaction_id, old_payment_info_id,
    new_payment_info_id, action, method, actor_id, actor_kind
  ) VALUES (
    p_transaction_id, p_transaction_id, p_payment_info_id,
    NULL, 'manual_deleted', 'manual_delete', auth.uid(), 'user'
  );
  DELETE FROM eshop.transactions WHERE id = p_transaction_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.delete_news_client_sync_v1(p_occasion bigint, p_news_id bigint, p_command_id uuid, p_expected_version bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_actor uuid:=auth.uid(); v_version bigint; v_begin jsonb; v_hash text;
  v_entity jsonb; v_previous_id bigint; v_private_impacts jsonb;
  v_is_publishable boolean;
BEGIN
  IF v_actor IS NULL OR NOT public.get_is_editor_on_occasion(p_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion editor required';
  END IF;
  SELECT NOT o.is_hidden INTO v_is_publishable FROM public.occasions o
    WHERE o.id=p_occasion;
  IF v_is_publishable IS NULL THEN
    RAISE invalid_parameter_value USING MESSAGE='occasion not found';
  END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object('occasion',p_occasion,
    'newsId',p_news_id,'expectedVersion',p_expected_version)::text,'UTF8'),
    'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'content.news.delete',
    p_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  SELECT to_jsonb(n) INTO v_entity FROM public.news n
    WHERE n.id=p_news_id AND n.occasion=p_occasion FOR UPDATE;
  IF v_entity IS NULL THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,
      'unchanged',200,jsonb_build_object('version',0,'news',NULL));
  END IF;
  INSERT INTO public.client_aggregate_versions
    (aggregate_type,scope_type,scope_id,aggregate_id,version)
  VALUES ('news','occasion',p_occasion,p_news_id::text,0) ON CONFLICT DO NOTHING;
  SELECT version INTO v_version FROM public.client_aggregate_versions
    WHERE aggregate_type='news' AND scope_type='occasion'
    AND scope_id=p_occasion AND aggregate_id=p_news_id::text FOR UPDATE;
  IF p_expected_version IS DISTINCT FROM v_version THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,
      'conflict',409,jsonb_build_object('version',v_version,'news',v_entity));
  END IF;
  SELECT n.id INTO v_previous_id FROM public.news n
    WHERE n.occasion=p_occasion AND n.id<p_news_id ORDER BY n.id DESC LIMIT 1;
  SELECT COALESCE(jsonb_agg(jsonb_build_object('component','private_news',
    'userId',un."user")),'[]'::jsonb) INTO v_private_impacts
  FROM public.user_news un JOIN public.occasion_users ou
    ON ou.occasion=p_occasion AND ou."user"=un."user"
  WHERE un.occasion=p_occasion AND un.news_id=p_news_id;
  IF v_previous_id IS NULL THEN
    DELETE FROM public.user_news WHERE occasion=p_occasion AND news_id=p_news_id;
  ELSE
    UPDATE public.user_news SET news_id=v_previous_id
      WHERE occasion=p_occasion AND news_id=p_news_id;
  END IF;
  DELETE FROM public.news WHERE id=p_news_id;
  DELETE FROM public.client_aggregate_versions WHERE aggregate_type='news'
    AND scope_type='occasion' AND scope_id=p_occasion
    AND aggregate_id=p_news_id::text;
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'content.news.delete','content',jsonb_build_array(jsonb_build_object(
      'entityType','news','entityId',p_news_id,'operation','delete',
      'safeLabel','News','changedFields',jsonb_build_array('aggregate'))),
    CASE WHEN v_is_publishable THEN ARRAY['content_catalog'] ELSE '{}'::text[] END,
    v_private_impacts,'[]',jsonb_build_object('version',v_version,'news',NULL));
END; $function$

CREATE OR REPLACE FUNCTION public.delete_occasion_domain_command_internal_v1(p_occasion bigint, p_command_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_unit bigint; v_title text; v_begin jsonb;
  v_attempt int;
  v_hash text; v_commit public.client_commits%ROWTYPE;
BEGIN
  IF v_actor IS NULL THEN RAISE insufficient_privilege USING MESSAGE='unit manager required'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object('occasion',p_occasion)::text,'UTF8'),'sha256'),'hex');
  -- A second lookup covers a concurrent delete that committed while our row
  -- lock was waiting. Tombstones retain actor, unit and exact request binding.
  FOR v_attempt IN 1..2 LOOP
    SELECT r.unit INTO v_unit FROM public.client_mutation_receipts r WHERE r.command_id=p_command_id
      AND r.actor_id=v_actor AND r.command_name='occasion.delete' AND r.request_sha256=v_hash AND r.occasion IS NULL;
    IF FOUND THEN
      v_begin:=public.begin_unit_client_mutation_v1(p_command_id,'occasion.delete',v_unit,v_actor,v_hash);
      IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
    END IF;
    PERFORM 1 FROM public.forms WHERE occasion=p_occasion ORDER BY id FOR UPDATE;
    PERFORM 1 FROM eshop.product_types WHERE occasion=p_occasion ORDER BY id FOR UPDATE;
    PERFORM 1 FROM eshop.products WHERE occasion=p_occasion ORDER BY id FOR UPDATE;
    SELECT o.unit,o.title INTO v_unit,v_title FROM public.occasions o WHERE o.id=p_occasion FOR UPDATE;
    EXIT WHEN FOUND;
  END LOOP;
  IF v_unit IS NULL OR NOT public.get_is_manager_on_unit(v_unit) THEN
    RAISE insufficient_privilege USING MESSAGE='unit manager required'; END IF;
  IF EXISTS(SELECT 1 FROM public.occasions WHERE id=p_occasion AND coalesce((data->>'client_sync_v1')::boolean,false)) THEN
    RAISE object_not_in_prerequisite_state USING MESSAGE='disable client_sync_v1 before deleting occasion'; END IF;
  v_begin:=public.begin_unit_client_mutation_v1(p_command_id,
    'occasion.delete',v_unit,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  PERFORM public.delete_occasion_internal_v1(p_occasion);
  DELETE FROM public.client_sync_scopes WHERE scope_type='occasion'
    AND scope_id=p_occasion;
  DELETE FROM public.client_projection_dirty_keys WHERE scope_type='occasion'
    AND scope_id=p_occasion;
  DELETE FROM public.client_aggregate_versions WHERE scope_type='occasion'
    AND scope_id=p_occasion;
  DELETE FROM public.client_sync_public_heads WHERE scope_type='occasion'
    AND scope_id=p_occasion;
  INSERT INTO public.client_commits
    (unit,actor_id,actor_display,actor_kind,source,change_class)
  SELECT v_unit,v_actor,nullif(concat_ws(' ',ui.name,ui.surname),''),'user',
    'occasion.delete','configuration' FROM public.user_info ui WHERE ui.id=v_actor
  RETURNING * INTO v_commit;
  INSERT INTO public.client_commit_items
    (commit_id,item_index,entity_type,entity_id,operation,safe_label,changed_fields)
  VALUES (v_commit.commit_id,0,'occasion',p_occasion::text,'delete',
    left(v_title,240),ARRAY['aggregate']);
  PERFORM public.fanout_unit_catalog_v1(v_commit.commit_id,v_unit);
  RETURN public.finish_client_mutation_v1(p_command_id,jsonb_build_object(
    'status','applied','code',200,'data',jsonb_build_object('occasionId',p_occasion),
    'mutation',jsonb_build_object('commandId',p_command_id,'receiptId',p_command_id,
      'commitId',v_commit.commit_id,'replayed',false,'occurredAt',v_commit.occurred_at),
    'sync',jsonb_build_object('replacements','[]'::jsonb)),v_commit.commit_id);
END; $function$

CREATE OR REPLACE FUNCTION public.delete_occasion_internal_v1(oc bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
    unit_id BIGINT;
BEGIN
  PERFORM public.check_occasion_writable(oc);

  SELECT unit
  INTO unit_id
  FROM public.occasions
  WHERE id = oc;

  PERFORM check_is_manager_on_unit(unit_id);

-- ***********************************************************
  -- 0. SAFETY CHECK: Strict Order Check
  --    Prevent deletion if ANY order exists (even storno).
  -- ***********************************************************
  IF EXISTS (
      SELECT 1
      FROM eshop.orders
      WHERE occasion = oc
  ) THEN
      RAISE EXCEPTION 'Cannot delete occasion % because it contains orders (including storno).', oc;
  END IF;

  -- ***********************************************************
  -- 1. Delete records that depend on 'events'.
  -- ***********************************************************
  DELETE FROM public.event_groups
    WHERE event_parent IN (SELECT id FROM public.events WHERE occasion = oc)
       OR event_child  IN (SELECT id FROM public.events WHERE occasion = oc);

  DELETE FROM public.event_roles
    WHERE event IN (SELECT id FROM public.events WHERE occasion = oc);

  DELETE FROM public.event_users
    WHERE event IN (SELECT id FROM public.events WHERE occasion = oc);

  DELETE FROM public.event_users_saved
    WHERE event IN (SELECT id FROM public.events WHERE occasion = oc);

  DELETE FROM public.exclusive_events
    WHERE event IN (SELECT id FROM public.events WHERE occasion = oc);

  -- ***********************************************************
  -- 2. Delete the 'events' themselves.
  -- ***********************************************************
  DELETE FROM public.events
    WHERE occasion = oc;

  -- ***********************************************************
  -- 3. Delete 'orders' dependent records.
  -- ***********************************************************
  DELETE FROM eshop.order_product_ticket
    WHERE "order" IN (SELECT id FROM eshop.orders WHERE occasion = oc);

  DELETE FROM eshop.orders_history
    WHERE "order" IN (SELECT id FROM eshop.orders WHERE occasion = oc);

  DELETE FROM eshop.bank_account_requests
    WHERE "order" IN (SELECT id FROM eshop.orders WHERE occasion = oc);

  -- ***********************************************************
  -- 4. Delete form-related records.
  -- ***********************************************************
  DELETE FROM public.form_fields
    WHERE form IN (SELECT id FROM public.forms WHERE occasion = oc);

  DELETE FROM public.forms
    WHERE occasion = oc;

  -- ***********************************************************
  -- 5. Delete records from tables that reference the occasion directly.
  -- ***********************************************************
  DELETE FROM public.email_templates
    WHERE occasion = oc;

  DELETE FROM public.email_wrappers
    WHERE occasion = oc;

  DELETE FROM public.information
    WHERE occasion = oc;

  DELETE FROM public.information_hidden
    WHERE occasion = oc;

  DELETE FROM public.log_notifications
    WHERE occasion = oc;

  UPDATE public.email_messages SET workflow_state='cancelled',last_error='occasion_deleted',data='{}',prepared=NULL,recipient=NULL,occasion=NULL,unit=NULL
    WHERE occasion = oc;

  DELETE FROM public.log_emails
    WHERE occasion = oc;

  DELETE FROM public.news
    WHERE occasion = oc;

  DELETE FROM public.occasion_users
    WHERE occasion = oc;

  DELETE FROM public.user_news
    WHERE occasion = oc;

  DELETE FROM public.places
    WHERE occasion = oc;

  DELETE FROM public.role_info
    WHERE occasion = oc;

  DELETE FROM public.user_groups
    WHERE "group" IN (SELECT id FROM public.user_group_info WHERE occasion = oc);

  DELETE FROM public.user_group_info
    WHERE occasion = oc;

  DELETE FROM public.exclusive_groups
    WHERE occasion = oc;

  -- ***********************************************************
  -- 6. Delete remaining records from the eshop schema.
  -- ***********************************************************
  DELETE FROM eshop.tickets
    WHERE occasion = oc;

  DELETE FROM eshop.spots
    WHERE occasion = oc;

  DELETE FROM eshop.products
    WHERE occasion = oc;

  DELETE FROM eshop.product_types
    WHERE occasion = oc;

  DELETE FROM eshop.planned_changes
    WHERE occasion = oc;

  DELETE FROM eshop.bank_account_requests
    WHERE occasion = oc;

  DELETE FROM eshop.blueprints
    WHERE occasion = oc;

  -- Delete orders (Safe now: we checked for non-storno orders at step 0,
  -- and deleted dependents in step 3).
  DELETE FROM eshop.orders
    WHERE occasion = oc;

  -- ***********************************************************
  -- 7. Null out referencing images.
  -- ***********************************************************
  UPDATE public.images
    SET occasion = NULL
    WHERE occasion = oc;

  -- ***********************************************************
  -- 8. Finally, delete the occasion itself.
  -- ***********************************************************
  DELETE FROM public.occasions
    WHERE id = oc;

  RETURN;
END;
$function$

CREATE OR REPLACE FUNCTION public.delete_occasion_setup_draft(p_id uuid, p_unit bigint, p_expected_revision bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE d public.occasion_setup_drafts;
BEGIN
  IF auth.uid() IS NULL OR NOT (public.get_is_editor_on_unit(p_unit) OR public.get_is_manager_on_unit(p_unit)) THEN
    RAISE EXCEPTION 'Draft access denied' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO d FROM public.occasion_setup_drafts WHERE id = p_id FOR UPDATE;
  IF NOT FOUND THEN RETURN; END IF;
  IF d.unit <> p_unit THEN RAISE EXCEPTION 'Draft access denied' USING ERRCODE = '42501'; END IF;
  IF d.revision IS DISTINCT FROM p_expected_revision THEN
    RAISE EXCEPTION 'Draft changed in another session' USING ERRCODE = '40001';
  END IF;
  DELETE FROM public.occasion_setup_drafts WHERE id = p_id;
END $function$

CREATE OR REPLACE FUNCTION public.delete_occasion_user_client_sync_v1(p_occasion bigint, p_user uuid, p_command_id uuid, p_expected_version bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_version bigint; v_begin jsonb; v_hash text;
  v_profile jsonb; v_event_ids bigint[]; v_group_ids bigint[];
  v_private_impacts jsonb; v_publishable boolean;
  v_actor_replacements jsonb:='[]'::jsonb;
BEGIN
  IF v_actor IS NULL OR NOT (public.get_is_manager_on_occasion(p_occasion)
    OR public.get_is_admin_on_occasion(p_occasion)) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion manager required'; END IF;
  SELECT NOT o.is_hidden INTO v_publishable FROM public.occasions o WHERE o.id=p_occasion;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object('occasion',p_occasion,
    'userId',p_user,'expectedVersion',p_expected_version)::text,'UTF8'),'sha256'),'hex');
  PERFORM 1 FROM public.user_info WHERE id=p_user FOR UPDATE;
  v_begin:=public.begin_client_mutation_v1(p_command_id,'profile.user.delete',
    p_occasion,v_actor,v_hash);
  PERFORM public.lock_activity_aggregate_internal_v1(p_occasion);
  IF NOT (public.get_is_manager_on_occasion(p_occasion) OR public.get_is_admin_on_occasion(p_occasion)) THEN RAISE insufficient_privilege USING MESSAGE='occasion manager required'; END IF;
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  PERFORM 1 FROM public.occasion_users ou WHERE ou.occasion=p_occasion
    AND ou."user"=p_user FOR UPDATE;
  IF NOT FOUND THEN RETURN public.complete_client_mutation_outcome_v1(p_command_id,
    'unchanged',200,jsonb_build_object('version',0,'profile',NULL)); END IF;
  INSERT INTO public.client_aggregate_versions
    (aggregate_type,scope_type,scope_id,aggregate_id,version)
  VALUES ('occasion_user','occasion',p_occasion,p_user::text,0) ON CONFLICT DO NOTHING;
  SELECT version INTO v_version FROM public.client_aggregate_versions
    WHERE aggregate_type='occasion_user' AND scope_type='occasion'
    AND scope_id=p_occasion AND aggregate_id=p_user::text FOR UPDATE;
  v_profile:=public.get_occasion_user_command_data_v1(p_occasion,p_user);
  IF p_expected_version IS DISTINCT FROM v_version THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'conflict',409,
      jsonb_build_object('version',v_version,'profile',v_profile)); END IF;
  SELECT COALESCE(array_agg(DISTINCT e.id),'{}'::bigint[]) INTO v_event_ids
  FROM public.events e LEFT JOIN public.event_users eu ON eu.event=e.id
  LEFT JOIN public.event_users_saved es ON es.event=e.id
  WHERE e.occasion=p_occasion AND (eu."user"=p_user OR es."user"=p_user);
  SELECT COALESCE(array_agg(ug."group"),'{}'::bigint[]) INTO v_group_ids
  FROM public.user_groups ug JOIN public.user_group_info g ON g.id=ug."group"
  WHERE ug."user"=p_user AND g.occasion=p_occasion;
  v_private_impacts:=public.remove_occasion_user_domain_internal_v1(p_occasion,p_user);
  IF EXISTS (SELECT 1 FROM jsonb_array_elements(v_private_impacts) impact
    WHERE impact->>'userId'=v_actor::text) THEN
    v_actor_replacements:=jsonb_build_array(jsonb_build_object(
      'component','private_profile','userId',v_actor,
      'payload',public.get_private_profile_payload_v1(p_occasion,v_actor))); END IF;
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'profile.user.delete','profile',jsonb_build_array(jsonb_build_object(
      'entityType','occasion_user','entityId',p_user,'operation','delete',
      'safeLabel','Occasion user','changedFields',jsonb_build_array('membership'))),
    CASE WHEN v_publishable AND cardinality(v_event_ids)>0 THEN ARRAY['live_public']
      ELSE '{}'::text[] END,v_private_impacts,
    CASE WHEN v_publishable THEN COALESCE((SELECT jsonb_agg(jsonb_build_object(
      'component','live_public','entityId',id)) FROM unnest(v_event_ids) id),'[]'::jsonb)
      ELSE '[]'::jsonb END,
    jsonb_build_object('version',v_version,'profile',NULL),
    '{}','[]','user',NULL,v_actor_replacements);
END; $function$

CREATE OR REPLACE FUNCTION public.delete_occasion_user_ws(usr_to_delete uuid, occasion_id bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE version bigint; result jsonb;
BEGIN
 IF auth.uid() IS NULL OR NOT (public.get_is_manager_on_occasion(occasion_id) OR public.get_is_admin_on_occasion(occasion_id)) THEN
  RAISE insufficient_privilege USING MESSAGE='occasion manager required'; END IF;
 PERFORM 1 FROM public.user_info WHERE id=usr_to_delete FOR UPDATE;
 PERFORM public.lock_activity_aggregate_internal_v1(occasion_id);
 SELECT coalesce(v.version,0) INTO version FROM (SELECT 1) seed LEFT JOIN public.client_aggregate_versions v
 ON v.aggregate_type='occasion_user' AND v.scope_type='occasion' AND v.scope_id=occasion_id AND v.aggregate_id=usr_to_delete::text;
 result:=public.delete_occasion_user_client_sync_v1(occasion_id,usr_to_delete,extensions.gen_random_uuid(),version);
 IF result->>'code'<>'200' THEN RAISE EXCEPTION 'Profile deletion rejected'; END IF;
END $function$

CREATE OR REPLACE FUNCTION public.delete_order(order_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  payment_info_id BIGINT;
  order_product_ticket_ids BIGINT[];
  ticket_ids BIGINT[];
  order_oc BIGINT;
  unit_id BIGINT;
  is_manager BOOLEAN;
BEGIN
  -- Retrieve the order's occasion and payment_info.
  SELECT occasion, payment_info
    INTO order_oc, payment_info_id
    FROM eshop.orders
   WHERE id = order_id;

  IF order_oc IS NULL THEN
    RAISE EXCEPTION 'Order not found.';
  END IF;

  -- Check if the current user is a manager on the order's occasion.
  SELECT unit
  INTO unit_id
  FROM public.occasions
  WHERE id = order_oc;

  PERFORM check_is_manager_on_unit(unit_id);

  -- Collect all order_product_ticket IDs for the order.
  SELECT ARRAY(SELECT id FROM eshop.order_product_ticket WHERE "order" = order_id)
    INTO order_product_ticket_ids;

  -- Collect all ticket IDs from the order_product_ticket rows.
  SELECT ARRAY(SELECT ticket
                 FROM eshop.order_product_ticket
                WHERE "order" = order_id
                  AND ticket IS NOT NULL)
    INTO ticket_ids;

  -- Free any spots that reference these order_product_ticket rows:
  -- set order_product_ticket, secret, and secret_expiration_time to NULL.
  UPDATE eshop.spots
     SET order_product_ticket      = NULL,
         secret                  = NULL,
         secret_expiration_time  = NULL,
         updated_at              = NOW()
   WHERE order_product_ticket = ANY(order_product_ticket_ids);

  -- Delete the related order_product_ticket entries.
  DELETE FROM eshop.order_product_ticket WHERE "order" = order_id;

  -- Delete the related tickets.
  DELETE FROM eshop.tickets WHERE id = ANY(ticket_ids);

  -- Delete order history rows.
  DELETE FROM eshop.orders_history WHERE "order" = order_id;

  -- If a payment_info row exists, first free it from the order reference, then delete it.
  IF payment_info_id IS NOT NULL THEN
    UPDATE eshop.orders
       SET payment_info = NULL
     WHERE id = order_id;

    DELETE FROM eshop.payment_info WHERE id = payment_info_id;
  END IF;

  -- Finally, delete the order record.
  DELETE FROM eshop.orders WHERE id = order_id;

  -- Return success response.
  RETURN JSONB_BUILD_OBJECT('code', 200, 'message', 'Order successfully deleted.');

EXCEPTION WHEN OTHERS THEN
  -- In case of any error, return an error JSON and rollback.
  RETURN JSONB_BUILD_OBJECT('code', 500, 'message', SQLERRM);
END;
$function$

CREATE OR REPLACE FUNCTION public.delete_order_client_sync_v1(p_order bigint, p_command_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_occasion bigint; v_unit bigint;
  v_begin jsonb; v_hash text; v_removed_users uuid[]; v_remaining_users uuid[];
  v_public text[]:='{}'; v_dirty jsonb:='[]'::jsonb;
BEGIN
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'order',p_order)::text,'UTF8'),'sha256'),'hex');
  SELECT o.occasion,oc.unit INTO v_occasion,v_unit FROM eshop.orders o
    JOIN public.occasions oc ON oc.id=o.occasion WHERE o.id=p_order;
  -- Successful deletion removes the order. Exact retries retain their verified
  -- scope in the existing receipt, and still require current scoped rights.
  IF v_occasion IS NULL THEN
    SELECT r.occasion,oc.unit INTO v_occasion,v_unit FROM public.client_mutation_receipts r
    JOIN public.occasions oc ON oc.id=r.occasion
    WHERE r.command_id=p_command_id AND r.command_name='inventory.order.delete'
      AND r.actor_id=v_actor AND r.request_sha256=v_hash AND r.status IN ('completed','expired');
  END IF;
  IF v_actor IS NULL OR v_occasion IS NULL
    OR NOT (public.get_is_manager_on_unit(v_unit) OR public.get_is_editor_on_unit(v_unit)
      OR public.get_is_admin_on_occasion(v_occasion)) THEN
    RAISE insufficient_privilege USING MESSAGE='unit manager, editor or organization admin required'; END IF;
  v_begin:=public.begin_client_mutation_v1(p_command_id,
    'inventory.order.delete',v_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  PERFORM public.admit_order_mutation_v1(v_occasion,(SELECT count(*) FROM eshop.order_product_ticket WHERE "order"=p_order));
  -- Match the email worker's outer send fence before form/order locks.
  PERFORM 1 FROM public.email_capacity FOR UPDATE;
  PERFORM 1 FROM public.forms WHERE id=(SELECT form FROM eshop.orders WHERE id=p_order) FOR UPDATE;
  SELECT COALESCE(array_agg(DISTINCT ou."user"),'{}'::uuid[]) INTO v_removed_users
  FROM eshop.order_product_ticket opt JOIN public.occasion_users ou
    ON ou.ticket=opt.ticket AND ou.occasion=v_occasion
  WHERE opt."order"=p_order;
  PERFORM public.delete_order_internal_v1(p_order);
  DELETE FROM public.client_sync_private_scopes s WHERE s.occasion=v_occasion
    AND s.user_id=ANY(v_removed_users);
  DELETE FROM public.client_aggregate_versions v
    WHERE v.aggregate_type='occasion_user' AND v.scope_type='occasion'
      AND v.scope_id=v_occasion AND v.aggregate_id=ANY(
        ARRAY(SELECT id::text FROM unnest(v_removed_users) id));
  SELECT COALESCE(array_agg(ou."user"),'{}'::uuid[]) INTO v_remaining_users
    FROM public.occasion_users ou WHERE ou.occasion=v_occasion;
  IF cardinality(v_removed_users)>0 THEN
    v_public:=ARRAY['live_public'];
    SELECT COALESCE(jsonb_agg(jsonb_build_object('component','live_public',
      'entityId',e.id)),'[]'::jsonb) INTO v_dirty
      FROM public.events e WHERE e.occasion=v_occasion;
  END IF;
  RETURN public.complete_private_profile_mutation_v1(p_command_id,v_occasion,
    'inventory.order.delete',jsonb_build_array(jsonb_build_object(
      'entityType','order','entityId',p_order,'operation','delete',
      'safeLabel','Order','changedFields',jsonb_build_array(
        'tickets','membership','allocations'))),v_remaining_users,v_public,v_dirty,
    jsonb_build_object('orderId',p_order,'removedUsers',cardinality(v_removed_users)));
END; $function$

CREATE OR REPLACE FUNCTION public.delete_order_history(p_history_id bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
    v_order_id bigint;
    v_occasion_id bigint;
    v_unit_id bigint;
BEGIN
    SELECT oh."order" INTO v_order_id
    FROM eshop.orders_history oh WHERE oh.id = p_history_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'History record not found.';
    END IF;

    -- Match order deletion's parent-before-history lock order. Pin the unit
    -- used for authorization as well as the history's actual parent binding.
    SELECT o.occasion, occ.unit INTO v_occasion_id, v_unit_id
    FROM eshop.orders o JOIN public.occasions occ ON occ.id = o.occasion
    WHERE o.id = v_order_id
    FOR UPDATE OF o FOR SHARE OF occ;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Could not find the unit associated with the order.';
    END IF;
    PERFORM 1 FROM eshop.orders_history oh
    WHERE oh.id = p_history_id AND oh."order" = v_order_id FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'History record not found or order changed.';
    END IF;

    -- Verify the user is a manager on the unit.
    -- This function will raise an exception if the user does not have manager permissions.
    PERFORM public.check_is_manager_on_unit(v_unit_id);

    -- Removing an audit entry does not mutate the parent order or its finance.
    -- Proceed with the deletion if permission check passes
    DELETE FROM eshop.orders_history WHERE id = p_history_id AND "order" = v_order_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.delete_order_internal_v1(order_id bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  payment_info_id BIGINT;
  order_product_ticket_ids BIGINT[];
  ticket_ids BIGINT[];
  order_oc BIGINT;
  unit_id BIGINT;
  ou_record RECORD;
  form_id BIGINT;
  related_orders BIGINT[];
  offer_ids UUID[];
  v_activity_impacts jsonb := '[]'::jsonb;
BEGIN
  -- Retrieve the order's occasion and payment_info.
  SELECT occasion, payment_info, form
    INTO order_oc, payment_info_id, form_id
    FROM eshop.orders
   WHERE id = delete_order_internal_v1.order_id;

  IF order_oc IS NULL THEN
    RAISE EXCEPTION 'Order not found.';
  END IF;

  -- Deletion belongs to scoped unit managers/editors and organization admins.
  SELECT unit
  INTO unit_id
  FROM public.occasions
  WHERE id = order_oc;

  IF auth.uid() IS NULL OR NOT (public.get_is_manager_on_unit(unit_id)
      OR public.get_is_editor_on_unit(unit_id) OR public.get_is_admin_on_occasion(order_oc)) THEN
    RAISE insufficient_privilege USING MESSAGE='unit manager, editor or organization admin required';
  END IF;
  -- The queue send gate locks global capacity before an order. Deletion must
  -- acquire that outer lock before the form/order helper to avoid inversion.
  PERFORM 1 FROM public.email_capacity FOR UPDATE;
  -- Form serialization fences offer issuance, acceptance, expiry and recovery.
  -- Lock every directly related order in ID order before changing any links.
  PERFORM 1 FROM public.forms WHERE id=form_id FOR UPDATE;
  SELECT array_agg(DISTINCT id ORDER BY id) INTO related_orders FROM (
    SELECT o.id FROM eshop.orders o WHERE o.id=delete_order_internal_v1.order_id OR o.source_waitlist_order_id=delete_order_internal_v1.order_id
      OR o.id=(SELECT source_waitlist_order_id FROM eshop.orders WHERE id=delete_order_internal_v1.order_id)
    UNION SELECT a.source_order_id FROM eshop.waitlist_acceptance_attempts a WHERE a.source_order_id=delete_order_internal_v1.order_id OR a.target_order_id=delete_order_internal_v1.order_id
    UNION SELECT a.target_order_id FROM eshop.waitlist_acceptance_attempts a WHERE a.source_order_id=delete_order_internal_v1.order_id OR a.target_order_id=delete_order_internal_v1.order_id
  ) related;
  IF EXISTS(SELECT 1 FROM eshop.orders o WHERE o.id=ANY(related_orders)
      AND (o.occasion<>order_oc OR o.form IS DISTINCT FROM form_id)) THEN
    RAISE EXCEPTION 'ORDER_WAITLIST_SCOPE_MISMATCH'; END IF;
  PERFORM public.lock_order_capacity_scope_internal(related_orders);
  IF EXISTS(SELECT 1 FROM eshop.orders WHERE id=delete_order_internal_v1.order_id AND state='preparing_payment')
    OR EXISTS(SELECT 1 FROM eshop.waitlist_acceptance_attempts a
      WHERE (a.target_order_id=delete_order_internal_v1.order_id OR a.source_order_id=delete_order_internal_v1.order_id) AND a.state='preparing') THEN
    RAISE EXCEPTION 'WAITLIST_ACCEPTANCE_IN_PROGRESS'; END IF;
  UPDATE public.forms SET capacity_revision=capacity_revision+1 WHERE id IN(SELECT form FROM eshop.orders WHERE id=delete_order_internal_v1.order_id);
  PERFORM public.lock_activity_aggregate_internal_v1(order_oc);
  IF auth.uid() IS NULL OR NOT (public.get_is_manager_on_unit(unit_id)
      OR public.get_is_editor_on_unit(unit_id) OR public.get_is_admin_on_occasion(order_oc)) THEN
    RAISE insufficient_privilege USING MESSAGE='unit manager, editor or organization admin required';
  END IF;

  -- After authorization, match the worker lock order (capacity, order,
  -- attempts, message). Recheck the order after locking against concurrent edits.
  PERFORM 1 FROM public.email_capacity FOR UPDATE;
  SELECT o.payment_info INTO payment_info_id
    FROM eshop.orders o
   WHERE o.id = delete_order_internal_v1.order_id AND o.occasion = order_oc
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Order not found or occasion changed.';
  END IF;

  -- Remove every queued/reminder/provider record for this order. log_emails
  -- and address suppressions are independent audit/safety records and remain.
  DELETE FROM public.email_delivery_events e
   WHERE e.message_id IN (SELECT m.message_id FROM public.email_messages m
                           WHERE m.order_id = delete_order_internal_v1.order_id)
      OR e.attempt_id IN (SELECT a.attempt_id FROM public.email_attempts a
                          JOIN public.email_messages m USING (message_id)
                         WHERE m.order_id = delete_order_internal_v1.order_id)
      OR e.provider_message_id IN (
           SELECT m.provider_message_id FROM public.email_messages m
            WHERE m.order_id = delete_order_internal_v1.order_id
           UNION
           SELECT a.provider_message_id FROM public.email_attempts a
           JOIN public.email_messages m USING (message_id)
            WHERE m.order_id = delete_order_internal_v1.order_id);

  DELETE FROM public.email_confirmation_receipts r
   WHERE r.message_id IN (SELECT m.message_id FROM public.email_messages m
                          WHERE m.order_id = delete_order_internal_v1.order_id);
  DELETE FROM public.email_attempts a
   WHERE a.message_id IN (SELECT m.message_id FROM public.email_messages m
                          WHERE m.order_id = delete_order_internal_v1.order_id);
  DELETE FROM public.email_messages m
   WHERE m.order_id = delete_order_internal_v1.order_id;

  -- Collect all order_product_ticket IDs for the order.
  SELECT ARRAY(SELECT id FROM eshop.order_product_ticket WHERE "order" = delete_order_internal_v1.order_id)
    INTO order_product_ticket_ids;

  -- Collect all ticket IDs from the order_product_ticket rows.
  SELECT ARRAY(SELECT ticket
                 FROM eshop.order_product_ticket
                WHERE "order" = delete_order_internal_v1.order_id
                  AND ticket IS NOT NULL)
    INTO ticket_ids;

  IF EXISTS(SELECT 1 FROM eshop.order_product_ticket x WHERE x.ticket=ANY(ticket_ids) AND x."order"<>delete_order_internal_v1.order_id) THEN
    RAISE EXCEPTION 'TICKET_LINKED_TO_ANOTHER_ORDER'; END IF;

  -- Remove only this order's capability/offer evidence. Accepted children are
  -- independent orders: detach their source FK, never their tickets or finance.
  SELECT coalesce(array_agg(w.id),'{}') INTO offer_ids FROM eshop.waitlist_offers w WHERE w.order_id=delete_order_internal_v1.order_id;
  PERFORM 1 FROM eshop.waitlist_acceptance_attempts a
    WHERE a.source_order_id=delete_order_internal_v1.order_id OR a.target_order_id=delete_order_internal_v1.order_id ORDER BY a.command_id FOR UPDATE;
  PERFORM 1 FROM eshop.waitlist_offers w WHERE w.id=ANY(offer_ids) ORDER BY w.id FOR UPDATE;
  PERFORM 1 FROM eshop.waitlist_offer_slots x
    WHERE x.offer_id=ANY(offer_ids) OR x.ticket_id=ANY(ticket_ids) OR x.resulting_order_id=delete_order_internal_v1.order_id ORDER BY x.id FOR UPDATE;
  DELETE FROM eshop.waitlist_capabilities c WHERE c.order_id=delete_order_internal_v1.order_id OR c.offer_id=ANY(offer_ids);
  DELETE FROM eshop.waitlist_acceptance_attempts a WHERE a.source_order_id=delete_order_internal_v1.order_id OR a.target_order_id=delete_order_internal_v1.order_id;
  UPDATE eshop.waitlist_offer_slots x SET resulting_order_id=NULL,updated_at=clock_timestamp() WHERE x.resulting_order_id=delete_order_internal_v1.order_id;
  DELETE FROM eshop.waitlist_offer_slots x WHERE x.offer_id=ANY(offer_ids) OR x.ticket_id=ANY(ticket_ids);
  DELETE FROM eshop.waitlist_offers w WHERE w.id=ANY(offer_ids);
  UPDATE eshop.orders o SET source_waitlist_order_id=NULL,updated_at=clock_timestamp() WHERE o.source_waitlist_order_id=delete_order_internal_v1.order_id;

  -- Free any spots that reference these order_product_ticket rows:
  -- set order_product_ticket, secret, and secret_expiration_time to NULL.
  UPDATE eshop.spots
     SET order_product_ticket      = NULL,
         secret                  = NULL,
         secret_expiration_time  = NULL,
         updated_at              = NOW()
   WHERE order_product_ticket = ANY(order_product_ticket_ids);

  -- Delete the related order_product_ticket entries.
  DELETE FROM eshop.order_product_ticket WHERE "order" = delete_order_internal_v1.order_id;

  -- Ticket-bound membership teardown has one domain owner, independent of
  -- the retired public RPC. Authorization remains the order's manager boundary.
  IF EXISTS(SELECT 1 FROM public.occasion_users WHERE ticket=ANY(ticket_ids) AND occasion<>order_oc) THEN
    RAISE invalid_parameter_value USING MESSAGE='ticket membership belongs to another occasion';
  END IF;
  FOR ou_record IN SELECT "user",occasion FROM public.occasion_users
    WHERE ticket=ANY(ticket_ids) AND occasion=order_oc ORDER BY "user"
  LOOP
    v_activity_impacts:=v_activity_impacts || public.remove_occasion_user_domain_internal_v1(order_oc,ou_record."user");
  END LOOP;
  -- The canonical order facade already invalidates profiles for remaining members.
  -- Teardown must also invalidate affected activity projections in sorted order.
  INSERT INTO public.client_sync_private_scopes(component,occasion,user_id,source_revision)
  SELECT DISTINCT x->>'component',order_oc,(x->>'userId')::uuid,1
  FROM jsonb_array_elements(v_activity_impacts) x
  JOIN public.occasion_users ou ON ou.occasion=order_oc AND ou."user"=(x->>'userId')::uuid
  WHERE x->>'component'='private_activity' ORDER BY 1,3
  ON CONFLICT(component,occasion,user_id) DO UPDATE
    SET source_revision=public.client_sync_private_scopes.source_revision+1,updated_at=clock_timestamp();

  -- Delete the related tickets.
  -- This is now safe, as any occasion_users foreign key constraints
  -- should be resolved by the loop above.
  DELETE FROM eshop.tickets WHERE id = ANY(ticket_ids);

  -- Delete order history rows.
  DELETE FROM eshop.orders_history WHERE "order" = delete_order_internal_v1.order_id;

  -- Order-specific bank requests must not keep the order alive through their FK.
  DELETE FROM eshop.bank_account_requests WHERE "order" = delete_order_internal_v1.order_id;

  -- If a payment_info row exists, first free it from the order reference, then delete it.
  IF payment_info_id IS NOT NULL THEN
    UPDATE eshop.orders
       SET payment_info = NULL
     WHERE id = delete_order_internal_v1.order_id;

    -- Retain imported/manual bank transactions while removing their payment link.
    UPDATE eshop.transactions
       SET payment_info = NULL
     WHERE payment_info = payment_info_id;

    DELETE FROM eshop.payment_info WHERE id = payment_info_id;
  END IF;

  -- Finally, delete the order record.
  DELETE FROM eshop.orders WHERE id = delete_order_internal_v1.order_id;

END;
$function$

CREATE OR REPLACE FUNCTION public.delete_owned_companion_guard_v1(p_occasion bigint, p_companion uuid)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_policy jsonb;
BEGIN
  v_policy:=public.get_companion_feature_policy_v1(p_occasion);
  IF NOT COALESCE((v_policy->>'is_enabled')::boolean,false)
      OR NOT COALESCE((v_policy->>'allow_user_create')::boolean,true) THEN
    RAISE insufficient_privilege USING MESSAGE='self-created companion lifecycle disabled';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.user_companions uc
    WHERE uc.occasion=p_occasion AND uc."user"=auth.uid()
      AND uc.companion=p_companion AND uc.origin='self_created') THEN
    RAISE insufficient_privilege USING MESSAGE='self-created companion ownership required';
  END IF;
END $function$

CREATE OR REPLACE FUNCTION public.delete_owned_companion_internal_v1(p_occasion bigint, p_companion uuid, p_command_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_begin jsonb; v_hash text; v_event_ids bigint[];
  v_group_ids bigint[]; v_private_impacts jsonb; v_replacements jsonb;
  v_is_publishable boolean;
BEGIN
  IF v_actor IS NULL OR p_companion IS NULL THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid companion delete'; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.occasion_users WHERE occasion=p_occasion AND "user"=v_actor)
    OR NOT coalesce((public.get_companion_feature_policy_v1(p_occasion)->>'is_enabled')::boolean,false)
    OR NOT coalesce((public.get_companion_feature_policy_v1(p_occasion)->>'allow_user_create')::boolean,true) THEN
    RAISE insufficient_privilege USING MESSAGE='self-created companion lifecycle disabled'; END IF;
  SELECT NOT o.is_hidden INTO v_is_publishable FROM public.occasions o
    WHERE o.id=p_occasion;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'occasion',p_occasion,'companion',p_companion)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'profile.companion.delete',
    p_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(
    'companion-owner:'||v_actor::text||':'||p_occasion::text,0));
  PERFORM pg_advisory_xact_lock(hashtextextended('attendance-user:'||p_companion::text||':'||p_occasion::text,0));
  PERFORM pg_advisory_xact_lock(hashtextextended('saved-program:'||p_companion::text||':'||p_occasion::text,0));
  PERFORM public.lock_activity_aggregate_internal_v1(p_occasion);
  PERFORM 1 FROM public.user_group_info WHERE occasion=p_occasion ORDER BY id FOR UPDATE;
  PERFORM 1 FROM public.user_info ui WHERE ui.id=p_companion FOR UPDATE;
  IF NOT FOUND THEN RETURN public.complete_client_mutation_outcome_v1(
    p_command_id,'unchanged',200,jsonb_build_object('companion',NULL)); END IF;
  PERFORM 1 FROM public.occasion_users WHERE "user"=p_companion ORDER BY occasion FOR UPDATE;
  PERFORM 1 FROM public.user_companions WHERE occasion=p_occasion AND companion=p_companion FOR UPDATE;
  PERFORM public.delete_owned_companion_guard_v1(p_occasion,p_companion);
  IF EXISTS(SELECT 1 FROM public.occasion_users WHERE "user"=p_companion AND occasion<>p_occasion) THEN
    RAISE invalid_parameter_value USING MESSAGE='cross-occasion companion requires manual cleanup'; END IF;

  SELECT COALESCE(array_agg(DISTINCT event_id ORDER BY event_id),'{}'::bigint[])
    INTO v_event_ids FROM (
      SELECT eu.event event_id FROM public.event_users eu JOIN public.events e
        ON e.id=eu.event WHERE eu."user"=p_companion AND e.occasion=p_occasion
      UNION SELECT es.event FROM public.event_users_saved es JOIN public.events e
        ON e.id=es.event WHERE es."user"=p_companion AND e.occasion=p_occasion
    ) affected;
  SELECT COALESCE(array_agg(ug."group" ORDER BY ug."group"),'{}'::bigint[])
    INTO v_group_ids FROM public.user_groups ug JOIN public.user_group_info g
      ON g.id=ug."group" WHERE ug."user"=p_companion AND g.occasion=p_occasion;
  PERFORM 1 FROM public.events e WHERE e.id=ANY(v_event_ids) ORDER BY e.id FOR UPDATE;
  PERFORM 1 FROM public.user_group_info g WHERE g.id=ANY(v_group_ids) ORDER BY g.id FOR UPDATE;
  SELECT COALESCE(jsonb_agg(jsonb_build_object('component','private_profile',
    'userId',impacted.user_id)),'[]'::jsonb) INTO v_private_impacts FROM (
      SELECT v_actor user_id UNION SELECT ug."user" FROM public.user_groups ug
        WHERE ug."group"=ANY(v_group_ids) AND ug."user"<>p_companion
    ) impacted JOIN public.occasion_users ou ON ou.occasion=p_occasion
      AND ou."user"=impacted.user_id;
  SELECT coalesce(jsonb_agg(DISTINCT item),'[]') INTO v_private_impacts FROM jsonb_array_elements(
    public.remove_occasion_user_domain_internal_v1(p_occasion,p_companion)||
    jsonb_build_array(jsonb_build_object('component','private_profile','userId',v_actor))) item;
  DELETE FROM public.client_aggregate_versions WHERE aggregate_type='occasion_user'
    AND scope_type='occasion' AND scope_id=p_occasion
    AND aggregate_id=p_companion::text;
  DELETE FROM public.user_reset_token WHERE "user"=p_companion;
  DELETE FROM public.user_companions WHERE "user"=p_companion OR companion=p_companion;
  DELETE FROM public.user_info WHERE id=p_companion;
  DELETE FROM auth.identities WHERE user_id=p_companion;
  DELETE FROM auth.users WHERE id=p_companion;
  v_replacements:=jsonb_build_array(jsonb_build_object(
    'component','private_profile','userId',v_actor,
    'payload',public.get_private_profile_payload_v1(p_occasion,v_actor)));
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'profile.companion.delete','profile',jsonb_build_array(jsonb_build_object(
      'entityType','companion','entityId',p_companion,'operation','delete',
      'safeLabel','Companion','changedFields',jsonb_build_array('aggregate'))),
    CASE WHEN v_is_publishable AND cardinality(v_event_ids)>0
      THEN ARRAY['live_public'] ELSE '{}'::text[] END,v_private_impacts,
    CASE WHEN v_is_publishable THEN COALESCE((SELECT jsonb_agg(jsonb_build_object(
      'component','live_public','entityId',event_id)) FROM unnest(v_event_ids) event_id),
      '[]'::jsonb) ELSE '[]'::jsonb END,
    jsonb_build_object('companion',NULL),'{}','[]','user',NULL,v_replacements);
END; $function$

CREATE OR REPLACE FUNCTION public.delete_product_domain_command_internal_v1(p_product_id bigint, p_command_id uuid, p_expected_version bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE actor uuid:=auth.uid(); oc bigint; title text; begin_result jsonb; hash text; version bigint; used bigint; original_key uuid;
BEGIN
 SELECT occasion INTO oc FROM public.client_mutation_receipts WHERE command_id=p_command_id AND actor_id=actor AND command_name='inventory.product.delete';
 IF NOT FOUND THEN SELECT t.occasion INTO oc FROM eshop.products t WHERE id=p_product_id; END IF;
 IF actor IS NULL OR oc IS NULL OR public.get_is_editor_order_on_occasion(oc) IS NOT TRUE THEN RAISE insufficient_privilege USING MESSAGE='product editor required'; END IF;
 hash:=encode(extensions.digest(convert_to((jsonb_build_object('productId',p_product_id)||CASE WHEN p_expected_version IS NULL THEN '{}'::jsonb ELSE jsonb_build_object('expectedVersion',p_expected_version) END)::text,'UTF8'),'sha256'),'hex');
 begin_result:=public.begin_client_mutation_v1(p_command_id,'inventory.product.delete',oc,actor,hash);
 IF begin_result->>'disposition'='replay' THEN RETURN begin_result->'response'; END IF;
 PERFORM public.lock_product_order_dependencies_internal_v1(p_product_id);
 SELECT t.title INTO title FROM eshop.products t WHERE id=p_product_id AND occasion=oc FOR UPDATE;
 IF NOT FOUND THEN RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',404,jsonb_build_object('productId',p_product_id)); END IF;
 SELECT coalesce(v.version,0) INTO version FROM (SELECT 1) seed LEFT JOIN public.client_aggregate_versions v
 ON v.aggregate_type='product' AND v.scope_type='occasion' AND v.scope_id=oc AND v.aggregate_id=p_product_id::text;
 IF p_expected_version IS NOT NULL AND p_expected_version IS DISTINCT FROM version THEN RETURN public.complete_client_mutation_outcome_v1(p_command_id,'conflict',409,jsonb_build_object('aggregate_version',version)); END IF;
 SELECT count(*) INTO used FROM eshop.order_product_ticket WHERE product=p_product_id;
 IF used>0 THEN RETURN public.complete_client_mutation_outcome_v1(p_command_id,'conflict',409,jsonb_build_object('message','product is in use')); END IF;
 PERFORM public.delete_product_internal_v1(p_product_id);
 DELETE FROM public.client_aggregate_versions WHERE aggregate_type='product' AND scope_type='occasion' AND scope_id=oc AND aggregate_id=p_product_id::text;
 RETURN public.complete_private_inventory_mutation_v1(p_command_id,oc,'inventory.product.delete',jsonb_build_array(jsonb_build_object('entityType','product','entityId',p_product_id,'operation','delete','safeLabel',left(title,240),'changedFields',jsonb_build_array('aggregate'))),'{}'::uuid[],jsonb_build_object('productId',p_product_id));
END $function$

CREATE OR REPLACE FUNCTION public.delete_product_internal_v1(p_product_id bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_occasion_id BIGINT;
  v_order_count INT;
BEGIN
  -- Determine the occasion of the product to check permissions.
  SELECT pt.occasion
    INTO v_occasion_id
  FROM eshop.products p
  JOIN eshop.product_types pt ON p.product_type = pt.id
  WHERE p.id = p_product_id FOR UPDATE OF p;

  -- If the product does not exist, raise a structured error.
  IF NOT FOUND THEN
    RAISE EXCEPTION '%', jsonb_build_object(
        'code', 'PRD404',
        'message', 'Product with ID ' || p_product_id || ' not found.'
    )::text;
  END IF;

  -- Authorization check. This function is expected to throw on failure.
  PERFORM public.check_is_editor_order_on_occasion(v_occasion_id);

  -- Safety Check: Ensure the product is not part of any existing orders.
  SELECT COUNT(*) INTO v_order_count
    FROM eshop.order_product_ticket
   WHERE product = p_product_id;
  IF v_order_count > 0 THEN
    RAISE EXCEPTION '%', jsonb_build_object(
        'code', 'PRD409',
        'message', 'Cannot delete product because it is included in ' || v_order_count || ' order(s).',
        'hint', 'Remove this product from all orders before deleting it.'
    )::text;
  END IF;

  -- **INTEGRATION:** Before deleting the product, clear all its inventory context associations.
  -- This call will also trigger the necessary de-allocation of spots.
  PERFORM public.update_product_inventory_contexts_internal_v1(p_product_id, '[]'::jsonb);

  DELETE FROM eshop.planned_changes WHERE subject_id=p_product_id AND change_type IN('products.price','products.is_hidden') AND NOT applied;

  -- Finally, delete the product itself.
  DELETE FROM eshop.products
   WHERE id = p_product_id;

END;
$function$

CREATE OR REPLACE FUNCTION public.delete_resource(p_resource_id bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE oc bigint; v bigint; result jsonb;
BEGIN
 SELECT occasion INTO oc FROM public.resources WHERE id=p_resource_id;
 PERFORM public.check_is_editor_order_on_occasion(oc);
 PERFORM public.lock_resource_pools_internal_v1(p_resource_id);
 SELECT coalesce((SELECT version FROM public.client_aggregate_versions WHERE aggregate_type='resource' AND scope_type='occasion' AND scope_id=oc AND aggregate_id=p_resource_id::text),0) INTO v;
 result:=public.delete_resource_client_sync_v1(oc,p_resource_id,extensions.gen_random_uuid(),v);
 IF result->>'code'<>'200' THEN RAISE serialization_failure USING MESSAGE='inventory deletion rejected'; END IF;
END $function$

CREATE OR REPLACE FUNCTION public.delete_resource_client_sync_v1(p_occasion bigint, p_resource bigint, p_command_id uuid, p_expected_version bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_pool bigint; v_version bigint; v_title text;
  v_begin jsonb; v_hash text; v_impacts jsonb; v_replacements jsonb:='[]'::jsonb;
BEGIN
  IF v_actor IS NULL OR NOT public.get_is_editor_order_on_occasion(p_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion order editor required'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object('occasion',p_occasion,
    'resourceId',p_resource,'expectedVersion',p_expected_version)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'inventory.resource.delete',
    p_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  v_pool:=public.lock_resource_pools_internal_v1(p_resource);
  SELECT r.inventory_pool,r.title INTO v_pool,v_title FROM public.resources r
    WHERE r.id=p_resource AND r.occasion=p_occasion FOR UPDATE;
  IF v_pool IS NULL THEN RETURN public.complete_client_mutation_outcome_v1(
    p_command_id,'unchanged',200,jsonb_build_object('version',0,'resource',NULL)); END IF;
  PERFORM 1 FROM public.inventory_pools ip WHERE ip.id=v_pool FOR UPDATE;
  PERFORM 1 FROM eshop.spots s WHERE s.resource=p_resource OR s.resource_slot IN(SELECT id FROM public.resource_slots WHERE resource=p_resource) ORDER BY s.id FOR UPDATE;
  INSERT INTO public.client_aggregate_versions
    (aggregate_type,scope_type,scope_id,aggregate_id,version)
  VALUES ('resource','occasion',p_occasion,p_resource::text,0) ON CONFLICT DO NOTHING;
  SELECT version INTO v_version FROM public.client_aggregate_versions
    WHERE aggregate_type='resource' AND scope_type='occasion'
      AND scope_id=p_occasion AND aggregate_id=p_resource::text FOR UPDATE;
  IF p_expected_version IS DISTINCT FROM v_version THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'conflict',409,
      jsonb_build_object('version',v_version,'resourceId',p_resource)); END IF;
  IF EXISTS (SELECT 1 FROM eshop.spots s WHERE (s.resource=p_resource OR s.resource_slot IN(SELECT id FROM public.resource_slots WHERE resource=p_resource))
    AND (s.order_product_ticket IS NOT NULL OR (s.secret IS NOT NULL AND s.secret_expiration_time>clock_timestamp()))) THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',409,
      jsonb_build_object('version',v_version,'resourceId',p_resource,
        'message','resource has reserved spots')); END IF;
  DELETE FROM eshop.spots WHERE resource=p_resource OR resource_slot IN(SELECT id FROM public.resource_slots WHERE resource=p_resource);
  DELETE FROM public.resources WHERE id=p_resource;
  PERFORM public.adjust_spot_capacity_for_pool(v_pool);
  PERFORM public.advance_ticketing_authoring_version_internal_v1('inventory_pool',p_occasion,v_pool);
  DELETE FROM public.client_aggregate_versions WHERE aggregate_type='resource'
    AND scope_type='occasion' AND scope_id=p_occasion AND aggregate_id=p_resource::text;
  SELECT COALESCE(jsonb_agg(jsonb_build_object('component','private_inventory',
    'userId',ou."user")),'[]'::jsonb) INTO v_impacts
    FROM public.occasion_users ou WHERE ou.occasion=p_occasion;
  IF EXISTS (SELECT 1 FROM public.occasion_users ou WHERE ou.occasion=p_occasion
    AND ou."user"=v_actor) THEN v_replacements:=jsonb_build_array(jsonb_build_object(
      'component','private_inventory','userId',v_actor,
      'payload',public.get_user_inventory_for_occasion_v1(p_occasion))); END IF;
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'inventory.resource.delete','inventory',jsonb_build_array(jsonb_build_object(
      'entityType','resource','entityId',p_resource,'operation','delete',
      'safeLabel',left(v_title,240),'changedFields',jsonb_build_array('aggregate'))),
    '{}',v_impacts,'[]',jsonb_build_object('version',v_version,'resource',NULL),
    '{}','[]','user',NULL,v_replacements);
END; $function$

CREATE OR REPLACE FUNCTION public.delete_speaker(p_speaker_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE oc bigint; ver bigint; r jsonb;
BEGIN
 SELECT occasion INTO oc FROM public.speakers WHERE id=p_speaker_id;
 IF oc IS NULL THEN RETURN jsonb_build_object('code',404); END IF;
 IF auth.uid() IS NULL OR NOT public.get_is_editor_on_occasion(oc) THEN RETURN jsonb_build_object('code',403); END IF;
 PERFORM public.lock_speaker_event_dependencies_internal_v1(p_speaker_id);
 PERFORM 1 FROM public.speakers WHERE id=p_speaker_id AND occasion=oc FOR UPDATE;
 SELECT coalesce(v.version,0) INTO ver FROM (SELECT 1) seed
 LEFT JOIN public.client_aggregate_versions v ON v.aggregate_type='speaker'
 AND v.scope_type='occasion' AND v.scope_id=oc AND v.aggregate_id=p_speaker_id::text;
 r:=public.delete_speaker_client_sync_v1(oc,p_speaker_id,extensions.gen_random_uuid(),ver);
 RETURN jsonb_build_object('code',r->'code');
END $function$

CREATE OR REPLACE FUNCTION public.delete_speaker_client_sync_v1(p_occasion bigint, p_speaker_id bigint, p_command_id uuid, p_expected_version bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_version bigint; v_begin jsonb; v_hash text;
  v_event_ids bigint[];
  v_entity jsonb; v_publishable boolean; v_hidden boolean; v_has_public_events boolean;
BEGIN
  IF v_actor IS NULL OR NOT public.get_is_editor_on_occasion(p_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion editor required'; END IF;
  SELECT NOT o.is_hidden INTO v_publishable FROM public.occasions o WHERE o.id=p_occasion;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object('occasion',p_occasion,
    'speakerId',p_speaker_id,'expectedVersion',p_expected_version)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'content.speaker.delete',
    p_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  v_event_ids:=public.lock_speaker_event_dependencies_internal_v1(p_speaker_id);
  SELECT public.get_speaker_command_data_v1(s.id),s.is_hidden INTO v_entity,v_hidden
    FROM public.speakers s WHERE s.id=p_speaker_id AND s.occasion=p_occasion FOR UPDATE;
  IF v_entity IS NULL THEN RETURN public.complete_client_mutation_outcome_v1(p_command_id,
    'unchanged',200,jsonb_build_object('version',0,'speaker',NULL)); END IF;
  INSERT INTO public.client_aggregate_versions
    (aggregate_type,scope_type,scope_id,aggregate_id,version)
  VALUES ('speaker','occasion',p_occasion,p_speaker_id::text,0) ON CONFLICT DO NOTHING;
  SELECT version INTO v_version FROM public.client_aggregate_versions
    WHERE aggregate_type='speaker' AND scope_type='occasion'
    AND scope_id=p_occasion AND aggregate_id=p_speaker_id::text FOR UPDATE;
  IF p_expected_version IS DISTINCT FROM v_version THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'conflict',409,
      jsonb_build_object('version',v_version,'speaker',v_entity)); END IF;
  SELECT EXISTS (SELECT 1 FROM public.event_speakers es JOIN public.events e
    ON e.id=es.event WHERE es.speaker=p_speaker_id AND NOT e.is_hidden)
    INTO v_has_public_events;
  INSERT INTO public.client_aggregate_versions(aggregate_type,scope_type,scope_id,aggregate_id,version)
  SELECT 'event','occasion',p_occasion,id::text,1 FROM unnest(v_event_ids) id
  ON CONFLICT(aggregate_type,scope_type,scope_id,aggregate_id) DO UPDATE
  SET version=public.client_aggregate_versions.version+1,updated_at=clock_timestamp();
  DELETE FROM public.speakers WHERE id=p_speaker_id;
  DELETE FROM public.client_aggregate_versions WHERE aggregate_type='speaker'
    AND scope_type='occasion' AND scope_id=p_occasion AND aggregate_id=p_speaker_id::text;
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'content.speaker.delete','content',jsonb_build_array(jsonb_build_object(
      'entityType','speaker','entityId',p_speaker_id,'operation','delete',
      'safeLabel',left(v_entity->>'title',240),'changedFields',jsonb_build_array('aggregate'))),
    CASE WHEN v_publishable THEN CASE WHEN NOT v_hidden THEN ARRAY['content_catalog']
      ELSE '{}'::text[] END||CASE WHEN NOT v_hidden
      AND v_has_public_events THEN ARRAY['program_catalog'] ELSE '{}'::text[] END
      ELSE '{}'::text[] END,'[]','[]',
    jsonb_build_object('version',v_version,'speaker',NULL));
END; $function$

CREATE OR REPLACE FUNCTION public.delete_speaker_topic(p_topic_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE oc bigint; ver bigint; r jsonb;
BEGIN
 SELECT occasion INTO oc FROM public.speaker_topics WHERE id=p_topic_id;
 IF oc IS NULL THEN RETURN jsonb_build_object('code',404); END IF;
 IF auth.uid() IS NULL OR NOT public.get_is_editor_on_occasion(oc) THEN RETURN jsonb_build_object('code',403); END IF;
 PERFORM 1 FROM public.speaker_topics WHERE id=p_topic_id AND occasion=oc FOR UPDATE;
 SELECT coalesce(v.version,0) INTO ver FROM (SELECT 1) seed
 LEFT JOIN public.client_aggregate_versions v ON v.aggregate_type='speaker_topic'
 AND v.scope_type='occasion' AND v.scope_id=oc AND v.aggregate_id=p_topic_id::text;
 r:=public.delete_speaker_topic_client_sync_v1(oc,p_topic_id,extensions.gen_random_uuid(),ver);
 RETURN jsonb_build_object('code',r->'code');
END $function$

