 WHERE occasion=p_occasion AND "user"=auth.uid();
 RETURN jsonb_build_object('newsId',marker);
END $function$

CREATE OR REPLACE FUNCTION public.get_occasion_by_link(link_param text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
    occ_record public.occasions;
    has_orders boolean;
    result jsonb;
BEGIN
    -- Legacy links may repeat across tenants after the canonical merge.
    -- This RPC supplies editor data, so resolve only inside the caller's tenant.
    SELECT o.* INTO occ_record
    FROM public.occasions o
    WHERE o.id = public.resolve_occasion_link_internal(link_param)
      AND o.organization = (
          SELECT ui.organization FROM public.user_info ui WHERE ui.id = auth.uid()
      );

    -- Return null if not found
    IF occ_record IS NULL THEN
        RETURN NULL;
    END IF;

    IF public.is_demo_occasion(occ_record.id) AND NOT public.can_read_demo_occasion(occ_record.id) THEN
        RAISE insufficient_privilege USING MESSAGE='Demo access denied';
    END IF;

    IF NOT (public.get_is_editor_view_on_occasion(occ_record.id)
        OR public.get_is_manager_on_occasion(occ_record.id)
        OR public.get_is_admin_on_occasion(occ_record.id)) THEN
        RAISE insufficient_privilege USING MESSAGE='occasion editor view required';
    END IF;

    -- 2. Check for active orders
    SELECT EXISTS (
        SELECT 1
        FROM eshop.orders
        WHERE occasion = occ_record.id
    ) INTO has_orders;

    -- 3. Merge the occasion record with the new boolean flag
    result := to_jsonb(occ_record) || jsonb_build_object('has_orders', has_orders);

    RETURN result;
END;
$function$

CREATE OR REPLACE FUNCTION public.get_occasion_by_scan_code(scan_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
    found_occasion_record RECORD;
BEGIN
    IF NOT public.check_scan_attempt_budget_v1(NULL) THEN
        RETURN jsonb_build_object('code',429,'message','abuse_limit_exceeded');
    END IF;
    SELECT o.id, o.title, o.features
    INTO found_occasion_record
    FROM public.occasions o
    JOIN public.occasions_hidden oh ON o.occasion_hidden = oh.id
    WHERE oh.secret = scan_code
    LIMIT 1;

    IF found_occasion_record IS NULL THEN
        PERFORM public.admit_scan_access_v1(NULL,false);
        RETURN jsonb_build_object('code',401,'message','invalid_scan_code');
    END IF;

    IF NOT public.admit_scan_access_v1(found_occasion_record.id,true) THEN
        RETURN jsonb_build_object('code',429,'message','abuse_limit_exceeded');
    END IF;
    RETURN jsonb_build_object(
        'id', found_occasion_record.id,
        'title', found_occasion_record.title,
        'features', found_occasion_record.features,
        'scanner_field_mappings', (SELECT coalesce(jsonb_object_agg(f->>'field_id',f->>'label'),'{}'::jsonb)
         FROM jsonb_array_elements((SELECT config->'fields' FROM public.scanner_settings WHERE occasion_id=found_occasion_record.id)) f
         WHERE f->>'source'='order_field' AND coalesce((f->>'default_visible')::boolean,true))
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.get_occasion_for_authoring_v1(p_occasion bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
