CREATE OR REPLACE FUNCTION public.get_occasion_for_context_v1(p_occasion bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE o public.occasions; privileged boolean;
BEGIN
 SELECT * INTO o FROM public.occasions WHERE id=p_occasion;
 IF NOT FOUND THEN RAISE insufficient_privilege USING MESSAGE='occasion unavailable'; END IF;
 privileged := auth.uid() IS NOT NULL AND (
   public.get_is_editor_view_on_occasion(o.id)
   OR public.get_is_manager_on_occasion(o.id)
   OR public.get_is_admin_on_occasion(o.id));
 IF public.is_demo_occasion(o.id) AND NOT public.can_read_demo_occasion(o.id) THEN
   RAISE insufficient_privilege USING MESSAGE='occasion unavailable';
 END IF;
 IF privileged THEN
   RETURN to_jsonb(o);
 END IF;
 IF auth.uid() IS NOT NULL AND EXISTS(SELECT 1 FROM public.occasion_users
     WHERE occasion=o.id AND "user"=auth.uid()) THEN
   RETURN to_jsonb(o)-'occasion_hidden';
 END IF;
 IF o.is_hidden IS DISTINCT FROM false OR o.is_open IS DISTINCT FROM true THEN
   RAISE insufficient_privilege USING MESSAGE='occasion unavailable';
 END IF;
 RETURN jsonb_build_object('id',o.id,'title',o.title,'description',o.description,
   'link',o.link,'start_time',o.start_time,'end_time',o.end_time,
   'is_open',o.is_open,'is_hidden',false,'is_promoted',o.is_promoted,
   'organization',o.organization,'unit',o.unit,
   'data',jsonb_build_object('timezone',o.data->'timezone'));
END $function$

CREATE OR REPLACE FUNCTION public.get_occasion_for_edit_v1(p_link text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_occasion bigint;
  v_result jsonb;
BEGIN
  SELECT o.id
  INTO v_occasion
  FROM public.occasions o
  WHERE o.id = public.resolve_occasion_link_internal(p_link)
    AND o.organization = (
      SELECT ui.organization
      FROM public.user_info ui
      WHERE ui.id = auth.uid()
    );

  IF v_occasion IS NULL THEN
    RAISE invalid_parameter_value USING MESSAGE = 'occasion not found';
  END IF;

  IF NOT (
    public.get_is_editor_view_on_occasion(v_occasion)
    OR public.get_is_manager_on_occasion(v_occasion)
    OR public.get_is_admin_on_occasion(v_occasion)
  ) THEN
    RAISE insufficient_privilege USING MESSAGE = 'occasion editor view required';
  END IF;

  SELECT to_jsonb(o) || jsonb_build_object(
    'aggregate_version', COALESCE(v.version, 0)
  )
  INTO v_result
  FROM public.occasions o
  LEFT JOIN public.client_aggregate_versions v
    ON v.aggregate_type = 'occasion'
    AND v.scope_type = 'occasion'
    AND v.scope_id = o.id
    AND v.aggregate_id = o.id::text
  WHERE o.id = v_occasion;

  RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public.get_occasion_from_link(org_id bigint, link_txt text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
    occasionId bigint;
    is_open_bool BOOLEAN;
    occasion_user occasion_users%rowtype;
    is_admin_bool BOOLEAN;
    occasion_link text;
    version_recommended text;
BEGIN
    -- If no link is provided, get the default occasion from the organization
    IF link_txt = '' THEN
        -- Get the default occasion ID from the organization's data
        SELECT data->>'DEFAULT_OCCASION' INTO occasionId
        FROM organizations
        WHERE id = org_id;

        -- If no default occasion is set, get the first open and non-hidden occasion within the organization
        IF occasionId IS NULL THEN
            SELECT id, link INTO occasionId, occasion_link
            FROM occasions
            WHERE is_open = true
              AND is_hidden = false
              AND organization = org_id
            LIMIT 1;

            -- If no open occasion is found, return a 404 response
            IF occasionId IS NULL THEN
                RETURN json_build_object('code', 404, 'message', 'No open occasion found for the organization');
            END IF;
        ELSE
            -- Get the link for the default occasion
            SELECT link INTO occasion_link
            FROM occasions
            WHERE id = occasionId AND organization = org_id;
        END IF;
    ELSE
        -- Get the occasion ID and link for the provided link within the specified organization
        SELECT id, link INTO occasionId, occasion_link
        FROM occasions
        WHERE id = public.resolve_occasion_link_internal(link_txt,org_id)
          AND is_hidden = false
          AND organization = org_id;

        -- If the occasion ID is not found, return a 404 response
        IF occasionId IS NULL THEN
            RETURN json_build_object('code', 404, 'message', 'Occasion not found');
        END IF;
    END IF;

     -- Retrieve version_recommended from organization's data
    SELECT data->>'VERSION_RECOMMENDED' INTO version_recommended
    FROM organizations
    WHERE id = org_id;

    -- Get the is_open status for the occasion
    SELECT is_open INTO is_open_bool
    FROM occasions
    WHERE id = occasionId;

    -- Get the occasion user record if it exists
    SELECT * INTO occasion_user
    FROM occasion_users
    WHERE occasion = occasionId
      AND "user" = auth.uid();

    -- Check if the current user is an admin on the occasion
    is_admin_bool := get_is_admin_on_occasion(occasionId);

    -- If the occasion is not open, enforce access restrictions
    IF is_open_bool = FALSE THEN
        IF auth.uid() IS NULL THEN
            RETURN json_build_object('code', 403, 'message', 'Access forbidden', 'link', occasion_link, 'version_recommended', version_recommended);
        END IF;
        IF occasion_user IS NULL AND NOT is_admin_bool THEN
            RETURN json_build_object('code', 403, 'message', 'Access forbidden', 'link', occasion_link, 'version_recommended', version_recommended);
        END IF;
        RETURN json_build_object(
            'code', 200,
            'is_admin', is_admin_bool,
            'occasion_user', COALESCE(row_to_json(occasion_user)::jsonb, NULL),
            'link', occasion_link,
            'occasion', occasionId,
            'version_recommended', version_recommended
        );
    END IF;

    -- If the occasion user record is not found, the user is authenticated, and the occasion is open
    IF occasion_user IS NULL AND auth.uid() IS NOT NULL THEN
        -- Add the user to the occasion
        PERFORM add_user_to_occasion(occasionId, auth.uid());

        -- Fetch the updated occasion user record
        SELECT * INTO occasion_user
        FROM occasion_users
        WHERE occasion = occasionId
          AND "user" = auth.uid();
    END IF;

    -- If the occasion user record is still not found and the user is not an admin, return basic occasion data
    IF occasion_user IS NULL THEN
        RETURN json_build_object(
            'code', 200,
            'is_admin', is_admin_bool,
            'link', occasion_link,
            'occasion', occasionId,
            'version_recommended', version_recommended
        );
    END IF;

    -- Return full occasion data including the user and admin status
    RETURN json_build_object(
        'code', 200,
        'is_admin', is_admin_bool,
        'occasion_user', row_to_json(occasion_user)::jsonb,
        'link', occasion_link,
        'occasion', occasionId,
        'version_recommended', version_recommended
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.get_occasion_setup_blueprint_resources(p_draft uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE d public.occasion_setup_drafts; doc jsonb; source_id bigint; resources jsonb; source_resources jsonb;
BEGIN
 SELECT * INTO d FROM public.occasion_setup_drafts WHERE id=p_draft;
 IF d.id IS NULL OR auth.uid() IS NULL OR NOT (public.get_is_editor_on_unit(d.unit) OR public.get_is_manager_on_unit(d.unit)) THEN RAISE insufficient_privilege USING MESSAGE='Draft access denied'; END IF;
 source_id:=(d.data->>'sourceId')::bigint;
 IF source_id IS NOT NULL AND (NOT public.can_copy_occasion_source(source_id) OR NOT EXISTS(SELECT 1 FROM public.occasions WHERE id=source_id AND organization=d.organization)) THEN RAISE insufficient_privilege USING MESSAGE='Copy source denied'; END IF;
 doc:=coalesce(d.data#>'{blueprintLayoutDraft,layout}',jsonb_build_object(
  'schemaVersion',2,'symbolSetVersion',1,'canvas',jsonb_build_object('x',0,'y',0,'width',2400,'height',1600,'fill','#FFFFFFFF'),
  'styles','{}'::jsonb,'seatingDefaults','{}'::jsonb,'textPolicy',jsonb_build_object('language','und','direction','auto'),
  'nodes','[]'::jsonb,'sections','[]'::jsonb,'selectionUnits','[]'::jsonb,'attachments','[]'::jsonb,'presets','[]'::jsonb));
 IF doc->>'schemaVersion' IS DISTINCT FROM '2' THEN RAISE check_violation USING MESSAGE='BLUEPRINT_LAYOUT_MIGRATION_REQUIRED';END IF;
  resources:=public.blueprint_canonical_text_resources_internal(doc,NULL,p_draft,true);
  source_resources:=CASE WHEN source_id IS NULL THEN '{}'::jsonb ELSE public.blueprint_canonical_text_resources_internal(doc,source_id,NULL,true) END;
  resources:=resources||jsonb_build_object(
   'fontFamilies',coalesce(source_resources->'fontFamilies','{}')||(resources->'fontFamilies'),
   'textLayouts',coalesce(source_resources->'textLayouts','{}')||(resources->'textLayouts'),
   'numberSymbols',coalesce(source_resources->'numberSymbols','{}')||(resources->'numberSymbols'),
   'assets',public.blueprint_canonical_asset_resources_internal(doc,source_id,NULL)||public.blueprint_canonical_asset_resources_internal(doc,NULL,d.unit));
  RETURN public.bound_document_data_v1(jsonb_build_object('resources',resources));
END $function$

CREATE OR REPLACE FUNCTION public.get_occasion_users_for_edit(p_occasion_id bigint)
 RETURNS json
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_result jsonb;
  v_users jsonb;
BEGIN
  v_result := public.get_occasion_users_for_edit_invitation_base_v1(
    p_occasion_id
  )::jsonb;
  IF COALESCE((v_result->>'code')::integer, 500) <> 200 THEN
    RETURN v_result::json;
  END IF;

  WITH accepted AS (
    SELECT (entry->>'user')::uuid AS "user" FROM jsonb_array_elements(public.get_occasion_sign_in_email_statuses(p_occasion_id)) entry
  )
  SELECT COALESCE(jsonb_agg(
    row.value || jsonb_build_object(
      'data',
      (CASE WHEN jsonb_typeof(row.value->'data') = 'object'
        THEN row.value->'data' ELSE '{}'::jsonb END - 'is_invited'::text)
      || jsonb_build_object('is_invited', accepted."user" IS NOT NULL)
    )
  ), '[]'::jsonb)
  INTO v_users
  FROM jsonb_array_elements(v_result #> '{data,occasion_users}') row
  LEFT JOIN accepted ON accepted."user" = (row.value->>'user')::uuid;

  RETURN jsonb_set(v_result, '{data,occasion_users}', v_users)::json;
END;
$function$

CREATE OR REPLACE FUNCTION public.get_order_agreement_data_v1(p_order bigint)
