CREATE OR REPLACE FUNCTION public.get_order_change_summary_v1(p_order_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
 v_current jsonb; v_currency text; v_current_price numeric; v_reference eshop.orders_history; v_latest bigint;
 v_sent_at timestamptz; v_ref_tickets jsonb; v_cur_tickets jsonb;
 v_ref jsonb; v_cur jsonb; v_ticket jsonb; v_symbol text; v_state text;
 v_before jsonb; v_after jsonb; v_added jsonb; v_removed jsonb; v_changed jsonb;
 v_cancelled jsonb:='[]'; v_removed_tickets jsonb:='[]'; v_added_tickets jsonb:='[]';
 v_product_changes jsonb:='[]'; v_old_total numeric:=0; v_new_total numeric:=0;
 i integer; j integer; v_has_changes boolean;
BEGIN
 SELECT data,currency_code,price INTO v_current,v_currency,v_current_price FROM eshop.orders WHERE id=p_order_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'order_not_found'; END IF;
 SELECT id INTO v_latest FROM eshop.orders_history WHERE "order"=p_order_id
 ORDER BY created_at DESC,id DESC LIMIT 1;
 SELECT * INTO v_reference FROM eshop.orders_history WHERE "order"=p_order_id
 AND data->>'is_sent_to_customer'='true' ORDER BY created_at DESC,id DESC LIMIT 1;
 IF FOUND THEN v_sent_at:=v_reference.created_at;
 ELSE
  SELECT * INTO v_reference FROM eshop.orders_history WHERE "order"=p_order_id
  ORDER BY created_at ASC,id ASC LIMIT 1;
 END IF;
 v_ref_tickets:=coalesce(v_reference.data->'tickets','[]');
 v_cur_tickets:=coalesce(v_current->'tickets','[]');
 SELECT coalesce(sum(coalesce((p->>'price')::numeric,0)),0) INTO v_old_total
 FROM jsonb_array_elements(v_ref_tickets) t,jsonb_array_elements(coalesce(t->'products','[]')) p;
 SELECT coalesce(sum(coalesce((p->>'price')::numeric,0)),0) INTO v_new_total
 FROM jsonb_array_elements(v_cur_tickets) t,jsonb_array_elements(coalesce(t->'products','[]')) p;
 v_old_total:=coalesce(v_reference.price,v_old_total);
 v_new_total:=coalesce(v_current_price,v_new_total);
 -- Without history there is no evidence from which to invent a change.
 IF v_reference.id IS NOT NULL THEN
  FOR v_ref IN SELECT value FROM jsonb_array_elements(v_ref_tickets) LOOP
   SELECT value INTO v_cur FROM jsonb_array_elements(v_cur_tickets)
   WHERE (v_ref->>'id' IS NOT NULL AND value->>'id'=v_ref->>'id')
      OR (v_ref->>'id' IS NULL AND value=v_ref) LIMIT 1;
   v_symbol:=NULL; v_state:=NULL;
   -- Order membership prevents historical/foreign IDs leaking ticket metadata.
   SELECT t.ticket_symbol,t.state INTO v_symbol,v_state FROM eshop.tickets t
   WHERE t.id::text=v_ref->>'id' AND EXISTS(SELECT 1 FROM eshop.order_product_ticket opt
      WHERE opt.ticket=t.id AND opt."order"=p_order_id);
   v_ticket:=jsonb_build_object('id',v_ref->'id','ticket_symbol',
     coalesce(nullif(v_ref->>'ticket_symbol',''),v_symbol),'products',coalesce(v_ref->'products','[]'));
   IF v_cur IS NULL THEN
    IF v_state='storno' THEN v_cancelled:=v_cancelled||jsonb_build_array(v_ticket);
    ELSE v_removed_tickets:=v_removed_tickets||jsonb_build_array(v_ticket); END IF;
    CONTINUE;
   END IF;
   v_before:=coalesce(v_ref->'products','[]'); v_after:=coalesce(v_cur->'products','[]');
   v_added:='[]'; v_removed:='[]'; v_changed:='[]';
   -- Preserve duplicate instances; never pair products across different tickets.
   IF jsonb_array_length(v_after)>0 THEN
    FOR i IN REVERSE jsonb_array_length(v_after)-1..0 LOOP
     SELECT ordinality::integer-1 INTO j FROM jsonb_array_elements(v_before) WITH ORDINALITY
     WHERE value->>'id' IS NOT DISTINCT FROM v_after->i->>'id'
       AND value->>'title' IS NOT DISTINCT FROM v_after->i->>'title'
       AND abs(coalesce((value->>'price')::numeric,0)-coalesce((v_after->i->>'price')::numeric,0))<0.001
     ORDER BY ordinality LIMIT 1;
     IF j IS NOT NULL THEN v_before:=v_before-j; v_after:=v_after-i; END IF;
    END LOOP;
   END IF;
   IF jsonb_array_length(v_after)>0 THEN
    FOR i IN REVERSE jsonb_array_length(v_after)-1..0 LOOP
     SELECT ordinality::integer-1 INTO j FROM jsonb_array_elements(v_before) WITH ORDINALITY
     WHERE value->>'id' IS NOT DISTINCT FROM v_after->i->>'id' ORDER BY ordinality LIMIT 1;
     IF j IS NOT NULL THEN
      v_changed:=v_changed||jsonb_build_array(jsonb_build_object('from',v_before->j,'to',v_after->i));
      v_before:=v_before-j; v_after:=v_after-i;
     END IF;
    END LOOP;
   END IF;
   v_added:=v_after; v_removed:=v_before;
   IF jsonb_array_length(v_added)+jsonb_array_length(v_removed)+jsonb_array_length(v_changed)>0 THEN
    v_product_changes:=v_product_changes||jsonb_build_array(v_ticket||jsonb_build_object(
     'added',v_added,'removed',v_removed,'changed',v_changed));
   END IF;
  END LOOP;
  FOR v_cur IN SELECT value FROM jsonb_array_elements(v_cur_tickets) LOOP
   IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(v_ref_tickets) r
     WHERE (v_cur->>'id' IS NOT NULL AND r->>'id'=v_cur->>'id') OR (v_cur->>'id' IS NULL AND r=v_cur)) THEN
    v_added_tickets:=v_added_tickets||jsonb_build_array(v_cur);
   END IF;
  END LOOP;
 END IF;
 v_has_changes:=v_reference.id IS NOT NULL AND (jsonb_array_length(v_cancelled)+jsonb_array_length(v_removed_tickets)
   +jsonb_array_length(v_added_tickets)+jsonb_array_length(v_product_changes)>0 OR v_old_total<>v_new_total);
 RETURN jsonb_build_object('version',1,'cancelledTickets',v_cancelled,'removedTickets',v_removed_tickets,
   'addedTickets',v_added_tickets,'productChanges',v_product_changes,'referenceTotal',v_old_total,
   'currentTotal',v_new_total,'currencyCode',coalesce(v_currency,'CZK'),'hasChanges',v_has_changes,'referenceOrder',to_jsonb(v_reference),
   'referenceHistoryId',v_reference.id,'latestHistoryId',v_latest,'latestSentAt',v_sent_at);
END $function$

CREATE OR REPLACE FUNCTION public.get_order_deletion_context_v1(p_order bigint, p_command_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_occasion bigint; v_unit bigint; v_state text; v_vs bigint;
  v_command text; v_response jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE insufficient_privilege USING MESSAGE='unit manager, editor or organization admin required';
  END IF;
  -- Deletion removes the order, so a lost response is recovered from its receipt.
  IF p_command_id IS NOT NULL THEN
    SELECT CASE WHEN r.status='expired' THEN public.expired_client_mutation_response_v1(r)
      ELSE r.response END INTO v_response FROM public.client_mutation_receipts r
    JOIN public.occasions oc ON oc.id=r.occasion
    WHERE r.command_id=p_command_id AND r.actor_id=auth.uid()
      AND r.command_name='inventory.order.delete' AND r.status IN ('completed','expired')
      AND r.request_sha256=encode(extensions.digest(convert_to(
        jsonb_build_object('order',p_order)::text,'UTF8'),'sha256'),'hex')
      AND (public.get_is_manager_on_unit(oc.unit) OR public.get_is_editor_on_unit(oc.unit)
        OR public.get_is_admin_on_occasion(oc.id));
    IF FOUND THEN RETURN jsonb_build_object('response',v_response); END IF;
    IF EXISTS(SELECT 1 FROM public.client_mutation_receipts WHERE command_id=p_command_id) THEN
      RAISE insufficient_privilege USING MESSAGE='command id unavailable';
    END IF;
  END IF;
  SELECT o.occasion,oc.unit,o.state,pi.variable_symbol
    INTO v_occasion,v_unit,v_state,v_vs
  FROM eshop.orders o JOIN public.occasions oc ON oc.id=o.occasion
    LEFT JOIN eshop.payment_info pi ON pi.id=o.payment_info WHERE o.id=p_order;
  IF v_occasion IS NULL OR NOT (public.get_is_manager_on_unit(v_unit)
      OR public.get_is_editor_on_unit(v_unit)
      OR public.get_is_admin_on_occasion(v_occasion)) THEN
    RAISE insufficient_privilege USING MESSAGE='unit manager, editor or organization admin required';
  END IF;
  PERFORM public.check_occasion_writable(v_occasion);
  IF v_state IN ('waitlisted','preparing_payment')
    OR EXISTS(SELECT 1 FROM eshop.waitlist_offers WHERE order_id=p_order)
    OR EXISTS(SELECT 1 FROM eshop.orders WHERE source_waitlist_order_id=p_order)
    OR EXISTS(SELECT 1 FROM eshop.waitlist_acceptance_attempts
      WHERE target_order_id=p_order OR source_order_id=p_order) THEN
    RAISE EXCEPTION 'ORDER_HAS_WAITLIST_HISTORY';
  END IF;
  -- Metadata reads do not charge. External deletion attempts share the order
  -- mutation burst budget before credentials/provider work; final SQL charges
  -- its own mutation and item count through the existing command boundary.
  IF p_command_id IS NOT NULL THEN
    PERFORM public.admit_order_mutation_v1(v_occasion,0);
  END IF;
  SELECT m.data->>'command_id' INTO v_command FROM public.email_messages m
    WHERE m.order_id=p_order AND m.code='TICKET_ORDER_CONFIRMATION'
    ORDER BY m.id DESC LIMIT 1;
  RETURN jsonb_build_object('hasFakturoid',EXISTS(
    SELECT 1 FROM eshop.external_services WHERE unit=v_unit AND type='FAKTUROID'),
    'commandId',v_command,'variableSymbol',v_vs);
END; $function$

CREATE OR REPLACE FUNCTION public.get_order_details(orderid bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
    result_data jsonb;
    reference_history_data jsonb;
    form_fields_data jsonb;
    form_key uuid;
    latest_history_id bigint;
BEGIN
    -- Retrieve the order, occasion, payment info, and bank account as separate objects
    SELECT jsonb_build_object(
        'order', to_jsonb(o.*),
        'occasion', to_jsonb(occ.*),
        'payment_info', to_jsonb(pi.*),
        'bank_account', to_jsonb(ba.*)
    )
    INTO result_data
    FROM eshop.orders AS o
    LEFT JOIN public.occasions AS occ ON o.occasion = occ.id
    LEFT JOIN eshop.payment_info AS pi ON o.payment_info = pi.id
    LEFT JOIN eshop.bank_accounts AS ba ON pi.bank_account = ba.id
    WHERE o.id = orderId;

    -- Check if the order was found
    IF result_data IS NULL THEN
        RETURN jsonb_build_object('code', 404, 'message', 'Order not found.');
    END IF;

    -- Find the latest order_history ID for the given order
    SELECT oh.id
    INTO latest_history_id
    FROM eshop.orders_history AS oh
    WHERE oh.order = orderId
    ORDER BY oh.created_at DESC
    LIMIT 1;

    IF latest_history_id IS NOT NULL THEN
        result_data := result_data || jsonb_build_object('latest_history_id', latest_history_id);
    END IF;

    -- Get the data of the latest SENT history entry
    SELECT data INTO reference_history_data
    FROM eshop.orders_history
    WHERE "order" = orderId AND (data->>'is_sent_to_customer')::boolean IS TRUE
    ORDER BY created_at DESC LIMIT 1;

    -- If no sent record was found, get the oldest record as the reference
    IF NOT FOUND THEN
        SELECT data INTO reference_history_data
        FROM eshop.orders_history
        WHERE "order" = orderId
        ORDER BY created_at ASC LIMIT 1;
    END IF;

    -- Add the reference data to the result
    IF reference_history_data IS NOT NULL THEN
        result_data := result_data || jsonb_build_object('reference_history', reference_history_data);
    END IF;

    -- Extract the form's unique key from the order's data
    form_key := (result_data->'order'->'data'->>'form')::uuid;

    -- If a form key exists, fetch all associated form fields
    IF form_key IS NOT NULL THEN
        SELECT jsonb_object_agg(ff.id, to_jsonb(ff.*))
        INTO form_fields_data
        FROM public.form_fields AS ff
        JOIN public.forms AS f ON ff.form = f.id
        WHERE f.key = form_key;

        -- If form fields were found, add them to the result data
        IF form_fields_data IS NOT NULL THEN
            result_data := result_data || jsonb_build_object('form_fields', form_fields_data);
        END IF;
    END IF;

    -- Return a success response with the collected data
    RETURN jsonb_build_object('code', 200, 'data', result_data);

EXCEPTION WHEN OTHERS THEN
    -- Handle any unexpected errors and return a detailed error message
    RETURN jsonb_build_object(
        'code', 500,
        'message', 'An unexpected error occurred.',
        'detail', SQLERRM
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.get_order_email_overview_source_v1(p_order_id bigint, p_recipient text, p_command_id uuid, p_delivery jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE requested eshop.orders; root eshop.orders; occ public.occasions; f public.forms;
 s eshop.order_overview_sources;
BEGIN
 PERFORM public.require_client_sync_service_role_v1();
 SELECT * INTO STRICT requested FROM eshop.orders WHERE id=p_order_id;
 SELECT * INTO STRICT root FROM eshop.orders WHERE id=coalesce(requested.source_waitlist_order_id,requested.id) FOR UPDATE;
 SELECT * INTO STRICT occ FROM public.occasions WHERE id=root.occasion;
 SELECT * INTO f FROM public.forms WHERE id=root.form AND occasion=occ.id;
 IF requested.occasion IS DISTINCT FROM root.occasion OR requested.form IS DISTINCT FROM root.form
 OR requested.data->>'email' IS DISTINCT FROM p_recipient OR root.data->>'email' IS DISTINCT FROM p_recipient THEN
  RAISE EXCEPTION 'INVALID_OVERVIEW_RECIPIENT';
 END IF;
 -- Orders without a public form have no public overview route.
 IF f.id IS NULL THEN RETURN NULL; END IF;
 SELECT src.* INTO s FROM eshop.order_overview_sources src JOIN eshop.waitlist_capabilities cap USING(token_hash)
 WHERE cap.order_id=root.id AND cap.form_id=f.id AND cap.organization_id=occ.organization
 AND cap.kind='order_view' AND cap.revoked_at IS NULL AND cap.expires_at>statement_timestamp()
 AND src.expires_at=cap.expires_at ORDER BY src.created_at DESC LIMIT 1;
 IF s.token_hash IS NULL THEN
  -- Never silently replace an expired/revoked capability with a different link.
  IF EXISTS(SELECT 1 FROM eshop.waitlist_capabilities WHERE order_id=root.id AND kind='order_view') THEN RETURN NULL; END IF;
  IF p_delivery IS NOT NULL THEN
   PERFORM public.issue_order_overview_internal(root.id,p_delivery,p_command_id);
   SELECT * INTO STRICT s FROM eshop.order_overview_sources WHERE command_id=p_command_id;
  END IF;
 END IF;
 RETURN jsonb_build_object('orderId',root.id,'organization',occ.organization,'occasion',occ.id,'unit',occ.unit,
 'recipient',p_recipient,'occasionTitle',occ.title,'orderSymbol',root.order_symbol,
 'participantCount',(SELECT count(*) FROM public.get_order_tickets_internal(root.id)),
 'formLink',f.link,'webLink',(SELECT data->>'DEFAULT_URL' FROM public.organizations WHERE id=occ.organization),
 'source',CASE WHEN s.token_hash IS NOT NULL THEN jsonb_build_object('sealed',s.sealed,'contentHash',s.content_hash,'tokenHash',s.token_hash,'expiresAt',s.expires_at) END);
END $function$

