CREATE OR REPLACE FUNCTION public.get_scan_code(occasion_link text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
    occasion_id BIGINT;
    current_scan_code TEXT;
BEGIN
    -- 1. Retrieve occasion_id using occasion_link
    SELECT id
    INTO occasion_id
    FROM public.occasions
    WHERE id = public.resolve_occasion_link_internal(occasion_link);

    -- 2. Check if occasion_link is valid
    IF occasion_id IS NULL THEN
        RETURN jsonb_build_object(
            'code', 404,
            'message', 'Occasion link does not exist.'
        );
    END IF;

    -- 3. Verify if the user is an editor on the occasion
    IF NOT get_is_editor_order_view_on_occasion(occasion_id) THEN
        RETURN jsonb_build_object(
            'code', 403,
            'message', 'User is not authorized to view scan code for this occasion.'
        );
    END IF;

    -- 4. Retrieve the scan_code from the occasions_hidden table via the foreign key
    SELECT oh.secret
    INTO current_scan_code
    FROM public.occasions_hidden oh
    JOIN public.occasions o ON o.occasion_hidden = oh.id
    WHERE o.id = occasion_id
    LIMIT 1;

    -- 4.a. Handle case where scan_code is not found
    IF current_scan_code IS NULL THEN
        RETURN jsonb_build_object(
            'code', 404,
            'message', 'Scan code not found for the specified occasion.'
        );
    END IF;

    -- 5. Return the scan_code
    RETURN jsonb_build_object(
        'code', 200,
        'message', 'Scan code retrieved successfully.',
        'scan_code', current_scan_code
    );

EXCEPTION
    WHEN OTHERS THEN
        -- Handle any unexpected exceptions
        RETURN jsonb_build_object(
            'code', 500,
            'message', 'An unexpected error occurred.',
            'detail', SQLERRM
        );
END;
$function$

CREATE OR REPLACE FUNCTION public.get_scanner_receipts(p_session uuid, p_token text, p_operation_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE s public.scanner_sessions; result jsonb;
BEGIN
 s:=public.scanner_session_internal(p_session,p_token,true);
 IF coalesce(array_length(p_operation_ids,1),0)>50 THEN RAISE invalid_parameter_value; END IF;
 -- Expired/revoked devices can reconcile their immutable history, never perform a new write.
 SELECT coalesce(jsonb_agg(receipt),'[]'::jsonb) INTO result FROM public.scanner_operations WHERE session_id=p_session AND operation_id=ANY(p_operation_ids);
 RETURN jsonb_build_object('code',200,'data',result,'server_time',now());
END $function$

CREATE OR REPLACE FUNCTION public.get_spot_management_bundle(p_inventory_pool_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
    v_occasion_id bigint;
    v_spots_data jsonb;
    v_inventory_contexts_data jsonb;
    v_resources_data jsonb;
    v_resource_slots_data jsonb;
    v_order_product_tickets_data jsonb;
    v_orders_data jsonb;
    result jsonb;
BEGIN
    -- Get occasion for permission check from the inventory pool
    SELECT occasion INTO v_occasion_id
    FROM public.inventory_pools
    WHERE id = p_inventory_pool_id;

    IF v_occasion_id IS NULL THEN
        RAISE EXCEPTION 'Inventory Pool not found.';
    END IF;

    -- Permission check (assuming a similar function exists for order view)
    IF NOT get_is_editor_order_view_on_occasion(v_occasion_id) THEN
        RAISE EXCEPTION 'User is not authorized to view this occasion.';
    END IF;

    -- Aggregate all inventory_contexts for the pool
    SELECT COALESCE(jsonb_agg(to_jsonb(ic) ORDER BY ic.block_date), '[]'::jsonb)
    INTO v_inventory_contexts_data
    FROM public.inventory_contexts ic
    WHERE ic.inventory_pool = p_inventory_pool_id;

    -- Aggregate all spots that belong to any context within the specified pool
    SELECT COALESCE(jsonb_agg(to_jsonb(s) ORDER BY s.id), '[]'::jsonb)
    INTO v_spots_data
    FROM eshop.spots s
    WHERE s.inventory_context IN (
        SELECT id FROM public.inventory_contexts WHERE inventory_pool = p_inventory_pool_id
    );

    -- Aggregate all resources for the pool
    SELECT COALESCE(jsonb_agg(to_jsonb(r) ORDER BY r.title), '[]'::jsonb)
    INTO v_resources_data
    FROM public.resources r
    WHERE r.inventory_pool = p_inventory_pool_id;

    -- Aggregate all resource slots for all resources within the pool
    SELECT COALESCE(jsonb_agg(to_jsonb(rs) ORDER BY rs.id), '[]'::jsonb)
    INTO v_resource_slots_data
    FROM public.resource_slots rs
    WHERE rs.resource IN (
        SELECT id FROM public.resources WHERE inventory_pool = p_inventory_pool_id
    );

    -- NEW: Aggregate all order_product_tickets related to the spots in the pool
    SELECT COALESCE(jsonb_agg(to_jsonb(opt) ORDER BY opt.id), '[]'::jsonb)
    INTO v_order_product_tickets_data
    FROM eshop.order_product_ticket opt
    WHERE opt.id IN (
        SELECT DISTINCT s.order_product_ticket
        FROM eshop.spots s
        WHERE s.inventory_context IN (
            SELECT id FROM public.inventory_contexts WHERE inventory_pool = p_inventory_pool_id
        ) AND s.order_product_ticket IS NOT NULL
    );

    -- NEW: Aggregate all orders related to those order_product_tickets
    SELECT COALESCE(jsonb_agg(to_jsonb(o) ORDER BY o.id), '[]'::jsonb)
    INTO v_orders_data
    FROM eshop.orders o
    WHERE o.id IN (
        SELECT DISTINCT opt."order"
        FROM eshop.order_product_ticket opt
        WHERE opt.id IN (
            SELECT DISTINCT s.order_product_ticket
            FROM eshop.spots s
            WHERE s.inventory_context IN (
                SELECT id FROM public.inventory_contexts WHERE inventory_pool = p_inventory_pool_id
            ) AND s.order_product_ticket IS NOT NULL
        ) AND opt."order" IS NOT NULL
    );

    -- Construct the final bundle object with the new data
    result := jsonb_build_object(
        'spots', v_spots_data,
        'inventory_contexts', v_inventory_contexts_data,
        'resources', v_resources_data,
        'resource_slots', v_resource_slots_data,
        'order_product_tickets', v_order_product_tickets_data, -- Added
        'orders', v_orders_data  -- Added
    );

    RETURN result;
EXCEPTION
    WHEN OTHERS THEN
        -- A more robust error handling for production
        RETURN jsonb_build_object('code', 500, 'message', SQLERRM);
END;
$function$

CREATE OR REPLACE FUNCTION public.get_spots_for_inclusion_type_group(p_inclusion_type_group_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
    v_occasion_id bigint;
    v_spots_data jsonb;
    v_inclusion_types_data jsonb;
    result jsonb;
BEGIN
    -- Get occasion for permission check
    SELECT occasion INTO v_occasion_id
    FROM public.inclusion_type_groups
    WHERE id = p_inclusion_type_group_id;

    IF v_occasion_id IS NULL THEN
        RAISE EXCEPTION 'Inclusion Type Group not found.';
    END IF;

    -- Permission check
    IF NOT get_is_editor_order_view_on_occasion(v_occasion_id) THEN
        RAISE EXCEPTION 'User is not authorized to view this occasion.';
    END IF;

    -- Aggregate spots that belong to any inclusion type within the specified group
    SELECT COALESCE(jsonb_agg(to_jsonb(s) ORDER BY s.id), '[]'::jsonb)
    INTO v_spots_data
    FROM eshop.spots s
    WHERE s.inclusion_type IN (
        SELECT id FROM public.inclusion_types WHERE inclusion_type_group = p_inclusion_type_group_id
    );

    -- Aggregate all inclusion types for the group
    SELECT COALESCE(jsonb_agg(to_jsonb(t) ORDER BY t.created_at), '[]'::jsonb)
    INTO v_inclusion_types_data
    FROM public.inclusion_types t
    WHERE t.inclusion_type_group = p_inclusion_type_group_id;

    -- Construct the final bundle object
    result := jsonb_build_object(
        'spots', v_spots_data,
        'inclusion_types', v_inclusion_types_data
    );

    RETURN result;
EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object('code', 500, 'message', SQLERRM);
END;
$function$

CREATE OR REPLACE FUNCTION public.get_ticket_document_data_v1(p_ticket bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE occ bigint;
BEGIN
 SELECT occasion INTO occ FROM eshop.tickets WHERE id=p_ticket;
 IF occ IS NULL OR NOT (public.is_service_role() OR (auth.uid() IS NOT NULL AND public.get_is_editor_order_view_on_occasion(occ))) THEN
  RAISE insufficient_privilege USING MESSAGE='ticket document access denied'; END IF;
 PERFORM public.admit_ticket_document_internal_v1(occ);
