END $function$

CREATE OR REPLACE FUNCTION public.get_transactions_for_order(order_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_occasion_id bigint;
BEGIN

  SELECT occasion INTO v_occasion_id FROM eshop.orders WHERE id = order_id;
  IF NOT get_is_editor_order_view_on_occasion(v_occasion_id) THEN
    RAISE EXCEPTION 'User is not authorized to view transactions for this occasion.' USING ERRCODE = 'P0001';
  END IF;

  RETURN (
    SELECT jsonb_build_object(
      'order_state', o.state,
      'payment_info', (
        SELECT to_jsonb(pi)
        FROM eshop.payment_info pi
        WHERE pi.id = o.payment_info
      ),
      'transactions', COALESCE((
        SELECT jsonb_agg(
            to_jsonb(t) || jsonb_build_object('createdByName',
                trim(both from COALESCE(ui.name, '') || ' ' || COALESCE(ui.surname, ''))
            )
        )
        FROM eshop.transactions t
        LEFT JOIN public.user_info ui ON t.created_by = ui.id
        WHERE t.payment_info = o.payment_info
      ), '[]'::jsonb)
    )
    FROM eshop.orders o
    WHERE o.id = order_id
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.get_unit_app_landing(p_unit bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_org bigint;
  v_data jsonb;
  v_occasion bigint;
  v_title text;
  v_admin boolean;
BEGIN
  SELECT organization INTO v_org FROM public.units WHERE id = p_unit;
  v_admin := public.get_is_admin_on_organization(v_org);
  IF v_org IS NULL OR NOT (v_admin OR public.get_is_editor_view_on_unit(p_unit)
      OR public.get_is_editor_on_unit(p_unit) OR public.get_is_manager_on_unit(p_unit)) THEN
    RAISE insufficient_privilege USING MESSAGE = 'Access denied';
  END IF;
  SELECT data INTO v_data FROM public.organizations WHERE id = v_org;
  v_occasion := (v_data->>'DEFAULT_OCCASION')::bigint;
  SELECT title INTO v_title FROM public.occasions
    WHERE id = v_occasion AND organization = v_org;
  RETURN jsonb_build_object('enabled', coalesce((v_data->>'IS_APP_SUPPORTED')::boolean, false),
    'occasion_id', v_occasion, 'occasion_title', v_title, 'can_manage', v_admin);
END;
$function$

CREATE OR REPLACE FUNCTION public.get_unit_edit_data(p_unit_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
    v_unit_data jsonb;
    v_occasions_data jsonb;
BEGIN
    -- 1. Call get_unit_for_edit to get the unit details
    SELECT get_unit_for_edit(p_unit_id) INTO v_unit_data;

    -- Check if get_unit_for_edit returned an error (code != 200)
    IF (v_unit_data->>'code')::INT <> 200 THEN
          RAISE EXCEPTION 'get_unit_for_edit failed: %', v_unit_data->>'message';
    END IF;

    -- 2. Call get_all_occasions_for_edit_v212 to get the occasions
    -- Note: get_all_occasions_for_edit_v212 returns the array directly, not wrapped in code/data
    SELECT get_all_occasions_for_edit_v212(p_unit_id) INTO v_occasions_data;

    -- 3. Merge the results.
    -- v_unit_data has structure {code: 200, data: {...}}
    -- We want to return structure that includes both.
    -- Let's return { unit: ..., occasions: ... }

    RETURN jsonb_build_object(
        'unit', (v_unit_data->'data'),
        'occasions', v_occasions_data
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.get_unit_legal_profile(p_unit bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE p public.unit_legal_profiles; org bigint; admin boolean; result jsonb;
BEGIN
 SELECT organization INTO org FROM public.units WHERE id=p_unit;
 admin:=coalesce(public.check_is_admin_of_organization(org),false);
 IF auth.uid() IS NULL OR org IS NULL OR NOT (public.get_is_manager_on_unit(p_unit) OR admin) THEN
  RAISE EXCEPTION 'Legal profile access denied' USING ERRCODE='42501';
 END IF;
 SELECT * INTO p FROM public.unit_legal_profiles WHERE unit_id=p_unit;
 result:=jsonb_build_object('unitId',p_unit,'revision',coalesce(p.revision,0),'status',coalesce(p.status,'unverified'),
 'legalName',coalesce(p.legal_name,''),'countryCode',coalesce(p.country_code,''),
 'registrationNumber',coalesce(p.registration_number,''),'vatId',coalesce(p.vat_id,''),
 'address',jsonb_build_object('street',coalesce(p.street,''),'city',coalesce(p.city,''),'postalCode',coalesce(p.postal_code,'')),
 'contactEmail',coalesce(p.contact_email,''),'phone',coalesce(p.phone,''),'website',coalesce(p.website,''),
 'submittedAt',p.submitted_at,'verifiedAt',CASE WHEN p.status='verified' AND p.reviewed_organization_id=org THEN p.reviewed_at END,
 'feedbackToApplicant',CASE WHEN p.reviewed_organization_id=org THEN p.feedback_to_applicant END);
 IF admin AND p.reviewed_organization_id=org THEN
  result:=result||jsonb_build_object('reviewNote',p.review_note,'reviewSource',p.review_source);
 END IF;
 RETURN jsonb_build_object('code',200,'profile',result);
END $function$

CREATE OR REPLACE FUNCTION public.get_unit_verification_queue(p_organization bigint, p_status text DEFAULT 'pending'::text, p_cursor jsonb DEFAULT NULL::jsonb, p_limit integer DEFAULT 50)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE items jsonb; next_cursor jsonb; lim integer:=greatest(1,least(coalesce(p_limit,50),50));
BEGIN
 IF auth.uid() IS NULL OR NOT coalesce(public.check_is_admin_of_organization(p_organization),false) THEN
  RAISE EXCEPTION 'Verification queue access denied' USING ERRCODE='42501';
 END IF;
 IF p_status IS NULL OR p_status NOT IN ('pending','verified') THEN RETURN jsonb_build_object('code',422,'errorCode','INVALID_STATUS','fieldErrors','{}'::jsonb); END IF;
 SELECT coalesce(jsonb_agg(profile ORDER BY submitted_at,unit_id),'[]') INTO items FROM (
  SELECT p.unit_id,p.submitted_at,(public.get_unit_legal_profile(p.unit_id)->'profile')||jsonb_build_object('unitTitle',u.title) AS profile
  FROM public.unit_legal_profiles p JOIN public.units u ON u.id=p.unit_id
  WHERE u.organization=p_organization AND p.status=p_status
   AND (p_status<>'verified' OR p.reviewed_organization_id=p_organization)
   AND (p_cursor IS NULL OR (p.submitted_at,p.unit_id)>((p_cursor->>'submittedAt')::timestamptz,(p_cursor->>'unitId')::bigint))
  ORDER BY p.submitted_at,p.unit_id LIMIT lim+1
 ) page;
 IF jsonb_array_length(items)>lim THEN
  items:=items-(jsonb_array_length(items)-1);
  next_cursor:=jsonb_build_object('submittedAt',items->(lim-1)->'submittedAt','unitId',items->(lim-1)->'unitId');
 END IF;
 RETURN jsonb_build_object('code',200,'items',items,'nextCursor',next_cursor);
END $function$

CREATE OR REPLACE FUNCTION public.get_user_group_info(p_group_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
    v_occasion_id bigint;
    v_is_member boolean;
    v_is_editor_view boolean;
    result_json jsonb;
BEGIN
    -- First, find the occasion for the requested group to check permissions against it.
    SELECT occasion INTO v_occasion_id FROM public.user_group_info WHERE id = p_group_id;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('code', 404, 'message', 'User group not found');
    END IF;

    -- Authorization Check:
    -- 1. Check if the current user is a member of the group.
    SELECT EXISTS (
        SELECT 1 FROM public.user_groups WHERE "group" = p_group_id AND "user" = auth.uid()
    ) INTO v_is_member;

    -- 2. Check if the current user has editor view permissions on the occasion.
    v_is_editor_view := get_is_editor_view_on_occasion(v_occasion_id);

    -- If the user is neither a member nor has editor view permissions, deny access.
    IF NOT v_is_member AND NOT v_is_editor_view THEN
        RETURN jsonb_build_object('code', 403, 'message', 'Not authorized to view this user group');
    END IF;

    -- If authorized, proceed to fetch the data.
    SELECT
        jsonb_build_object(
            'id', ugi.id,
            'title', ugi.title,
            'description', ugi.description,
            'type', ugi.type,
            'data', ugi.data,
            'leader', ugi.leader,
            'place', ugi.place,
            'user_info', (SELECT jsonb_build_object('id', ui_leader.id, 'name', ui_leader.name, 'surname', ui_leader.surname) FROM public.user_info ui_leader WHERE ui_leader.id = ugi.leader),
            'places', (SELECT jsonb_build_object('id', p.id, 'title', p.title, 'description', p.description, 'type', p.type, 'created_at', p.created_at, 'coordinates', p.coordinates, 'is_hidden', p.is_hidden, 'updated_at', p.updated_at, 'occasion', p.occasion, 'order', p."order", 'icon', p.icon, 'unit', p.unit) FROM public.places p WHERE p.id = ugi.place),
            'user_groups', (SELECT COALESCE(jsonb_agg(jsonb_build_object('user_info', jsonb_build_object('id', p_ui.id, 'name', p_ui.name, 'surname', p_ui.surname))), '[]'::jsonb) FROM public.user_groups ug JOIN public.user_info p_ui ON ug."user" = p_ui.id WHERE ug."group" = ugi.id)
        )
    INTO result_json
    FROM public.user_group_info ugi
    WHERE ugi.id = p_group_id;

    -- Return the data in a structured response on success.
    RETURN jsonb_build_object('code', 200, 'data', result_json);

EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('code', 500, 'message', SQLERRM);
END;
$function$

CREATE OR REPLACE FUNCTION public.get_user_group_info_with_users(p_group_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
    v_occasion_id bigint;
    v_is_member boolean;
    v_is_editor_view boolean;
    v_current_user_is_admin boolean;
    result_json jsonb;
BEGIN
    -- Check if the group exists and get its occasion for permission checks.
    SELECT occasion INTO v_occasion_id FROM public.user_group_info WHERE id = p_group_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'USER_GROUP_NOT_FOUND';
    END IF;

    -- Authorization Check: User must be a member or have editor view permissions on the occasion.
    SELECT EXISTS (SELECT 1 FROM public.user_groups WHERE "group" = p_group_id AND "user" = auth.uid()) INTO v_is_member;
    v_is_editor_view := public.get_is_editor_view_on_occasion(v_occasion_id)
      OR public.get_is_editor_on_occasion(v_occasion_id);

    IF NOT v_is_member AND NOT v_is_editor_view THEN
        RAISE EXCEPTION 'NOT_AUTHORIZED';
    END IF;

    -- Get the current user's admin status for this specific group.
    SELECT is_admin INTO v_current_user_is_admin FROM public.user_groups WHERE "group" = p_group_id AND "user" = auth.uid();

    -- If authorized, build the final JSON object.
    SELECT
        jsonb_build_object(
            'id', ugi.id,
            'title', ugi.title,
            'description', ugi.description,
            'type', ugi.type,
            'data', ugi.data,
            'place', ugi.place, -- This is placeId
            'is_admin', COALESCE(v_current_user_is_admin, false),
            'places', (SELECT row_to_json(p)::jsonb||jsonb_build_object('aggregate_version',COALESCE((SELECT version FROM public.client_aggregate_versions WHERE aggregate_type='place' AND scope_type='occasion' AND scope_id=v_occasion_id AND aggregate_id=p.id::text),0)) FROM public.places p WHERE p.id = ugi.place),
            'user_groups', (
                SELECT COALESCE(jsonb_agg(
                    jsonb_build_object(
                        'is_admin', ug.is_admin,
                        'user_info', jsonb_build_object('id',p_ui.id,'name',p_ui.name,'surname',p_ui.surname)
                    )
                ), '[]'::jsonb)
                FROM public.user_groups ug
                JOIN public.user_info p_ui ON ug."user" = p_ui.id
                WHERE ug."group" = ugi.id
            )
        )
    INTO result_json
    FROM public.user_group_info ugi
    WHERE ugi.id = p_group_id;

    RETURN result_json;
END;
$function$

