CREATE OR REPLACE FUNCTION public.get_waitlist_email_context_v1(p_operation text, p_payload jsonb, p_actor uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE fid bigint; f public.forms; occ public.occasions; contexts jsonb; r jsonb; o eshop.orders;
BEGIN
 PERFORM public.require_client_sync_service_role_v1();
 IF p_operation='register' THEN SELECT id INTO fid FROM public.forms WHERE key=(p_payload->>'form')::uuid;
 ELSIF p_operation='send' THEN fid:=(p_payload->>'formId')::bigint;
 ELSE RAISE EXCEPTION 'Invalid email context operation'; END IF;
 SELECT * INTO STRICT f FROM public.forms WHERE id=fid; SELECT * INTO STRICT occ FROM public.occasions WHERE id=f.occasion;
 IF p_operation='send' AND NOT EXISTS(SELECT 1 FROM public.occasion_users WHERE occasion=occ.id AND "user"=p_actor AND is_editor_order) THEN
  RAISE insufficient_privilege USING MESSAGE='Order editor required'; END IF;
 contexts:='[]';
 IF p_operation='register' THEN contexts:=jsonb_build_array(jsonb_build_object('recipient',p_payload->>'email','organization',occ.organization,
  'occasion',occ.id,'unit',occ.unit,'occasionTitle',occ.title,'participantCount',jsonb_array_length(p_payload->'tickets'),'formLink',f.link));
 ELSE
  FOR r IN SELECT * FROM jsonb_array_elements(p_payload->'recipients') LOOP
   SELECT * INTO STRICT o FROM eshop.orders WHERE id=(r->>'orderId')::bigint AND form=fid;
   contexts:=contexts||jsonb_build_array(jsonb_build_object('orderId',o.id,'recipient',o.data->>'email','organization',occ.organization,
   'occasion',occ.id,'unit',occ.unit,'occasionTitle',occ.title,'orderSymbol',o.order_symbol,
   'participantCount',(SELECT count(*) FROM public.get_order_tickets_internal(o.id)),
   'offeredCount',(r->>'count')::integer,'formLink',f.link,'expiresAt',p_payload->>'expiresAt'));
  END LOOP;
 END IF;
 RETURN contexts;
END $function$

CREATE OR REPLACE FUNCTION public.get_waitlist_email_render_context_v1(p_order_id bigint, p_offer_id uuid DEFAULT NULL::uuid, p_recipient text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE o eshop.orders; f public.forms; occ public.occasions; org public.organizations;
 manage_message public.email_messages; manage_cap eshop.waitlist_capabilities;
 source_cap eshop.waitlist_capabilities; v_recipient text; v_timezone text;
BEGIN
 PERFORM public.require_client_sync_service_role_v1();
 SELECT * INTO o FROM eshop.orders WHERE id=p_order_id;
 SELECT * INTO f FROM public.forms WHERE id=o.form;
 SELECT * INTO occ FROM public.occasions WHERE id=o.occasion;
 SELECT * INTO org FROM public.organizations WHERE id=occ.organization;
 IF o.id IS NULL OR f.id IS NULL OR f.occasion<>occ.id OR o.state<>'waitlisted'
 OR (p_offer_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM eshop.waitlist_offers
  WHERE id=p_offer_id AND order_id=o.id AND form_id=f.id AND expires_at>clock_timestamp()
  AND EXISTS(SELECT 1 FROM eshop.waitlist_offer_slots WHERE offer_id=p_offer_id AND outcome='pending'))) THEN
  RAISE EXCEPTION 'waitlist_email_source_invalid';
 END IF;
 v_timezone:=public.get_waitlist_form_timezone_internal(f.id);
 v_recipient:=coalesce(p_recipient,o.data->>'email');
 SELECT * INTO manage_message FROM public.email_messages m
 WHERE m.order_id=o.id AND m.message_kind='waitlist_confirmation'
 AND m.recipient=v_recipient
 AND m.data ? 'waitlistEnvelope' ORDER BY m.id LIMIT 1;
 SELECT * INTO manage_cap FROM eshop.waitlist_capabilities
 WHERE order_id=o.id AND form_id=f.id AND organization_id=org.id
 AND kind='manage' AND revoked_at IS NULL;
 SELECT * INTO source_cap FROM eshop.waitlist_capabilities
 WHERE order_id=o.id AND form_id=f.id AND organization_id=org.id AND revoked_at IS NULL
 AND CASE WHEN p_offer_id IS NULL THEN kind='manage'
  ELSE kind='offer' AND offer_id=p_offer_id AND expires_at>clock_timestamp() END;
 IF manage_message.id IS NULL OR manage_cap.token_hash IS NULL OR source_cap.token_hash IS NULL THEN
  RAISE EXCEPTION 'waitlist_email_source_invalid';
 END IF;
 RETURN jsonb_build_object('orderId',o.id,'orderSymbol',o.order_symbol,
  'organization',org.id,'occasion',occ.id,'unit',occ.unit,'formLink',f.link,
  'webLink',org.data->>'DEFAULT_URL','replyTo',public.get_reply_to_email_for_order(o.id),
  'participantCount',(SELECT count(*) FROM public.get_order_tickets_internal(o.id)),
  'offeredCount',(SELECT count(*) FROM eshop.waitlist_offer_slots
    WHERE offer_id=p_offer_id AND outcome='pending'),
  'timeZone',v_timezone,
  'communicationTone',public.get_effective_form_data(f.id)->>'communication_tone',
  'toneSubstitutions',public.get_waitlist_email_tone_substitutions_internal(f.id),
  'expiresAt',(SELECT expires_at FROM eshop.waitlist_offers WHERE id=p_offer_id),
  'tokenHash',source_cap.token_hash,'manageTokenHash',manage_cap.token_hash,
  'manageEnvelope',manage_message.data->'waitlistEnvelope',
  'overviewSource',(SELECT jsonb_build_object('sealed',s.sealed,'contentHash',s.content_hash,'tokenHash',s.token_hash) FROM eshop.order_overview_sources s JOIN eshop.waitlist_capabilities c USING(token_hash) WHERE c.order_id=o.id AND c.kind='order_view' AND c.revoked_at IS NULL AND c.expires_at>statement_timestamp() ORDER BY s.created_at DESC LIMIT 1),
  'manageContentHash',manage_message.data->>'content_hash');
END $function$

CREATE OR REPLACE FUNCTION public.get_waitlist_offer_email_preview(p_form_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE f public.forms; occ public.occasions; resolved jsonb; tone jsonb;
 v_key text; v_value text; html text; subject text; v_timezone text; instructions_html text;
BEGIN
 SELECT * INTO STRICT f FROM public.forms WHERE id=p_form_id;
 PERFORM public.check_is_editor_order_on_occasion(f.occasion);
 SELECT * INTO STRICT occ FROM public.occasions WHERE id=f.occasion;
 resolved:=public.get_email_template_and_wrapper('waitlist_offer',
  jsonb_build_object('organization',occ.organization,'occasion',occ.id,'unit',occ.unit));
 -- Match the trusted delivery context's existing occasion/unit/org fallback.
 v_timezone:=public.get_waitlist_form_timezone_internal(f.id);
 -- Older preview clients know order/count/date variables, but not the new
 -- semantic copy keys. Expand only trusted copy here; leave those old keys.
 tone:=public.get_waitlist_email_tone_substitutions_internal(f.id);
 html:=resolved#>>'{template,html}'; subject:=resolved#>>'{template,subject}';
 instructions_html:=html;
 FOR v_key,v_value IN SELECT key,value FROM jsonb_each_text(tone) LOOP
  v_value:=replace(replace(replace(replace(replace(v_value,'&','&amp;'),'<','&lt;'),'>','&gt;'),'"','&quot;'),chr(39),'&#39;');
  html:=replace(html,'{{'||v_key||'}}',v_value);
  IF v_key<>'waitlist_offer_instructions' THEN
   instructions_html:=replace(instructions_html,'{{'||v_key||'}}',v_value);
  END IF;
  subject:=replace(subject,'{{'||v_key||'}}',v_value);
 END LOOP;
 IF html IS NOT NULL THEN resolved:=jsonb_set(resolved,'{template,html}',to_jsonb(html)); END IF;
 IF subject IS NOT NULL THEN resolved:=jsonb_set(resolved,'{template,subject}',to_jsonb(subject)); END IF;
 RETURN resolved||jsonb_build_object('code',200,'occasionTitle',occ.title,'formLink',f.link,
 'timeZone',v_timezone,'instructionsTemplateHtml',instructions_html,
 'communicationTone',public.get_effective_form_data(f.id)->>'communication_tone',
 'toneSubstitutions',tone);
END $function$

CREATE OR REPLACE FUNCTION public.get_waitlist_offer_proposal(p_form_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE f public.forms; c jsonb; proposals jsonb; available integer;
BEGIN
 SELECT * INTO STRICT f FROM public.forms WHERE id=p_form_id;
 PERFORM public.check_is_editor_order_on_occasion(f.occasion);
 PERFORM 1 FROM public.forms WHERE id=f.id FOR UPDATE;
 PERFORM public.expire_waitlist_form_internal(f.id);
 c:=public.get_form_capacity_snapshot_internal(f.id); available:=(c->>'offerablePlaces')::integer;
 -- count is the suggested allocation; waitingCount is the authoritative recipient limit.
 -- Keep unallocated eligible recipients so editors can adjust the allocation safely.
 SELECT coalesce(jsonb_agg(jsonb_build_object('orderId',order_id,'count',offered,'waitingCount',total) ORDER BY first_queue,order_id),'[]') INTO proposals
 FROM (SELECT order_id,min(waitlist_queue_at) first_queue,count(*) total,
  count(*) FILTER(WHERE position<=available) offered FROM
  (SELECT p.*,o.id order_id,row_number() OVER(ORDER BY p.waitlist_queue_at,p.created_at,p.id) position FROM eshop.tickets p
   JOIN LATERAL(SELECT DISTINCT x."order" FROM eshop.order_product_ticket x WHERE x.ticket=p.id) x ON true
   JOIN eshop.orders o ON o.id=x."order" WHERE o.form=f.id AND o.state='waitlisted' AND public.get_effective_waitlist_ticket_lifecycle_internal(p.id)='waiting' ) ranked GROUP BY order_id) grouped;
 RETURN jsonb_build_object('code',200,'formId',f.id,'revision',c->'revision','capacity',c,'recipients',proposals,
 'offerDurationSeconds',f.waitlist_offer_duration_seconds,'serverTime',clock_timestamp());
END $function$

CREATE OR REPLACE FUNCTION public.google_auth_resolve_account_v1(p_organization bigint, p_raw_email text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_users uuid[];
BEGIN
  PERFORM public.require_service_role();
  SELECT array_agg(id) INTO v_users FROM public.user_info
  WHERE organization=p_organization AND lower(btrim(email_readonly))=lower(btrim(p_raw_email));
  IF cardinality(v_users) IS DISTINCT FROM 1 THEN RETURN NULL; END IF;
  RETURN public.resolve_existing_user_session_v1(v_users[1]);
END $function$

CREATE OR REPLACE FUNCTION public.google_auth_transition_v1(p_operation text, p_attempt uuid, p_secret_hash text, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE a public.external_login_attempts%rowtype; c public.external_login_clients%rowtype;
  v_user uuid; v_existing uuid; v_target jsonb; v_status text; v_signup boolean;
BEGIN
  PERFORM public.require_service_role();
  IF p_operation='start' THEN
    SELECT * INTO c FROM public.external_login_clients WHERE client_id=p_payload->>'clientId' AND enabled;
    IF c.client_id IS NULL OR c.organization IS DISTINCT FROM (p_payload->>'organization')::bigint
      OR c.origin IS DISTINCT FROM p_payload->>'origin' THEN RAISE EXCEPTION 'provider_unavailable'; END IF;
    INSERT INTO public.external_login_attempts(id,client_id,organization,intent,status,challenge,state_hash,nonce_hash,bootstrap_hash,verifier_encrypted)
    VALUES(p_attempt,c.client_id,c.organization,coalesce(p_payload->>'intent','login'),'created',p_payload->>'challenge',p_payload->>'stateHash',p_payload->>'nonceHash',p_secret_hash,p_payload->>'verifierEncrypted') RETURNING * INTO a;
    RETURN to_jsonb(a)||jsonb_build_object('redirectUri',c.redirect_uri,'origin',c.origin);
  END IF;
  SELECT * INTO a FROM public.external_login_attempts WHERE id=p_attempt FOR UPDATE;
  IF a.id IS NULL OR a.expires_at<=clock_timestamp() THEN RAISE EXCEPTION 'attempt_expired'; END IF;
  SELECT * INTO c FROM public.external_login_clients WHERE client_id=a.client_id AND enabled;
  IF c.client_id IS NULL THEN RAISE EXCEPTION 'provider_unavailable'; END IF;
  IF p_operation='bootstrap' THEN
    IF a.status<>'created' OR a.bootstrap_hash IS DISTINCT FROM p_secret_hash THEN RAISE EXCEPTION 'invalid_provider_proof'; END IF;
    UPDATE public.external_login_attempts SET status='bootstrapped',bootstrap_hash=NULL,browser_hash=p_payload->>'browserHash' WHERE id=a.id RETURNING * INTO a;
  ELSIF p_operation='provider' THEN
    IF a.status<>'bootstrapped' OR a.state_hash IS DISTINCT FROM p_secret_hash
       OR a.browser_hash IS DISTINCT FROM p_payload->>'browserHash' THEN RAISE EXCEPTION 'invalid_provider_proof'; END IF;
    IF p_payload->>'issuer' <> 'https://accounts.google.com' OR coalesce(p_payload->>'subject','')='' THEN RAISE EXCEPTION 'invalid_provider_proof'; END IF;
    UPDATE public.external_login_attempts SET status='provider_verified',issuer=p_payload->>'issuer',subject=p_payload->>'subject',
      email=lower(btrim(p_payload->>'email')),proposed_name=p_payload->>'name',mailbox_verified=(p_payload->>'mailboxVerified')::boolean,
      handoff_hash=p_payload->>'handoffHash',handoff_expires_at=clock_timestamp()+interval '60 seconds',verifier_encrypted=NULL
    WHERE id=a.id RETURNING * INTO a;
  ELSIF p_operation='claim' THEN
    IF a.status<>'provider_verified' OR a.handoff_hash IS DISTINCT FROM p_secret_hash
      OR a.handoff_expires_at<=clock_timestamp() OR a.challenge IS DISTINCT FROM p_payload->>'challenge' THEN RAISE EXCEPTION 'invalid_provider_proof'; END IF;
    SELECT user_id INTO v_user FROM public.external_login_identities WHERE organization=a.organization AND issuer=a.issuer AND subject=a.subject;
    IF v_user IS NOT NULL THEN
      IF public.resolve_existing_user_session_v1(v_user) IS NULL THEN RAISE EXCEPTION 'account_identity_inconsistent'; END IF;
      v_status := CASE WHEN a.intent='unlink' OR (public.resolve_existing_user_session_v1(v_user)->>'requiresMfa')::boolean IS TRUE THEN 'awaiting_account_proof' ELSE 'ready' END;
    ELSE
      IF a.intent='unlink' THEN RAISE EXCEPTION 'account_proof_failed'; END IF;
      SELECT (data->>'IS_REGISTRATION_ENABLED')::boolean IS TRUE INTO v_signup FROM public.organizations WHERE id=a.organization;
      IF EXISTS(SELECT 1 FROM public.user_info WHERE organization=a.organization AND lower(btrim(email_readonly))=a.email) OR v_signup IS DISTINCT FROM true THEN v_status := 'awaiting_account_proof';
      ELSE v_status := 'awaiting_profile'; END IF;
    END IF;
    UPDATE public.external_login_attempts SET status=v_status,target_user=v_user,handoff_hash=NULL,continuation_hash=p_payload->>'continuationHash'
    WHERE id=a.id RETURNING * INTO a;
  ELSE
    IF a.continuation_hash IS DISTINCT FROM p_secret_hash OR a.challenge IS DISTINCT FROM p_payload->>'challenge' THEN RAISE EXCEPTION 'invalid_provider_proof'; END IF;
    IF p_operation='mfa_begin' THEN
      IF a.status NOT IN ('awaiting_account_proof','awaiting_profile') THEN RAISE EXCEPTION 'invalid_provider_proof'; END IF;
      v_user := (p_payload->>'provenUser')::uuid;
      v_target := public.resolve_existing_user_session_v1(v_user);
      IF v_target IS NULL OR (v_target->>'organization')::bigint<>a.organization
        OR (a.target_user IS NOT NULL AND a.target_user<>v_user) THEN RAISE EXCEPTION 'account_proof_failed'; END IF;
      UPDATE public.external_login_attempts SET status='awaiting_mfa',mfa_user=v_user,
        mfa_session_encrypted=p_payload->>'sessionEncrypted',continuation_hash=p_payload->>'continuationHash' WHERE id=a.id RETURNING * INTO a;
    ELSIF p_operation='mfa_proven' THEN
      IF a.status<>'awaiting_mfa' OR a.mfa_user IS DISTINCT FROM (p_payload->>'provenUser')::uuid THEN RAISE EXCEPTION 'account_proof_failed'; END IF;
      UPDATE public.external_login_attempts SET status='awaiting_account_proof',mfa_session_encrypted=NULL WHERE id=a.id RETURNING * INTO a;
    ELSIF p_operation='mailbox_send' THEN
      IF a.status<>'awaiting_profile' OR a.mailbox_verified OR a.mailbox_hash IS NOT NULL THEN RAISE EXCEPTION 'invalid_provider_proof'; END IF;
      UPDATE public.external_login_attempts SET mailbox_hash=p_payload->>'mailboxHash' WHERE id=a.id RETURNING * INTO a;
    ELSIF p_operation='mailbox_verify' THEN
      IF a.status<>'awaiting_profile' OR a.mailbox_tries>=5 THEN RAISE EXCEPTION 'invalid_provider_proof'; END IF;
      UPDATE public.external_login_attempts SET mailbox_tries=mailbox_tries+1,mailbox_verified=(mailbox_hash IS NOT NULL AND mailbox_hash=p_payload->>'mailboxHash'),
        continuation_hash=p_payload->>'continuationHash' WHERE id=a.id RETURNING * INTO a;
    ELSIF p_operation='unlink' THEN
      IF a.intent<>'unlink' OR a.status<>'awaiting_account_proof' OR a.target_user IS DISTINCT FROM (p_payload->>'provenUser')::uuid
        OR public.resolve_existing_user_session_v1(a.target_user) IS NULL THEN RAISE EXCEPTION 'account_proof_failed'; END IF;
      DELETE FROM public.external_login_identities WHERE organization=a.organization AND user_id=a.target_user AND issuer=a.issuer AND subject=a.subject;
      IF NOT FOUND THEN RAISE EXCEPTION 'identity_already_linked'; END IF;
      DELETE FROM public.external_login_attempts WHERE id<>a.id AND organization=a.organization AND (target_user=a.target_user OR (issuer=a.issuer AND subject=a.subject));
      UPDATE public.external_login_attempts SET status='consumed',continuation_hash=NULL WHERE id=a.id RETURNING * INTO a;
    ELSIF p_operation IN ('link','register') THEN
      IF a.intent<>'login' THEN RAISE EXCEPTION 'invalid_provider_proof'; END IF;
      IF a.status NOT IN ('awaiting_account_proof','awaiting_profile') THEN RAISE EXCEPTION 'invalid_provider_proof'; END IF;
      PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('user-sign-in-email:'||a.organization::text,0));
      IF p_operation='link' THEN
        v_user := (p_payload->>'provenUser')::uuid;
        v_target := public.resolve_existing_user_session_v1(v_user);
        IF v_target IS NULL OR (v_target->>'organization')::bigint<>a.organization OR (a.target_user IS NOT NULL AND a.target_user<>v_user) THEN RAISE EXCEPTION 'account_proof_failed'; END IF;
      ELSE
        SELECT (data->>'IS_REGISTRATION_ENABLED')::boolean IS TRUE INTO v_signup FROM public.organizations WHERE id=a.organization FOR SHARE;
        IF v_signup IS DISTINCT FROM true THEN RAISE EXCEPTION 'registration_disabled'; END IF;
        IF NOT a.mailbox_verified THEN RAISE EXCEPTION 'mailbox_proof_required'; END IF;
        IF EXISTS(SELECT 1 FROM public.user_info WHERE organization=a.organization AND lower(btrim(email_readonly))=a.email) THEN
          UPDATE public.external_login_attempts SET status='awaiting_account_proof',continuation_hash=p_payload->>'continuationHash' WHERE id=a.id RETURNING * INTO a;
          RETURN to_jsonb(a)||jsonb_build_object('redirectUri',c.redirect_uri,'origin',c.origin);
        END IF;
        IF EXISTS(SELECT 1 FROM auth.users WHERE email=public.format_auth_email(a.organization,a.email)) THEN RAISE EXCEPTION 'account_identity_inconsistent'; END IF;
        IF coalesce(p_payload#>>'{profile,name}','')='' OR coalesce(p_payload#>>'{profile,surname}','')=''
          OR p_payload->>'consent' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'profile_required'; END IF;
        v_user := public.create_user_in_organization_with_data_pure(a.organization,a.email,p_payload->>'password',p_payload->'profile');
        PERFORM public.initialize_registration_unit_v1(v_user,a.organization,a.email,coalesce(nullif(p_payload->>'unitTitle',''),'Moje akce'));
      END IF;
      SELECT user_id INTO v_existing FROM public.external_login_identities WHERE organization=a.organization AND issuer=a.issuer AND subject=a.subject;
      IF v_existing IS NOT NULL AND v_existing<>v_user THEN RAISE EXCEPTION 'identity_already_linked'; END IF;
      IF EXISTS(SELECT 1 FROM public.external_login_identities WHERE organization=a.organization AND user_id=v_user AND subject<>a.subject) THEN RAISE EXCEPTION 'identity_already_linked'; END IF;
      INSERT INTO public.external_login_identities(organization,user_id,issuer,subject) VALUES(a.organization,v_user,a.issuer,a.subject)
        ON CONFLICT(organization,provider,issuer,subject) DO NOTHING;
      UPDATE public.external_login_attempts SET status='ready',target_user=v_user,continuation_hash=p_payload->>'continuationHash' WHERE id=a.id RETURNING * INTO a;
    ELSIF p_operation='issue' THEN
      IF a.status<>'ready' OR NOT EXISTS(SELECT 1 FROM public.external_login_identities WHERE organization=a.organization AND user_id=a.target_user AND issuer=a.issuer AND subject=a.subject)
        THEN RAISE EXCEPTION 'invalid_provider_proof'; END IF;
      UPDATE public.external_login_attempts SET status='issuing' WHERE id=a.id RETURNING * INTO a;
    ELSIF p_operation='finish' THEN
      IF a.status<>'issuing' OR NOT EXISTS(SELECT 1 FROM public.external_login_identities WHERE organization=a.organization AND user_id=a.target_user AND issuer=a.issuer AND subject=a.subject)
        OR public.resolve_existing_user_session_v1(a.target_user) IS NULL THEN RAISE EXCEPTION 'account_identity_inconsistent'; END IF;
      UPDATE public.external_login_attempts SET status='consumed',continuation_hash=NULL,mailbox_hash=NULL,browser_hash=NULL WHERE id=a.id RETURNING * INTO a;
    ELSE RAISE EXCEPTION 'invalid_operation'; END IF;
  END IF;
  RETURN to_jsonb(a)||jsonb_build_object('redirectUri',c.redirect_uri,'origin',c.origin);
END $function$

CREATE OR REPLACE FUNCTION public.import_occasion_users_from_csv_apply_v1(p_occasion_id bigint, p_rows jsonb, p_delete_user_ids jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
    v_unit_id bigint;
    v_organization_id bigint;
    v_row jsonb;
    v_data_patch jsonb;
    v_services_patch jsonb;
    v_group_assignments jsonb := '[]'::jsonb;
    v_user_id uuid;
    v_email text;
    v_delivery_email text;
    v_existing_email text;
    v_has_delivery_email boolean;
    v_response jsonb;
    v_is_occasion_member boolean;
    v_created integer := 0;
    v_updated integer := 0;
    v_deleted integer := 0;
    v_global_before jsonb;
BEGIN
    SELECT o.unit, u.organization
      INTO v_unit_id, v_organization_id
      FROM public.occasions o
      JOIN public.units u ON u.id = o.unit
     WHERE o.id = p_occasion_id;

    IF v_unit_id IS NULL THEN
        RAISE EXCEPTION 'OCCASION_NOT_FOUND';
    END IF;

    IF NOT (
        public.get_is_manager_on_occasion(p_occasion_id)
        OR public.get_is_admin_on_occasion(p_occasion_id)
        OR public.get_is_editor_on_unit(v_unit_id)
    ) THEN
        RAISE EXCEPTION 'NOT_AUTHORIZED';
    END IF;

    IF COALESCE(jsonb_typeof(p_rows), 'null') <> 'array'
       OR COALESCE(jsonb_typeof(p_delete_user_ids), 'null') <> 'array' THEN
        RAISE EXCEPTION 'INVALID_IMPORT_PAYLOAD';
    END IF;
    IF jsonb_array_length(p_rows) > 10000
       OR jsonb_array_length(p_delete_user_ids) > 10000 THEN
        RAISE EXCEPTION 'IMPORT_PAYLOAD_TOO_LARGE';
    END IF;

    IF EXISTS (
        SELECT 1 FROM jsonb_array_elements(p_rows) item
         WHERE jsonb_typeof(item) <> 'object'
            OR jsonb_typeof(item->'data') <> 'object'
    ) THEN
        RAISE EXCEPTION 'INVALID_IMPORT_ROW';
    END IF;
    IF EXISTS (
        SELECT 1 FROM jsonb_array_elements(p_rows) item
         WHERE NULLIF(btrim(item->'data'->>'email'), '') IS NULL
    ) THEN
        RAISE EXCEPTION 'EMAIL_REQUIRED';
    END IF;
    IF EXISTS (
        SELECT 1 FROM jsonb_array_elements(p_rows) item
         WHERE length(btrim(item->'data'->>'email')) > 254
            OR lower(btrim(item->'data'->>'email'))
               !~ '^[^[:space:]@]+@[^[:space:]@]+$'
            OR (
                item ? 'email_delivery'
                AND (
                    NULLIF(btrim(item->>'email_delivery'), '') IS NULL
                    OR length(btrim(item->>'email_delivery')) > 254
                    OR lower(btrim(item->>'email_delivery'))
                       !~ '^[^[:space:]@]+@[^[:space:]@]+$'
                )
            )
    ) THEN
        RAISE EXCEPTION 'INVALID_EMAIL';
    END IF;
    IF EXISTS (
        SELECT 1
          FROM jsonb_array_elements(p_rows) item
         GROUP BY lower(btrim(item->'data'->>'email'))
        HAVING count(*) > 1
    ) THEN
        RAISE EXCEPTION 'DUPLICATE_ACCOUNT_EMAIL';
    END IF;
    IF EXISTS (
        SELECT 1
          FROM jsonb_array_elements(p_rows) item
         WHERE NULLIF(item->>'user_id', '') IS NOT NULL
         GROUP BY item->>'user_id'
        HAVING count(*) > 1
    ) THEN
        RAISE EXCEPTION 'DUPLICATE_USER_ID';
    END IF;
    IF EXISTS (
        SELECT 1
          FROM jsonb_array_elements(p_rows) item
          JOIN jsonb_array_elements_text(p_delete_user_ids) deleted(id)
            ON deleted.id = item->>'user_id'
    ) THEN
        RAISE EXCEPTION 'CONFLICTING_IMPORT_OPERATION';
    END IF;

    -- Serialize all CSV imports for one occasion. The group RPC uses the same
    -- lock, which is transaction-reentrant for this session.
    PERFORM pg_catalog.pg_advisory_xact_lock(p_occasion_id);
    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended(
            'user-sign-in-email:' || v_organization_id::text, 0
        )
    );

    FOR v_row IN SELECT value FROM jsonb_array_elements(p_rows)
    LOOP
        IF COALESCE(jsonb_typeof(v_row), 'null') <> 'object'
           OR COALESCE(jsonb_typeof(v_row->'data'), 'null') <> 'object' THEN
            RAISE EXCEPTION 'INVALID_IMPORT_ROW';
        END IF;

        v_data_patch := v_row->'data';
        v_email := lower(btrim(v_data_patch->>'email'));
        v_has_delivery_email := v_row ? 'email_delivery';
        v_delivery_email := lower(btrim(COALESCE(
            v_row->>'email_delivery', v_data_patch->>'email'
        )));
        IF v_email IS NULL OR v_email = '' THEN
            RAISE EXCEPTION 'EMAIL_REQUIRED';
        END IF;
        IF v_delivery_email IS NULL OR v_delivery_email = '' THEN
            RAISE EXCEPTION 'DELIVERY_EMAIL_REQUIRED';
        END IF;

        v_user_id := NULLIF(v_row->>'user_id', '')::uuid;
        v_is_occasion_member := false;

        IF v_user_id IS NULL THEN
            -- Resolve against the occasion first. This makes a retry or a
            -- stale client safe: add_user_to_occasion must never replace an
            -- existing occasion row with profile data.
            SELECT ou."user"
              INTO v_user_id
              FROM public.occasion_users ou
              JOIN public.user_info ui ON ui.id = ou."user"
             WHERE ou.occasion = p_occasion_id
               AND lower(btrim(COALESCE(ui.email_readonly,
                                        ou.data->>'email'))) = v_email
             ORDER BY ou.created_at
             LIMIT 1;

            v_is_occasion_member := v_user_id IS NOT NULL;

            -- A CSV create may also refer to an organization user who simply
            -- is not on this occasion yet. Reuse that identity before creating
            -- a new Auth user.
            IF v_user_id IS NULL THEN
                SELECT ui.id
                  INTO v_user_id
                 FROM public.user_info ui
                 WHERE ui.organization = v_organization_id
                   AND lower(btrim(ui.email_readonly)) = v_email
                 ORDER BY ui.created_at
                 LIMIT 1;
            END IF;

            IF v_user_id IS NULL AND EXISTS (
                SELECT 1 FROM public.user_info ui
                 WHERE ui.organization = v_organization_id
                   AND lower(btrim(ui.email_readonly)) = v_email
            ) THEN
                -- The client assigns deterministic +N account emails for a
                -- CSV batch. Reassigning one here would make a later retry
                -- point at a different person. Without a stable external ID,
                -- reject the stale/colliding input instead of guessing identity.
                RAISE EXCEPTION 'ACCOUNT_EMAIL_ALREADY_EXISTS';
            END IF;

            IF v_user_id IS NULL THEN
                SELECT au.id
                  INTO v_user_id
                  FROM auth.users au
                 WHERE lower(au.email) = lower(v_organization_id::text || '+' || v_email)
                 ORDER BY au.created_at
                 LIMIT 1;
            END IF;

            IF v_user_id IS NULL THEN
                v_user_id := public.create_user_in_organization_with_data_pure(
                    v_organization_id,
                    v_email,
                    NULLIF(v_delivery_email, v_email),
                    encode(gen_random_bytes(16), 'hex'),
                    v_data_patch
                );
            ELSIF NOT EXISTS (
                SELECT 1 FROM public.user_info ui WHERE ui.id = v_user_id
            ) THEN
                INSERT INTO public.user_info (
                    id, organization, email_readonly, email_delivery, data,
                    name, surname, sex
                ) VALUES (
                    v_user_id,
                    v_organization_id,
                    v_email,
                    v_delivery_email,
                    v_data_patch,
                    v_data_patch->>'name',
                    v_data_patch->>'surname',
                    v_data_patch->>'sex'
                );
            END IF;

            IF v_is_occasion_member THEN
                v_updated := v_updated + 1;
            ELSE
                v_response := public.add_user_to_occasion_internal_v1(p_occasion_id, v_user_id);
                IF COALESCE((v_response->>'code')::integer, 500) <> 200 THEN
                    RAISE EXCEPTION 'ADD_USER_TO_OCCASION_FAILED: %',
                        COALESCE(v_response->>'message',
                                 'code ' || (v_response->>'code'));
                END IF;
                v_created := v_created + 1;
            END IF;
        ELSE
            SELECT lower(btrim(COALESCE(ui.email_readonly, ou.data->>'email')))
              INTO v_existing_email
              FROM public.occasion_users ou
              JOIN public.user_info ui ON ui.id = ou."user"
             WHERE ou.occasion = p_occasion_id
               AND ou."user" = v_user_id;

            IF NOT FOUND THEN
                RAISE EXCEPTION 'USER_NOT_ON_OCCASION';
            END IF;
            IF v_existing_email IS DISTINCT FROM v_email THEN
                RAISE EXCEPTION 'USER_EMAIL_MISMATCH';
            END IF;
            v_updated := v_updated + 1;
        END IF;

        SELECT to_jsonb(ui) INTO v_global_before FROM public.user_info ui WHERE id=v_user_id FOR UPDATE;
        UPDATE public.user_info ui
           SET data = COALESCE(ui.data, '{}'::jsonb)
                      || public.get_user_profile_data_patch(v_data_patch),
               email_delivery = CASE
                   WHEN v_has_delivery_email
                       THEN NULLIF(v_delivery_email, v_email)
                   ELSE ui.email_delivery
               END,
               name = CASE WHEN v_data_patch ? 'name'
                           THEN v_data_patch->>'name' ELSE ui.name END,
               surname = CASE WHEN v_data_patch ? 'surname'
                              THEN v_data_patch->>'surname' ELSE ui.surname END,
               sex = CASE WHEN v_data_patch ? 'sex'
                          THEN v_data_patch->>'sex' ELSE ui.sex END,
               phone = CASE WHEN v_data_patch ? 'phone'
                            THEN v_data_patch->>'phone' ELSE ui.phone END,
               birth_date = CASE WHEN v_data_patch ? 'birthDate'
                                 THEN NULLIF(v_data_patch->>'birthDate', '')::date
                                 ELSE ui.birth_date END
         WHERE ui.id = v_user_id;

        PERFORM public.publish_user_profile_change_internal_v1(v_user_id,p_occasion_id,v_global_before);

        IF v_row ? 'services' THEN
            IF COALESCE(jsonb_typeof(v_row->'services'), 'null') <> 'object' THEN
                RAISE EXCEPTION 'INVALID_SERVICES_PATCH';
            END IF;
            v_services_patch := v_row->'services';
        ELSE
            v_services_patch := NULL;
        END IF;

        UPDATE public.occasion_users ou
           SET data = COALESCE(ou.data, '{}'::jsonb) || v_data_patch,
               services = CASE
                   WHEN v_services_patch IS NULL THEN ou.services
                   ELSE COALESCE(ou.services, '{}'::jsonb) || v_services_patch
               END
         WHERE ou.occasion = p_occasion_id
           AND ou."user" = v_user_id;

        IF v_row ? 'group_title' THEN
            v_group_assignments := v_group_assignments || jsonb_build_array(
                jsonb_build_object(
                    'user_id', v_user_id,
                    'group_title', v_row->>'group_title'
                )
            );
        END IF;
    END LOOP;

    FOR v_user_id IN
        SELECT value::uuid FROM jsonb_array_elements_text(p_delete_user_ids)
    LOOP
        IF NOT EXISTS (
            SELECT 1 FROM public.occasion_users ou
             WHERE ou.occasion = p_occasion_id AND ou."user" = v_user_id
        ) THEN
            RAISE EXCEPTION 'DELETE_USER_NOT_ON_OCCASION';
        END IF;
        PERFORM public.remove_occasion_user_domain_internal_v1(p_occasion_id,v_user_id);
        v_deleted := v_deleted + 1;
    END LOOP;

    IF jsonb_array_length(v_group_assignments) > 0 THEN
        PERFORM public.import_user_group_assignments_internal_v1(
            p_occasion_id,
            v_group_assignments
        );
    END IF;

    RETURN jsonb_build_object(
        'code', 200,
        'created', v_created,
        'updated', v_updated,
        'deleted', v_deleted,
        'groups', jsonb_array_length(v_group_assignments)
    );
END;
$function$

