CREATE OR REPLACE FUNCTION public.lock_event_deletion_scope_internal_v1(p_occasion bigint, p_ids bigint[])
 RETURNS bigint[]
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE children bigint[]; current_children bigint[];
BEGIN
 SELECT ARRAY(SELECT DISTINCT event_child FROM public.event_groups WHERE event_parent=ANY(p_ids) AND NOT event_child=ANY(p_ids) ORDER BY event_child) INTO children;
 IF EXISTS(SELECT 1 FROM public.events WHERE id=ANY(children) AND occasion<>p_occasion) THEN RAISE insufficient_privilege USING MESSAGE='event child outside occasion'; END IF;
 PERFORM 1 FROM public.events WHERE occasion=p_occasion AND id=ANY(p_ids||children) ORDER BY id FOR UPDATE;
 SELECT ARRAY(SELECT DISTINCT event_child FROM public.event_groups WHERE event_parent=ANY(p_ids) AND NOT event_child=ANY(p_ids) ORDER BY event_child) INTO current_children;
 IF children IS DISTINCT FROM current_children THEN RAISE serialization_failure USING MESSAGE='event links changed; retry the same command'; END IF;
 RETURN children;
END $function$

CREATE OR REPLACE FUNCTION public.lock_group_occasion_internal_v1(p_occasion bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
BEGIN
 PERFORM public.log_canonical_mutation_scope_internal_v1(p_occasion);
 PERFORM pg_catalog.pg_advisory_xact_lock(p_occasion);
 PERFORM 1 FROM public.user_group_info WHERE occasion=p_occasion ORDER BY id FOR UPDATE;
 INSERT INTO public.client_aggregate_versions(aggregate_type,scope_type,scope_id,aggregate_id,version)
 SELECT 'user_group','occasion',p_occasion,id::text,0 FROM public.user_group_info WHERE occasion=p_occasion ORDER BY id ON CONFLICT DO NOTHING;
 PERFORM 1 FROM public.client_aggregate_versions WHERE aggregate_type='user_group' AND scope_type='occasion' AND scope_id=p_occasion ORDER BY aggregate_id::bigint FOR UPDATE;
END $function$

CREATE OR REPLACE FUNCTION public.lock_pool_product_dependencies_internal_v1(p_pool bigint)
 RETURNS bigint[]
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_product_ids bigint[];
BEGIN
 SELECT coalesce(array_agg(DISTINCT pic.product ORDER BY pic.product),'{}') INTO v_product_ids
 FROM eshop.product_inventory_contexts pic JOIN public.inventory_contexts ic ON ic.id=pic.inventory_context WHERE ic.inventory_pool=p_pool;
 PERFORM public.lock_order_capacity_scope_internal(ARRAY(SELECT DISTINCT "order" FROM eshop.order_product_ticket WHERE product=ANY(v_product_ids)));
 PERFORM 1 FROM eshop.products WHERE id=ANY(v_product_ids) ORDER BY id FOR UPDATE;
 PERFORM 1 FROM public.inventory_pools WHERE id=p_pool FOR UPDATE;
 IF EXISTS(SELECT 1 FROM eshop.product_inventory_contexts pic JOIN public.inventory_contexts ic ON ic.id=pic.inventory_context
   WHERE ic.inventory_pool=p_pool AND NOT pic.product=ANY(v_product_ids)) THEN
  RAISE serialization_failure USING MESSAGE='inventory product dependencies changed; retry the same command'; END IF;
 RETURN v_product_ids;
END $function$

CREATE OR REPLACE FUNCTION public.lock_product_order_dependencies_internal_v1(p_product bigint)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE ids bigint[];
BEGIN
 SELECT ARRAY(SELECT DISTINCT "order" FROM eshop.order_product_ticket WHERE product=p_product ORDER BY "order") INTO ids;
 PERFORM public.lock_order_capacity_scope_internal(ids);
 PERFORM 1 FROM eshop.products WHERE id=p_product FOR UPDATE;
 IF EXISTS(SELECT 1 FROM eshop.order_product_ticket WHERE product=p_product AND NOT "order"=ANY(ids)) THEN
  RAISE serialization_failure USING MESSAGE='product order parents changed; retry the same command'; END IF;
END $function$

CREATE OR REPLACE FUNCTION public.lock_resource_pools_internal_v1(p_resource bigint, p_target bigint DEFAULT NULL::bigint)
 RETURNS bigint
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE origin bigint; current_pool bigint;
BEGIN
 SELECT inventory_pool INTO origin FROM public.resources WHERE id=p_resource;
 PERFORM 1 FROM public.inventory_pools WHERE id=ANY(ARRAY[origin,p_target]) ORDER BY id FOR UPDATE;
 SELECT inventory_pool INTO current_pool FROM public.resources WHERE id=p_resource FOR UPDATE;
 IF current_pool IS DISTINCT FROM origin THEN
  RAISE serialization_failure USING MESSAGE='resource pool changed; retry the same command'; END IF;
 RETURN origin;
END $function$

CREATE OR REPLACE FUNCTION public.lock_speaker_event_dependencies_internal_v1(p_speaker bigint)
 RETURNS bigint[]
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE ids bigint[]; current_ids bigint[];
BEGIN
 SELECT ARRAY(SELECT event FROM public.event_speakers WHERE speaker=p_speaker ORDER BY event) INTO ids;
 PERFORM 1 FROM public.events WHERE id=ANY(ids) ORDER BY id FOR UPDATE;
 PERFORM 1 FROM public.speakers WHERE id=p_speaker FOR UPDATE;
 SELECT ARRAY(SELECT event FROM public.event_speakers WHERE speaker=p_speaker ORDER BY event) INTO current_ids;
 IF ids IS DISTINCT FROM current_ids THEN RAISE serialization_failure USING MESSAGE='speaker event links changed; retry the same command'; END IF;
 RETURN ids;
END $function$

CREATE OR REPLACE FUNCTION public.lock_spot_assignment_scope_internal_v1(p_spots bigint[], p_resources bigint[] DEFAULT '{}'::bigint[])
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE before_spots jsonb; after_spots jsonb; before_resources jsonb; after_resources jsonb; resource_ids bigint[];
BEGIN
 SELECT coalesce(jsonb_agg(jsonb_build_array(s.id,s.occasion,s.product,s.blueprint,s.inventory_context,s.resource,s.resource_slot,s.order_product_ticket) ORDER BY s.id),'[]')
 INTO before_spots FROM eshop.spots s WHERE s.id=ANY(p_spots);
 SELECT ARRAY(SELECT DISTINCT id FROM (
  SELECT unnest(p_resources) id UNION SELECT s.resource FROM eshop.spots s WHERE s.id=ANY(p_spots)
  UNION SELECT rs.resource FROM public.resource_slots rs JOIN eshop.spots s ON s.resource_slot=rs.id WHERE s.id=ANY(p_spots)) r WHERE id IS NOT NULL)
 INTO resource_ids;
 SELECT coalesce(jsonb_agg(jsonb_build_array(r.id,r.inventory_pool) ORDER BY r.id),'[]') INTO before_resources FROM public.resources r WHERE r.id=ANY(resource_ids);
 PERFORM public.lock_order_capacity_scope_internal(ARRAY(SELECT DISTINCT opt."order" FROM eshop.order_product_ticket opt JOIN eshop.spots s ON s.order_product_ticket=opt.id WHERE s.id=ANY(p_spots)));
 PERFORM 1 FROM eshop.products WHERE id IN(SELECT product FROM eshop.spots WHERE id=ANY(p_spots)) ORDER BY id FOR UPDATE;
 PERFORM 1 FROM eshop.blueprints WHERE id IN(SELECT blueprint FROM eshop.spots WHERE id=ANY(p_spots)) ORDER BY id FOR UPDATE;
 PERFORM 1 FROM public.inventory_pools WHERE id IN(
  SELECT inventory_pool FROM public.resources WHERE id=ANY(resource_ids)
  UNION SELECT c.inventory_pool FROM public.inventory_contexts c JOIN eshop.spots s ON s.inventory_context=c.id WHERE s.id=ANY(p_spots)) ORDER BY id FOR UPDATE;
 PERFORM 1 FROM public.resources WHERE id=ANY(resource_ids) ORDER BY id FOR UPDATE;
 SELECT coalesce(jsonb_agg(jsonb_build_array(r.id,r.inventory_pool) ORDER BY r.id),'[]') INTO after_resources FROM public.resources r WHERE r.id=ANY(resource_ids);
 IF before_resources IS DISTINCT FROM after_resources THEN RAISE serialization_failure USING MESSAGE='resource parent changed; retry the same command'; END IF;
 PERFORM 1 FROM public.resource_slots WHERE resource=ANY(resource_ids) ORDER BY id FOR UPDATE;
 PERFORM 1 FROM eshop.spots WHERE id=ANY(p_spots) ORDER BY id FOR UPDATE;
 SELECT coalesce(jsonb_agg(jsonb_build_array(s.id,s.occasion,s.product,s.blueprint,s.inventory_context,s.resource,s.resource_slot,s.order_product_ticket) ORDER BY s.id),'[]')
 INTO after_spots FROM eshop.spots s WHERE s.id=ANY(p_spots);
 IF before_spots IS DISTINCT FROM after_spots THEN RAISE serialization_failure USING MESSAGE='spot parent changed; retry the same command'; END IF;
END $function$

CREATE OR REPLACE FUNCTION public.lock_ticket_order_products_internal(p_order bigint, p_input jsonb DEFAULT NULL::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE ids bigint[];
BEGIN
 SELECT coalesce(array_agg(DISTINCT id),'{}') INTO ids FROM (
  SELECT product id FROM eshop.order_product_ticket WHERE "order"=p_order
  UNION ALL SELECT (f->>'product_type')::bigint FROM jsonb_array_elements(coalesce(p_input->'ticket','[]')) t
   CROSS JOIN LATERAL jsonb_array_elements(coalesce(t->'fields','[]')) f WHERE f ? 'product_type'
  UNION ALL SELECT s.product FROM jsonb_array_elements(coalesce(p_input->'ticket','[]')) t JOIN eshop.spots s ON s.id=(t->>'spot')::bigint) selected;
 PERFORM 1 FROM eshop.products WHERE id=ANY(ids) ORDER BY id FOR UPDATE;
 PERFORM 1 FROM eshop.blueprints WHERE id IN(
  SELECT blueprint FROM public.forms WHERE id IN(SELECT form FROM eshop.orders WHERE id=p_order)
  UNION SELECT blueprint FROM eshop.spots WHERE product=ANY(ids)) ORDER BY id FOR UPDATE;
 PERFORM 1 FROM public.inventory_pools WHERE id IN(SELECT ic.inventory_pool FROM public.inventory_contexts ic
  JOIN eshop.product_inventory_contexts pic ON pic.inventory_context=ic.id WHERE pic.product=ANY(ids)) ORDER BY id FOR UPDATE;
 PERFORM 1 FROM public.inventory_contexts WHERE id IN(SELECT inventory_context FROM eshop.product_inventory_contexts WHERE product=ANY(ids)) ORDER BY id FOR UPDATE;
END $function$

CREATE OR REPLACE FUNCTION public.log_canonical_mutation_request_v1()
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
 h jsonb; method text; path text; request_id text; fields jsonb; client_info text[];
BEGIN
 method:=current_setting('request.method',true);
 IF method IS NULL OR method NOT IN ('POST','PATCH','PUT','DELETE') THEN RETURN; END IF;
 path:=current_setting('request.path',true);
 -- Never log query strings, bodies, cookies, arbitrary header values or JWTs.
 IF path IS NULL OR length(path)>180 OR path !~ '^/[a-zA-Z0-9_/.-]+$' THEN path:='unidentified'; END IF;
 BEGIN h:=nullif(current_setting('request.headers',true),'')::jsonb;
 EXCEPTION WHEN invalid_text_representation THEN h:='{}'::jsonb; END;
 client_info:=regexp_match(h->>'x-client-info','^festapp/([0-9]{1,4}\.[0-9]{1,4}\.[0-9]{1,4})[+]([0-9]{1,10})/(web|pwa|android|ios|js|service|edge|import|cron)$');
 request_id:=gen_random_uuid()::text;
 PERFORM set_config('festapp.mutation_audit_request_id',request_id,true);
 fields:=jsonb_build_object('schemaVersion',1,'event','request','requestId',request_id,
   'pid',pg_backend_pid(),'actor',auth.uid(),'role',current_user,'method',method,'path',path,
   'declaredVersion',client_info[1],'declaredBuild',client_info[2],'declaredPlatform',client_info[3]);
 RAISE LOG 'FESTAPP_MUTATION_OBSERVATION %',fields;
END $function$

CREATE OR REPLACE FUNCTION public.lookup_scanner_ticket(p_session uuid, p_token text, p_symbol text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE s public.scanner_sessions; cfg public.scanner_settings; tid bigint; result jsonb;
BEGIN
 s:=public.scanner_session_internal(p_session,p_token);
 IF NOT public.admit_scan_access_v1(s.occasion_id,true) THEN RETURN jsonb_build_object('code',429,'reason','abuse_limit_exceeded','server_time',now()); END IF;
 SELECT * INTO cfg FROM public.scanner_settings WHERE occasion_id=s.occasion_id;
 SELECT t.id INTO tid FROM eshop.tickets t WHERE t.occasion=s.occasion_id AND t.ticket_symbol=p_symbol LIMIT 1;
 IF tid IS NULL AND p_symbol ~* '^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$' THEN
  SELECT t.id INTO tid FROM public.occasion_users ou JOIN eshop.tickets t ON t.id=ou.ticket WHERE ou.occasion=s.occasion_id AND ou."user"=p_symbol::uuid AND t.occasion=s.occasion_id LIMIT 1;
 END IF;
 SELECT dto INTO result FROM public.scanner_ticket_projection_internal(s.occasion_id,cfg.config,tid) WHERE ticket_id=tid;
 IF result IS NOT NULL THEN result:=result||jsonb_build_object('can_reset_password',public.scanner_can_reset_password_internal(s.occasion_id,tid)); END IF;
 RETURN jsonb_build_object('code',CASE WHEN result IS NULL THEN 404 ELSE 200 END,'reason',CASE WHEN result IS NULL THEN 'not_found' ELSE 'found' END,
 'data',result,'settings_revision',cfg.revision,'server_time',now());
END $function$

CREATE OR REPLACE FUNCTION public.mark_news_read_client_sync_v1(p_occasion bigint, p_news_id bigint, p_command_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_user uuid:=auth.uid();
  v_revision bigint;
  v_begin jsonb;
  v_commit jsonb;
  v_read_at timestamptz;
  v_data jsonb;
  v_response jsonb;
  v_request_sha256 text;
BEGIN
  IF v_user IS NULL
     OR NOT EXISTS (SELECT 1 FROM public.occasion_users ou
       WHERE ou.occasion=p_occasion AND ou."user"=v_user)
     OR NOT EXISTS (SELECT 1 FROM public.news n
       WHERE n.id=p_news_id AND n.occasion=p_occasion)
  THEN RETURN jsonb_build_object('code',403); END IF;

  v_request_sha256:=encode(extensions.digest(convert_to(
    jsonb_build_object('occasion',p_occasion,'newsId',p_news_id)::text,'UTF8'),
    'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'news.mark_read',
    p_occasion,v_user,v_request_sha256);
  IF v_begin->>'disposition'='replay' THEN
    RETURN v_begin->'response';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(v_user::text||':'||p_occasion::text,0));

  SELECT COALESCE(source_revision,0) INTO v_revision
  FROM (SELECT 1) seed LEFT JOIN public.client_sync_private_scopes s
    ON s.component='private_news' AND s.occasion=p_occasion AND s.user_id=v_user;
  -- A delayed command never moves the high-water mark backwards.
  SELECT greatest(p_news_id,coalesce(max(news_id),0)) INTO p_news_id
    FROM public.user_news WHERE "user"=v_user AND occasion=p_occasion;
  IF (SELECT count(*)=1 AND max(news_id)=p_news_id
      FROM public.user_news
      WHERE "user"=v_user AND occasion=p_occasion) THEN
    v_data:=jsonb_build_object('revision',v_revision,'payload',jsonb_build_array(
      jsonb_build_object('newsId',p_news_id)));
    v_response:=jsonb_build_object('status','unchanged','code',200,'data',v_data,
      'mutation',jsonb_build_object('commandId',p_command_id,'receiptId',p_command_id,
        'commitId',NULL,'replayed',false,'occurredAt',clock_timestamp()),
      'sync',jsonb_build_object('replacements','[]'::jsonb));
    RETURN public.finish_client_mutation_v1(p_command_id,v_response,NULL);
  END IF;

  v_read_at:=clock_timestamp();
  v_data:=jsonb_build_object('revision',v_revision+1,'payload',jsonb_build_array(
    jsonb_build_object('newsId',p_news_id,'readAt',v_read_at)));
  DELETE FROM public.user_news WHERE "user"=v_user AND occasion=p_occasion;
  INSERT INTO public.user_news(news_id,"user",occasion) VALUES(p_news_id,v_user,p_occasion);
  v_commit:=public.record_client_sync_commit_v1(p_occasion,'mark_news_read','private',
    jsonb_build_array(jsonb_build_object('entityType','news_marker',
      'entityId',p_news_id,'operation','update','safeLabel','News read marker',
    'changedFields',jsonb_build_array('news_id'))),ARRAY['live_public'],jsonb_build_array(
      jsonb_build_object('component','private_news','userId',v_user)),jsonb_build_array(
      jsonb_build_object('component','live_public','entityId',p_news_id)),
    'user',NULL);
  SELECT source_revision INTO v_revision FROM public.client_sync_private_scopes
    WHERE component='private_news' AND occasion=p_occasion AND user_id=v_user;
  v_data:=v_data||jsonb_build_object('revision',v_revision);
  v_response:=jsonb_build_object('status','applied','code',200,'data',v_data,
    'mutation',jsonb_build_object('commandId',p_command_id,
      'receiptId',p_command_id,'commitId',v_commit->>'commitId','replayed',false,
      'occurredAt',v_commit->>'occurredAt'),
    'sync',jsonb_build_object('replacements',jsonb_build_array(jsonb_build_object(
      'component','private_news','revision',v_revision,'payload',v_data->'payload'))));
  RETURN public.finish_client_mutation_v1(
    p_command_id,v_response,(v_commit->>'commitId')::uuid);
END; $function$

CREATE OR REPLACE FUNCTION public.match_bank_transaction(p_transaction_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_transaction eshop.transactions%ROWTYPE;
  v_candidate_ids bigint[];
  v_candidate_id bigint;
  v_signal_count integer := 0;
BEGIN
  IF public.is_demo_bank_account((SELECT bank_account_id FROM eshop.transactions WHERE id=p_transaction_id)) THEN
    RETURN jsonb_build_object('outcome','skipped_demo');
  END IF;
  PERFORM public.require_service_role();

  SELECT * INTO v_transaction
  FROM eshop.transactions
  WHERE id = p_transaction_id
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'MATCH_TRANSACTION_NOT_FOUND'; END IF;

  IF v_transaction.payment_info IS NOT NULL THEN
    RETURN jsonb_build_object('verdict', 'already_paired',
      'transaction_id', p_transaction_id, 'payment_info_id', v_transaction.payment_info);
  END IF;
  IF v_transaction.amount <= 0
     OR v_transaction.bank_account_id IS NULL
     OR nullif(trim(v_transaction.currency::text), '') IS NULL THEN
    RETURN jsonb_build_object('verdict', 'ineligible', 'reason', 'invalid_direction_or_scope');
  END IF;
  IF v_transaction.ingest_source LIKE '%_email'
     AND v_transaction.transaction_id IS NULL
     AND v_transaction.command_id IS NULL THEN
    RETURN jsonb_build_object('verdict', 'ineligible', 'reason', 'unverified_identity');
  END IF;

  WITH raw_signals(kind, value) AS (
    SELECT 'vs', trim(v_transaction.vs::text)
      WHERE trim(COALESCE(v_transaction.vs::text, '')) ~ '^[0-9]{1,10}$'
    UNION ALL
    SELECT 'rf', public.normalize_creditor_reference(v_transaction.payer_reference)
      WHERE v_transaction.payer_reference IS NOT NULL
        AND public.is_valid_creditor_reference(v_transaction.payer_reference)
    UNION ALL
    SELECT 'rf', public.normalize_creditor_reference(m.captures[2])
      FROM regexp_matches(
        upper(concat_ws(E'\n', v_transaction.message_for_recipient,
          v_transaction.user_identification, v_transaction.comment)),
        '(^|[^A-Z0-9])(RF[0-9]{2}[A-Z0-9[:space:]]{1,25})([^A-Z0-9]|$)', 'g'
      ) AS m(captures)
      WHERE public.is_valid_creditor_reference(m.captures[2])
    UNION ALL
    SELECT 'vs', trim(v_transaction.message_for_recipient)
      WHERE nullif(trim(COALESCE(v_transaction.vs::text, '')), '') IS NULL
        AND trim(COALESCE(v_transaction.message_for_recipient, '')) ~ '^[0-9]{1,10}$'
    UNION ALL
    SELECT 'vs', substring(v_transaction.message_for_recipient
      FROM '(?i)(?:VS|variabilní symbol)[[:space:]]*[:=-]?[[:space:]]*([0-9]{1,10})')
      WHERE nullif(trim(COALESCE(v_transaction.vs::text, '')), '') IS NULL
        AND substring(v_transaction.message_for_recipient
          FROM '(?i)(?:VS|variabilní symbol)[[:space:]]*[:=-]?[[:space:]]*([0-9]{1,10})') IS NOT NULL
  ), signals AS (
    SELECT DISTINCT kind, value FROM raw_signals
  ), candidates AS (
    SELECT DISTINCT pi.id
    FROM signals s
    JOIN eshop.payment_info pi
      ON (s.kind = 'rf' AND pi.creditor_reference = s.value)
      OR (s.kind = 'vs' AND pi.variable_symbol = s.value::bigint)
    WHERE (pi.bank_account = v_transaction.bank_account_id
      OR public.bank_sync_accounts_match(p_transaction_id,pi.bank_account))
      AND upper(trim(pi.currency_code::text)) = upper(trim(v_transaction.currency::text))
  )
  SELECT (SELECT count(*) FROM signals), array_agg(c.id ORDER BY c.id)
  INTO v_signal_count, v_candidate_ids
  FROM candidates c;

  IF v_signal_count = 0 OR v_candidate_ids IS NULL THEN
    RETURN jsonb_build_object('verdict', 'unmatched', 'reason', 'no_unique_reference');
  END IF;
  IF cardinality(v_candidate_ids) <> 1 THEN
    RETURN jsonb_build_object('verdict', 'ambiguous', 'candidate_count', cardinality(v_candidate_ids));
  END IF;

  v_candidate_id := v_candidate_ids[1];
  PERFORM public.apply_transaction_pairing(
    p_transaction_id, v_candidate_id, 'automatic_reference', 'service',
    jsonb_build_object('signal_count', v_signal_count)
  );
  RETURN jsonb_build_object('verdict', 'paired', 'transaction_id', p_transaction_id,
    'payment_info_id', v_candidate_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.materialize_setup_area_inventory_internal(p_area jsonb, p_product bigint, p_target bigint)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE bundle jsonb; pool_id bigint; context_id bigint; capacity_value bigint; linked jsonb;
BEGIN
 PERFORM public.check_is_editor_order_on_occasion(p_target);
 IF NOT EXISTS(SELECT 1 FROM eshop.products WHERE id=p_product AND occasion=p_target) THEN RAISE check_violation USING MESSAGE='BLUEPRINT_SETUP_PRODUCT_NOT_IN_FORM'; END IF;
 capacity_value:=(p_area->>'capacity')::bigint;
 IF capacity_value IS NULL OR capacity_value<0 OR capacity_value>2147483647 THEN RAISE check_violation USING MESSAGE='BLUEPRINT_SETUP_AREA_CAPACITY_REQUIRED'; END IF;
 bundle:=public.update_inventory_pool_bundle(jsonb_build_object('pool',jsonb_build_object('occasion',p_target,'title','Standing','type','generic','sellable_capacity',capacity_value,'data','{}'::jsonb),
  'contexts',jsonb_build_array(jsonb_build_object('title','Standing','order',0,'data','{}'::jsonb))));
 pool_id:=(bundle#>>'{pool,id}')::bigint;
 SELECT id INTO context_id FROM public.inventory_contexts WHERE inventory_pool=pool_id ORDER BY id LIMIT 1;
 PERFORM public.update_resource(jsonb_build_object('inventory_pool',pool_id,'title','Standing','capacity',capacity_value,'booking_rules','{}'::jsonb));
 SELECT coalesce(jsonb_agg(jsonb_build_object('inventory_context_id',inventory_context,'quantity',quantity)),'[]') INTO linked FROM eshop.product_inventory_contexts WHERE product=p_product;
 PERFORM public.update_product_inventory_contexts_internal_v1(p_product,linked||jsonb_build_array(jsonb_build_object('inventory_context_id',context_id,'quantity',1)));
 RETURN context_id;
END $function$

CREATE OR REPLACE FUNCTION public.materialize_setup_blueprint_layout_internal(p_draft jsonb, p_product_map jsonb, p_source bigint, p_target bigint, p_unit bigint)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE doc jsonb:=p_draft->'layout'; ids jsonb:='{}'; seat jsonb; grp jsonb; area jsonb; product_id bigint; context_id bigint;
 seats jsonb:='[]'; groups jsonb:='[]'; areas jsonb:='[]'; result jsonb; context_map jsonb;
BEGIN
 PERFORM public.check_is_editor_on_occasion(p_target);
 IF p_source IS NOT NULL AND NOT public.can_copy_occasion_source(p_source) THEN RAISE insufficient_privilege USING MESSAGE='Copy source denied'; END IF;
 IF jsonb_typeof(doc)<>'object' OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_draft) k WHERE k NOT IN('layout','seatBindings','groupProducts','areaBindings')) THEN RAISE check_violation USING MESSAGE='BLUEPRINT_SETUP_INVALID_DRAFT'; END IF;
 IF p_source IS NOT NULL THEN
  WITH RECURSIVE records(value) AS (SELECT doc UNION ALL SELECT child.value FROM records CROSS JOIN LATERAL (
   SELECT item.value FROM jsonb_each(CASE WHEN jsonb_typeof(records.value)='object' THEN records.value ELSE '{}' END) item
   UNION ALL SELECT item.value FROM jsonb_array_elements(CASE WHEN jsonb_typeof(records.value)='array' THEN records.value ELSE '[]' END) item) child)
  SELECT coalesce(jsonb_object_agg(value->>'id',extensions.gen_random_uuid()),'{}') INTO ids FROM records WHERE jsonb_typeof(value)='object' AND value ? 'id';
  doc:=public.remap_blueprint_layout_ids_internal(doc,ids);
 END IF;
 PERFORM public.validate_blueprint_layout_internal(doc);
 IF p_source IS NOT NULL THEN PERFORM public.copy_blueprint_text_resources_internal(p_source,NULL,p_target,doc);END IF;
 PERFORM public.check_blueprint_text_resources_internal(doc,p_target);
 PERFORM public.copy_blueprint_canonical_bitmap_resources_internal(p_source,p_unit,p_target,doc);
 FOR seat IN SELECT value FROM jsonb_array_elements(coalesce(p_draft->'seatBindings','[]')) LOOP
  IF seat ? 'spotId' OR EXISTS(SELECT 1 FROM jsonb_object_keys(seat) k WHERE k NOT IN('nodeId','productId','title','groupNodeId','selectionUnitId','blocked','productAssignmentMode')) THEN RAISE check_violation USING MESSAGE='BLUEPRINT_SETUP_BINDING_IDENTITY'; END IF;
  product_id:=(p_product_map->>(seat->>'productId'))::bigint;
  IF seat->>'productId' IS NOT NULL AND product_id IS NULL THEN RAISE check_violation USING MESSAGE='BLUEPRINT_SETUP_PRODUCT_NOT_IN_FORM'; END IF;
  seats:=seats||jsonb_build_array(seat||jsonb_build_object('nodeId',coalesce(ids->> (seat->>'nodeId'),seat->>'nodeId'),
   'productAssignmentMode',coalesce(seat->>'productAssignmentMode','override'),'groupNodeId',coalesce(ids->>(seat->>'groupNodeId'),seat->>'groupNodeId'),'selectionUnitId',coalesce(ids->>(seat->>'selectionUnitId'),seat->>'selectionUnitId'),
   'spotId',NULL,'productId',product_id,'operation','upsert'));
 END LOOP;
 FOR grp IN SELECT value FROM jsonb_array_elements(coalesce(p_draft->'groupProducts','[]')) LOOP
  product_id:=(p_product_map->>(grp->>'productId'))::bigint;
  IF grp->>'productId' IS NOT NULL AND product_id IS NULL THEN RAISE check_violation USING MESSAGE='BLUEPRINT_SETUP_PRODUCT_NOT_IN_FORM'; END IF;
  groups:=groups||jsonb_build_array(jsonb_build_object('groupNodeId',coalesce(ids->>(grp->>'groupNodeId'),grp->>'groupNodeId'),'productId',product_id));
 END LOOP;
 context_map:=public.copy_setup_area_inventory_internal(coalesce(p_draft->'areaBindings','[]'),p_product_map,p_source,p_target);
 FOR area IN SELECT value FROM jsonb_array_elements(coalesce(p_draft->'areaBindings','[]')) LOOP
  product_id:=(p_product_map->>(area->>'productId'))::bigint;
  IF product_id IS NULL THEN RAISE check_violation USING MESSAGE='BLUEPRINT_SETUP_PRODUCT_NOT_IN_FORM'; END IF;
  IF area->>'inventoryContextId' IS NOT NULL THEN context_id:=(context_map->>(area->>'inventoryContextId'))::bigint;
  ELSE context_id:=public.materialize_setup_area_inventory_internal(area,product_id,p_target); END IF;
  areas:=areas||jsonb_build_array(jsonb_build_object('nodeId',coalesce(ids->>(area->>'nodeId'),area->>'nodeId'),'productId',product_id,'inventoryContextId',context_id,'operation','upsert'));
 END LOOP;
 result:=public.save_blueprint_layout_internal_v1(jsonb_build_object('occasion',p_target,'expected_layout_revision',0,'title','Blueprint','layout',doc,'seatChanges',seats,'groupProductChanges',groups,'areaBindingChanges',areas)||jsonb_build_object('textResourceIds',to_jsonb(public.blueprint_text_resource_ids_internal(doc,p_target))));
 RETURN (result->>'blueprint_id')::bigint;
END $function$

CREATE OR REPLACE FUNCTION public.merge_ticket_appearance_internal_v1(p_occasion bigint, p_features jsonb, p_appearance jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE result jsonb:='[]'; feature jsonb; background text; old_background text;
BEGIN
 IF p_appearance IS NULL THEN RETURN p_features; END IF;
 IF jsonb_typeof(p_appearance) IS DISTINCT FROM 'object'
  OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_appearance) k WHERE k NOT IN ('background','ticket_type'))
  OR (p_appearance ? 'ticket_type' AND p_appearance->>'ticket_type' IS NOT NULL
    AND p_appearance->>'ticket_type' NOT IN ('wide','named')) THEN
  RAISE invalid_parameter_value USING MESSAGE='invalid ticket appearance'; END IF;
 SELECT f->>'background' INTO old_background FROM jsonb_array_elements(p_features) f WHERE f->>'code'='ticket';
 background:=p_appearance->>'background';
 IF background IS NOT NULL AND background IS DISTINCT FROM old_background AND NOT EXISTS(
  SELECT 1 FROM public.images i JOIN public.occasions o ON o.id=p_occasion
  WHERE i.link=background AND (i.occasion=o.id OR i.unit=o.unit)) THEN
  RAISE insufficient_privilege USING MESSAGE='ticket background must belong to this occasion or unit'; END IF;
 FOR feature IN SELECT value FROM jsonb_array_elements(p_features) LOOP
  IF feature->>'code'='ticket' THEN feature:=feature||p_appearance; END IF;
  result:=result||jsonb_build_array(feature);
 END LOOP;
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.merge_ticket_layout_features(p_old jsonb, p_next jsonb, p_change jsonb DEFAULT NULL::jsonb, p_create boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE old_layout jsonb; next_layout jsonb; f jsonb; result jsonb:='[]'; found_ticket boolean:=false;
BEGIN
  IF jsonb_typeof(p_next) IS DISTINCT FROM 'array' OR (SELECT count(*) FROM jsonb_array_elements(p_next) e WHERE e->>'code'='ticket')>1
  THEN RAISE EXCEPTION 'Invalid features'; END IF;
  SELECT value->'layout' INTO old_layout FROM jsonb_array_elements(COALESCE(p_old,'[]')) WHERE value->>'code'='ticket';
  next_layout:=old_layout;
  IF p_change IS NOT NULL THEN
    IF jsonb_typeof(p_change)<>'object' OR NOT (p_change ? 'expected' AND p_change ? 'next')
      OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_change) k WHERE k NOT IN ('expected','next','appearance')) THEN RAISE EXCEPTION 'Invalid ticket layout change'; END IF;
    IF COALESCE(old_layout,'null') IS DISTINCT FROM p_change->'expected' THEN
      RAISE EXCEPTION 'ticket_layout_conflict' USING ERRCODE='40001';
    END IF;
    -- A client must not downgrade a schema it does not understand.
    IF old_layout IS NOT NULL AND old_layout->'schemaVersion' IS DISTINCT FROM '3'::jsonb THEN RAISE EXCEPTION 'Unsupported ticket layout'; END IF;
    next_layout:=p_change->'next';
    IF next_layout IS NULL OR next_layout='null'::jsonb THEN RAISE EXCEPTION 'Ticket layout reset rejected'; END IF;
    PERFORM public.validate_ticket_layout(next_layout);
  END IF;
  FOR f IN SELECT * FROM jsonb_array_elements(p_next) LOOP
    IF f->>'code'='ticket' THEN
      found_ticket:=true;
      IF p_create AND p_change IS NULL THEN next_layout:=f->'layout'; IF next_layout IS NOT NULL THEN PERFORM public.validate_ticket_layout(next_layout); END IF; END IF;
      f:=f-'layout'; IF next_layout IS NOT NULL THEN f:=f||jsonb_build_object('layout',next_layout); END IF;
    END IF;
    result:=result||jsonb_build_array(f);
  END LOOP;
  IF NOT found_ticket AND next_layout IS NOT NULL THEN result:=result||jsonb_build_array(jsonb_build_object('code','ticket','is_enabled',false,'layout',next_layout)); END IF;
  RETURN result;
END;
$function$

CREATE OR REPLACE FUNCTION public.migrate_blueprint_layout_reviewed_internal(p_source text, p_source_sha text, p_blueprint jsonb, p_command_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE b eshop.blueprints; source jsonb; current_source jsonb; c jsonb; s eshop.spots; old_object jsonb; old_group text;
 effective_changes jsonb:='[]'; expected_node uuid; expected_group uuid; request_hash text; started jsonb; result jsonb; before_spots jsonb; after_spots jsonb; users uuid[];
BEGIN
 IF p_source_sha !~ '^[0-9a-f]{64}$' OR encode(extensions.digest(convert_to(p_source,'UTF8'),'sha256'),'hex') IS DISTINCT FROM p_source_sha THEN
  RAISE check_violation USING MESSAGE='BLUEPRINT_MIGRATION_SOURCE_HASH_MISMATCH'; END IF;
 source:=p_source::jsonb;
 SELECT * INTO b FROM eshop.blueprints WHERE id=(p_blueprint->>'id')::bigint;
 IF b.id IS NULL OR (source->>'id')::bigint IS DISTINCT FROM b.id OR (source->>'occasion')::bigint IS DISTINCT FROM b.occasion
  OR (p_blueprint->>'occasion')::bigint IS DISTINCT FROM b.occasion
  OR p_blueprint->>'title' IS DISTINCT FROM coalesce(b.title,'') THEN RAISE check_violation USING MESSAGE='BLUEPRINT_MIGRATION_SCOPE_MISMATCH'; END IF;
 IF auth.uid() IS NULL OR NOT (coalesce(public.get_is_editor_on_occasion(b.occasion),false) OR coalesce(public.get_is_manager_on_occasion(b.occasion),false) OR
  (public.is_demo_occasion(b.occasion) AND EXISTS(SELECT 1 FROM public.occasion_users ou WHERE ou.occasion=b.occasion AND ou."user"=auth.uid() AND (ou.is_editor OR ou.is_manager)))) THEN
  RAISE insufficient_privilege USING MESSAGE='blueprint migration reviewer required'; END IF;
 request_hash:=encode(extensions.digest(convert_to(jsonb_build_object('sourceSha',p_source_sha,'request',p_blueprint)::text,'UTF8'),'sha256'),'hex');
 started:=public.begin_client_mutation_reviewed_impl_internal(p_command_id,'inventory.blueprint.migrate',b.occasion,auth.uid(),request_hash,true);
 IF started->>'disposition'='replay' THEN RETURN started->'response'; END IF;
 PERFORM public.lock_blueprint_scope_internal(ARRAY[b.occasion]);
 SELECT * INTO b FROM eshop.blueprints WHERE id=b.id FOR UPDATE;
 IF b.layout IS NOT NULL OR b.layout_revision<>0 OR (p_blueprint->>'expected_layout_revision')::bigint IS DISTINCT FROM 0
  OR EXISTS(SELECT 1 FROM eshop.blueprint_seat_bindings WHERE blueprint=b.id) THEN
  RAISE check_violation USING MESSAGE='BLUEPRINT_MIGRATION_INITIAL_LAYOUT_REQUIRED'; END IF;
 -- Match canonical writer lock order and freeze only stable commercial facts.
 PERFORM 1 FROM eshop.products WHERE occasion=b.occasion ORDER BY id FOR UPDATE;
 PERFORM 1 FROM public.inventory_pools WHERE id IN(SELECT ic.inventory_pool FROM public.inventory_contexts ic
  JOIN eshop.product_inventory_contexts pic ON pic.inventory_context=ic.id JOIN eshop.products p ON p.id=pic.product WHERE p.occasion=b.occasion) ORDER BY id FOR UPDATE;
 PERFORM 1 FROM public.inventory_contexts WHERE id IN(SELECT pic.inventory_context FROM eshop.product_inventory_contexts pic JOIN eshop.products p ON p.id=pic.product WHERE p.occasion=b.occasion) ORDER BY id FOR UPDATE;
 PERFORM 1 FROM eshop.spots WHERE blueprint=b.id ORDER BY id FOR UPDATE;
 current_source:=public.blueprint_legacy_migration_source_internal(b.id);
 IF current_source IS DISTINCT FROM source THEN RAISE check_violation USING MESSAGE='BLUEPRINT_MIGRATION_REVIEW_STALE'; END IF;
 IF jsonb_array_length(coalesce(p_blueprint->'areaBindingChanges','[]'))<>0 OR
  jsonb_array_length(coalesce(p_blueprint#>'{layout,selectionUnits}','[]'))<>0 OR
  jsonb_array_length(coalesce(p_blueprint->'seatChanges','[]'))<>(SELECT count(*) FROM eshop.spots WHERE blueprint=b.id) THEN
  RAISE check_violation USING MESSAGE='BLUEPRINT_MIGRATION_BINDING_SET_MISMATCH'; END IF;
 SELECT coalesce(jsonb_agg(to_jsonb(spot) ORDER BY spot.id),'[]') INTO before_spots FROM eshop.spots spot WHERE spot.blueprint=b.id;
 FOR c IN SELECT value FROM jsonb_array_elements(coalesce(p_blueprint->'seatChanges','[]')) LOOP
  SELECT * INTO s FROM eshop.spots WHERE id=(c->>'spotId')::bigint AND blueprint=b.id AND occasion=b.occasion;
  IF s.id IS NULL OR c->>'operation' IS DISTINCT FROM 'upsert' OR c->>'selectionUnitId' IS NOT NULL OR
   (c->>'productId')::bigint IS DISTINCT FROM s.product OR c->>'title' IS DISTINCT FROM coalesce(s.title,'') OR
   (c->>'blocked')::boolean IS DISTINCT FROM coalesce(s.state='black',false) THEN
   RAISE check_violation USING MESSAGE='BLUEPRINT_MIGRATION_SPOT_FACTS_CHANGED'; END IF;
  expected_node:=extensions.uuid_generate_v5('6ba7b811-9dad-11d1-80b4-00c04fd430c8',format('festapp:occasion:%s:blueprint:%s:spot:%s',b.occasion,b.id,s.id));
  SELECT obj INTO old_object FROM jsonb_array_elements(coalesce(b.objects,'[]')) obj WHERE obj->>'type'='spot' AND (obj->>'id')::bigint=s.id;
  IF old_object IS NULL THEN RAISE check_violation USING MESSAGE='BLUEPRINT_MIGRATION_LEGACY_SPOT_MISSING'; END IF;
  old_group:=old_object->>'group';expected_group:=NULL;
  IF old_group IS NOT NULL AND EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(b.groups,'[]')) grp WHERE grp->>'id'=old_group) THEN
   expected_group:=extensions.uuid_generate_v5('6ba7b811-9dad-11d1-80b4-00c04fd430c8',format('festapp:occasion:%s:blueprint:%s:group:%s',b.occasion,b.id,old_group)); END IF;
  IF (c->>'nodeId')::uuid IS DISTINCT FROM expected_node OR (c->>'groupNodeId')::uuid IS DISTINCT FROM expected_group THEN
   RAISE check_violation USING MESSAGE='BLUEPRINT_MIGRATION_GROUP_MAPPING_CHANGED'; END IF;
  effective_changes:=effective_changes||jsonb_build_array(c||jsonb_build_object('title',s.title));
  INSERT INTO eshop.blueprint_seat_bindings(blueprint,node_id,spot,selection_unit,group_node,blocked)
   VALUES(b.id,expected_node,s.id,NULL,expected_group,(c->>'blocked')::boolean);
 END LOOP;
 -- Seeded metadata permits the unchanged protected seats to pass the same
 -- canonical aggregate owner used by every runtime save.
 result:=public.save_blueprint_layout_impl_internal((p_blueprint-'title')||jsonb_build_object('seatChanges',effective_changes),true);
 SELECT coalesce(jsonb_agg(to_jsonb(spot) ORDER BY spot.id),'[]') INTO after_spots FROM eshop.spots spot WHERE spot.blueprint=b.id;
 IF before_spots IS DISTINCT FROM after_spots THEN RAISE check_violation USING MESSAGE='BLUEPRINT_MIGRATION_LIVE_FACTS_CHANGED'; END IF;
 SELECT coalesce(array_agg(DISTINCT ou."user"),'{}') INTO users FROM public.occasion_users ou WHERE ou.occasion=b.occasion;
 result:=result||jsonb_build_object('migrationSourceSha256',p_source_sha);
 RETURN public.complete_private_inventory_mutation_v1(p_command_id,b.occasion,'inventory.blueprint.migrate',
  jsonb_build_array(jsonb_build_object('entityType','blueprint','entityId',b.id,'operation','update','safeLabel','Reviewed blueprint layout migration','changedFields',jsonb_build_array('layout','bindings'))),users,result);
END $function$

CREATE OR REPLACE FUNCTION public.move_place_client_sync_v1(p_occasion bigint, p_place_id bigint, p_command_id uuid, p_expected_version bigint, p_lat double precision, p_lng double precision)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_actor uuid:=auth.uid(); v_version bigint; v_begin jsonb; v_hash text;
  v_place public.places%ROWTYPE; v_commit jsonb; v_public jsonb; v_response jsonb;
  v_is_publishable boolean; v_affects_public boolean; v_group bigint; v_impacts jsonb:='[]'; v_replacements jsonb:='[]';
BEGIN
 PERFORM public.assert_canonical_mutation_write_release_internal_v1(p_occasion);
  SELECT p.* INTO v_place FROM public.places p
    WHERE p.id=p_place_id AND p.occasion=p_occasion;
  IF NOT FOUND THEN RAISE invalid_parameter_value USING MESSAGE='place not found'; END IF;
  IF v_actor IS NULL OR p_lat IS NULL OR p_lng IS NULL OR p_lat NOT BETWEEN -90 AND 90 OR p_lng NOT BETWEEN -180 AND 180
    OR NOT (public.get_is_editor_on_occasion(p_occasion) OR EXISTS (
      SELECT 1 FROM public.user_groups ug JOIN public.user_group_info g
        ON g.id=ug."group" WHERE ug."user"=v_actor AND ug.is_admin
        AND g.occasion=p_occasion AND g.place=p_place_id
        AND v_place.type='group' AND v_place.is_hidden)) THEN
    RAISE insufficient_privilege USING MESSAGE='place move permission required';
  END IF;
  SELECT NOT o.is_hidden INTO v_is_publishable FROM public.occasions o WHERE o.id=p_occasion;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object('occasion',p_occasion,
    'placeId',p_place_id,'expectedVersion',p_expected_version,'lat',p_lat,'lng',p_lng)::text,
    'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'map.place.move',p_occasion,
    v_actor,v_hash);
  PERFORM public.lock_group_occasion_internal_v1(p_occasion);
  SELECT p.* INTO v_place FROM public.places p WHERE p.id=p_place_id AND p.occasion=p_occasion FOR UPDATE;
  IF NOT FOUND THEN RAISE invalid_parameter_value USING MESSAGE='place not found'; END IF;
  IF v_actor IS NULL OR p_lat IS NULL OR p_lng IS NULL OR p_lat NOT BETWEEN -90 AND 90 OR p_lng NOT BETWEEN -180 AND 180
    OR NOT (public.get_is_editor_on_occasion(p_occasion) OR EXISTS (
      SELECT 1 FROM public.user_groups ug JOIN public.user_group_info g
        ON g.id=ug."group" WHERE ug."user"=v_actor AND ug.is_admin
        AND g.occasion=p_occasion AND g.place=p_place_id
        AND v_place.type='group' AND v_place.is_hidden)) THEN
    RAISE insufficient_privilege USING MESSAGE='place move permission required';
  END IF;
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  IF v_place.type='group' AND v_place.is_hidden THEN
    SELECT id INTO v_group FROM public.user_group_info WHERE occasion=p_occasion AND place=p_place_id ORDER BY id LIMIT 1;
    PERFORM public.assert_group_place_owner_internal_v1(p_occasion,v_group,p_place_id,false);
  END IF;
  INSERT INTO public.client_aggregate_versions
    (aggregate_type,scope_type,scope_id,aggregate_id,version)
  VALUES ('place','occasion',p_occasion,p_place_id::text,0) ON CONFLICT DO NOTHING;
  SELECT version INTO v_version FROM public.client_aggregate_versions
    WHERE aggregate_type='place' AND scope_type='occasion' AND scope_id=p_occasion
      AND aggregate_id=p_place_id::text FOR UPDATE;
  IF p_expected_version IS DISTINCT FROM v_version THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,
      'conflict',409,jsonb_build_object('version',v_version,'place',
        to_jsonb(v_place)||jsonb_build_object('aggregate_version',v_version)));
  END IF;
  IF v_place.coordinates=jsonb_build_object('latLng',jsonb_build_object('lat',p_lat,'lng',p_lng)) THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,
      'unchanged',200,jsonb_build_object('version',v_version,'place',
        to_jsonb(v_place)||jsonb_build_object('aggregate_version',v_version)));
  END IF;
  UPDATE public.places SET coordinates=jsonb_build_object('latLng',
    jsonb_build_object('lat',p_lat,'lng',p_lng)),updated_at=clock_timestamp()
    WHERE id=p_place_id RETURNING * INTO v_place;
  UPDATE public.client_aggregate_versions SET version=version+1,
    updated_at=clock_timestamp() WHERE aggregate_type='place'
    AND scope_type='occasion' AND scope_id=p_occasion AND aggregate_id=p_place_id::text
    RETURNING version INTO v_version;
  IF v_group IS NOT NULL THEN
    UPDATE public.client_aggregate_versions SET version=version+1,updated_at=clock_timestamp()
      WHERE aggregate_type='user_group' AND scope_type='occasion' AND scope_id=p_occasion AND aggregate_id=v_group::text;
  END IF;
  v_impacts:=public.group_profile_impacts_internal_v1(p_occasion,ARRAY(SELECT DISTINCT ug."user" FROM public.user_groups ug JOIN public.user_group_info g ON g.id=ug."group" WHERE g.occasion=p_occasion AND g.place=p_place_id));
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(v_impacts) x WHERE x->>'userId'=v_actor::text) THEN
    v_replacements:=jsonb_build_array(jsonb_build_object('component','private_profile','userId',v_actor,'payload',public.get_private_profile_payload_v1(p_occasion,v_actor)));
  END IF;
  v_affects_public:=NOT v_place.is_hidden;
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'map.place.move','map',
    jsonb_build_array(jsonb_build_object('entityType','place','entityId',p_place_id,
      'operation','update','safeLabel',left(v_place.title,240),
      'changedFields',jsonb_build_array('coordinates'))),
    CASE WHEN v_is_publishable AND v_affects_public THEN ARRAY['map_catalog']
      ELSE '{}'::text[] END,v_impacts,'[]',
    jsonb_build_object('version',v_version,'place',to_jsonb(v_place)||
      jsonb_build_object('aggregate_version',v_version)),'{}','[]','user',NULL,v_replacements);
END; $function$

CREATE OR REPLACE FUNCTION public.move_product_price_wave(p_wave_id bigint, p_expected_revision bigint, p_change_time timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_wave eshop.product_price_waves%ROWTYPE;
BEGIN
  SELECT * INTO STRICT v_wave FROM eshop.product_price_waves WHERE id=p_wave_id FOR UPDATE;
  PERFORM public.check_product_wave_editor(v_wave.occasion);
  IF v_wave.revision IS DISTINCT FROM p_expected_revision THEN RAISE serialization_failure USING MESSAGE='PRICE_CHANGE_CONFLICT'; END IF;
  IF p_change_time IS NULL OR NOT isfinite(p_change_time) OR p_change_time<=clock_timestamp() THEN
    RAISE invalid_parameter_value USING MESSAGE='FUTURE_TIME_REQUIRED'; END IF;
  IF EXISTS(SELECT 1 FROM eshop.planned_changes WHERE wave_id=p_wave_id AND applied) THEN
    RAISE invalid_parameter_value USING MESSAGE='WAVE_ALREADY_APPLIED'; END IF;
  PERFORM 1 FROM eshop.products WHERE id IN(SELECT subject_id FROM eshop.planned_changes
    WHERE wave_id=p_wave_id AND NOT applied) ORDER BY id FOR UPDATE;
  PERFORM 1 FROM eshop.planned_changes WHERE wave_id=p_wave_id AND NOT applied ORDER BY subject_id,id FOR UPDATE;
  IF EXISTS(SELECT 1 FROM eshop.planned_changes target JOIN eshop.planned_changes other
    ON other.subject_id=target.subject_id AND other.change_type=target.change_type
    WHERE target.wave_id=p_wave_id AND NOT target.applied AND NOT other.applied
      AND other.wave_id IS DISTINCT FROM p_wave_id AND other.change_time=p_change_time) THEN
    RAISE serialization_failure USING MESSAGE='PRICE_CHANGE_CONFLICT'; END IF;
  IF EXISTS(SELECT 1 FROM eshop.planned_changes WHERE wave_id=p_wave_id AND applied) THEN
    RAISE invalid_parameter_value USING MESSAGE='WAVE_ALREADY_APPLIED'; END IF;
  IF p_change_time<=clock_timestamp() THEN RAISE invalid_parameter_value USING MESSAGE='FUTURE_TIME_REQUIRED'; END IF;
  UPDATE eshop.product_price_waves SET change_time=p_change_time,revision=revision+1 WHERE id=p_wave_id RETURNING * INTO v_wave;
  UPDATE eshop.planned_changes SET change_time=p_change_time,revision=revision+1,failed_at=NULL,failure_code=NULL
    WHERE wave_id=p_wave_id AND NOT applied;
  RETURN to_jsonb(v_wave);
END; $function$

CREATE OR REPLACE FUNCTION public.mutate_map_entity_internal_v1(p_kind text, p_action text, p_occasion bigint, p_command_id uuid, p_expected_version bigint, p_entity_id bigint, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_actor uuid:=auth.uid(); v_id bigint:=p_entity_id; v_version bigint;
  v_begin jsonb; v_hash text; v_current jsonb; v_requested jsonb;
  v_entity jsonb; v_commit jsonb; v_public jsonb; v_response jsonb;
  v_is_publishable boolean; v_old_hidden boolean; v_new_hidden boolean;
  v_impacts jsonb:='[]'; v_replacements jsonb:='[]';
  v_affects_public boolean:=false; v_label text; v_entity_key text;
BEGIN
  IF p_kind NOT IN ('place','place_type','path') OR p_action NOT IN ('save','delete')
    OR v_actor IS NULL OR NOT public.get_is_editor_on_occasion(p_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion editor required';
  END IF;
  SELECT NOT o.is_hidden INTO v_is_publishable FROM public.occasions o
    WHERE o.id=p_occasion;
  IF v_is_publishable IS NULL THEN
    RAISE invalid_parameter_value USING MESSAGE='occasion not found';
  END IF;

  IF p_action='save' THEN
    IF p_payload IS NULL OR jsonb_typeof(p_payload)<>'object'
      OR octet_length(p_payload::text)>262144 THEN
      RAISE invalid_parameter_value USING MESSAGE='invalid map aggregate';
    END IF;
    IF p_kind='place' THEN
      IF EXISTS (SELECT 1 FROM jsonb_object_keys(p_payload) key WHERE key NOT IN
          ('id','title','description','type','coordinates','isHidden','order','icon'))
        OR NOT (p_payload ?& ARRAY['title','coordinates','isHidden'])
        OR length(p_payload->>'title') NOT BETWEEN 1 AND 500
        OR jsonb_typeof(p_payload->'coordinates')<>'object'
        OR jsonb_typeof(p_payload#>'{coordinates,latLng}')<>'object'
        OR jsonb_typeof(p_payload#>'{coordinates,latLng,lat}')<>'number'
        OR jsonb_typeof(p_payload#>'{coordinates,latLng,lng}')<>'number'
        OR (p_payload#>>'{coordinates,latLng,lat}')::double precision NOT BETWEEN -90 AND 90
        OR (p_payload#>>'{coordinates,latLng,lng}')::double precision NOT BETWEEN -180 AND 180 THEN
        RAISE invalid_parameter_value USING MESSAGE='invalid place aggregate';
      END IF;
      v_id:=(p_payload->>'id')::bigint;
      v_requested:=jsonb_build_object('id',v_id,'title',p_payload->>'title',
        'description',p_payload->>'description','type',p_payload->>'type',
        'coordinates',p_payload->'coordinates','isHidden',(p_payload->>'isHidden')::boolean,
        'order',(p_payload->>'order')::bigint,'icon',(p_payload->>'icon')::bigint);
      v_entity_key:='place';
    ELSIF p_kind='place_type' THEN
      IF EXISTS (SELECT 1 FROM jsonb_object_keys(p_payload) key WHERE key NOT IN
          ('id','code','title','icon','order','isHidden','isDefault'))
        OR NOT (p_payload ?& ARRAY['code','title','isHidden','isDefault'])
        OR length(p_payload->>'code') NOT BETWEEN 1 AND 100
        OR (p_payload->>'code') !~ '^[A-Za-z0-9_-]+$'
        OR length(p_payload->>'title') NOT BETWEEN 1 AND 500 THEN
        RAISE invalid_parameter_value USING MESSAGE='invalid place type aggregate';
      END IF;
      v_id:=(p_payload->>'id')::bigint;
      v_requested:=jsonb_build_object('id',v_id,'code',p_payload->>'code',
        'title',p_payload->>'title','icon',(p_payload->>'icon')::bigint,
        'order',(p_payload->>'order')::bigint,
        'isHidden',(p_payload->>'isHidden')::boolean,
        'isDefault',(p_payload->>'isDefault')::boolean);
      v_entity_key:='placeType';
    ELSE
      IF EXISTS (SELECT 1 FROM jsonb_object_keys(p_payload) key WHERE key NOT IN
          ('id','title','pathData','data','icon','isHidden','order'))
        OR NOT (p_payload ?& ARRAY['title','isHidden'])
        OR length(p_payload->>'title') NOT BETWEEN 1 AND 500
        OR (p_payload->'pathData' IS NOT NULL
          AND jsonb_typeof(p_payload->'pathData')<>'array')
        OR COALESCE(jsonb_array_length(p_payload->'pathData'),0)>500 THEN
        RAISE invalid_parameter_value USING MESSAGE='invalid path aggregate';
      END IF;
      v_id:=(p_payload->>'id')::bigint;
      v_requested:=jsonb_build_object('id',v_id,'title',p_payload->>'title',
        'pathData',p_payload->'pathData','data',p_payload->'data',
        'icon',(p_payload->>'icon')::bigint,
        'isHidden',(p_payload->>'isHidden')::boolean,
        'order',(p_payload->>'order')::bigint);
      v_entity_key:='path';
    END IF;
  ELSE
    IF v_id IS NULL THEN RAISE invalid_parameter_value USING MESSAGE='entity id required'; END IF;
    v_entity_key:=CASE p_kind WHEN 'place_type' THEN 'placeType' ELSE p_kind END;
  END IF;

  IF (p_payload->>'icon') IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.icons i JOIN public.occasions o
      ON o.id=p_occasion AND i.organization=o.organization
    WHERE i.id=(p_payload->>'icon')::bigint AND (i.unit=o.unit OR i.unit IS NULL)
  ) THEN RAISE invalid_parameter_value USING MESSAGE='cross-scope map icon'; END IF;
  IF p_kind='path' AND p_action='save' AND EXISTS (
    SELECT 1 FROM jsonb_array_elements(COALESCE(p_payload->'pathData','[]')) segment,
      LATERAL jsonb_array_elements(segment) node
    WHERE (jsonb_typeof(node)='number' AND NOT EXISTS (
      SELECT 1 FROM public.places p WHERE p.id=(node#>>'{}')::bigint
        AND p.occasion=p_occasion))
      OR (jsonb_typeof(node)='object' AND NOT (
        jsonb_typeof(node->'lat')='number' AND jsonb_typeof(node->'lng')='number'))
      OR jsonb_typeof(node) NOT IN ('number','object')
  ) THEN RAISE invalid_parameter_value USING MESSAGE='invalid or cross-scope path node'; END IF;

  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'kind',p_kind,'action',p_action,'occasion',p_occasion,'entityId',v_id,
    'expectedVersion',p_expected_version,'payload',p_payload)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,
    'map.'||p_kind||'.'||p_action,p_occasion,v_actor,v_hash);
  IF p_kind='place' THEN PERFORM public.lock_group_occasion_internal_v1(p_occasion); END IF;
  IF NOT public.get_is_editor_on_occasion(p_occasion) THEN RAISE insufficient_privilege USING MESSAGE='occasion editor required'; END IF;
  IF p_kind='place' AND p_action='save' AND (
    ((p_payload->>'type')='group' AND (p_payload->>'isHidden')::boolean)
    OR EXISTS(SELECT 1 FROM public.places p WHERE p.id=v_id AND p.occasion=p_occasion AND p.type='group' AND p.is_hidden)) THEN
    RAISE invalid_parameter_value USING MESSAGE='private group place is owned by group save'; END IF;
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;

  IF v_id IS NOT NULL THEN
    IF p_kind='place' THEN
      PERFORM 1 FROM public.places p WHERE p.id=v_id AND p.occasion=p_occasion FOR UPDATE;
      IF FOUND THEN SELECT jsonb_build_object('id',p.id,'title',p.title,
        'description',p.description,'type',p.type,'coordinates',p.coordinates,
        'isHidden',p.is_hidden,'order',p."order",'icon',p.icon),p.is_hidden,p.title
        INTO v_current,v_old_hidden,v_label FROM public.places p WHERE p.id=v_id; END IF;
    ELSIF p_kind='place_type' THEN
      PERFORM 1 FROM public.place_types t WHERE t.id=v_id AND t.occasion=p_occasion FOR UPDATE;
      IF FOUND THEN SELECT jsonb_build_object('id',t.id,'code',t.code,'title',t.title,
        'icon',t.icon,'order',t."order",'isHidden',t.is_hidden,'isDefault',t.is_default),
        t.is_hidden,t.title INTO v_current,v_old_hidden,v_label
        FROM public.place_types t WHERE t.id=v_id; END IF;
    ELSE
      PERFORM 1 FROM public.path_groups pg WHERE pg.id=v_id AND pg.occasion=p_occasion FOR UPDATE;
      IF FOUND THEN SELECT jsonb_build_object('id',pg.id,'title',pg.title,
        'pathData',pg.path_data,'data',pg.data,'icon',pg.icon,
        'isHidden',pg.is_hidden,'order',pg."order"),pg.is_hidden,pg.title
        INTO v_current,v_old_hidden,v_label FROM public.path_groups pg WHERE pg.id=v_id; END IF;
    END IF;
    IF v_current IS NULL THEN
      RETURN public.complete_client_mutation_outcome_v1(p_command_id,
        CASE WHEN p_action='delete' THEN 'unchanged' ELSE 'rejected' END,
        CASE WHEN p_action='delete' THEN 200 ELSE 404 END,
        jsonb_build_object('version',0,v_entity_key,NULL));
    END IF;
    INSERT INTO public.client_aggregate_versions
      (aggregate_type,scope_type,scope_id,aggregate_id,version)
    VALUES (p_kind,'occasion',p_occasion,v_id::text,0) ON CONFLICT DO NOTHING;
    SELECT version INTO v_version FROM public.client_aggregate_versions
      WHERE aggregate_type=p_kind AND scope_type='occasion' AND scope_id=p_occasion
        AND aggregate_id=v_id::text FOR UPDATE;
    IF p_expected_version IS DISTINCT FROM v_version THEN
      IF p_kind='place' THEN SELECT to_jsonb(p)||jsonb_build_object('aggregate_version',v_version)
        INTO v_entity FROM public.places p WHERE p.id=v_id;
      ELSIF p_kind='place_type' THEN SELECT to_jsonb(t)||jsonb_build_object('aggregate_version',v_version)
        INTO v_entity FROM public.place_types t WHERE t.id=v_id;
      ELSE SELECT to_jsonb(pg)||jsonb_build_object('aggregate_version',v_version)
        INTO v_entity FROM public.path_groups pg WHERE pg.id=v_id; END IF;
      RETURN public.complete_client_mutation_outcome_v1(p_command_id,
        'conflict',409,jsonb_build_object('version',v_version,
          v_entity_key,v_entity));
    END IF;
  ELSIF p_expected_version IS NOT NULL THEN
    RAISE invalid_parameter_value USING MESSAGE='new map aggregate must not have expected version';
  END IF;

  IF p_action='save' AND v_current IS NOT DISTINCT FROM v_requested THEN
    IF p_kind='place' THEN SELECT to_jsonb(p)||jsonb_build_object('aggregate_version',v_version)
      INTO v_entity FROM public.places p WHERE p.id=v_id;
    ELSIF p_kind='place_type' THEN SELECT to_jsonb(t)||jsonb_build_object('aggregate_version',v_version)
      INTO v_entity FROM public.place_types t WHERE t.id=v_id;
    ELSE SELECT to_jsonb(pg)||jsonb_build_object('aggregate_version',v_version)
      INTO v_entity FROM public.path_groups pg WHERE pg.id=v_id; END IF;
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,
      'unchanged',200,jsonb_build_object('version',v_version,
        v_entity_key,v_entity));
  END IF;

  IF p_action='delete' THEN
    IF p_kind='place' AND (EXISTS (SELECT 1 FROM public.events e WHERE e.place=v_id)
      OR EXISTS(SELECT 1 FROM public.activity_assignment_places WHERE place_id=v_id)
      OR EXISTS(SELECT 1 FROM public.activity_places WHERE place_id=v_id)
      OR EXISTS (SELECT 1 FROM public.user_group_info g WHERE g.place=v_id)
      OR EXISTS (SELECT 1 FROM public.path_groups pg,
          LATERAL jsonb_array_elements(COALESCE(pg.path_data,'[]')) segment,
          LATERAL jsonb_array_elements(segment) node
        WHERE pg.occasion=p_occasion AND jsonb_typeof(node)='number'
          AND (node#>>'{}')::bigint=v_id)) THEN
      RETURN public.complete_client_mutation_outcome_v1(p_command_id,
        'rejected',409,jsonb_build_object('version',v_version,
          v_entity_key,NULL));
    END IF;
    IF p_kind='place_type' AND EXISTS (SELECT 1 FROM public.places p
      WHERE p.occasion=p_occasion AND p.type=v_current->>'code') THEN
      RETURN public.complete_client_mutation_outcome_v1(p_command_id,
        'rejected',409,jsonb_build_object('version',v_version,
          v_entity_key,NULL));
    END IF;
    IF p_kind='place' THEN DELETE FROM public.places WHERE id=v_id;
    ELSIF p_kind='place_type' THEN DELETE FROM public.place_types WHERE id=v_id;
    ELSE DELETE FROM public.path_groups WHERE id=v_id; END IF;
    DELETE FROM public.client_aggregate_versions WHERE aggregate_type=p_kind
      AND scope_type='occasion' AND scope_id=p_occasion AND aggregate_id=v_id::text;
    v_entity:=NULL;
    v_affects_public:=NOT v_old_hidden;
  ELSE
    v_new_hidden:=(p_payload->>'isHidden')::boolean;
    v_affects_public:=NOT COALESCE(v_old_hidden,true) OR NOT v_new_hidden;
    IF p_kind='place' THEN
      IF v_id IS NULL THEN INSERT INTO public.places
        (title,description,type,coordinates,is_hidden,occasion,"order",icon)
        VALUES (p_payload->>'title',p_payload->>'description',p_payload->>'type',
          p_payload->'coordinates',v_new_hidden,p_occasion,(p_payload->>'order')::bigint,
          (p_payload->>'icon')::bigint) RETURNING id INTO v_id;
      ELSE UPDATE public.places SET title=p_payload->>'title',description=p_payload->>'description',
        type=p_payload->>'type',coordinates=p_payload->'coordinates',is_hidden=v_new_hidden,
        "order"=(p_payload->>'order')::bigint,icon=(p_payload->>'icon')::bigint,
        updated_at=clock_timestamp() WHERE id=v_id; END IF;
    ELSIF p_kind='place_type' THEN
      IF v_id IS NULL THEN INSERT INTO public.place_types
        (occasion,code,title,icon,"order",is_hidden,is_default)
        VALUES (p_occasion,p_payload->>'code',p_payload->>'title',(p_payload->>'icon')::bigint,
          (p_payload->>'order')::bigint,v_new_hidden,(p_payload->>'isDefault')::boolean)
        RETURNING id INTO v_id;
      ELSE UPDATE public.place_types SET code=p_payload->>'code',title=p_payload->>'title',
        icon=(p_payload->>'icon')::bigint,"order"=(p_payload->>'order')::bigint,
        is_hidden=v_new_hidden,is_default=(p_payload->>'isDefault')::boolean,
        updated_at=clock_timestamp() WHERE id=v_id; END IF;
    ELSE
      IF v_id IS NULL THEN INSERT INTO public.path_groups
        (title,path_data,data,icon,is_hidden,occasion,"order")
        VALUES (p_payload->>'title',p_payload->'pathData',p_payload->'data',
          (p_payload->>'icon')::bigint,v_new_hidden,p_occasion,
          (p_payload->>'order')::bigint) RETURNING id INTO v_id;
      ELSE UPDATE public.path_groups SET title=p_payload->>'title',
        path_data=p_payload->'pathData',data=p_payload->'data',
        icon=(p_payload->>'icon')::bigint,is_hidden=v_new_hidden,
        "order"=(p_payload->>'order')::bigint WHERE id=v_id; END IF;
    END IF;
    IF v_version IS NULL THEN v_version:=1;
      INSERT INTO public.client_aggregate_versions
        (aggregate_type,scope_type,scope_id,aggregate_id,version)
      VALUES (p_kind,'occasion',p_occasion,v_id::text,v_version);
    ELSE UPDATE public.client_aggregate_versions SET version=version+1,
      updated_at=clock_timestamp() WHERE aggregate_type=p_kind
      AND scope_type='occasion' AND scope_id=p_occasion AND aggregate_id=v_id::text
      RETURNING version INTO v_version; END IF;
    IF p_kind='place' THEN SELECT to_jsonb(p)||jsonb_build_object('aggregate_version',v_version),p.title
      INTO v_entity,v_label FROM public.places p WHERE p.id=v_id;
    ELSIF p_kind='place_type' THEN SELECT to_jsonb(t)||jsonb_build_object('aggregate_version',v_version),t.title
      INTO v_entity,v_label FROM public.place_types t WHERE t.id=v_id;
    ELSE SELECT to_jsonb(pg)||jsonb_build_object('aggregate_version',v_version),pg.title
      INTO v_entity,v_label FROM public.path_groups pg WHERE pg.id=v_id; END IF;
  END IF;

  IF p_kind='place' THEN
    v_impacts:=public.group_profile_impacts_internal_v1(p_occasion,ARRAY(SELECT DISTINCT ug."user" FROM public.user_groups ug JOIN public.user_group_info g ON g.id=ug."group" WHERE g.occasion=p_occasion AND g.place=v_id));
    IF EXISTS(SELECT 1 FROM jsonb_array_elements(v_impacts) x WHERE x->>'userId'=v_actor::text) THEN
      v_replacements:=jsonb_build_array(jsonb_build_object('component','private_profile','userId',v_actor,'payload',public.get_private_profile_payload_v1(p_occasion,v_actor)));
    END IF;
  END IF;
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'map.'||p_kind||'.'||p_action,'map',jsonb_build_array(jsonb_build_object(
      'entityType',p_kind,'entityId',v_id,'operation',CASE WHEN p_action='delete'
        THEN 'delete' WHEN v_current IS NULL THEN 'insert' ELSE 'update' END,
      'safeLabel',left(v_label,240),'changedFields',jsonb_build_array('aggregate'))),
    CASE WHEN v_is_publishable AND v_affects_public THEN ARRAY['map_catalog']
      ELSE '{}'::text[] END,v_impacts,'[]',
    jsonb_build_object('version',COALESCE(v_version,0),v_entity_key,v_entity),'{}','[]','user',NULL,v_replacements);
END; $function$

CREATE OR REPLACE FUNCTION public.next_order_sequence(p_occasion bigint)
 RETURNS bigint
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE candidate bigint;
BEGIN
 IF p_occasion IS NULL THEN RAISE EXCEPTION 'order_sequence requires occasion'; END IF;
 PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('festapp:order-sequence:' || p_occasion::text, 0));
 SELECT COALESCE(MAX(order_sequence), 0) + 1 INTO candidate FROM eshop.orders WHERE occasion=p_occasion;
 RETURN candidate;
END;
$function$

CREATE OR REPLACE FUNCTION public.normalize_activity_graph_internal_v1(p_occasion bigint, p_graph jsonb, p_utc boolean DEFAULT true, p_validate boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE a jsonb; x jsonb; result jsonb:='[]'; assignments jsonb; seen uuid[]:='{}'; seen_assignments uuid[]:='{}'; aid uuid; xid uuid; places jsonb; events jsonb;
BEGIN
 IF p_graph IS NULL OR jsonb_typeof(p_graph)<>'array' OR jsonb_array_length(p_graph)>2000 OR octet_length(p_graph::text)>2097152 THEN RAISE invalid_parameter_value USING MESSAGE='invalid activity graph'; END IF;
 FOR a IN SELECT value FROM jsonb_array_elements(p_graph) ORDER BY value->>'id' LOOP
  IF jsonb_typeof(a)<>'object' OR NOT(a ?& ARRAY['id','title','is_hidden','order','assignments']) OR EXISTS(SELECT 1 FROM jsonb_object_keys(a) k WHERE k NOT IN('id','title','description','type','unit','is_hidden','order','data','assignments')) OR jsonb_typeof(a->'assignments')<>'array' THEN RAISE invalid_parameter_value USING MESSAGE='invalid activity'; END IF;
  aid:=(a->>'id')::uuid;
  IF aid IS NULL OR aid=ANY(seen) OR (p_validate AND EXISTS(SELECT 1 FROM public.activities WHERE id=aid AND occasion<>p_occasion)) OR (p_validate AND a->>'unit' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.occasions WHERE id=p_occasion AND unit=(a->>'unit')::bigint)) THEN RAISE invalid_parameter_value USING MESSAGE='duplicate or foreign activity'; END IF;
  seen:=array_append(seen,aid); assignments:='[]';
  FOR x IN SELECT value FROM jsonb_array_elements(a->'assignments') ORDER BY value->>'id' LOOP
   IF jsonb_typeof(x)<>'object' OR NOT(x ?& ARRAY['id','linked_place_ids','linked_event_ids']) OR EXISTS(SELECT 1 FROM jsonb_object_keys(x) k WHERE k NOT IN('id','user','start_time','end_time','title','description','data','linked_place_ids','linked_event_ids')) OR jsonb_typeof(x->'linked_place_ids')<>'array' OR jsonb_typeof(x->'linked_event_ids')<>'array' THEN RAISE invalid_parameter_value USING MESSAGE='invalid assignment'; END IF;
   xid:=(x->>'id')::uuid;
   IF xid IS NULL OR xid=ANY(seen_assignments) OR (p_validate AND EXISTS(SELECT 1 FROM public.activity_assignments aa JOIN public.activities ac ON ac.id=aa.activity_id WHERE aa.id=xid AND ac.occasion<>p_occasion)) OR (p_validate AND x->>'user' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.occasion_users WHERE occasion=p_occasion AND "user"=(x->>'user')::uuid)) THEN RAISE invalid_parameter_value USING MESSAGE='duplicate or foreign assignment'; END IF;
   IF p_validate AND (x->>'user' IS NULL OR x->>'start_time' IS NULL OR x->>'end_time' IS NULL OR public.activity_time_internal_v1(x->>'end_time',p_occasion,p_utc)::timestamptz < public.activity_time_internal_v1(x->>'start_time',p_occasion,p_utc)::timestamptz) THEN RAISE invalid_parameter_value USING MESSAGE='assignment user and ordered times required'; END IF;
   seen_assignments:=array_append(seen_assignments,xid);
   IF p_validate AND (EXISTS(SELECT 1 FROM jsonb_array_elements_text(x->'linked_place_ids') id WHERE NOT EXISTS(SELECT 1 FROM public.places WHERE public.places.id=id::bigint AND occasion=p_occasion)) OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(x->'linked_event_ids') id WHERE NOT EXISTS(SELECT 1 FROM public.events WHERE public.events.id=id::bigint AND occasion=p_occasion))) THEN RAISE invalid_parameter_value USING MESSAGE='foreign assignment reference'; END IF;
   SELECT COALESCE(jsonb_agg(id::bigint ORDER BY id::bigint),'[]') INTO places FROM jsonb_array_elements_text(x->'linked_place_ids') id;
   SELECT COALESCE(jsonb_agg(id::bigint ORDER BY id::bigint),'[]') INTO events FROM jsonb_array_elements_text(x->'linked_event_ids') id;
   IF jsonb_array_length(places)<>(SELECT count(DISTINCT v) FROM jsonb_array_elements(places) v) OR jsonb_array_length(events)<>(SELECT count(DISTINCT v) FROM jsonb_array_elements(events) v) THEN RAISE invalid_parameter_value USING MESSAGE='duplicate assignment links'; END IF;
   assignments:=assignments||jsonb_build_array(jsonb_build_object('id',xid,'user',(x->>'user')::uuid,'start_time',public.activity_time_internal_v1(x->>'start_time',p_occasion,p_utc),'end_time',public.activity_time_internal_v1(x->>'end_time',p_occasion,p_utc),'title',x->>'title','description',x->>'description','data',x->'data','linked_place_ids',places,'linked_event_ids',events));
  END LOOP;
  result:=result||jsonb_build_array(jsonb_build_object('id',aid,'title',a->>'title','description',a->>'description','type',a->>'type','unit',(a->>'unit')::bigint,'is_hidden',(a->>'is_hidden')::boolean,'order',(a->>'order')::bigint,'data',a->'data','assignments',assignments));
 END LOOP;
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.normalize_form_ticket_answers_internal(p_form bigint, p_tickets jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE tickets jsonb:='[]'; ticket jsonb; answer jsonb; fields jsonb; field_id bigint; numeric_keys text[];
 definition public.form_fields; value jsonb; seen bigint[]; product_choices text[]; product_choice text;
BEGIN
 IF jsonb_typeof(p_tickets) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'Invalid ticket answers'; END IF;
 FOR ticket IN SELECT * FROM jsonb_array_elements(p_tickets) LOOP
  fields:='[]'; seen:='{}'; product_choices:='{}';
  IF ticket ? 'fields' AND jsonb_typeof(ticket->'fields') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'Invalid ticket fields'; END IF;
  FOR answer IN SELECT * FROM jsonb_array_elements(coalesce(ticket->'fields','[]')) LOOP
   IF jsonb_typeof(answer) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'Invalid ticket field'; END IF;
   SELECT coalesce(array_agg(key),'{}') INTO numeric_keys FROM jsonb_object_keys(answer) key WHERE key ~ '^[0-9]+$';
   IF cardinality(numeric_keys)>1 THEN RAISE EXCEPTION 'FORM_FIELD_AMBIGUOUS'; END IF;
   field_id:=NULL;
   IF answer ? '_subFieldId' THEN
    IF coalesce(answer->>'_subFieldId','') !~ '^[1-9][0-9]{0,17}$' THEN RAISE EXCEPTION 'FORM_FIELD_SCOPE_MISMATCH'; END IF;
    field_id:=(answer->>'_subFieldId')::bigint;
    IF cardinality(numeric_keys)=1 AND numeric_keys[1]<>field_id::text THEN RAISE EXCEPTION 'FORM_FIELD_SCOPE_MISMATCH'; END IF;
   ELSIF cardinality(numeric_keys)=1 THEN
    IF numeric_keys[1] !~ '^[1-9][0-9]{0,17}$' THEN RAISE EXCEPTION 'FORM_FIELD_SCOPE_MISMATCH'; END IF;
    field_id:=numeric_keys[1]::bigint;
   END IF;
   IF field_id IS NOT NULL THEN
    SELECT * INTO definition FROM public.form_fields WHERE id=field_id AND form=p_form AND is_ticket_field AND NOT is_hidden;
    IF NOT FOUND THEN RAISE EXCEPTION 'FORM_FIELD_SCOPE_MISMATCH'; END IF;
    IF NOT answer ? field_id::text AND NOT answer ? definition.type THEN RAISE EXCEPTION 'FORM_FIELD_TYPE_MISMATCH'; END IF;
    IF answer ? field_id::text AND answer ? definition.type AND answer->(field_id::text) IS DISTINCT FROM answer->definition.type THEN
     RAISE EXCEPTION 'FORM_FIELD_VALUE_CONFLICT'; END IF;
    -- A typed name cannot stand in for another field type with the same ID.
    IF EXISTS(SELECT 1 FROM jsonb_object_keys(answer) key WHERE key<>field_id::text AND key<>definition.type
     AND key NOT IN ('_subFieldId','currency_code','price')) THEN
      RAISE EXCEPTION 'FORM_FIELD_TYPE_MISMATCH'; END IF;
    value:=coalesce(answer->(field_id::text),answer->definition.type);
    IF field_id=ANY(seen) AND NOT (definition.type='product_type' AND coalesce(definition.data->>'selection_type','')='select_many') THEN
     RAISE EXCEPTION 'FORM_FIELD_AMBIGUOUS'; END IF;
    seen:=seen||field_id;
    IF definition.type='product_type' THEN
     product_choice:=field_id::text||':'||((value#>>'{}')::bigint)::text;
     IF product_choice=ANY(product_choices) THEN RAISE EXCEPTION 'FORM_FIELD_AMBIGUOUS'; END IF;
     product_choices:=product_choices||product_choice;
     IF NOT EXISTS(SELECT 1 FROM eshop.products product WHERE product.id=(value#>>'{}')::bigint
       AND product.product_type=definition.product_type) THEN RAISE EXCEPTION 'PRODUCT_SCOPE_MISMATCH'; END IF;
    END IF;
    -- Existing product and personal-choice transports carry UI price hints.
    -- They never determine payment; the finalizer prices actual products only.
    answer:=answer-'price';
    answer:=answer||jsonb_build_object(field_id::text,value,definition.type,value,'_subFieldId',field_id);
   END IF;
   fields:=fields||jsonb_build_array(answer);
  END LOOP;
  tickets:=tickets||jsonb_build_array(jsonb_set(ticket,'{fields}',fields,true));
 END LOOP;
 RETURN tickets;
END $function$

CREATE OR REPLACE FUNCTION public.normalize_occasion_setup_invite_emails(p_emails text[])
 RETURNS text[]
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE result text[];
BEGIN
 IF coalesce(cardinality(p_emails),0)>20 THEN RAISE invalid_parameter_value USING MESSAGE='At most 20 invitations'; END IF;
 IF EXISTS(SELECT 1 FROM unnest(p_emails) e WHERE e IS NULL OR length(btrim(e))>254
   OR btrim(e) !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$') THEN
  RAISE invalid_parameter_value USING MESSAGE='Invalid invitation email'; END IF;
 SELECT coalesce(array_agg(e ORDER BY e),'{}'::text[]) INTO result
 FROM (SELECT DISTINCT lower(btrim(e)) e FROM unnest(p_emails) e) normalized;
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.open_scanner_session(p_scan_code text DEFAULT NULL::text, p_occasion bigint DEFAULT NULL::bigint, p_device_name text DEFAULT 'Hlavní vstup'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE oc public.occasions; s public.scanner_sessions; cfg public.scanner_settings; token text; origin text; sec text;
BEGIN
 IF NOT public.check_scan_attempt_budget_v1(p_occasion) THEN RETURN jsonb_build_object('code',429,'reason','abuse_limit_exceeded','retry_after_ms',30000,'server_time',now()); END IF;
 IF p_scan_code IS NOT NULL THEN
  SELECT o.* INTO oc FROM public.occasions o JOIN public.occasions_hidden oh ON oh.id=o.occasion_hidden WHERE oh.secret=p_scan_code LIMIT 1;
  -- record assignment above must match the occasion row exactly
  origin:='scan_link'; sec:=p_scan_code;
 ELSE
  PERFORM public.scanner_require_settings_editor_internal(p_occasion);
  SELECT * INTO oc FROM public.occasions WHERE id=p_occasion; origin:='authenticated';
 END IF;
 IF oc.id IS NULL THEN PERFORM public.admit_scan_access_v1(NULL,false); RETURN jsonb_build_object('code',401,'reason','invalid_scan_code','server_time',now()); END IF;
 IF NOT public.admit_scan_access_v1(oc.id,true) THEN RETURN jsonb_build_object('code',429,'reason','abuse_limit_exceeded','server_time',now()); END IF;
 INSERT INTO public.scanner_settings(occasion_id,config) VALUES(oc.id,public.scanner_default_settings_internal(oc.id)) ON CONFLICT DO NOTHING;
 SELECT * INTO cfg FROM public.scanner_settings WHERE occasion_id=oc.id FOR SHARE;
 token:=encode(gen_random_bytes(32),'hex');
 INSERT INTO public.scanner_sessions(occasion_id,actor_user_id,access_origin,token_hash,scan_secret_hash,epoch,device_name,expires_at,offline_until)
 VALUES(oc.id,CASE WHEN origin='authenticated' THEN auth.uid() END,origin,encode(digest(token,'sha256'),'hex'),encode(digest(sec,'sha256'),'hex'),cfg.epoch,left(p_device_name,80),now()+interval '12 hours',
 now()+make_interval(hours=>CASE WHEN (cfg.config#>>'{offline,enabled}')::boolean THEN (cfg.config#>>'{offline,max_hours}')::integer ELSE 0 END)) RETURNING * INTO s;
 RETURN jsonb_build_object('code',200,'server_time',now(),'data',jsonb_build_object('session_id',s.id,'token',token,'occasion_id',oc.id,'organization_id',oc.organization,
 'title',oc.title,'epoch',s.epoch,'expires_at',s.expires_at,'offline_until',s.offline_until,'settings_revision',cfg.revision,'settings',cfg.config,'device_name',s.device_name,
 'capabilities',jsonb_build_object('search_tickets',(cfg.config#>>'{manual_search,tickets}')::boolean,'search_users',(cfg.config#>>'{manual_search,users}')::boolean,
 'settings',public.scanner_can_manage_settings_internal(oc.id),'event_history',auth.uid() IS NOT NULL AND public.get_is_editor_order_on_occasion(oc.id),'offline',(cfg.config#>>'{offline,enabled}')::boolean)));
END $function$

CREATE OR REPLACE FUNCTION public.password_verification_attempt_v1(event jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE actor uuid; allowed boolean;
BEGIN
 actor:=(event->>'user_id')::uuid;
 IF actor IS NULL OR jsonb_typeof(event->'valid') IS DISTINCT FROM 'boolean'
  OR NOT EXISTS(SELECT 1 FROM auth.users WHERE id=actor) THEN
  RETURN jsonb_build_object('decision','reject','message','Invalid login attempt','should_logout_user',false);
 END IF;
 allowed:=public.abuse_charge_v1(public.abuse_effective_rules_v1('auth.password',NULL,NULL),
  jsonb_build_object('actor',actor::text),'{}',true);
 RETURN jsonb_build_object('decision',CASE WHEN allowed THEN 'continue' ELSE 'reject' END,
  'message',CASE WHEN allowed THEN '' ELSE 'Too many login attempts. Try again later.' END,
  'should_logout_user',false);
END $function$

CREATE OR REPLACE FUNCTION public.prepare_scanner_snapshot(p_session uuid, p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE s public.scanner_sessions; cfg public.scanner_settings; sid uuid:=gen_random_uuid(); v_manifest jsonb;
 policy jsonb; max_items bigint; max_bytes bigint; items bigint; bytes bigint;
BEGIN
 s:=public.scanner_session_internal(p_session,p_token); SELECT * INTO cfg FROM public.scanner_settings WHERE occasion_id=s.occasion_id;
 IF NOT (cfg.config#>>'{offline,enabled}')::boolean OR s.offline_until<=now() THEN RAISE insufficient_privilege USING MESSAGE='offline_disabled'; END IF;
 -- Bound repeated materialization per device, in addition to existing operation/export policy.
 PERFORM pg_advisory_xact_lock(hashtextextended(p_session::text,5318));
 IF EXISTS(SELECT 1 FROM public.scanner_snapshots WHERE session_id=p_session AND created_at>now()-interval '60 seconds') THEN
  RETURN jsonb_build_object('code',429,'reason','snapshot_rate_limit','retry_after_ms',60000,'server_time',now()); END IF;
 IF NOT public.admit_scan_access_v1(s.occasion_id,true) THEN RETURN jsonb_build_object('code',429,'reason','abuse_limit_exceeded','server_time',now()); END IF;
 policy:=public.abuse_effective_rules_v1('scan.export',(SELECT unit FROM public.occasions WHERE id=s.occasion_id),(SELECT organization FROM public.occasions WHERE id=s.occasion_id));
 SELECT (r->>'base_limit')::bigint INTO max_items FROM jsonb_array_elements(policy->'rules') r WHERE r->>'rule_key'='scan.export.items';
 SELECT (r->>'base_limit')::bigint INTO max_bytes FROM jsonb_array_elements(policy->'rules') r WHERE r->>'rule_key'='scan.export.bytes';
 IF max_items IS NULL OR max_bytes IS NULL THEN RAISE configuration_limit_exceeded USING MESSAGE='abuse_policy_missing'; END IF;
 INSERT INTO public.scanner_snapshots(id,session_id,manifest,expires_at) VALUES(sid,p_session,'{}',s.offline_until);
 -- Exactly one statement snapshot supplies pages AND manifest. Never paginate live tickets.
 WITH projected AS MATERIALIZED (
  SELECT ticket_id,dto,row_number() OVER(ORDER BY ticket_id) rn FROM public.scanner_ticket_projection_internal(s.occasion_id,cfg.config)
 ), pages AS MATERIALIZED (
  SELECT ((rn-1)/200)::integer idx,jsonb_agg(dto ORDER BY rn)::text payload,count(*) n FROM projected GROUP BY ((rn-1)/200)::integer
 ), stored AS (
  INSERT INTO public.scanner_snapshot_pages(snapshot_id,page_index,payload_text,digest)
  SELECT sid,idx,payload,encode(digest(convert_to(payload,'UTF8'),'sha256'),'hex') FROM pages RETURNING *
 ) SELECT jsonb_build_object('schema_version',1,'snapshot_id',sid,'session_id',p_session,'occasion_id',s.occasion_id,'epoch',s.epoch,
 'settings_revision',cfg.revision,'server_time',now(),'expires_at',s.offline_until,'ticket_count',(SELECT count(*) FROM projected),
 'byte_count',coalesce(sum(octet_length(payload_text)),0),'pages',coalesce(jsonb_agg(jsonb_build_object('index',page_index,'digest',digest) ORDER BY page_index),'[]'::jsonb))
 INTO v_manifest FROM stored;
 items:=(v_manifest->>'ticket_count')::bigint; bytes:=(v_manifest->>'byte_count')::bigint;
 IF items>max_items OR bytes>max_bytes THEN
  DELETE FROM public.scanner_snapshots WHERE id=sid;
  RETURN jsonb_build_object('code',429,'reason','snapshot_policy_limit','server_time',now()); END IF;
 UPDATE public.scanner_snapshots SET manifest=v_manifest WHERE id=sid;
 -- Snapshot cleanup only; receipts and unresolved operations are never TTL deleted.
 DELETE FROM public.scanner_snapshots WHERE expires_at<now()-interval '24 hours';
 RETURN jsonb_build_object('code',200,'data',v_manifest,'server_time',now());
END $function$

CREATE OR REPLACE FUNCTION public.preview_blueprint_swap(p_spot_1 bigint, p_spot_2 bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE ids bigint[]; order_ids bigint[]; before_orders jsonb; sides jsonb; result jsonb; occ bigint;
BEGIN
 SELECT min(occasion) INTO occ FROM eshop.spots WHERE id IN(p_spot_1,p_spot_2);
 IF occ IS NULL THEN RAISE insufficient_privilege USING MESSAGE='order editor required'; END IF;
 IF public.get_is_editor_order_on_occasion(occ) IS NOT TRUE THEN RAISE insufficient_privilege USING MESSAGE='order editor required'; END IF;
 PERFORM public.lock_blueprint_scope_internal(ARRAY[occ]);
 ids:=public.blueprint_selection_unit_spots_internal(p_spot_1)||public.blueprint_selection_unit_spots_internal(p_spot_2);
 SELECT array_agg(DISTINCT opt."order") INTO order_ids FROM eshop.spots s JOIN eshop.order_product_ticket opt ON opt.id=s.order_product_ticket WHERE s.id=ANY(ids);
 PERFORM public.lock_order_capacity_scope_internal(order_ids);
 SELECT coalesce(jsonb_object_agg(id::text,price),'{}') INTO before_orders FROM eshop.orders WHERE id=ANY(order_ids);
 SELECT coalesce(jsonb_agg(jsonb_build_object('spotId',s.id,'title',s.title,'orderId',o.id,'ticketId',opt.ticket,
  'customer',jsonb_build_object('name',o.data->>'name','surname',o.data->>'surname','email',o.data->>'email')) ORDER BY s.id),'[]')
 INTO sides FROM eshop.spots s LEFT JOIN eshop.order_product_ticket opt ON opt.id=s.order_product_ticket LEFT JOIN eshop.orders o ON o.id=opt."order" WHERE s.id=ANY(ids);
 BEGIN
  PERFORM public.swap_spot_tickets_internal_v1(p_spot_1,p_spot_2);
  SELECT jsonb_build_object('code',200,'spotIds',to_jsonb(ids),'sides',sides,'orders',coalesce(jsonb_agg(jsonb_build_object(
   'orderId',id,'beforeAmount',(before_orders->>id::text)::numeric,'afterAmount',price,
   'delta',price-(before_orders->>id::text)::numeric,'currencyCode',currency_code) ORDER BY id),'[]')) INTO result FROM eshop.orders WHERE id=ANY(order_ids);
  RAISE SQLSTATE 'BP001' USING MESSAGE='rollback successful swap preview';
 EXCEPTION WHEN SQLSTATE 'BP001' THEN NULL;
 WHEN OTHERS THEN result:=jsonb_build_object('code',409,'reason',SQLERRM,'issues',jsonb_build_array(jsonb_build_object('reason',SQLERRM)));
 END;
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.preview_occasion_setup_invitations(p_id uuid, p_emails text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE d public.occasion_setup_drafts; emails text[]; event_id bigint; event_link text; event_title text; recipients jsonb; org_data jsonb;
BEGIN
 SELECT * INTO d FROM public.occasion_setup_drafts WHERE id=p_id;
 IF NOT FOUND OR auth.uid() IS NULL OR NOT (public.get_is_manager_on_unit(d.unit) OR public.get_is_editor_on_unit(d.unit)) THEN
  RAISE insufficient_privilege USING MESSAGE='Draft access denied'; END IF;
 IF NOT public.get_is_manager_on_unit(d.unit) THEN RETURN jsonb_build_object('canManage',false,'recipients','[]'::jsonb); END IF;
 IF p_emails IS NULL THEN
  IF d.data ? 'finalizedOccasion' AND d.data->'sendTeamInvitations' IS DISTINCT FROM 'true'::jsonb THEN
   RAISE invalid_parameter_value USING MESSAGE='Invitation sending not confirmed'; END IF;
  IF jsonb_typeof(coalesce(d.data->'teamInviteEmails','[]'::jsonb)) IS DISTINCT FROM 'array' THEN
   RAISE invalid_parameter_value USING MESSAGE='Invalid invitation emails'; END IF;
  p_emails:=ARRAY(SELECT jsonb_array_elements_text(coalesce(d.data->'teamInviteEmails','[]'::jsonb)));
 END IF;
 emails:=public.normalize_occasion_setup_invite_emails(p_emails);
 event_id:=(d.data->>'finalizedOccasion')::bigint;
 IF event_id IS NOT NULL THEN SELECT link,title INTO event_link,event_title FROM public.occasions WHERE id=event_id AND unit=d.unit AND organization=d.organization;
 ELSE event_link:=d.data->>'link'; event_title:=d.data->>'title'; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('email',e,'kind',CASE WHEN EXISTS(
   SELECT 1 FROM public.unit_users uu WHERE uu.unit=d.unit AND uu."user"=ui.id) THEN 'member'
   WHEN ui.id IS NOT NULL THEN 'account' ELSE 'new' END,
   'role',public.occasion_setup_invitation_role(d.data->'teamInviteRoles',e),
   'alreadyEditor',coalesce((SELECT ou.is_editor OR ou.is_manager OR (ou.is_editor_view AND public.occasion_setup_invitation_role(d.data->'teamInviteRoles',e)='read_only') FROM public.occasion_users ou
      WHERE ou.occasion=event_id AND ou."user"=ui.id),false)) ORDER BY e),'[]')
 INTO recipients FROM unnest(emails) e LEFT JOIN public.user_info ui
 ON ui.organization=d.organization AND lower(btrim(ui.email_readonly))=e;
 SELECT jsonb_build_object('APP_NAME',data->>'APP_NAME','DEFAULT_URL',data->>'DEFAULT_URL') INTO org_data FROM public.organizations WHERE id=d.organization;
 RETURN jsonb_build_object('canManage',true,'sendConfirmed',d.data->'sendTeamInvitations'='true'::jsonb,'recipients',recipients,'event',jsonb_build_object(
   'id',event_id,'link',event_link,'title',event_title,'unit',d.unit,'organization',d.organization),
   'organizationData',org_data);
END $function$

CREATE OR REPLACE FUNCTION public.preview_scanner_ticket(p_occasion bigint, p_config jsonb, p_symbol text)
 RETURNS jsonb
 LANGUAGE plpgsql
