CREATE OR REPLACE FUNCTION public.process_occasion_auto_import(p_occasion_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_occasion_features JSONB;
    v_is_auto_import_enabled BOOLEAN := false;
    v_import_res JSONB;
    v_inserted_user JSONB;
    v_target_user_id UUID;
    v_processed_count INT := 0;
BEGIN
    -- 1. Check if feature is enabled for this occasion
    SELECT features INTO v_occasion_features
    FROM public.occasions
    WHERE id = p_occasion_id;

    -- Since features is an Array, we expand it using jsonb_array_elements
    -- and filter for the object where 'code' is 'import'.
    SELECT COALESCE((feature_obj->>'auto_import')::boolean, false)
    INTO v_is_auto_import_enabled
    FROM jsonb_array_elements(v_occasion_features) AS feature_obj
    WHERE feature_obj->>'code' = 'import'
    LIMIT 1;

    -- 2. If enabled, run import and password reset
    IF v_is_auto_import_enabled THEN

        -- Run the import
        v_import_res := public.import_users_from_tickets(p_occasion_id);

        -- Check if we have inserted users
        IF v_import_res ? 'inserted' THEN
            FOR v_inserted_user IN SELECT * FROM jsonb_array_elements(v_import_res->'inserted')
            LOOP
                -- Extract ID directly from the updated function's return object
                v_target_user_id := (v_inserted_user->>'id')::UUID;

                IF v_target_user_id IS NOT NULL THEN
                    -- Reset password to '1'
                    UPDATE auth.users
                    SET encrypted_password = crypt('1', gen_salt('bf'))
                    WHERE id = v_target_user_id;

                    v_processed_count := v_processed_count + 1;
                END IF;
            END LOOP;
        END IF;

        -- Return result for debugging/logging
        RETURN jsonb_build_object(
            'success', true,
            'processed_users', v_processed_count,
            'import_details', v_import_res
        );
    END IF;

    -- Return skipped if feature disabled
    RETURN jsonb_build_object('success', false, 'reason', 'feature_disabled');
END;
$function$

CREATE OR REPLACE FUNCTION public.process_token_register(data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
    email_exists boolean;
    inserted_id uuid;
    token uuid;
    result jsonb;
BEGIN
    -- Legacy registration helper has no application caller; retained for trusted maintenance only.
    PERFORM public.require_service_role();

    -- Check if the data contains an email
    IF NOT (data ? 'email') THEN
        -- Construct the result JSONB object with code 400
        result := jsonb_build_object('code', 400, 'message', 'Email is required');
        RETURN result;
    END IF;

    -- Call the function to get the user_id by email
    email_exists := get_user_id_by_email(data ->> 'email') IS NOT NULL;

    -- If email exists, return error
    IF email_exists THEN
        -- Construct the result JSONB object with code 400
        result := jsonb_build_object('code', 400, 'message', 'Email already exists');
        RETURN result;
    END IF;

    -- Generate token
    token := gen_random_uuid();

    -- Insert data into the token_register_user table and capture the inserted ID
    INSERT INTO token_register_user (id, token, is_activated, data)
    VALUES (gen_random_uuid(), token, false, data)
    RETURNING id INTO inserted_id;

    -- Construct the result JSONB object with code 200, ID, and token
    result := jsonb_build_object('code', 200, 'id', inserted_id, 'token', token, 'message', 'Registration successful');
    RETURN result;
END;
$function$

CREATE OR REPLACE FUNCTION public.project_local_payment_reference_order_internal(p_response jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE payload jsonb:=CASE WHEN p_response ? 'data' THEN p_response->'data' ELSE p_response END;
 target eshop.orders; payment eshop.payment_info; details jsonb;
BEGIN
 IF payload#>>'{order,id}' IS NULL THEN RETURN p_response; END IF;
 SELECT * INTO target FROM eshop.orders WHERE id=(payload#>>'{order,id}')::bigint;
 IF target.id IS NULL OR target.state='storno' THEN
  payload:=jsonb_set(payload,'{order,payment_info}','null')||jsonb_build_object('code',409,'errorCode','ORDER_NOT_PAYABLE');
 ELSE
  SELECT * INTO payment FROM eshop.payment_info WHERE id=target.payment_info;
  IF payment.id IS NOT NULL THEN
   details:=coalesce(payload#>'{order,payment_info}','{}')||jsonb_build_object('id',payment.id,'variable_symbol',payment.variable_symbol,
    'creditor_reference',payment.creditor_reference,'amount',payment.amount,'deposit_amount',payment.deposit_amount,
    'deadline',payment.deadline,'deposit_deadline',payment.deposit_deadline,'currency_code',payment.currency_code);
   payload:=jsonb_set(payload,'{order,payment_info}',details);
  END IF;
 END IF;
 IF p_response ? 'data' THEN RETURN jsonb_set(p_response,'{data}',payload); END IF;
 RETURN payload;
END $function$

CREATE OR REPLACE FUNCTION public.publish_activities_client_sync_v1(p_occasion bigint, p_command_id uuid, p_expected_version bigint, p_activities_data jsonb, p_history_data jsonb, p_parent_history_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE actor uuid:=auth.uid(); b jsonb; v bigint; latest bigint; graph jsonb; history jsonb; old_graph jsonb; previous_history jsonb; hid bigint; live_changed boolean; deleted int; impacts jsonb; replacements jsonb:='[]'; users uuid[];
BEGIN
 PERFORM public.assert_canonical_mutation_write_release_internal_v1(p_occasion);
 IF actor IS NULL OR NOT public.get_is_editor_on_occasion(p_occasion) THEN RAISE insufficient_privilege USING MESSAGE='occasion editor required'; END IF;
 IF p_activities_data IS NULL OR jsonb_typeof(p_activities_data)<>'array' OR p_history_data IS NULL OR jsonb_typeof(p_history_data)<>'object' OR octet_length(p_activities_data::text)>2097152 OR octet_length(p_history_data::text)>2097152 THEN RAISE invalid_parameter_value USING MESSAGE='invalid activities aggregate'; END IF;
 b:=public.begin_client_mutation_v1(p_command_id,'activities.publish',p_occasion,actor,encode(extensions.digest(jsonb_build_object('occasion',p_occasion,'expectedVersion',p_expected_version,'activities',p_activities_data,'history',p_history_data,'parentHistoryId',p_parent_history_id)::text,'sha256'),'hex'));
 v:=public.lock_activity_editor_internal_v1(p_occasion);
 IF b->>'disposition'='replay' THEN RETURN b->'response'; END IF;
 SELECT id,activities_data INTO latest,previous_history FROM public.activity_history WHERE occasion_id=p_occasion AND history_type='PUBLISH' ORDER BY id DESC LIMIT 1;
 IF p_expected_version IS DISTINCT FROM v OR p_parent_history_id IS DISTINCT FROM latest THEN RETURN public.complete_client_mutation_outcome_v1(p_command_id,'conflict',409,jsonb_build_object('version',v,'latestPublishId',latest,'historyId',latest)); END IF;
 graph:=public.normalize_activity_graph_internal_v1(p_occasion,p_activities_data,true);
 IF graph IS DISTINCT FROM public.activity_history_graph_internal_v1(p_occasion,p_history_data-'_consume_autosave') THEN RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',400,jsonb_build_object('version',v,'latestPublishId',latest,'reason','graph_history_mismatch')); END IF;
 history:=public.activity_graph_history_internal_v1(graph); old_graph:=public.current_activity_graph_internal_v1(p_occasion);
 live_changed:=graph IS DISTINCT FROM old_graph OR latest IS NULL;
 IF NOT live_changed AND public.activity_history_graph_internal_v1(p_occasion,previous_history)=graph THEN
  deleted:=public.consume_selected_activity_draft_internal_v1(p_occasion,actor,latest,p_history_data->'_consume_autosave',graph);
  IF deleted=0 THEN RETURN public.complete_client_mutation_outcome_v1(p_command_id,'unchanged',200,jsonb_build_object('version',v,'historyId',latest,'latestPublishId',latest,'draftId',(SELECT id FROM public.activity_history WHERE occasion_id=p_occasion AND user_id=actor AND history_type='AUTOSAVE' ORDER BY id DESC LIMIT 1),'draftConsumed',false)); END IF;
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,'activities.publish','activities',jsonb_build_array(jsonb_build_object('entityType','activity_draft','entityId',NULL,'operation','delete','changedFields',jsonb_build_array('draft'))),'{}','[]','[]',jsonb_build_object('version',v,'historyId',latest,'latestPublishId',latest,'draftId',NULL,'draftConsumed',true));
 END IF;
 SELECT ARRAY(SELECT DISTINCT (x->>'user')::uuid FROM jsonb_array_elements(old_graph||graph) a,LATERAL jsonb_array_elements(a->'assignments') x WHERE x->>'user' IS NOT NULL UNION SELECT actor) INTO users;
 PERFORM public.replace_activities_graph_internal_v1(p_occasion,graph);
 hid:=public.write_activity_history_internal_v1(p_occasion,actor,history,'PUBLISH',latest,'Published via application');
 deleted:=public.consume_selected_activity_draft_internal_v1(p_occasion,actor,latest,p_history_data->'_consume_autosave',graph);
 UPDATE public.client_aggregate_versions SET version=version+1,updated_at=clock_timestamp() WHERE aggregate_type='activities' AND scope_type='occasion' AND scope_id=p_occasion AND aggregate_id=p_occasion::text RETURNING version INTO v;
 SELECT COALESCE(jsonb_agg(jsonb_build_object('component','private_activity','userId',u) ORDER BY u),'[]') INTO impacts FROM unnest(users) u JOIN public.occasion_users ou ON ou.occasion=p_occasion AND ou."user"=u;
 replacements:=jsonb_build_array(jsonb_build_object('component','private_activity','userId',actor,'payload',(public.get_my_events_and_activities(p_occasion,true)->'data')));
 PERFORM public.retain_activity_history_internal_v1(p_occasion);
 RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,'activities.publish','activities',jsonb_build_array(jsonb_build_object('entityType','activities','entityId',p_occasion,'operation','publish','changedFields',jsonb_build_array('graph','history'))),'{}',impacts,'[]',jsonb_build_object('version',v,'historyId',hid,'latestPublishId',hid,'draftId',(SELECT id FROM public.activity_history WHERE occasion_id=p_occasion AND user_id=actor AND history_type='AUTOSAVE' ORDER BY id DESC LIMIT 1),'draftConsumed',deleted>0,'activities',graph),'{}','[]','user',NULL,replacements);
END $function$

CREATE OR REPLACE FUNCTION public.publish_news_client_sync_v1(p_occasion bigint, p_add_to_news boolean, p_news_message text, p_send_notification boolean, p_notification_heading text, p_notification_content text, p_recipients jsonb, p_command_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_notification uuid; v_actor uuid:=auth.uid(); v_organization bigint; v_begin jsonb; v_hash text;
  v_id bigint; v_version bigint:=0; v_entity jsonb; v_items jsonb:='[]'::jsonb;
  v_is_publishable boolean; v_response jsonb; v_required_revision bigint;
BEGIN
  IF v_actor IS NULL OR NOT public.get_is_editor_on_occasion(p_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion editor required'; END IF;
  SELECT o.organization,NOT o.is_hidden INTO v_organization,v_is_publishable
    FROM public.occasions o WHERE o.id=p_occasion;
  IF v_organization IS NULL OR NOT COALESCE(p_add_to_news,false)
      AND NOT COALESCE(p_send_notification,false)
    OR p_add_to_news AND (p_news_message IS NULL
      OR octet_length(p_news_message) NOT BETWEEN 1 AND 524288)
    OR p_send_notification AND (p_notification_content IS NULL
      OR octet_length(p_notification_content)>65536
      OR octet_length(COALESCE(p_notification_heading,''))>2048
      OR p_recipients IS NOT NULL AND (jsonb_typeof(p_recipients)<>'array'
        OR jsonb_array_length(p_recipients)>5000
        OR EXISTS (SELECT 1 FROM jsonb_array_elements(p_recipients) value
          WHERE jsonb_typeof(value)<>'string'
            OR octet_length(value#>>'{}')>512))) THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid news publication'; END IF;
  IF COALESCE(p_add_to_news,false) AND COALESCE(p_send_notification,false)
      AND NOT v_is_publishable THEN
    RAISE invalid_parameter_value
      USING MESSAGE='news push requires a publicly publishable occasion';
  END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'occasion',p_occasion,'addToNews',p_add_to_news,'newsMessage',p_news_message,
    'sendNotification',p_send_notification,'notificationHeading',p_notification_heading,
    'notificationContent',p_notification_content,'recipients',p_recipients)::text,
    'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'content.news.publish',
    p_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  IF coalesce(p_send_notification,false) THEN PERFORM public.charge_notification_intent_v1(p_occasion,v_actor,p_recipients,p_notification_heading,p_notification_content); END IF;
  IF COALESCE(p_add_to_news,false) THEN
    INSERT INTO public.news(message,created_by,occasion)
      VALUES (p_news_message,v_actor,p_occasion) RETURNING id INTO v_id;
    v_version:=1;
    INSERT INTO public.client_aggregate_versions
      (aggregate_type,scope_type,scope_id,aggregate_id,version)
    VALUES ('news','occasion',p_occasion,v_id::text,v_version);
    SELECT to_jsonb(n)||jsonb_build_object('aggregate_version',v_version)
      INTO v_entity FROM public.news n WHERE n.id=v_id;
    v_items:=v_items||jsonb_build_array(jsonb_build_object(
      'entityType','news','entityId',v_id,'operation','insert','safeLabel','News',
      'changedFields',jsonb_build_array('message')));
  END IF;
  IF COALESCE(p_send_notification,false) THEN
    v_items:=v_items||jsonb_build_array(jsonb_build_object(
      'entityType','notification','entityId',NULL,'operation','publish',
      'safeLabel','Notification','changedFields',jsonb_build_array('delivery_request')));
  END IF;

  -- A notification-only test has no news publication to wait for.
  IF COALESCE(p_send_notification,false) AND NOT COALESCE(p_add_to_news,false) THEN
    INSERT INTO public.log_notifications
      (occasion,organization,user_id,"to",heading,content,data,abuse_admitted_at)
    VALUES (p_occasion,v_organization,v_actor,p_recipients,
      p_notification_heading,p_notification_content,jsonb_build_object('path','news'),statement_timestamp()) RETURNING id INTO v_notification;
    PERFORM public.dispatch_log_notification_v1(v_notification);
  END IF;

  v_response:=public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'content.news.publish','content',v_items,
    CASE WHEN COALESCE(p_add_to_news,false) AND v_is_publishable
      THEN ARRAY['content_catalog'] ELSE '{}'::text[] END,'[]','[]',
    jsonb_build_object('version',v_version,'news',v_entity,
      'notificationQueued',COALESCE(p_send_notification,false)));

  IF COALESCE(p_add_to_news,false) AND COALESCE(p_send_notification,false) THEN
    SELECT c.resulting_revision INTO v_required_revision
    FROM public.client_commit_components c
    WHERE c.commit_id=(v_response#>>'{mutation,commitId}')::uuid
      AND c.component='content_catalog' AND c.scope_type='occasion'
      AND c.scope_id=p_occasion AND c.user_id IS NULL;
    IF v_required_revision IS NULL THEN
      RAISE EXCEPTION 'news publication did not produce a content revision';
    END IF;
    INSERT INTO public.news_notification_outbox
      (command_id,occasion,organization,user_id,required_content_revision,
       "to",heading,content,data,abuse_admitted_at)
    VALUES (p_command_id,p_occasion,v_organization,v_actor,v_required_revision,
      p_recipients,p_notification_heading,p_notification_content,
      jsonb_build_object('path','news'),statement_timestamp());
  END IF;
  RETURN v_response;
END; $function$

CREATE OR REPLACE FUNCTION public.publish_user_profile_change_internal_v1(p_user uuid, p_origin bigint, p_before jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE oc bigint;
BEGIN
 IF p_before IS NOT DISTINCT FROM (SELECT to_jsonb(ui) FROM public.user_info ui WHERE id=p_user) THEN RETURN; END IF;
 FOR oc IN SELECT occasion FROM public.occasion_users WHERE "user"=p_user AND occasion IS DISTINCT FROM p_origin ORDER BY occasion LOOP
  INSERT INTO public.client_aggregate_versions(aggregate_type,scope_type,scope_id,aggregate_id,version)
  VALUES('occasion_user','occasion',oc,p_user::text,1)
  ON CONFLICT(aggregate_type,scope_type,scope_id,aggregate_id) DO UPDATE
  SET version=public.client_aggregate_versions.version+1,updated_at=clock_timestamp();
  PERFORM public.impact_private_profile_users_v1(oc,ARRAY[p_user],'profile.global.changed');
  PERFORM public.impact_companion_owners_v1(oc,ARRAY[p_user],'profile.companion_identity.changed');
 END LOOP;
END $function$

CREATE OR REPLACE FUNCTION public.random_payment_reference_digits_internal(p_digits integer)
 RETURNS bigint
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE value text:=''; bytes bytea; n integer; i integer;
BEGIN
 IF p_digits NOT BETWEEN 1 AND 10 THEN RAISE EXCEPTION 'PAYMENT_REFERENCE_POLICY_INVALID'; END IF;
 WHILE length(value)<p_digits LOOP
  bytes:=extensions.gen_random_bytes(32);
  FOR i IN 0..31 LOOP
   n:=get_byte(bytes,i);
   IF n>=250 OR (value='' AND mod(n,10)=0) THEN CONTINUE; END IF;
   value:=value||mod(n,10)::text;
   EXIT WHEN length(value)=p_digits;
  END LOOP;
 END LOOP;
 RETURN value::bigint;
END $function$

CREATE OR REPLACE FUNCTION public.random_public_link_internal()
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE alphabet constant text := '23456789abcdefghjkmnpqrstuvwxyz'; result text := ''; b integer;
BEGIN
 -- Rejection sampling avoids modulo bias (31 symbols).
 WHILE length(result)<8 LOOP
  b := get_byte(extensions.gen_random_bytes(1),0);
  IF b < 248 THEN result := result || substr(alphabet,b % 31 + 1,1); END IF;
 END LOOP;
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.recalculate_order_payment_status(p_order_id bigint)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
    v_payment_info_id bigint;
    v_paid numeric;
    v_deposit_amount numeric;
    v_price numeric;
    v_state text;
    v_transition jsonb;
BEGIN
    -- Get Order Details
    SELECT payment_info, price, state INTO v_payment_info_id, v_price, v_state
    FROM eshop.orders
    WHERE id = p_order_id;

    IF v_payment_info_id IS NULL THEN
        RETURN;
    END IF;

    -- Get Paid Amount and Deposit Amount from Payment Info
    SELECT paid, deposit_amount INTO v_paid, v_deposit_amount
    FROM eshop.payment_info
    WHERE id = v_payment_info_id;

    -- Update Logic
    IF COALESCE(v_paid, 0) >= COALESCE(v_deposit_amount, v_price) THEN
        -- Fully Paid (or Deposit Paid) -> Move to Paid
        IF v_state != 'paid' AND (v_state = 'ordered' OR v_state = 'created' OR v_state = 'expired') THEN
             -- The legacy JSON boundary reports failures instead of raising.
             -- Propagate them so payment, order, ticket intent and webhook receipt
             -- cannot commit independently of the canonical paid transition.
             v_transition := public.update_order_and_tickets_to_paid(p_order_id);
             IF (v_transition->>'code') IS DISTINCT FROM '200' THEN
                 RAISE EXCEPTION 'ORDER_PAID_TRANSITION_FAILED: %',
                     COALESCE(v_transition->>'message','invalid transition receipt');
             END IF;
        END IF;
    ELSE
        -- Underpaid -> Revert to Ordered (if currently Paid)
        IF v_state IN ('paid','sent') THEN
            PERFORM public.cancel_order_email_intents(p_order_id);
            -- Revert Order
            UPDATE eshop.orders
            SET state = 'ordered', updated_at = now(),email_payment_version=email_payment_version+1
            WHERE id = p_order_id;

            -- Revert Tickets (only those that are 'paid')
            UPDATE eshop.tickets
            SET state = 'ordered', updated_at = now() -- Reverted to 'ordered' as 'valid' is not a supported state

            FROM eshop.order_product_ticket
            WHERE eshop.order_product_ticket.ticket = eshop.tickets.id
            AND eshop.order_product_ticket."order" = p_order_id
            AND eshop.tickets.state IN ('paid','sent');
        END IF;
    END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.reconcile_unknown_email(p_message uuid, p_decision text, p_evidence text, p_provider_id text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE m public.email_messages;
BEGIN
 PERFORM public.require_service_role();
 PERFORM 1 FROM public.email_capacity FOR UPDATE;
 IF p_evidence IS NULL OR length(p_evidence)<10 OR p_decision NOT IN ('accepted','known_not_accepted','cancelled') THEN RAISE EXCEPTION 'reconciliation_evidence_required'; END IF;
 SELECT * INTO m FROM public.email_messages WHERE message_id=p_message FOR UPDATE;
 IF m.workflow_state<>'unknown' THEN RAISE EXCEPTION 'email_not_unknown'; END IF;
 IF p_decision='accepted' AND p_provider_id IS NULL THEN RAISE EXCEPTION 'provider_receipt_required'; END IF;
 UPDATE public.email_messages SET workflow_state=CASE p_decision WHEN 'accepted' THEN 'accepted' WHEN 'known_not_accepted' THEN 'pending' ELSE 'cancelled' END,
 accepted_at=CASE WHEN p_decision='accepted' THEN now() ELSE accepted_at END,provider_message_id=coalesce(p_provider_id,provider_message_id),
 target_time=now(),lease_token=NULL,lease_until=NULL,post_action=post_action||jsonb_build_object('reconciliation',jsonb_build_object('decision',p_decision,'evidence',left(p_evidence,256),'at',now()))
 WHERE message_id=p_message;
 PERFORM public.wake_email_worker();
END $function$

CREATE OR REPLACE FUNCTION public.record_account_deletion_sync_v1(p_user uuid, p_organization bigint)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_commit public.client_commits%ROWTYPE; v_occasion bigint;
  v_revision bigint; v_event bigint; v_member uuid;
BEGIN
  PERFORM public.require_client_sync_service_role_v1();
  IF p_user IS NULL OR p_organization IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.user_info ui
    WHERE ui.id=p_user AND ui.organization=p_organization) THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid account deletion sync scope';
  END IF;
  FOR v_occasion IN SELECT DISTINCT dependency.occasion FROM (
 SELECT occasion FROM public.occasion_users WHERE "user"=p_user
 UNION SELECT gi.occasion FROM public.user_groups g JOIN public.user_group_info gi ON gi.id=g."group" WHERE g."user"=p_user
 UNION SELECT a.occasion FROM public.activity_assignments x JOIN public.activities a ON a.id=x.activity_id WHERE x."user"=p_user
 UNION SELECT occasion_id FROM public.activity_history WHERE user_id=p_user
) dependency JOIN public.occasions o ON o.id=dependency.occasion WHERE o.organization=p_organization ORDER BY dependency.occasion LOOP
    PERFORM public.lock_activity_aggregate_internal_v1(v_occasion);
  END LOOP;
  INSERT INTO public.client_commits
    (organization,actor_id,actor_display,actor_kind,source,change_class,reason)
  VALUES (p_organization,p_user,NULL,'service','account.delete','profile',
    'confirmed account deletion') RETURNING * INTO v_commit;
  INSERT INTO public.client_commit_items
    (commit_id,item_index,entity_type,entity_id,operation,safe_label,changed_fields)
  VALUES (v_commit.commit_id,0,'user',p_user::text,'delete',NULL,
    ARRAY['membership','profile','private_data']);
  FOR v_occasion IN SELECT DISTINCT dependency.occasion FROM (
 SELECT occasion FROM public.occasion_users WHERE "user"=p_user
 UNION SELECT gi.occasion FROM public.user_groups g JOIN public.user_group_info gi ON gi.id=g."group" WHERE g."user"=p_user
 UNION SELECT a.occasion FROM public.activity_assignments x JOIN public.activities a ON a.id=x.activity_id WHERE x."user"=p_user
 UNION SELECT occasion_id FROM public.activity_history WHERE user_id=p_user
) dependency JOIN public.occasions o ON o.id=dependency.occasion WHERE o.organization=p_organization ORDER BY dependency.occasion LOOP
    IF EXISTS (SELECT 1 FROM public.event_users eu JOIN public.events e
        ON e.id=eu.event WHERE eu."user"=p_user AND e.occasion=v_occasion)
      OR EXISTS (SELECT 1 FROM public.event_users_saved es JOIN public.events e
        ON e.id=es.event WHERE es."user"=p_user AND e.occasion=v_occasion) THEN
      INSERT INTO public.client_sync_scopes
        (component,scope_type,scope_id,source_revision)
      VALUES ('live_public','occasion',v_occasion,1)
      ON CONFLICT (component,scope_type,scope_id) DO UPDATE SET
        source_revision=public.client_sync_scopes.source_revision+1,
        updated_at=now() RETURNING source_revision INTO v_revision;
      INSERT INTO public.client_commit_components
        (commit_id,component,scope_type,scope_id,user_id,resulting_revision)
      VALUES (v_commit.commit_id,'live_public','occasion',v_occasion,NULL,v_revision);
      FOR v_event IN SELECT DISTINCT id FROM (
        SELECT eu.event id FROM public.event_users eu JOIN public.events e
          ON e.id=eu.event WHERE eu."user"=p_user AND e.occasion=v_occasion
        UNION SELECT es.event FROM public.event_users_saved es JOIN public.events e
          ON e.id=es.event WHERE es."user"=p_user AND e.occasion=v_occasion
      ) affected ORDER BY id LOOP
        INSERT INTO public.client_projection_dirty_keys
          (component,scope_type,scope_id,entity_id,source_revision)
        VALUES ('live_public','occasion',v_occasion,v_event,v_revision)
        ON CONFLICT (component,scope_type,scope_id,entity_id) DO UPDATE SET
          source_revision=EXCLUDED.source_revision,dirty_since=now(),
          claimed_at=NULL,claim_token=NULL;
      END LOOP;
    END IF;
    IF EXISTS(SELECT 1 FROM public.activity_assignments aa JOIN public.activities a ON a.id=aa.activity_id WHERE a.occasion=v_occasion AND aa."user"=p_user) OR EXISTS(SELECT 1 FROM public.activity_history WHERE occasion_id=v_occasion AND user_id=p_user AND history_type='PUBLISH') THEN
      UPDATE public.client_aggregate_versions SET version=version+1,updated_at=clock_timestamp() WHERE aggregate_type='activities' AND scope_type='occasion' AND scope_id=v_occasion AND aggregate_id=v_occasion::text;
      FOR v_member IN SELECT "user" FROM public.occasion_users WHERE occasion=v_occasion AND "user"<>p_user ORDER BY "user" LOOP
        INSERT INTO public.client_sync_private_scopes(component,occasion,user_id,source_revision) VALUES('private_activity',v_occasion,v_member,1) ON CONFLICT(component,occasion,user_id) DO UPDATE SET source_revision=public.client_sync_private_scopes.source_revision+1,updated_at=clock_timestamp() RETURNING source_revision INTO v_revision;
        INSERT INTO public.client_commit_components(commit_id,component,scope_type,scope_id,user_id,resulting_revision) VALUES(v_commit.commit_id,'private_activity','occasion',v_occasion,v_member,v_revision);
      END LOOP;
    END IF;
    FOR v_member IN SELECT ou."user" FROM public.occasion_users ou
      WHERE ou.occasion=v_occasion AND ou."user"<>p_user ORDER BY ou."user" LOOP
      INSERT INTO public.client_sync_private_scopes
        (component,occasion,user_id,source_revision)
      VALUES ('private_profile',v_occasion,v_member,1)
      ON CONFLICT (component,occasion,user_id) DO UPDATE SET
        source_revision=public.client_sync_private_scopes.source_revision+1,
        updated_at=now() RETURNING source_revision INTO v_revision;
      INSERT INTO public.client_commit_components
        (commit_id,component,scope_type,scope_id,user_id,resulting_revision)
      VALUES (v_commit.commit_id,'private_profile','occasion',v_occasion,
        v_member,v_revision);
    END LOOP;
    UPDATE public.client_aggregate_versions SET version=version+1,
      updated_at=clock_timestamp() WHERE aggregate_type='user_group'
      AND scope_type='occasion' AND scope_id=v_occasion AND aggregate_id IN (
        SELECT ug."group"::text FROM public.user_groups ug
        WHERE ug."user"=p_user);
  END LOOP;
  RETURN v_commit.commit_id;
END; $function$

CREATE OR REPLACE FUNCTION public.record_bank_sync_health(p_organization_id bigint, p_connection_id bigint, p_success_at timestamp with time zone, p_error text, p_ingest_enabled boolean, p_polling_enabled boolean, p_token_present boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_connection eshop.bank_sync_connections; v_code text;
BEGIN
  PERFORM public.require_service_role();
  SELECT c.* INTO STRICT v_connection FROM eshop.bank_sync_connections c
    WHERE c.id=p_connection_id AND EXISTS (SELECT 1 FROM eshop.unit_bank_accounts ub JOIN public.units u ON u.id=ub.unit
      WHERE u.organization=p_organization_id AND (ub.bank_account=c.bank_account_id OR ub.bank_account IN
        (SELECT a.bank_account_id FROM eshop.bank_sync_account_aliases a WHERE a.connection_id=c.id))) FOR UPDATE;
  IF p_error IS NOT NULL AND p_error NOT IN ('fio_token_invalid_or_inactive','fio_receiving_account_mismatch','bank_sync_retry_required') THEN
    RAISE EXCEPTION 'BANK_SYNC_HEALTH_ERROR_INVALID';
  END IF;
  PERFORM public.record_bank_sync_pull(p_connection_id,p_success_at,p_error);
  INSERT INTO eshop.bank_sync_health(connection_id,checked_at,ingest_enabled,polling_enabled,token_present)
    VALUES(p_connection_id,now(),p_ingest_enabled,p_polling_enabled,p_token_present)
    ON CONFLICT(connection_id) DO UPDATE SET checked_at=now(),
      ingest_enabled=COALESCE(EXCLUDED.ingest_enabled,eshop.bank_sync_health.ingest_enabled),
      polling_enabled=COALESCE(EXCLUDED.polling_enabled,eshop.bank_sync_health.polling_enabled),
      token_present=COALESCE(EXCLUDED.token_present,eshop.bank_sync_health.token_present);
  IF v_connection.mode='email' AND v_connection.state='degraded' AND p_error IS NULL AND p_ingest_enabled IS TRUE THEN
    UPDATE eshop.bank_sync_connections SET state='connected' WHERE id=p_connection_id;
  END IF;
  v_code:=CASE WHEN v_connection.state IN ('connected','degraded') THEN public.bank_sync_problem(p_connection_id) END;
  UPDATE eshop.bank_sync_health SET warning_code=v_code,
    warning_since=CASE WHEN v_code IS NULL THEN NULL ELSE COALESCE(warning_since,now()) END,
    incident_id=CASE WHEN v_code IS NULL THEN NULL ELSE COALESCE(incident_id,gen_random_uuid()) END,
    notified_at=CASE WHEN v_code IS NULL THEN NULL ELSE notified_at END WHERE connection_id=p_connection_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.record_client_sync_commit_v1(p_occasion bigint, p_source text, p_change_class text, p_items jsonb, p_public_components text[], p_private_impacts jsonb DEFAULT '[]'::jsonb, p_dirty_keys jsonb DEFAULT '[]'::jsonb, p_actor_kind text DEFAULT 'user'::text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_commit public.client_commits%ROWTYPE;
  v_component text;
  v_revision bigint;
  v_item jsonb;
  v_index integer := 0;
  v_user uuid := auth.uid();
  v_dirty jsonb;
  v_private jsonb;
  v_private_user uuid;
BEGIN
  IF p_actor_kind='user' THEN
    IF v_user IS NULL OR NOT EXISTS (SELECT 1 FROM public.user_info ui
      WHERE ui.id=v_user) THEN
      RAISE insufficient_privilege USING MESSAGE='authenticated actor required';
    END IF;
  ELSIF p_actor_kind IN ('service','break_glass','system') THEN
    PERFORM public.require_client_sync_service_role_v1();
    IF p_actor_kind='break_glass' AND nullif(btrim(p_reason),'') IS NULL THEN
      RAISE EXCEPTION 'break-glass reason is required';
    END IF;
  ELSE
    IF p_actor_kind<>'unknown' OR v_user IS NOT NULL THEN
      RAISE insufficient_privilege USING MESSAGE='unsupported commit actor';
    END IF;
  END IF;
  INSERT INTO public.client_commits
    (occasion, actor_id, actor_display, actor_kind, source, change_class,
     reason)
  SELECT p_occasion, v_user,
    nullif(concat_ws(' ', ui.name, ui.surname), ''), p_actor_kind, p_source,
    p_change_class, p_reason
  FROM (SELECT 1) seed LEFT JOIN public.user_info ui ON ui.id = v_user
  RETURNING * INTO v_commit;

  FOR v_item IN SELECT value FROM jsonb_array_elements(COALESCE(p_items, '[]')) LOOP
    INSERT INTO public.client_commit_items
      (commit_id, item_index, entity_type, entity_id, operation, safe_label, changed_fields)
    VALUES (v_commit.commit_id, v_index, v_item->>'entityType', v_item->>'entityId',
      v_item->>'operation', left(v_item->>'safeLabel', 240),
      ARRAY(SELECT jsonb_array_elements_text(COALESCE(v_item->'changedFields','[]'))));
    v_index := v_index + 1;
  END LOOP;

  FOREACH v_component IN ARRAY COALESCE(p_public_components, '{}') LOOP
    INSERT INTO public.client_sync_scopes(component, scope_type, scope_id, source_revision)
    VALUES (v_component, 'occasion', p_occasion, 1)
    ON CONFLICT (component, scope_type, scope_id) DO UPDATE
      SET source_revision = public.client_sync_scopes.source_revision + 1,
          updated_at = now()
    RETURNING source_revision INTO v_revision;
    INSERT INTO public.client_commit_components
      (commit_id, component, scope_type, scope_id, user_id, resulting_revision)
    VALUES (v_commit.commit_id, v_component, 'occasion', p_occasion,
      NULL, v_revision);
    IF v_component<>'live_public' OR NOT EXISTS (
      SELECT 1 FROM jsonb_array_elements(COALESCE(p_dirty_keys,'[]')) impact
      WHERE impact->>'component'=v_component) THEN
      INSERT INTO public.client_projection_dirty_keys
        (component, scope_type, scope_id, entity_id, source_revision)
      VALUES (v_component, 'occasion', p_occasion, 0, v_revision)
      ON CONFLICT (component, scope_type, scope_id, entity_id) DO UPDATE
        SET source_revision = EXCLUDED.source_revision, dirty_since = now(),
            claimed_at = NULL, claim_token = NULL;
    END IF;
  END LOOP;

  FOR v_private IN SELECT DISTINCT value
    FROM jsonb_array_elements(COALESCE(p_private_impacts,'[]')) LOOP
      v_component:=v_private->>'component';
      v_private_user:=(v_private->>'userId')::uuid;
      IF v_component NOT LIKE 'private\_%' OR NOT EXISTS (
        SELECT 1 FROM public.occasion_users ou
        WHERE ou.occasion=p_occasion AND ou."user"=v_private_user) THEN
        RAISE invalid_parameter_value USING MESSAGE='invalid private sync impact';
      END IF;
      INSERT INTO public.client_sync_private_scopes(component, occasion, user_id, source_revision)
      VALUES (v_component, p_occasion, v_private_user, 1)
      ON CONFLICT (component, occasion, user_id) DO UPDATE
        SET source_revision = public.client_sync_private_scopes.source_revision + 1,
            updated_at = now()
      RETURNING source_revision INTO v_revision;
      INSERT INTO public.client_commit_components
        (commit_id, component, scope_type, scope_id, user_id, resulting_revision)
      VALUES (v_commit.commit_id, v_component, 'occasion', p_occasion,
        v_private_user, v_revision);
  END LOOP;

  FOR v_dirty IN SELECT value FROM jsonb_array_elements(COALESCE(p_dirty_keys, '[]')) LOOP
    INSERT INTO public.client_projection_dirty_keys
      (component, scope_type, scope_id, entity_id, source_revision)
    VALUES (v_dirty->>'component', 'occasion', p_occasion,
      (v_dirty->>'entityId')::bigint, COALESCE((v_dirty->>'revision')::bigint,
        (SELECT s.source_revision FROM public.client_sync_scopes s
         WHERE s.component=v_dirty->>'component' AND s.scope_type='occasion'
           AND s.scope_id=p_occasion),0))
    ON CONFLICT (component, scope_type, scope_id, entity_id) DO UPDATE
      SET source_revision = GREATEST(public.client_projection_dirty_keys.source_revision,
          EXCLUDED.source_revision), dirty_since = now(), claimed_at = NULL, claim_token = NULL;
  END LOOP;

  RETURN jsonb_build_object('commitId', v_commit.commit_id,
    'occurredAt', v_commit.occurred_at);
END;
$function$

CREATE OR REPLACE FUNCTION public.record_email_events(p_events jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
BEGIN
 PERFORM public.require_service_role();
 PERFORM 1 FROM public.email_capacity FOR UPDATE;
 IF jsonb_typeof(p_events)<>'array' OR jsonb_array_length(p_events)>100 THEN RAISE EXCEPTION 'invalid_event_batch'; END IF;
 INSERT INTO public.email_delivery_events(event_key,provider_message_id,attempt_id,recipient,event_type,provider_time,hard_bounce,invalid_recipient)
 SELECT e->>'key',e->>'provider_id',(e->>'attempt_id')::uuid,e->>'recipient',e->>'type',(e->>'time')::timestamptz,coalesce((e->>'hard_bounce')::boolean,false),coalesce((e->>'invalid_recipient')::boolean,false)
 FROM jsonb_array_elements(p_events) e ON CONFLICT(event_key) DO NOTHING;
 PERFORM public.reconcile_email_events();
END $function$

CREATE OR REPLACE FUNCTION public.recover_email_delivery()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
BEGIN
 PERFORM public.require_service_role();
 PERFORM 1 FROM public.email_capacity FOR UPDATE;
 PERFORM public.recover_email_leases();
 UPDATE public.email_messages SET workflow_state='expired',lease_token=NULL,lease_until=NULL
 WHERE expires_at<now() AND workflow_state IN ('pending','retry_wait','blocked','preparing');
 -- Erase sensitive body after terminal state/expiry; retain correlation and dedupe tombstones.
 UPDATE public.email_messages SET prepared=NULL,data=data-'ciphertext'
 WHERE message_kind IN ('registration','sign_in','reset_password','google_mailbox','gotrue','deletion_confirm','deletion_complete')
 AND (workflow_state IN ('accepted','dead','cancelled','suppressed','expired') OR expires_at<now()) AND prepared IS NOT NULL;
 UPDATE public.email_messages SET prepared=NULL,data=jsonb_build_object('command_id',data->'command_id')
 WHERE created_at<now()-interval '30 days' AND workflow_state IN ('accepted','dead','cancelled','suppressed','expired') AND prepared IS NOT NULL;
 DELETE FROM public.email_confirmation_receipts WHERE expires_at<now();
 DELETE FROM public.email_delivery_events WHERE received_at<now()-interval '90 days';
 PERFORM public.apply_email_post_actions();
 PERFORM public.reconcile_email_events();
 PERFORM public.wake_email_worker();
END $function$

CREATE OR REPLACE FUNCTION public.recover_email_leases()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
BEGIN
 PERFORM public.require_service_role();
 PERFORM 1 FROM public.email_capacity FOR UPDATE;
 -- Sending expiry is ambiguous, preparation expiry is safe to recover.
 UPDATE public.email_attempts a SET state='unknown',finished_at=now(),error_code='lease_expired'
 FROM public.email_messages m WHERE m.message_id=a.message_id AND m.workflow_state='sending' AND m.lease_until<now() AND a.state='sending';
 UPDATE public.email_messages SET workflow_state='unknown',last_error='lease_expired' WHERE workflow_state='sending' AND lease_until<now();
 UPDATE public.email_attempts a SET state='cancelled',finished_at=now() FROM public.email_messages m
 WHERE a.message_id=m.message_id AND a.lease_token=m.lease_token AND a.state='preparing' AND m.lease_until<now();
 UPDATE public.email_messages SET workflow_state='pending',lease_token=NULL,lease_until=NULL WHERE workflow_state='preparing' AND lease_until<now();

END $function$

CREATE OR REPLACE FUNCTION public.refresh_abuse_unit_evidence_v1()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE u record; cap bigint; n integer:=0; verified bigint;
BEGIN
 PERFORM public.require_service_role();
 SELECT hard_cap/greatest(growth_increment,1)+1 INTO cap FROM public.abuse_policy_rules WHERE rule_key='email.ordinary.unit.day';
 IF cap IS NULL THEN RAISE configuration_limit_exceeded USING MESSAGE='abuse_policy_missing'; END IF;
 FOR u IN SELECT units.id FROM public.units LEFT JOIN public.abuse_unit_evidence e ON e.unit=units.id
  WHERE e.measured_at IS NULL OR e.measured_at<statement_timestamp()-interval '5 minutes'
  ORDER BY e.measured_at NULLS FIRST,units.id LIMIT 20 LOOP
  IF NOT pg_try_advisory_xact_lock(hashtextextended('abuse-growth:'||u.id,0)) THEN CONTINUE; END IF;
  SELECT count(*) INTO verified FROM (
   SELECT ord.id FROM eshop.orders ord JOIN public.occasions occ ON occ.id=ord.occasion
   WHERE occ.unit=u.id AND ord.state IN ('paid','sent') AND ord.price>0
   AND (SELECT coalesce(sum(t.amount),0) FROM eshop.transactions t
    WHERE t.payment_info=ord.payment_info AND t.currency=ord.currency_code
     AND EXISTS(SELECT 1 FROM eshop.bank_transaction_identities i WHERE i.transaction_id=t.id))>=ord.price LIMIT cap
  ) proof;
  INSERT INTO public.abuse_unit_evidence VALUES(u.id,verified,statement_timestamp())
   ON CONFLICT(unit) DO UPDATE SET verified_orders=excluded.verified_orders,measured_at=excluded.measured_at;
  n:=n+1;
 END LOOP;
 RETURN n;
END $function$

CREATE OR REPLACE FUNCTION public.refresh_email_quota(p_account text, p_region text, p_rate numeric, p_daily numeric, p_used numeric)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE c public.email_capacity;
BEGIN
 PERFORM public.require_service_role();
 SELECT * INTO c FROM public.email_capacity FOR UPDATE;
 IF c.account_id IS DISTINCT FROM p_account OR c.region IS DISTINCT FROM p_region OR p_rate IS NULL OR p_daily IS NULL OR p_used IS NULL OR p_rate<=0 OR p_daily<=0 OR p_used<0 THEN RAISE EXCEPTION 'email_quota_identity_mismatch'; END IF;
 UPDATE public.email_capacity SET max_rate=p_rate,daily_quota=p_daily,provider_sent_24h=p_used,quota_at=now(),wake_error=NULL,rate_factor=least(1,rate_factor+0.05) WHERE singleton;
END $function$

CREATE OR REPLACE FUNCTION public.register_blueprint_image_asset(p_occasion bigint, p_project text, p_asset jsonb, p_issued_at bigint, p_proof text, p_unit bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE secret_value text; message text; expected text; org bigint; image_id bigint; existing public.blueprint_image_assets; ext text; expected_url text;
BEGIN
 IF public.get_blueprint_image_upload_access(p_occasion,p_project,p_unit) IS NOT TRUE THEN RAISE insufficient_privilege USING MESSAGE='blueprint image editor required'; END IF;
 IF p_occasion IS NOT NULL THEN PERFORM public.check_occasion_writable(p_occasion); END IF;
 IF jsonb_typeof(p_asset) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(p_asset))<>8
  OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_asset) key WHERE key NOT IN ('assetRef','hash','url','width','height','mimeType','byteLength','state')) THEN
  RAISE invalid_parameter_value USING MESSAGE='BLUEPRINT_INVALID_IMAGE_MANIFEST'; END IF;
 IF p_asset ? 'reserved' OR p_asset->>'state' IS DISTINCT FROM 'ready' OR coalesce(p_asset->>'hash','') !~ '^[a-f0-9]{64}$'
  OR p_asset->>'assetRef' IS DISTINCT FROM 'image:'||(p_asset->>'hash')
  OR jsonb_typeof(p_asset->'width') IS DISTINCT FROM 'number' OR jsonb_typeof(p_asset->'height') IS DISTINCT FROM 'number' OR jsonb_typeof(p_asset->'byteLength') IS DISTINCT FROM 'number'
  OR (p_asset->>'width')::numeric<>trunc((p_asset->>'width')::numeric) OR (p_asset->>'height')::numeric<>trunc((p_asset->>'height')::numeric)
  OR (p_asset->>'byteLength')::numeric<>trunc((p_asset->>'byteLength')::numeric)
  OR (p_asset->>'width')::numeric NOT BETWEEN 1 AND 3000 OR (p_asset->>'height')::numeric NOT BETWEEN 1 AND 3000
  OR (p_asset->>'byteLength')::numeric NOT BETWEEN 1 AND 819200 OR p_asset->>'mimeType' NOT IN ('image/png','image/jpeg','image/webp') THEN
  RAISE invalid_parameter_value USING MESSAGE='BLUEPRINT_INVALID_IMAGE_MANIFEST'; END IF;
 ext:=CASE p_asset->>'mimeType' WHEN 'image/jpeg' THEN 'jpg' WHEN 'image/png' THEN 'png' WHEN 'image/webp' THEN 'webp' END;
 expected_url:='https://'||CASE WHEN p_project='a' THEN 'a.img.festapp.net' ELSE 'img.festapp.net' END||'/images/'||CASE WHEN p_unit IS NULL THEN p_occasion::text ELSE 'unit-'||p_unit::text END||'/blueprint/'||(p_asset->>'hash')||'.'||ext;
 IF p_asset->>'url' IS DISTINCT FROM expected_url OR p_issued_at IS NULL OR p_issued_at<extract(epoch FROM statement_timestamp())-600 OR p_issued_at>extract(epoch FROM statement_timestamp())+30
  OR coalesce(p_proof,'') !~ '^[a-f0-9]{64}$' THEN RAISE insufficient_privilege USING MESSAGE='BLUEPRINT_IMAGE_ATTESTATION_REJECTED'; END IF;
 SELECT decrypted_secret INTO secret_value FROM vault.decrypted_secrets WHERE name='blueprint_image_processing_v1';
 IF secret_value IS NULL OR length(secret_value)<32 THEN RAISE configuration_limit_exceeded USING MESSAGE='BLUEPRINT_IMAGE_PROCESSOR_NOT_CONFIGURED'; END IF;
 message:=concat_ws(E'\n','blueprint-image-v1',CASE WHEN p_unit IS NULL THEN 'occasion:'||p_occasion::text ELSE 'unit:'||p_unit::text END,p_project,p_asset->>'assetRef',p_asset->>'hash',p_asset->>'url',p_asset->>'width',p_asset->>'height',p_asset->>'mimeType',p_asset->>'byteLength',p_issued_at::text);
 expected:=encode(extensions.hmac(convert_to(message,'UTF8'),convert_to(secret_value,'UTF8'),'sha256'),'hex');
 IF extensions.digest(convert_to(p_proof,'UTF8'),'sha256')<>extensions.digest(convert_to(expected,'UTF8'),'sha256') THEN RAISE insufficient_privilege USING MESSAGE='BLUEPRINT_IMAGE_ATTESTATION_REJECTED'; END IF;
 IF p_unit IS NULL THEN
  PERFORM public.lock_blueprint_scope_internal(ARRAY[p_occasion]);
  SELECT organization INTO org FROM public.occasions WHERE id=p_occasion;
 ELSE
  PERFORM pg_advisory_xact_lock(hashtextextended('blueprint-image-unit:'||p_unit,0));
  SELECT organization INTO org FROM public.units WHERE id=p_unit;
 END IF;
 SELECT * INTO existing FROM public.blueprint_image_assets WHERE (occasion=p_occasion OR unit=p_unit) AND asset_ref=p_asset->>'assetRef';
 IF FOUND THEN
  IF existing.organization<>org OR existing.hash<>p_asset->>'hash' OR existing.url<>p_asset->>'url' OR existing.width<>(p_asset->>'width')::integer OR existing.height<>(p_asset->>'height')::integer OR existing.mime_type<>p_asset->>'mimeType' OR existing.byte_length<>(p_asset->>'byteLength')::integer THEN RAISE check_violation USING MESSAGE='BLUEPRINT_IMAGE_IMMUTABLE'; END IF;
  RETURN p_asset;
 END IF;
 image_id:=public.add_image_record_internal(p_asset->>'url',p_occasion,p_unit);
 INSERT INTO public.blueprint_image_assets(occasion,unit,organization,asset_ref,hash,url,width,height,mime_type,byte_length,image)
 VALUES(p_occasion,p_unit,org,p_asset->>'assetRef',p_asset->>'hash',p_asset->>'url',(p_asset->>'width')::integer,(p_asset->>'height')::integer,p_asset->>'mimeType',(p_asset->>'byteLength')::integer,image_id);
 RETURN p_asset;
END $function$

CREATE OR REPLACE FUNCTION public.register_blueprint_text_resources(p_occasion bigint, p_setup_draft uuid, p_resources jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE scope text; item record; old jsonb; kind text; collection text;
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE insufficient_privilege USING MESSAGE='text service required'; END IF;
 IF (p_occasion IS NULL)=(p_setup_draft IS NULL) OR p_resources->>'protocol' IS DISTINCT FROM '2'
 OR jsonb_typeof(p_resources->'textLayouts') IS DISTINCT FROM 'object' OR jsonb_typeof(p_resources->'numberSymbols') IS DISTINCT FROM 'object'
 OR octet_length(p_resources::text)>16777216 THEN RAISE invalid_parameter_value USING MESSAGE='BLUEPRINT_INVALID_TEXT_RESOURCES'; END IF;
 scope:=CASE WHEN p_occasion IS NOT NULL THEN 'occasion:'||p_occasion::text ELSE 'setup:'||p_setup_draft::text END;
 PERFORM pg_advisory_xact_lock(hashtextextended('blueprint-text:'||scope,0));
 FOREACH collection IN ARRAY ARRAY['textLayouts','numberSymbols'] LOOP
  kind:=CASE collection WHEN 'textLayouts' THEN 'text' ELSE 'number' END;
  FOR item IN SELECT key,value FROM jsonb_each(p_resources->collection) LOOP
   IF jsonb_typeof(item.value) IS DISTINCT FROM 'object' OR item.value->>'id' IS NULL
    OR (kind='text' AND (item.key IS DISTINCT FROM item.value->>'id' OR item.key !~ '^layout-text:[a-f0-9]{64}$' OR item.value#>>'{descriptor,layoutResourceProtocol}' IS DISTINCT FROM '2'))
    OR (kind='number' AND (item.key IS DISTINCT FROM item.value->>'fontFaceId' OR item.value->>'id' !~ '^layout-number:[a-f0-9]{64}$'))
    THEN RAISE invalid_parameter_value USING MESSAGE='BLUEPRINT_INVALID_TEXT_RESOURCE'; END IF;
   SELECT payload INTO old FROM public.blueprint_text_resources WHERE scope_key=scope AND resource_id=item.value->>'id';
   IF FOUND THEN
    IF old IS DISTINCT FROM item.value THEN RAISE check_violation USING MESSAGE='BLUEPRINT_TEXT_RESOURCE_IMMUTABLE'; END IF;
   ELSE
    INSERT INTO public.blueprint_text_resources(scope_key,occasion,setup_draft,resource_id,resource_kind,payload)
     VALUES(scope,p_occasion,p_setup_draft,item.value->>'id',kind,item.value);
   END IF;
  END LOOP;
 END LOOP;
END $function$

CREATE OR REPLACE FUNCTION public.release_blueprint_holds_client_sync_v1(p_spots bigint[], p_command_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE actor uuid:=auth.uid(); occ bigint; ids bigint[]; bp bigint; started jsonb; users uuid[]; fingerprint text;
BEGIN
 IF actor IS NULL OR coalesce(cardinality(p_spots),0)=0 OR cardinality(p_spots)>256 THEN
  RAISE insufficient_privilege USING MESSAGE='order editor required'; END IF;
 SELECT min(b.occasion),min(s.blueprint) INTO occ,bp FROM eshop.spots s JOIN eshop.blueprints b ON b.id=s.blueprint WHERE s.id=ANY(p_spots);
 IF occ IS NULL OR public.get_is_editor_order_on_occasion(occ) IS NOT TRUE OR
  (SELECT count(*) FROM eshop.spots WHERE id=ANY(p_spots) AND blueprint=bp) <>
  cardinality(ARRAY(SELECT DISTINCT x FROM unnest(p_spots) x)) THEN
  RAISE insufficient_privilege USING MESSAGE='order editor required'; END IF;
 PERFORM public.lock_blueprint_scope_internal(ARRAY[occ]);
 PERFORM public.check_occasion_writable(occ);
 fingerprint:=encode(extensions.digest(convert_to(jsonb_build_object('spots',p_spots)::text,'UTF8'),'sha256'),'hex');
 started:=public.begin_client_mutation_v1(p_command_id,'inventory.blueprint.holds.release',occ,actor,fingerprint);
 IF started->>'disposition'='replay' THEN RETURN started->'response'; END IF;
 SELECT array_agg(DISTINCT member ORDER BY member) INTO ids FROM unnest(p_spots) requested
 CROSS JOIN LATERAL unnest(public.blueprint_selection_unit_spots_internal(requested)) member;
 PERFORM 1 FROM eshop.spots WHERE id=ANY(ids) ORDER BY id FOR UPDATE;
 IF EXISTS(SELECT 1 FROM eshop.spots WHERE id=ANY(ids) AND (blueprint IS DISTINCT FROM bp OR order_product_ticket IS NOT NULL)) THEN
  RAISE check_violation USING MESSAGE='Spot is already ordered'; END IF;
 SELECT coalesce(array_agg(ou."user"),'{}'::uuid[]) INTO users FROM public.occasion_users ou WHERE ou.occasion=occ;
 UPDATE eshop.spots SET secret=NULL,secret_expiration_time=NULL,updated_at=now()
 WHERE id=ANY(ids) AND order_product_ticket IS NULL;
 RETURN public.complete_profile_inventory_membership_mutation_v1(p_command_id,occ,'inventory.blueprint.holds.release',
  jsonb_build_array(jsonb_build_object('entityType','spot','entityId',NULL,'operation','update','safeLabel','Temporary reservation released','changedFields',jsonb_build_array('reservation'))),
  users,jsonb_build_object('spotIds',to_jsonb(ids)));
END $function$

CREATE OR REPLACE FUNCTION public.release_client_projection_claims_v1(p_claim_tokens uuid[])
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_released integer;
BEGIN
  PERFORM public.require_client_sync_service_role_v1();
  IF p_claim_tokens IS NULL OR cardinality(p_claim_tokens)=0
     OR array_position(p_claim_tokens,NULL) IS NOT NULL THEN
    RAISE invalid_parameter_value USING MESSAGE='non-empty claim tokens required';
  END IF;
  UPDATE public.client_projection_dirty_keys d
  SET claimed_at=NULL,claim_token=NULL
  WHERE d.claim_token=ANY(p_claim_tokens);
  GET DIAGNOSTICS v_released=ROW_COUNT;
  RETURN v_released;
END;
$function$

CREATE OR REPLACE FUNCTION public.remap_blueprint_layout_ids_internal(p_value jsonb, p_ids jsonb, p_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE result jsonb;
BEGIN
 IF jsonb_typeof(p_value)='object' THEN
  SELECT coalesce(jsonb_object_agg(item.key,public.remap_blueprint_layout_ids_internal(item.value,p_ids,item.key)),'{}') INTO result FROM jsonb_each(p_value) item;
  RETURN result;
 ELSIF jsonb_typeof(p_value)='array' THEN
  SELECT coalesce(jsonb_agg(public.remap_blueprint_layout_ids_internal(item.value,p_ids,p_key) ORDER BY item.position),'[]') INTO result FROM jsonb_array_elements(p_value) WITH ORDINALITY item(value,position);
  RETURN result;
 ELSIF jsonb_typeof(p_value)='string' AND p_key IN ('id','parentId','rootId','assemblyId','seatId','targetId','nodeIds') THEN
  RETURN coalesce(p_ids->(p_value#>>'{}'),p_value);
 END IF;
 RETURN p_value;
END $function$

CREATE OR REPLACE FUNCTION public.remove_image_records(p_links text[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_row record; v_occasion bigint;
BEGIN
  IF COALESCE(array_length(p_links,1),0)=0 THEN RETURN; END IF;
  FOR v_row IN SELECT DISTINCT i.occasion,i.unit FROM public.images i
    WHERE i.link=ANY(p_links)
  LOOP
    IF v_row.occasion IS NOT NULL THEN
      IF NOT public.get_is_editor_on_occasion(v_row.occasion)
         AND NOT public.get_is_editor_order_on_occasion(v_row.occasion) THEN
        RAISE insufficient_privilege USING MESSAGE='occasion editor required';
      END IF;
    ELSIF v_row.unit IS NOT NULL AND NOT public.get_is_editor_on_unit(v_row.unit) THEN
      RAISE insufficient_privilege USING MESSAGE='unit editor required';
    END IF;
  END LOOP;

  FOR v_occasion IN SELECT DISTINCT i.occasion FROM public.images i
    WHERE i.link=ANY(p_links) AND i.occasion IS NOT NULL
  LOOP
    DELETE FROM public.images i
      WHERE i.link=ANY(p_links) AND i.occasion=v_occasion;
    PERFORM public.record_client_sync_commit_v1(
      v_occasion,'image.remove','content',jsonb_build_array(jsonb_build_object(
        'entityType','occasion_image','entityId','batch','operation','delete',
        'safeLabel','occasion media','changedFields',jsonb_build_array('link'))),
      ARRAY['occasion_config'],'[]'::jsonb,'[]'::jsonb,'user',NULL);
  END LOOP;

  DELETE FROM public.images i WHERE i.link=ANY(p_links);
END; $function$

CREATE OR REPLACE FUNCTION public.remove_occasion_user_domain_internal_v1(p_occasion bigint, p_user uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE groups bigint[]; impacts jsonb;
BEGIN
 PERFORM public.lock_activity_aggregate_internal_v1(p_occasion);
 SELECT COALESCE(array_agg(DISTINCT g.id),'{}') INTO groups FROM public.user_group_info g LEFT JOIN public.user_groups ug ON g.id=ug."group" WHERE g.occasion=p_occasion AND (ug."user"=p_user OR g.leader=p_user);
 impacts:=public.group_profile_impacts_internal_v1(p_occasion,ARRAY(SELECT "user" FROM public.user_groups WHERE "group"=ANY(groups))||ARRAY[p_user]);
 impacts:=(SELECT COALESCE(jsonb_agg(x),'[]') FROM jsonb_array_elements(impacts) x WHERE x->>'userId'<>p_user::text)||public.remove_user_activity_internal_v1(p_occasion,ARRAY[p_user]);
 UPDATE public.news SET created_by=NULL WHERE created_by=p_user AND occasion=p_occasion;
 UPDATE public.user_group_info SET leader=NULL WHERE occasion=p_occasion AND leader=p_user;
 DELETE FROM public.user_groups WHERE "user"=p_user AND "group"=ANY(groups);
 INSERT INTO public.client_aggregate_versions(aggregate_type,scope_type,scope_id,aggregate_id,version)
 SELECT 'user_group','occasion',p_occasion,id::text,1 FROM unnest(groups) id
 ON CONFLICT(aggregate_type,scope_type,scope_id,aggregate_id) DO UPDATE
 SET version=public.client_aggregate_versions.version+1,updated_at=clock_timestamp();
 DELETE FROM public.event_users WHERE "user"=p_user AND event IN(SELECT id FROM public.events WHERE occasion=p_occasion);
 DELETE FROM public.event_users_saved WHERE "user"=p_user AND event IN(SELECT id FROM public.events WHERE occasion=p_occasion);
 DELETE FROM public.user_news WHERE "user"=p_user AND occasion=p_occasion;
 DELETE FROM public.occasion_users WHERE "user"=p_user AND occasion=p_occasion;
 DELETE FROM public.client_sync_private_scopes WHERE occasion=p_occasion AND user_id=p_user;
 DELETE FROM public.client_aggregate_versions WHERE aggregate_type='occasion_user' AND scope_type='occasion' AND scope_id=p_occasion AND aggregate_id=p_user::text;
 RETURN impacts;
END $function$

CREATE OR REPLACE FUNCTION public.remove_transaction_from_payment_info_ws(p_transaction_id bigint, p_payment_info_id bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_bank_account_id bigint;
  v_occasion_id bigint;
BEGIN
  SELECT pi.bank_account, o.occasion INTO v_bank_account_id, v_occasion_id
  FROM eshop.payment_info pi
  JOIN eshop.orders o ON o.payment_info = pi.id
  WHERE pi.id = p_payment_info_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'PAYMENT_INFO_NOT_FOUND'; END IF;
  PERFORM public.check_is_admin_for_bank_account(v_bank_account_id);
  PERFORM public.check_is_editor_order_on_occasion(v_occasion_id);
  IF NOT EXISTS (SELECT 1 FROM eshop.transactions t
    WHERE t.id = p_transaction_id AND t.payment_info = p_payment_info_id) THEN
    RAISE EXCEPTION 'TRANSACTION_PAIRING_MISMATCH';
  END IF;
  PERFORM public.apply_transaction_pairing(
    p_transaction_id, NULL, 'manual_unlink', 'user'
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.remove_user_activity_internal_v1(p_occasion bigint, p_users uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE impacted uuid[]; n int; impacts jsonb;
BEGIN
 PERFORM public.lock_activity_aggregate_internal_v1(p_occasion);
 SELECT ARRAY(SELECT DISTINCT aa."user" FROM public.activity_assignments aa JOIN public.activities a ON a.id=aa.activity_id WHERE a.occasion=p_occasion) INTO impacted;
 DELETE FROM public.activity_assignments aa USING public.activities a WHERE a.id=aa.activity_id AND a.occasion=p_occasion AND aa."user"=ANY(p_users);
 GET DIAGNOSTICS n=ROW_COUNT;
 IF n=0 THEN RETURN '[]'; END IF;
 UPDATE public.client_aggregate_versions SET version=version+1,updated_at=clock_timestamp() WHERE aggregate_type='activities' AND scope_type='occasion' AND scope_id=p_occasion AND aggregate_id=p_occasion::text;
 SELECT COALESCE(jsonb_agg(jsonb_build_object('component','private_activity','userId',id) ORDER BY id),'[]') INTO impacts FROM unnest(impacted) id JOIN public.occasion_users ou ON ou.occasion=p_occasion AND ou."user"=id WHERE NOT id=ANY(p_users);
 RETURN impacts;
END $function$

CREATE OR REPLACE FUNCTION public.replace_activities_graph_internal_v1(p_occasion bigint, p_graph jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE a jsonb; x jsonb; graph jsonb; changed int;
BEGIN
 graph:=public.normalize_activity_graph_internal_v1(p_occasion,p_graph,true);
 DELETE FROM public.activity_assignments aa USING public.activities a WHERE aa.activity_id=a.id AND a.occasion=p_occasion AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(graph) g,LATERAL jsonb_array_elements(g->'assignments') assignment WHERE assignment->>'id'=aa.id::text);
 DELETE FROM public.activities WHERE occasion=p_occasion AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(graph) g WHERE g->>'id'=public.activities.id::text);
 FOR a IN SELECT value FROM jsonb_array_elements(graph) LOOP
  INSERT INTO public.activities(id,title,description,type,unit,occasion,is_hidden,"order",data) VALUES((a->>'id')::uuid,a->>'title',a->>'description',a->>'type',(a->>'unit')::bigint,p_occasion,(a->>'is_hidden')::boolean,(a->>'order')::bigint,a->'data') ON CONFLICT(id) DO UPDATE SET title=excluded.title,description=excluded.description,type=excluded.type,unit=excluded.unit,is_hidden=excluded.is_hidden,"order"=excluded."order",data=excluded.data WHERE public.activities.occasion=p_occasion;
  GET DIAGNOSTICS changed=ROW_COUNT; IF changed<>1 THEN RAISE invalid_parameter_value USING MESSAGE='global activity UUID collision'; END IF;
  FOR x IN SELECT value FROM jsonb_array_elements(a->'assignments') LOOP
   INSERT INTO public.activity_assignments(id,activity_id,"user",start_time,end_time,title,description,data) VALUES((x->>'id')::uuid,(a->>'id')::uuid,(x->>'user')::uuid,(x->>'start_time')::timestamptz,(x->>'end_time')::timestamptz,x->>'title',x->>'description',x->'data') ON CONFLICT(id) DO UPDATE SET activity_id=excluded.activity_id,"user"=excluded."user",start_time=excluded.start_time,end_time=excluded.end_time,title=excluded.title,description=excluded.description,data=excluded.data WHERE EXISTS(SELECT 1 FROM public.activities owner WHERE owner.id=public.activity_assignments.activity_id AND owner.occasion=p_occasion);
   GET DIAGNOSTICS changed=ROW_COUNT; IF changed<>1 THEN RAISE invalid_parameter_value USING MESSAGE='global assignment UUID collision'; END IF;
   DELETE FROM public.activity_assignment_places WHERE assignment_id=(x->>'id')::uuid;
   INSERT INTO public.activity_assignment_places(assignment_id,place_id) SELECT (x->>'id')::uuid,value::bigint FROM jsonb_array_elements_text(x->'linked_place_ids');
   DELETE FROM public.activity_assignment_events WHERE assignment_id=(x->>'id')::uuid;
   INSERT INTO public.activity_assignment_events(assignment_id,event_id) SELECT (x->>'id')::uuid,value::bigint FROM jsonb_array_elements_text(x->'linked_event_ids');
  END LOOP;
 END LOOP;
END $function$

CREATE OR REPLACE FUNCTION public.replace_blueprint_order_client_sync_v1(p_spot_ids bigint[], p_input_data jsonb, p_command_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_occasion bigint; v_begin jsonb; v_hash text;
  v_prepare jsonb; v_result jsonb; v_before_users uuid[];
BEGIN
  PERFORM public.lock_blueprint_scope_internal(ARRAY(SELECT DISTINCT occasion FROM eshop.spots WHERE id=ANY(p_spot_ids)));
  SELECT min(s.occasion) INTO v_occasion FROM eshop.spots s
    WHERE s.id=ANY(p_spot_ids);
  IF v_actor IS NULL OR v_occasion IS NULL OR cardinality(p_spot_ids)=0
    OR (SELECT count(*) FROM eshop.spots s
      WHERE s.id=ANY(p_spot_ids) AND s.occasion=v_occasion)
      <>cardinality(ARRAY(SELECT DISTINCT id FROM unnest(p_spot_ids) id))
    OR NOT public.get_is_editor_order_on_occasion(v_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='order editor required'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'spots',p_spot_ids,'input',p_input_data)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,
    'inventory.order.replace',v_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN public.project_local_payment_reference_order_internal(v_begin->'response'); END IF;
  SELECT COALESCE(array_agg(ou."user"),'{}'::uuid[]) INTO v_before_users
    FROM public.occasion_users ou WHERE ou.occasion=v_occasion;
  BEGIN
    v_prepare:=public.confirm_blueprint_order_change_internal_v1(
      p_spot_ids,p_input_data);
    IF COALESCE((v_prepare->>'success')::boolean,false) IS NOT TRUE THEN
      RAISE check_violation USING MESSAGE='replacement preparation rejected',
        DETAIL=v_prepare::text; END IF;
    v_result:=public.create_ticket_order_internal_v1(v_prepare->'orderDetails');
    IF COALESCE((v_result->>'code')::integer,500)<>200 THEN
      RAISE check_violation USING MESSAGE='replacement order rejected',
        DETAIL=v_result::text; END IF;
  EXCEPTION WHEN check_violation THEN
    RETURN public.complete_client_mutation_outcome_v1(
      p_command_id,'rejected',400,COALESCE(v_result,v_prepare,
        jsonb_build_object('message','order replacement rejected')));
  END;
  PERFORM public.enqueue_ticket_order_confirmation_v1(
    p_command_id,v_occasion,v_result,
    COALESCE(p_input_data->>'lang',v_prepare#>>'{orderDetails,lang}'));
  RETURN public.complete_profile_inventory_membership_mutation_v1(
    p_command_id,v_occasion,'inventory.order.replace',
    jsonb_build_array(jsonb_build_object('entityType','order',
      'entityId',v_result#>>'{order,id}','operation','insert',
      'safeLabel','Blueprint order replacement','changedFields',jsonb_build_array(
        'cancellations','tickets','products','allocations','membership'))),
    v_before_users,v_result);
END; $function$

CREATE OR REPLACE FUNCTION public.replace_group_assignments_client_sync_v1(p_occasion bigint, p_command_id uuid, p_assignments jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_begin jsonb; v_hash text; v_unit bigint;
  v_before jsonb; v_after jsonb; v_changed bigint[];
  v_group_ids bigint[]; v_impacted_users uuid[]; v_private_impacts jsonb;
  v_actor_replacements jsonb:='[]'::jsonb;
BEGIN
 PERFORM public.assert_canonical_mutation_write_release_internal_v1(p_occasion);
  SELECT o.unit INTO v_unit FROM public.occasions o WHERE o.id=p_occasion;
  IF v_actor IS NULL OR NOT (public.get_is_editor_on_occasion(p_occasion)
    OR public.get_is_manager_on_occasion(p_occasion)
    OR public.get_is_admin_on_occasion(p_occasion)
    OR public.get_is_editor_on_unit(v_unit)) THEN
    RAISE insufficient_privilege USING MESSAGE='group import permission required'; END IF;
  IF p_assignments IS NULL OR jsonb_typeof(p_assignments)<>'array'
    OR jsonb_array_length(p_assignments)>10000
    OR octet_length(p_assignments::text)>2097152 THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid group assignments'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object('occasion',p_occasion,
    'assignments',p_assignments)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'profile.groups.import',
    p_occasion,v_actor,v_hash);
  PERFORM public.lock_group_occasion_internal_v1(p_occasion);
  IF NOT (public.get_is_editor_on_occasion(p_occasion) OR public.get_is_manager_on_occasion(p_occasion) OR public.get_is_admin_on_occasion(p_occasion) OR public.get_is_editor_on_unit(v_unit)) THEN RAISE insufficient_privilege USING MESSAGE='group import permission required'; END IF;
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock(p_occasion);
  PERFORM 1 FROM public.user_group_info g WHERE g.occasion=p_occasion
    AND g.type IS NULL ORDER BY g.id FOR UPDATE;
  SELECT COALESCE(array_agg(DISTINCT ug."group"),'{}'::bigint[])
    INTO v_group_ids FROM public.user_groups ug JOIN public.user_group_info g
      ON g.id=ug."group" JOIN jsonb_to_recordset(p_assignments)
      x(user_id uuid,group_title text) ON x.user_id=ug."user"
    WHERE g.occasion=p_occasion AND g.type IS NULL;
  SELECT COALESCE(array_agg(DISTINCT members."user"),'{}'::uuid[])
    INTO v_impacted_users FROM public.user_groups members
    WHERE members."group"=ANY(v_group_ids);
  SELECT COALESCE(jsonb_object_agg(g.id,public.get_user_group_command_data_v1(g.id)-'aggregate_version'),'{}') INTO v_before FROM public.user_group_info g WHERE g.occasion=p_occasion AND g.type IS NULL;
  PERFORM public.import_user_group_assignments_internal_v1(
    p_occasion,p_assignments);
  SELECT COALESCE(jsonb_object_agg(g.id,public.get_user_group_command_data_v1(g.id)-'aggregate_version'),'{}') INTO v_after FROM public.user_group_info g WHERE g.occasion=p_occasion AND g.type IS NULL;
  IF v_before=v_after THEN RETURN public.complete_client_mutation_outcome_v1(p_command_id,'unchanged',200,jsonb_build_object('assignments',jsonb_array_length(p_assignments))); END IF;
  SELECT ARRAY(SELECT key::bigint FROM jsonb_each(v_after) WHERE value IS DISTINCT FROM v_before->key ORDER BY key::bigint) INTO v_changed;
  SELECT ARRAY(SELECT DISTINCT id FROM unnest(v_group_ids||COALESCE((
    SELECT array_agg(ug."group") FROM public.user_groups ug
    JOIN public.user_group_info g ON g.id=ug."group"
    JOIN jsonb_to_recordset(p_assignments) x(user_id uuid,group_title text)
      ON x.user_id=ug."user" WHERE g.occasion=p_occasion AND g.type IS NULL),
    '{}'::bigint[])) id ORDER BY id) INTO v_group_ids;
  SELECT ARRAY(SELECT DISTINCT id FROM unnest(v_impacted_users||COALESCE((
    SELECT array_agg(members."user") FROM public.user_groups members
    WHERE members."group"=ANY(v_group_ids)),'{}'::uuid[])) id ORDER BY id)
    INTO v_impacted_users;
  INSERT INTO public.client_aggregate_versions
    (aggregate_type,scope_type,scope_id,aggregate_id,version)
  SELECT 'user_group','occasion',p_occasion,id::text,1 FROM unnest(v_changed) id
  ON CONFLICT (aggregate_type,scope_type,scope_id,aggregate_id) DO UPDATE
    SET version=public.client_aggregate_versions.version+1,
      updated_at=clock_timestamp();
  v_private_impacts:=public.group_profile_impacts_internal_v1(p_occasion,v_impacted_users);
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(v_private_impacts) x WHERE x->>'userId'=v_actor::text) THEN v_actor_replacements:=jsonb_build_array(
    jsonb_build_object('component','private_profile','userId',v_actor,
      'payload',public.get_private_profile_payload_v1(p_occasion,v_actor))); END IF;
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'profile.groups.import','profile',jsonb_build_array(jsonb_build_object(
      'entityType','user_group_membership','entityId',NULL,'operation','import',
      'safeLabel','Group assignment import','changedFields',jsonb_build_array('memberships'))),
    '{}',v_private_impacts,'[]',jsonb_build_object(
      'assignments',jsonb_array_length(p_assignments)),
    '{}','[]','user',NULL,v_actor_replacements);
END; $function$

CREATE OR REPLACE FUNCTION public.report_cleaning_issue_client_sync_v1(p_place bigint, p_problem_type text, p_note text, p_command_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_occasion bigint; v_begin jsonb; v_hash text;
  v_result jsonb; v_existing bigint; v_has_note boolean;
BEGIN
  SELECT p.occasion INTO v_occasion FROM public.places p WHERE p.id=p_place;
  IF v_actor IS NULL OR v_occasion IS NULL THEN
    RAISE insufficient_privilege USING MESSAGE='signed-in occasion participant required';
  END IF;
  v_has_note:=NULLIF(btrim(COALESCE(p_note,'')),'') IS NOT NULL;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'place',p_place,'problemType',p_problem_type,'note',p_note)::text,'UTF8'),
    'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'cleaning.report',
    v_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  PERFORM 1 FROM public.places p WHERE p.id=p_place FOR UPDATE;
  SELECT cr.id INTO v_existing FROM public.cleaning_reports cr
    WHERE cr.place=p_place AND cr.problem_type=p_problem_type
      AND cr.resolved_at IS NULL ORDER BY cr.created_at LIMIT 1 FOR UPDATE;
  v_result:=public.report_cleaning_issue_internal_v1(p_place,p_problem_type,p_note);
  IF COALESCE((v_result->>'code')::integer,500)<>200 THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',
      COALESCE((v_result->>'code')::integer,400),COALESCE(v_result->'data','{}')||
      jsonb_build_object('message',v_result->>'message')); END IF;
  IF v_existing IS NOT NULL AND NOT v_has_note THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'unchanged',200,
      v_result->'data'); END IF;
  RETURN public.complete_client_mutation_applied_v1(p_command_id,v_occasion,
    'cleaning.report','cleaning',jsonb_build_array(jsonb_build_object(
      'entityType','cleaning_report','entityId',v_result#>>'{data,id}',
      'operation',CASE WHEN v_existing IS NULL THEN 'insert' ELSE 'update' END,
      'safeLabel','Cleaning report','changedFields',CASE WHEN v_existing IS NULL
        THEN jsonb_build_array('place','problemType') ELSE jsonb_build_array('note') END)),
    CASE WHEN v_existing IS NULL THEN ARRAY['live_public'] ELSE '{}'::text[] END,
    '[]',CASE WHEN v_existing IS NULL THEN jsonb_build_array(jsonb_build_object(
      'component','live_public','entityId',p_place)) ELSE '[]'::jsonb END,
    v_result->'data');
END; $function$

CREATE OR REPLACE FUNCTION public.report_cleaning_issue_internal_v1(place_id bigint, problem_type text, note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_user uuid := auth.uid();
  v_note text := NULLIF(btrim(COALESCE(note, '')), '');
  v_place public.places%ROWTYPE;
  v_occasion bigint;
  v_organization bigint;
  v_type_label text;
  v_existing public.cleaning_reports%ROWTYPE;
  v_report public.cleaning_reports%ROWTYPE;
  v_crew jsonb;
  v_notification_deferred boolean:=false;
  v_notification uuid;
  v_policy jsonb; v_new_data jsonb;
BEGIN
  IF v_user IS NULL THEN
    RETURN jsonb_build_object('code', 401, 'message', 'Sign in is required to report a cleaning issue');
  END IF;

  -- Problem types — keep in sync with: cleaning_reports.problem_type CHECK
  -- (database/tables/tables.sql), CleaningStatusHelper (cleaning_status.dart)
  -- and the report dialog (cleaning_report_dialog.dart).
  IF problem_type NOT IN ('paper', 'hygiene', 'contamination') THEN
    RETURN jsonb_build_object('code', 400, 'message', 'Invalid problem type');
  END IF;

  IF char_length(COALESCE(v_note, '')) > 2000 THEN
    RETURN jsonb_build_object('code', 413, 'message', 'Note is too long');
  END IF;

  SELECT * INTO v_place FROM public.places WHERE id = place_id;
  IF NOT FOUND OR v_place.occasion IS NULL THEN
    RETURN jsonb_build_object('code', 404, 'message', 'Toilet not found');
  END IF;

  v_occasion := v_place.occasion;

  IF NOT EXISTS (
    SELECT 1
    FROM public.occasion_users
    WHERE occasion = v_occasion
      AND "user" = v_user
      AND is_approved = true
  ) THEN
    RETURN jsonb_build_object('code', 403, 'message', 'Approved occasion participation is required');
  END IF;

  -- Blocked reporters (anti-spam hard ban) cannot file reports on this occasion.
  -- This is the source of truth; the UI also greys the report action out via the
  -- is_blocked flag returned by get_cleaning_status.
  IF EXISTS (
    SELECT 1 FROM public.occasion_users
    WHERE occasion = v_occasion
      AND "user" = v_user
      AND is_cleaning_blocked = true
  ) THEN
    RETURN jsonb_build_object('code', 403, 'message', 'Reporting has been disabled for your account');
  END IF;

  -- Place must be flagged as a toilet (places.type = 'toilet'). This is set by
  -- the "WC / Úklid" checkbox in the admin Places grid — no place_types catalog
  -- row is required.
  IF v_place.type IS DISTINCT FROM 'toilet' THEN
    RETURN jsonb_build_object('code', 400, 'message', 'Place is not a toilet');
  END IF;

  -- Feature "cleaning" must be enabled on the occasion (occasions.features).
  IF NOT EXISTS (
    SELECT 1
    FROM public.occasions o
    CROSS JOIN LATERAL jsonb_array_elements(COALESCE(o.features, '[]'::jsonb)) feature
    WHERE o.id = v_occasion
      AND feature->>'code' = 'cleaning'
      AND LOWER(COALESCE(feature->>'is_enabled', 'false')) = 'true'
  ) THEN
    RETURN jsonb_build_object('code', 404, 'message', 'Cleaning feature is not enabled for this occasion');
  END IF;

  -- Committed accepted work, including appended duplicate notes, shares one
  -- actor identity. Removing a report cannot replenish its rolling budget.
  BEGIN
    v_policy:=public.abuse_effective_rules_v1('cleaning.report',NULL,NULL);
    PERFORM public.abuse_charge_v1(v_policy,
      jsonb_build_object('actor',v_user),jsonb_build_object('cleaning.note.bytes',octet_length(coalesce(v_note,'')), 'cleaning.report.bytes',0));
  EXCEPTION WHEN SQLSTATE 'PT429' THEN RETURN jsonb_build_object('code',429,'message','Too many reports, please wait a moment'); END;
  PERFORM pg_advisory_xact_lock(hashtextextended('cleaning-report:'||place_id::text||':'||problem_type,0));

  -- Push-notification labels are deliberately Czech-only (the crew is Czech;
  -- localizing push messages is out of scope). Keep the type list in sync — see
  -- the problem_type check above.
  v_type_label := CASE problem_type
    WHEN 'paper'         THEN 'Nedostatek toaletního papíru'
    WHEN 'hygiene'       THEN 'Nedostatek hygienických potřeb'
    WHEN 'contamination' THEN 'Totální znečištění ☣️'
  END;

  -- Dedup: reuse an open report of the same place + type.
  SELECT cr.* INTO v_existing
  FROM public.cleaning_reports cr
  WHERE cr.place = place_id
    AND cr.problem_type = report_cleaning_issue_internal_v1.problem_type
    AND cr.resolved_at IS NULL
  ORDER BY cr.created_at ASC
  LIMIT 1;

  IF FOUND THEN
    IF v_note IS NOT NULL THEN
      v_new_data:=COALESCE(v_existing.data,'{}'::jsonb)||jsonb_build_object('extra_notes',coalesce(v_existing.data->'extra_notes','[]'::jsonb)||to_jsonb(v_note));
      IF octet_length(v_new_data::text)>(SELECT (r->>'base_limit')::bigint FROM jsonb_array_elements(v_policy->'rules') r WHERE r->>'rule_key'='cleaning.report.bytes') THEN
        RETURN jsonb_build_object('code',429,'message','Report note capacity is limited'); END IF;
      UPDATE public.cleaning_reports SET data=v_new_data WHERE id=v_existing.id;
    END IF;
    RETURN jsonb_build_object('code',200,'data',jsonb_build_object('duplicate',true,'id',v_existing.id));
  END IF;

  INSERT INTO public.cleaning_reports (occasion, place, problem_type, note, created_by)
  VALUES (v_occasion, place_id, problem_type, v_note, v_user)
  RETURNING * INTO v_report;

  -- Notify the crew (uuid array of is_cleaning_crew users on this occasion),
  -- excluding anyone who muted cleaning notifications for themselves
  -- (occasion_users.data.cleaning_notifications_off).
  SELECT jsonb_agg("user"::text) INTO v_crew
  FROM public.occasion_users
  WHERE occasion = v_occasion
    AND is_cleaning_crew = true
    AND COALESCE((data->>'cleaning_notifications_off')::boolean, false) = false;

  IF v_crew IS NOT NULL AND jsonb_array_length(v_crew) > 0 THEN
    -- organization comes straight from the occasion row (occasions.organization
    -- is NOT NULL) — no magic fallback needed.
    SELECT organization INTO v_organization FROM public.occasions WHERE id = v_occasion;

    BEGIN
      PERFORM public.charge_notification_intent_v1(v_occasion,v_user,v_crew,v_place.title || ' - ' || v_type_label,COALESCE(v_note,v_type_label));
    INSERT INTO public.log_notifications (occasion, organization, user_id, "to", heading, content, data, abuse_admitted_at)
    VALUES (
      v_occasion,
      v_organization,
      v_user,
      v_crew,
      v_place.title || ' — ' || v_type_label,
      COALESCE(v_note, v_type_label),
      jsonb_build_object('path', 'cleaning'), statement_timestamp()
    ) RETURNING id INTO v_notification;
    PERFORM public.dispatch_log_notification_v1(v_notification);
    EXCEPTION WHEN SQLSTATE 'PT429' THEN v_notification_deferred:=true; END;
  END IF;

  RETURN jsonb_build_object(
    'code', 200,
    'data', jsonb_build_object('duplicate', false, 'id', v_report.id, 'notificationDeferred',v_notification_deferred)
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.reserve_draft_payment_reference(p_payment_info_id bigint, p_variable_symbol bigint, p_command_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE target eshop.orders; pi eshop.payment_info; claim jsonb; result jsonb; policy jsonb; symbol bigint; users uuid[];
BEGIN
 IF auth.uid() IS NULL OR p_command_id IS NULL OR p_variable_symbol IS NULL OR p_variable_symbol NOT BETWEEN 1 AND 9999999999 THEN
  RAISE insufficient_privilege USING MESSAGE='Invalid payment reference command'; END IF;
 SELECT * INTO STRICT target FROM eshop.orders WHERE payment_info=p_payment_info_id;
 PERFORM public.check_is_editor_order_on_occasion(target.occasion);
 PERFORM public.check_occasion_writable(target.occasion);
 claim:=public.begin_client_mutation_v1(p_command_id,'inventory.payment.reference',target.occasion,auth.uid(),
  encode(extensions.digest(jsonb_build_object('payment',p_payment_info_id,'symbol',p_variable_symbol)::text,'sha256'),'hex'));
 IF claim->>'disposition'='replay' THEN RETURN claim->'response'; END IF;
 PERFORM public.lock_order_capacity_scope_internal(ARRAY[target.id]);
 SELECT * INTO STRICT target FROM eshop.orders WHERE id=target.id FOR UPDATE;
 SELECT * INTO STRICT pi FROM eshop.payment_info WHERE id=p_payment_info_id FOR UPDATE;
 IF target.state<>'created' OR pi.variable_symbol IS NOT NULL OR pi.creditor_reference IS NOT NULL
 OR EXISTS(SELECT 1 FROM eshop.transactions WHERE payment_info=pi.id)
 OR EXISTS(SELECT 1 FROM public.email_messages WHERE order_id=target.id) THEN
  RAISE EXCEPTION 'PUBLISHED_PAYMENT_REFERENCE_IMMUTABLE'; END IF;
 policy:=jsonb_build_object('mode','exact','value',p_variable_symbol::text);
 symbol:=public.reserve_payment_reference_internal(pi.id,target.form,'manual:'||p_command_id,policy,
  encode(extensions.digest(jsonb_build_object('payment',pi.id,'symbol',p_variable_symbol)::text,'sha256'),'hex'));
 UPDATE eshop.payment_info SET variable_symbol=symbol,
 creditor_reference=CASE WHEN upper(trim(currency_code))='EUR' THEN public.generate_creditor_reference(symbol) ELSE NULL END WHERE id=pi.id;
 SELECT coalesce(array_agg(ou."user"),'{}') INTO users FROM public.occasion_users ou WHERE ou.occasion=target.occasion;
 RETURN public.complete_profile_inventory_membership_mutation_v1(p_command_id,target.occasion,'inventory.payment.reference',
  jsonb_build_array(jsonb_build_object('entityType','order','entityId',target.id,'operation','update','safeLabel','Payment reference',
  'changedFields',jsonb_build_array('payment_info'))),users,jsonb_build_object('code',200,'variable_symbol',symbol));
END $function$

CREATE OR REPLACE FUNCTION public.reserve_order_payment_reference_internal(p_payment bigint, p_form bigint)
 RETURNS bigint
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE cfg jsonb; policy jsonb;
BEGIN
 SELECT coalesce(data->'variable_symbol','{}') INTO STRICT cfg FROM public.forms WHERE id=p_form;
 IF coalesce(cfg->>'type','random')='sequence' THEN
  IF coalesce(cfg->>'starting_number','') !~ '^[0-9]{1,10}$' OR (cfg->>'starting_number')::bigint<1 THEN RAISE EXCEPTION 'PAYMENT_REFERENCE_POLICY_INVALID'; END IF;
  policy:=jsonb_build_object('mode','sequence','from',cfg->>'starting_number');
 ELSIF coalesce(cfg->>'type','random')='random' THEN
  policy:=jsonb_build_object('mode','random','preferred_digits',coalesce(cfg->'preferred_digits','4'), 'max_digits',coalesce(cfg->'max_digits','10'));
 ELSE RAISE EXCEPTION 'PAYMENT_REFERENCE_POLICY_INVALID'; END IF;
 RETURN public.reserve_payment_reference_internal(p_payment,p_form,'payment:'||p_payment,policy,
  encode(extensions.digest(jsonb_build_object('payment',p_payment,'form',p_form,'policy',policy)::text,'sha256'),'hex'));
END $function$

CREATE OR REPLACE FUNCTION public.reserve_payment_reference_internal(p_payment bigint, p_form bigint, p_source text, p_policy jsonb, p_payload_sha256 text)
 RETURNS bigint
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE pi eshop.payment_info; account text; ns eshop.payment_reference_namespaces; previous eshop.payment_reference_reservations;
 phase text; mode text:=p_policy->>'mode'; value bigint; floor bigint; cursor bigint; digits integer; preferred integer; maximum integer; attempt integer;
 high bigint; normalized jsonb;
BEGIN
 SELECT s.phase INTO phase FROM eshop.payment_reference_scopes s JOIN public.occasions o ON o.organization=s.organization_id
 JOIN public.forms f ON f.occasion=o.id WHERE f.id=p_form;
 IF phase IS DISTINCT FROM 'active' THEN RAISE EXCEPTION 'PAYMENT_REFERENCE_SCOPE_NOT_ACTIVE'; END IF;
 PERFORM public.check_occasion_writable((SELECT occasion FROM public.forms WHERE id=p_form));
 IF p_source IS NULL OR length(p_source) NOT BETWEEN 1 AND 255 OR p_payload_sha256 IS NULL OR p_payload_sha256 !~ '^[a-f0-9]{64}$'
 OR p_policy IS NULL OR jsonb_typeof(p_policy)<>'object' THEN RAISE EXCEPTION 'PAYMENT_REFERENCE_POLICY_INVALID'; END IF;
 IF mode='exact' THEN
  IF (p_policy-'mode'-'value')<>'{}'::jsonb OR jsonb_typeof(p_policy->'value') IS DISTINCT FROM 'string' OR coalesce(p_policy->>'value','') !~ '^[0-9]{1,10}$' THEN RAISE EXCEPTION 'PAYMENT_REFERENCE_POLICY_INVALID'; END IF;
  value:=(p_policy->>'value')::bigint;
  IF value=0 THEN RAISE EXCEPTION 'PAYMENT_REFERENCE_POLICY_INVALID'; END IF;
  normalized:=jsonb_build_object('mode',mode,'value',value::text);
 ELSIF mode='sequence' THEN
  IF (p_policy-'mode'-'from')<>'{}'::jsonb OR jsonb_typeof(p_policy->'from') IS DISTINCT FROM 'string' OR coalesce(p_policy->>'from','') !~ '^[0-9]{1,10}$'
   OR (p_policy->>'from')::bigint<1 THEN RAISE EXCEPTION 'PAYMENT_REFERENCE_POLICY_INVALID'; END IF;
  normalized:=jsonb_build_object('mode',mode,'from',((p_policy->>'from')::bigint)::text);
 ELSIF mode='random' THEN
  IF (p_policy-'mode'-'preferred_digits'-'max_digits')<>'{}'::jsonb OR jsonb_typeof(p_policy->'preferred_digits') IS DISTINCT FROM 'number'
   OR (p_policy ? 'max_digits' AND jsonb_typeof(p_policy->'max_digits') IS DISTINCT FROM 'number')
   OR coalesce(p_policy->>'preferred_digits','') !~ '^[0-9]{1,2}$' OR coalesce(p_policy->>'max_digits','10') !~ '^[0-9]{1,2}$' THEN RAISE EXCEPTION 'PAYMENT_REFERENCE_POLICY_INVALID'; END IF;
  digits:=(p_policy->>'preferred_digits')::integer;maximum:=coalesce((p_policy->>'max_digits')::integer,10);
  IF digits NOT BETWEEN 1 AND 10 OR maximum NOT BETWEEN digits AND 10 THEN RAISE EXCEPTION 'PAYMENT_REFERENCE_POLICY_INVALID'; END IF;
  normalized:=jsonb_build_object('mode',mode,'preferred_digits',digits,'max_digits',maximum);
 ELSE RAISE EXCEPTION 'PAYMENT_REFERENCE_POLICY_INVALID'; END IF;
 -- Same lock order as the finalizer: form, namespace, then new payment. The
 -- namespace lock serializes aliases and separate forms inside this database.
 PERFORM 1 FROM public.forms WHERE id=p_form FOR UPDATE;
 SELECT * INTO STRICT pi FROM eshop.payment_info WHERE id=p_payment;
 IF pi.amount<=0 OR NOT EXISTS(SELECT 1 FROM eshop.orders WHERE payment_info=p_payment AND form=p_form) THEN RAISE EXCEPTION 'PAYMENT_REFERENCE_PAYMENT_SCOPE_INVALID'; END IF;
 SELECT n.* INTO ns FROM eshop.payment_reference_namespaces n JOIN eshop.payment_reference_accounts a ON a.namespace_id=n.id
 WHERE a.bank_account_id=pi.bank_account FOR UPDATE OF n;
 IF ns.id IS NULL THEN RAISE EXCEPTION 'PAYMENT_REFERENCE_ACCOUNT_NOT_ENROLLED'; END IF;
 SELECT public.canonical_payment_reference_account_internal(b.account_number) INTO account FROM eshop.bank_accounts b WHERE b.id=pi.bank_account AND b.type IS DISTINCT FROM 'CASH';
 IF account IS DISTINCT FROM ns.canonical_account THEN RAISE EXCEPTION 'PAYMENT_REFERENCE_ACCOUNT_IDENTITY_IMMUTABLE'; END IF;
 SELECT * INTO previous FROM eshop.payment_reference_reservations WHERE namespace_id=ns.id AND source_ref=p_source;
 IF previous.id IS NOT NULL THEN
  IF previous.payload_sha256<>p_payload_sha256 OR previous.policy<>normalized OR previous.original_payment_info_id IS DISTINCT FROM p_payment THEN
   RAISE EXCEPTION 'PAYMENT_REFERENCE_SOURCE_CONFLICT'; END IF;
  RETURN previous.variable_symbol;
 END IF;
 IF NOT ns.allocation_enabled THEN RAISE EXCEPTION 'PAYMENT_REFERENCE_REGISTRY_LOCKED'; END IF;
 IF mode='sequence' THEN
  SELECT greatest(coalesce(max(p.variable_symbol),0),coalesce((SELECT high_water FROM eshop.payment_reference_form_watermarks WHERE form_id=p_form),0)) INTO high
   FROM eshop.orders o JOIN eshop.payment_info p ON p.id=o.payment_info WHERE o.form=p_form;
  SELECT high_water INTO cursor FROM eshop.payment_reference_sequences WHERE namespace_id=ns.id AND form_id=p_form;
  floor:=greatest((normalized->>'from')::bigint,high+1,coalesce(cursor+1,1));
  IF floor>9999999999 THEN RAISE EXCEPTION 'PAYMENT_REFERENCE_SEQUENCE_EXHAUSTED'; END IF;
  IF NOT EXISTS(SELECT 1 FROM eshop.payment_reference_reservations WHERE namespace_id=ns.id AND variable_symbol=floor) THEN value:=floor;
  ELSE
   SELECT r.variable_symbol+1 INTO value FROM eshop.payment_reference_reservations r
    WHERE r.namespace_id=ns.id AND r.variable_symbol>=floor AND r.variable_symbol<9999999999
    AND NOT EXISTS(SELECT 1 FROM eshop.payment_reference_reservations used WHERE used.namespace_id=ns.id AND used.variable_symbol=r.variable_symbol+1)
    ORDER BY r.variable_symbol LIMIT 1;
  END IF;
  IF value IS NULL THEN RAISE EXCEPTION 'PAYMENT_REFERENCE_SEQUENCE_EXHAUSTED'; END IF;
 ELSIF mode='random' THEN
  preferred:=digits;
  <<find_random>>
  FOR digits IN preferred..maximum LOOP
   FOR attempt IN 1..16 LOOP
    value:=public.random_payment_reference_digits_internal(digits);
    EXIT find_random WHEN NOT EXISTS(SELECT 1 FROM eshop.payment_reference_reservations WHERE namespace_id=ns.id AND variable_symbol=value);
    value:=NULL;
   END LOOP;
  END LOOP;
  IF value IS NULL THEN RAISE EXCEPTION 'PAYMENT_REFERENCE_RETRY_REQUIRED'; END IF;
 END IF;
 IF EXISTS(SELECT 1 FROM eshop.payment_reference_reservations WHERE namespace_id=ns.id AND variable_symbol=value) THEN RAISE EXCEPTION 'PAYMENT_REFERENCE_CONFLICT'; END IF;
 INSERT INTO eshop.payment_reference_reservations(namespace_id,variable_symbol,source_ref,policy,payload_sha256,payment_info_id,original_payment_info_id,form_id)
 VALUES(ns.id,value,p_source,normalized,p_payload_sha256,p_payment,p_payment,p_form);
 IF mode='sequence' THEN
  INSERT INTO eshop.payment_reference_sequences(namespace_id,form_id,high_water) VALUES(ns.id,p_form,value)
  ON CONFLICT(namespace_id,form_id) DO UPDATE SET high_water=greatest(eshop.payment_reference_sequences.high_water,excluded.high_water);
 END IF;
 INSERT INTO eshop.payment_reference_form_watermarks(form_id,high_water) VALUES(p_form,value)
 ON CONFLICT(form_id) DO UPDATE SET high_water=greatest(eshop.payment_reference_form_watermarks.high_water,excluded.high_water);
 RETURN value;
END $function$

CREATE OR REPLACE FUNCTION public.reserve_public_link_internal(p_kind text, p_id bigint, p_slug text, p_create boolean DEFAULT false)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE current_slug text; candidate text; owner_id bigint; attempt integer; automatic boolean;
BEGIN
 IF p_kind='occasion' THEN
  SELECT link INTO current_slug FROM public.occasions WHERE id=p_id FOR UPDATE;
 ELSIF p_kind='form' THEN
  SELECT link INTO current_slug FROM public.forms WHERE id=p_id FOR UPDATE;
 ELSE RAISE invalid_parameter_value USING MESSAGE='Invalid public link kind'; END IF;
 IF NOT FOUND THEN RAISE invalid_parameter_value USING MESSAGE='Public link target missing'; END IF;
 automatic := p_create AND coalesce(p_slug,'')='';
 IF NOT p_create AND p_slug IS NULL THEN RETURN current_slug; END IF;
 -- Exact legacy no-op before new syntax validation.
 IF NOT p_create AND p_slug=current_slug THEN RETURN current_slug; END IF;
 IF NOT automatic AND (p_slug IS NULL OR length(p_slug)>80 OR p_slug !~ '^[a-z0-9]+(-[a-z0-9]+)*$') THEN
  RAISE invalid_parameter_value USING MESSAGE='Invalid public link';
 END IF;
 FOR attempt IN 1..20 LOOP
  candidate := CASE WHEN automatic THEN public.random_public_link_internal() ELSE p_slug END;
  IF p_kind='occasion' AND candidate=ANY(public.occasion_reserved_public_paths_internal()) THEN
   RAISE invalid_parameter_value USING MESSAGE='Reserved public link'; END IF;
  -- Unique insert serializes contenders, including historical reservations.
  IF p_kind='occasion' THEN
   INSERT INTO public.occasion_link_reservations(slug,occasion) VALUES(candidate,p_id) ON CONFLICT DO NOTHING;
   SELECT occasion INTO owner_id FROM public.occasion_link_reservations WHERE slug=candidate;
   -- Only an original owner may return to its own grandfathered alias.
   IF owner_id IS NULL AND EXISTS(SELECT 1 FROM public.legacy_occasion_link_bindings
     WHERE slug=candidate AND occasion=p_id) THEN owner_id:=p_id; END IF;
  ELSE
   INSERT INTO public.form_link_reservations(slug,form) VALUES(candidate,p_id) ON CONFLICT DO NOTHING;
   SELECT form INTO owner_id FROM public.form_link_reservations WHERE slug=candidate;
  END IF;
  IF owner_id=p_id THEN
   RETURN candidate;
  END IF;
  IF NOT automatic THEN RAISE unique_violation USING MESSAGE='Public link is already in use'; END IF;
 END LOOP;
 RAISE unique_violation USING MESSAGE='Public link allocation exhausted';
END $function$

CREATE OR REPLACE FUNCTION public.reset_password_and_enqueue_email(p_user uuid, p_password text, p_occasion bigint, p_sealed jsonb, p_content_hash text, p_dedupe text, p_expires timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_answer jsonb; v_context jsonb; v_email text; v_result jsonb; v_existing public.email_messages; v_password_version text;
BEGIN
 -- Reuse the existing hierarchical permission check, including elevated-account protections.
 IF auth.uid() IS NULL OR NOT coalesce(public.get_can_reset_user_password(p_user),false) THEN RAISE EXCEPTION 'password_reset_denied'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('sign-in:'||p_user::text||':'||p_occasion::text,0));
 SELECT * INTO v_existing FROM public.email_messages WHERE recipient_user=p_user AND occasion=p_occasion AND message_kind='sign_in' AND (dedupe_key=p_dedupe OR (workflow_state IN ('pending','preparing','sending','retry_wait','unknown','accepted') AND expires_at>now())) ORDER BY id DESC LIMIT 1;
 IF v_existing.id IS NOT NULL THEN
  RETURN jsonb_build_object('message_id',v_existing.message_id,'replayed',true);
 END IF;
 IF NOT EXISTS(SELECT 1 FROM public.occasion_users WHERE occasion=p_occasion AND "user"=p_user) THEN RAISE EXCEPTION 'user_not_in_occasion'; END IF;
 v_answer:=public.reset_user_password(p_user,p_password);
 IF v_answer->>'code'<>'200' THEN RAISE EXCEPTION 'password_reset_denied'; END IF;
 SELECT jsonb_build_object('organization',organization,'occasion',id,'unit',unit,'recipient_user',p_user) INTO v_context FROM public.occasions WHERE id=p_occasion;
 v_email:=public.get_user_delivery_email(p_user);
 SELECT encode(extensions.digest(encrypted_password,'sha256'),'hex') INTO v_password_version FROM auth.users WHERE id=p_user;
 v_result:=public.enqueue_email('sign_in',v_context,v_email,jsonb_build_object('password_version',v_password_version,'content_hash',p_content_hash),p_dedupe,'SIGN_IN_CODE',now(),p_expires);
 UPDATE public.email_messages SET prepared=p_sealed,prepared_hash=encode(extensions.digest(p_sealed::text,'sha256'),'hex'),prepared_at=now() WHERE message_id=(v_result->>'message_id')::uuid;
 PERFORM public.admit_email_intent_v1((SELECT id FROM public.email_messages WHERE message_id=(v_result->>'message_id')::uuid),true);
 RETURN v_result;
END $function$

CREATE OR REPLACE FUNCTION public.reset_password_via_scan(ticket_id bigint, password text, scan_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
    v_occasion_id bigint;
    v_expected_scan_code text;
    v_target_user_id uuid;
    v_target_email text;
    v_encrypted_pw text;
BEGIN
    IF NOT public.check_scan_attempt_budget_v1((SELECT occasion FROM eshop.tickets WHERE id=ticket_id)) THEN
        RETURN jsonb_build_object('code',429,'message','abuse_limit_exceeded');
    END IF;
    -- =================================================================
    -- 1. INPUT VALIDATION
    -- =================================================================
    IF ticket_id IS NULL THEN
         RETURN jsonb_build_object('code', 400, 'message', 'Ticket ID is missing.');
    END IF;

    IF password IS NULL OR trim(password) = '' THEN
         RETURN jsonb_build_object('code', 400, 'message', 'Password cannot be empty.');
    END IF;

    -- =================================================================
    -- 2. VALIDATE TICKET AND SCAN CODE
    -- =================================================================

    -- Get Occasion ID from Ticket
    SELECT occasion INTO v_occasion_id
    FROM eshop.tickets
    WHERE id = ticket_id;

    IF v_occasion_id IS NULL THEN
        PERFORM public.admit_scan_access_v1(NULL,false);
        RETURN jsonb_build_object('code', 404, 'message', 'Ticket not found or no occasion assigned.');
    END IF;

    -- Get Expected Scan Code (Secret) from Occasions Hidden
    SELECT oh.secret INTO v_expected_scan_code
    FROM public.occasions_hidden oh
    JOIN public.occasions o ON o.occasion_hidden = oh.id
    WHERE o.id = v_occasion_id
    LIMIT 1;

    IF v_expected_scan_code IS NULL THEN
        PERFORM public.admit_scan_access_v1(v_occasion_id,false);
        RETURN jsonb_build_object('code', 400, 'message', 'Scan code not defined for this occasion.');
    END IF;

    -- Verify Code Matches
    IF scan_code IS DISTINCT FROM v_expected_scan_code THEN
        PERFORM public.admit_scan_access_v1(v_occasion_id,false);
        RETURN jsonb_build_object('code', 401, 'message', 'Invalid scan code.');
    END IF;

    -- =================================================================
    -- 3. IDENTIFY TARGET USER
    -- =================================================================

    -- Find the user attached to this ticket via occasion_users
    SELECT "user" INTO v_target_user_id
    FROM public.occasion_users
    WHERE ticket = ticket_id;

    IF v_target_user_id IS NULL THEN
        RETURN jsonb_build_object('code', 404, 'message', 'No user found associated with this ticket.');
    END IF;

    -- =================================================================
    -- 4. SECURITY CHECK: PREVENT RESET FOR PRIVILEGED USERS
    -- =================================================================
    BEGIN
        PERFORM public.check_is_scan_password_reset_target_allowed(
            v_target_user_id
        );
    EXCEPTION
        WHEN insufficient_privilege THEN
            RETURN jsonb_build_object(
                'code', 403,
                'message', 'Security Restriction: Cannot reset password for privileged users via scan.'
            );
    END;

    -- =================================================================
    -- 5. PERFORM PASSWORD RESET
    -- =================================================================

    IF NOT public.admit_scan_password_reset_v1(v_occasion_id,v_target_user_id) THEN
        RETURN jsonb_build_object('code',429,'message','abuse_limit_exceeded');
    END IF;

    -- Generate encrypted password
    v_encrypted_pw := crypt(password, gen_salt('bf'));

    -- Update auth.users
    UPDATE auth.users
    SET encrypted_password = v_encrypted_pw
    WHERE id = v_target_user_id
    RETURNING email INTO v_target_email;

    IF v_target_email IS NULL THEN
         -- Fallback if email wasn't returned (unlikely if ID exists)
         RETURN jsonb_build_object('code', 500, 'message', 'Password updated, but failed to retrieve email.');
    END IF;

    -- =================================================================
    -- 6. SUCCESS RESPONSE
    -- =================================================================
    RETURN jsonb_build_object(
        'code', 200,
        'message', 'Password successfully reset.',
        'email', v_target_email
    );

EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object(
            'code', 500,
            'message', 'An unexpected error occurred.',
            'detail', SQLERRM
        );
END;
$function$

CREATE OR REPLACE FUNCTION public.reset_scanner_password(p_session uuid, p_token text, p_ticket bigint, p_password text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE s public.scanner_sessions; secret text;
BEGIN
 s:=public.scanner_session_internal(p_session,p_token);
 IF NOT EXISTS(SELECT 1 FROM eshop.tickets WHERE id=p_ticket AND occasion=s.occasion_id) THEN RAISE insufficient_privilege; END IF;
 IF NOT public.scanner_can_reset_password_internal(s.occasion_id,p_ticket) THEN RAISE insufficient_privilege USING MESSAGE='password_reset_not_available'; END IF;
 SELECT oh.secret INTO secret FROM public.occasions o JOIN public.occasions_hidden oh ON oh.id=o.occasion_hidden WHERE o.id=s.occasion_id;
 RETURN public.reset_password_via_scan(p_ticket,p_password,secret);
END $function$

CREATE OR REPLACE FUNCTION public.reset_user_password(p_user_id uuid, p_password text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_current_user_id uuid := auth.uid();
  v_has_permission boolean := false;
  v_encrypted_pw text;
  v_is_unit_manager_path boolean;
  v_is_occasion_manager_path boolean;
  v_target_has_elevated_privileges boolean;
  v_target_is_org_admin boolean;
BEGIN
    -- =================================================================
    -- 1. INPUT VALIDATION
    -- =================================================================
    IF p_user_id IS NULL THEN
        RAISE EXCEPTION '%',
            jsonb_build_object('code', 4000, 'message', 'Input data is invalid: User ID is missing')::text;
    END IF;

    IF p_password IS NULL OR trim(p_password) = '' THEN
        RAISE EXCEPTION '%',
            jsonb_build_object('code', 4000, 'message', 'Input data is invalid: Password cannot be empty')::text;
    END IF;

    -- =================================================================
    -- 2. USER EXISTENCE CHECK
    -- =================================================================
    IF NOT EXISTS (SELECT 1 FROM auth.users WHERE id = p_user_id) THEN
        RAISE EXCEPTION '%',
            jsonb_build_object('code', 4040, 'message', 'User not found')::text;
    END IF;


    -- =================================================================
    -- 3. PERMISSION CHECKS (HIERARCHICAL LOGIC)
    -- =================================================================
    -- The function checks for permissions in a specific, prioritized order.

    IF auth.uid() IS NULL OR public.get_can_reset_user_password(p_user_id) IS NOT TRUE THEN
        RAISE EXCEPTION '%',jsonb_build_object('code',4030,'message','Permission denied. You do not have the required privileges to reset this user''s password.')::text;
    END IF;

    -- =================================================================
    -- 4. PASSWORD UPDATE
    -- =================================================================
    -- All manual and emailed password changes share admission before bcrypt.
    -- Verification counters use the account UUID and are never reset here.
    PERFORM public.abuse_charge_v1(public.abuse_effective_rules_v1('auth.password.change',NULL,NULL),
      jsonb_build_object('actor',auth.uid(),'recipient',p_user_id::text),
      jsonb_build_object('password.change.payload.bytes',octet_length(p_password)));
    v_encrypted_pw := crypt(p_password, gen_salt('bf'));

    UPDATE auth.users
    SET encrypted_password = v_encrypted_pw
    WHERE auth.users.id = p_user_id;

    -- =================================================================
    -- 5. SUCCESS RESPONSE
    -- =================================================================
    RETURN jsonb_build_object('code', 200, 'message', 'Password has been successfully updated.');

EXCEPTION
    WHEN OTHERS THEN
        RETURN CASE
            WHEN left(SQLERRM, 1) = '{' THEN SQLERRM::jsonb
            ELSE jsonb_build_object('code', 5000, 'message', SQLERRM)
        END;
END;
$function$

CREATE OR REPLACE FUNCTION public.resolve_cleaning_place_client_sync_v1(p_place bigint, p_command_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_occasion bigint;
  v_begin jsonb;
  v_hash text;
  v_result jsonb;
  v_open integer;
BEGIN
  SELECT p.occasion INTO v_occasion
  FROM public.places p
  WHERE p.id = p_place;

  IF v_actor IS NULL OR v_occasion IS NULL THEN
    RAISE insufficient_privilege USING MESSAGE = 'cleaning crew required';
  END IF;

  v_hash := encode(extensions.digest(convert_to(jsonb_build_object(
    'place', p_place
  )::text, 'UTF8'), 'sha256'), 'hex');
  v_begin := public.begin_client_mutation_v1(
    p_command_id,
    'cleaning.resolve',
    v_occasion,
    v_actor,
    v_hash
  );
  IF v_begin->>'disposition' = 'replay' THEN
    RETURN v_begin->'response';
  END IF;

  PERFORM 1 FROM public.places p WHERE p.id = p_place FOR UPDATE;
  PERFORM 1
  FROM public.cleaning_reports cr
  WHERE cr.place = p_place AND cr.resolved_at IS NULL
  ORDER BY cr.id
  FOR UPDATE;

  SELECT count(*) INTO v_open
  FROM public.cleaning_reports cr
  WHERE cr.place = p_place AND cr.resolved_at IS NULL;

  v_result := public.resolve_cleaning_place_internal_v1(p_place);
  IF COALESCE((v_result->>'code')::integer, 500) <> 200 THEN
    RETURN public.complete_client_mutation_outcome_v1(
      p_command_id,
      'rejected',
      COALESCE((v_result->>'code')::integer, 400),
      COALESCE(v_result->'data', '{}') ||
        jsonb_build_object('message', v_result->>'message')
    );
  END IF;

  IF v_open = 0 THEN
    RETURN public.complete_client_mutation_outcome_v1(
      p_command_id,
      'unchanged',
      200,
      v_result->'data'
    );
  END IF;

  RETURN public.complete_client_mutation_applied_v1(
    p_command_id,
    v_occasion,
    'cleaning.resolve',
    'cleaning',
    jsonb_build_array(jsonb_build_object(
      'entityType', 'cleaning_place',
      'entityId', p_place,
      'operation', 'update',
      'safeLabel', 'Cleaning place',
      'changedFields', jsonb_build_array('resolvedAt')
    )),
    ARRAY['live_public'],
    '[]',
    jsonb_build_array(jsonb_build_object(
      'component', 'live_public',
      'entityId', p_place
    )),
    v_result->'data'
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.resolve_cleaning_place_internal_v1(place_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_user uuid := auth.uid();
  v_occasion bigint;
  v_count integer;
BEGIN
  IF v_user IS NULL THEN
    RETURN jsonb_build_object('code', 401, 'message', 'Sign in is required');
  END IF;

  SELECT occasion INTO v_occasion FROM public.places WHERE id = place_id;
  IF v_occasion IS NULL THEN
    RETURN jsonb_build_object('code', 404, 'message', 'Toilet not found');
  END IF;

  IF NOT public.get_is_cleaning_crew_on_occasion(v_occasion) THEN
    RETURN jsonb_build_object('code', 403, 'message', 'Cleaning crew access required');
  END IF;

  WITH updated AS (
    UPDATE public.cleaning_reports
    SET resolved_by = v_user,
        resolved_at = now()
    WHERE place = place_id
      AND resolved_at IS NULL
    RETURNING 1
  )
  SELECT count(*) INTO v_count FROM updated;

  RETURN jsonb_build_object(
    'code', 200,
    'data', jsonb_build_object('resolved', v_count)
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.resolve_counseling_slot_delete_occasion_internal_v1(p_speaker bigint, p_event bigint)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_occasion BIGINT;
BEGIN
  SELECT s.occasion INTO v_occasion
  FROM public.speakers s
  WHERE s.id = p_speaker;

  IF v_occasion IS NULL THEN
    RETURN NULL;
  END IF;
  IF auth.uid() IS NULL OR NOT public.get_is_editor_on_occasion(v_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE = 'occasion editor required';
  END IF;

  PERFORM public.lock_event_deletion_scope_internal_v1(v_occasion,ARRAY[p_event]);
  PERFORM 1
  FROM public.events e
  JOIN public.event_speakers es
    ON es.event = e.id AND es.speaker = p_speaker
  WHERE e.id = p_event
    AND e.occasion = v_occasion
    AND COALESCE((e.data->>'is_counseling_slot')::BOOLEAN, FALSE)
  FOR UPDATE OF e;

  IF NOT FOUND THEN
    RETURN NULL;
  END IF;
  RETURN v_occasion;
END;
$function$

CREATE OR REPLACE FUNCTION public.resolve_customer_order_access_v1(p_token text, p_order_id bigint, p_offer_id uuid, p_command_id uuid, p_delivery jsonb DEFAULT NULL::jsonb, p_actor uuid DEFAULT NULL::uuid, p_reissue boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE o eshop.orders; f public.forms; occ public.occasions; c eshop.waitlist_capabilities; s eshop.order_overview_sources;
BEGIN
 PERFORM public.require_client_sync_service_role_v1();
 IF p_offer_id IS NOT NULL THEN
  IF p_order_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM eshop.waitlist_offers WHERE id=p_offer_id AND order_id=p_order_id) THEN RAISE EXCEPTION 'INVALID_CAPABILITY'; END IF;
  SELECT order_id INTO p_order_id FROM eshop.waitlist_offers WHERE id=p_offer_id;
 END IF;
 SELECT * INTO STRICT o FROM eshop.orders WHERE id=p_order_id AND source_waitlist_order_id IS NULL FOR UPDATE;
 SELECT * INTO STRICT f FROM public.forms WHERE id=o.form AND occasion=o.occasion;
 SELECT * INTO STRICT occ FROM public.occasions WHERE id=o.occasion;
 IF p_reissue THEN
  IF NOT EXISTS(SELECT 1 FROM eshop.waitlist_capabilities WHERE order_id=o.id AND kind='manage' AND form_id=f.id AND organization_id=occ.organization) THEN RAISE EXCEPTION 'INVALID_CAPABILITY'; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.occasion_users WHERE occasion=occ.id AND "user"=p_actor AND is_editor_order) THEN
   RAISE insufficient_privilege USING MESSAGE='Order editor required'; END IF;
 ELSE
  IF o.state<>'waitlisted' OR NOT EXISTS(SELECT 1 FROM public.get_order_tickets_internal(o.id) WHERE state='waitlisted') THEN RAISE EXCEPTION 'INVALID_CAPABILITY'; END IF;
  SELECT * INTO c FROM eshop.waitlist_capabilities WHERE token_hash=encode(extensions.digest(p_token,'sha256'),'hex')
   AND order_id=o.id AND form_id=f.id AND organization_id=occ.organization AND revoked_at IS NULL
   AND (expires_at IS NULL OR expires_at>statement_timestamp())
   AND ((p_offer_id IS NULL AND kind='manage') OR (kind='offer' AND offer_id=p_offer_id));
  IF p_token IS NULL OR length(p_token)<>64 OR c.token_hash IS NULL OR (p_offer_id IS NOT NULL AND NOT EXISTS(
   SELECT 1 FROM eshop.waitlist_offers w JOIN eshop.waitlist_offer_slots x ON x.offer_id=w.id
   WHERE w.id=p_offer_id AND w.order_id=o.id AND w.form_id=f.id AND w.expires_at>statement_timestamp() AND x.outcome='pending')) THEN
   RAISE EXCEPTION 'INVALID_CAPABILITY'; END IF;
 END IF;
 -- Command replay precedes rotation. It never resurrects a revoked/expired generation.
 SELECT src.* INTO s FROM eshop.order_overview_sources src JOIN eshop.waitlist_capabilities cap USING(token_hash)
 WHERE cap.order_id=o.id AND cap.kind='order_view' AND cap.revoked_at IS NULL
 AND cap.expires_at>statement_timestamp() AND src.expires_at=cap.expires_at
 AND (NOT p_reissue OR src.command_id=p_command_id) ORDER BY src.created_at DESC LIMIT 1;
 IF s.token_hash IS NULL AND p_delivery IS NOT NULL THEN
  IF p_reissue AND EXISTS(SELECT 1 FROM eshop.orders_history WHERE "order"=o.id
   AND data->>'action'='order_overview_reissued' AND data->>'commandId'=p_command_id::text) THEN
   RAISE EXCEPTION 'OVERVIEW_REISSUE_REQUIRED'; END IF;
  IF NOT p_reissue AND EXISTS(SELECT 1 FROM eshop.waitlist_capabilities WHERE order_id=o.id AND kind='order_view') THEN
   RAISE EXCEPTION 'OVERVIEW_REISSUE_REQUIRED'; END IF;
  IF p_reissue THEN UPDATE eshop.waitlist_capabilities SET revoked_at=statement_timestamp() WHERE order_id=o.id AND kind='order_view' AND revoked_at IS NULL; END IF;
  PERFORM public.issue_order_overview_internal(o.id,p_delivery,p_command_id);
  IF p_reissue THEN INSERT INTO eshop.orders_history("order",state,data) VALUES(o.id,o.state,
   jsonb_build_object('action','order_overview_reissued','commandId',p_command_id,'actor',p_actor)); END IF;
  SELECT * INTO s FROM eshop.order_overview_sources WHERE command_id=p_command_id;
 END IF;
 RETURN jsonb_build_object('code',200,'orderId',o.id,'formLink',f.link,'organization',occ.organization,'occasion',occ.id,'unit',occ.unit,
  'orderSymbol',o.order_symbol,
  'email',(SELECT jsonb_build_object('message_id',message_id,'workflow_state',workflow_state) FROM public.email_messages WHERE dedupe_key='order-overview:'||p_command_id::text AND order_id=o.id),
  'recipient',o.data->>'email','occasionTitle',occ.title,'participantCount',(SELECT count(*) FROM public.get_order_tickets_internal(o.id)),
  'webLink',(SELECT data->>'DEFAULT_URL' FROM public.organizations WHERE id=occ.organization),
  'source',CASE WHEN s.token_hash IS NOT NULL THEN jsonb_build_object('sealed',s.sealed,'contentHash',s.content_hash,'tokenHash',s.token_hash,'expiresAt',s.expires_at) END);
END $function$

CREATE OR REPLACE FUNCTION public.resolve_existing_user_session_v1(p_user uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_profile public.user_info%rowtype; v_auth auth.users%rowtype;
BEGIN
  PERFORM public.require_service_role();
  SELECT * INTO v_profile FROM public.user_info WHERE id=p_user;
  SELECT * INTO v_auth FROM auth.users WHERE id=p_user;
  IF v_profile.id IS NULL OR v_auth.id IS NULL OR v_auth.deleted_at IS NOT NULL
    OR v_auth.banned_until > clock_timestamp()
    OR v_auth.email IS DISTINCT FROM public.format_auth_email(v_profile.organization,v_profile.email_readonly) THEN
    RETURN NULL;
  END IF;
  RETURN jsonb_build_object('userId',v_auth.id,'authEmail',v_auth.email,'organization',v_profile.organization,'requiresMfa',EXISTS(SELECT 1 FROM auth.mfa_factors WHERE user_id=p_user AND status='verified'));
END $function$

CREATE OR REPLACE FUNCTION public.resolve_scanner_conflict(p_operation uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE op public.scanner_operations;
BEGIN
 SELECT * INTO STRICT op FROM public.scanner_operations WHERE operation_id=p_operation;
 PERFORM public.check_is_editor_order_on_occasion(op.occasion_id);
 IF auth.uid() IS NULL OR op.receipt->>'outcome'<>'conflict' THEN RAISE insufficient_privilege; END IF;
 INSERT INTO public.scanner_conflict_resolutions(operation_id,actor_user_id,reason) VALUES(p_operation,auth.uid(),p_reason) ON CONFLICT DO NOTHING;
 RETURN jsonb_build_object('code',200,'server_time',now());
END $function$

CREATE OR REPLACE FUNCTION public.retain_activity_history_internal_v1(p_occasion bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE protected bigint[]; depth int;
BEGIN
 WITH RECURSIVE roots AS (
 SELECT id,parent_history_id FROM public.activity_history WHERE occasion_id=p_occasion AND history_type='AUTOSAVE'
 UNION SELECT id,parent_history_id FROM (SELECT id,parent_history_id FROM public.activity_history WHERE occasion_id=p_occasion AND history_type='PUBLISH' ORDER BY id DESC LIMIT 1) latest
 ), chain AS (
 SELECT id,parent_history_id,ARRAY[id] path,1 depth FROM roots
 UNION ALL SELECT h.id,h.parent_history_id,c.path||h.id,c.depth+1 FROM chain c JOIN public.activity_history h ON h.id=c.parent_history_id AND h.occasion_id=p_occasion WHERE NOT h.id=ANY(c.path) AND c.depth<10000
 ) SELECT array_agg(DISTINCT id),max(chain.depth) INTO protected,depth FROM chain;
 -- Fail closed on unbounded history: do not silently cut a protected chain.
 IF depth>=10000 THEN RETURN; END IF;
 DELETE FROM public.activity_history WHERE occasion_id=p_occasion AND created_at<now()-interval '30 days' AND NOT id=ANY(COALESCE(protected,'{}'::bigint[]));
END $function$

CREATE OR REPLACE FUNCTION public.review_unit_verification(p_unit bigint, p_expected_revision bigint, p_decision text, p_feedback text DEFAULT NULL::text, p_note text DEFAULT NULL::text, p_source text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE p public.unit_legal_profiles; org bigint; errors jsonb:='{}';
BEGIN
 SELECT organization INTO org FROM public.units WHERE id=p_unit FOR UPDATE;
 IF auth.uid() IS NULL OR org IS NULL OR NOT coalesce(public.check_is_admin_of_organization(org),false) OR public.is_demo_unit(p_unit) THEN
  RAISE EXCEPTION 'Verification review denied' USING ERRCODE='42501';
 END IF;
 SELECT * INTO p FROM public.unit_legal_profiles WHERE unit_id=p_unit FOR UPDATE;
 IF p_expected_revision IS DISTINCT FROM coalesce(p.revision,0) THEN RETURN jsonb_build_object('code',409,'errorCode','REVISION_CONFLICT','profile',public.get_unit_legal_profile(p_unit)->'profile'); END IF;
 IF p_decision IS NULL OR p_decision NOT IN ('approve','reject','revoke')
  OR (p_decision IN ('approve','reject') AND p.status IS DISTINCT FROM 'pending')
  OR (p_decision='revoke' AND (p.status IS DISTINCT FROM 'verified' OR p.reviewed_organization_id IS DISTINCT FROM org))
 THEN RETURN jsonb_build_object('code',422,'errorCode','INVALID_TRANSITION','fieldErrors','{}'::jsonb); END IF;
 IF p_decision='approve' THEN
  IF p.legal_name='' OR p.country_code='' OR p.registration_number='' OR p.street='' OR p.city='' OR p.postal_code='' OR p.contact_email='' THEN errors:=errors||jsonb_build_object('profile','INCOMPLETE_PROFILE'); END IF;
  IF coalesce(btrim(p_source),'')='' THEN errors:=errors||jsonb_build_object('reviewSource','REQUIRED'); END IF;
 ELSE
  IF coalesce(btrim(p_feedback),'')='' THEN errors:=errors||jsonb_build_object('feedbackToApplicant','REQUIRED'); END IF;
 END IF;
 IF length(p_feedback)>4000 OR length(p_note)>4000 OR length(p_source)>2000 THEN errors:=errors||jsonb_build_object('review','TOO_LONG'); END IF;
 IF errors<>'{}' THEN RETURN jsonb_build_object('code',422,'errorCode','INVALID_REVIEW','fieldErrors',errors); END IF;
 UPDATE public.unit_legal_profiles SET revision=revision+1,
 status=CASE p_decision WHEN 'approve' THEN 'verified' WHEN 'reject' THEN 'rejected' ELSE 'revoked' END,
 reviewed_at=statement_timestamp(),reviewed_by=auth.uid(),reviewed_organization_id=org,
 feedback_to_applicant=nullif(btrim(p_feedback),''),review_note=nullif(btrim(p_note),''),review_source=nullif(btrim(p_source),'')
 WHERE unit_id=p_unit;
 INSERT INTO public.unit_legal_profile_audit(unit_id,organization_id,revision,actor_id,action,snapshot)
 SELECT p_unit,org,revision,auth.uid(),p_decision,to_jsonb(t) FROM public.unit_legal_profiles t WHERE unit_id=p_unit;
 RETURN jsonb_build_object('code',200,'outcome','applied','profile',public.get_unit_legal_profile(p_unit)->'profile');
END $function$

CREATE OR REPLACE FUNCTION public.revoke_reception_login_qr_v1(p_occasion bigint, p_user uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_actor uuid:=auth.uid();
BEGIN
  IF NOT public.get_can_use_reception(p_occasion) THEN
    RETURN jsonb_build_object('code',403,'message','reception_unavailable');
  END IF;
  IF NOT public.reception_rate_limit_v1('revoke') THEN
    RETURN jsonb_build_object('code',429,'message','rate_limited');
  END IF;
  IF NOT EXISTS(
    SELECT 1 FROM public.reception_registrations r
    WHERE r.occasion=p_occasion AND r."user"=p_user AND r.status='active'
      AND ((r.created_by=v_actor AND r.created_at>now()-interval '30 minutes')
        OR public.get_is_manager_on_occasion(p_occasion)
        OR public.get_is_admin_on_occasion(p_occasion))
  ) THEN
    RETURN jsonb_build_object('code',403,'message','registration_unavailable');
  END IF;
  UPDATE public.user_login_qr_credentials
  SET revoked_at=now()
  WHERE occasion=p_occasion AND "user"=p_user AND revoked_at IS NULL;
  RETURN jsonb_build_object('code',200,'status','revoked');
END $function$

CREATE OR REPLACE FUNCTION public.revoke_scanner_session(p_session uuid, p_token text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE s public.scanner_sessions;
BEGIN
 SELECT * INTO s FROM public.scanner_sessions WHERE id=p_session;
 IF p_token IS NOT NULL THEN s:=public.scanner_session_internal(p_session,p_token,true);
 ELSE PERFORM public.check_is_editor_order_on_occasion(s.occasion_id); END IF;
 UPDATE public.scanner_sessions SET revoked_at=now() WHERE id=p_session;
 RETURN jsonb_build_object('code',200,'server_time',now());
END $function$

CREATE OR REPLACE FUNCTION public.sanitize_waitlist_history_internal(p_value jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE result jsonb;
BEGIN
 IF jsonb_typeof(p_value)='object' THEN
  SELECT coalesce(jsonb_object_agg(key,public.sanitize_waitlist_history_internal(value)),'{}') INTO result
  FROM jsonb_each(p_value) WHERE lower(key) NOT IN
   ('token','secret','password','offertoken','managetoken','capability','waitlistenvelope','sealed','tokenhash');
  RETURN result;
 ELSIF jsonb_typeof(p_value)='array' THEN
  SELECT coalesce(jsonb_agg(public.sanitize_waitlist_history_internal(value) ORDER BY ordinal),'[]') INTO result
  FROM jsonb_array_elements(p_value) WITH ORDINALITY item(value,ordinal);
  RETURN result;
 END IF;
 RETURN p_value;
END $function$

CREATE OR REPLACE FUNCTION public.save_activity_draft_client_sync_v1(p_occasion bigint, p_command_id uuid, p_expected_version bigint, p_history_data jsonb, p_parent_history_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE actor uuid:=auth.uid(); b jsonb; v bigint; latest bigint; draft public.activity_history%rowtype; graph jsonb; history jsonb; result jsonb; hid bigint;
BEGIN
 PERFORM public.assert_canonical_mutation_write_release_internal_v1(p_occasion);
 IF actor IS NULL OR NOT public.get_is_editor_on_occasion(p_occasion) THEN RAISE insufficient_privilege USING MESSAGE='occasion editor required'; END IF;
 IF p_history_data IS NULL OR jsonb_typeof(p_history_data)<>'object' OR octet_length(p_history_data::text)>2097152 THEN RAISE invalid_parameter_value USING MESSAGE='invalid draft'; END IF;
 b:=public.begin_client_mutation_v1(p_command_id,'activities.draft.save',p_occasion,actor,encode(extensions.digest(jsonb_build_object('occasion',p_occasion,'expectedVersion',p_expected_version,'history',p_history_data,'parent',p_parent_history_id)::text,'sha256'),'hex'));
 v:=public.lock_activity_editor_internal_v1(p_occasion);
 IF b->>'disposition'='replay' THEN RETURN b->'response'; END IF;
 SELECT id INTO latest FROM public.activity_history WHERE occasion_id=p_occasion AND history_type='PUBLISH' ORDER BY id DESC LIMIT 1;
 IF p_expected_version IS DISTINCT FROM v OR p_parent_history_id IS DISTINCT FROM latest THEN RETURN public.complete_client_mutation_outcome_v1(p_command_id,'conflict',409,jsonb_build_object('version',v,'latestPublishId',latest)); END IF;
 graph:=public.activity_history_graph_internal_v1(p_occasion,p_history_data-'_consume_autosave'); history:=public.activity_graph_history_internal_v1(graph);
 SELECT * INTO draft FROM public.activity_history WHERE occasion_id=p_occasion AND user_id=actor AND history_type='AUTOSAVE' ORDER BY id DESC LIMIT 1;
 result:=jsonb_build_object('version',v,'latestPublishId',latest,'draftId',draft.id,'draftParentHistoryId',latest);
 IF draft.id IS NOT NULL AND draft.activities_data=history AND draft.parent_history_id IS NOT DISTINCT FROM latest THEN RETURN public.complete_client_mutation_outcome_v1(p_command_id,'unchanged',200,result); END IF;
 hid:=public.write_activity_history_internal_v1(p_occasion,actor,history,'AUTOSAVE',latest,NULL);
 PERFORM public.retain_activity_history_internal_v1(p_occasion);
 RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,'activities.draft.save','activities',jsonb_build_array(jsonb_build_object('entityType','activity_draft','entityId',hid,'operation',CASE WHEN draft.id IS NULL THEN 'insert' ELSE 'update' END,'changedFields',jsonb_build_array('draft'))),'{}','[]','[]',result||jsonb_build_object('draftId',hid));
END $function$

CREATE OR REPLACE FUNCTION public.save_activity_history(p_occasion_id bigint, p_activities_data jsonb, p_history_type text, p_parent_history_id bigint, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE version bigint; result jsonb; canonical_history jsonb;
BEGIN
 IF auth.uid() IS NULL OR NOT coalesce(public.get_is_editor_on_occasion(p_occasion_id),false) THEN
  RETURN jsonb_build_object('code',403); END IF;
 IF p_history_type IS DISTINCT FROM 'AUTOSAVE' THEN
  RETURN jsonb_build_object('code',426,'message','Upgrade required for atomic activity publication'); END IF;
 version:=public.lock_activity_editor_internal_v1(p_occasion_id);
 canonical_history:=public.activity_graph_history_internal_v1(
  public.activity_history_graph_internal_v1(p_occasion_id,p_activities_data));
 result:=public.save_activity_draft_client_sync_v1(p_occasion_id,extensions.gen_random_uuid(),version,canonical_history,p_parent_history_id);
 RETURN jsonb_build_object('code',result->'code','message',result->>'status','data',
  jsonb_build_object('historyId',result#>'{data,draftId}',
   'created_at',(SELECT created_at FROM public.activity_history WHERE id=(result#>>'{data,draftId}')::bigint),
   'latest_publish_id',result#>'{data,latestPublishId}'));
END $function$

CREATE OR REPLACE FUNCTION public.save_bank_sync_connection(p_operation_id uuid, p_instance_id text, p_remote_id text, p_pairing_code text, p_mode text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_op eshop.bank_sync_operations%ROWTYPE; v_account eshop.bank_accounts%ROWTYPE; v_id bigint;
BEGIN
  PERFORM public.require_service_role();
  SELECT * INTO STRICT v_op FROM eshop.bank_sync_operations WHERE id=p_operation_id AND state='running';
  PERFORM public.check_bank_account_writable(v_op.bank_account_id);
  IF v_op.operation<>'create' THEN RAISE EXCEPTION 'BANK_SYNC_PROVISION_OPERATION_REQUIRED'; END IF;
  SELECT * INTO STRICT v_account FROM eshop.bank_accounts WHERE id=v_op.bank_account_id FOR UPDATE;
  -- Activation adopts historical movement identities under the account lock.
  -- Existing accounts use the same canonical provisioning path as new accounts.
  INSERT INTO eshop.bank_sync_connections(instance_id,consumer_app_id,remote_bank_account_id,bank_account_id,physical_account,
    provider,mode,state,pairing_code,manifest_sha256)
    VALUES(p_instance_id,'festapp',p_remote_id,v_account.id,upper(regexp_replace(v_account.account_number,'\s','','g')),
      public.bank_sync_provider_for_account(v_account.account_number),p_mode,'provisioning',p_pairing_code,v_op.payload_sha256)
    ON CONFLICT(bank_account_id) DO UPDATE SET pairing_code=EXCLUDED.pairing_code
    WHERE eshop.bank_sync_connections.remote_bank_account_id=EXCLUDED.remote_bank_account_id
      AND eshop.bank_sync_connections.instance_id=EXCLUDED.instance_id RETURNING id INTO v_id;
  IF v_id IS NULL THEN RAISE EXCEPTION 'BANK_SYNC_CONNECTION_MAPPING_CONFLICT'; END IF;
  RETURN v_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.save_blueprint_layout_impl_internal(p_blueprint jsonb, p_reviewed_demo boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE b eshop.blueprints; c jsonb; binding eshop.blueprint_seat_bindings; s eshop.spots;
 node uuid; group_id uuid; unit_id uuid; product_id bigint; spot_id bigint; blocked_value boolean; assignment_mode text;
 pool public.inventory_pools; capacity_int bigint;
 node_index jsonb; unit_index jsonb; seat_count bigint; text_ids text[]:='{}';
 doc jsonb:=p_blueprint->'layout'; result jsonb; expected bigint; issue text; all_seats uuid[]; supplied uuid[];
BEGIN
 IF nullif(p_blueprint->>'id','') IS NULL THEN
  IF (coalesce(public.get_is_editor_on_occasion((p_blueprint->>'occasion')::bigint),false) OR coalesce(public.get_is_manager_on_occasion((p_blueprint->>'occasion')::bigint),false)) IS NOT TRUE THEN
   RAISE insufficient_privilege USING MESSAGE='blueprint editor required'; END IF;
  INSERT INTO eshop.blueprints(occasion,organization,title) SELECT id,organization,p_blueprint->>'title' FROM public.occasions WHERE id=(p_blueprint->>'occasion')::bigint RETURNING * INTO b;
 ELSE
  SELECT * INTO b FROM eshop.blueprints WHERE id=(p_blueprint->>'id')::bigint;
  PERFORM 1 FROM eshop.products WHERE occasion=b.occasion ORDER BY id FOR UPDATE;
  SELECT * INTO b FROM eshop.blueprints WHERE id=(p_blueprint->>'id')::bigint FOR UPDATE;
 END IF;
 IF b.id IS NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='BLUEPRINT_NOT_FOUND'; END IF;
 IF p_reviewed_demo AND public.is_demo_occasion(b.occasion) THEN
  IF NOT EXISTS(SELECT 1 FROM public.occasion_users ou WHERE ou.occasion=b.occasion AND ou."user"=auth.uid() AND (ou.is_editor OR ou.is_manager)) THEN RAISE insufficient_privilege USING MESSAGE='blueprint migration reviewer required'; END IF;
 ELSE
 IF (coalesce(public.get_is_editor_on_occasion(b.occasion),false) OR coalesce(public.get_is_manager_on_occasion(b.occasion),false)) IS NOT TRUE THEN RAISE insufficient_privilege USING MESSAGE='blueprint editor required'; END IF;
 END IF;
 IF p_reviewed_demo AND public.is_demo_occasion(b.occasion) THEN
  IF b.layout IS NOT NULL THEN RAISE check_violation USING MESSAGE='BLUEPRINT_MIGRATION_INITIAL_LAYOUT_REQUIRED'; END IF;
 ELSE PERFORM public.check_occasion_writable(b.occasion); END IF;
 expected:=(p_blueprint->>'expected_layout_revision')::bigint;
 IF expected IS NULL OR expected<>b.layout_revision THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='BLUEPRINT_REVISION_CONFLICT'; END IF;
 PERFORM public.validate_blueprint_layout_internal(doc);
  PERFORM public.check_blueprint_text_resources_internal(doc,b.occasion);
  text_ids:=public.blueprint_text_resource_ids_internal(doc,b.occasion);
  IF jsonb_typeof(p_blueprint->'textResourceIds') IS DISTINCT FROM 'array'
    OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_blueprint->'textResourceIds') id WHERE jsonb_typeof(id)<>'string')
    OR (SELECT coalesce(array_agg(id ORDER BY id),'{}'::text[]) FROM jsonb_array_elements_text(p_blueprint->'textResourceIds') id) IS DISTINCT FROM text_ids
    THEN RAISE check_violation USING MESSAGE='BLUEPRINT_TEXT_RESOURCE_REFS_MISMATCH'; END IF;

 PERFORM public.check_blueprint_image_resource_internal(doc,b.occasion);
 PERFORM public.check_blueprint_bitmap_resources_internal(doc,b.occasion);
 SELECT coalesce(jsonb_object_agg(x->>'id',x),'{}'),count(*) FILTER(WHERE x->>'kind'='seat') INTO node_index,seat_count FROM jsonb_array_elements(doc->'nodes') x;
 -- Membership is projected from the document, never trusted from an overlay.
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(doc->'selectionUnits','[]')) u WHERE
   (u->>'id')::uuid IS NULL OR jsonb_array_length(u->'nodeIds')=0 OR coalesce(u->>'kind','atomic')<>'atomic')
  OR EXISTS(SELECT member FROM jsonb_array_elements(coalesce(doc->'selectionUnits','[]')) u
   CROSS JOIN LATERAL jsonb_array_elements_text(u->'nodeIds') member GROUP BY member HAVING count(*)>1)
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(doc->'selectionUnits','[]')) u
   CROSS JOIN LATERAL jsonb_array_elements_text(u->'nodeIds') member
   WHERE coalesce(node_index->member->>'kind','')<>'seat') THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='BLUEPRINT_INVALID_SELECTION_UNITS'; END IF;
 SELECT coalesce(jsonb_object_agg(member,u->>'id'),'{}') INTO unit_index
 FROM jsonb_array_elements(coalesce(doc->'selectionUnits','[]')) u CROSS JOIN LATERAL jsonb_array_elements_text(u->'nodeIds') member;
 -- Keep the existing financial resource lock ordering, before spot row locks.
 PERFORM 1 FROM eshop.products WHERE occasion=b.occasion ORDER BY id FOR UPDATE;
 PERFORM 1 FROM public.inventory_pools WHERE id IN(SELECT ic.inventory_pool FROM public.inventory_contexts ic
  JOIN eshop.product_inventory_contexts pic ON pic.inventory_context=ic.id JOIN eshop.products p ON p.id=pic.product WHERE p.occasion=b.occasion) ORDER BY id FOR UPDATE;
 PERFORM 1 FROM public.inventory_contexts WHERE id IN(SELECT pic.inventory_context FROM eshop.product_inventory_contexts pic JOIN eshop.products p ON p.id=pic.product WHERE p.occasion=b.occasion) ORDER BY id FOR UPDATE;
 PERFORM 1 FROM eshop.spots WHERE blueprint=b.id ORDER BY id FOR UPDATE;
 IF EXISTS(SELECT change->>'nodeId' FROM jsonb_array_elements(coalesce(p_blueprint->'seatChanges','[]')) change GROUP BY change->>'nodeId' HAVING count(*)>1) THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='BLUEPRINT_DUPLICATE_SEAT_CHANGE'; END IF;
 FOR c IN SELECT * FROM jsonb_array_elements(coalesce(p_blueprint->'seatChanges','[]')) LOOP
  node:=(c->>'nodeId')::uuid;
  SELECT * INTO binding FROM eshop.blueprint_seat_bindings WHERE blueprint=b.id AND node_id=node;
  IF c->>'operation'='delete' THEN
   IF binding.node_id IS NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='BLUEPRINT_BINDING_NOT_FOUND',DETAIL=c::text; END IF;
   SELECT * INTO s FROM eshop.spots WHERE id=binding.spot;
   IF s.order_product_ticket IS NOT NULL OR (s.secret IS NOT NULL AND s.secret_expiration_time>clock_timestamp()) THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='BLUEPRINT_SEAT_PROTECTED',DETAIL=c::text; END IF;
   DELETE FROM eshop.blueprint_seat_bindings WHERE blueprint=b.id AND node_id=node;
   DELETE FROM eshop.spots WHERE id=s.id;
   CONTINUE;
  END IF;
  IF c->>'operation' IS DISTINCT FROM 'upsert' OR coalesce(node_index->node::text->>'kind','')<>'seat' THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='BLUEPRINT_INVALID_SEAT_CHANGE',DETAIL=c::text; END IF;
  IF NOT c ? 'productId' OR NOT c ? 'blocked' OR NOT c ? 'groupNodeId' OR NOT c ? 'selectionUnitId' THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='BLUEPRINT_INCOMPLETE_SEAT_CHANGE',DETAIL=c::text; END IF;
  assignment_mode:=coalesce(c->>'productAssignmentMode','override');
  IF assignment_mode NOT IN ('inherit','override') OR NOT c ? 'productAssignmentMode' THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_PRODUCT_ASSIGNMENT_MODE'; END IF;
  product_id:=(c->>'productId')::bigint; group_id:=(c->>'groupNodeId')::uuid; unit_id:=(c->>'selectionUnitId')::uuid; blocked_value:=(c->>'blocked')::boolean;
  IF blocked_value IS NULL OR (product_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM eshop.products WHERE id=product_id AND occasion=b.occasion)) THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='BLUEPRINT_INVALID_PRODUCT',DETAIL=c::text; END IF;
  IF group_id IS NOT NULL AND coalesce(node_index->group_id::text->>'kind','') NOT IN ('group','table','furniture') THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='BLUEPRINT_INVALID_GROUP',DETAIL=c::text; END IF;
  IF unit_id IS DISTINCT FROM (unit_index->>node::text)::uuid THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='BLUEPRINT_UNIT_MEMBERSHIP_MISMATCH',DETAIL=c::text; END IF;
  spot_id:=(c->>'spotId')::bigint;
  IF binding.node_id IS NOT NULL AND spot_id IS DISTINCT FROM binding.spot THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='BLUEPRINT_SPOT_IDENTITY_CHANGED',DETAIL=c::text; END IF;
  IF spot_id IS NOT NULL THEN
   SELECT * INTO s FROM eshop.spots WHERE id=spot_id AND blueprint=b.id AND occasion=b.occasion;
   IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='BLUEPRINT_SPOT_SCOPE_MISMATCH',DETAIL=c::text; END IF;
   IF (s.order_product_ticket IS NOT NULL OR (s.secret IS NOT NULL AND s.secret_expiration_time>clock_timestamp()))
    AND (s.product IS DISTINCT FROM product_id OR s.title IS DISTINCT FROM c->>'title'
     OR coalesce(binding.blocked,false) IS DISTINCT FROM blocked_value OR binding.selection_unit IS DISTINCT FROM unit_id OR binding.group_node IS DISTINCT FROM group_id OR binding.product_assignment_mode IS DISTINCT FROM assignment_mode) THEN
    RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='BLUEPRINT_SEAT_PROTECTED',DETAIL=c::text; END IF;
   UPDATE eshop.spots SET product=product_id,title=c->>'title',updated_at=now() WHERE id=spot_id
    AND (product IS DISTINCT FROM product_id OR title IS DISTINCT FROM c->>'title');
  ELSE
   INSERT INTO eshop.spots(blueprint,occasion,product,title) VALUES(b.id,b.occasion,product_id,c->>'title') RETURNING id INTO spot_id;
  END IF;
  INSERT INTO eshop.blueprint_seat_bindings(blueprint,node_id,spot,selection_unit,group_node,blocked,product_assignment_mode)
   VALUES(b.id,node,spot_id,unit_id,group_id,blocked_value,assignment_mode)
   ON CONFLICT(blueprint,node_id) DO UPDATE SET selection_unit=excluded.selection_unit,group_node=excluded.group_node,blocked=excluded.blocked,product_assignment_mode=excluded.product_assignment_mode;
 END LOOP;
 IF EXISTS(SELECT 1 FROM eshop.blueprint_seat_bindings sb WHERE sb.blueprint=b.id AND coalesce(node_index->sb.node_id::text->>'kind','')<>'seat')
  OR (SELECT count(*) FROM eshop.blueprint_seat_bindings sb WHERE sb.blueprint=b.id)<>seat_count
  OR EXISTS(SELECT 1 FROM eshop.blueprint_seat_bindings sb WHERE sb.blueprint=b.id AND sb.selection_unit IS DISTINCT FROM
   (unit_index->>sb.node_id::text)::uuid) THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='BLUEPRINT_BINDING_SET_MISMATCH'; END IF;
 IF EXISTS(SELECT 1 FROM eshop.blueprint_seat_bindings sb WHERE sb.blueprint=b.id AND sb.group_node IS NOT NULL AND coalesce(node_index->sb.group_node::text->>'kind','') NOT IN ('group','table','furniture')) THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='BLUEPRINT_INVALID_GROUP'; END IF;
 FOR c IN SELECT * FROM jsonb_array_elements(coalesce(p_blueprint->'groupProductChanges','[]')) LOOP
  IF NOT c ? 'productId' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='BLUEPRINT_INCOMPLETE_GROUP_CHANGE',DETAIL=c::text; END IF;
  node:=(c->>'groupNodeId')::uuid; product_id:=(c->>'productId')::bigint;
  IF coalesce(node_index->node::text->>'kind','') NOT IN ('table','group','furniture')
   OR (product_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM eshop.products WHERE id=product_id AND occasion=b.occasion)) THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='BLUEPRINT_INVALID_GROUP_PRODUCT',DETAIL=c::text; END IF;
  DELETE FROM eshop.blueprint_group_products WHERE blueprint=b.id AND group_node=node;
  IF product_id IS NOT NULL THEN INSERT INTO eshop.blueprint_group_products VALUES(b.id,node,product_id); END IF;
 END LOOP;
 DELETE FROM eshop.blueprint_group_products gp WHERE blueprint=b.id AND NOT node_index ? gp.group_node::text;
 IF EXISTS(SELECT 1 FROM eshop.blueprint_seat_bindings sb JOIN eshop.spots bound_spot ON bound_spot.id=sb.spot LEFT JOIN eshop.blueprint_group_products gp ON gp.blueprint=sb.blueprint AND gp.group_node=sb.group_node WHERE sb.blueprint=b.id AND sb.product_assignment_mode='inherit' AND (sb.group_node IS NULL OR gp.product IS NULL)) THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INHERITED_PRODUCT_MISMATCH'; END IF;
 FOR c IN SELECT * FROM jsonb_array_elements(coalesce(p_blueprint->'areaBindingChanges','[]')) LOOP
  node:=(c->>'nodeId')::uuid; product_id:=(c->>'productId')::bigint;
  DELETE FROM eshop.blueprint_area_bindings WHERE blueprint=b.id AND node_id=node;
  IF c->>'operation'='delete' THEN CONTINUE; END IF;
  IF c->>'operation' IS DISTINCT FROM 'upsert' OR coalesce(node_index->node::text->>'kind','')<>'capacityArea'
   OR NOT EXISTS(SELECT 1 FROM eshop.product_inventory_contexts pic JOIN eshop.products p ON p.id=pic.product JOIN public.inventory_contexts ic ON ic.id=pic.inventory_context JOIN public.inventory_pools ip ON ip.id=ic.inventory_pool WHERE pic.product=product_id AND pic.inventory_context=(c->>'inventoryContextId')::bigint AND p.occasion=b.occasion AND ip.occasion=b.occasion) THEN
   RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='BLUEPRINT_INVALID_AREA_BINDING',DETAIL=c::text; END IF;
  IF c ? 'capacity' THEN
   capacity_int:=(c->>'capacity')::bigint;
   IF capacity_int IS NULL OR capacity_int<0 OR capacity_int>1000000 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='BLUEPRINT_INVALID_CAPACITY'; END IF;
   SELECT ip.* INTO pool FROM public.inventory_pools ip JOIN public.inventory_contexts ic ON ic.inventory_pool=ip.id WHERE ic.id=(c->>'inventoryContextId')::bigint;
   PERFORM public.update_inventory_pool_bundle(jsonb_build_object('pool',to_jsonb(pool)||jsonb_build_object('sellable_capacity',capacity_int)));
  END IF;
  INSERT INTO eshop.blueprint_area_bindings VALUES(b.id,node,(c->>'inventoryContextId')::bigint,product_id);
 END LOOP;
 IF EXISTS(SELECT 1 FROM eshop.blueprint_area_bindings ab WHERE blueprint=b.id AND coalesce(node_index->ab.node_id::text->>'kind','')<>'capacityArea') THEN
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='BLUEPRINT_AREA_BINDING_SET_MISMATCH'; END IF;
 UPDATE eshop.blueprints SET layout=doc,layout_text_resource_ids=text_ids,layout_revision=layout_revision+1,updated_at=now(),title=coalesce(p_blueprint->>'title',title) WHERE id=b.id RETURNING * INTO b;
 result:=public.blueprint_binding_projection_internal(b.id)||jsonb_build_object('code',200,'blueprint_id',b.id,'layout_revision',b.layout_revision,
  'document_hash',encode(extensions.digest(convert_to(doc::text,'UTF8'),'sha256'),'hex'));
 IF octet_length(result::text)>4194304 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='BLUEPRINT_RESULT_TOO_LARGE'; END IF;
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.save_event_client_sync_v1(p_occasion bigint, p_command_id uuid, p_expected_version bigint, p_event jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_response jsonb; v_commit uuid; v_event bigint;
BEGIN
  v_response:=public.save_event_domain_command_internal_v1(
    p_occasion,p_command_id,p_expected_version,p_event);
  IF v_response->>'status'='applied' THEN
    v_commit:=NULLIF(v_response#>>'{mutation,commitId}','')::uuid;
    v_event:=NULLIF(v_response#>>'{data,event,id}','')::bigint;
    IF v_event IS NULL THEN v_event:=NULLIF(v_response#>>'{data,eventId}','')::bigint; END IF;
    IF v_commit IS NOT NULL AND v_event IS NOT NULL
       AND EXISTS (SELECT 1 FROM public.occasions o WHERE o.id=p_occasion AND NOT o.is_hidden) THEN
      PERFORM public.attach_event_live_projection_v1(v_commit,p_occasion,ARRAY[v_event]);
    END IF;
  END IF;
  RETURN v_response;
END; $function$

CREATE OR REPLACE FUNCTION public.save_event_domain_command_internal_v1(p_occasion bigint, p_command_id uuid, p_expected_version bigint, p_event jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_event_id bigint := (p_event->>'id')::bigint;
  v_version bigint;
  v_begin jsonb;
  v_commit jsonb;
  v_data jsonb;
  v_current jsonb;
  v_requested jsonb;
  v_response jsonb;
  v_program jsonb;
  v_hash text;
  v_changed boolean := true;
  v_is_publishable boolean;
  v_parent_ids bigint[];
  v_role_ids bigint[];
BEGIN
  IF v_actor IS NULL OR NOT public.get_is_editor_on_occasion(p_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion editor required';
  END IF;
  SELECT NOT o.is_hidden INTO v_is_publishable
  FROM public.occasions o WHERE o.id=p_occasion;
  IF v_is_publishable IS NULL THEN
    RAISE invalid_parameter_value USING MESSAGE='occasion not found';
  END IF;
  IF p_event IS NULL OR jsonb_typeof(p_event)<>'object'
     OR octet_length(p_event::text)>131072
     OR EXISTS (SELECT 1 FROM jsonb_object_keys(p_event) key WHERE key NOT IN
       ('id','title','startTime','endTime','maxParticipants','description',
        'placeId','splitForMenWomen','isGroupEvent','isHidden','type','data',
        'order','parentEventIds','eventRoleIds'))
     OR NOT (p_event ?& ARRAY['title','startTime','endTime','splitForMenWomen',
       'isGroupEvent','isHidden','order','parentEventIds','eventRoleIds'])
     OR jsonb_typeof(p_event->'parentEventIds')<>'array'
     OR jsonb_typeof(p_event->'eventRoleIds')<>'array'
     OR jsonb_array_length(p_event->'parentEventIds')>1000
     OR jsonb_array_length(p_event->'eventRoleIds')>1000
     OR length(p_event->>'title') NOT BETWEEN 1 AND 500
     OR (p_event->>'startTime')::timestamptz >= (p_event->>'endTime')::timestamptz
     OR COALESCE((p_event->>'maxParticipants')::bigint,0)<0 THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid event aggregate';
  END IF;

  SELECT COALESCE(array_agg(value::bigint ORDER BY value::bigint),'{}')
    INTO v_parent_ids FROM jsonb_array_elements_text(p_event->'parentEventIds');
  SELECT COALESCE(array_agg(value::bigint ORDER BY value::bigint),'{}')
    INTO v_role_ids FROM jsonb_array_elements_text(p_event->'eventRoleIds');
  v_requested:=jsonb_build_object(
    'id',v_event_id,'title',p_event->>'title',
    'startTime',(p_event->>'startTime')::timestamptz,
    'endTime',(p_event->>'endTime')::timestamptz,
    'maxParticipants',(p_event->>'maxParticipants')::bigint,
    'description',p_event->>'description',
    'placeId',(p_event->>'placeId')::bigint,
    'splitForMenWomen',(p_event->>'splitForMenWomen')::boolean,
    'isGroupEvent',(p_event->>'isGroupEvent')::boolean,
    'isHidden',(p_event->>'isHidden')::boolean,'type',p_event->>'type',
    'data',p_event->'data','order',(p_event->>'order')::bigint,
    'parentEventIds',to_jsonb(v_parent_ids),'eventRoleIds',to_jsonb(v_role_ids));

  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'occasion',p_occasion,'expectedVersion',p_expected_version,'event',p_event)::text,
    'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'event.save',
    p_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  PERFORM 1 FROM public.places WHERE id=(p_event->>'placeId')::bigint AND occasion=p_occasion FOR KEY SHARE;
  PERFORM 1 FROM public.role_info WHERE id=ANY(v_role_ids) AND occasion=p_occasion ORDER BY id FOR KEY SHARE;
  PERFORM 1 FROM public.events WHERE id=ANY(v_parent_ids||ARRAY[v_event_id]) AND occasion=p_occasion ORDER BY id FOR UPDATE;

  IF v_event_id IS NOT NULL THEN
    PERFORM 1 FROM public.events e WHERE e.id=v_event_id AND e.occasion=p_occasion
      FOR UPDATE;
    IF NOT FOUND THEN
      v_response:=jsonb_build_object('status','rejected','code',404,
        'data',jsonb_build_object('eventId',v_event_id),
        'mutation',jsonb_build_object('commandId',p_command_id,'receiptId',p_command_id,
          'commitId',NULL,'replayed',false,'occurredAt',clock_timestamp()),
        'sync',jsonb_build_object('replacements','[]'::jsonb));
      RETURN public.finish_client_mutation_v1(p_command_id,v_response,NULL);
    END IF;
    INSERT INTO public.client_aggregate_versions
      (aggregate_type,scope_type,scope_id,aggregate_id,version)
    VALUES ('event','occasion',p_occasion,v_event_id::text,0)
    ON CONFLICT DO NOTHING;
    SELECT version INTO v_version FROM public.client_aggregate_versions
      WHERE aggregate_type='event' AND scope_type='occasion'
        AND scope_id=p_occasion AND aggregate_id=v_event_id::text FOR UPDATE;
    v_current:=public.get_event_command_data_v1(v_event_id);
    IF p_expected_version IS DISTINCT FROM v_version THEN
      v_response:=jsonb_build_object('status','conflict','code',409,
        'data',jsonb_build_object('version',v_version,'event',v_current),
        'mutation',jsonb_build_object('commandId',p_command_id,'receiptId',p_command_id,
          'commitId',NULL,'replayed',false,'occurredAt',clock_timestamp()),
        'sync',jsonb_build_object('replacements','[]'::jsonb));
      RETURN public.finish_client_mutation_v1(p_command_id,v_response,NULL);
    END IF;
    v_changed:=v_current IS DISTINCT FROM v_requested;
  ELSIF p_expected_version IS NOT NULL THEN
    RAISE invalid_parameter_value USING MESSAGE='new event must not have an expected version';
  END IF;

  IF cardinality(v_parent_ids)<>cardinality(ARRAY(SELECT DISTINCT unnest(v_parent_ids)))
     OR cardinality(v_role_ids)<>cardinality(ARRAY(SELECT DISTINCT unnest(v_role_ids)))
     OR (v_event_id IS NOT NULL AND v_event_id=ANY(v_parent_ids))
     OR EXISTS (
       SELECT 1
       FROM unnest(v_parent_ids) AS parent(parent_id)
       LEFT JOIN public.events e
         ON e.id=parent.parent_id AND e.occasion=p_occasion
       WHERE e.id IS NULL
     )
     OR EXISTS (
       SELECT 1
       FROM unnest(v_role_ids) AS requested_role(role_id)
       LEFT JOIN public.role_info r
         ON r.id=requested_role.role_id AND r.occasion=p_occasion
       WHERE r.id IS NULL
     )
     OR ((p_event->>'placeId') IS NOT NULL AND NOT EXISTS (
       SELECT 1 FROM public.places p WHERE p.id=(p_event->>'placeId')::bigint
         AND p.occasion=p_occasion)) THEN
    RAISE invalid_parameter_value USING MESSAGE='event aggregate contains cross-scope references';
  END IF;


  IF NOT v_changed THEN
    v_response:=jsonb_build_object('status','unchanged','code',200,
      'data',jsonb_build_object('version',v_version,'event',v_current),
      'mutation',jsonb_build_object('commandId',p_command_id,'receiptId',p_command_id,
        'commitId',NULL,'replayed',false,'occurredAt',clock_timestamp()),
      'sync',jsonb_build_object('replacements','[]'::jsonb));
    RETURN public.finish_client_mutation_v1(p_command_id,v_response,NULL);
  END IF;

  IF v_event_id IS NULL THEN
    INSERT INTO public.events(title,start_time,end_time,max_participants,description,
      place,split_for_men_women,is_group_event,is_hidden,occasion,type,data,"order")
    VALUES (p_event->>'title',(p_event->>'startTime')::timestamptz,
      (p_event->>'endTime')::timestamptz,(p_event->>'maxParticipants')::bigint,
      p_event->>'description',(p_event->>'placeId')::bigint,
      (p_event->>'splitForMenWomen')::boolean,(p_event->>'isGroupEvent')::boolean,
      (p_event->>'isHidden')::boolean,p_occasion,p_event->>'type',p_event->'data',
      (p_event->>'order')::bigint) RETURNING id INTO v_event_id;
    v_version:=1;
    INSERT INTO public.client_aggregate_versions
      (aggregate_type,scope_type,scope_id,aggregate_id,version)
    VALUES ('event','occasion',p_occasion,v_event_id::text,v_version);
  ELSE
    UPDATE public.events SET title=p_event->>'title',
      start_time=(p_event->>'startTime')::timestamptz,
      end_time=(p_event->>'endTime')::timestamptz,
      max_participants=(p_event->>'maxParticipants')::bigint,
      description=p_event->>'description',place=(p_event->>'placeId')::bigint,
      split_for_men_women=(p_event->>'splitForMenWomen')::boolean,
      is_group_event=(p_event->>'isGroupEvent')::boolean,
      is_hidden=(p_event->>'isHidden')::boolean,type=p_event->>'type',
      data=p_event->'data',"order"=(p_event->>'order')::bigint,updated_at=now()
    WHERE id=v_event_id;
    UPDATE public.client_aggregate_versions SET version=version+1,updated_at=clock_timestamp()
      WHERE aggregate_type='event' AND scope_type='occasion'
        AND scope_id=p_occasion AND aggregate_id=v_event_id::text
      RETURNING version INTO v_version;
  END IF;
  DELETE FROM public.event_groups WHERE event_child=v_event_id;
  INSERT INTO public.event_groups(event_parent,event_child)
    SELECT parent.parent_id,v_event_id
    FROM unnest(v_parent_ids) AS parent(parent_id);
  DELETE FROM public.event_roles WHERE event=v_event_id;
  INSERT INTO public.event_roles(event,role)
    SELECT v_event_id,requested_role.role_id
    FROM unnest(v_role_ids) AS requested_role(role_id);

  v_data:=jsonb_build_object('version',v_version,
    'event',public.get_event_command_data_v1(v_event_id));
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'event.save','program',jsonb_build_array(jsonb_build_object(
      'entityType','event','entityId',v_event_id,
      'operation',CASE WHEN v_current IS NULL THEN 'insert' ELSE 'update' END,
      'safeLabel',left(p_event->>'title',240),
      'changedFields',jsonb_build_array('aggregate'))),
    CASE WHEN v_is_publishable THEN ARRAY['program_catalog'] ELSE '{}'::text[] END,
    '[]','[]',v_data);
END;
$function$

CREATE OR REPLACE FUNCTION public.save_exclusive_group_client_sync_v1(p_occasion bigint, p_command_id uuid, p_expected_version bigint, p_group jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_id bigint; v_version bigint; v_begin jsonb;
  v_hash text; v_current jsonb; v_entity jsonb; v_event_ids bigint[];
  v_requested jsonb;
BEGIN
  IF v_actor IS NULL OR NOT public.get_is_editor_on_occasion(p_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion editor required'; END IF;
  IF p_group IS NULL OR jsonb_typeof(p_group)<>'object'
    OR EXISTS (SELECT 1 FROM jsonb_object_keys(p_group) key
      WHERE key NOT IN ('id','title','events'))
    OR nullif(btrim(p_group->>'title'),'') IS NULL
    OR octet_length(p_group->>'title')>2048
    OR jsonb_typeof(p_group->'events')<>'array'
    OR jsonb_array_length(p_group->'events')>500
    OR EXISTS (SELECT 1 FROM jsonb_array_elements(p_group->'events') value
      WHERE jsonb_typeof(value)<>'number') THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid exclusive group'; END IF;
  SELECT COALESCE(array_agg(value::text::bigint ORDER BY value::text::bigint),
    '{}'::bigint[]) INTO v_event_ids FROM jsonb_array_elements(p_group->'events');
  IF cardinality(v_event_ids)<>cardinality(ARRAY(SELECT DISTINCT unnest(v_event_ids))) THEN
    RAISE invalid_parameter_value USING MESSAGE='duplicate exclusive event'; END IF;
  v_id:=(p_group->>'id')::bigint;
  IF v_id IS NULL AND p_expected_version IS NOT NULL THEN
    RAISE invalid_parameter_value USING MESSAGE='new group must not have expected version'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'occasion',p_occasion,'expectedVersion',p_expected_version,
    'group',p_group)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'schedule.exclusive_group.save',
    p_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  IF EXISTS (SELECT 1 FROM unnest(v_event_ids) event_id WHERE NOT EXISTS (
    SELECT 1 FROM public.events e WHERE e.id=event_id AND e.occasion=p_occasion)) THEN
    RAISE invalid_parameter_value USING MESSAGE='exclusive event outside occasion'; END IF;
  PERFORM 1 FROM public.events e WHERE e.id=ANY(v_event_ids) ORDER BY e.id FOR UPDATE;
  IF v_id IS NOT NULL THEN
    PERFORM 1 FROM public.exclusive_groups g WHERE g.id=v_id
      AND g.occasion=p_occasion FOR UPDATE;
    IF NOT FOUND THEN RETURN public.complete_client_mutation_outcome_v1(
      p_command_id,'rejected',404,jsonb_build_object('version',0,'group',NULL)); END IF;
    INSERT INTO public.client_aggregate_versions
      (aggregate_type,scope_type,scope_id,aggregate_id,version)
    VALUES ('exclusive_group','occasion',p_occasion,v_id::text,0)
    ON CONFLICT DO NOTHING;
    SELECT version INTO v_version FROM public.client_aggregate_versions
      WHERE aggregate_type='exclusive_group' AND scope_type='occasion'
      AND scope_id=p_occasion AND aggregate_id=v_id::text FOR UPDATE;
    v_current:=public.get_exclusive_group_command_data_v1(v_id);
    IF p_expected_version IS DISTINCT FROM v_version THEN
      RETURN public.complete_client_mutation_outcome_v1(p_command_id,'conflict',409,
        jsonb_build_object('version',v_version,'group',v_current)); END IF;
    v_requested:=jsonb_build_object('id',v_id,'title',p_group->>'title',
      'exclusive_events',COALESCE((SELECT jsonb_agg(jsonb_build_object('event',event_id)
        ORDER BY event_id) FROM unnest(v_event_ids) event_id),'[]'::jsonb),
      'aggregate_version',v_version);
    IF v_current=v_requested THEN RETURN public.complete_client_mutation_outcome_v1(
      p_command_id,'unchanged',200,jsonb_build_object(
        'version',v_version,'group',v_current)); END IF;
    UPDATE public.exclusive_groups SET title=p_group->>'title' WHERE id=v_id;
    DELETE FROM public.exclusive_events WHERE "group"=v_id;
    INSERT INTO public.exclusive_events("group",event)
      SELECT v_id,event_id FROM unnest(v_event_ids) event_id;
    UPDATE public.client_aggregate_versions SET version=version+1,
      updated_at=clock_timestamp() WHERE aggregate_type='exclusive_group'
      AND scope_type='occasion' AND scope_id=p_occasion AND aggregate_id=v_id::text
      RETURNING version INTO v_version;
  ELSE
    INSERT INTO public.exclusive_groups(title,occasion)
      VALUES (p_group->>'title',p_occasion) RETURNING id INTO v_id;
    INSERT INTO public.exclusive_events("group",event)
      SELECT v_id,event_id FROM unnest(v_event_ids) event_id;
    v_version:=1;
    INSERT INTO public.client_aggregate_versions
      (aggregate_type,scope_type,scope_id,aggregate_id,version)
    VALUES ('exclusive_group','occasion',p_occasion,v_id::text,v_version);
  END IF;
  v_entity:=public.get_exclusive_group_command_data_v1(v_id);
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'schedule.exclusive_group.save','schedule_constraints',
    jsonb_build_array(jsonb_build_object('entityType','exclusive_group',
      'entityId',v_id,'operation',CASE WHEN v_current IS NULL THEN 'insert' ELSE 'update' END,
      'safeLabel',left(p_group->>'title',240),
      'changedFields',jsonb_build_array('title','events'))),
    '{}','[]','[]',jsonb_build_object('version',v_version,'group',v_entity));
END; $function$

CREATE OR REPLACE FUNCTION public.save_icon_client_sync_v1(p_occasion bigint, p_command_id uuid, p_icon jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE u bigint; old_receipt jsonb; old_hash text;
BEGIN
 SELECT unit INTO u FROM public.occasions WHERE id=p_occasion;
 IF u IS NULL THEN RAISE invalid_parameter_value USING MESSAGE='occasion unit required'; END IF;
 -- Preserve receipts produced by the former occasion-scoped command.
 IF EXISTS(SELECT 1 FROM public.client_mutation_receipts WHERE command_id=p_command_id
   AND command_name='map.icon.save') THEN
  IF auth.uid() IS NULL OR NOT public.get_is_editor_on_unit(u) THEN
   RAISE insufficient_privilege USING MESSAGE='unit editor required'; END IF;
  old_hash:=encode(extensions.digest(convert_to(jsonb_build_object('occasion',p_occasion,'icon',p_icon)::text,'UTF8'),'sha256'),'hex');
  old_receipt:=public.begin_client_mutation_v1(p_command_id,'map.icon.save',p_occasion,auth.uid(),old_hash);
  IF old_receipt->>'disposition'='replay' THEN RETURN old_receipt->'response'; END IF;
  RAISE serialization_failure USING MESSAGE='incomplete legacy icon intent';
 END IF;
 RETURN public.save_unit_icon_client_sync_v1(u,p_command_id,p_icon);
END $function$

CREATE OR REPLACE FUNCTION public.save_information_client_sync_v1(p_occasion bigint, p_command_id uuid, p_expected_version bigint, p_information jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_actor uuid:=auth.uid(); v_id bigint; v_hidden_id bigint; v_old_hidden_id bigint;
  v_version bigint; v_begin jsonb; v_hash text; v_current jsonb;
  v_requested jsonb; v_entity jsonb; v_commit jsonb; v_public jsonb;
  v_response jsonb; v_is_publishable boolean; v_old_is_hidden boolean;
  v_new_is_hidden boolean; v_affects_public boolean;
BEGIN
  IF v_actor IS NULL OR NOT public.get_is_editor_on_occasion(p_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion editor required';
  END IF;
  SELECT NOT o.is_hidden INTO v_is_publishable FROM public.occasions o
    WHERE o.id=p_occasion;
  IF v_is_publishable IS NULL THEN
    RAISE invalid_parameter_value USING MESSAGE='occasion not found';
  END IF;
  PERFORM public.validate_information_content_internal_v1(p_information,false);
  v_id:=(p_information->>'id')::bigint;
  v_new_is_hidden:=(p_information->>'isHidden')::boolean;
  v_requested:=jsonb_build_object('id',v_id,'title',p_information->>'title',
    'description',p_information->>'description','type',p_information->>'type',
    'isHidden',v_new_is_hidden,'order',(p_information->>'order')::bigint,
    'data',p_information->'data','hiddenData',p_information->'hiddenData');
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'occasion',p_occasion,'expectedVersion',p_expected_version,
    'information',p_information)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'content.information.save',
    p_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;

  IF v_id IS NOT NULL THEN
    PERFORM 1 FROM public.information i WHERE i.id=v_id AND i.occasion=p_occasion
      FOR UPDATE;
    IF NOT FOUND THEN
      RETURN public.complete_client_mutation_outcome_v1(p_command_id,
        'rejected',404,jsonb_build_object('version',0,'information',NULL));
    END IF;
    INSERT INTO public.client_aggregate_versions
      (aggregate_type,scope_type,scope_id,aggregate_id,version)
    VALUES ('information','occasion',p_occasion,v_id::text,0) ON CONFLICT DO NOTHING;
    SELECT version INTO v_version FROM public.client_aggregate_versions
      WHERE aggregate_type='information' AND scope_type='occasion'
      AND scope_id=p_occasion AND aggregate_id=v_id::text FOR UPDATE;
    SELECT jsonb_build_object('id',i.id,'title',i.title,'description',i.description,
      'type',i.type,'isHidden',i.is_hidden,'order',i."order",'data',i.data,
      'hiddenData',ih.data),i.is_hidden,i.information_hidden
      INTO v_current,v_old_is_hidden,v_old_hidden_id
    FROM public.information i LEFT JOIN public.information_hidden ih
      ON ih.id=i.information_hidden WHERE i.id=v_id;
    IF p_expected_version IS DISTINCT FROM v_version THEN
      RETURN public.complete_client_mutation_outcome_v1(p_command_id,
        'conflict',409,jsonb_build_object('version',v_version,'information',
          public.get_information_command_data_v1(v_id)));
    END IF;
  ELSIF p_expected_version IS NOT NULL THEN
    RAISE invalid_parameter_value USING MESSAGE='new information must not have expected version';
  END IF;

  IF v_current IS NOT DISTINCT FROM v_requested THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,
      'unchanged',200,jsonb_build_object('version',v_version,'information',
        public.get_information_command_data_v1(v_id)));
  END IF;

  IF p_information->>'type'='game' THEN
    IF v_old_hidden_id IS NULL THEN
      INSERT INTO public.information_hidden(data,occasion)
      VALUES (p_information->'hiddenData',p_occasion) RETURNING id INTO v_hidden_id;
    ELSE
      UPDATE public.information_hidden SET data=p_information->'hiddenData'
      WHERE id=v_old_hidden_id AND occasion=p_occasion RETURNING id INTO v_hidden_id;
      IF v_hidden_id IS NULL THEN
        RAISE invalid_parameter_value USING MESSAGE='cross-scope hidden information';
      END IF;
    END IF;
  END IF;
  IF v_id IS NULL THEN
    INSERT INTO public.information(title,description,type,is_hidden,"order",data,
      information_hidden,occasion)
    VALUES (p_information->>'title',p_information->>'description',
      p_information->>'type',v_new_is_hidden,(p_information->>'order')::bigint,
      p_information->'data',v_hidden_id,p_occasion) RETURNING id INTO v_id;
    v_version:=1;
    INSERT INTO public.client_aggregate_versions
      (aggregate_type,scope_type,scope_id,aggregate_id,version)
    VALUES ('information','occasion',p_occasion,v_id::text,v_version);
  ELSE
    UPDATE public.information SET title=p_information->>'title',
      description=p_information->>'description',type=p_information->>'type',
      is_hidden=v_new_is_hidden,"order"=(p_information->>'order')::bigint,
      data=p_information->'data',information_hidden=v_hidden_id,
      updated_at=clock_timestamp() WHERE id=v_id;
    UPDATE public.client_aggregate_versions SET version=version+1,
      updated_at=clock_timestamp() WHERE aggregate_type='information'
      AND scope_type='occasion' AND scope_id=p_occasion AND aggregate_id=v_id::text
      RETURNING version INTO v_version;
    IF v_old_hidden_id IS NOT NULL AND v_hidden_id IS NULL THEN
      DELETE FROM public.information_hidden WHERE id=v_old_hidden_id
        AND occasion=p_occasion;
    END IF;
  END IF;
  v_entity:=public.get_information_command_data_v1(v_id)||
    jsonb_build_object('aggregate_version',v_version);
  v_affects_public:=NOT COALESCE(v_old_is_hidden,true) OR NOT v_new_is_hidden;
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'content.information.save','content',jsonb_build_array(jsonb_build_object(
      'entityType','information','entityId',v_id,
      'operation',CASE WHEN v_current IS NULL THEN 'insert' ELSE 'update' END,
      'safeLabel',left(p_information->>'title',240),
      'changedFields',jsonb_build_array('aggregate'))),
    CASE WHEN v_is_publishable AND v_affects_public THEN ARRAY['content_catalog']
      ELSE '{}'::text[] END,'[]','[]',
    jsonb_build_object('version',v_version,'information',v_entity));
END; $function$

CREATE OR REPLACE FUNCTION public.save_inventory_pool_client_sync_v1(p_occasion bigint, p_command_id uuid, p_expected_version bigint, p_bundle jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_actor uuid:=auth.uid(); v_pool_id bigint:=(p_bundle#>>'{pool,id}')::bigint;
  v_version bigint; v_begin jsonb; v_hash text; v_result jsonb;
  v_commit jsonb; v_response jsonb; v_private_impacts jsonb;
  v_current_command_data jsonb; v_requested_command_data jsonb;
  v_product_ids bigint[]; v_product_id bigint;
  v_actor_private_revision bigint; v_actor_private_payload jsonb;
BEGIN
  IF v_actor IS NULL OR NOT public.get_is_editor_order_on_occasion(p_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion order editor required';
  END IF;
  IF p_bundle IS NULL OR jsonb_typeof(p_bundle)<>'object'
    OR octet_length(p_bundle::text)>1048576
    OR EXISTS (SELECT 1 FROM jsonb_object_keys(p_bundle) key
      WHERE key NOT IN ('pool','contexts'))
    OR jsonb_typeof(p_bundle->'pool')<>'object'
    OR EXISTS (SELECT 1 FROM jsonb_object_keys(p_bundle->'pool') key
      WHERE key NOT IN ('id','title','sellable_capacity','occasion',
        'description','type','data'))
    OR (p_bundle ? 'contexts' AND p_bundle->'contexts'<>'null'::jsonb AND jsonb_typeof(p_bundle->'contexts')<>'array')
    OR jsonb_array_length(CASE WHEN jsonb_typeof(p_bundle->'contexts')='array' THEN p_bundle->'contexts' ELSE '[]'::jsonb END)>2000
    OR (p_bundle#>>'{pool,occasion}')::bigint IS DISTINCT FROM p_occasion
    OR (v_pool_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.inventory_pools ip
      WHERE ip.id=v_pool_id AND ip.occasion=p_occasion))
    OR EXISTS (SELECT 1 FROM jsonb_array_elements(CASE WHEN jsonb_typeof(p_bundle->'contexts')='array' THEN p_bundle->'contexts' ELSE '[]'::jsonb END) c
      WHERE jsonb_typeof(c)<>'object' OR EXISTS (
        SELECT 1 FROM jsonb_object_keys(c) key
        WHERE key NOT IN ('id','inventory_pool','block_date','title','order','data'))
      OR ((c->>'id') IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM public.inventory_contexts ic
        WHERE ic.id=(c->>'id')::bigint AND ic.inventory_pool=v_pool_id))) THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid or cross-scope inventory aggregate';
  END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object('occasion',p_occasion,
    'expectedVersion',p_expected_version,'bundle',p_bundle)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'inventory.pool.save',
    p_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;

  IF v_pool_id IS NOT NULL THEN
    v_product_ids:=public.lock_pool_product_dependencies_internal_v1(v_pool_id);
    PERFORM 1 FROM public.inventory_pools ip WHERE ip.id=v_pool_id
      AND ip.occasion=p_occasion FOR UPDATE;
    INSERT INTO public.client_aggregate_versions
      (aggregate_type,scope_type,scope_id,aggregate_id,version)
    VALUES ('inventory_pool','occasion',p_occasion,v_pool_id::text,0)
    ON CONFLICT DO NOTHING;
    SELECT version INTO v_version FROM public.client_aggregate_versions
      WHERE aggregate_type='inventory_pool' AND scope_type='occasion'
        AND scope_id=p_occasion AND aggregate_id=v_pool_id::text FOR UPDATE;
    IF p_expected_version IS DISTINCT FROM v_version THEN
      v_response:=jsonb_build_object('status','conflict','code',409,
        'data',jsonb_build_object('version',v_version,
          'bundle',public.get_inventory_pool_bundle(v_pool_id)),
        'mutation',jsonb_build_object('commandId',p_command_id,'receiptId',p_command_id,
          'commitId',NULL,'replayed',false,'occurredAt',clock_timestamp()),
        'sync',jsonb_build_object('replacements','[]'::jsonb));
      RETURN public.finish_client_mutation_v1(p_command_id,v_response,NULL);
    END IF;

    IF NOT p_bundle ? 'contexts' OR p_bundle->'contexts'='null'::jsonb THEN
      p_bundle:=jsonb_set(p_bundle,'{contexts}',coalesce((SELECT jsonb_agg(jsonb_build_object(
        'id',ic.id,'inventory_pool',ic.inventory_pool,'block_date',ic.block_date,'title',ic.title,'order',ic."order",'data',ic.data)
        ORDER BY ic."order",ic.id) FROM public.inventory_contexts ic WHERE ic.inventory_pool=v_pool_id),'[]'));
    END IF;
    SELECT jsonb_build_object(
      'pool',jsonb_build_object('id',ip.id,'title',ip.title,
        'sellable_capacity',ip.sellable_capacity,'occasion',ip.occasion,
        'description',ip.description,'type',ip.type,'data',ip.data),
      'contexts',COALESCE((SELECT jsonb_agg(jsonb_build_object(
        'id',ic.id,'inventory_pool',ic.inventory_pool,
        'block_date',ic.block_date,'title',ic.title,'order',ic."order",
        'data',ic.data) ORDER BY ic."order",ic.id)
        FROM public.inventory_contexts ic
        WHERE ic.inventory_pool=ip.id),'[]'::jsonb))
      INTO v_current_command_data
    FROM public.inventory_pools ip WHERE ip.id=v_pool_id;
    SELECT jsonb_build_object(
      'pool',jsonb_build_object('id',(p_bundle#>>'{pool,id}')::bigint,
        'title',p_bundle#>>'{pool,title}',
        'sellable_capacity',(p_bundle#>>'{pool,sellable_capacity}')::bigint,
        'occasion',(p_bundle#>>'{pool,occasion}')::bigint,
        'description',p_bundle#>>'{pool,description}',
        'type',p_bundle#>>'{pool,type}','data',p_bundle#>'{pool,data}'),
      'contexts',COALESCE((SELECT jsonb_agg(jsonb_build_object(
        'id',(c->>'id')::bigint,'inventory_pool',v_pool_id,
        'block_date',(c->>'block_date')::date,'title',c->>'title',
        'order',(c->>'order')::bigint,'data',c->'data')
        ORDER BY (c->>'order')::bigint,(c->>'id')::bigint)
        FROM jsonb_array_elements(CASE WHEN jsonb_typeof(p_bundle->'contexts')='array' THEN p_bundle->'contexts' ELSE '[]'::jsonb END) c),'[]'::jsonb))
      INTO v_requested_command_data;
    IF v_current_command_data = v_requested_command_data THEN
      v_response:=jsonb_build_object('status','unchanged','code',200,
        'data',jsonb_build_object('version',v_version,
          'bundle',public.get_inventory_pool_bundle(v_pool_id)),
        'mutation',jsonb_build_object('commandId',p_command_id,
          'receiptId',p_command_id,'commitId',NULL,'replayed',false,
          'occurredAt',clock_timestamp()),
        'sync',jsonb_build_object('replacements','[]'::jsonb));
      RETURN public.finish_client_mutation_v1(p_command_id,v_response,NULL);
    END IF;
  ELSIF p_expected_version IS NOT NULL THEN
    RAISE invalid_parameter_value USING MESSAGE='new inventory pool must not have expected version';
  END IF;

  IF NOT p_bundle ? 'contexts' OR p_bundle->'contexts'='null'::jsonb THEN
    p_bundle:=jsonb_set(p_bundle,'{contexts}','[]'); END IF;
  v_result:=public.update_inventory_pool_bundle_internal_v1(p_bundle);
  FOREACH v_product_id IN ARRAY coalesce(v_product_ids,'{}'::bigint[]) LOOP
    PERFORM public.advance_ticketing_authoring_version_internal_v1('product',p_occasion,v_product_id);
  END LOOP;
  IF v_result ? 'code' AND COALESCE((v_result->>'code')::integer,500)<>200 THEN
    RAISE EXCEPTION 'inventory aggregate handler failed: %',v_result->>'message';
  END IF;
  v_pool_id:=(v_result#>>'{pool,id}')::bigint;
  IF v_pool_id IS NULL THEN RAISE EXCEPTION 'inventory handler returned no pool id'; END IF;
  IF v_version IS NULL THEN
    v_version:=1;
    INSERT INTO public.client_aggregate_versions
      (aggregate_type,scope_type,scope_id,aggregate_id,version)
    VALUES ('inventory_pool','occasion',p_occasion,v_pool_id::text,v_version);
  ELSE
    UPDATE public.client_aggregate_versions SET version=version+1,
      updated_at=clock_timestamp() WHERE aggregate_type='inventory_pool'
      AND scope_type='occasion' AND scope_id=p_occasion AND aggregate_id=v_pool_id::text
      RETURNING version INTO v_version;
  END IF;
  SELECT COALESCE(jsonb_agg(jsonb_build_object('component','private_inventory',
    'userId',ou."user")),'[]'::jsonb) INTO v_private_impacts
    FROM public.occasion_users ou WHERE ou.occasion=p_occasion;
  v_commit:=public.record_client_sync_commit_v1(p_occasion,'inventory.pool.save',
    'inventory',jsonb_build_array(jsonb_build_object('entityType','inventory_pool',
      'entityId',v_pool_id,'operation',CASE WHEN (p_bundle#>>'{pool,id}') IS NULL
        THEN 'insert' ELSE 'update' END,'safeLabel',left(v_result#>>'{pool,title}',240),
      'changedFields',jsonb_build_array('aggregate'))),'{}',v_private_impacts,
    '[]','user',NULL);
  SELECT s.source_revision INTO STRICT v_actor_private_revision
  FROM public.client_sync_private_scopes s
  WHERE s.component='private_inventory' AND s.occasion=p_occasion
    AND s.user_id=v_actor;
  v_actor_private_payload:=public.get_user_inventory_for_occasion_v1(p_occasion);
  v_result:=v_result||jsonb_build_object('aggregate_version',v_version);
  v_response:=jsonb_build_object('status','applied','code',200,
    'data',jsonb_build_object('version',v_version,'bundle',v_result),
    'mutation',jsonb_build_object('commandId',p_command_id,'receiptId',p_command_id,
      'commitId',v_commit->>'commitId','replayed',false,'occurredAt',v_commit->>'occurredAt'),
    'sync',jsonb_build_object('replacements',jsonb_build_array(
      jsonb_build_object('component','private_inventory',
        'revision',v_actor_private_revision,'payload',v_actor_private_payload))));
  RETURN public.finish_client_mutation_v1(p_command_id,v_response,
    (v_commit->>'commitId')::uuid);
END; $function$

CREATE OR REPLACE FUNCTION public.save_news_client_sync_v1(p_occasion bigint, p_command_id uuid, p_expected_version bigint, p_news jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_actor uuid:=auth.uid(); v_id bigint; v_version bigint; v_begin jsonb;
  v_hash text; v_current jsonb; v_entity jsonb; v_is_publishable boolean;
BEGIN
  IF v_actor IS NULL OR NOT public.get_is_editor_on_occasion(p_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion editor required';
  END IF;
  SELECT NOT o.is_hidden INTO v_is_publishable FROM public.occasions o
    WHERE o.id=p_occasion;
  IF v_is_publishable IS NULL THEN
    RAISE invalid_parameter_value USING MESSAGE='occasion not found';
  END IF;
  IF p_news IS NULL OR jsonb_typeof(p_news)<>'object'
    OR EXISTS (SELECT 1 FROM jsonb_object_keys(p_news) key
      WHERE key NOT IN ('id','message'))
    OR NOT (p_news ? 'message')
    OR octet_length(COALESCE(p_news->>'message','')) NOT BETWEEN 1 AND 524288 THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid news';
  END IF;
  v_id:=(p_news->>'id')::bigint;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'occasion',p_occasion,'expectedVersion',p_expected_version,
    'news',p_news)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'content.news.save',
    p_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  IF v_id IS NOT NULL THEN
    SELECT jsonb_build_object('id',n.id,'message',n.message) INTO v_current
    FROM public.news n WHERE n.id=v_id AND n.occasion=p_occasion FOR UPDATE;
    IF v_current IS NULL THEN
      RETURN public.complete_client_mutation_outcome_v1(p_command_id,
        'rejected',404,jsonb_build_object('version',0,'news',NULL));
    END IF;
    INSERT INTO public.client_aggregate_versions
      (aggregate_type,scope_type,scope_id,aggregate_id,version)
    VALUES ('news','occasion',p_occasion,v_id::text,0) ON CONFLICT DO NOTHING;
    SELECT version INTO v_version FROM public.client_aggregate_versions
      WHERE aggregate_type='news' AND scope_type='occasion'
      AND scope_id=p_occasion AND aggregate_id=v_id::text FOR UPDATE;
    IF p_expected_version IS DISTINCT FROM v_version THEN
      SELECT to_jsonb(n)||jsonb_build_object('aggregate_version',v_version)
        INTO v_entity FROM public.news n WHERE n.id=v_id;
      RETURN public.complete_client_mutation_outcome_v1(p_command_id,
        'conflict',409,jsonb_build_object('version',v_version,'news',v_entity));
    END IF;
    IF v_current=jsonb_build_object('id',v_id,'message',p_news->>'message') THEN
      SELECT to_jsonb(n)||jsonb_build_object('aggregate_version',v_version)
        INTO v_entity FROM public.news n WHERE n.id=v_id;
      RETURN public.complete_client_mutation_outcome_v1(p_command_id,
        'unchanged',200,jsonb_build_object('version',v_version,'news',v_entity));
    END IF;
    UPDATE public.news SET message=p_news->>'message',updated_at=clock_timestamp()
      WHERE id=v_id;
    UPDATE public.client_aggregate_versions SET version=version+1,
      updated_at=clock_timestamp() WHERE aggregate_type='news'
      AND scope_type='occasion' AND scope_id=p_occasion AND aggregate_id=v_id::text
      RETURNING version INTO v_version;
  ELSE
    IF p_expected_version IS NOT NULL THEN
      RAISE invalid_parameter_value USING MESSAGE='new news must not have expected version';
    END IF;
    INSERT INTO public.news(message,created_by,occasion)
    VALUES (p_news->>'message',v_actor,p_occasion) RETURNING id INTO v_id;
    v_version:=1;
    INSERT INTO public.client_aggregate_versions
      (aggregate_type,scope_type,scope_id,aggregate_id,version)
    VALUES ('news','occasion',p_occasion,v_id::text,v_version);
  END IF;
  SELECT to_jsonb(n)||jsonb_build_object('aggregate_version',v_version)
    INTO v_entity FROM public.news n WHERE n.id=v_id;
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'content.news.save','content',jsonb_build_array(jsonb_build_object(
      'entityType','news','entityId',v_id,
      'operation',CASE WHEN v_current IS NULL THEN 'insert' ELSE 'update' END,
      'safeLabel','News','changedFields',jsonb_build_array('message'))),
    CASE WHEN v_is_publishable THEN ARRAY['content_catalog'] ELSE '{}'::text[] END,
    '[]','[]',jsonb_build_object('version',v_version,'news',v_entity));
END; $function$

CREATE OR REPLACE FUNCTION public.save_occasion_client_sync_v1(p_occasion bigint, p_command_id uuid, p_expected_version bigint, p_config jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_config jsonb;
  v_data jsonb;
  v_enabled boolean;
  v_hidden boolean;
  v_unit bigint;
BEGIN
  SELECT
    COALESCE((o.data->>'client_sync_v1')::boolean, false),
    o.is_hidden,
    o.unit
  INTO v_enabled, v_hidden, v_unit
  FROM public.occasions o
  WHERE o.id = p_occasion;

  IF auth.uid() IS NULL OR NOT (
    public.get_is_editor_on_occasion(p_occasion)
    OR public.get_is_admin_on_occasion(p_occasion)
    OR (v_unit IS NOT NULL AND public.get_is_editor_on_unit(v_unit))
  ) THEN
    RAISE insufficient_privilege USING MESSAGE = 'occasion editor required';
  END IF;

  IF v_enabled
    AND NOT v_hidden
    AND COALESCE((p_config->>'is_hidden')::boolean, false)
  THEN
    RAISE object_not_in_prerequisite_state
      USING MESSAGE = 'disable client_sync_v1 before hiding occasion';
  END IF;

  -- A layout-only command must not manufacture data/features or run general settings effects.
  IF p_config ? 'ticket_layout_change' AND p_config - ARRAY['id','ticket_layout_change']='{}'::jsonb THEN
    IF NOT public.can_edit_ticket_layout(p_occasion) THEN
      RAISE insufficient_privilege USING MESSAGE='unit editor required';
    END IF;
    RETURN public.save_occasion_domain_command_internal_v1(
      p_occasion,p_command_id,p_expected_version,p_config);
  END IF;

  v_data := CASE
    WHEN jsonb_typeof(p_config->'data') = 'object' THEN p_config->'data'
    ELSE '{}'::jsonb
  END;
  v_config := jsonb_set(
    p_config,
    '{data}',
    jsonb_set(
      v_data,
      '{client_sync_v1}',
      to_jsonb(COALESCE(v_enabled, false)),
      true
    ),
    true
  );

  RETURN public.save_occasion_domain_command_internal_v1(
    p_occasion,
    p_command_id,
    p_expected_version,
    v_config
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.save_occasion_domain_command_internal_v1(p_occasion bigint, p_command_id uuid, p_expected_version bigint, p_config jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_version bigint;
  v_begin jsonb;
  v_hash text;
  v_entity jsonb;
  v_old_hidden boolean;
  v_new_hidden boolean;
  v_old_unit bigint;
  v_new_unit bigint;
  v_features jsonb;
  v_fanout_units bigint[] := '{}';
BEGIN
  SELECT o.unit INTO v_old_unit
  FROM public.occasions o
  WHERE o.id = p_occasion;

  IF v_actor IS NULL OR NOT (
    public.get_is_editor_on_occasion(p_occasion)
    OR public.get_is_admin_on_occasion(p_occasion)
    OR (v_old_unit IS NOT NULL AND public.get_is_editor_on_unit(v_old_unit))
  ) THEN
    RAISE insufficient_privilege USING MESSAGE = 'occasion editor required';
  END IF;

  IF p_config IS NULL OR jsonb_typeof(p_config) <> 'object'
    OR octet_length(p_config::text) > 1048576
    OR (p_config->>'id')::bigint IS DISTINCT FROM p_occasion
    OR EXISTS (
      SELECT 1
      FROM jsonb_object_keys(p_config) key
      WHERE key NOT IN (
        'id', 'start_time', 'end_time', 'is_open', 'is_hidden', 'is_promoted',
        'link', 'title', 'description', 'data', 'services', 'organization',
        'unit', 'features', 'form_link', 'has_orders', 'stats', 'ticket_layout_change'
      )
    )
  THEN
    RAISE invalid_parameter_value USING MESSAGE = 'invalid occasion aggregate';
  END IF;

  v_hash := encode(extensions.digest(convert_to(jsonb_build_object(
    'occasion', p_occasion,
    'expectedVersion', p_expected_version,
    'config', p_config
  )::text, 'UTF8'), 'sha256'), 'hex');
  v_begin := public.begin_client_mutation_v1(
    p_command_id,
    'occasion.config.save',
    p_occasion,
    v_actor,
    v_hash
  );
  IF v_begin->>'disposition' = 'replay' THEN
    RETURN v_begin->'response';
  END IF;

  IF NOT (p_config ? 'ticket_layout_change' AND p_config-ARRAY['id','ticket_layout_change']='{}'::jsonb) THEN
    PERFORM 1 FROM public.forms WHERE occasion=p_occasion ORDER BY id FOR UPDATE;
  END IF;

  SELECT o.is_hidden, o.unit INTO v_old_hidden, v_old_unit
  FROM public.occasions o
  WHERE o.id = p_occasion
  FOR UPDATE;
  IF NOT FOUND THEN
    RETURN public.complete_client_mutation_outcome_v1(
      p_command_id,
      'rejected',
      404,
      jsonb_build_object('version', 0, 'occasion', NULL)
    );
  END IF;

  INSERT INTO public.client_aggregate_versions(
    aggregate_type, scope_type, scope_id, aggregate_id, version
  ) VALUES ('occasion', 'occasion', p_occasion, p_occasion::text, 0)
  ON CONFLICT DO NOTHING;
  SELECT version INTO v_version
  FROM public.client_aggregate_versions
  WHERE aggregate_type = 'occasion'
    AND scope_type = 'occasion'
    AND scope_id = p_occasion
    AND aggregate_id = p_occasion::text
  FOR UPDATE;
  IF p_expected_version IS DISTINCT FROM v_version THEN
    SELECT to_jsonb(o) || jsonb_build_object('aggregate_version', v_version)
    INTO v_entity
    FROM public.occasions o
    WHERE o.id = p_occasion;
    RETURN public.complete_client_mutation_outcome_v1(
      p_command_id,
      'conflict',
      409,
      jsonb_build_object('version', v_version, 'occasion', v_entity)
    );
  END IF;

  IF p_config ? 'ticket_layout_change' AND p_config - ARRAY['id','ticket_layout_change']='{}'::jsonb THEN
    IF NOT public.can_edit_ticket_layout(p_occasion) THEN
      RAISE insufficient_privilege USING MESSAGE='unit editor required';
    END IF;
    SELECT features INTO v_features FROM public.occasions WHERE id=p_occasion;
    v_features:=public.merge_ticket_layout_features(v_features,v_features,p_config->'ticket_layout_change');
    v_features:=public.merge_ticket_appearance_internal_v1(p_occasion,v_features,p_config#>'{ticket_layout_change,appearance}');
    PERFORM public.validate_ticket_layout_references(p_occasion,f->'layout')
      FROM jsonb_array_elements(v_features) f WHERE f->>'code'='ticket' AND f ? 'layout';
    UPDATE public.occasions SET features=v_features,updated_at=clock_timestamp() WHERE id=p_occasion;
  ELSE
    PERFORM public.update_occasion_internal_v1(p_config);
  END IF;
  UPDATE public.client_aggregate_versions
  SET version = version + 1, updated_at = clock_timestamp()
  WHERE aggregate_type = 'occasion'
    AND scope_type = 'occasion'
    AND scope_id = p_occasion
    AND aggregate_id = p_occasion::text
  RETURNING version INTO v_version;
  SELECT to_jsonb(o) || jsonb_build_object('aggregate_version', v_version)
  INTO v_entity
  FROM public.occasions o
  WHERE o.id = p_occasion;

  v_new_hidden := (v_entity->>'is_hidden')::boolean;
  v_new_unit := (v_entity->>'unit')::bigint;
  IF NOT v_old_hidden THEN
    v_fanout_units := array_append(v_fanout_units, v_old_unit);
  END IF;
  IF NOT v_new_hidden AND v_new_unit IS DISTINCT FROM v_old_unit THEN
    v_fanout_units := array_append(v_fanout_units, v_new_unit);
  ELSIF NOT v_new_hidden AND v_old_hidden THEN
    v_fanout_units := array_append(v_fanout_units, v_new_unit);
  END IF;

  RETURN public.complete_client_mutation_applied_v1(
    p_command_id,
    p_occasion,
    'occasion.config.save',
    'configuration',
    jsonb_build_array(jsonb_build_object(
      'entityType', 'occasion',
      'entityId', p_occasion,
      'operation', 'update',
      'safeLabel', left(v_entity->>'title', 240),
      'changedFields', jsonb_build_array('configuration')
    )),
    CASE WHEN v_old_hidden AND NOT v_new_hidden THEN ARRAY[
      'occasion_config', 'program_catalog', 'map_catalog', 'content_catalog',
      'live_public'
    ] ELSE ARRAY['occasion_config'] END,
    '[]',
    '[]',
    jsonb_build_object('version', v_version, 'occasion', v_entity),
    CASE WHEN NOT v_new_hidden THEN ARRAY['occasion_config'] ELSE '{}'::text[] END,
    '[]',
    'user',
    NULL,
    '[]',
    v_fanout_units
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.save_occasion_legacy_facade_internal_v1(input_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE oc bigint; version bigint; old_features jsonb; next_features jsonb;
 old_ticket jsonb; next_ticket jsonb;
BEGIN
 IF auth.uid() IS NULL THEN RAISE insufficient_privilege USING MESSAGE='authenticated user required'; END IF;
 oc:=nullif(input_data->>'id','')::bigint;
 IF oc IS NULL THEN
  RETURN public.create_occasion_client_sync_v1(extensions.gen_random_uuid(),input_data);
 END IF;
 IF NOT public.can_edit_ticket_layout(oc) THEN
  RAISE insufficient_privilege USING MESSAGE='unit editor required'; END IF;
 -- Same form -> occasion ordering as the canonical general-settings command.
 PERFORM 1 FROM public.forms WHERE occasion=oc ORDER BY id FOR UPDATE;
 SELECT features INTO old_features FROM public.occasions WHERE id=oc FOR UPDATE;
 IF input_data ? 'ticket_layout_change' THEN
  RAISE serialization_failure USING MESSAGE='ticket_layout_editor_upgrade_required'; END IF;
 next_features:=public.merge_ticket_layout_features(old_features,coalesce(input_data->'features','[]'::jsonb));
 SELECT value INTO old_ticket FROM jsonb_array_elements(old_features) WHERE value->>'code'='ticket';
 SELECT value INTO next_ticket FROM jsonb_array_elements(next_features) WHERE value->>'code'='ticket';
 IF jsonb_build_object('background',nullif(old_ticket->>'background',''),
       'ticket_type',coalesce(old_ticket->>'ticket_type','wide'))
    IS DISTINCT FROM jsonb_build_object('background',nullif(next_ticket->>'background',''),
       'ticket_type',coalesce(next_ticket->>'ticket_type','wide')) THEN
  RAISE serialization_failure USING MESSAGE='ticket_layout_editor_upgrade_required'; END IF;
 SELECT coalesce(v.version,0) INTO version FROM (SELECT 1) seed
 LEFT JOIN public.client_aggregate_versions v ON v.aggregate_type='occasion'
 AND v.scope_type='occasion' AND v.scope_id=oc AND v.aggregate_id=oc::text;
 RETURN public.save_occasion_client_sync_v1(oc,extensions.gen_random_uuid(),version,input_data);
END $function$

CREATE OR REPLACE FUNCTION public.save_occasion_setup_draft(p_id uuid, p_expected_revision bigint, p_data jsonb, p_step integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE d public.occasion_setup_drafts;
BEGIN
  SELECT * INTO d FROM public.occasion_setup_drafts WHERE id = p_id FOR UPDATE;
  IF NOT FOUND OR auth.uid() IS NULL OR NOT (public.get_is_editor_on_unit(d.unit) OR public.get_is_manager_on_unit(d.unit)) THEN
    RAISE EXCEPTION 'Draft access denied' USING ERRCODE = '42501';
  END IF;
  IF d.data ? 'finalizedOccasion' THEN RAISE invalid_parameter_value USING MESSAGE='Draft already finalized'; END IF;
  p_data := p_data - 'finalizedOccasion' - 'finalizeResponse';
  IF p_data IS NULL OR jsonb_typeof(p_data) <> 'object' OR octet_length(p_data::text) > 262144 OR p_step IS NULL OR p_step NOT BETWEEN 0 AND 6 THEN
    RAISE EXCEPTION 'Invalid draft' USING ERRCODE = '22023'; END IF;
  IF d.data ? 'copy_locale' THEN p_data := jsonb_set(p_data,'{copy_locale}',d.data->'copy_locale'); END IF;
  IF p_data ? 'copy_locale' AND p_data->>'sourceId' IS NOT NULL
     AND coalesce((p_data->>'copy_title_edited')::boolean,false)=false AND coalesce(p_data->>'title','')='' THEN
    IF NOT public.can_copy_occasion_source((p_data->>'sourceId')::bigint) OR NOT EXISTS(SELECT 1 FROM public.occasions WHERE id=(p_data->>'sourceId')::bigint AND organization=d.organization) THEN
      RAISE insufficient_privilege USING MESSAGE='Copy source denied'; END IF;
    IF d.revision=p_expected_revision+1 AND d.data->>'sourceId'=p_data->>'sourceId' THEN
      p_data := jsonb_set(p_data,'{title}',d.data->'title');
    ELSE
      p_data := jsonb_set(p_data,'{title}',to_jsonb(public.copy_occasion_title_internal(
        (SELECT title FROM public.occasions WHERE id=(p_data->>'sourceId')::bigint),p_data->>'copy_locale')));
    END IF;
  END IF;
  IF d.revision = p_expected_revision + 1 AND d.data = p_data AND d.current_step = p_step THEN RETURN to_jsonb(d); END IF;
  IF d.revision IS DISTINCT FROM p_expected_revision THEN
    RAISE EXCEPTION 'Draft changed in another session' USING ERRCODE = '40001'; END IF;
  PERFORM public.admit_occasion_draft_v1(auth.uid(),d.unit,d.organization,octet_length(p_data::text),false,false);
  UPDATE public.occasion_setup_drafts SET data = p_data, current_step = p_step,
    revision = revision + 1, updated_at = now() WHERE id = p_id RETURNING * INTO d;
  RETURN to_jsonb(d);
END $function$

CREATE OR REPLACE FUNCTION public.save_occasion_user_for_edit(input_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE oc bigint:=(input_data->>'occasion')::bigint; usr uuid:=(input_data->>'user')::uuid; ver bigint; r jsonb;
BEGIN
 IF auth.uid() IS NULL OR NOT(public.get_is_manager_on_occasion(oc) OR public.get_is_admin_on_occasion(oc)) THEN RETURN jsonb_build_object('code',403); END IF;
 PERFORM 1 FROM public.user_info WHERE id=usr FOR UPDATE;
 PERFORM 1 FROM public.occasion_users WHERE occasion=oc AND "user"=usr FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('code',404); END IF;
 SELECT coalesce(v.version,0) INTO ver FROM (SELECT 1) seed LEFT JOIN public.client_aggregate_versions v
 ON v.aggregate_type='occasion_user' AND v.scope_type='occasion' AND v.scope_id=oc AND v.aggregate_id=usr::text;
 input_data:=jsonb_set(input_data,'{data}',CASE WHEN jsonb_typeof(input_data->'data')='object' THEN (input_data->'data')-'is_invited' ELSE '{}' END);
 r:=public.save_profile_client_sync_v1(oc,usr,extensions.gen_random_uuid(),ver,input_data);
 RETURN jsonb_build_object('code',r->'code','message',r#>'{data,message}');
END $function$

CREATE OR REPLACE FUNCTION public.save_place_location(p_place_id bigint, p_lat double precision, p_lng double precision)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE oc bigint; version bigint; result jsonb;
BEGIN
 IF auth.uid() IS NULL THEN RETURN jsonb_build_object('code',401); END IF;
 SELECT occasion INTO oc FROM public.places WHERE id=p_place_id;
 IF NOT FOUND THEN RETURN jsonb_build_object('code',404); END IF;
 IF NOT (public.get_is_editor_on_occasion(oc) OR EXISTS(
  SELECT 1 FROM public.user_groups m JOIN public.user_group_info g ON g.id=m."group"
  JOIN public.places p ON p.id=g.place AND p.type='group' AND p.is_hidden
  WHERE g.place=p_place_id AND g.occasion=oc AND m."user"=auth.uid() AND m.is_admin)) THEN
  RETURN jsonb_build_object('code',403); END IF;
 PERFORM public.lock_group_occasion_internal_v1(oc);
 SELECT coalesce(v.version,0) INTO version FROM (SELECT 1) seed LEFT JOIN public.client_aggregate_versions v
 ON v.aggregate_type='place' AND v.scope_type='occasion' AND v.scope_id=oc AND v.aggregate_id=p_place_id::text;
 BEGIN
  result:=public.move_place_client_sync_v1(oc,p_place_id,extensions.gen_random_uuid(),version,p_lat,p_lng);
 EXCEPTION WHEN insufficient_privilege THEN RETURN jsonb_build_object('code',403); END;
 RETURN jsonb_build_object('code',result->'code','data',jsonb_build_object('id',p_place_id));
END $function$

CREATE OR REPLACE FUNCTION public.save_product_price_change(p_product_id bigint, p_price numeric, p_change_time timestamp with time zone, p_change_id bigint DEFAULT NULL::bigint, p_expected_revision bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_product eshop.products%ROWTYPE; v_change eshop.planned_changes%ROWTYPE; v_occasion bigint;
BEGIN
  SELECT p.* INTO STRICT v_product FROM eshop.products p WHERE p.id=p_product_id FOR UPDATE;
  SELECT pt.occasion INTO STRICT v_occasion FROM eshop.product_types pt WHERE pt.id=v_product.product_type;
  IF auth.uid() IS NULL OR NOT EXISTS (SELECT 1 FROM public.occasions o JOIN public.user_info ui
    ON ui.organization=o.organization WHERE o.id=v_occasion AND ui.id=auth.uid()) THEN
    RAISE insufficient_privilege USING MESSAGE='ORDER_EDITOR_REQUIRED'; END IF;
  PERFORM public.check_is_editor_order_on_occasion(v_occasion);
  IF v_product.occasion IS DISTINCT FROM v_occasion THEN RAISE EXCEPTION 'PRODUCT_OCCASION_MISMATCH'; END IF;
  PERFORM public.validate_product_price(p_price,v_product.data,v_product.currency_code);
  IF p_change_time IS NULL OR NOT isfinite(p_change_time) OR p_change_time <= clock_timestamp() THEN
    RAISE invalid_parameter_value USING MESSAGE='FUTURE_TIME_REQUIRED'; END IF;
  IF p_change_id IS NULL THEN
    IF p_expected_revision IS NOT NULL THEN RAISE invalid_parameter_value USING MESSAGE='INVALID_REVISION'; END IF;
    INSERT INTO eshop.planned_changes(change_type,subject_id,new_value,change_time,occasion)
    VALUES ('products.price',p_product_id,p_price::text,p_change_time,v_occasion) RETURNING * INTO v_change;
  ELSE
    SELECT * INTO v_change FROM eshop.planned_changes WHERE id=p_change_id FOR UPDATE;
    IF NOT FOUND OR v_change.subject_id<>p_product_id OR v_change.change_type<>'products.price'
      OR v_change.applied OR v_change.revision IS DISTINCT FROM p_expected_revision THEN
      RAISE serialization_failure USING MESSAGE='PRICE_CHANGE_CONFLICT'; END IF;
    UPDATE eshop.planned_changes SET new_value=p_price::text,change_time=p_change_time,
      occasion=v_occasion,revision=revision+1,failed_at=NULL,failure_code=NULL,
      wave_id=CASE WHEN change_time=p_change_time THEN wave_id ELSE NULL END
      WHERE id=p_change_id RETURNING * INTO v_change;
  END IF;
  RETURN to_jsonb(v_change);
END; $function$

CREATE OR REPLACE FUNCTION public.save_product_wave_target(p_wave_id bigint, p_product_id bigint, p_expected_wave_revision bigint, p_price numeric, p_is_hidden boolean, p_expected_price_revision bigint DEFAULT NULL::bigint, p_expected_visibility_revision bigint DEFAULT NULL::bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_wave eshop.product_price_waves%ROWTYPE; v_product eshop.products%ROWTYPE;
  v_price eshop.planned_changes%ROWTYPE; v_visibility eshop.planned_changes%ROWTYPE;
BEGIN
  SELECT * INTO STRICT v_wave FROM eshop.product_price_waves WHERE id=p_wave_id FOR UPDATE;
  PERFORM public.check_product_wave_editor(v_wave.occasion);
  IF v_wave.revision IS DISTINCT FROM p_expected_wave_revision THEN RAISE serialization_failure USING MESSAGE='PRICE_CHANGE_CONFLICT'; END IF;
  IF v_wave.change_time<=clock_timestamp() THEN RAISE invalid_parameter_value USING MESSAGE='FUTURE_TIME_REQUIRED'; END IF;
  SELECT * INTO STRICT v_product FROM eshop.products WHERE id=p_product_id FOR UPDATE;
  IF v_product.occasion IS DISTINCT FROM v_wave.occasion OR NOT EXISTS(
    SELECT 1 FROM eshop.product_types WHERE id=v_product.product_type AND occasion=v_wave.occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='PRODUCT_OCCASION_MISMATCH'; END IF;
  IF v_wave.change_time<=clock_timestamp() THEN RAISE invalid_parameter_value USING MESSAGE='FUTURE_TIME_REQUIRED'; END IF;
  -- Lock in the same subject/plan order as the executor and single-product editor.
  PERFORM 1 FROM eshop.planned_changes WHERE subject_id=p_product_id AND wave_id=p_wave_id
    AND NOT applied ORDER BY id FOR UPDATE;
  SELECT * INTO v_price FROM eshop.planned_changes WHERE subject_id=p_product_id
    AND wave_id=p_wave_id AND change_type='products.price' AND NOT applied;
  SELECT * INTO v_visibility FROM eshop.planned_changes WHERE subject_id=p_product_id
    AND wave_id=p_wave_id AND change_type='products.is_hidden' AND NOT applied;
  IF v_price.revision IS DISTINCT FROM p_expected_price_revision OR
    v_visibility.revision IS DISTINCT FROM p_expected_visibility_revision THEN
    RAISE serialization_failure USING MESSAGE='PRICE_CHANGE_CONFLICT'; END IF;
  -- Seat products must not become unorderable while seats remain selectable.
  -- Keep an existing target on a price-only save; NULL explicitly cancels it.
  IF p_is_hidden IS NOT NULL AND EXISTS (
    SELECT 1 FROM eshop.spots s WHERE s.product=p_product_id AND s.occasion=v_wave.occasion
  ) AND (v_visibility.id IS NULL OR v_visibility.new_value IS DISTINCT FROM p_is_hidden::text) THEN
    RAISE invalid_parameter_value USING MESSAGE='BLUEPRINT_PRODUCT_VISIBILITY_NOT_SUPPORTED';
  END IF;
  IF EXISTS(SELECT 1 FROM eshop.planned_changes WHERE subject_id=p_product_id
    AND change_time=v_wave.change_time AND NOT applied AND wave_id IS DISTINCT FROM p_wave_id
    AND ((change_type='products.price' AND p_price IS NOT NULL) OR
         (change_type='products.is_hidden' AND p_is_hidden IS NOT NULL))) THEN
    RAISE serialization_failure USING MESSAGE='PRICE_CHANGE_CONFLICT'; END IF;
  IF p_price IS NOT NULL THEN
    PERFORM public.validate_product_price(p_price,v_product.data,v_product.currency_code);
    IF v_price.id IS NULL THEN
      INSERT INTO eshop.planned_changes(change_type,subject_id,new_value,change_time,occasion,wave_id)
        VALUES('products.price',p_product_id,p_price::text,v_wave.change_time,v_wave.occasion,p_wave_id);
    ELSE
      UPDATE eshop.planned_changes SET new_value=p_price::text,failed_at=NULL,failure_code=NULL,revision=revision+1 WHERE id=v_price.id;
    END IF;
  ELSIF v_price.id IS NOT NULL THEN DELETE FROM eshop.planned_changes WHERE id=v_price.id;
  END IF;
  IF p_is_hidden IS NOT NULL THEN
    IF v_visibility.id IS NULL THEN
      INSERT INTO eshop.planned_changes(change_type,subject_id,new_value,change_time,occasion,wave_id)
        VALUES('products.is_hidden',p_product_id,p_is_hidden::text,v_wave.change_time,v_wave.occasion,p_wave_id);
    ELSE
      UPDATE eshop.planned_changes SET new_value=p_is_hidden::text,failed_at=NULL,failure_code=NULL,revision=revision+1 WHERE id=v_visibility.id;
    END IF;
  ELSIF v_visibility.id IS NOT NULL THEN DELETE FROM eshop.planned_changes WHERE id=v_visibility.id;
  END IF;
END; $function$

CREATE OR REPLACE FUNCTION public.save_product_wave_target_client_sync_v1(p_target jsonb, p_command_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE oc bigint; actor uuid:=auth.uid(); begin_result jsonb; hash text; wave jsonb; wave_id bigint; users uuid[];
BEGIN
 IF p_target IS NULL OR jsonb_typeof(p_target) IS DISTINCT FROM 'object' OR octet_length(p_target::text)>8192
  OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_target) k WHERE k NOT IN ('occasion_link','product_id','wave_id','change_time',
    'expected_wave_revision','price','is_hidden','expected_price_revision','expected_visibility_revision'))
  OR ((p_target->>'wave_id' IS NOT NULL)::integer+(p_target->>'change_time' IS NOT NULL)::integer)<>1
  OR NOT p_target ?& ARRAY['occasion_link','product_id','price','is_hidden','expected_price_revision','expected_visibility_revision']
 THEN RAISE invalid_parameter_value USING MESSAGE='invalid wave target'; END IF;
 oc:=public.resolve_occasion_link_internal(p_target->>'occasion_link');
 IF actor IS NULL OR oc IS NULL THEN RAISE insufficient_privilege USING MESSAGE='wave editor required'; END IF;
 PERFORM public.check_product_wave_editor(oc);
 IF NOT EXISTS(SELECT 1 FROM eshop.products WHERE id=(p_target->>'product_id')::bigint AND occasion=oc) THEN
  RAISE insufficient_privilege USING MESSAGE='PRODUCT_OCCASION_MISMATCH'; END IF;
 hash:=encode(extensions.digest(convert_to(p_target::text,'UTF8'),'sha256'),'hex');
 begin_result:=public.begin_client_mutation_v1(p_command_id,'inventory.wave.target.save',oc,actor,hash);
 IF begin_result->>'disposition'='replay' THEN RETURN begin_result->'response'; END IF;
 IF p_target->>'wave_id' IS NULL THEN
  wave:=public.create_product_price_wave(p_target->>'occasion_link',(p_target->>'change_time')::timestamptz);
  wave_id:=(wave->>'id')::bigint;
 ELSE
  wave_id:=(p_target->>'wave_id')::bigint;
  SELECT to_jsonb(w) INTO wave FROM eshop.product_price_waves w WHERE id=wave_id AND occasion=oc FOR UPDATE;
  IF wave IS NULL THEN RAISE insufficient_privilege USING MESSAGE='foreign wave'; END IF;
  IF p_target->>'expected_wave_revision' IS NULL THEN RAISE invalid_parameter_value USING MESSAGE='wave revision required'; END IF;
 END IF;
 PERFORM public.save_product_wave_target(wave_id,(p_target->>'product_id')::bigint,
  CASE WHEN p_target->>'wave_id' IS NULL THEN (wave->>'revision')::bigint ELSE (p_target->>'expected_wave_revision')::bigint END,
  (p_target->>'price')::numeric,(p_target->>'is_hidden')::boolean,
  (p_target->>'expected_price_revision')::bigint,(p_target->>'expected_visibility_revision')::bigint);
 SELECT coalesce(array_agg(DISTINCT ou."user"),'{}') INTO users FROM public.occasion_users ou
 JOIN eshop.order_product_ticket opt ON opt.ticket=ou.ticket WHERE ou.occasion=oc AND opt.product=(p_target->>'product_id')::bigint;
 RETURN public.complete_private_inventory_mutation_v1(p_command_id,oc,'inventory.wave.target.save',
  jsonb_build_array(jsonb_build_object('entityType','product_price_wave','entityId',wave_id,'operation','update',
   'safeLabel','Product price wave','changedFields',jsonb_build_array('targets'))),users,jsonb_build_object('wave',wave,'productId',p_target->'product_id'));
END $function$

CREATE OR REPLACE FUNCTION public.save_profile_client_sync_v1(p_occasion bigint, p_user uuid, p_command_id uuid, p_expected_version bigint, p_profile jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_version bigint; v_begin jsonb; v_hash text;
  v_before jsonb; v_after jsonb; v_result jsonb; v_replacements jsonb:='[]'::jsonb;
BEGIN
  IF v_actor IS NULL OR NOT (public.get_is_manager_on_occasion(p_occasion)
    OR public.get_is_admin_on_occasion(p_occasion)) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion manager required'; END IF;
  IF p_profile IS NULL OR jsonb_typeof(p_profile)<>'object'
    OR octet_length(p_profile::text)>262144
    OR (p_profile->>'occasion')::bigint IS DISTINCT FROM p_occasion
    OR (p_profile->>'user')::uuid IS DISTINCT FROM p_user THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid occasion user profile'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object('occasion',p_occasion,
    'userId',p_user,'expectedVersion',p_expected_version,
    'profile',p_profile)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'profile.user.save',
    p_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  PERFORM 1 FROM public.user_info WHERE id=p_user FOR UPDATE;
  PERFORM 1 FROM public.occasion_users ou WHERE ou.occasion=p_occasion
    AND ou."user"=p_user FOR UPDATE;
  IF NOT FOUND THEN RETURN public.complete_client_mutation_outcome_v1(p_command_id,
    'rejected',404,jsonb_build_object('version',0,'profile',NULL)); END IF;
  INSERT INTO public.client_aggregate_versions
    (aggregate_type,scope_type,scope_id,aggregate_id,version)
  VALUES ('occasion_user','occasion',p_occasion,p_user::text,0) ON CONFLICT DO NOTHING;
  SELECT version INTO v_version FROM public.client_aggregate_versions
    WHERE aggregate_type='occasion_user' AND scope_type='occasion'
    AND scope_id=p_occasion AND aggregate_id=p_user::text FOR UPDATE;
  v_before:=public.get_occasion_user_command_data_v1(p_occasion,p_user);
  IF p_expected_version IS DISTINCT FROM v_version THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'conflict',409,
      jsonb_build_object('version',v_version,'profile',v_before)); END IF;
  v_result:=public.save_occasion_user_for_edit_internal_v1(p_profile);
  IF COALESCE((v_result->>'code')::integer,500)<>200 THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',
      COALESCE((v_result->>'code')::integer,400),jsonb_build_object(
        'version',v_version,'profile',v_before,'message',v_result->>'message'));
  END IF;
  v_after:=public.get_occasion_user_command_data_v1(p_occasion,p_user);
  IF v_after IS NOT DISTINCT FROM v_before THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'unchanged',200,
      jsonb_build_object('version',v_version,'profile',v_after)); END IF;
  UPDATE public.client_aggregate_versions SET version=version+1,
    updated_at=clock_timestamp() WHERE aggregate_type='occasion_user'
    AND scope_type='occasion' AND scope_id=p_occasion AND aggregate_id=p_user::text
    RETURNING version INTO v_version;
  IF v_actor=p_user THEN v_replacements:=jsonb_build_array(jsonb_build_object(
    'component','private_profile','userId',p_user,
    'payload',public.get_private_profile_payload_v1(p_occasion,p_user))); END IF;
  -- Companion-owner invalidation is part of the mutation, never a replay follow-up.
  PERFORM public.impact_companion_owners_v1(p_occasion,ARRAY[p_user],'profile.companion_identity.changed');
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'profile.user.save','profile',jsonb_build_array(jsonb_build_object(
      'entityType','occasion_user','entityId',p_user,'operation','update',
      'safeLabel','Occasion user','changedFields',jsonb_build_array('profile','rights','services'))),
    '{}',jsonb_build_array(jsonb_build_object('component','private_profile',
      'userId',p_user)),'[]',jsonb_build_object('version',v_version,'profile',v_after),
    '{}','[]','user',NULL,v_replacements);
END; $function$

CREATE OR REPLACE FUNCTION public.save_resource_client_sync_v1(p_occasion bigint, p_command_id uuid, p_expected_version bigint, p_resource jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_id bigint:=(p_resource->>'id')::bigint;
  v_pool bigint:=(p_resource->>'inventory_pool')::bigint; v_version bigint; v_origin_pool bigint;
  v_begin jsonb; v_hash text; v_current jsonb; v_entity jsonb;
  v_impacts jsonb; v_replacements jsonb:='[]'::jsonb;
BEGIN
  -- No booking rules and an empty rule document have the same domain meaning.
  IF p_resource->'booking_rules'='null'::jsonb THEN
    p_resource:=jsonb_set(p_resource,'{booking_rules}','{}'); END IF;
  IF v_actor IS NULL OR NOT public.get_is_editor_order_on_occasion(p_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion order editor required'; END IF;
  IF p_resource IS NULL OR jsonb_typeof(p_resource)<>'object'
    OR octet_length(p_resource::text)>131072
    OR EXISTS (SELECT 1 FROM jsonb_object_keys(p_resource) key WHERE key NOT IN
      ('id','title','capacity','booking_rules','inventory_pool'))
    OR v_pool IS NULL OR length(btrim(COALESCE(p_resource->>'title',''))) NOT BETWEEN 1 AND 500
    OR coalesce((p_resource->>'capacity')::integer,-1) NOT BETWEEN 0 AND 1000000
    OR jsonb_typeof(COALESCE(p_resource->'booking_rules','{}'))<>'object' THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid resource aggregate'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object('occasion',p_occasion,
    'expectedVersion',p_expected_version,'resource',p_resource)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'inventory.resource.save',
    p_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.inventory_pools WHERE id=v_pool AND occasion=p_occasion) THEN
    RAISE invalid_parameter_value USING MESSAGE='inventory pool is outside occasion'; END IF;
  IF v_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.resources WHERE id=v_id AND occasion=p_occasion) THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',404,jsonb_build_object('version',0,'resource',NULL)); END IF;
  v_origin_pool:=public.lock_resource_pools_internal_v1(v_id,v_pool);
  PERFORM 1 FROM public.inventory_pools ip WHERE ip.id=v_pool
    AND ip.occasion=p_occasion FOR UPDATE;
  IF NOT FOUND THEN RAISE invalid_parameter_value USING MESSAGE='inventory pool is outside occasion'; END IF;
  IF v_id IS NOT NULL THEN
    SELECT to_jsonb(r) INTO v_current FROM public.resources r WHERE r.id=v_id
      AND r.occasion=p_occasion FOR UPDATE;
    IF v_current IS NULL THEN RETURN public.complete_client_mutation_outcome_v1(
      p_command_id,'rejected',404,jsonb_build_object('version',0,'resource',NULL)); END IF;
    INSERT INTO public.client_aggregate_versions
      (aggregate_type,scope_type,scope_id,aggregate_id,version)
    VALUES ('resource','occasion',p_occasion,v_id::text,0) ON CONFLICT DO NOTHING;
    SELECT version INTO v_version FROM public.client_aggregate_versions
      WHERE aggregate_type='resource' AND scope_type='occasion'
        AND scope_id=p_occasion AND aggregate_id=v_id::text FOR UPDATE;
    IF p_expected_version IS DISTINCT FROM v_version THEN
      RETURN public.complete_client_mutation_outcome_v1(p_command_id,'conflict',409,
        jsonb_build_object('version',v_version,'resource',v_current||
          jsonb_build_object('aggregate_version',v_version))); END IF;
    IF jsonb_build_object('title',v_current->>'title','capacity',(v_current->>'capacity')::integer,
      'booking_rules',COALESCE(v_current->'booking_rules','{}'),
      'inventory_pool',(v_current->>'inventory_pool')::bigint)=jsonb_build_object(
      'title',p_resource->>'title','capacity',(p_resource->>'capacity')::integer,
      'booking_rules',COALESCE(p_resource->'booking_rules','{}'),
      'inventory_pool',v_pool) THEN RETURN public.complete_client_mutation_outcome_v1(
        p_command_id,'unchanged',200,jsonb_build_object('version',v_version,
          'resource',v_current||jsonb_build_object('aggregate_version',v_version))); END IF;
    PERFORM 1 FROM eshop.spots WHERE resource=v_id OR resource_slot IN(SELECT id FROM public.resource_slots WHERE resource=v_id) ORDER BY id FOR UPDATE;
    IF (v_origin_pool IS DISTINCT FROM v_pool AND EXISTS(SELECT 1 FROM eshop.spots
      WHERE (resource=v_id OR resource_slot IN(SELECT id FROM public.resource_slots WHERE resource=v_id))
      AND (order_product_ticket IS NOT NULL OR (secret IS NOT NULL AND secret_expiration_time>clock_timestamp()))))
      OR EXISTS(SELECT 1 FROM eshop.spots WHERE (resource=v_id OR resource_slot IN(SELECT id FROM public.resource_slots WHERE resource=v_id))
        AND (order_product_ticket IS NOT NULL OR (secret IS NOT NULL AND secret_expiration_time>clock_timestamp()))
        GROUP BY inventory_context HAVING count(*)>(p_resource->>'capacity')::integer) THEN
      RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',409,
        jsonb_build_object('version',v_version,'resourceId',v_id,'message','resource capacity or move conflicts with reserved spots')); END IF;
    IF v_origin_pool IS DISTINCT FROM v_pool THEN
      DELETE FROM eshop.spots WHERE resource=v_id OR resource_slot IN(SELECT id FROM public.resource_slots WHERE resource=v_id);
    END IF;
    UPDATE public.resources SET title=p_resource->>'title',
      capacity=(p_resource->>'capacity')::integer,
      booking_rules=COALESCE(p_resource->'booking_rules','{}'),inventory_pool=v_pool,
      updated_at=clock_timestamp() WHERE id=v_id;
    UPDATE public.client_aggregate_versions SET version=version+1,
      updated_at=clock_timestamp() WHERE aggregate_type='resource'
      AND scope_type='occasion' AND scope_id=p_occasion AND aggregate_id=v_id::text
      RETURNING version INTO v_version;
  ELSE
    IF p_expected_version IS NOT NULL THEN
      RAISE invalid_parameter_value USING MESSAGE='new resource must not have expected version'; END IF;
    INSERT INTO public.resources(occasion,inventory_pool,title,capacity,booking_rules)
    VALUES (p_occasion,v_pool,p_resource->>'title',(p_resource->>'capacity')::integer,
      COALESCE(p_resource->'booking_rules','{}')) RETURNING id INTO v_id;
    v_version:=1;
    INSERT INTO public.client_aggregate_versions
      (aggregate_type,scope_type,scope_id,aggregate_id,version)
    VALUES ('resource','occasion',p_occasion,v_id::text,v_version);
  END IF;
  IF v_origin_pool IS NOT NULL AND v_origin_pool IS DISTINCT FROM v_pool THEN
    PERFORM public.adjust_spot_capacity_for_pool(v_origin_pool);
  END IF;
  PERFORM public.adjust_spot_capacity_for_pool(v_pool);
  PERFORM public.advance_ticketing_authoring_version_internal_v1('inventory_pool',p_occasion,v_pool);
  IF v_origin_pool IS NOT NULL AND v_origin_pool IS DISTINCT FROM v_pool THEN
    PERFORM public.advance_ticketing_authoring_version_internal_v1('inventory_pool',p_occasion,v_origin_pool);
  END IF;
  SELECT to_jsonb(r)||jsonb_build_object('aggregate_version',v_version)
    INTO v_entity FROM public.resources r WHERE r.id=v_id;
  SELECT COALESCE(jsonb_agg(jsonb_build_object('component','private_inventory',
    'userId',ou."user")),'[]'::jsonb) INTO v_impacts
    FROM public.occasion_users ou WHERE ou.occasion=p_occasion;
  IF EXISTS (SELECT 1 FROM public.occasion_users ou WHERE ou.occasion=p_occasion
    AND ou."user"=v_actor) THEN v_replacements:=jsonb_build_array(jsonb_build_object(
      'component','private_inventory','userId',v_actor,
      'payload',public.get_user_inventory_for_occasion_v1(p_occasion))); END IF;
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'inventory.resource.save','inventory',jsonb_build_array(jsonb_build_object(
      'entityType','resource','entityId',v_id,
      'operation',CASE WHEN v_current IS NULL THEN 'insert' ELSE 'update' END,
      'safeLabel',left(p_resource->>'title',240),'changedFields',jsonb_build_array('aggregate'))),
    '{}',v_impacts,'[]',jsonb_build_object('version',v_version,'resource',v_entity),
    '{}','[]','user',NULL,v_replacements);
END; $function$

CREATE OR REPLACE FUNCTION public.save_speaker_client_sync_v1(p_occasion bigint, p_command_id uuid, p_expected_version bigint, p_speaker jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_actor uuid:=auth.uid(); v_id bigint; v_version bigint; v_begin jsonb;
  v_hash text; v_current jsonb; v_requested jsonb; v_entity jsonb;
  v_topic_ids bigint[]; v_old_hidden boolean; v_new_hidden boolean;
  v_publishable boolean; v_content_impact boolean; v_program_impact boolean;
BEGIN
  IF v_actor IS NULL OR NOT public.get_is_editor_on_occasion(p_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion editor required';
  END IF;
  SELECT NOT o.is_hidden INTO v_publishable FROM public.occasions o WHERE o.id=p_occasion;
  IF v_publishable IS NULL THEN RAISE invalid_parameter_value USING MESSAGE='occasion not found'; END IF;
  IF p_speaker IS NULL OR jsonb_typeof(p_speaker)<>'object'
    OR octet_length(p_speaker::text)>786432
    OR EXISTS (SELECT 1 FROM jsonb_object_keys(p_speaker) key WHERE key NOT IN
      ('id','title','subtitle','description','image','order','is_hidden','data','topics'))
    OR NOT (p_speaker ?& ARRAY['title','order','is_hidden','data','topics'])
    OR jsonb_typeof(p_speaker->'topics')<>'array'
    OR jsonb_array_length(p_speaker->'topics')>1000
    OR length(btrim(COALESCE(p_speaker->>'title',''))) NOT BETWEEN 1 AND 200
    OR octet_length(COALESCE(p_speaker->>'description',''))>524288
    OR octet_length(COALESCE((p_speaker->'data')::text,''))>131072 THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid speaker aggregate';
  END IF;
  SELECT COALESCE(array_agg(value::bigint ORDER BY value::bigint),'{}')
    INTO v_topic_ids FROM jsonb_array_elements_text(p_speaker->'topics');
  IF cardinality(v_topic_ids)<>cardinality(ARRAY(SELECT DISTINCT unnest(v_topic_ids)))
    OR EXISTS (
      SELECT 1
      FROM unnest(v_topic_ids) AS requested_topic(topic_id)
      LEFT JOIN public.speaker_topics t
        ON t.id=requested_topic.topic_id AND t.occasion=p_occasion
      WHERE t.id IS NULL
    ) THEN
    RAISE invalid_parameter_value USING MESSAGE='speaker contains invalid topics';
  END IF;
  v_id:=(p_speaker->>'id')::bigint;
  v_new_hidden:=(p_speaker->>'is_hidden')::boolean;
  v_requested:=jsonb_build_object('id',v_id,'title',p_speaker->>'title',
    'subtitle',p_speaker->>'subtitle','description',p_speaker->>'description',
    'image',p_speaker->>'image','order',(p_speaker->>'order')::bigint,
    'is_hidden',v_new_hidden,'data',p_speaker->'data','topics',to_jsonb(v_topic_ids));
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object('occasion',p_occasion,
    'expectedVersion',p_expected_version,'speaker',p_speaker)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'content.speaker.save',
    p_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  IF v_id IS NOT NULL THEN
    PERFORM 1 FROM public.speakers s WHERE s.id=v_id AND s.occasion=p_occasion FOR UPDATE;
    IF NOT FOUND THEN RETURN public.complete_client_mutation_outcome_v1(p_command_id,
      'rejected',404,jsonb_build_object('version',0,'speaker',NULL)); END IF;
    INSERT INTO public.client_aggregate_versions
      (aggregate_type,scope_type,scope_id,aggregate_id,version)
    VALUES ('speaker','occasion',p_occasion,v_id::text,0) ON CONFLICT DO NOTHING;
    SELECT version INTO v_version FROM public.client_aggregate_versions
      WHERE aggregate_type='speaker' AND scope_type='occasion'
      AND scope_id=p_occasion AND aggregate_id=v_id::text FOR UPDATE;
    SELECT jsonb_build_object('id',s.id,'title',s.title,'subtitle',s.subtitle,
      'description',s.description,'image',s.image,'order',s."order",
      'is_hidden',s.is_hidden,'data',s.data,'topics',COALESCE((SELECT jsonb_agg(
        l.topic ORDER BY l.topic) FROM public.speaker_topic_links l
        WHERE l.speaker=s.id),'[]'::jsonb)),s.is_hidden
      INTO v_current,v_old_hidden FROM public.speakers s WHERE s.id=v_id;
    IF p_expected_version IS DISTINCT FROM v_version THEN
      RETURN public.complete_client_mutation_outcome_v1(p_command_id,'conflict',409,
        jsonb_build_object('version',v_version,'speaker',
          public.get_speaker_command_data_v1(v_id)||jsonb_build_object(
            'aggregate_version',v_version))); END IF;
  ELSIF p_expected_version IS NOT NULL THEN
    RAISE invalid_parameter_value USING MESSAGE='new speaker must not have expected version';
  END IF;
  IF v_current IS NOT DISTINCT FROM v_requested THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'unchanged',200,
      jsonb_build_object('version',v_version,'speaker',
        public.get_speaker_command_data_v1(v_id)||jsonb_build_object(
          'aggregate_version',v_version)));
  END IF;
  IF v_id IS NULL THEN
    INSERT INTO public.speakers(occasion,title,subtitle,description,image,"order",is_hidden,data)
    VALUES (p_occasion,p_speaker->>'title',p_speaker->>'subtitle',
      p_speaker->>'description',p_speaker->>'image',(p_speaker->>'order')::bigint,
      v_new_hidden,p_speaker->'data') RETURNING id INTO v_id;
    v_version:=1;
    INSERT INTO public.client_aggregate_versions
      (aggregate_type,scope_type,scope_id,aggregate_id,version)
    VALUES ('speaker','occasion',p_occasion,v_id::text,v_version);
  ELSE
    UPDATE public.speakers SET title=p_speaker->>'title',subtitle=p_speaker->>'subtitle',
      description=p_speaker->>'description',image=p_speaker->>'image',
      "order"=(p_speaker->>'order')::bigint,is_hidden=v_new_hidden,data=p_speaker->'data'
      WHERE id=v_id;
    UPDATE public.client_aggregate_versions SET version=version+1,
      updated_at=clock_timestamp() WHERE aggregate_type='speaker'
      AND scope_type='occasion' AND scope_id=p_occasion AND aggregate_id=v_id::text
      RETURNING version INTO v_version;
  END IF;
  DELETE FROM public.speaker_topic_links WHERE speaker=v_id;
  INSERT INTO public.speaker_topic_links(speaker,topic)
    SELECT v_id,requested_topic.topic_id
    FROM unnest(v_topic_ids) AS requested_topic(topic_id);
  v_entity:=public.get_speaker_command_data_v1(v_id)||
    jsonb_build_object('aggregate_version',v_version);
  v_program_impact:=v_old_hidden IS DISTINCT FROM v_new_hidden AND EXISTS (
    SELECT 1 FROM public.event_speakers es JOIN public.events e ON e.id=es.event
    WHERE es.speaker=v_id AND NOT e.is_hidden);
  v_content_impact:=NOT COALESCE(v_old_hidden,true) OR NOT v_new_hidden;
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'content.speaker.save','content',jsonb_build_array(jsonb_build_object(
      'entityType','speaker','entityId',v_id,
      'operation',CASE WHEN v_current IS NULL THEN 'insert' ELSE 'update' END,
      'safeLabel',left(p_speaker->>'title',240),'changedFields',jsonb_build_array('aggregate'))),
    CASE WHEN v_publishable THEN CASE WHEN v_content_impact
      THEN ARRAY['content_catalog'] ELSE '{}'::text[] END||CASE WHEN v_program_impact
      THEN ARRAY['program_catalog'] ELSE '{}'::text[] END ELSE '{}'::text[] END,
    '[]','[]',jsonb_build_object('version',v_version,'speaker',v_entity));
END; $function$

CREATE OR REPLACE FUNCTION public.save_speaker_topic_client_sync_v1(p_occasion bigint, p_command_id uuid, p_expected_version bigint, p_topic jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_id bigint; v_version bigint; v_begin jsonb;
  v_hash text; v_current jsonb; v_entity jsonb; v_publishable boolean;
  v_old_hidden boolean; v_new_hidden boolean; v_content_impact boolean;
BEGIN
  IF v_actor IS NULL OR NOT public.get_is_editor_on_occasion(p_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion editor required'; END IF;
  SELECT NOT o.is_hidden INTO v_publishable FROM public.occasions o WHERE o.id=p_occasion;
  IF p_topic IS NULL OR jsonb_typeof(p_topic)<>'object'
    OR EXISTS (SELECT 1 FROM jsonb_object_keys(p_topic) key WHERE key NOT IN
      ('id','title','order','is_hidden')) OR NOT (p_topic ?& ARRAY['title','order','is_hidden'])
    OR length(btrim(COALESCE(p_topic->>'title',''))) NOT BETWEEN 1 AND 200 THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid speaker topic'; END IF;
  v_id:=(p_topic->>'id')::bigint; v_new_hidden:=(p_topic->>'is_hidden')::boolean;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object('occasion',p_occasion,
    'expectedVersion',p_expected_version,'topic',p_topic)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'content.speaker_topic.save',
    p_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  IF v_id IS NOT NULL THEN
    SELECT to_jsonb(t),t.is_hidden INTO v_current,v_old_hidden FROM public.speaker_topics t
      WHERE t.id=v_id AND t.occasion=p_occasion FOR UPDATE;
    IF v_current IS NULL THEN RETURN public.complete_client_mutation_outcome_v1(p_command_id,
      'rejected',404,jsonb_build_object('version',0,'topic',NULL)); END IF;
    INSERT INTO public.client_aggregate_versions
      (aggregate_type,scope_type,scope_id,aggregate_id,version)
    VALUES ('speaker_topic','occasion',p_occasion,v_id::text,0) ON CONFLICT DO NOTHING;
    SELECT version INTO v_version FROM public.client_aggregate_versions
      WHERE aggregate_type='speaker_topic' AND scope_type='occasion'
      AND scope_id=p_occasion AND aggregate_id=v_id::text FOR UPDATE;
    IF p_expected_version IS DISTINCT FROM v_version THEN
      RETURN public.complete_client_mutation_outcome_v1(p_command_id,'conflict',409,
        jsonb_build_object('version',v_version,'topic',v_current||
          jsonb_build_object('aggregate_version',v_version))); END IF;
    IF jsonb_build_object('id',v_id,'occasion',p_occasion,'title',v_current->>'title',
      'order',(v_current->>'order')::bigint,'is_hidden',(v_current->>'is_hidden')::boolean)
      = jsonb_build_object('id',v_id,'occasion',p_occasion,'title',p_topic->>'title',
      'order',(p_topic->>'order')::bigint,'is_hidden',v_new_hidden) THEN
      RETURN public.complete_client_mutation_outcome_v1(p_command_id,'unchanged',200,
        jsonb_build_object('version',v_version,'topic',v_current||
          jsonb_build_object('aggregate_version',v_version))); END IF;
    UPDATE public.speaker_topics SET title=p_topic->>'title',
      "order"=(p_topic->>'order')::bigint,is_hidden=v_new_hidden,
      updated_at=clock_timestamp() WHERE id=v_id
      RETURNING to_jsonb(speaker_topics.*) INTO v_entity;
    UPDATE public.client_aggregate_versions SET version=version+1,
      updated_at=clock_timestamp() WHERE aggregate_type='speaker_topic'
      AND scope_type='occasion' AND scope_id=p_occasion AND aggregate_id=v_id::text
      RETURNING version INTO v_version;
  ELSE
    IF p_expected_version IS NOT NULL THEN
      RAISE invalid_parameter_value USING MESSAGE='new topic must not have expected version'; END IF;
    INSERT INTO public.speaker_topics(occasion,title,"order",is_hidden)
    VALUES (p_occasion,p_topic->>'title',(p_topic->>'order')::bigint,v_new_hidden)
    RETURNING id,to_jsonb(speaker_topics.*) INTO v_id,v_entity;
    v_version:=1;
    INSERT INTO public.client_aggregate_versions
      (aggregate_type,scope_type,scope_id,aggregate_id,version)
    VALUES ('speaker_topic','occasion',p_occasion,v_id::text,v_version);
  END IF;
  v_entity:=v_entity||jsonb_build_object('aggregate_version',v_version);
  v_content_impact:=NOT COALESCE(v_old_hidden,true) OR NOT v_new_hidden;
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'content.speaker_topic.save','content',jsonb_build_array(jsonb_build_object(
      'entityType','speaker_topic','entityId',v_id,
      'operation',CASE WHEN v_current IS NULL THEN 'insert' ELSE 'update' END,
      'safeLabel',left(p_topic->>'title',240),'changedFields',jsonb_build_array('aggregate'))),
    CASE WHEN v_publishable AND v_content_impact THEN ARRAY['content_catalog'] ELSE '{}'::text[] END,
    '[]','[]',jsonb_build_object('version',v_version,'topic',v_entity));
END; $function$

CREATE OR REPLACE FUNCTION public.save_unit_icon_client_sync_v1(p_unit bigint, p_command_id uuid, p_icon jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_actor uuid:=auth.uid();  v_organization bigint; v_id bigint;
  v_begin jsonb; v_hash text; v_commit jsonb; v_icon jsonb; v_response jsonb;
BEGIN
  SELECT u.organization INTO v_organization FROM public.units u WHERE u.id=p_unit;
  IF v_actor IS NULL OR p_unit IS NULL OR NOT public.get_is_editor_on_unit(p_unit) THEN
    RAISE insufficient_privilege USING MESSAGE='unit editor required';
  END IF;
  IF p_icon IS NULL OR jsonb_typeof(p_icon)<>'object'
    OR EXISTS (SELECT 1 FROM jsonb_object_keys(p_icon) key WHERE key NOT IN ('link','svg'))
    OR NOT (p_icon ?& ARRAY['link','svg'])
    OR length(p_icon->>'link') NOT BETWEEN 1 AND 200
    OR octet_length(COALESCE(p_icon->>'svg','')) NOT BETWEEN 1 AND 51200 THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid icon';
  END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object('unit',p_unit,
    'icon',p_icon)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_unit_client_mutation_v1(p_command_id,'unit.icon.save',p_unit,
    v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  INSERT INTO public.icons(link,data,organization,unit,created_by)
  VALUES (p_icon->>'link',p_icon->>'svg',v_organization,p_unit,v_actor)
  RETURNING id INTO v_id;
  INSERT INTO public.client_aggregate_versions
    (aggregate_type,scope_type,scope_id,aggregate_id,version)
  VALUES ('icon','unit',p_unit,v_id::text,1);
  SELECT to_jsonb(i)||jsonb_build_object('aggregate_version',1)
    INTO v_icon FROM public.icons i WHERE i.id=v_id;
  v_response:=public.complete_unit_mutation_internal_v1(p_command_id,p_unit,'unit.icon.save','icon',v_id,'insert',jsonb_build_object('icon',v_icon));
  PERFORM public.fanout_unit_map_catalog_internal_v1((v_response#>>'{mutation,commitId}')::uuid,p_unit);
  RETURN v_response;
END; $function$

CREATE OR REPLACE FUNCTION public.save_unit_information_client_sync_v1(p_unit bigint, p_command_id uuid, p_expected_version bigint, p_information jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE actor uuid:=auth.uid(); ident bigint; ver bigint; before_row jsonb; after_row jsonb; begun jsonb; hash text;
BEGIN
 IF actor IS NULL OR NOT public.get_is_editor_on_unit(p_unit) THEN RAISE insufficient_privilege USING MESSAGE='unit editor required'; END IF;
 PERFORM public.validate_information_content_internal_v1(p_information,true);
 ident:=(p_information->>'id')::bigint;
 hash:=encode(extensions.digest(convert_to(jsonb_build_object('unit',p_unit,'expectedVersion',p_expected_version,'information',p_information)::text,'UTF8'),'sha256'),'hex');
 begun:=public.begin_unit_client_mutation_v1(p_command_id,'unit.information.save',p_unit,actor,hash);
 IF begun->>'disposition'='replay' THEN RETURN begun->'response'; END IF;
 IF ident IS NOT NULL THEN
  SELECT to_jsonb(i) INTO before_row FROM public.information i WHERE i.id=ident AND i.unit=p_unit AND i.occasion IS NULL FOR UPDATE;
  IF before_row IS NULL THEN RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',404,'{}'); END IF;
  IF before_row->>'type'='game' OR before_row->>'information_hidden' IS NOT NULL THEN RAISE invalid_parameter_value USING MESSAGE='unit games unsupported'; END IF;
  INSERT INTO public.client_aggregate_versions(aggregate_type,scope_type,scope_id,aggregate_id,version)
  VALUES('information','unit',p_unit,ident::text,0) ON CONFLICT DO NOTHING;
  SELECT version INTO ver FROM public.client_aggregate_versions WHERE aggregate_type='information' AND scope_type='unit' AND scope_id=p_unit AND aggregate_id=ident::text FOR UPDATE;
  IF p_expected_version IS DISTINCT FROM ver THEN RETURN public.complete_client_mutation_outcome_v1(p_command_id,'conflict',409,jsonb_build_object('version',ver,'information',before_row)); END IF;
  IF jsonb_build_object('title',before_row->'title','description',before_row->'description','type',before_row->'type','isHidden',before_row->'is_hidden','order',before_row->'order','data',before_row->'data')
   =p_information-'id'-'hiddenData' THEN RETURN public.complete_client_mutation_outcome_v1(p_command_id,'unchanged',200,jsonb_build_object('version',ver,'information',before_row)); END IF;
  UPDATE public.information SET title=p_information->>'title',description=p_information->>'description',type=p_information->>'type',
   is_hidden=(p_information->>'isHidden')::boolean,"order"=(p_information->>'order')::bigint,data=p_information->'data',updated_at=clock_timestamp() WHERE id=ident;
  UPDATE public.client_aggregate_versions SET version=version+1,updated_at=clock_timestamp() WHERE aggregate_type='information' AND scope_type='unit' AND scope_id=p_unit AND aggregate_id=ident::text RETURNING version INTO ver;
 ELSE
  IF p_expected_version IS NOT NULL THEN RAISE invalid_parameter_value USING MESSAGE='new information cannot have version'; END IF;
  INSERT INTO public.information(unit,title,description,type,is_hidden,"order",data)
  VALUES(p_unit,p_information->>'title',p_information->>'description',p_information->>'type',(p_information->>'isHidden')::boolean,(p_information->>'order')::bigint,p_information->'data') RETURNING id INTO ident;
  ver:=1;INSERT INTO public.client_aggregate_versions(aggregate_type,scope_type,scope_id,aggregate_id,version) VALUES('information','unit',p_unit,ident::text,ver);
 END IF;
 SELECT to_jsonb(i)||jsonb_build_object('aggregate_version',ver) INTO after_row FROM public.information i WHERE id=ident;
 RETURN public.complete_unit_mutation_internal_v1(p_command_id,p_unit,'unit.information.save','information',ident,CASE WHEN before_row IS NULL THEN 'insert' ELSE 'update' END,jsonb_build_object('version',ver,'information',after_row));
END $function$

CREATE OR REPLACE FUNCTION public.save_unit_legal_profile(p_unit bigint, p_expected_revision bigint, p_profile jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE p public.unit_legal_profiles; n public.unit_legal_profiles; org bigint; k text; v text;
 errors jsonb:='{}'; normalized jsonb; old_values jsonb; checksum integer:=0; i integer;
BEGIN
 SELECT organization INTO org FROM public.units WHERE id=p_unit FOR UPDATE;
 IF auth.uid() IS NULL OR org IS NULL OR NOT public.get_is_manager_on_unit(p_unit) OR public.is_demo_unit(p_unit) THEN
  RAISE EXCEPTION 'Legal profile write denied' USING ERRCODE='42501';
 END IF;
 SELECT * INTO p FROM public.unit_legal_profiles WHERE unit_id=p_unit FOR UPDATE;
 IF p_expected_revision IS DISTINCT FROM coalesce(p.revision,0) THEN
  RETURN jsonb_build_object('code',409,'errorCode','REVISION_CONFLICT','profile',public.get_unit_legal_profile(p_unit)->'profile');
 END IF;
 IF jsonb_typeof(p_profile) IS DISTINCT FROM 'object' THEN
  RETURN jsonb_build_object('code',422,'errorCode','INVALID_PROFILE','fieldErrors',jsonb_build_object('profile','OBJECT_REQUIRED'));
 END IF;
 FOR k IN SELECT jsonb_object_keys(p_profile) LOOP
  IF k<>ALL(ARRAY['legalName','countryCode','registrationNumber','vatId','address','contactEmail','phone','website']) THEN errors:=errors||jsonb_build_object(k,'UNKNOWN_FIELD'); END IF;
  IF k<>'address' AND jsonb_typeof(p_profile->k) NOT IN ('string','null') THEN errors:=errors||jsonb_build_object(k,'TEXT_REQUIRED'); END IF;
 END LOOP;
 IF p_profile ? 'address' AND jsonb_typeof(p_profile->'address') IS DISTINCT FROM 'object' THEN
  errors:=errors||jsonb_build_object('address','OBJECT_REQUIRED');
 ELSE
  FOR k IN SELECT jsonb_object_keys(coalesce(p_profile->'address','{}')) LOOP
   IF k<>ALL(ARRAY['street','city','postalCode']) THEN errors:=errors||jsonb_build_object('address.'||k,'UNKNOWN_FIELD'); END IF;
   IF jsonb_typeof(p_profile->'address'->k) NOT IN ('string','null') THEN errors:=errors||jsonb_build_object('address.'||k,'TEXT_REQUIRED'); END IF;
  END LOOP;
 END IF;
 IF errors<>'{}' THEN RETURN jsonb_build_object('code',422,'errorCode','INVALID_PROFILE','fieldErrors',errors); END IF;
 n.legal_name:=btrim(coalesce(p_profile->>'legalName',''));
 n.country_code:=upper(btrim(coalesce(p_profile->>'countryCode','')));
 n.registration_number:=btrim(coalesce(p_profile->>'registrationNumber',''));
 n.vat_id:=btrim(coalesce(p_profile->>'vatId',''));
 n.street:=btrim(coalesce(p_profile#>>'{address,street}',''));
 n.city:=btrim(coalesce(p_profile#>>'{address,city}',''));
 n.postal_code:=btrim(coalesce(p_profile#>>'{address,postalCode}',''));
 n.contact_email:=lower(btrim(coalesce(p_profile->>'contactEmail','')));
 n.phone:=btrim(coalesce(p_profile->>'phone',''));
 n.website:=btrim(coalesce(p_profile->>'website',''));
 normalized:=jsonb_build_object('legalName',n.legal_name,'countryCode',n.country_code,'registrationNumber',n.registration_number,
 'vatId',n.vat_id,'address',jsonb_build_object('street',n.street,'city',n.city,'postalCode',n.postal_code),
 'contactEmail',n.contact_email,'phone',n.phone,'website',n.website);
 FOR k,v IN SELECT key,value#>>'{}' FROM jsonb_each(normalized-'address') LOOP
  IF length(v)>(CASE k WHEN 'legalName' THEN 200 WHEN 'contactEmail' THEN 254 WHEN 'website' THEN 500 WHEN 'phone' THEN 40 WHEN 'countryCode' THEN 2 ELSE 50 END)
   OR v ~ '[[:cntrl:]]' THEN errors:=errors||jsonb_build_object(k,'INVALID_LENGTH_OR_CHARACTERS'); END IF;
 END LOOP;
 IF length(n.street)>200 OR length(n.city)>100 OR length(n.postal_code)>20 OR (n.street||n.city||n.postal_code) ~ '[[:cntrl:]]' THEN errors:=errors||jsonb_build_object('address','INVALID_ADDRESS'); END IF;
 IF n.country_code<>'' AND n.country_code !~ '^[A-Z]{2}$' THEN errors:=errors||jsonb_build_object('countryCode','INVALID_COUNTRY'); END IF;
 IF n.registration_number<>'' AND n.country_code='CZ' THEN
  IF n.registration_number !~ '^[0-9]{8}$' THEN errors:=errors||jsonb_build_object('registrationNumber','INVALID_CZ_ICO');
  ELSE
   FOR i IN 1..7 LOOP checksum:=checksum+substring(n.registration_number,i,1)::integer*(9-i); END LOOP;
   IF ((11-checksum%11)%10)<>substring(n.registration_number,8,1)::integer THEN errors:=errors||jsonb_build_object('registrationNumber','INVALID_CZ_ICO'); END IF;
  END IF;
 END IF;
 IF n.contact_email<>'' AND n.contact_email !~ '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$' THEN errors:=errors||jsonb_build_object('contactEmail','INVALID_EMAIL'); END IF;
 IF n.phone<>'' AND n.phone !~ '^[+0-9][0-9 ()-]{2,39}$' THEN errors:=errors||jsonb_build_object('phone','INVALID_PHONE'); END IF;
 IF n.website<>'' AND n.website !~ '^https://[A-Za-z0-9]([A-Za-z0-9.-]*[A-Za-z0-9])?(:[0-9]{1,5})?([/?#][^[:space:]<>]*)?$' THEN errors:=errors||jsonb_build_object('website','HTTPS_REQUIRED'); END IF;
 IF errors<>'{}' THEN RETURN jsonb_build_object('code',422,'errorCode','INVALID_PROFILE','fieldErrors',errors); END IF;
 old_values:=(public.get_unit_legal_profile(p_unit)->'profile')-ARRAY['unitId','revision','status','submittedAt','verifiedAt','feedbackToApplicant','reviewNote','reviewSource'];
 IF normalized=old_values AND (p.reviewed_organization_id IS NULL OR p.reviewed_organization_id=org) THEN
  RETURN jsonb_build_object('code',200,'outcome','unchanged','profile',public.get_unit_legal_profile(p_unit)->'profile');
 END IF;
 INSERT INTO public.unit_legal_profiles(unit_id,revision,legal_name,country_code,registration_number,vat_id,street,city,postal_code,contact_email,phone,website)
 VALUES(p_unit,coalesce(p.revision,0)+1,n.legal_name,n.country_code,n.registration_number,n.vat_id,n.street,n.city,n.postal_code,n.contact_email,n.phone,n.website)
 ON CONFLICT(unit_id) DO UPDATE SET revision=excluded.revision,status='unverified',legal_name=excluded.legal_name,
 country_code=excluded.country_code,registration_number=excluded.registration_number,vat_id=excluded.vat_id,
 street=excluded.street,city=excluded.city,postal_code=excluded.postal_code,contact_email=excluded.contact_email,
 phone=excluded.phone,website=excluded.website,submitted_at=NULL,submitted_by=NULL,reviewed_at=NULL,reviewed_by=NULL,
 reviewed_organization_id=NULL,feedback_to_applicant=NULL,review_note=NULL,review_source=NULL;
 INSERT INTO public.unit_legal_profile_audit(unit_id,organization_id,revision,actor_id,action,snapshot)
 SELECT p_unit,org,revision,auth.uid(),'save',to_jsonb(t) FROM public.unit_legal_profiles t WHERE unit_id=p_unit;
 RETURN jsonb_build_object('code',200,'outcome','applied','profile',public.get_unit_legal_profile(p_unit)->'profile');
END $function$

CREATE OR REPLACE FUNCTION public.save_user_group_client_sync_v1(p_occasion bigint, p_command_id uuid, p_expected_version bigint, p_group jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_actor uuid:=auth.uid(); v_id bigint; v_version bigint; v_begin jsonb;
  v_hash text; v_current jsonb; v_requested jsonb; v_entity jsonb;
  v_participants jsonb; v_current_participants jsonb;
  v_old_users uuid[]; v_new_users uuid[];
  v_old_place bigint; v_old_private boolean:=false; v_place_id bigint;
  v_private_place jsonb; v_place_version bigint; v_private_impacts jsonb;
  v_current_place jsonb; v_requested_place jsonb; v_place_changed boolean:=false;
  v_actor_replacements jsonb:='[]'::jsonb;
BEGIN
 PERFORM public.assert_canonical_mutation_write_release_internal_v1(p_occasion);
  v_id:=(p_group->>'id')::bigint;
  IF v_actor IS NULL OR NOT (public.get_is_editor_on_occasion(p_occasion)
    OR (v_id IS NOT NULL AND EXISTS (SELECT 1 FROM public.user_groups ug
      JOIN public.user_group_info g ON g.id=ug."group"
      WHERE ug."group"=v_id AND ug."user"=v_actor AND ug.is_admin
        AND g.occasion=p_occasion))) THEN
    RAISE insufficient_privilege USING MESSAGE='group editor required';
  END IF;
  IF p_group IS NULL OR jsonb_typeof(p_group)<>'object'
    OR octet_length(p_group::text)>524288
    OR EXISTS (SELECT 1 FROM jsonb_object_keys(p_group) key WHERE key NOT IN
      ('id','title','description','type','placeId','privatePlace','participants'))
    OR NOT (p_group ?& ARRAY['title','participants'])
    OR jsonb_typeof(p_group->'participants')<>'array'
    OR jsonb_array_length(p_group->'participants')>5000
    OR length(btrim(COALESCE(p_group->>'title',''))) NOT BETWEEN 1 AND 500
    OR octet_length(COALESCE(p_group->>'description',''))>262144 THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid group aggregate';
  END IF;
  SELECT COALESCE(jsonb_agg(jsonb_build_object('userId',x.user_id,
    'isAdmin',COALESCE(x.is_admin,false)) ORDER BY x.user_id),'[]'::jsonb),
    COALESCE(array_agg(x.user_id ORDER BY x.user_id),'{}'::uuid[])
    INTO v_participants,v_new_users
  FROM jsonb_to_recordset(p_group->'participants') x(user_id uuid,is_admin boolean);
  IF jsonb_array_length(p_group->'participants')<>cardinality(v_new_users)
    OR cardinality(v_new_users)<>cardinality(ARRAY(SELECT DISTINCT unnest(v_new_users)))
    OR EXISTS (SELECT 1 FROM unnest(v_new_users) id LEFT JOIN public.occasion_users ou
      ON ou."user"=id AND ou.occasion=p_occasion WHERE ou."user" IS NULL) THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid group participants';
  END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_group->'participants') x WHERE jsonb_typeof(x)<>'object' OR x->>'user_id' IS NULL OR EXISTS(SELECT 1 FROM jsonb_object_keys(x) k WHERE k NOT IN ('user_id','is_admin')))
    OR (p_group->>'placeId' IS NOT NULL AND p_group->'privatePlace' IS NOT NULL AND p_group->'privatePlace'<>'null'::jsonb) THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid group participants or place choice'; END IF;
  v_private_place:=p_group->'privatePlace';
  IF v_private_place IS NOT NULL AND v_private_place<>'null'::jsonb AND (
    jsonb_typeof(v_private_place)<>'object'
    OR EXISTS (SELECT 1 FROM jsonb_object_keys(v_private_place) key WHERE key NOT IN
      ('id','title','description','coordinates','order','icon'))
    OR length(btrim(COALESCE(v_private_place->>'title',''))) NOT BETWEEN 1 AND 500
    OR jsonb_typeof(v_private_place->'coordinates')<>'object'
    OR octet_length(v_private_place::text)>131072) THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid private group place';
  END IF;
  IF v_private_place IS NOT NULL AND v_private_place<>'null'::jsonb THEN
    IF jsonb_typeof(v_private_place#>'{coordinates,latLng,lat}') IS DISTINCT FROM 'number'
      OR jsonb_typeof(v_private_place#>'{coordinates,latLng,lng}') IS DISTINCT FROM 'number'
      OR (v_private_place#>>'{coordinates,latLng,lat}')::double precision NOT BETWEEN -90 AND 90
      OR (v_private_place#>>'{coordinates,latLng,lng}')::double precision NOT BETWEEN -180 AND 180
      OR (v_private_place->>'icon' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.icons i JOIN public.occasions o ON o.id=p_occasion AND i.organization=o.organization WHERE i.id=(v_private_place->>'icon')::bigint AND (i.unit=o.unit OR i.unit IS NULL))) THEN
      RAISE invalid_parameter_value USING MESSAGE='invalid private coordinates or icon'; END IF;
  END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object('occasion',p_occasion,
    'expectedVersion',p_expected_version,'group',p_group)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'profile.group.save',
    p_occasion,v_actor,v_hash);
  PERFORM public.lock_group_occasion_internal_v1(p_occasion);
  IF v_actor IS NULL OR NOT (public.get_is_editor_on_occasion(p_occasion)
    OR (v_id IS NOT NULL AND EXISTS (SELECT 1 FROM public.user_groups ug
      JOIN public.user_group_info g ON g.id=ug."group"
      WHERE ug."group"=v_id AND ug."user"=v_actor AND ug.is_admin
        AND g.occasion=p_occasion))) THEN
    RAISE insufficient_privilege USING MESSAGE='group editor required';
  END IF;
  IF EXISTS(SELECT 1 FROM unnest(v_new_users) id LEFT JOIN public.occasion_users ou ON ou.occasion=p_occasion AND ou."user"=id WHERE ou."user" IS NULL) THEN RAISE invalid_parameter_value USING MESSAGE='invalid group participants after lock'; END IF;
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  IF v_id IS NOT NULL THEN
    PERFORM 1 FROM public.user_group_info g WHERE g.id=v_id
      AND g.occasion=p_occasion FOR UPDATE;
    IF NOT FOUND THEN RETURN public.complete_client_mutation_outcome_v1(
      p_command_id,'rejected',404,jsonb_build_object('version',0,'group',NULL)); END IF;
    SELECT g.place,COALESCE(p.is_hidden AND p.type='group',false),
      public.get_user_group_command_data_v1(g.id)
      INTO v_old_place,v_old_private,v_current
    FROM public.user_group_info g LEFT JOIN public.places p ON p.id=g.place
    WHERE g.id=v_id;
    SELECT COALESCE(array_agg(ug."user" ORDER BY ug."user"),'{}'::uuid[]),
      COALESCE(jsonb_agg(jsonb_build_object('userId',ug."user",
        'isAdmin',ug.is_admin) ORDER BY ug."user"),'[]'::jsonb)
      INTO v_old_users,v_current_participants FROM public.user_groups ug
      WHERE ug."group"=v_id;
    INSERT INTO public.client_aggregate_versions
      (aggregate_type,scope_type,scope_id,aggregate_id,version)
    VALUES ('user_group','occasion',p_occasion,v_id::text,0) ON CONFLICT DO NOTHING;
    SELECT version INTO v_version FROM public.client_aggregate_versions
      WHERE aggregate_type='user_group' AND scope_type='occasion'
      AND scope_id=p_occasion AND aggregate_id=v_id::text FOR UPDATE;
    IF p_expected_version IS DISTINCT FROM v_version THEN
      RETURN public.complete_client_mutation_outcome_v1(p_command_id,'conflict',409,
        jsonb_build_object('version',v_version,'group',v_current)); END IF;
  ELSIF p_expected_version IS NOT NULL THEN
    RAISE invalid_parameter_value USING MESSAGE='new group must not have expected version';
  END IF;
  IF v_private_place IS NOT NULL AND v_private_place<>'null'::jsonb THEN
    v_place_id:=(v_private_place->>'id')::bigint;
    IF v_place_id IS NULL THEN
      INSERT INTO public.places(title,description,type,coordinates,is_hidden,"order",icon,occasion)
      VALUES (v_private_place->>'title',v_private_place->>'description','group',
        v_private_place->'coordinates',true,(v_private_place->>'order')::bigint,
        (v_private_place->>'icon')::bigint,p_occasion) RETURNING id INTO v_place_id;
      v_place_version:=1;
      v_place_changed:=true;
      INSERT INTO public.client_aggregate_versions
        (aggregate_type,scope_type,scope_id,aggregate_id,version)
      VALUES ('place','occasion',p_occasion,v_place_id::text,v_place_version);
    ELSE
      PERFORM 1 FROM public.places p WHERE p.id=v_place_id AND p.occasion=p_occasion
        AND p.type='group' AND p.is_hidden FOR UPDATE;
      IF NOT FOUND OR v_id IS NULL OR NOT v_old_private
        OR v_place_id IS DISTINCT FROM v_old_place THEN
        RAISE invalid_parameter_value USING MESSAGE='private place is not owned by group';
      END IF;
      PERFORM public.assert_group_place_owner_internal_v1(p_occasion,v_id,v_place_id,false);
      INSERT INTO public.client_aggregate_versions
        (aggregate_type,scope_type,scope_id,aggregate_id,version)
      VALUES ('place','occasion',p_occasion,v_place_id::text,0) ON CONFLICT DO NOTHING;
      SELECT jsonb_build_object('id',p.id,'title',p.title,
        'description',p.description,'coordinates',p.coordinates,
        'order',p."order",'icon',p.icon) INTO v_current_place
      FROM public.places p WHERE p.id=v_place_id;
      v_requested_place:=jsonb_build_object('id',v_place_id,
        'title',v_private_place->>'title','description',v_private_place->>'description',
        'coordinates',v_private_place->'coordinates',
        'order',(v_private_place->>'order')::bigint,
        'icon',(v_private_place->>'icon')::bigint);
      v_place_changed:=v_current_place IS DISTINCT FROM v_requested_place;
      IF v_place_changed THEN
        UPDATE public.places SET title=v_private_place->>'title',
          description=v_private_place->>'description',coordinates=v_private_place->'coordinates',
          "order"=(v_private_place->>'order')::bigint,icon=(v_private_place->>'icon')::bigint
          WHERE id=v_place_id;
        UPDATE public.client_aggregate_versions SET version=version+1,
          updated_at=clock_timestamp() WHERE aggregate_type='place'
          AND scope_type='occasion' AND scope_id=p_occasion
          AND aggregate_id=v_place_id::text RETURNING version INTO v_place_version;
      ELSE
        SELECT version INTO v_place_version FROM public.client_aggregate_versions
        WHERE aggregate_type='place' AND scope_type='occasion'
          AND scope_id=p_occasion AND aggregate_id=v_place_id::text;
      END IF;
    END IF;
  ELSE
    v_place_id:=(p_group->>'placeId')::bigint;
    IF v_place_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.places p
      WHERE p.id=v_place_id AND p.occasion=p_occasion
        AND (NOT p.is_hidden OR (p.id=v_old_place AND p.type='group' AND v_old_private))) THEN
      RAISE invalid_parameter_value USING MESSAGE='invalid shared group place';
    END IF;
  END IF;
  v_requested:=jsonb_build_object('id',v_id,'title',p_group->>'title',
    'description',p_group->>'description','type',p_group->>'type',
    'place',v_place_id,'participants',v_participants);
  IF v_current IS NOT NULL AND jsonb_build_object('id',v_id,
      'title',v_current->>'title','description',v_current->>'description',
      'type',v_current->>'type','place',(v_current->>'place')::bigint,
      'participants',v_current_participants)=v_requested
      AND NOT v_place_changed THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'unchanged',200,
      jsonb_build_object('version',v_version,'group',v_current));
  END IF;
  IF v_old_private AND v_old_place IS DISTINCT FROM v_place_id THEN
    PERFORM public.assert_group_place_owner_internal_v1(p_occasion,v_id,v_old_place,true);
  END IF;
  IF v_id IS NULL THEN
    INSERT INTO public.user_group_info(title,description,type,place,occasion)
    VALUES (p_group->>'title',p_group->>'description',p_group->>'type',v_place_id,p_occasion)
    RETURNING id INTO v_id;
    v_version:=1;
    INSERT INTO public.client_aggregate_versions
      (aggregate_type,scope_type,scope_id,aggregate_id,version)
    VALUES ('user_group','occasion',p_occasion,v_id::text,v_version);
  ELSE
    UPDATE public.user_group_info SET title=p_group->>'title',
      description=p_group->>'description',type=p_group->>'type',place=v_place_id
      WHERE id=v_id;
    UPDATE public.client_aggregate_versions SET version=version+1,
      updated_at=clock_timestamp() WHERE aggregate_type='user_group'
      AND scope_type='occasion' AND scope_id=p_occasion AND aggregate_id=v_id::text
      RETURNING version INTO v_version;
  END IF;
  PERFORM public.write_user_group_members_internal_v1(p_occasion,v_id,p_group->'participants',true);
  IF v_old_private AND v_old_place IS DISTINCT FROM v_place_id THEN
    IF EXISTS (SELECT 1 FROM public.user_group_info g WHERE g.id<>v_id
      AND g.place=v_old_place) THEN
      RAISE foreign_key_violation USING MESSAGE='private group place has another owner';
    END IF;
    DELETE FROM public.places WHERE id=v_old_place;
    DELETE FROM public.client_aggregate_versions WHERE aggregate_type='place'
      AND scope_type='occasion' AND scope_id=p_occasion AND aggregate_id=v_old_place::text;
  END IF;
  v_private_impacts:=public.group_profile_impacts_internal_v1(p_occasion,COALESCE(v_old_users,'{}'::uuid[])||v_new_users);
  v_entity:=public.get_user_group_command_data_v1(v_id)||
    jsonb_build_object('aggregate_version',v_version);
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(v_private_impacts) x WHERE x->>'userId'=v_actor::text) THEN
    v_actor_replacements:=jsonb_build_array(jsonb_build_object(
      'component','private_profile','userId',v_actor,
      'payload',public.get_private_profile_payload_v1(p_occasion,v_actor)));
  END IF;
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'profile.group.save','profile',jsonb_build_array(jsonb_build_object(
      'entityType','user_group','entityId',v_id,
      'operation',CASE WHEN v_current IS NULL THEN 'insert' ELSE 'update' END,
      'safeLabel',left(p_group->>'title',240),'changedFields',jsonb_build_array('aggregate'))),
    '{}',v_private_impacts,'[]',jsonb_build_object('version',v_version,'group',v_entity),
    '{}','[]','user',NULL,v_actor_replacements);
END; $function$

CREATE OR REPLACE FUNCTION public.scanner_admit_ticket_internal(p_ticket bigint)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
BEGIN
 PERFORM public.check_ticket_is_mutable(p_ticket);
 IF EXISTS(SELECT 1 FROM eshop.tickets WHERE id=p_ticket AND state='used') THEN RAISE EXCEPTION 'already_used'; END IF;
 UPDATE eshop.tickets SET state='used',updated_at=clock_timestamp() WHERE id=p_ticket;
END $function$

CREATE OR REPLACE FUNCTION public.scanner_can_reset_password_internal(p_occasion bigint, p_ticket bigint)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE target uuid;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.occasions o JOIN public.organizations org ON org.id=o.organization
   WHERE o.id=p_occasion AND org.data->>'IS_APP_SUPPORTED'='true') THEN RETURN false; END IF;
 SELECT ou."user" INTO target FROM public.occasion_users ou JOIN eshop.tickets t ON t.id=ou.ticket
 WHERE ou.occasion=p_occasion AND t.occasion=p_occasion AND t.id=p_ticket LIMIT 1;
 IF target IS NULL THEN RETURN false; END IF;
 PERFORM public.check_is_scan_password_reset_target_allowed(target);
 RETURN true;
EXCEPTION WHEN insufficient_privilege THEN RETURN false;
END $function$

CREATE OR REPLACE FUNCTION public.scanner_lock_ticket_internal(p_ticket bigint)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE parents bigint[]; current_parents bigint[]; parent bigint;
BEGIN
 SELECT array_agg(DISTINCT x."order" ORDER BY x."order") INTO parents FROM eshop.order_product_ticket x WHERE x.ticket=p_ticket;
 PERFORM public.lock_order_capacity_scope_internal(parents);
 FOREACH parent IN ARRAY coalesce(parents,ARRAY[]::bigint[]) LOOP
  PERFORM 1 FROM eshop.orders WHERE id=parent FOR UPDATE;
 END LOOP;
 PERFORM 1 FROM eshop.tickets WHERE id=p_ticket FOR UPDATE;
 SELECT array_agg(DISTINCT x."order" ORDER BY x."order") INTO current_parents FROM eshop.order_product_ticket x WHERE x.ticket=p_ticket;
 IF parents IS DISTINCT FROM current_parents THEN RAISE serialization_failure USING MESSAGE='ticket_parent_changed'; END IF;
END $function$

CREATE OR REPLACE FUNCTION public.scanner_session_internal(p_session uuid, p_token text, p_allow_expired boolean DEFAULT false)
 RETURNS scanner_sessions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE s public.scanner_sessions; cfg public.scanner_settings; secret text;
BEGIN
 -- Shared policy then session locks also serialize revocation and settings changes.
 SELECT * INTO cfg FROM public.scanner_settings WHERE occasion_id=(SELECT occasion_id FROM public.scanner_sessions WHERE id=p_session) FOR SHARE;
 SELECT * INTO s FROM public.scanner_sessions WHERE id=p_session FOR SHARE;
 IF s.id IS NULL OR p_token IS NULL OR s.token_hash<>encode(digest(p_token,'sha256'),'hex') THEN
  RAISE SQLSTATE 'PT401' USING MESSAGE='invalid_scanner_session'; END IF;
 IF s.actor_user_id IS NOT NULL AND (auth.uid() IS DISTINCT FROM s.actor_user_id OR NOT public.scanner_can_manage_settings_internal(s.occasion_id)) THEN
  RAISE SQLSTATE 'PT403' USING MESSAGE='scanner_actor_changed'; END IF;
 SELECT oh.secret INTO secret FROM public.occasions o JOIN public.occasions_hidden oh ON oh.id=o.occasion_hidden WHERE o.id=s.occasion_id;
 IF NOT p_allow_expired AND (s.revoked_at IS NOT NULL OR s.expires_at<=now() OR s.epoch<>cfg.epoch
 OR (s.access_origin='scan_link' AND s.scan_secret_hash IS DISTINCT FROM encode(digest(secret,'sha256'),'hex'))) THEN
  RAISE SQLSTATE 'PT401' USING MESSAGE='scanner_session_expired'; END IF;
 RETURN s;
END $function$

CREATE OR REPLACE FUNCTION public.scanner_validate_settings_internal(p_occasion bigint, p_config jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE f jsonb; n bigint;
BEGIN
 IF p_config IS NULL OR octet_length(p_config::text)>32768 OR p_config->>'schema_version' IS DISTINCT FROM '1'
 OR coalesce(p_config#>>'{products,mode}','') NOT IN ('all','none','selected')
 OR jsonb_typeof(p_config#>'{products,ids}') IS DISTINCT FROM 'array'
 OR jsonb_typeof(p_config#>'{products,order}') IS DISTINCT FROM 'array'
 OR jsonb_typeof(p_config->'fields') IS DISTINCT FROM 'array'
 OR jsonb_array_length(p_config->'fields')>40
 OR coalesce((p_config#>>'{offline,max_hours}')::numeric,0) NOT BETWEEN 0 AND 12
 OR coalesce((p_config#>>'{admission,allow_unpaid_offline}')::boolean,true)

 THEN RAISE invalid_parameter_value USING MESSAGE='invalid_scanner_settings'; END IF;
 IF (SELECT count(*)<>count(DISTINCT value) FROM jsonb_array_elements(p_config#>'{products,ids}'))
 OR (SELECT count(*)<>count(DISTINCT value) FROM jsonb_array_elements(p_config#>'{products,order}')) THEN RAISE invalid_parameter_value USING MESSAGE='duplicate_product'; END IF;
 FOR n IN SELECT value::text::bigint FROM jsonb_array_elements(p_config#>'{products,ids}') LOOP
  IF NOT EXISTS(SELECT 1 FROM eshop.products WHERE id=n AND occasion=p_occasion) THEN RAISE invalid_parameter_value USING MESSAGE='foreign_product'; END IF;
 END LOOP;
 FOR n IN SELECT value::text::bigint FROM jsonb_array_elements(p_config#>'{products,order}') LOOP
  IF NOT EXISTS(SELECT 1 FROM eshop.products WHERE id=n AND occasion=p_occasion) THEN RAISE invalid_parameter_value USING MESSAGE='foreign_product'; END IF;
 END LOOP;
 IF (SELECT count(*)<>count(DISTINCT e->>'key') FROM jsonb_array_elements(p_config->'fields') e) THEN RAISE invalid_parameter_value USING MESSAGE='duplicate_field'; END IF;
 FOR f IN SELECT * FROM jsonb_array_elements(p_config->'fields') LOOP
  IF f->>'source'='builtin' THEN
   IF f->>'key' NOT IN ('holder_name','spot','groups','note') THEN RAISE invalid_parameter_value USING MESSAGE='invalid_builtin'; END IF;
  ELSIF f->>'source' IN ('order_field','ticket_field') THEN
   IF f->>'key' IS DISTINCT FROM (CASE f->>'source' WHEN 'order_field' THEN 'order' ELSE 'ticket' END)||':'||(f->>'form_id')||':'||(f->>'field_id')
   OR NOT EXISTS(SELECT 1 FROM public.form_fields ff JOIN public.forms fm ON fm.id=ff.form
    WHERE ff.id=(f->>'field_id')::bigint AND ff.form=(f->>'form_id')::bigint AND fm.occasion=p_occasion
    AND ff.is_ticket_field=(f->>'source'='ticket_field')) THEN RAISE invalid_parameter_value USING MESSAGE='foreign_field'; END IF;
  ELSE RAISE invalid_parameter_value USING MESSAGE='invalid_field_source'; END IF;
 END LOOP;
END $function$

CREATE OR REPLACE FUNCTION public.search_scanner_tickets(p_session uuid, p_token text, p_query text, p_after bigint DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE s public.scanner_sessions; cfg public.scanner_settings; result jsonb;
BEGIN
 s:=public.scanner_session_internal(p_session,p_token); SELECT * INTO cfg FROM public.scanner_settings WHERE occasion_id=s.occasion_id;
 IF NOT coalesce((cfg.config#>>'{manual_search,tickets}')::boolean,false) THEN RAISE insufficient_privilege USING MESSAGE='manual_search_disabled'; END IF;
 IF length(p_query) NOT BETWEEN 2 AND 100 THEN RETURN jsonb_build_object('code',400,'reason','invalid_query','server_time',now()); END IF;
 IF NOT public.admit_scan_access_v1(s.occasion_id,true) THEN RETURN jsonb_build_object('code',429,'reason','abuse_limit_exceeded','server_time',now()); END IF;
 SELECT coalesce(jsonb_agg(dto ORDER BY ticket_id),'[]'::jsonb) INTO result FROM (
 SELECT * FROM public.scanner_ticket_projection_internal(s.occasion_id,cfg.config) WHERE ticket_id>p_after
 AND (strpos(lower(dto->>'holder_name'),lower(p_query))>0 OR strpos(lower(dto->>'symbol'),lower(p_query))>0) ORDER BY ticket_id LIMIT 30) found;
 RETURN jsonb_build_object('code',200,'data',result,'server_time',now());
END $function$

CREATE OR REPLACE FUNCTION public.search_scanner_users(p_session uuid, p_token text, p_query text, p_after uuid DEFAULT '00000000-0000-0000-0000-000000000000'::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE s public.scanner_sessions; cfg jsonb; result jsonb;
BEGIN
 s:=public.scanner_session_internal(p_session,p_token);
 SELECT config INTO cfg FROM public.scanner_settings WHERE occasion_id=s.occasion_id;
 IF NOT coalesce((cfg#>>'{manual_search,users}')::boolean,false) THEN RAISE insufficient_privilege USING MESSAGE='manual_search_disabled'; END IF;
 IF length(p_query) NOT BETWEEN 2 AND 100 THEN RETURN jsonb_build_object('code',400,'reason','invalid_query'); END IF;
 IF NOT public.admit_scan_access_v1(s.occasion_id,true) THEN RETURN jsonb_build_object('code',429,'reason','abuse_limit_exceeded'); END IF;
 SELECT coalesce(jsonb_agg(item ORDER BY id),'[]'::jsonb) INTO result FROM (
 SELECT u.id,jsonb_build_object('user_id',u.id,'holder_name',concat_ws(' ',u.name,u.surname),'symbol',u.id) item
 FROM public.occasion_users ou JOIN public.user_info u ON u.id=ou."user"
 JOIN public.occasions o ON o.id=ou.occasion
 LEFT JOIN public.organization_users orgu ON orgu."user"=u.id AND orgu.organization=o.organization
 WHERE ou.occasion=s.occasion_id AND u.id>p_after AND orgu.is_hidden IS NOT TRUE
 AND strpos(lower(concat_ws(' ',u.name,u.surname)),lower(p_query))>0 ORDER BY u.id LIMIT 30) rows;
 RETURN jsonb_build_object('code',200,'data',result,'server_time',now());
END $function$

CREATE OR REPLACE FUNCTION public.select_spot_single_internal_v1(form_key uuid, secret_id uuid, spot_id bigint, selecting boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE bp bigint; occ bigint; org bigint; un bigint; s eshop.spots; policy jsonb; scopes jsonb; costs jsonb; r jsonb; held bigint; duration_seconds integer; form_data jsonb; form_open boolean; fid bigint;
BEGIN
 IF secret_id IS NULL OR selecting IS NULL THEN RETURN jsonb_build_object('code',400,'message','Invalid reservation'); END IF;
 SELECT f.blueprint,f.occasion,o.organization,o.unit,f.id,f.is_open INTO bp,occ,org,un,fid,form_open FROM public.forms f
 JOIN public.occasions o ON o.id=f.occasion WHERE f.key=form_key;
 IF bp IS NULL THEN RETURN jsonb_build_object('code',404,'message','Form blueprint not found'); END IF;
 PERFORM public.check_occasion_writable(occ);
 -- A buyer's active inventory is serialized before the individual spot lock.
 PERFORM pg_advisory_xact_lock(hashtextextended('hold:'||secret_id::text,0));
 SELECT * INTO s FROM eshop.spots WHERE id=spot_id AND blueprint=bp FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('code',404,'message','Spot not found'); END IF;
 IF s.order_product_ticket IS NOT NULL THEN RETURN jsonb_build_object('code',409,'message','Spot is already ordered'); END IF;
 IF s.secret_expiration_time<=clock_timestamp() THEN
  UPDATE eshop.spots SET secret=NULL,secret_expiration_time=NULL WHERE id=spot_id;
  s.secret:=NULL; s.secret_expiration_time:=NULL;
 END IF;
 IF s.secret IS NOT NULL AND s.secret IS DISTINCT FROM secret_id THEN
  RETURN jsonb_build_object('code',403,'message','Spot is held by another buyer'); END IF;
 IF NOT selecting THEN
  UPDATE eshop.spots SET secret=NULL,secret_expiration_time=NULL,updated_at=now() WHERE id=spot_id;
  RETURN jsonb_build_object('code',200,'message','Spot deselected');
 END IF;
 -- A retry cannot move the original expiration, including after another tab reload.
 IF s.secret=secret_id THEN RETURN jsonb_build_object('code',200,'message','Spot selected','expiresAt',s.secret_expiration_time); END IF;
 r:=public.blueprint_hold_admission_internal(fid,ARRAY[s.id],secret_id);
 IF (r->>'code')::integer<>200 THEN RETURN r; END IF;
 IF selecting AND public.get_is_editor_order_on_occasion(occ) IS NOT TRUE THEN
  form_data:=public.get_effective_form_data(fid);
  IF form_open IS NOT TRUE OR
   (coalesce(form_data#>>'{schedule,start_time}',form_data->>'start_time'))::timestamptz>clock_timestamp() OR
   (coalesce(form_data#>>'{schedule,end_time}',form_data->>'end_time'))::timestamptz<clock_timestamp() THEN
   RETURN jsonb_build_object('code',403,'message','Form is not open'); END IF;
 END IF;
 policy:=public.abuse_effective_rules_v1('spot.hold',un,org);
 scopes:=jsonb_build_object('recipient',secret_id,'unit',un,'organization',org);
 FOR r IN SELECT value FROM jsonb_array_elements(policy->'rules') ORDER BY value->>'rule_key' LOOP
  PERFORM pg_advisory_xact_lock(hashtextextended('abuse:'||(r->>'rule_key')||':'||(scopes->>(r->>'scope_kind')),0));
 END LOOP;
 SELECT count(*) INTO held FROM eshop.spots WHERE secret=secret_id AND secret_expiration_time>clock_timestamp() AND order_product_ticket IS NULL;
 costs:=jsonb_build_object('hold.active.buyer',held+1);
 PERFORM public.abuse_charge_v1(policy,scopes,costs);
 SELECT (x->>'base_limit')::integer INTO duration_seconds FROM jsonb_array_elements(public.abuse_effective_rules_v1('hold.duration',un,org)->'rules') x;
 IF duration_seconds IS NULL THEN RAISE configuration_limit_exceeded USING MESSAGE='abuse_policy_missing'; END IF;
 UPDATE eshop.spots SET secret=secret_id,secret_expiration_time=clock_timestamp()+make_interval(secs=>duration_seconds),updated_at=now() WHERE id=spot_id RETURNING * INTO s;
 RETURN jsonb_build_object('code',200,'message','Spot selected','expiresAt',s.secret_expiration_time);
END $function$

CREATE OR REPLACE FUNCTION public.select_spot(form_key uuid, secret_id uuid, spot_id bigint, selecting boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE ids bigint[]; member_id bigint; r jsonb; occ bigint; bp bigint; fid bigint;
BEGIN
 SELECT occasion,blueprint,id INTO occ,bp,fid FROM public.forms WHERE key=form_key;
 PERFORM public.lock_blueprint_scope_internal(ARRAY[occ]);
 PERFORM pg_advisory_xact_lock(hashtextextended('hold:'||secret_id::text,0));
 ids:=public.blueprint_selection_unit_spots_internal(spot_id);
 PERFORM 1 FROM public.forms WHERE id=fid FOR UPDATE;
 PERFORM public.lock_blueprint_hold_scope_internal(ids);
 PERFORM 1 FROM eshop.spots WHERE id=ANY(ids) ORDER BY id FOR UPDATE;
 BEGIN
  IF selecting AND EXISTS(SELECT 1 FROM eshop.spots s LEFT JOIN eshop.blueprint_seat_bindings b ON b.spot=s.id
   WHERE s.id=ANY(ids) AND (b.blocked OR s.product IS NULL)
    AND NOT coalesce(s.secret=secret_id AND s.secret_expiration_time>clock_timestamp(),false)) THEN
   RAISE check_violation USING MESSAGE='BLUEPRINT_SEAT_UNAVAILABLE'; END IF;
  IF selecting THEN
   r:=public.blueprint_hold_admission_internal(fid,ids,secret_id);
   IF (r->>'code')::integer<>200 THEN RETURN r; END IF;
  END IF;
  FOREACH member_id IN ARRAY ids LOOP
   r:=public.select_spot_single_internal_v1(form_key,secret_id,member_id,selecting);
   IF coalesce((r->>'code')::integer,500)<>200 THEN RAISE check_violation USING MESSAGE='BLUEPRINT_HOLD_REJECTED'; END IF;
  END LOOP;
 EXCEPTION WHEN check_violation THEN
  RETURN coalesce(r,jsonb_build_object('code',409,'reason',SQLERRM,'message',SQLERRM));
 END;
 RETURN r||jsonb_build_object('spotIds',to_jsonb(ids));
END $function$

CREATE OR REPLACE FUNCTION public.set_abuse_policy_v1(p_expected_revision bigint, p_reason text, p_changes jsonb)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_revision bigint; c jsonb; r public.abuse_policy_rules; v_old jsonb; v_author text;
BEGIN
 PERFORM public.require_service_role();
 IF length(btrim(p_reason)) NOT BETWEEN 8 AND 1000 OR p_reason IS NULL OR jsonb_typeof(p_changes) IS DISTINCT FROM 'array'
  OR jsonb_array_length(p_changes) NOT BETWEEN 1 AND 100 THEN RAISE invalid_parameter_value USING MESSAGE='invalid abuse policy batch'; END IF;
 SELECT revision INTO v_revision FROM public.abuse_policy_revision FOR UPDATE;
 IF p_expected_revision IS DISTINCT FROM v_revision THEN RAISE serialization_failure USING MESSAGE='abuse policy revision conflict'; END IF;
 v_author:=coalesce(auth.uid()::text,session_user::text);
 SELECT jsonb_build_object('rules',(SELECT jsonb_agg(to_jsonb(x)) FROM public.abuse_policy_rules x),
 'overrides',(SELECT jsonb_agg(to_jsonb(x)) FROM public.abuse_policy_overrides x)) INTO v_old;
 FOR c IN SELECT value FROM jsonb_array_elements(p_changes) LOOP
  IF EXISTS(SELECT 1 FROM jsonb_object_keys(c) k WHERE k NOT IN ('rule_key','base_limit','target_kind','target_id','expires_at')) THEN
   RAISE invalid_parameter_value USING MESSAGE='unsupported abuse policy parameter'; END IF;
  SELECT * INTO r FROM public.abuse_policy_rules WHERE rule_key=c->>'rule_key';
  IF NOT FOUND OR (c->>'base_limit')::bigint IS NULL OR (c->>'base_limit')::bigint NOT BETWEEN 1 AND r.hard_cap THEN
   RAISE invalid_parameter_value USING MESSAGE='invalid abuse policy limit'; END IF;
  IF c ? 'target_kind' THEN
   IF (c->>'target_kind'='unit' AND r.scope_kind<>'unit') OR
    (c->>'target_kind'='organization' AND r.scope_kind NOT IN ('unit','organization')) OR
    c->>'target_kind' NOT IN ('unit','organization') OR (c->>'target_id')::bigint IS NULL OR
    (c->>'expires_at')::timestamptz IS NULL OR (c->>'expires_at')::timestamptz<=statement_timestamp() OR
    (c->>'expires_at')::timestamptz>statement_timestamp()+interval '90 days' THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid abuse override scope or expiry'; END IF;
   IF NOT (CASE WHEN c->>'target_kind'='unit' THEN EXISTS(SELECT 1 FROM public.units WHERE id=(c->>'target_id')::bigint)
    ELSE EXISTS(SELECT 1 FROM public.organizations WHERE id=(c->>'target_id')::bigint) END) THEN
    RAISE invalid_parameter_value USING MESSAGE='unknown abuse override target'; END IF;
   INSERT INTO public.abuse_policy_overrides VALUES(r.rule_key,c->>'target_kind',(c->>'target_id')::bigint,
    (c->>'base_limit')::bigint,(c->>'expires_at')::timestamptz,p_reason,v_author)
   ON CONFLICT(rule_key,target_kind,target_id) DO UPDATE SET base_limit=excluded.base_limit,expires_at=excluded.expires_at,reason=excluded.reason,author=excluded.author;
  ELSE
   IF c ? 'target_id' OR c ? 'expires_at' THEN RAISE invalid_parameter_value USING MESSAGE='override target required'; END IF;
   UPDATE public.abuse_policy_rules SET base_limit=(c->>'base_limit')::bigint WHERE rule_key=r.rule_key;
  END IF;
 END LOOP;
 UPDATE public.abuse_policy_revision SET revision=revision+1 RETURNING revision INTO v_revision;
 INSERT INTO public.abuse_policy_audit SELECT v_revision,clock_timestamp(),v_author,p_reason,v_old,
  jsonb_build_object('rules',(SELECT jsonb_agg(to_jsonb(x)) FROM public.abuse_policy_rules x),
   'overrides',(SELECT jsonb_agg(to_jsonb(x)) FROM public.abuse_policy_overrides x));
 RETURN v_revision;
END $function$

CREATE OR REPLACE FUNCTION public.set_cleaning_notifications_muted_client_sync_v1(p_occasion bigint, p_muted boolean, p_command_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_begin jsonb; v_hash text; v_result jsonb;
  v_current boolean; v_impacts jsonb; v_replacements jsonb;
BEGIN
  IF v_actor IS NULL THEN RAISE insufficient_privilege USING MESSAGE='sign in required'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'occasion',p_occasion,'muted',COALESCE(p_muted,false))::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'cleaning.notifications.set',
    p_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  SELECT COALESCE((ou.data->>'cleaning_notifications_off')::boolean,false)
    INTO v_current FROM public.occasion_users ou WHERE ou.occasion=p_occasion
      AND ou."user"=v_actor FOR UPDATE;
  v_result:=public.set_cleaning_notifications_muted_internal_v1(p_occasion,p_muted);
  IF COALESCE((v_result->>'code')::integer,500)<>200 THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',
      COALESCE((v_result->>'code')::integer,400),COALESCE(v_result->'data','{}')||
      jsonb_build_object('message',v_result->>'message')); END IF;
  IF v_current IS NOT DISTINCT FROM COALESCE(p_muted,false) THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'unchanged',200,
      v_result->'data'); END IF;
  v_impacts:=jsonb_build_array(jsonb_build_object(
    'component','private_profile','userId',v_actor));
  v_replacements:=jsonb_build_array(jsonb_build_object(
    'component','private_profile','userId',v_actor,
    'payload',public.get_private_profile_payload_v1(p_occasion,v_actor)));
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'cleaning.notifications.set','profile',jsonb_build_array(jsonb_build_object(
      'entityType','cleaning_preference','entityId',v_actor,'operation','update',
      'safeLabel','Cleaning notifications','changedFields',jsonb_build_array('muted'))),
    '{}',v_impacts,'[]',v_result->'data','{}','[]','user',NULL,v_replacements);
END; $function$

CREATE OR REPLACE FUNCTION public.set_cleaning_notifications_muted_internal_v1(p_occasion bigint, p_muted boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_user uuid := auth.uid();
  v_found boolean;
BEGIN
  IF v_user IS NULL THEN
    RETURN jsonb_build_object('code', 401, 'message', 'Sign in is required');
  END IF;

  UPDATE public.occasion_users
  SET data = COALESCE(data, '{}'::jsonb)
             || jsonb_build_object('cleaning_notifications_off', COALESCE(p_muted, false))
  WHERE occasion = p_occasion AND "user" = v_user
  RETURNING true INTO v_found;

  IF NOT COALESCE(v_found, false) THEN
    RETURN jsonb_build_object('code', 404, 'message', 'Participant not found on this occasion');
  END IF;

  RETURN jsonb_build_object(
    'code', 200,
    'data', jsonb_build_object('muted', COALESCE(p_muted, false))
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.set_cleaning_reporter_blocked_client_sync_v1(p_occasion bigint, p_user uuid, p_blocked boolean, p_command_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_begin jsonb; v_hash text; v_result jsonb;
  v_current boolean; v_impacts jsonb; v_replacements jsonb:='[]'::jsonb;
BEGIN
  IF v_actor IS NULL THEN RAISE insufficient_privilege USING MESSAGE='sign in required'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'occasion',p_occasion,'userId',p_user,'blocked',p_blocked)::text,'UTF8'),
    'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'cleaning.reporter.set',
    p_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  SELECT ou.is_cleaning_blocked INTO v_current FROM public.occasion_users ou
    WHERE ou.occasion=p_occasion AND ou."user"=p_user FOR UPDATE;
  v_result:=public.set_cleaning_reporter_blocked_internal_v1(
    p_occasion,p_user,p_blocked);
  IF COALESCE((v_result->>'code')::integer,500)<>200 THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',
      COALESCE((v_result->>'code')::integer,400),COALESCE(v_result->'data','{}')||
      jsonb_build_object('message',v_result->>'message')); END IF;
  IF v_current IS NOT DISTINCT FROM p_blocked THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'unchanged',200,
      v_result->'data'); END IF;
  v_impacts:=jsonb_build_array(jsonb_build_object(
    'component','private_profile','userId',p_user));
  IF p_user=v_actor THEN v_replacements:=jsonb_build_array(jsonb_build_object(
    'component','private_profile','userId',v_actor,
    'payload',public.get_private_profile_payload_v1(p_occasion,v_actor))); END IF;
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'cleaning.reporter.set','profile',jsonb_build_array(jsonb_build_object(
      'entityType','occasion_user','entityId',p_user,'operation','update',
      'safeLabel','Cleaning reporter','changedFields',jsonb_build_array('blocked'))),
    '{}',v_impacts,'[]',v_result->'data','{}','[]','user',NULL,v_replacements);
END; $function$

CREATE OR REPLACE FUNCTION public.set_cleaning_reporter_blocked_internal_v1(p_occasion bigint, p_user uuid, p_blocked boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_caller uuid := auth.uid();
  v_found boolean;
BEGIN
  IF v_caller IS NULL THEN
    RETURN jsonb_build_object('code', 401, 'message', 'Sign in is required');
  END IF;

  IF p_user IS NULL THEN
    RETURN jsonb_build_object('code', 400, 'message', 'Target user is required');
  END IF;

  -- Blocking needs crew rights; unblocking needs the higher editor right.
  IF p_blocked THEN
    IF NOT public.get_is_cleaning_crew_on_occasion(p_occasion) THEN
      RETURN jsonb_build_object('code', 403, 'message', 'Cleaning crew access required');
    END IF;
  ELSE
    IF NOT public.get_is_editor_on_occasion(p_occasion) THEN
      RETURN jsonb_build_object('code', 403, 'message', 'Editor access required to unblock');
    END IF;
  END IF;

  IF p_blocked THEN
    UPDATE public.occasion_users
    SET is_cleaning_blocked = true,
        data = COALESCE(data, '{}'::jsonb) || jsonb_build_object(
          'cleaning_blocked_by', v_caller::text,
          'cleaning_blocked_at', to_char(now(), 'YYYY-MM-DD"T"HH24:MI:SSOF'))
    WHERE occasion = p_occasion AND "user" = p_user
    RETURNING true INTO v_found;
  ELSE
    UPDATE public.occasion_users
    SET is_cleaning_blocked = false,
        data = COALESCE(data, '{}'::jsonb) - 'cleaning_blocked_by' - 'cleaning_blocked_at'
    WHERE occasion = p_occasion AND "user" = p_user
    RETURNING true INTO v_found;
  END IF;

  IF NOT COALESCE(v_found, false) THEN
    RETURN jsonb_build_object('code', 404, 'message', 'Participant not found on this occasion');
  END IF;

  RETURN jsonb_build_object(
    'code', 200,
    'data', jsonb_build_object('blocked', p_blocked)
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.set_event_attendance_client_sync_v1(p_event_id bigint, p_participant_id uuid, p_action text, p_command_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_actor uuid:=auth.uid(); v_occasion bigint; v_event public.events%ROWTYPE;
  v_begin jsonb; v_hash text; v_response jsonb; v_commit jsonb;
  v_private_revision bigint; v_live_revision bigint; v_private_payload jsonb;
  v_live_payload jsonb; v_code integer; v_registration_start timestamptz;
  v_feature jsonb; v_limit integer; v_count bigint; v_group bigint;
  v_is_male boolean; v_changed boolean:=false; v_status text;
  v_needs_occasion_join boolean:=false; v_profile_revision bigint;
  v_profile_payload jsonb; v_private_impacts jsonb; v_items jsonb;
  v_is_publishable boolean; v_companion_owner uuid;
BEGIN
  IF p_action NOT IN ('sign_in','sign_out') OR p_participant_id IS NULL THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid attendance command';
  END IF;
  SELECT r.occasion INTO v_occasion FROM public.client_mutation_receipts r WHERE r.command_id=p_command_id
    AND r.actor_id=v_actor AND r.command_name='event.attendance.'||p_action;
  IF NOT FOUND THEN
  SELECT e.occasion,NOT o.is_hidden INTO v_occasion,v_is_publishable
  FROM public.events e JOIN public.occasions o ON o.id=e.occasion
  WHERE e.id=p_event_id;
  ELSE
    SELECT NOT is_hidden INTO v_is_publishable FROM public.occasions WHERE id=v_occasion;
  END IF;
  IF v_actor IS NULL OR v_occasion IS NULL OR NOT (
    v_actor=p_participant_id OR EXISTS (SELECT 1 FROM public.user_companions c
      WHERE c.occasion=v_occasion AND c."user"=v_actor AND c.companion=p_participant_id AND COALESCE((public.get_companion_feature_policy_v1(v_occasion)->>'is_enabled')::boolean,false))
    OR public.get_is_editor_on_occasion(v_occasion)) THEN
    RAISE insufficient_privilege USING MESSAGE='participant attendance permission required';
  END IF;
  SELECT c."user" INTO v_companion_owner FROM public.user_companions c
    JOIN public.occasion_users ou ON ou."user"=c."user" AND ou.occasion=v_occasion
    WHERE c.occasion=v_occasion AND c.companion=p_participant_id ORDER BY c."user" LIMIT 1;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object('eventId',p_event_id,
    'participantId',p_participant_id,'action',p_action)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'event.attendance.'||p_action,
    v_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(
    'attendance-user:'||p_participant_id::text||':'||v_occasion::text,0));
  FOR v_group IN SELECT ee."group" FROM public.exclusive_events ee
      WHERE ee.event=p_event_id ORDER BY ee."group" LOOP
    PERFORM pg_advisory_xact_lock(hashtextextended(
      'attendance-group:'||v_group::text,0));
  END LOOP;
  SELECT * INTO STRICT v_event FROM public.events e WHERE e.id=p_event_id
    AND e.occasion=v_occasion FOR UPDATE;

  IF p_action='sign_out' THEN
    IF NOT EXISTS (SELECT 1 FROM public.event_users eu
      WHERE eu.event=p_event_id AND eu."user"=p_participant_id) THEN
      v_status:='unchanged'; v_code:=404;
    ELSIF clock_timestamp() > v_event.end_time THEN
      v_status:='rejected'; v_code:=201;
    ELSE
      DELETE FROM public.event_users WHERE event=p_event_id AND "user"=p_participant_id;
      v_changed:=true; v_code:=200;
    END IF;
  ELSE
    IF NOT EXISTS (SELECT 1 FROM public.occasion_users ou
      WHERE ou.occasion=v_occasion AND ou."user"=p_participant_id) THEN
      IF v_actor=p_participant_id AND EXISTS (SELECT 1 FROM public.occasions o
        WHERE o.id=v_occasion AND o.is_open) THEN
        v_needs_occasion_join:=true;
      END IF;
      IF NOT v_needs_occasion_join THEN
        v_status:='rejected'; v_code:=403;
      END IF;
    END IF;
    IF v_code IS NULL AND EXISTS (SELECT 1 FROM public.event_users eu
      WHERE eu.event=p_event_id AND eu."user"=p_participant_id) THEN
      v_status:='unchanged'; v_code:=103;
    END IF;
    IF v_code IS NULL AND clock_timestamp() > v_event.end_time THEN
      v_status:='rejected'; v_code:=100;
    END IF;

    IF v_code IS NULL AND COALESCE((v_event.data->>'is_counseling_slot')::boolean,false) THEN
      SELECT f INTO v_feature FROM public.occasions o,
        LATERAL jsonb_array_elements(o.features) f
      WHERE o.id=v_occasion AND f->>'code'='counseling' LIMIT 1;
      IF v_feature IS NULL OR COALESCE((v_feature->>'is_enabled')::boolean,false)=false THEN
        v_status:='rejected'; v_code:=108;
      ELSE
        v_registration_start:=(v_feature->>'registration_start_time')::timestamptz;
        IF v_registration_start IS NOT NULL AND clock_timestamp()<v_registration_start THEN
          v_status:='rejected'; v_code:=104;
        END IF;
        v_limit:=COALESCE((v_feature->>'max_active_bookings')::integer,1);
        IF v_code IS NULL AND v_limit>0 THEN
          SELECT count(*) INTO v_count FROM public.event_users eu
          JOIN public.events e ON e.id=eu.event
          WHERE eu."user"=p_participant_id AND e.occasion=v_occasion
            AND COALESCE((e.data->>'is_counseling_slot')::boolean,false)
            AND e.end_time>clock_timestamp();
          IF v_count>=v_limit THEN v_status:='rejected'; v_code:=109; END IF;
        END IF;
      END IF;
    ELSIF v_code IS NULL THEN
      SELECT f INTO v_feature FROM public.occasions o,
        LATERAL jsonb_array_elements(o.features) f
      WHERE o.id=v_occasion AND f->>'code'='workshops' LIMIT 1;
      IF v_feature IS NOT NULL THEN
        IF COALESCE((v_feature->>'is_enabled')::boolean,false)=false THEN
          v_status:='rejected'; v_code:=108;
        ELSE
          v_registration_start:=(v_feature->>'start_time')::timestamptz;
          IF v_registration_start IS NOT NULL AND clock_timestamp()<v_registration_start THEN
            v_status:='rejected'; v_code:=104;
          END IF;
        END IF;
      END IF;
    END IF;

    IF v_code IS NULL AND EXISTS (
      SELECT 1 FROM public.exclusive_events target
      JOIN public.exclusive_events occupied ON occupied."group"=target."group"
      JOIN public.event_users eu ON eu.event=occupied.event
      WHERE target.event=p_event_id AND eu."user"=p_participant_id) THEN
      v_status:='rejected'; v_code:=102;
    END IF;
    IF v_code IS NULL AND EXISTS (
      SELECT 1 FROM public.event_users eu JOIN public.events e ON e.id=eu.event
      WHERE eu."user"=p_participant_id AND e.id<>p_event_id
        AND e.start_time<v_event.end_time AND e.end_time>v_event.start_time) THEN
      v_status:='rejected'; v_code:=107;
    END IF;
    IF v_code IS NULL AND COALESCE(v_event.max_participants,0)>0 THEN
      SELECT count(*) INTO v_count FROM public.event_users eu WHERE eu.event=p_event_id;
      IF v_event.split_for_men_women THEN
        SELECT COALESCE(u.sex='male',false) INTO v_is_male
          FROM public.user_info u WHERE u.id=p_participant_id;
        SELECT count(*) INTO v_count FROM public.event_users eu
          JOIN public.user_info u ON u.id=eu."user" WHERE eu.event=p_event_id
            AND (u.sex='male')=v_is_male;
        IF v_count>=v_event.max_participants/2 THEN
          v_status:='rejected'; v_code:=CASE WHEN v_is_male THEN 105 ELSE 106 END;
        END IF;
      ELSIF v_count>=v_event.max_participants THEN
        v_status:='rejected'; v_code:=101;
      END IF;
    END IF;
    IF v_code IS NULL THEN
      IF v_needs_occasion_join THEN
        PERFORM public.add_user_to_occasion_internal_v1(v_occasion,p_participant_id);
        IF NOT EXISTS (SELECT 1 FROM public.occasion_users ou
          WHERE ou.occasion=v_occasion AND ou."user"=p_participant_id) THEN
          RAISE EXCEPTION 'occasion membership handler did not create membership';
        END IF;
      END IF;
      INSERT INTO public.event_users(event,"user") VALUES(p_event_id,p_participant_id);
      v_changed:=true; v_code:=200;
    END IF;
  END IF;

  IF NOT v_changed THEN
    v_response:=jsonb_build_object('status',v_status,'code',v_code,
      'data',jsonb_build_object('eventId',p_event_id,'participantId',p_participant_id,
        'isSignedIn',EXISTS(SELECT 1 FROM public.event_users eu
          WHERE eu.event=p_event_id AND eu."user"=p_participant_id),
        'eventsRegistrationStart',v_registration_start),
      'mutation',jsonb_build_object('commandId',p_command_id,'receiptId',p_command_id,
        'commitId',NULL,'replayed',false,'occurredAt',clock_timestamp()),
      'sync',jsonb_build_object('replacements','[]'::jsonb));
    RETURN public.finish_client_mutation_v1(p_command_id,v_response,NULL);
  END IF;

  v_items:=jsonb_build_array(jsonb_build_object(
      'entityType','event_attendance','entityId',p_event_id||':'||p_participant_id::text,
      'operation','update','safeLabel','Event attendance',
      'changedFields',jsonb_build_array('is_signed_in')));
  v_private_impacts:=jsonb_build_array(jsonb_build_object(
    'component','private_program','userId',p_participant_id));
  IF v_companion_owner IS NOT NULL THEN
    v_private_impacts:=v_private_impacts||jsonb_build_array(jsonb_build_object(
      'component','private_profile','userId',v_companion_owner));
  END IF;
  IF v_needs_occasion_join THEN
    v_items:=v_items||jsonb_build_array(jsonb_build_object(
      'entityType','occasion_membership','entityId',p_participant_id,
      'operation','insert','safeLabel','Occasion membership',
      'changedFields',jsonb_build_array('occasion')));
    v_private_impacts:=v_private_impacts||jsonb_build_array(jsonb_build_object(
      'component','private_profile','userId',p_participant_id));
  END IF;
  v_commit:=public.record_client_sync_commit_v1(v_occasion,
    'event.attendance.'||p_action,'attendance',v_items,
    CASE WHEN v_is_publishable THEN ARRAY['live_public'] ELSE '{}'::text[] END,
    v_private_impacts,CASE WHEN v_is_publishable THEN jsonb_build_array(
      jsonb_build_object('component','live_public','entityId',p_event_id))
      ELSE '[]'::jsonb END,'user',NULL);
  SELECT source_revision INTO v_private_revision FROM public.client_sync_private_scopes
    WHERE component='private_program' AND occasion=v_occasion AND user_id=p_participant_id;
  IF v_needs_occasion_join OR v_companion_owner IS NOT NULL THEN
    SELECT source_revision INTO STRICT v_profile_revision
    FROM public.client_sync_private_scopes
    WHERE component='private_profile' AND occasion=v_occasion
      AND user_id=COALESCE(v_companion_owner,p_participant_id);
    v_profile_payload:=public.get_private_profile_payload_v1(
      v_occasion,COALESCE(v_companion_owner,p_participant_id));
  END IF;
  SELECT jsonb_build_object(
    'signedIn',COALESCE(jsonb_agg(eu.event ORDER BY eu.event),'[]'::jsonb),
    'saved',(SELECT COALESCE(jsonb_agg(es.event ORDER BY es.event),'[]'::jsonb)
      FROM public.event_users_saved es JOIN public.events e ON e.id=es.event
      WHERE es."user"=p_participant_id AND e.occasion=v_occasion))
    INTO v_private_payload FROM public.event_users eu JOIN public.events e ON e.id=eu.event
    WHERE eu."user"=p_participant_id AND e.occasion=v_occasion;
  IF v_is_publishable THEN
    SELECT source_revision INTO v_live_revision FROM public.client_sync_scopes
      WHERE component='live_public' AND scope_type='occasion' AND scope_id=v_occasion;
    INSERT INTO public.event_public_state
      (occasion,event,participant_count,saved_count,remaining_capacity,revision,projected_at)
    SELECT v_occasion,v_event.id,count(DISTINCT eu."user"),count(DISTINCT es."user"),
      CASE WHEN v_event.max_participants IS NULL THEN NULL
        ELSE GREATEST(v_event.max_participants-count(DISTINCT eu."user"),0) END,
      v_live_revision,clock_timestamp()
    FROM (SELECT 1) seed LEFT JOIN public.event_users eu ON eu.event=v_event.id
    LEFT JOIN public.event_users_saved es ON es.event=v_event.id
    ON CONFLICT (occasion,event) DO UPDATE SET
      participant_count=EXCLUDED.participant_count,saved_count=EXCLUDED.saved_count,
      remaining_capacity=EXCLUDED.remaining_capacity,revision=EXCLUDED.revision,
      projected_at=EXCLUDED.projected_at;
    SELECT jsonb_build_object(
      'events',COALESCE(jsonb_agg(jsonb_build_object('eventId',s.event,
        'participantCount',s.participant_count,'savedCount',s.saved_count,
        'remainingCapacity',s.remaining_capacity) ORDER BY s.event),'[]'::jsonb),
      'cleaning',(SELECT COALESCE(jsonb_agg(jsonb_build_object('placeId',c.place,
        'status',c.status,'openReportCount',c.open_report_count) ORDER BY c.place),'[]'::jsonb)
        FROM public.cleaning_public_state c WHERE c.occasion=v_occasion))
      INTO v_live_payload FROM public.event_public_state s JOIN public.events e ON e.id=s.event
      WHERE s.occasion=v_occasion AND NOT e.is_hidden;
  END IF;
  v_response:=jsonb_build_object('status','applied','code',200,
    'data',jsonb_build_object('eventId',p_event_id,'participantId',p_participant_id,
      'isSignedIn',p_action='sign_in'),
    'mutation',jsonb_build_object('commandId',p_command_id,'receiptId',p_command_id,
      'commitId',v_commit->>'commitId','replayed',false,'occurredAt',v_commit->>'occurredAt'),
    'sync',jsonb_build_object('replacements',
      CASE WHEN v_is_publishable THEN jsonb_build_array(jsonb_build_object(
        'component','live_public','revision',v_live_revision,
        'payload',v_live_payload)) ELSE '[]'::jsonb END ||
      CASE WHEN v_actor=p_participant_id THEN jsonb_build_array(jsonb_build_object(
        'component','private_program','revision',v_private_revision,
        'payload',v_private_payload)) ELSE '[]'::jsonb END ||
        CASE WHEN v_needs_occasion_join OR v_companion_owner=v_actor
          THEN jsonb_build_array(jsonb_build_object(
          'component','private_profile','revision',v_profile_revision,
          'payload',v_profile_payload)) ELSE '[]'::jsonb END));
  RETURN public.finish_client_mutation_v1(p_command_id,v_response,
    (v_commit->>'commitId')::uuid);
END; $function$

CREATE OR REPLACE FUNCTION public.set_event_speakers(p_event bigint, p_speakers bigint[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE oc bigint; ver bigint; result jsonb;
BEGIN
 SELECT occasion INTO oc FROM public.events WHERE id=p_event;
 IF oc IS NULL THEN RETURN jsonb_build_object('code',404); END IF;
 IF public.get_is_editor_on_occasion(oc) IS NOT TRUE THEN RETURN jsonb_build_object('code',403); END IF;
 PERFORM 1 FROM public.events WHERE id=p_event FOR UPDATE;
 SELECT coalesce(v.version,0) INTO ver FROM (SELECT 1) seed LEFT JOIN public.client_aggregate_versions v
 ON v.aggregate_type='event' AND v.scope_type='occasion' AND v.scope_id=oc AND v.aggregate_id=p_event::text;
 result:=public.save_event_speakers_client_sync_v1(oc,p_event,extensions.gen_random_uuid(),ver,p_speakers);
