CREATE OR REPLACE FUNCTION public.set_saved_program_client_sync_v1(p_occasion bigint, p_event_ids bigint[], p_mode text, p_command_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_actor UUID := auth.uid();
  v_response JSONB;
  v_revision BIGINT;
  v_payload JSONB;
BEGIN
  v_response := public.set_saved_program_client_sync_v1_transactional(
    p_occasion, p_event_ids, p_mode, p_command_id
  );

  IF jsonb_array_length(v_response #> '{sync,replacements}') = 0 THEN
    SELECT source_revision INTO v_revision
    FROM public.client_sync_private_scopes
    WHERE component = 'private_program'
      AND occasion = p_occasion
      AND user_id = v_actor;

    IF v_revision IS NOT NULL THEN
      SELECT jsonb_build_object(
        'signedIn', (
          SELECT COALESCE(jsonb_agg(eu.event ORDER BY eu.event), '[]'::jsonb)
          FROM public.event_users eu
          JOIN public.events e ON e.id = eu.event
          WHERE eu."user" = v_actor AND e.occasion = p_occasion
        ),
        'saved', (
          SELECT COALESCE(jsonb_agg(es.event ORDER BY es.event), '[]'::jsonb)
          FROM public.event_users_saved es
          JOIN public.events e ON e.id = es.event
          WHERE es."user" = v_actor AND e.occasion = p_occasion
        )
      ) INTO v_payload;

      v_response := jsonb_set(
        v_response,
        '{sync,replacements}',
        jsonb_build_array(jsonb_build_object(
          'component', 'private_program',
          'revision', v_revision,
          'payload', v_payload
        ))
      );
    END IF;
  END IF;

  RETURN v_response;
END;
$function$

CREATE OR REPLACE FUNCTION public.set_unit_app_landing(p_unit bigint, p_occasion bigint, p_expected_occasion bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_org bigint;
  v_data jsonb;
  v_current bigint;
BEGIN
  SELECT organization INTO v_org FROM public.units WHERE id = p_unit;
  IF v_org IS NULL OR NOT public.get_is_admin_on_organization(v_org) THEN
    RAISE insufficient_privilege USING MESSAGE = 'Access denied';
  END IF;
  SELECT data INTO v_data FROM public.organizations WHERE id = v_org FOR UPDATE;
  IF NOT coalesce((v_data->>'IS_APP_SUPPORTED')::boolean, false) THEN
    RAISE invalid_parameter_value USING MESSAGE = 'Application is not enabled';
  END IF;
  v_current := (v_data->>'DEFAULT_OCCASION')::bigint;
  IF v_current IS DISTINCT FROM p_expected_occasion THEN
    RAISE serialization_failure USING MESSAGE = 'App landing changed. Refresh and try again.';
  END IF;
  IF p_occasion IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.occasions WHERE id = p_occasion
      AND unit = p_unit AND organization = v_org AND is_open = true
  ) THEN
    RAISE invalid_parameter_value USING MESSAGE = 'Choose an open occasion in this unit';
  END IF;
  -- The representative occasion is a separate application setting; preserve it.
  UPDATE public.organizations
    SET data = (coalesce(data, '{}'::jsonb) - 'DEFAULT_OCCASION')
      || CASE WHEN p_occasion IS NULL THEN '{}'::jsonb
         ELSE jsonb_build_object('DEFAULT_OCCASION', p_occasion) END
    WHERE id = v_org;
  RETURN public.get_unit_app_landing(p_unit);
END;
$function$

CREATE OR REPLACE FUNCTION public.setup_crons(p_project_url text)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
BEGIN
  -- Security Check
  IF auth.role() <> 'service_role' AND session_user <> 'postgres' THEN
      RAISE EXCEPTION 'Access Denied: Service role required.';
  END IF;

  -- Schedule the apply_planned_changes cron job (runs every minute)
  PERFORM cron.schedule(
    'apply_planned_changes',
    '*/1 * * * *',
    'SELECT apply_planned_changes()'
  );

  -- BankSync owns bank polling. This job only recovers durable control intents.
  PERFORM cron.schedule('festapp_canonical_bank_sync_reconcile','*/5 * * * *',
    format($$SELECT net.http_post(url:='%s/functions/v1/bank-sync-reconcile',
      body:=jsonb_build_object('requestSecret',public.generate_request_secret(3600)),
      timeout_milliseconds:=360000)$$,p_project_url));

  PERFORM cron.schedule('festapp_canonical_waitlist_expiry','*/1 * * * *','SELECT public.expire_waitlist_offers(100)');
  PERFORM cron.schedule('festapp_canonical_process_email_queue','*/1 * * * *','SELECT public.recover_email_delivery()');
END;
$function$

CREATE OR REPLACE FUNCTION public.setup_triggers(p_project_url text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  relation_name text;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' AND session_user <> 'postgres' THEN
    RAISE EXCEPTION 'Access Denied: Service role required.';
  END IF;
  IF p_project_url !~ '^https://[^/]+$' THEN
    RAISE EXCEPTION 'Project URL must be an HTTPS origin';
  END IF;

  FOREACH relation_name IN ARRAY ARRAY[
    'events', 'icons', 'information', 'news', 'occasions', 'places',
    'user_info', 'speakers', 'speaker_topics', 'cleaning_reports'
  ] LOOP
    EXECUTE format('DROP TRIGGER IF EXISTS handle_updated_at ON public.%I', relation_name);
    EXECUTE format(
      'CREATE TRIGGER handle_updated_at BEFORE UPDATE ON public.%I '
      'FOR EACH ROW EXECUTE FUNCTION extensions.moddatetime(''updated_at'')',
      relation_name
    );
  END LOOP;

  -- Notification delivery is an explicit domain-command operation.
  UPDATE public.notification_runtime SET endpoint=p_project_url||'/functions/v1/notify' WHERE singleton;
END
$function$

CREATE OR REPLACE FUNCTION public.set_user_password_token(token uuid, password text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_user_id uuid;
  token_created_at timestamptz;
  email text;
  encrypted_pw text;
BEGIN
  DELETE FROM public.user_reset_token urt
  WHERE urt.token=$1
  RETURNING urt."user",urt.created_at INTO v_user_id,token_created_at;
  IF v_user_id IS NULL OR token_created_at < clock_timestamp()-interval '30 minutes' THEN
    RETURN jsonb_build_object('code',403);
  END IF;
  IF length(password)<8 THEN RETURN jsonb_build_object('code',400); END IF;

  encrypted_pw:=crypt(password,gen_salt('bf'));
  UPDATE auth.users SET encrypted_password=encrypted_pw WHERE id=v_user_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('code',404); END IF;

  UPDATE auth.refresh_tokens SET revoked=true WHERE auth.refresh_tokens.user_id=v_user_id::text;
  DELETE FROM auth.sessions WHERE auth.sessions.user_id=v_user_id;
  SELECT email_readonly INTO email FROM public.user_info WHERE id=v_user_id;
  IF email IS NULL THEN RETURN jsonb_build_object('code',404); END IF;
  RETURN jsonb_build_object('code',200,'email',email);
END
$function$

