CREATE OR REPLACE FUNCTION public.storno_order_client_sync_v1(p_order bigint, p_command_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_occasion bigint; v_begin jsonb; v_hash text;
  v_before_users uuid[]; v_unchanged boolean:=false;
BEGIN
  PERFORM public.lock_blueprint_scope_internal(ARRAY[(SELECT occasion FROM eshop.orders WHERE id=p_order)]);
  SELECT o.occasion INTO v_occasion FROM eshop.orders o WHERE o.id=p_order;
  IF v_actor IS NULL OR v_occasion IS NULL
    OR NOT public.get_is_editor_order_on_occasion(v_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='order editor required'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'order',p_order)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,
    'inventory.order.cancel',v_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  -- A committed cancellation needs only a receipt, without another admission.
  IF (SELECT state FROM eshop.orders WHERE id=p_order)='storno' THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'unchanged',200,
      jsonb_build_object('orderId',p_order));
  END IF;
  BEGIN
    -- Preserve admission -> domain locks, also relative to deletion. If another
    -- cancellation wins while waiting, roll back this attempt's admission.
    PERFORM public.admit_order_mutation_v1(v_occasion,(SELECT count(*) FROM eshop.order_product_ticket WHERE "order"=p_order));
    PERFORM public.lock_order_capacity_scope_internal(ARRAY[p_order]);
    IF (SELECT state FROM eshop.orders WHERE id=p_order)='storno' THEN
      RAISE SQLSTATE 'P0C01' USING MESSAGE='cancellation already committed'; END IF;
    SELECT COALESCE(array_agg(ou."user"),'{}'::uuid[]) INTO v_before_users
      FROM public.occasion_users ou WHERE ou.occasion=v_occasion;
    PERFORM public.update_order_and_tickets_to_storno_ws_internal_v1(p_order);
  EXCEPTION WHEN SQLSTATE 'P0C01' THEN v_unchanged:=true;
  END;
  IF v_unchanged THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'unchanged',200,
      jsonb_build_object('orderId',p_order));
  END IF;
  RETURN public.complete_profile_inventory_membership_mutation_v1(
    p_command_id,v_occasion,'inventory.order.cancel',
    jsonb_build_array(jsonb_build_object('entityType','order','entityId',p_order,
      'operation','update','safeLabel','Order cancellation',
      'changedFields',jsonb_build_array('state','tickets','membership','allocations'))),
    v_before_users,jsonb_build_object('orderId',p_order));
END; $function$

CREATE OR REPLACE FUNCTION public.storno_ticket_221(ticket_id bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
    ticket_record RECORD;
    order_id BIGINT;
    ticket_price NUMERIC(10, 2) := 0;
    updated_tickets JSONB := '[]'::JSONB;
    original_data JSONB;
    ticket_data JSONB;
    product JSONB;
    remaining_active_tickets_count BIGINT;
BEGIN
    -- Check if the ticket exists and fetch its associated data
    SELECT t.*, o.id AS order_id, o.data AS order_data, t.occasion
    INTO ticket_record
    FROM eshop.tickets t
    JOIN eshop.order_product_ticket opt ON opt.ticket = t.id
    JOIN eshop.orders o ON o.id = opt."order"
    WHERE t.id = ticket_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Ticket not found (ID: %)', ticket_id;
    END IF;

    IF NOT get_is_editor_order_on_occasion(ticket_record.occasion) THEN
        RAISE EXCEPTION 'Permission denied to storno ticket on occasion %', ticket_record.occasion;
    END IF;

    -- Check if this is the last non-storno ticket on the order.
    SELECT COUNT(t.id)
    INTO remaining_active_tickets_count
    FROM eshop.tickets t
    JOIN eshop.order_product_ticket opt ON opt.ticket = t.id
    WHERE opt."order" = ticket_record.order_id
      AND t.id != ticket_id
      AND (t.state IS NULL OR t.state != 'storno');

    -- If it is the last active ticket, storno the whole order instead and exit.
    IF remaining_active_tickets_count = 0 THEN
        PERFORM public.update_order_and_tickets_to_storno_ws_221(ticket_record.order_id);
        RETURN; -- Exit the function
    END IF;

    -- --- Proceed with single ticket storno ---

    -- *** REFACTORED PART ***
    -- Call the helper to storno the single ticket and its relations
    PERFORM internal_storno_tickets_221(ARRAY[ticket_id]);
    -- All the logic for tickets, spots, and occasion_users is now done.

    -- Remove the ticket from orders.data and calculate the price reduction
    original_data := ticket_record.order_data;
    FOR ticket_data IN SELECT JSONB_ARRAY_ELEMENTS(original_data->'tickets') LOOP
        IF (ticket_data->>'id')::BIGINT = ticket_id THEN
            -- Calculate the price of all products in the ticket
            FOR product IN SELECT JSONB_ARRAY_ELEMENTS(ticket_data->'products') LOOP
                ticket_price := ticket_price + COALESCE((product->>'price')::NUMERIC, 0);
            END LOOP;
        ELSE
            -- Keep all other tickets
            updated_tickets := updated_tickets || ticket_data;
        END IF;
    END LOOP;

    -- Update the order's data and price
    UPDATE eshop.orders
    SET
        data = original_data || JSONB_BUILD_OBJECT('tickets', updated_tickets),
        price = COALESCE(price, 0) - ticket_price,
        updated_at = NOW()
    WHERE id = ticket_record.order_id;

    -- Save the change to orders_history
    INSERT INTO eshop.orders_history (
        "order",
        data,
        state,
        price,
        created_at
    )
    VALUES (
        ticket_record.order_id,
        original_data || JSONB_BUILD_OBJECT('tickets', updated_tickets),
        'ordered',
        COALESCE((SELECT price FROM eshop.orders WHERE id = ticket_record.order_id), 0),
        NOW()
    );

END;
$function$

CREATE OR REPLACE FUNCTION public.storno_ticket(ticket_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
    ticket_record RECORD;
    order_id BIGINT;
    ticket_price NUMERIC(10, 2) := 0;
    updated_tickets JSONB := '[]'::JSONB;
    original_data JSONB;
    ticket_data JSONB;
    product JSONB;
    remaining_opt_id BIGINT;
BEGIN
    -- Check if the ticket exists and fetch its associated data
    SELECT t.*, o.id AS order_id, o.data AS order_data, t.occasion
    INTO ticket_record
    FROM eshop.tickets t
    JOIN eshop.order_product_ticket opt ON opt.ticket = t.id
    JOIN eshop.orders o ON o.id = opt."order"
    WHERE t.id = ticket_id;

    IF NOT FOUND THEN
        RETURN JSONB_BUILD_OBJECT('code', 1001, 'message', 'Ticket not found');
    END IF;

    IF NOT get_is_editor_order_on_occasion(ticket_record.occasion) THEN
        RETURN JSONB_BUILD_OBJECT('code', 1002, 'message', 'Permission denied');
    END IF;

    -- Update ticket state to "storno"
    UPDATE eshop.tickets
    SET state = 'storno', updated_at = NOW()
    WHERE id = ticket_id;

    -- Nullify the relevant spot's order_product_ticket
    UPDATE eshop.spots
    SET order_product_ticket = NULL, secret = NULL, secret_expiration_time = NULL, updated_at = NOW(), resource = NULL, state = NULL
    WHERE order_product_ticket IN (
        SELECT id FROM eshop.order_product_ticket WHERE ticket = ticket_id
    );

    -- Find and keep one order_product_ticket and update its product to NULL
    SELECT id INTO remaining_opt_id
    FROM eshop.order_product_ticket
    WHERE ticket = ticket_id
    LIMIT 1;

    IF remaining_opt_id IS NOT NULL THEN
        UPDATE eshop.order_product_ticket
        SET product = NULL
        WHERE id = remaining_opt_id;

        -- Delete all other order_product_ticket records for the ticket
        DELETE FROM eshop.order_product_ticket
        WHERE ticket = ticket_id AND id != remaining_opt_id;
    END IF;

    -- Remove the ticket from orders.data and calculate the price reduction
    original_data := ticket_record.order_data;
    FOR ticket_data IN SELECT JSONB_ARRAY_ELEMENTS(original_data->'tickets') LOOP
        IF (ticket_data->>'id')::BIGINT = ticket_id THEN
            -- Calculate the price of all products in the ticket
            FOR product IN SELECT JSONB_ARRAY_ELEMENTS(ticket_data->'products') LOOP
                ticket_price := ticket_price + COALESCE((product->>'price')::NUMERIC, 0);
            END LOOP;
        ELSE
            -- Keep all other tickets
            updated_tickets := updated_tickets || ticket_data;
        END IF;
    END LOOP;

    -- Update the order's data and price
    UPDATE eshop.orders
    SET
        data = original_data || JSONB_BUILD_OBJECT('tickets', updated_tickets),
        price = COALESCE(price, 0) - ticket_price,
        updated_at = NOW()
    WHERE id = ticket_record.order_id;

    -- Save the change to orders_history
    INSERT INTO eshop.orders_history (
        "order",
        data,
        state,
        price,
        created_at
    )
    VALUES (
        ticket_record.order_id,
        original_data || JSONB_BUILD_OBJECT('tickets', updated_tickets),
        'ordered',
        COALESCE((SELECT price FROM eshop.orders WHERE id = ticket_record.order_id), 0),
        NOW()
    );

    -- Return success response
    RETURN JSONB_BUILD_OBJECT(
        'code', 200,
        'message', 'Ticket successfully cancelled',
        'ticket_id', ticket_id,
        'order_id', ticket_record.order_id,
        'price_reduction', ticket_price,
        'remaining_order_product_ticket', remaining_opt_id
    );
EXCEPTION
    WHEN OTHERS THEN
        RETURN JSONB_BUILD_OBJECT('code', 500, 'message', 'An error occurred', 'details', SQLERRM);
END;
$function$

CREATE OR REPLACE FUNCTION public.storno_tickets_bulk_internal_v1(p_ticket_ids bigint[], p_send_email boolean DEFAULT true)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
    v_order_id BIGINT;
    v_occasion_id BIGINT;
    v_tickets_in_order BIGINT[];
    v_tickets_to_cancel_in_order BIGINT[];
    v_remaining_count INT;
    v_ticket_id_to_remove BIGINT;
    v_original_data JSONB;
    v_updated_tickets_json JSONB;
    v_ticket_elem JSONB;
    v_product_elem JSONB;
    v_removed_price NUMERIC(10, 2);
    v_current_price NUMERIC(10, 2);
BEGIN
    PERFORM public.lock_blueprint_scope_internal(ARRAY(SELECT DISTINCT occasion FROM eshop.tickets WHERE id=ANY(p_ticket_ids)));
    PERFORM public.check_blueprint_selection_units_internal(ARRAY(SELECT s.id FROM eshop.spots s JOIN eshop.order_product_ticket opt ON opt.id=s.order_product_ticket WHERE opt.ticket=ANY(p_ticket_ids)));
    PERFORM public.lock_order_capacity_scope_internal(ARRAY(SELECT DISTINCT "order" FROM eshop.order_product_ticket WHERE ticket=ANY(p_ticket_ids)));
    -- 1. Identify all unique orders involved in this batch AND their occasion
    -- We need the occasion ID to perform the security check
    FOR v_order_id, v_occasion_id IN
        SELECT DISTINCT o.id, o.occasion
        FROM eshop.tickets t
        JOIN eshop.order_product_ticket opt ON t.id = opt.ticket
        JOIN eshop.orders o ON opt."order" = o.id
        WHERE t.id = ANY(p_ticket_ids)
        ORDER BY o.id
    LOOP
        -- 2. SECURITY CHECK
        -- Verify that the current user has editor permissions on the occasion associated with the order.
        IF NOT public.get_is_editor_order_on_occasion(v_occasion_id) THEN
            RAISE EXCEPTION 'Permission denied to storno tickets for order % on occasion %', v_order_id, v_occasion_id;
        END IF;

        -- Repeated selected tickets in an otherwise active order are a no-op.
        IF NOT EXISTS(SELECT 1 FROM eshop.order_product_ticket opt JOIN eshop.tickets t ON t.id=opt.ticket
          WHERE opt."order"=v_order_id AND t.id=ANY(p_ticket_ids) AND t.state IS DISTINCT FROM 'storno') THEN
          CONTINUE;
        END IF;
        PERFORM public.check_order_is_mutable(v_order_id);
        -- Serialize cancellations on the same order before counting survivors.
        PERFORM 1 FROM eshop.orders WHERE id = v_order_id FOR UPDATE;

        -- 3. Get all active tickets currently in this order
        SELECT ARRAY_AGG(t.id)
        INTO v_tickets_in_order
        FROM eshop.tickets t
        JOIN eshop.order_product_ticket opt ON t.id = opt.ticket
        WHERE opt."order" = v_order_id
        AND (t.state IS NULL OR t.state != 'storno');

        -- 4. Get intersection: Tickets in this order that we want to cancel
        SELECT ARRAY_AGG(id)
        INTO v_tickets_to_cancel_in_order
        FROM UNNEST(v_tickets_in_order) AS id
        WHERE id = ANY(p_ticket_ids);

        -- A replay or a selection containing only cancelled tickets has no effect.
        IF coalesce(cardinality(v_tickets_to_cancel_in_order), 0) = 0 THEN
            CONTINUE;
        END IF;

        -- 5. Calculate how many would remain
        v_remaining_count := array_length(v_tickets_in_order, 1) - array_length(v_tickets_to_cancel_in_order, 1);

        -- -----------------------------------------------------
        -- SCENARIO A: Full Order Cancellation
        -- -----------------------------------------------------
        IF v_remaining_count <= 0 THEN
            -- Helper function to cancel the entire order
            PERFORM public.cancel_order_domain_internal_v1(v_order_id,p_send_email);

        -- -----------------------------------------------------
        -- SCENARIO B: Partial Cancellation (Modify Order)
        -- -----------------------------------------------------
        ELSE
            -- 1. Mark specific tickets as storno in DB
            PERFORM internal_storno_tickets_221(v_tickets_to_cancel_in_order);

            -- 2. Fetch Order Data
            SELECT data, price INTO v_original_data, v_current_price
            FROM eshop.orders WHERE id = v_order_id;

            v_updated_tickets_json := '[]'::JSONB;
            v_removed_price := 0;

            -- 3. Rebuild JSON data, filtering out cancelled tickets and summing price to remove
            FOR v_ticket_elem IN SELECT * FROM jsonb_array_elements(v_original_data->'tickets')
            LOOP
                v_ticket_id_to_remove := (v_ticket_elem->>'id')::BIGINT;

                -- If this ticket is one of the ones being cancelled
                IF v_ticket_id_to_remove = ANY(v_tickets_to_cancel_in_order) THEN
                    -- Sum up price to deduct
                    FOR v_product_elem IN SELECT * FROM jsonb_array_elements(v_ticket_elem->'products')
                    LOOP
                        v_removed_price := v_removed_price + COALESCE((v_product_elem->>'price')::NUMERIC, 0);
                    END LOOP;
                ELSE
                    -- Keep this ticket in the new JSON
                    v_updated_tickets_json := v_updated_tickets_json || v_ticket_elem;
                END IF;
            END LOOP;

            -- Fence unsent snapshots of the previous ticket set, and keep the
            -- payment amount aligned with the new order total.
            PERFORM public.cancel_order_email_intents(v_order_id);
            UPDATE eshop.payment_info SET amount=GREATEST(0, COALESCE(v_current_price,0)-v_removed_price)
            WHERE id=(SELECT payment_info FROM eshop.orders WHERE id=v_order_id);

            -- 4. Update Order (Data & Price)
            UPDATE eshop.orders
            SET
                data = v_original_data || JSONB_BUILD_OBJECT('tickets', v_updated_tickets_json),
                price = GREATEST(0, COALESCE(v_current_price, 0) - v_removed_price),
                email_payment_version = email_payment_version + 1,
                updated_at = NOW()
            WHERE id = v_order_id;

            -- Refresh only this order's existing reminder schedule for its new amount.
            PERFORM public.set_payment_deadline(pi.id,pi.deadline)
            FROM eshop.payment_info pi JOIN eshop.orders o ON o.payment_info=pi.id
            WHERE o.id=v_order_id AND o.state='ordered' AND pi.deadline IS NOT NULL;

            -- Existing delivery policy prepares the surviving tickets if their
            -- paid order has not finished sending yet; sent orders stay untouched.
            PERFORM public.enqueue_paid_order_tickets(v_order_id);

            -- 5. Insert ONE history record for this modification
            INSERT INTO eshop.orders_history (
                "order",
                data,
                state,
                price,
                created_at
            )
            VALUES (
                v_order_id,
                v_original_data || JSONB_BUILD_OBJECT('tickets', v_updated_tickets_json),
                (SELECT state FROM eshop.orders WHERE id=v_order_id),
                GREATEST(0, COALESCE(v_current_price, 0) - v_removed_price),
                NOW()
            );
        END IF;
    END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.storno_tickets_client_sync_v1(p_tickets bigint[], p_command_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_request_tickets bigint[]:=p_tickets; v_actor uuid:=auth.uid(); v_occasion bigint; v_begin jsonb; v_hash text;
  v_unchanged boolean:=false; v_before_users uuid[]; v_changed_orders bigint[]; v_cancelled jsonb; v_updated jsonb;
BEGIN
  p_tickets:=ARRAY(SELECT DISTINCT id FROM unnest(p_tickets) id ORDER BY id);
  PERFORM public.lock_blueprint_scope_internal(ARRAY(SELECT DISTINCT occasion FROM eshop.tickets WHERE id=ANY(p_tickets)));
  IF cardinality(p_tickets)>(SELECT hard_cap FROM public.abuse_policy_rules WHERE rule_key='order.mutation.items') THEN RAISE SQLSTATE 'PT429' USING MESSAGE='abuse_limit_exceeded'; END IF;
  SELECT min(t.occasion) INTO v_occasion FROM eshop.tickets t
    WHERE t.id=ANY(p_tickets);
  IF v_actor IS NULL OR v_occasion IS NULL OR cardinality(p_tickets)=0
    OR (SELECT count(*) FROM eshop.tickets t
      WHERE t.id=ANY(p_tickets) AND t.occasion=v_occasion)
      <>cardinality(ARRAY(SELECT DISTINCT id FROM unnest(p_tickets) id))
    OR NOT public.get_is_editor_order_on_occasion(v_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='order editor required'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'tickets',v_request_tickets)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,
    'inventory.tickets.cancel',v_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  IF NOT EXISTS(SELECT 1 FROM eshop.tickets WHERE id=ANY(p_tickets) AND state IS DISTINCT FROM 'storno') THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'unchanged',200,
      jsonb_build_object('ticketIds',to_jsonb(p_tickets),'cancelledOrderIds','[]'::jsonb,'updatedOrders','[]'::jsonb));
  END IF;
  BEGIN
  PERFORM public.admit_order_mutation_v1(v_occasion,cardinality(p_tickets));
  SELECT COALESCE(array_agg(ou."user"),'{}'::uuid[]) INTO v_before_users
    FROM public.occasion_users ou WHERE ou.occasion=v_occasion;
  PERFORM public.lock_order_capacity_scope_internal(ARRAY(SELECT DISTINCT "order" FROM eshop.order_product_ticket WHERE ticket=ANY(p_tickets)));
  -- Lock in the same order as the bulk mutation, then capture only actual changes.
  PERFORM o.id FROM eshop.orders o WHERE o.id IN (
    SELECT opt."order" FROM eshop.order_product_ticket opt
    JOIN eshop.tickets t ON t.id=opt.ticket
    WHERE t.id=ANY(p_tickets)) ORDER BY o.id FOR UPDATE;
  SELECT array_agg(DISTINCT opt."order") INTO v_changed_orders
    FROM eshop.order_product_ticket opt JOIN eshop.tickets t ON t.id=opt.ticket
    WHERE t.id=ANY(p_tickets) AND t.state IS DISTINCT FROM 'storno';
  IF coalesce(cardinality(v_changed_orders),0)=0 THEN
    RAISE SQLSTATE 'P0C01' USING MESSAGE='cancellation already committed'; END IF;
  PERFORM public.storno_tickets_bulk_internal_v1(p_tickets, false);
  SELECT coalesce(jsonb_agg(o.id ORDER BY o.id) FILTER(WHERE o.state='storno'),'[]'::jsonb),
    coalesce(jsonb_agg(jsonb_build_object('id',o.id,'email',o.data->>'email') ORDER BY o.id)
      FILTER(WHERE o.state IS DISTINCT FROM 'storno'),'[]'::jsonb)
    INTO v_cancelled,v_updated FROM eshop.orders o WHERE o.id=ANY(v_changed_orders);
  EXCEPTION WHEN SQLSTATE 'P0C01' THEN v_unchanged:=true;
  END;
  IF v_unchanged THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'unchanged',200,
      jsonb_build_object('ticketIds',to_jsonb(p_tickets),'cancelledOrderIds','[]'::jsonb,'updatedOrders','[]'::jsonb));
  END IF;
  RETURN public.complete_profile_inventory_membership_mutation_v1(
    p_command_id,v_occasion,'inventory.tickets.cancel',
    jsonb_build_array(jsonb_build_object('entityType','ticket','entityId',NULL,
      'operation','update','safeLabel','Ticket cancellation',
      'changedFields',jsonb_build_array('state','membership','allocations'))),
    v_before_users,jsonb_build_object('ticketIds',to_jsonb(p_tickets),
      'cancelledOrderIds',v_cancelled,'updatedOrders',v_updated));
END; $function$

CREATE OR REPLACE FUNCTION public.submit_event_feedback(p_event bigint, p_rating text, p_note text DEFAULT NULL::text, p_client_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE p_occasion bigint; r jsonb;
BEGIN
 SELECT occasion INTO p_occasion FROM public.events WHERE id=p_event;
 IF p_occasion IS NULL THEN RETURN jsonb_build_object('code',404); END IF;
 r:=public.submit_event_feedback_client_sync_v1(p_occasion,p_event,p_rating,p_note,p_client_id,extensions.gen_random_uuid());
 RETURN jsonb_build_object('code',r->'code','data',r#>'{data,feedback}','message',r#>'{data,message}');
END $function$

CREATE OR REPLACE FUNCTION public.submit_event_feedback_client_sync_v1(p_occasion bigint, p_event bigint, p_rating text, p_note text, p_client_id uuid, p_command_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_client uuid; v_begin jsonb; v_hash text;
  v_result jsonb; v_before public.event_feedback%ROWTYPE;
  v_after public.event_feedback%ROWTYPE; v_private_impacts jsonb:='[]'::jsonb;
  v_replacements jsonb:='[]'::jsonb; v_operation text;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.events e
    WHERE e.id=p_event AND e.occasion=p_occasion) THEN
    RAISE invalid_parameter_value USING MESSAGE='feedback event outside occasion'; END IF;
  v_client:=CASE WHEN v_actor IS NULL THEN p_client_id ELSE NULL END;
  IF v_actor IS NULL AND v_client IS NULL THEN
    RAISE invalid_parameter_value USING MESSAGE='anonymous client id required'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'occasion',p_occasion,'event',p_event,'rating',p_rating,'note',p_note,
    'clientId',v_client)::text,'UTF8'),'sha256'),'hex');
  IF v_actor IS NULL THEN
    v_begin:=public.begin_anonymous_client_mutation_v1(p_command_id,
      'feedback.submit',p_occasion,v_client,v_hash);
  ELSE
    v_begin:=public.begin_client_mutation_v1(p_command_id,'feedback.submit',
      p_occasion,v_actor,v_hash);
  END IF;
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  PERFORM 1 FROM public.events e WHERE e.id=p_event FOR UPDATE;
  IF v_actor IS NULL THEN
    SELECT * INTO v_before FROM public.event_feedback f
      WHERE f.event=p_event AND f."user" IS NULL AND f.client_id=v_client
      FOR UPDATE;
  ELSE
    SELECT * INTO v_before FROM public.event_feedback f
      WHERE f.event=p_event AND f."user"=v_actor FOR UPDATE;
  END IF;
  v_result:=public.submit_event_feedback_internal_v1(
    p_event,p_rating,p_note,v_client);
  IF COALESCE((v_result->>'code')::integer,500)<>200 THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',
      CASE WHEN COALESCE((v_result->>'code')::integer,400) BETWEEN 100 AND 599
        THEN (v_result->>'code')::integer ELSE 400 END,
      jsonb_build_object('message',v_result->>'message'));
  END IF;
  SELECT * INTO STRICT v_after FROM public.event_feedback f
    WHERE f.id=(v_result#>>'{data,id}')::bigint;
  IF v_before.id IS NOT NULL AND v_before.rating IS NOT DISTINCT FROM v_after.rating
      AND v_before.note IS NOT DISTINCT FROM v_after.note
      AND v_before.data IS NOT DISTINCT FROM v_after.data THEN
    UPDATE public.event_feedback SET updated_at=v_before.updated_at
      WHERE id=v_after.id;
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'unchanged',200,
      jsonb_build_object('feedback',public.get_event_feedback_command_data_v1(v_after.id)));
  END IF;
  v_operation:=CASE WHEN v_before.id IS NULL THEN 'insert' ELSE 'update' END;
  IF v_actor IS NOT NULL AND EXISTS (SELECT 1 FROM public.occasion_users ou
    WHERE ou.occasion=p_occasion AND ou."user"=v_actor) THEN
    v_private_impacts:=jsonb_build_array(jsonb_build_object(
      'component','private_feedback','userId',v_actor));
    v_replacements:=jsonb_build_array(jsonb_build_object(
      'component','private_feedback','userId',v_actor,
      'payload',public.get_private_feedback_payload_v1(p_occasion,v_actor)));
  END IF;
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'feedback.submit','feedback',jsonb_build_array(jsonb_build_object(
      'entityType','event_feedback','entityId',v_after.id,'operation',v_operation,
      'safeLabel','Event feedback','changedFields',jsonb_build_array('rating','note'))),
    '{}',v_private_impacts,'[]',jsonb_build_object(
      'feedback',public.get_event_feedback_command_data_v1(v_after.id)),
    '{}','[]',CASE WHEN v_actor IS NULL THEN 'unknown' ELSE 'user' END,NULL,
    v_replacements);
END; $function$

CREATE OR REPLACE FUNCTION public.submit_event_feedback_internal_v1(p_event bigint, p_rating text, p_note text DEFAULT NULL::text, p_client_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
    v_event public.events%ROWTYPE;
    v_user UUID := auth.uid();
    v_note TEXT := NULLIF(btrim(COALESCE(p_note, '')), '');
    v_is_limited BOOLEAN;
    v_is_editor BOOLEAN;
    v_feedback public.event_feedback%ROWTYPE;
BEGIN
    IF p_rating NOT IN ('happy', 'neutral', 'sad') THEN
        RETURN jsonb_build_object('code', 400, 'message', 'Invalid rating');
    END IF;

    IF char_length(COALESCE(v_note, '')) > 2000 THEN
        RETURN jsonb_build_object('code', 413, 'message', 'Feedback text is too long');
    END IF;

    SELECT *
    INTO v_event
    FROM public.events
    WHERE id = p_event
      AND is_hidden = false;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('code', 404, 'message', 'Event not found');
    END IF;

    IF NOT public.get_is_event_allowed(p_event) THEN
        RETURN jsonb_build_object('code', 403, 'message', 'Event is not available');
    END IF;

    IF NOT public.get_is_event_feedback_enabled_on_occasion(v_event.occasion) THEN
        RETURN jsonb_build_object('code', 404, 'message', 'Feedback feature is not enabled for this occasion');
    END IF;

    IF COALESCE(v_event.data->>'feedback_enabled', 'false') <> 'true' THEN
        RETURN jsonb_build_object('code', 404, 'message', 'Feedback is not enabled for this event');
    END IF;

    v_is_editor := public.get_is_editor_view_on_occasion(v_event.occasion);

    IF now() < v_event.start_time AND NOT v_is_editor THEN
        RETURN jsonb_build_object('code', 409, 'message', 'Feedback is not open yet');
    END IF;

    v_is_limited := COALESCE(v_event.max_participants, 0) > 0;
    IF v_is_limited AND NOT v_is_editor THEN
        IF v_user IS NULL THEN
            RETURN jsonb_build_object('code', 401, 'message', 'Sign in is required for feedback on this event');
        END IF;

        IF NOT EXISTS (
            SELECT 1
            FROM public.event_users eu
            WHERE eu.event = p_event
              AND eu."user" = v_user
        ) THEN
            RETURN jsonb_build_object('code', 403, 'message', 'Only signed-in participants can rate this event');
        END IF;
    END IF;

    IF v_user IS NULL AND p_client_id IS NULL THEN
        RETURN jsonb_build_object('code', 401, 'message', 'Client id is required for anonymous feedback');
    END IF;

    IF v_user IS NOT NULL THEN
        INSERT INTO public.event_feedback (event, occasion, "user", rating, note)
        VALUES (p_event, v_event.occasion, v_user, p_rating, v_note)
        ON CONFLICT (event, "user") WHERE "user" IS NOT NULL
        DO UPDATE SET
            rating = EXCLUDED.rating,
            note = EXCLUDED.note,
            updated_at = now()
        RETURNING * INTO v_feedback;
    ELSE
        INSERT INTO public.event_feedback (event, occasion, client_id, rating, note)
        VALUES (p_event, v_event.occasion, p_client_id, p_rating, v_note)
        ON CONFLICT (event, client_id) WHERE "user" IS NULL AND client_id IS NOT NULL
        DO UPDATE SET
            rating = EXCLUDED.rating,
            note = EXCLUDED.note,
            updated_at = now()
        RETURNING * INTO v_feedback;
    END IF;

    RETURN jsonb_build_object(
        'code', 200,
        'data', jsonb_build_object(
            'id', v_feedback.id,
            'event', v_feedback.event,
            'rating', v_feedback.rating,
            'note', v_feedback.note,
            'created_at', v_feedback.created_at,
            'updated_at', v_feedback.updated_at
        )
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.submit_unit_verification(p_unit bigint, p_expected_revision bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE p public.unit_legal_profiles; org bigint; errors jsonb:='{}'; k text; v text;
BEGIN
 SELECT organization INTO org FROM public.units WHERE id=p_unit FOR UPDATE;
 IF auth.uid() IS NULL OR org IS NULL OR NOT public.get_is_manager_on_unit(p_unit) OR public.is_demo_unit(p_unit) THEN
  RAISE EXCEPTION 'Legal profile submission denied' USING ERRCODE='42501';
 END IF;
 SELECT * INTO p FROM public.unit_legal_profiles WHERE unit_id=p_unit FOR UPDATE;
 IF p_expected_revision IS DISTINCT FROM coalesce(p.revision,0) THEN RETURN jsonb_build_object('code',409,'errorCode','REVISION_CONFLICT','profile',public.get_unit_legal_profile(p_unit)->'profile'); END IF;
 FOR k,v IN SELECT key,value#>>'{}' FROM jsonb_each(public.get_unit_legal_profile(p_unit)->'profile') WHERE key=ANY(ARRAY['legalName','countryCode','registrationNumber','contactEmail']) LOOP
  IF coalesce(v,'')='' THEN errors:=errors||jsonb_build_object(k,'REQUIRED'); END IF;
 END LOOP;
 IF coalesce(p.street,'')='' OR coalesce(p.city,'')='' OR coalesce(p.postal_code,'')='' THEN errors:=errors||jsonb_build_object('address','REQUIRED'); END IF;
 IF errors<>'{}' THEN RETURN jsonb_build_object('code',422,'errorCode','INCOMPLETE_PROFILE','fieldErrors',errors); END IF;
 IF p.status NOT IN ('unverified','rejected','revoked') THEN RETURN jsonb_build_object('code',422,'errorCode','INVALID_TRANSITION','fieldErrors','{}'::jsonb); END IF;
 UPDATE public.unit_legal_profiles SET revision=revision+1,status='pending',submitted_at=statement_timestamp(),submitted_by=auth.uid(),
 reviewed_at=NULL,reviewed_by=NULL,reviewed_organization_id=NULL,feedback_to_applicant=NULL,review_note=NULL,review_source=NULL WHERE unit_id=p_unit;
 INSERT INTO public.unit_legal_profile_audit(unit_id,organization_id,revision,actor_id,action,snapshot)
 SELECT p_unit,org,revision,auth.uid(),'submit',to_jsonb(t) FROM public.unit_legal_profiles t WHERE unit_id=p_unit;
 PERFORM public.enqueue_unit_verification_request(p_unit);
 RETURN jsonb_build_object('code',200,'outcome','applied','profile',public.get_unit_legal_profile(p_unit)->'profile');
END $function$

CREATE OR REPLACE FUNCTION public.suggest_occasion_setup_form_link(p_id uuid, p_title text, p_requested_link text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE d public.occasion_setup_drafts; base text; candidate text; suffix integer:=1; year text;
BEGIN
 SELECT * INTO d FROM public.occasion_setup_drafts WHERE id=p_id;
 IF NOT FOUND OR auth.uid() IS NULL OR NOT (public.get_is_editor_on_unit(d.unit) OR public.get_is_manager_on_unit(d.unit)) THEN
  RAISE insufficient_privilege USING MESSAGE='Draft access denied'; END IF;
 IF length(coalesce(p_title,''))>500 OR length(coalesce(p_requested_link,''))>80 THEN
  RAISE invalid_parameter_value USING MESSAGE='Invalid public link input'; END IF;
 base:=trim(both '-' from regexp_replace(public.f_unaccent(left(coalesce(p_title,''),500)),'[^a-z0-9]+','-','g'));
 base:=trim(trailing '-' from left(base,64));
 IF base='' THEN base:='akce'; END IF;
 year:=substring(coalesce(d.data->>'start',d.data->>'start_time','') from '^([0-9]{4})-');
 IF year IS NOT NULL AND base !~ '[0-9]{4}' THEN base:=base||'-'||year; END IF;
 candidate:=base;
 WHILE EXISTS(SELECT 1 FROM public.form_link_reservations WHERE slug=candidate) LOOP
  suffix:=suffix+1; candidate:=base||'-'||suffix;
  IF suffix>1000 THEN candidate:=base||'-'||left(replace(d.id::text,'-',''),8); EXIT; END IF;
 END LOOP;
 -- Deterministic bounded fallback, still checked rather than presumed free.
 IF EXISTS(SELECT 1 FROM public.form_link_reservations WHERE slug=candidate) THEN
  RAISE unique_violation USING MESSAGE='Public link suggestions exhausted'; END IF;
 RETURN jsonb_build_object('suggestion',candidate,'available',
  CASE WHEN p_requested_link IS NULL OR p_requested_link='' THEN NULL
  ELSE p_requested_link ~ '^[a-z0-9]+(-[a-z0-9]+)*$'
    AND NOT EXISTS(SELECT 1 FROM public.form_link_reservations WHERE slug=p_requested_link) END);
END $function$

CREATE OR REPLACE FUNCTION public.swap_spot_pair_internal_v1(spot_id_1 bigint, spot_id_2 bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
    spot1 RECORD;
    spot2 RECORD;
    occasion_id_common BIGINT;
    has_permission BOOLEAN;
    now_time TIMESTAMP WITH TIME ZONE := NOW();
BEGIN
    -- 1. Input Validation
    IF spot_id_1 IS NULL OR spot_id_2 IS NULL THEN
        RAISE EXCEPTION 'Both spot_id_1 and spot_id_2 must be provided' USING ERRCODE = '22023';
    END IF;
    IF spot_id_1 = spot_id_2 THEN
        RAISE EXCEPTION 'Cannot swap a spot with itself' USING ERRCODE = '22023';
    END IF;

    PERFORM public.lock_spot_assignment_scope_internal_v1(ARRAY[spot_id_1,spot_id_2]);

    -- 2. Fetch Spot Data
    SELECT * INTO spot1 FROM eshop.spots WHERE id = spot_id_1 FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Spot 1 not found (ID: %)', spot_id_1 USING ERRCODE = 'P0002'; END IF;
    SELECT * INTO spot2 FROM eshop.spots WHERE id = spot_id_2 FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Spot 2 not found (ID: %)', spot_id_2 USING ERRCODE = 'P0002'; END IF;

    -- 3. Permission and Occasion Check
    IF spot1.occasion IS NULL OR spot2.occasion IS NULL THEN
         RAISE EXCEPTION 'Spots are missing occasion information' USING ERRCODE = '22004';
    END IF;
    IF spot1.occasion <> spot2.occasion THEN
        RAISE EXCEPTION 'Spots do not belong to the same occasion (Spot1: %, Spot2: %)', spot1.occasion, spot2.occasion USING ERRCODE = 'P0001';
    END IF;
    occasion_id_common := spot1.occasion;

    -- Check permission
    BEGIN
        SELECT get_is_editor_order_on_occasion(occasion_id_common) INTO has_permission;
    EXCEPTION
        WHEN undefined_function THEN RAISE EXCEPTION 'Permission check function get_is_editor_order_on_occasion() does not exist.' USING ERRCODE = '42883';
        WHEN OTHERS THEN RAISE EXCEPTION 'Error during permission check: %', SQLERRM;
    END;
    IF has_permission <> TRUE THEN
        RAISE EXCEPTION 'User is not authorized to edit order_ids for this occasion' USING ERRCODE = '42501';
    END IF;

    IF EXISTS(SELECT 1 FROM eshop.spots WHERE id IN(spot_id_1,spot_id_2)
      AND secret IS NOT NULL AND secret_expiration_time>clock_timestamp()) THEN
      RAISE object_not_in_prerequisite_state USING MESSAGE='SPOT_HELD'; END IF;
    -- Ticket locks follow the already locked order parents, in a stable order.
    PERFORM 1 FROM eshop.tickets WHERE id IN(SELECT ticket FROM eshop.order_product_ticket
      WHERE id IN(spot1.order_product_ticket,spot2.order_product_ticket)) ORDER BY id FOR UPDATE;

    -- 4. Main Swap Logic: Branch based on assignment status
    -- This logic is now greatly simplified by the helper functions.

    IF spot1.order_product_ticket IS NOT NULL AND spot2.order_product_ticket IS NOT NULL THEN
        -- ----------------------------------------------------------------
        -- CASE A: BOTH SPOTS ARE ASSIGNED
        -- ----------------------------------------------------------------

        -- Ticket 1 (from spot 1) moves to Spot 2, so it must adopt Spot 2's product.
        PERFORM public._swap_spots_update_ticket(spot1.order_product_ticket, spot2.product, spot_id_2);

        -- Ticket 2 (from spot 2) moves to Spot 1, so it must adopt Spot 1's product.
        PERFORM public._swap_spots_update_ticket(spot2.order_product_ticket, spot1.product, spot_id_1);

    ELSIF spot1.order_product_ticket IS NOT NULL OR spot2.order_product_ticket IS NOT NULL THEN
        -- ----------------------------------------------------------------
        -- CASE B/C: ONE SPOT IS ASSIGNED, ONE IS UNASSIGNED
        -- ----------------------------------------------------------------

        IF spot1.order_product_ticket IS NOT NULL THEN
            -- Spot 1 is assigned, Spot 2 is unassigned.
            -- Ticket 1 moves to Spot 2 and adopts Spot 2's product.
            PERFORM public._swap_spots_update_ticket(spot1.order_product_ticket, spot2.product, spot_id_2);
        ELSE
            -- Spot 2 is assigned, Spot 1 is unassigned.
            -- Ticket 2 moves to Spot 1 and adopts Spot 1's product.
            PERFORM public._swap_spots_update_ticket(spot2.order_product_ticket, spot1.product, spot_id_1);
        END IF;

    ELSE
        -- ----------------------------------------------------------------
        -- CASE D: BOTH SPOTS ARE UNASSIGNED
        -- ----------------------------------------------------------------
        -- Nothing to do.
        RETURN;
    END IF;

    -- 5. Final Spot Update
    -- This block runs for Cases A, B, and C.
    -- We ONLY swap the 'order_product_ticket' FK. The 'product' column
    -- on the spot (spot1.product, spot2.product) never changes.
    UPDATE eshop.spots
    SET
        order_product_ticket = CASE
            WHEN id = spot_id_1 THEN spot2.order_product_ticket -- Spot 1 gets Ticket 2
            WHEN id = spot_id_2 THEN spot1.order_product_ticket -- Spot 2 gets Ticket 1
        END
    WHERE id IN (spot_id_1, spot_id_2);

END;
$function$

CREATE OR REPLACE FUNCTION public._swap_spots_update_ticket(p_opt_id bigint, p_new_product_id bigint, p_new_spot_id bigint)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
    opt RECORD;
    ord RECORD;
    original_product_id BIGINT;
    original_product_json JSONB;
    original_price NUMERIC;

    new_product_json JSONB;
    new_price NUMERIC;
    new_data JSONB;
    new_order_price NUMERIC;
    new_state TEXT;

    price_delta NUMERIC;
    history_needed BOOLEAN;
    now_time TIMESTAMP WITH TIME ZONE := NOW();
BEGIN
    -- 1. Get current ticket and order data
    SELECT * INTO opt FROM eshop.order_product_ticket WHERE id = p_opt_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Order Product Ticket % not found', p_opt_id; END IF;

    PERFORM public.check_ticket_is_mutable(opt.ticket);
    SELECT * INTO ord FROM eshop.orders WHERE id = opt."order" FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Order % not found', opt."order"; END IF;

    original_product_id := opt.product;

    -- 2. Find the *original* product JSON and price from the order_ids.data
    SELECT prod, (prod->>'price')::numeric
    INTO original_product_json, original_price
    FROM jsonb_array_elements(ord.data->'tickets') tckt,
         jsonb_array_elements(tckt->'products') prod
    WHERE (tckt->>'id')::bigint = opt.ticket
      AND (prod->>'id')::bigint = original_product_id;

    IF original_price IS NULL THEN
        RAISE EXCEPTION 'Could not find original price for product % on ticket %', original_product_id, opt.ticket;
    END IF;

    -- 3. Generate the *new* product JSON
    new_product_json := public._swap_spots_generate_product_json(p_new_product_id, p_new_spot_id);
    new_price := (new_product_json->>'price')::numeric;
    IF new_product_json->>'currency_code' IS DISTINCT FROM ord.currency_code THEN
      RAISE EXCEPTION 'BLUEPRINT_CURRENCY_MISMATCH'; END IF;

    -- 4. Check if an update is even needed.
    -- If the new JSON is identical to the old, nothing needs to be done.
    IF original_product_json = new_product_json THEN
        RETURN;
    END IF;

    -- 5. Calculate financials and state
    price_delta := new_price - original_price;
    history_needed := (original_product_id IS DISTINCT FROM p_new_product_id);
    new_order_price := COALESCE(ord.price, 0) + price_delta;

    -- Recalculate order state
    SELECT CASE
        WHEN COALESCE(pi.paid, 0) >= new_order_price AND new_order_price > 0 THEN 'paid'
        WHEN new_order_price <= 0 THEN 'paid'
        ELSE 'ordered'
    END INTO new_state
    FROM (SELECT COALESCE((SELECT paid FROM eshop.payment_info WHERE id=ord.payment_info),0) AS paid) pi;

    -- 6. Build the new order_ids.data JSON
    new_data := jsonb_set(
        ord.data,
        '{tickets}',
        (SELECT jsonb_agg(
            -- Find the matching ticket
            CASE WHEN (tckt->>'id')::bigint = opt.ticket
            THEN jsonb_set(
                tckt,
                '{products}',
                (SELECT jsonb_agg(
                    -- Find the matching product and replace it
                    CASE
                        WHEN (prod->>'id')::bigint = original_product_id
                        THEN new_product_json -- Swap in the new product JSON
                        ELSE prod
                    END
                ) FROM jsonb_array_elements(tckt->'products') prod)
            )
            ELSE tckt
            END
        ) FROM jsonb_array_elements(ord.data->'tickets') tckt)
    );

    -- 7. Perform all database updates

    -- Update payment info
    IF price_delta <> 0 THEN
        UPDATE eshop.payment_info SET amount = amount + price_delta WHERE id = ord.payment_info;
    END IF;

    -- Update the order itself
    UPDATE eshop.orders
    SET
        price = new_order_price,
        data = new_data,
        state = new_state,
        updated_at = now_time
    WHERE id = ord.id;

    -- Update the link table
    UPDATE eshop.order_product_ticket
    SET
        product = p_new_product_id
    WHERE id = p_opt_id;

    -- 8. Create history log *only if* the product ID actually changed
    IF history_needed THEN
        INSERT INTO eshop.orders_history("order", data, state, price, currency_code)
        VALUES (ord.id, new_data, new_state, new_order_price, ord.currency_code);
    END IF;

END;
$function$

CREATE OR REPLACE FUNCTION public.swap_spot_tickets_client_sync_v1(p_spot_1 bigint, p_spot_2 bigint, p_command_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_occasion bigint; v_begin jsonb; v_hash text;
  v_users uuid[];
BEGIN
  SELECT occasion INTO v_occasion FROM public.client_mutation_receipts WHERE command_id=p_command_id AND actor_id=v_actor AND command_name='inventory.spots.swap';
  IF NOT FOUND THEN
  SELECT min(s.occasion) INTO v_occasion FROM eshop.spots s
    WHERE s.id IN (p_spot_1,p_spot_2);
  END IF;
  IF v_actor IS NULL OR p_spot_1 IS NULL OR p_spot_2 IS NULL
    OR p_spot_1=p_spot_2 OR v_occasion IS NULL
    OR NOT public.get_is_editor_order_on_occasion(v_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='order editor required'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'spot1',p_spot_1,'spot2',p_spot_2)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,
    'inventory.spots.swap',v_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  IF (SELECT count(*) FROM eshop.spots s
      WHERE s.id IN (p_spot_1,p_spot_2) AND s.occasion=v_occasion)<>2
 THEN RAISE insufficient_privilege USING MESSAGE='foreign spot swap'; END IF;

  PERFORM public.lock_blueprint_scope_internal(ARRAY[v_occasion]);
  PERFORM public.lock_spot_assignment_scope_internal_v1(ARRAY[p_spot_1,p_spot_2]);
  SELECT COALESCE(array_agg(DISTINCT ou."user"),'{}'::uuid[]) INTO v_users
  FROM eshop.spots s JOIN eshop.order_product_ticket opt
    ON opt.id=s.order_product_ticket JOIN public.occasion_users ou
    ON ou.ticket=opt.ticket AND ou.occasion=v_occasion
  WHERE s.id IN (p_spot_1,p_spot_2);
  PERFORM public.swap_spot_tickets_internal_v1(p_spot_1,p_spot_2);
  RETURN public.complete_private_inventory_mutation_v1(p_command_id,v_occasion,
    'inventory.spots.swap',jsonb_build_array(jsonb_build_object(
      'entityType','spot_assignment','entityId',NULL,'operation','update',
      'safeLabel','Spot ticket swap','changedFields',jsonb_build_array(
        'order_product_ticket','product'))),v_users,jsonb_build_object(
          'spotIds',jsonb_build_array(p_spot_1,p_spot_2)));
END; $function$

CREATE OR REPLACE FUNCTION public.swap_spot_tickets_internal_v1(spot_id_1 bigint, spot_id_2 bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE ids1 bigint[]; ids2 bigint[]; order_ids bigint[]; occ bigint; i integer;
BEGIN
 SELECT min(occasion) INTO occ FROM eshop.spots WHERE id IN(spot_id_1,spot_id_2);
 IF occ IS NULL OR (SELECT count(*) FROM eshop.spots WHERE id IN(spot_id_1,spot_id_2) AND occasion=occ)<>2 THEN
  RAISE EXCEPTION 'BLUEPRINT_SPOT_SCOPE_MISMATCH'; END IF;
 IF public.get_is_editor_order_on_occasion(occ) IS NOT TRUE THEN RAISE insufficient_privilege USING MESSAGE='order editor required'; END IF;
 PERFORM public.check_occasion_writable(occ);
 PERFORM public.lock_blueprint_scope_internal(ARRAY[occ]);
 ids1:=public.blueprint_selection_unit_spots_internal(spot_id_1);
 ids2:=public.blueprint_selection_unit_spots_internal(spot_id_2);
 IF cardinality(ids1)<>cardinality(ids2) OR ids1 && ids2 THEN RAISE EXCEPTION 'BLUEPRINT_UNIT_SIZE_MISMATCH'; END IF;
 PERFORM public.check_blueprint_selection_units_internal(ids1||ids2);
 SELECT array_agg(DISTINCT opt."order") INTO order_ids FROM eshop.spots s JOIN eshop.order_product_ticket opt ON opt.id=s.order_product_ticket WHERE s.id=ANY(ids1||ids2);
 PERFORM public.lock_order_capacity_scope_internal(order_ids);
 PERFORM public.lock_ticket_order_products_internal(o.id) FROM eshop.orders o WHERE id=ANY(order_ids) ORDER BY id;
 -- Destination products may differ from products currently held by those order_ids.
 PERFORM 1 FROM eshop.products WHERE id IN(SELECT product FROM eshop.spots WHERE id=ANY(ids1||ids2)) ORDER BY id FOR UPDATE;
 PERFORM 1 FROM eshop.payment_info WHERE id IN(SELECT payment_info FROM eshop.orders WHERE id=ANY(order_ids)) ORDER BY id FOR UPDATE;
 PERFORM 1 FROM eshop.spots WHERE id=ANY(ids1||ids2) ORDER BY id FOR UPDATE;
 IF EXISTS(SELECT 1 FROM eshop.spots s LEFT JOIN eshop.blueprint_seat_bindings b ON b.spot=s.id
  WHERE s.id=ANY(ids1||ids2) AND (b.blocked OR s.product IS NULL OR (s.secret IS NOT NULL AND s.secret_expiration_time>statement_timestamp()))) THEN
  RAISE EXCEPTION 'BLUEPRINT_SEAT_PROTECTED'; END IF;
 FOR i IN 1..cardinality(ids1) LOOP PERFORM public.swap_spot_pair_internal_v1(ids1[i],ids2[i]); END LOOP;
END $function$

CREATE OR REPLACE FUNCTION public.sync_scanner_operations(p_session uuid, p_token text, p_operations jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE s public.scanner_sessions; cfg public.scanner_settings; op jsonb; canonical jsonb; h text; prior public.scanner_operations;
 tid bigint; proj jsonb; receipt jsonb; outcome text; reason text; results jsonb:='[]'; existing boolean; snap public.scanner_snapshots;
BEGIN
 s:=public.scanner_session_internal(p_session,p_token);
 IF p_operations IS NULL OR jsonb_typeof(p_operations)<>'array' OR jsonb_array_length(p_operations) NOT BETWEEN 1 AND 50 OR octet_length(p_operations::text)>262144 THEN
  RETURN jsonb_build_object('code',400,'reason','invalid_batch','server_time',now()); END IF;
 SELECT * INTO cfg FROM public.scanner_settings WHERE occasion_id=s.occasion_id;
 IF NOT public.admit_scan_access_v1(s.occasion_id,true) THEN RETURN jsonb_build_object('code',429,'reason','abuse_limit_exceeded','retry_after_ms',30000,'server_time',now()); END IF;
 FOR op IN SELECT value FROM jsonb_array_elements(p_operations) LOOP
  IF op->>'action' IS DISTINCT FROM 'admit_ticket' OR op->>'origin_session_id' IS DISTINCT FROM p_session::text
   OR op->>'eligibility_fingerprint' IS NULL OR length(op->>'eligibility_fingerprint')<>64
   OR op->>'operation_id' IS NULL OR op->>'ticket_id' IS NULL THEN
   RAISE invalid_parameter_value USING MESSAGE='invalid_operation'; END IF;
  tid:=(op->>'ticket_id')::bigint;
  canonical:=jsonb_build_object('operation_id',(op->>'operation_id')::uuid,'origin_session_id',p_session,'occasion_id',s.occasion_id,
   'ticket_id',tid,'action','admit_ticket','snapshot_id',op->'snapshot_id','settings_revision',op->'settings_revision',
   'eligibility_fingerprint',op->'eligibility_fingerprint','confirm_unpaid',coalesce((op->>'confirm_unpaid')::boolean,false),'captured_at',op->'captured_at');
  h:=encode(digest(canonical::text,'sha256'),'hex');
  -- Serializes global identity before any domain mutation. No incomplete receipt survives a transaction.
  PERFORM pg_advisory_xact_lock(hashtextextended(op->>'operation_id',5317));
  SELECT * INTO prior FROM public.scanner_operations WHERE operation_id=(op->>'operation_id')::uuid;
  IF FOUND THEN
   IF prior.session_id<>p_session OR prior.payload_hash<>h THEN
    results:=results||jsonb_build_array(jsonb_build_object('operation_id',op->>'operation_id','outcome','rejected','reason','operation_payload_mismatch'));
   ELSE results:=results||jsonb_build_array(prior.receipt||jsonb_build_object('replayed',true)); END IF;
   CONTINUE;
  END IF;
  IF NOT public.admit_scan_access_v1(s.occasion_id,true) THEN
   RETURN jsonb_build_object('code',429,'reason','abuse_limit_exceeded','retry_after_ms',30000,'server_time',now());
  END IF;
  outcome:='rejected'; reason:='not_found'; proj:=NULL;
  IF EXISTS(SELECT 1 FROM eshop.tickets WHERE id=tid AND occasion=s.occasion_id) THEN
   PERFORM public.scanner_lock_ticket_internal(tid);
   PERFORM public.check_occasion_writable(s.occasion_id);
   SELECT dto INTO proj FROM public.scanner_ticket_projection_internal(s.occasion_id,cfg.config,tid);
   IF proj->>'state'='used' THEN outcome:='conflict'; reason:='already_used';
   ELSIF proj->>'state' IN ('storno','waitlisted') OR NOT coalesce((proj->>'admission_allowed')::boolean,false) THEN reason:='admission_not_allowed';
   ELSIF proj->>'eligibility_fingerprint' IS DISTINCT FROM op->>'eligibility_fingerprint' THEN outcome:='conflict'; reason:='eligibility_changed';
   ELSIF (proj->>'requires_unpaid_confirmation')::boolean AND (NOT coalesce((op->>'confirm_unpaid')::boolean,false) OR op->>'snapshot_id' IS NOT NULL) THEN reason:='unpaid_confirmation_required';
   ELSE
    reason:='admitted'; outcome:='accepted';
    IF op->>'snapshot_id' IS NOT NULL THEN
     SELECT * INTO snap FROM public.scanner_snapshots WHERE id=(op->>'snapshot_id')::uuid AND session_id=p_session;
     IF snap.id IS NULL OR snap.expires_at<=now() OR s.offline_until<=now() OR NOT EXISTS(
      SELECT 1 FROM public.scanner_snapshot_pages pg CROSS JOIN LATERAL jsonb_array_elements(pg.payload_text::jsonb) item
      WHERE pg.snapshot_id=snap.id AND item->>'ticket_id'=tid::text AND item->>'eligibility_fingerprint'=op->>'eligibility_fingerprint') THEN
      outcome:='conflict'; reason:='offline_grant_invalid'; END IF;
    END IF;
    IF outcome='accepted' THEN
     PERFORM public.scanner_admit_ticket_internal(tid);
    END IF;
   END IF;
  END IF;
  receipt:=jsonb_build_object('operation_id',op->>'operation_id','ticket_id',tid,'outcome',outcome,'reason',reason,
   'committed_at',clock_timestamp(),'eligibility_fingerprint',op->>'eligibility_fingerprint');
  INSERT INTO public.scanner_operations(operation_id,session_id,occasion_id,ticket_id,payload_hash,payload,receipt)
   VALUES((op->>'operation_id')::uuid,p_session,s.occasion_id,tid,h,canonical,receipt);
  results:=results||jsonb_build_array(receipt);
 END LOOP;
 RETURN jsonb_build_object('code',200,'data',results,'server_time',now());
END $function$

CREATE OR REPLACE FUNCTION public.sync_source_via_http_client_sync_v1(p_source_name text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_organization bigint; v_before jsonb; v_after jsonb; v_result text;
  v_changed bigint[]; v_deleted bigint[]; v_units bigint[]; v_commit public.client_commits%ROWTYPE;
  v_occasion bigint; v_unit bigint; v_revision bigint;
BEGIN
  PERFORM public.require_client_sync_service_role_v1();
  IF nullif(btrim(p_source_name),'') IS NULL THEN
    RAISE invalid_parameter_value USING MESSAGE='one external source is required'; END IF;
  PERFORM 1 FROM public.external_sync_sources s
    WHERE s.source_name=p_source_name FOR UPDATE;
  SELECT min(m.target_org_id),array_agg(DISTINCT m.target_unit_id ORDER BY m.target_unit_id)
    INTO v_organization,v_units FROM public.external_sync_maps m
    WHERE m.source_name=p_source_name;
  IF v_organization IS NULL OR EXISTS (SELECT 1 FROM public.external_sync_maps m
      WHERE m.source_name=p_source_name AND m.target_org_id<>v_organization) THEN
    RAISE invalid_parameter_value USING MESSAGE='external source must map to one organization';
  END IF;
  SELECT COALESCE(jsonb_agg(jsonb_build_object('id',o.id,'unit',o.unit,
    'row',to_jsonb(o)-'updated_at') ORDER BY o.id),'[]'::jsonb) INTO v_before
    FROM public.occasions o WHERE o.external_source=p_source_name;
  v_result:=public.sync_source_via_http_internal_v1(p_source_name);
  IF v_result LIKE 'Error:%' THEN
    RAISE external_routine_exception USING MESSAGE=v_result; END IF;
  SELECT COALESCE(jsonb_agg(jsonb_build_object('id',o.id,'unit',o.unit,
    'row',to_jsonb(o)-'updated_at') ORDER BY o.id),'[]'::jsonb) INTO v_after
    FROM public.occasions o WHERE o.external_source=p_source_name;
  IF v_before=v_after THEN RETURN v_result; END IF;
  SELECT ARRAY(SELECT COALESCE(a.id,b.id) FROM
    jsonb_to_recordset(v_after) a(id bigint,unit bigint,row jsonb)
    FULL JOIN jsonb_to_recordset(v_before) b(id bigint,unit bigint,row jsonb)
      ON a.id=b.id WHERE a.row IS DISTINCT FROM b.row ORDER BY 1)
    INTO v_changed;
  SELECT ARRAY(SELECT b.id FROM jsonb_to_recordset(v_before)
    b(id bigint,unit bigint,row jsonb) WHERE NOT EXISTS (
      SELECT 1 FROM jsonb_to_recordset(v_after) a(id bigint,unit bigint,row jsonb)
      WHERE a.id=b.id) ORDER BY b.id) INTO v_deleted;
  SELECT ARRAY(SELECT DISTINCT unit_id FROM (
    SELECT unit unit_id FROM jsonb_to_recordset(v_before)
      b(id bigint,unit bigint,row jsonb) WHERE id=ANY(v_changed)
    UNION SELECT unit FROM jsonb_to_recordset(v_after)
      a(id bigint,unit bigint,row jsonb) WHERE id=ANY(v_changed)
  ) units WHERE unit_id IS NOT NULL ORDER BY unit_id) INTO v_units;
  INSERT INTO public.client_commits
    (organization,actor_id,actor_display,actor_kind,source,change_class,reason)
  VALUES (v_organization,NULL,NULL,'service','occasion.external_sync',
    'configuration','external source '||p_source_name) RETURNING * INTO v_commit;
  INSERT INTO public.client_commit_items
    (commit_id,item_index,entity_type,entity_id,operation,safe_label,changed_fields)
  VALUES (v_commit.commit_id,0,'external_source',p_source_name,'sync',
    left(p_source_name,240),ARRAY['occasions']);
  FOREACH v_occasion IN ARRAY v_changed LOOP
    IF v_occasion=ANY(COALESCE(v_deleted,'{}'::bigint[])) THEN
      DELETE FROM public.client_projection_dirty_keys
        WHERE scope_type='occasion' AND scope_id=v_occasion;
      DELETE FROM public.client_sync_scopes
        WHERE scope_type='occasion' AND scope_id=v_occasion;
      DELETE FROM public.client_sync_private_scopes WHERE occasion=v_occasion;
      CONTINUE;
    END IF;
    INSERT INTO public.client_sync_scopes
      (component,scope_type,scope_id,source_revision)
    VALUES ('occasion_config','occasion',v_occasion,1)
    ON CONFLICT (component,scope_type,scope_id) DO UPDATE SET
      source_revision=public.client_sync_scopes.source_revision+1,updated_at=now()
    RETURNING source_revision INTO v_revision;
    INSERT INTO public.client_commit_components
      (commit_id,component,scope_type,scope_id,user_id,resulting_revision)
    VALUES (v_commit.commit_id,'occasion_config','occasion',v_occasion,NULL,v_revision);
  END LOOP;
  FOREACH v_unit IN ARRAY COALESCE(v_units,'{}'::bigint[]) LOOP
    PERFORM public.fanout_unit_catalog_v1(v_commit.commit_id,v_unit);
  END LOOP;
  RETURN v_result;
END; $function$

CREATE OR REPLACE FUNCTION public.unassign_existing_companion_client_sync_v1(p_occasion bigint, p_owner uuid, p_companion uuid, p_command_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_policy jsonb; v_begin jsonb; v_hash text;
BEGIN
  v_policy:=public.get_companion_feature_policy_v1(p_occasion);
  IF NOT public.get_can_assign_companions_on_occasion(p_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion editor required';
  END IF;
  IF NOT COALESCE((v_policy->>'is_enabled')::boolean,false)
      OR NOT COALESCE((v_policy->>'allow_admin_assign')::boolean,false) THEN
    RAISE insufficient_privilege USING MESSAGE='admin companion assignment disabled';
  END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object('occasion',p_occasion,
    'owner',p_owner,'companion',p_companion)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,'profile.companion.unassign',
    p_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(
    'companion-member:'||p_occasion::text||':'||least(p_owner::text,p_companion::text),0));
  DELETE FROM public.user_companions uc WHERE uc.occasion=p_occasion
    AND uc."user"=p_owner AND uc.companion=p_companion
    AND uc.origin='admin_assigned';
  IF NOT FOUND THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'unchanged',200,
      jsonb_build_object('owner',p_owner,'companion',p_companion));
  END IF;
  RETURN public.complete_private_profile_mutation_v1(p_command_id,p_occasion,
    'profile.companion.unassign',jsonb_build_array(jsonb_build_object(
      'entityType','companion_assignment','entityId',p_companion,'operation','delete',
      'safeLabel','Companion assignment','changedFields',jsonb_build_array('owner'))),
    ARRAY[p_owner],'{}','[]',jsonb_build_object('owner',p_owner,'companion',p_companion));
END $function$

CREATE OR REPLACE FUNCTION public.update_bank_account(p_id bigint, p_account_number text, p_title text, p_type text DEFAULT 'FIO'::text, p_supported_currencies text[] DEFAULT NULL::text[], p_account_number_human_readable text DEFAULT NULL::text, p_unit_id bigint DEFAULT NULL::bigint, p_creditor_name text DEFAULT NULL::text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
    v_id bigint;
    v_account_number text;
    v_operation_id uuid;
    v_request jsonb;
BEGIN
    PERFORM public.check_bank_account_writable(p_id);
    -- Prevent manual manipulation of CASH accounts
    IF p_type = 'CASH' THEN
        RAISE EXCEPTION 'CASH_ACCOUNT_MANUAL_UPDATE_FORBIDDEN';
    END IF;

    IF char_length(p_title)>120 THEN RAISE EXCEPTION 'BANK_ACCOUNT_TITLE_TOO_LONG'; END IF;

    -- Input normalization
    v_account_number := TRIM(p_account_number);

    IF p_id IS NULL THEN
        -- Creation: If p_unit_id is provided, enforce that creator is Manager of that unit
        IF p_unit_id IS NOT NULL THEN
             PERFORM check_is_manager_on_unit(p_unit_id);
        END IF;

        -- Check for duplicate account number on insert
        IF EXISTS (SELECT 1 FROM eshop.bank_accounts WHERE account_number = v_account_number) THEN
             RAISE EXCEPTION 'ACCOUNT_NUMBER_EXISTS';
        END IF;

        INSERT INTO eshop.bank_accounts (account_number, title, type, supported_currencies, account_number_human_readable, creditor_name)
        VALUES (v_account_number, p_title, p_type, p_supported_currencies, p_account_number_human_readable, nullif(trim(p_creditor_name), ''))
        RETURNING id INTO v_id;

        -- Automatically make the creator an Admin
        INSERT INTO eshop.bank_account_users (bank_account, "user", is_admin)
        VALUES (v_id, auth.uid(), true);

        -- Automatically link to unit if provided
        IF p_unit_id IS NOT NULL THEN
             INSERT INTO eshop.unit_bank_accounts (unit, bank_account, priority)
             VALUES (p_unit_id, v_id, 0);
        END IF;
    ELSE
        -- Check for duplicate account number on update (exclude current id)
        IF EXISTS (SELECT 1 FROM eshop.bank_accounts WHERE account_number = v_account_number AND id != p_id) THEN
             RAISE EXCEPTION 'ACCOUNT_NUMBER_EXISTS';
        END IF;

        -- Security Check: Caller must be an Admin of the bank account
        IF NOT EXISTS (
            SELECT 1 FROM eshop.bank_account_users
            WHERE bank_account = p_id AND "user" = auth.uid() AND is_admin = true
        ) THEN
            RAISE EXCEPTION 'Permission denied: Only bank account admins can update details.';
        END IF;

        PERFORM 1 FROM eshop.bank_accounts WHERE id=p_id FOR UPDATE;
        IF EXISTS (SELECT 1 FROM eshop.bank_sync_connections WHERE bank_account_id=p_id)
          AND EXISTS (SELECT 1 FROM eshop.bank_accounts WHERE id=p_id
            AND (account_number IS DISTINCT FROM v_account_number OR type IS DISTINCT FROM p_type)) THEN
          RAISE EXCEPTION 'BANK_SYNC_ACCOUNT_IDENTITY_IMMUTABLE';
        END IF;
        IF EXISTS(SELECT 1 FROM eshop.payment_reference_accounts a JOIN eshop.payment_reference_namespaces n ON n.id=a.namespace_id
          WHERE a.bank_account_id=p_id AND (n.canonical_account IS DISTINCT FROM public.canonical_payment_reference_account_internal(v_account_number)
           OR p_type='CASH')) THEN RAISE EXCEPTION 'PAYMENT_REFERENCE_ACCOUNT_IDENTITY_IMMUTABLE'; END IF;
        UPDATE eshop.bank_accounts
        SET
            account_number = v_account_number,
            title = p_title,
            type = p_type,
            supported_currencies = p_supported_currencies,
            account_number_human_readable = p_account_number_human_readable,
            creditor_name = nullif(trim(p_creditor_name), ''),
            updated_at = NOW()
        WHERE id = p_id
        RETURNING id INTO v_id;
    END IF;
    -- Local details and the durable remote update intent commit together.
    IF p_id IS NOT NULL AND EXISTS(SELECT 1 FROM eshop.bank_sync_connections WHERE bank_account_id=v_id) THEN
      v_operation_id := gen_random_uuid();
      v_request := jsonb_build_object('operation','update_details','operation_id',v_operation_id,'account_id',v_id);
      INSERT INTO eshop.bank_sync_operations(id,bank_account_id,actor,operation,payload_sha256,state,request)
        VALUES(v_operation_id,v_id,auth.uid(),'update_details',encode(extensions.digest(v_request::text,'sha256'),'hex'),'pending',v_request);
    END IF;
    RETURN v_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.update_bank_account_user(p_bank_account_id bigint, p_user_email text, p_is_admin boolean, p_is_support boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
    v_user_id uuid;
BEGIN
    -- Security Check: Caller must be an Admin of the bank account
    IF NOT EXISTS (
        SELECT 1 FROM eshop.bank_account_users
        WHERE bank_account = p_bank_account_id AND "user" = auth.uid() AND is_admin = true
    ) THEN
        RAISE EXCEPTION 'Permission denied: Only bank account admins can manage users.';
    END IF;

    -- Find user by email (assuming email_readonly is populated and unique-ish for lookup)
    -- In a real app, might want a better user lookup, but this fits the pattern
    SELECT id INTO v_user_id FROM public.user_info WHERE email_readonly = p_user_email LIMIT 1;

    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'User not found';
    END IF;

    -- If both flags are false or null, remove the user
    IF (p_is_admin IS NULL OR p_is_admin = false) AND (p_is_support IS NULL OR p_is_support = false) THEN
        DELETE FROM eshop.bank_account_users
        WHERE bank_account = p_bank_account_id AND "user" = v_user_id;
    ELSE
        IF EXISTS (SELECT 1 FROM eshop.bank_account_users WHERE bank_account = p_bank_account_id AND "user" = v_user_id) THEN
            UPDATE eshop.bank_account_users
            SET is_admin = COALESCE(p_is_admin, false), is_support = COALESCE(p_is_support, false)
            WHERE bank_account = p_bank_account_id AND "user" = v_user_id;
        ELSE
            INSERT INTO eshop.bank_account_users (bank_account, "user", is_admin, is_support)
            VALUES (p_bank_account_id, v_user_id, COALESCE(p_is_admin, false), COALESCE(p_is_support, false));
        END IF;
    END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.update_blueprint_client_sync_v1(p_blueprint jsonb, p_command_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_occasion bigint; v_blueprint bigint;
  v_begin jsonb; v_hash text; v_users uuid[]; v_result jsonb; v_reason text; v_detail text; v_issue jsonb;
BEGIN
  IF p_blueprint IS NULL OR jsonb_typeof(p_blueprint)<>'object'
    OR octet_length(p_blueprint::text)>8388608 THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid blueprint aggregate'; END IF;
  SELECT occasion INTO v_occasion FROM public.client_mutation_receipts WHERE command_id=p_command_id AND actor_id=v_actor AND command_name='inventory.blueprint.save';
  IF NOT FOUND THEN
  v_occasion:=NULLIF(p_blueprint->>'occasion','')::bigint;
  v_blueprint:=NULLIF(p_blueprint->>'id','')::bigint;
  IF v_blueprint IS NOT NULL THEN SELECT occasion INTO v_occasion FROM eshop.blueprints WHERE id=v_blueprint; END IF;
  ELSE v_blueprint:=NULLIF(p_blueprint->>'id','')::bigint; END IF;
  IF v_actor IS NULL OR v_occasion IS NULL
    OR (coalesce(public.get_is_editor_on_occasion(v_occasion),false) OR coalesce(public.get_is_manager_on_occasion(v_occasion),false)) IS NOT TRUE THEN
    RAISE insufficient_privilege USING MESSAGE='blueprint editor required'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'occasion',v_occasion,'blueprint',p_blueprint)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,
    'inventory.blueprint.save',v_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  IF v_blueprint IS NOT NULL AND NOT EXISTS (SELECT 1 FROM eshop.blueprints b WHERE b.id=v_blueprint AND b.occasion=v_occasion) THEN RAISE insufficient_privilege USING MESSAGE='foreign blueprint'; END IF;
  PERFORM public.lock_blueprint_scope_internal(ARRAY[v_occasion]);
  SELECT COALESCE(array_agg(DISTINCT ou."user"),'{}'::uuid[]) INTO v_users
  FROM public.occasion_users ou JOIN eshop.order_product_ticket opt
    ON opt.ticket=ou.ticket JOIN eshop.spots s
    ON s.order_product_ticket=opt.id
  WHERE ou.occasion=v_occasion AND s.occasion=v_occasion;
  BEGIN
    IF p_blueprint->'layout' IS NULL OR p_blueprint->'layout'='null'::jsonb THEN RAISE check_violation USING MESSAGE='BLUEPRINT_LAYOUT_REQUIRED'; END IF;
    v_result:=public.save_blueprint_layout_internal_v1(p_blueprint);
  EXCEPTION WHEN check_violation OR raise_exception OR invalid_text_representation OR not_null_violation OR unique_violation OR foreign_key_violation THEN
    GET STACKED DIAGNOSTICS v_reason=MESSAGE_TEXT,v_detail=PG_EXCEPTION_DETAIL;
    v_issue:=jsonb_build_object('reason',v_reason);
    IF left(coalesce(v_detail,''),1)='{' THEN
      BEGIN v_issue:=v_issue||jsonb_strip_nulls(jsonb_build_object('nodeId',(v_detail::jsonb)->'nodeId','spotId',(v_detail::jsonb)->'spotId','groupNodeId',(v_detail::jsonb)->'groupNodeId'));
      EXCEPTION WHEN invalid_text_representation THEN NULL; END;
    END IF;
    v_result:=jsonb_build_object('code',409,'reason',CASE WHEN SQLSTATE IN ('23514','P0001') THEN v_reason ELSE 'BLUEPRINT_INVALID_INPUT' END,
      'issues',jsonb_build_array(v_issue),
      'layout_revision',(SELECT layout_revision FROM eshop.blueprints WHERE id=v_blueprint));
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',409,v_result);
  END;
  RETURN public.complete_private_inventory_mutation_v1(p_command_id,v_occasion,
    'inventory.blueprint.save',jsonb_build_array(jsonb_build_object(
      'entityType','blueprint','entityId',v_result->>'blueprint_id',
      'operation',CASE WHEN v_blueprint IS NULL THEN 'insert' ELSE 'update' END,
      'safeLabel',left(p_blueprint->>'title',240),'changedFields',jsonb_build_array(
        'layout','bindings'))),v_users,v_result);
END; $function$

CREATE OR REPLACE FUNCTION public.update_email_template(p_data jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_occ   bigint;
  v_unit  bigint;
  v_org   bigint;
  v_code  text;
  v_existing_id bigint;
  v_actual_unit bigint;
  v_actual_org bigint;
BEGIN
  -- Extract values from input JSON.
  v_occ  := CASE WHEN p_data ? 'occasion' THEN (p_data ->> 'occasion')::bigint ELSE NULL END;
  v_unit := CASE WHEN p_data ? 'unit' THEN (p_data ->> 'unit')::bigint ELSE NULL END;
  v_org := (p_data ->> 'organization')::bigint;
  v_code := p_data ->> 'code';

  -- Resolve the actual hierarchy before authorizing template writes.
  IF v_occ IS NOT NULL THEN
    SELECT unit, organization INTO v_actual_unit, v_actual_org FROM public.occasions WHERE id=v_occ;
    IF NOT FOUND OR (v_unit IS NOT NULL AND v_unit IS DISTINCT FROM v_actual_unit)
        OR (v_org IS NOT NULL AND v_org IS DISTINCT FROM v_actual_org) THEN
      RAISE insufficient_privilege USING MESSAGE='Invalid email template hierarchy';
    END IF;
    v_unit := v_actual_unit;
    v_org := v_actual_org;
    IF NOT public.is_service_role() AND public.get_is_editor_on_occasion(v_occ) IS NOT TRUE
       AND public.get_is_editor_order_on_occasion(v_occ) IS NOT TRUE THEN
      RAISE insufficient_privilege USING MESSAGE='Occasion template write denied';
    END IF;
  ELSIF v_unit IS NOT NULL THEN
    SELECT organization INTO v_actual_org FROM public.units WHERE id=v_unit;
    IF NOT FOUND OR (v_org IS NOT NULL AND v_org IS DISTINCT FROM v_actual_org) THEN
      RAISE insufficient_privilege USING MESSAGE='Invalid email template hierarchy';
    END IF;
    v_org := v_actual_org;
    IF NOT public.is_service_role() AND public.get_is_editor_on_unit(v_unit) IS NOT TRUE THEN
      RAISE insufficient_privilege USING MESSAGE='Unit template write denied';
    END IF;
  ELSIF NOT public.is_service_role() THEN
    IF v_org IS NULL OR public.get_is_admin_on_organization(v_org) IS NOT TRUE THEN
      RAISE insufficient_privilege USING MESSAGE='Organization template write denied';
    END IF;
  END IF;

  -- An occasion override is identified by occasion + code. Ancestors are
  -- metadata, not identity; the partial unique index also fences concurrent saves.
  IF v_occ IS NOT NULL THEN
    INSERT INTO public.email_templates (html, occasion, subject, organization, code, unit, title)
    VALUES (p_data->>'html', v_occ, p_data->>'subject', v_org, v_code, v_unit, p_data->>'title')
    ON CONFLICT (occasion, code) WHERE occasion IS NOT NULL
    DO UPDATE SET html=EXCLUDED.html, subject=EXCLUDED.subject, title=EXCLUDED.title,
                  unit=EXCLUDED.unit, organization=EXCLUDED.organization;
    RETURN;
  END IF;

  -- Try to find an existing email template matching the given context and code.
  SELECT id
    INTO v_existing_id
  FROM public.email_templates
  WHERE
    ((occasion = v_occ) OR (occasion IS NULL AND v_occ IS NULL))
    AND ((unit = v_unit) OR (unit IS NULL AND v_unit IS NULL))
    AND ((organization = v_org) OR (organization IS NULL AND v_org IS NULL))
    AND code = v_code
  LIMIT 1;

  IF FOUND THEN
    -- Update the existing record.
    UPDATE public.email_templates
    SET
      html    = p_data ->> 'html',
      subject = p_data ->> 'subject',
      title   = p_data ->> 'title'
    WHERE id = v_existing_id;
  ELSE
    -- Insert a new record.
    INSERT INTO public.email_templates (
      html,
      occasion,
      subject,
      organization,
      code,
      unit,
      title
    )
    VALUES (
      p_data ->> 'html',
      v_occ,
      p_data ->> 'subject',
      v_org,
      v_code,
      v_unit,
      p_data ->> 'title'
    );
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.update_entity_email_banner(p_entity_type text, p_entity_id bigint, p_banner_url text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
    v_org_id bigint;
    v_entity_title text;
    v_new_html text;
    v_before jsonb;
begin
    -- 1. Validate Entity Type and Permissions
    if p_entity_type = 'occasion' then
        if (public.get_is_editor_on_occasion(p_entity_id) IS NOT TRUE
            AND public.get_is_editor_order_on_occasion(p_entity_id) IS NOT TRUE) then
            perform public.raise_error('permission_denied');
        end if;

        SELECT data INTO v_before FROM public.occasions WHERE id=p_entity_id FOR UPDATE;
        -- Update Occasion Data
        update public.occasions
        set data = jsonb_set(coalesce(data, '{}'), '{email_banner}', coalesce(to_jsonb(p_banner_url),'null'::jsonb))
        where id = p_entity_id
        returning organization, title into v_org_id, v_entity_title;

    elsif p_entity_type = 'unit' then
        if (public.get_is_editor_on_unit(p_entity_id) IS NOT TRUE) then
            perform public.raise_error('permission_denied');
        end if;

        SELECT data INTO v_before FROM public.units WHERE id=p_entity_id FOR UPDATE;
        -- Update Unit Data
        update public.units
        set data = jsonb_set(coalesce(data, '{}'), '{email_banner}', coalesce(to_jsonb(p_banner_url),'null'::jsonb))
        where id = p_entity_id
        returning organization, title into v_org_id, v_entity_title;

    else
        raise exception 'Invalid entity type: %', p_entity_type;
    end if;

    IF v_before IS DISTINCT FROM (CASE WHEN p_entity_type='occasion'
      THEN (SELECT data FROM public.occasions WHERE id=p_entity_id)
      ELSE (SELECT data FROM public.units WHERE id=p_entity_id) END) THEN
      INSERT INTO public.client_aggregate_versions(aggregate_type,scope_type,scope_id,aggregate_id,version)
      VALUES(p_entity_type,p_entity_type,p_entity_id,p_entity_id::text,1)
      ON CONFLICT(aggregate_type,scope_type,scope_id,aggregate_id) DO UPDATE
      SET version=public.client_aggregate_versions.version+1,updated_at=clock_timestamp();
    END IF;

    -- 2. Handle HTML Wrapper Logic
    if p_banner_url is not null then
        -- Construct Custom HTML
        v_new_html := '<div style="font-family: Arial, sans-serif; font-size: 16px; max-width: 680px; margin: 0 auto;">';
        v_new_html := v_new_html || '<div style="text-align: center;">';
        v_new_html := v_new_html || '<img src="' || p_banner_url || '" alt="' || coalesce(v_entity_title, 'Banner') || '" style="width: 100%; height: auto; display: block;">';
        v_new_html := v_new_html || '</div>';
        v_new_html := v_new_html || '<div style="margin-top: 10px; margin-bottom: 10px;">';
        v_new_html := v_new_html || '{{content}}';
        v_new_html := v_new_html || '</div></div>';

        -- Upsert Wrapper
        if p_entity_type = 'occasion' then
             -- For occasion, check existing wrapper
            if exists (select 1 from public.email_wrappers where occasion = p_entity_id) then
                update public.email_wrappers set html = v_new_html where occasion = p_entity_id;
            else
                insert into public.email_wrappers (occasion, organization, unit, title, html)
                values (p_entity_id, v_org_id, (select unit from occasions where id = p_entity_id), 'Occasion Banner Wrapper', v_new_html);
            end if;
        elsif p_entity_type = 'unit' then
             -- For unit (occasion is null)
            if exists (select 1 from public.email_wrappers where unit = p_entity_id and occasion is null) then
                update public.email_wrappers set html = v_new_html where unit = p_entity_id and occasion is null;
            else
                insert into public.email_wrappers (occasion, organization, unit, title, html)
                values (null, v_org_id, p_entity_id, 'Unit Banner Wrapper', v_new_html);
            end if;
        end if;
    else
        -- 3. Banner Removed -> Delete Wrapper
        if p_entity_type = 'occasion' then
            delete from public.email_wrappers where occasion = p_entity_id;
        elsif p_entity_type = 'unit' then
            delete from public.email_wrappers where unit = p_entity_id and occasion is null;
        end if;
    end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.update_form_client_sync_v1(p_form jsonb, p_command_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_occasion bigint; v_form bigint;
  v_begin jsonb; v_hash text; v_version bigint; v_expected bigint; v_users uuid[]; v_result jsonb; v_check record; v_current bigint;
BEGIN
  IF p_form IS NULL OR jsonb_typeof(p_form)<>'object'
    OR octet_length(p_form::text)>4194304 THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid form aggregate'; END IF;
  v_occasion:=NULLIF(p_form->>'occasion','')::bigint;
  v_form:=NULLIF(p_form->>'id','')::bigint;
  IF v_actor IS NULL OR v_occasion IS NULL OR v_form IS NULL
    OR NOT public.get_is_editor_order_on_occasion(v_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='order editor required'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'occasion',v_occasion,'form',p_form)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,
    'inventory.form.save',v_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.forms WHERE id=v_form AND occasion=v_occasion) THEN RAISE insufficient_privilege USING MESSAGE='foreign form'; END IF;
  -- Parent order matches checkout: form, product, blueprint, then seats.
  PERFORM 1 FROM public.forms WHERE id=v_form AND occasion=v_occasion FOR UPDATE;
  PERFORM 1 FROM eshop.product_types WHERE occasion=v_occasion ORDER BY id FOR UPDATE;
  PERFORM 1 FROM eshop.products WHERE occasion=v_occasion ORDER BY id FOR UPDATE;
  IF v_form IS NOT NULL THEN
    INSERT INTO public.client_aggregate_versions(aggregate_type,scope_type,scope_id,aggregate_id,version)
    VALUES('form','occasion',v_occasion,v_form::text,0) ON CONFLICT DO NOTHING;
    SELECT version INTO v_version FROM public.client_aggregate_versions
    WHERE aggregate_type='form' AND scope_type='occasion' AND scope_id=v_occasion AND aggregate_id=v_form::text FOR UPDATE;
  ELSE v_version:=0; END IF;
  -- Missing baseline remains an installed-client adapter, explicitly not MCP-ready.
  v_expected:=CASE WHEN p_form ? 'expected_aggregate_version' THEN (p_form->>'expected_aggregate_version')::bigint ELSE v_version END;
  IF v_expected IS DISTINCT FROM v_version THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'conflict',409,jsonb_build_object('aggregate_version',v_version)); END IF;
  -- These maps were frozen when the editor loaded. No read-before-write rebasing.
  -- Missing maps are the bounded released-client facade, not MCP-ready authoring.
  IF p_form ? 'expected_product_versions' OR p_form ? 'expected_product_type_versions' THEN
    IF jsonb_typeof(p_form->'expected_product_versions') IS DISTINCT FROM 'object'
      OR jsonb_typeof(p_form->'expected_product_type_versions') IS DISTINCT FROM 'object' THEN
      RAISE invalid_parameter_value USING MESSAGE='original product versions required'; END IF;
    FOR v_check IN
      SELECT DISTINCT 'product'::text kind, (p->>'id')::bigint id FROM jsonb_array_elements(coalesce(p_form->'form_fields','[]')) f
        CROSS JOIN LATERAL jsonb_array_elements(coalesce(nullif(f#>'{product_type,products}','null'),'[]')) p WHERE p->>'id' IS NOT NULL
      UNION SELECT 'product',value::bigint FROM jsonb_array_elements_text(coalesce(p_form->'deleted_product_ids','[]'))
      UNION SELECT DISTINCT 'product',p.id FROM eshop.products p JOIN public.form_fields ff ON ff.product_type=p.product_type
        WHERE ff.form=v_form AND ff.id IN (SELECT value::bigint FROM jsonb_array_elements_text(coalesce(p_form->'deleted_field_ids','[]')))
      UNION SELECT DISTINCT 'product_type',(f#>>'{product_type,id}')::bigint FROM jsonb_array_elements(coalesce(p_form->'form_fields','[]')) f
        WHERE f#>>'{product_type,id}' IS NOT NULL
      ORDER BY 1,2
    LOOP
      IF NOT (CASE v_check.kind WHEN 'product' THEN p_form->'expected_product_versions'
        ELSE p_form->'expected_product_type_versions' END) ? v_check.id::text THEN
        RAISE invalid_parameter_value USING MESSAGE='missing original product baseline'; END IF;
      IF (v_check.kind='product' AND NOT EXISTS(SELECT 1 FROM eshop.products WHERE id=v_check.id AND occasion=v_occasion))
        OR (v_check.kind='product_type' AND NOT EXISTS(SELECT 1 FROM eshop.product_types WHERE id=v_check.id AND occasion=v_occasion)) THEN
        RETURN public.complete_client_mutation_outcome_v1(p_command_id,'conflict',409,jsonb_build_object('entity_type',v_check.kind,'entity_id',v_check.id,'deleted',true)); END IF;
      SELECT coalesce(v.version,0) INTO v_current FROM (SELECT 1) seed LEFT JOIN public.client_aggregate_versions v
        ON v.aggregate_type=v_check.kind AND v.scope_type='occasion' AND v.scope_id=v_occasion AND v.aggregate_id=v_check.id::text;
      IF ((CASE v_check.kind WHEN 'product' THEN p_form->'expected_product_versions' ELSE p_form->'expected_product_type_versions' END)->>v_check.id::text)::bigint IS DISTINCT FROM v_current THEN
        RETURN public.complete_client_mutation_outcome_v1(p_command_id,'conflict',409,
          jsonb_build_object('aggregate_version',v_version,'entity_type',v_check.kind,'entity_id',v_check.id,'entity_version',v_current));
      END IF;
    END LOOP;
  END IF;
  SELECT COALESCE(array_agg(DISTINCT ou."user"),'{}'::uuid[]) INTO v_users
  FROM public.occasion_users ou JOIN eshop.order_product_ticket opt
    ON opt.ticket=ou.ticket JOIN eshop.products p ON p.id=opt.product
  WHERE ou.occasion=v_occasion AND p.occasion=v_occasion;
  BEGIN
    v_result:=public.update_form_internal_v1(p_form-'expected_aggregate_version'-'expected_product_versions'-'expected_product_type_versions');
    IF coalesce((v_result->>'code')::integer,500)<>200 THEN
      RAISE SQLSTATE 'P0F01' USING MESSAGE='authoring domain rejected'; END IF;
  EXCEPTION WHEN SQLSTATE 'P0F01' THEN NULL;
  END;
  IF coalesce((v_result->>'code')::integer,500)<>200 THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',
      CASE WHEN (v_result->>'code')::integer BETWEEN 100 AND 599 THEN (v_result->>'code')::integer ELSE 400 END,v_result); END IF;
  v_form:=(v_result->>'form_id')::bigint;
  INSERT INTO public.client_aggregate_versions(aggregate_type,scope_type,scope_id,aggregate_id,version)
    VALUES('form','occasion',v_occasion,v_form::text,1)
    ON CONFLICT(aggregate_type,scope_type,scope_id,aggregate_id) DO UPDATE
    SET version=public.client_aggregate_versions.version+1,updated_at=clock_timestamp()
    RETURNING version INTO v_version;
  v_result:=v_result||jsonb_build_object('aggregate_version',v_version,
    'product_versions',public.get_ticketing_product_versions_internal_v1(v_occasion,'product'),
    'product_type_versions',public.get_ticketing_product_versions_internal_v1(v_occasion,'product_type'));
  RETURN public.complete_private_inventory_mutation_v1(p_command_id,v_occasion,
    'inventory.form.save',jsonb_build_array(jsonb_build_object(
      'entityType','form','entityId',v_form,'operation','update',
      'safeLabel',left(p_form->>'title',240),'changedFields',jsonb_build_array(
        'configuration','products'))),v_users,v_result);
END; $function$

CREATE OR REPLACE FUNCTION public.update_inclusion_type_group(p_inclusion_type_group_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
    v_occasion_id bigint;
    v_group_id bigint;
    v_type_data jsonb;
    v_type_id bigint;
    v_type_ids_from_input bigint[];
    result jsonb;

    -- Variables for spot management
    v_maximum_capacity INT;
    v_current_spot_count INT;
    v_reserved_spot_count INT;
    v_spots_to_add INT;
    v_spots_to_delete INT;
    v_free_spots INT;
BEGIN
    -- Resolve occasion ID from the input data. An ID is required for updates.
    v_occasion_id := (p_inclusion_type_group_data->>'occasion')::bigint;
    IF v_occasion_id IS NULL THEN
        RAISE EXCEPTION 'Occasion ID is required to update an inclusion type group.';
    END IF;

    -- Permission check to ensure the user can edit data for this occasion.
    IF NOT get_is_editor_order_on_occasion(v_occasion_id) THEN
        RAISE EXCEPTION 'User is not authorized to edit this occasion.';
    END IF;

    -- Upsert the main group record.
    v_group_id := (p_inclusion_type_group_data->>'id')::bigint;

    IF v_group_id IS NULL THEN
        INSERT INTO public.inclusion_type_groups (title, type, occasion, created_at, updated_at)
        VALUES (
            p_inclusion_type_group_data->>'title',
            p_inclusion_type_group_data->>'type',
            v_occasion_id,
            now(),
            now()
        ) RETURNING id INTO v_group_id;
    ELSE
        UPDATE public.inclusion_type_groups
        SET
            title = p_inclusion_type_group_data->>'title',
            type = p_inclusion_type_group_data->>'type',
            updated_at = now()
        WHERE id = v_group_id;
    END IF;

    -- Upsert the nested inclusion types and manage spots.
    IF jsonb_typeof(p_inclusion_type_group_data->'inclusion_types') = 'array' THEN
        v_type_ids_from_input := ARRAY[]::bigint[];
        FOR v_type_data IN SELECT * FROM jsonb_array_elements(p_inclusion_type_group_data->'inclusion_types')
        LOOP
            v_type_id := (v_type_data->>'id')::bigint;
            IF v_type_id IS NULL THEN
                INSERT INTO public.inclusion_types (title, inclusion_type_group, data, created_at, updated_at)
                VALUES (
                    v_type_data->>'title',
                    v_group_id,
                    v_type_data->'data',
                    now(),
                    now()
                ) RETURNING id INTO v_type_id;
            ELSE
                UPDATE public.inclusion_types
                SET title = v_type_data->>'title', data = v_type_data->'data', updated_at = now()
                WHERE id = v_type_id;
            END IF;
            v_type_ids_from_input := array_append(v_type_ids_from_input, v_type_id);

            -- === Spot Management Logic ===
            v_maximum_capacity := COALESCE((v_type_data->'data'->>'maximum')::int, 0);

            SELECT COUNT(*), COUNT(*) FILTER (WHERE order_product_ticket IS NOT NULL)
            INTO v_current_spot_count, v_reserved_spot_count
            FROM eshop.spots
            WHERE inclusion_type = v_type_id;

            IF v_maximum_capacity > v_current_spot_count THEN
                v_spots_to_add := v_maximum_capacity - v_current_spot_count;
                INSERT INTO eshop.spots (occasion, inclusion_type, title)
                SELECT v_occasion_id, v_type_id, v_type_data->>'title'
                FROM generate_series(1, v_spots_to_add);

            ELSIF v_maximum_capacity < v_current_spot_count THEN
                v_spots_to_delete := v_current_spot_count - v_maximum_capacity;
                v_free_spots := v_current_spot_count - v_reserved_spot_count;

                IF v_spots_to_delete > v_free_spots THEN
                    RAISE EXCEPTION 'Cannot reduce capacity to %, as % spots are already reserved.', v_maximum_capacity, v_reserved_spot_count;
                END IF;

                DELETE FROM eshop.spots
                WHERE id IN (
                    SELECT id FROM eshop.spots
                    WHERE inclusion_type = v_type_id AND order_product_ticket IS NULL
                    LIMIT v_spots_to_delete
                );
            END IF;

        END LOOP;

        DELETE FROM public.inclusion_types
        WHERE inclusion_type_group = v_group_id
        AND id <> ALL(v_type_ids_from_input);
    END IF;

    -- Return the fully updated group object with its nested types.
    SELECT jsonb_build_object(
        'id', g.id,
        'created_at', g.created_at,
        'updated_at', g.updated_at,
        'title', g.title,
        'type', g.type,
        'occasion', g.occasion,
        'inclusion_types', (
            SELECT COALESCE(jsonb_agg(
                jsonb_build_object(
                    'id', t.id,
                    'created_at', t.created_at,
                    'updated_at', t.updated_at,
                    'title', t.title,
                    'inclusion_type_group', t.inclusion_type_group,
                    'data', t.data
                ) ORDER BY t.created_at
            ), '[]'::jsonb)
            FROM public.inclusion_types t
            WHERE t.inclusion_type_group = g.id
        )
    )
    INTO result
    FROM public.inclusion_type_groups g
    WHERE g.id = v_group_id;

    RETURN result;
EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object('code', 500, 'message', SQLERRM);
END;
$function$

CREATE OR REPLACE FUNCTION public.update_inventory_pool_bundle_internal_v1(p_bundle_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
    v_pool_data jsonb := p_bundle_data->'pool';
    v_pool_id bigint;
    v_occasion_id bigint;

    -- Context variables
    v_context_data jsonb;
    v_context_id bigint;
    v_context_ids_from_input bigint[] := ARRAY[]::bigint[];

    result jsonb;
BEGIN
    -- Resolve occasion ID from the input data. It's required for both create and update.
    v_occasion_id := (v_pool_data->>'occasion')::bigint;
    IF v_occasion_id IS NULL THEN
        RAISE EXCEPTION '%', jsonb_build_object('code', 'B001', 'message', 'Occasion ID is required.')::text;
    END IF;

    -- Permission check
    IF NOT get_is_editor_order_on_occasion(v_occasion_id) THEN
        RAISE EXCEPTION '%', jsonb_build_object('code', 403, 'message', 'User is not authorized to edit this occasion.')::text;
    END IF;

    -- 1. Upsert the main inventory_pool record
    v_pool_id := (v_pool_data->>'id')::bigint;

    IF v_pool_id IS NULL THEN
        -- Create a new pool if ID is not provided
        INSERT INTO public.inventory_pools (title, occasion, sellable_capacity, description, type, data, created_at, updated_at)
        VALUES (
            v_pool_data->>'title',
            v_occasion_id,
            (v_pool_data->>'sellable_capacity')::bigint,
            v_pool_data->>'description',
            v_pool_data->>'type',
            v_pool_data->'data',
            now(),
            now()
        ) RETURNING id INTO v_pool_id;
    ELSE
        PERFORM 1 FROM public.inventory_pools WHERE id=v_pool_id AND occasion=v_occasion_id FOR UPDATE;
        IF NOT FOUND THEN RAISE EXCEPTION 'Inventory pool scope mismatch'; END IF;
        PERFORM 1 FROM public.inventory_contexts WHERE inventory_pool=v_pool_id ORDER BY id FOR UPDATE;
        IF (v_pool_data->>'sellable_capacity')::bigint < (SELECT count(*) FROM eshop.spots s JOIN public.inventory_contexts ic ON ic.id=s.inventory_context
          WHERE ic.inventory_pool=v_pool_id AND (s.order_product_ticket IS NOT NULL OR (s.secret IS NOT NULL AND s.secret_expiration_time>clock_timestamp()))) THEN
          RAISE EXCEPTION 'INVENTORY_CAPACITY_BELOW_COMMITTED'; END IF;
        -- Update the existing pool
        UPDATE public.inventory_pools
        SET
            title = v_pool_data->>'title',
            sellable_capacity = (v_pool_data->>'sellable_capacity')::bigint,
            description = v_pool_data->>'description',
            type = v_pool_data->>'type',
            data = v_pool_data->'data',
            updated_at = now()
        WHERE id = v_pool_id;
    END IF;

    -- NOTE: Resource and Slot management logic has been removed as requested.

    -- 2. Upsert/Delete Inventory Contexts
    IF jsonb_typeof(p_bundle_data->'contexts') = 'array' THEN
        FOR v_context_data IN SELECT * FROM jsonb_array_elements(p_bundle_data->'contexts')
        LOOP
            v_context_id := (v_context_data->>'id')::bigint;
            IF v_context_id IS NULL THEN
                -- Create new context, now including the 'data' field
                INSERT INTO public.inventory_contexts (inventory_pool, block_date, title, "order", data)
                VALUES (v_pool_id, (v_context_data->>'block_date')::date, v_context_data->>'title', (v_context_data->>'order')::bigint, v_context_data->'data')
                RETURNING id INTO v_context_id;
            ELSE
                -- Update existing context, now including the 'data' field
                UPDATE public.inventory_contexts
                SET
                    block_date = (v_context_data->>'block_date')::date,
                    title = v_context_data->>'title',
                    "order" = (v_context_data->>'order')::bigint,
                    data = v_context_data->'data' -- Added this line
                WHERE id = v_context_id;
            END IF;
            v_context_ids_from_input := array_append(v_context_ids_from_input, v_context_id);
        END LOOP;
        -- Deleting a context must not detach a sold or currently held spot.
        PERFORM 1 FROM eshop.spots WHERE inventory_context IN (SELECT id FROM public.inventory_contexts
          WHERE inventory_pool=v_pool_id AND id<>ALL(v_context_ids_from_input)) ORDER BY id FOR UPDATE;
        IF EXISTS(SELECT 1 FROM eshop.spots WHERE inventory_context IN (SELECT id FROM public.inventory_contexts
          WHERE inventory_pool=v_pool_id AND id<>ALL(v_context_ids_from_input))
          AND (order_product_ticket IS NOT NULL OR (secret IS NOT NULL AND secret_expiration_time>clock_timestamp()))) THEN
          RAISE check_violation USING MESSAGE='INVENTORY_CONTEXT_IN_USE'; END IF;
        -- Delete contexts that were removed in the UI for this pool
        DELETE FROM public.inventory_contexts WHERE inventory_pool = v_pool_id AND id <> ALL(v_context_ids_from_input);
    END IF;

    -- 3. Create or delete spots for the inventory pool based on its resources and contexts.
    -- The function is executed, and its integer return value is discarded.
    PERFORM adjust_spot_capacity_for_pool(v_pool_id);

    -- Return the fully updated bundle by calling the get function
    RETURN get_inventory_pool_bundle(v_pool_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.update_inventory_pool_bundle(p_bundle_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_id bigint:=(p_bundle_data#>>'{pool,id}')::bigint; oc bigint; v bigint; result jsonb; bundle jsonb:=p_bundle_data;
BEGIN
 oc:=(bundle#>>'{pool,occasion}')::bigint;
 IF v_id IS NOT NULL THEN SELECT occasion INTO oc FROM public.inventory_pools WHERE inventory_pools.id=v_id; END IF;
 PERFORM public.check_is_editor_order_on_occasion(oc);
 IF v_id IS NOT NULL THEN
 PERFORM public.lock_pool_product_dependencies_internal_v1(v_id);
  PERFORM 1 FROM public.inventory_pools WHERE inventory_pools.id=v_id FOR UPDATE;
  SELECT coalesce((SELECT version FROM public.client_aggregate_versions WHERE aggregate_type='inventory_pool'
   AND scope_type='occasion' AND scope_id=oc AND aggregate_id=v_id::text),0) INTO v;
  IF NOT bundle ? 'contexts' THEN bundle:=bundle||jsonb_build_object('contexts',public.get_inventory_pool_bundle(v_id)->'contexts'); END IF;
 END IF;
 result:=public.save_inventory_pool_client_sync_v1(oc,extensions.gen_random_uuid(),v,bundle);
 IF result->>'code'<>'200' THEN RAISE serialization_failure USING MESSAGE='inventory pool save rejected'; END IF;
 RETURN result#>'{data,bundle}';
END $function$

CREATE OR REPLACE FUNCTION public.update_occasion_203(input_data jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE result jsonb;
BEGIN
 result:=public.save_occasion_legacy_facade_internal_v1(input_data);
 IF result->>'status'='conflict' THEN RAISE serialization_failure USING MESSAGE='occasion changed'; END IF;
 IF result->>'status'='rejected' THEN RAISE invalid_parameter_value USING MESSAGE='occasion save rejected'; END IF;
