CREATE OR REPLACE FUNCTION public.update_order_and_tickets_to_storno_with_security(order_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
    occasion_id bigint;
BEGIN
    -- Retrieve the occasion associated with the order
