CREATE OR REPLACE FUNCTION public.update_order_and_tickets_to_storno_ws_internal_v1(order_id bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
    occasion_id bigint;
BEGIN
    PERFORM public.lock_blueprint_scope_internal(ARRAY[(SELECT occasion FROM eshop.orders WHERE id=order_id)]);
    -- Retrieve the occasion associated with the order
    SELECT occasion INTO occasion_id FROM eshop.orders WHERE id = order_id;

    -- Check if the order exists and has an associated occasion
    IF occasion_id IS NULL THEN
        RAISE EXCEPTION 'Order not found or no associated occasion.';
    END IF;

    -- Verify if the user is an editor on the occasion
    IF (SELECT get_is_editor_order_on_occasion(occasion_id)) <> TRUE THEN
        RAISE EXCEPTION 'User is not editor.';
    END IF;

    PERFORM public.lock_order_capacity_scope_internal(ARRAY[order_id]);
    -- Use the same parent lock order as ticket cancellation.
    PERFORM 1 FROM eshop.orders WHERE id=order_id FOR UPDATE;

    -- Call the original function to update the order and tickets
    PERFORM update_order_and_tickets_to_storno_221(order_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.update_order_note_hidden(order_id bigint, new_note_hidden text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
    DECLARE
        occasion_id bigint;
    BEGIN
        -- Retrieve the occasion_id from the order
        SELECT occasion INTO occasion_id FROM eshop.orders WHERE id = order_id;

        -- Check if occasion_id was successfully retrieved
        IF occasion_id IS NULL THEN
            RETURN jsonb_build_object('code', 404, 'message', 'Order not found or occasion not specified');
        END IF;

        -- Check if the user has the right to edit the given occasion
        IF (get_is_editor_order_on_occasion(occasion_id)) <> TRUE THEN
            -- Return an error if the user is not authorized
            RETURN jsonb_build_object('code', 403, 'message', 'User is not authorized to edit this occasion');
        END IF;

        PERFORM public.lock_order_capacity_scope_internal(ARRAY[order_id]);
        IF (SELECT state FROM eshop.orders WHERE id=order_id)<>'waitlisted' THEN
          PERFORM public.check_order_is_mutable(order_id);
        END IF;

        -- Proceed to update note_hidden if the user is authorized
        UPDATE eshop.orders
        SET note_hidden = new_note_hidden, updated_at = now()
        WHERE id = order_id;

        -- Check if the update was successful
        IF FOUND THEN
            RETURN jsonb_build_object('code', 200, 'message', 'Update successful');
        ELSE
            RETURN jsonb_build_object('code', 404, 'message', 'Order not found');
        END IF;
    END;
    $function$

CREATE OR REPLACE FUNCTION public.update_order_responses(p_order_id bigint, responses jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
    v_occasion_id BIGINT;
    v_order_form_id BIGINT;
    v_current_state text;
    v_current_data JSONB;
    v_new_data JSONB;
    v_field_definitions JSONB;
    v_current_fields_map JSONB;
    v_merged_fields_map JSONB;
    v_new_fields_array JSONB;

    v_field_id_text TEXT;
    v_field_type TEXT;
    v_new_value JSONB;

    v_updated_order_state TEXT;
    v_updated_order_price NUMERIC(10, 2);
    v_updated_order_data JSONB;
BEGIN
    -- Fetch the order's current data, occasion, and form ID
    SELECT
        o.data,
        o.occasion,
        o.form,
        o.state
    INTO
        v_current_data,
        v_occasion_id,
        v_order_form_id,
        v_current_state
    FROM eshop.orders o
    WHERE o.id = p_order_id;

    -- Raise an exception if the SELECT INTO returned no row
    IF v_occasion_id IS NULL THEN
        RAISE EXCEPTION 'Order not found: %', p_order_id;
    END IF;

    -- Check if the current user has order editing permissions for this occasion
    IF (SELECT get_is_editor_order_on_occasion(v_occasion_id)) <> TRUE THEN
        RAISE EXCEPTION 'User does not have permission to edit this order.';
    END IF;

    -- Reject the terminal state before form validation, without reversing
    -- the form -> order lock order used by form-field removal.
    IF v_current_state='storno' THEN
        RAISE EXCEPTION 'ORDER_CANCELLED: Cancelled orders are read-only' USING ERRCODE='55000';
    END IF;

    -- Raise an exception if the order is not linked to a form
    IF v_order_form_id IS NULL THEN
        RAISE EXCEPTION 'Order % has no associated form.', p_order_id;
    END IF;

    -- Coordinate response validation/writes with form saves and field removal.
    PERFORM 1 FROM public.forms WHERE id = v_order_form_id FOR SHARE;
    PERFORM public.check_order_is_mutable(p_order_id);
    SELECT data INTO v_current_data FROM eshop.orders WHERE id=p_order_id;

    -- Fetch all field definitions for this form into a JSONB map { "field_id": "field_type" }
    SELECT jsonb_object_agg(ff.id::text, ff.type)
    INTO v_field_definitions
    FROM public.form_fields ff
    WHERE ff.form = v_order_form_id;

    -- Raise an exception if the form has no fields
    IF v_field_definitions IS NULL THEN
        RAISE EXCEPTION 'No form fields found for form %', v_order_form_id;
    END IF;

    -- FIX: Use a LATERAL join to explicitly reference the columns from jsonb_each,
    -- resolving the "ambiguous column 'value'" error.
    SELECT jsonb_object_agg(je.key, je.value)
    INTO v_current_fields_map
    FROM jsonb_array_elements(v_current_data -> 'fields') AS jae(field_object),
         LATERAL jsonb_each(jae.field_object) AS je(key, value);

    -- Start with the current order data
    v_new_data := v_current_data;

    -- Merge the existing fields map with the new responses. New responses overwrite old ones.
    v_merged_fields_map := COALESCE(v_current_fields_map, '{}'::jsonb) || responses;

    -- Iterate through only the *incoming* responses to handle updates and nulls
    FOR v_field_id_text, v_new_value IN SELECT * FROM jsonb_each(responses)
    LOOP
        -- Get the type of the field being updated
        v_field_type := v_field_definitions ->> v_field_id_text;

        -- Validate that the field ID exists on this order's form
        IF v_field_type IS NULL THEN
            RAISE EXCEPTION 'Field ID % not found on form %', v_field_id_text, v_order_form_id;
        END IF;

        -- Handle null values: remove the key from the top level and from the merged map
        IF v_new_value IS NULL OR v_new_value = 'null'::jsonb THEN

            -- Remove from the map that will build the 'fields' array
            v_merged_fields_map := v_merged_fields_map - v_field_id_text;

            -- Remove top-level duplicated fields
            IF v_field_type = 'name' THEN
                v_new_data := v_new_data - 'name';
            ELSIF v_field_type = 'surname' THEN
                v_new_data := v_new_data - 'surname';
            ELSIF v_field_type = 'email' THEN
                v_new_data := v_new_data - 'email';
            ELSIF v_field_type = 'phone' THEN
                v_new_data := v_new_data - 'phone';
            END IF;

        -- Handle non-null values: update the top-level keys
        ELSE

            -- Update top-level duplicated fields
            IF v_field_type = 'name' THEN
                v_new_data := v_new_data || jsonb_build_object('name', v_new_value);
            ELSIF v_field_type = 'surname' THEN
                v_new_data := v_new_data || jsonb_build_object('surname', v_new_value);
            ELSIF v_field_type = 'email' THEN
                v_new_data := v_new_data || jsonb_build_object('email', v_new_value);
            ELSIF v_field_type = 'phone' THEN
                v_new_data := v_new_data || jsonb_build_object('phone', v_new_value);
            END IF;

        END IF;
    END LOOP;

    -- Rebuild the 'fields' array from the (now null-stripped) merged map
    -- It converts { "id": "val" } back to [ {"id": "val"} ]
    SELECT jsonb_agg(jsonb_build_object(key, value))
    INTO v_new_fields_array
    FROM jsonb_each(v_merged_fields_map);

    -- Set the new 'fields' array in the main data object
    v_new_data := jsonb_set(
        v_new_data,
        '{fields}',
        COALESCE(v_new_fields_array, '[]'::jsonb)
    );

    -- Update the order in the database
    UPDATE eshop.orders
    SET
        data = v_new_data,
        updated_at = NOW()
    WHERE
        id = p_order_id
    RETURNING
        state, price, data
    INTO
        v_updated_order_state, v_updated_order_price, v_updated_order_data;

    -- Save the change to the orders_history table
    INSERT INTO eshop.orders_history (
        "order",
        state,
        price,
        data,
        created_at
    )
    VALUES (
        p_order_id,
        v_updated_order_state,
        v_updated_order_price,
        v_updated_order_data,
        NOW()
    );

END;
$function$

CREATE OR REPLACE FUNCTION public.update_product_client_sync_v1(p_product jsonb, p_command_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_product bigint; v_occasion bigint;
  v_begin jsonb; v_hash text; v_users uuid[]; v_version bigint; v_expected bigint;
BEGIN
  IF p_product IS NULL OR jsonb_typeof(p_product)<>'object'
    OR octet_length(p_product::text)>524288 THEN
    RAISE invalid_parameter_value USING MESSAGE='invalid product aggregate'; END IF;
  v_product:=NULLIF(p_product->>'id','')::bigint;
  SELECT occasion INTO v_occasion FROM public.client_mutation_receipts WHERE command_id=p_command_id AND actor_id=v_actor AND command_name='inventory.product.save';
  IF NOT FOUND THEN
  IF v_product IS NOT NULL THEN
    SELECT p.occasion INTO v_occasion FROM eshop.products p WHERE p.id=v_product;
  ELSE
    SELECT pt.occasion INTO v_occasion FROM eshop.product_types pt
      WHERE pt.id=NULLIF(p_product->>'product_type','')::bigint;
  END IF;
  END IF;
  IF v_actor IS NULL OR v_occasion IS NULL
    OR NOT public.get_is_editor_order_on_occasion(v_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='order editor required'; END IF;
  IF jsonb_typeof(p_product->'inventory_contexts')='array' THEN
    p_product:=jsonb_set(p_product,'{inventory_contexts}',coalesce((SELECT jsonb_agg(c ORDER BY (c->>'inventory_context_id')::bigint)
      FROM jsonb_array_elements(p_product->'inventory_contexts') c),'[]')); END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'occasion',v_occasion,'product',p_product)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,
    'inventory.product.save',v_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  IF v_product IS NOT NULL THEN
    SELECT COALESCE(array_agg(DISTINCT ou."user"),'{}'::uuid[]) INTO v_users
    FROM eshop.order_product_ticket opt JOIN public.occasion_users ou
      ON ou.ticket=opt.ticket AND ou.occasion=v_occasion
    WHERE opt.product=v_product;
  ELSE v_users:='{}'::uuid[]; END IF;
  -- Context replacement recalculates allocations: acquire the same outer order
  -- parents before saving a product, never product then order in this command.
  PERFORM public.lock_product_order_dependencies_internal_v1(v_product);
  IF v_product IS NOT NULL THEN
    PERFORM 1 FROM eshop.products WHERE id=v_product AND occasion=v_occasion FOR UPDATE;
    SELECT coalesce(v.version,0) INTO v_version FROM (SELECT 1) seed
    LEFT JOIN public.client_aggregate_versions v ON v.aggregate_type='product'
    AND v.scope_type='occasion' AND v.scope_id=v_occasion AND v.aggregate_id=v_product::text;
    -- Released scalar facades may omit this control until their explicit upgrade gate.
    v_expected:=CASE WHEN p_product ? 'expected_aggregate_version'
      THEN (p_product->>'expected_aggregate_version')::bigint ELSE v_version END;
    IF v_expected IS DISTINCT FROM v_version THEN
      RETURN public.complete_client_mutation_outcome_v1(p_command_id,'conflict',409,
        jsonb_build_object('productId',v_product,'aggregate_version',v_version)); END IF;
  ELSIF p_product->>'expected_aggregate_version' IS NOT NULL THEN
    RAISE invalid_parameter_value USING MESSAGE='new product cannot have expected version';
  END IF;
  v_product:=public.update_product_internal_v1(p_product-'expected_aggregate_version');
  SELECT version INTO v_version FROM public.client_aggregate_versions WHERE aggregate_type='product'
    AND scope_type='occasion' AND scope_id=v_occasion AND aggregate_id=v_product::text;
  RETURN public.complete_private_inventory_mutation_v1(p_command_id,v_occasion,
    'inventory.product.save',jsonb_build_array(jsonb_build_object(
      'entityType','product','entityId',v_product,'operation',
      CASE WHEN p_product->>'id' IS NULL THEN 'insert' ELSE 'update' END,
      'safeLabel',left(p_product->>'title',240),'changedFields',jsonb_build_array(
        'configuration','contexts'))),v_users,jsonb_build_object('productId',v_product,'aggregate_version',v_version));
END; $function$

CREATE OR REPLACE FUNCTION public.update_product_internal_v1(p_input jsonb)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_product_id BIGINT;
  v_occasion_id BIGINT;
  v_product_type_id BIGINT;
  v_existing_price NUMERIC;
  v_input_price NUMERIC;
  v_effective_price NUMERIC;
  v_input_deposit NUMERIC;
BEGIN
  -- Extract product id from the input JSON
  v_product_id := (p_input->>'id')::BIGINT;

  -- Try to find the product to determine if we are updating or creating.
  -- This also gets the *current* occasion for the permission check on UPDATE.
  IF v_product_id IS NOT NULL THEN
    SELECT pt.occasion, p.price
    INTO v_occasion_id, v_existing_price
    FROM eshop.products p
    JOIN eshop.product_types pt ON p.product_type = pt.id
    WHERE p.id = v_product_id FOR UPDATE OF p;
  END IF;

  -- CASE 1: Product was found (v_product_id was not null and existed)
  IF FOUND THEN
    -- We are UPDATING.

    -- Ensure the caller has permission to edit this product's *current* occasion.
    -- This function is expected to raise an exception on failure.
    PERFORM public.check_is_editor_order_on_occasion(v_occasion_id);

    -- VALIDATION: deposit amount must be less than effective price (input price overrides existing)
    v_input_price := NULLIF(p_input->>'price', '')::NUMERIC;
    v_effective_price := COALESCE(v_input_price, v_existing_price);
    v_input_deposit := NULLIF(p_input->'data'->'deposit'->>'amount', '')::NUMERIC;
    IF v_input_deposit IS NOT NULL AND v_input_deposit > 0
       AND v_effective_price IS NOT NULL AND v_input_deposit >= v_effective_price THEN
      RAISE EXCEPTION '%', jsonb_build_object(
          'code', 'DEPOSIT_AMOUNT_TOO_HIGH',
          'message', 'Deposit amount (' || v_input_deposit || ') must be less than price (' || v_effective_price || ').'
      )::text;
    END IF;

    PERFORM public.validate_product_price_update(v_product_id,v_effective_price,
      COALESCE(p_input->'data',(SELECT data FROM eshop.products WHERE id=v_product_id)),
      COALESCE(p_input->>'currency_code',(SELECT currency_code FROM eshop.products WHERE id=v_product_id)));
    -- A product with schedules cannot silently move to another occasion/type.
    IF EXISTS (SELECT 1 FROM eshop.planned_changes WHERE subject_id=v_product_id
      AND change_type IN('products.price','products.is_hidden') AND NOT applied) AND (
      NULLIF(p_input->>'occasion','')::bigint IS DISTINCT FROM v_occasion_id AND p_input->>'occasion' IS NOT NULL
      OR NULLIF(p_input->>'product_type','')::bigint IS DISTINCT FROM
        (SELECT product_type FROM eshop.products WHERE id=v_product_id) AND p_input->>'product_type' IS NOT NULL
    ) THEN RAISE EXCEPTION 'CANCEL_PRICE_CHANGES_BEFORE_PRODUCT_MOVE'; END IF;

    IF p_input->>'product_type' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM eshop.product_types WHERE id=(p_input->>'product_type')::bigint AND occasion=v_occasion_id) THEN RAISE EXCEPTION 'Product type occasion mismatch'; END IF;
    IF p_input->>'occasion' IS NOT NULL AND (p_input->>'occasion')::bigint<>v_occasion_id THEN RAISE EXCEPTION 'Product occasion cannot change'; END IF;
    -- Update only the fields that are provided in the input JSON.
    -- COALESCE is used to keep the existing value if a new one isn't provided.
    -- NULLIF is added to safely handle empty strings '' during casting.
    PERFORM 1 FROM public.occasions WHERE id=v_occasion_id FOR UPDATE;
    IF p_input ? 'product_type' AND NULLIF(p_input->>'product_type','')::bigint IS DISTINCT FROM (SELECT product_type FROM eshop.products WHERE id=v_product_id)
      AND EXISTS(SELECT 1 FROM eshop.order_product_ticket WHERE product=v_product_id)
    THEN RAISE EXCEPTION 'Purchased product type cannot change'; END IF;
    IF nullif(p_input->>'maximum','')::integer>0 AND
      nullif(p_input->>'maximum','')::integer<(SELECT count(*) FROM eshop.order_product_ticket WHERE product=v_product_id) THEN
      RAISE EXCEPTION 'PRODUCT_CAPACITY_BELOW_COMMITTED'; END IF;
    UPDATE eshop.products p
    SET
      occasion      = COALESCE(NULLIF(p_input->>'occasion', '')::BIGINT, p.occasion),
      title         = COALESCE(p_input->>'title',         p.title),
      description   = COALESCE(p_input->>'description',   p.description),
      price         = COALESCE(NULLIF(p_input->>'price', '')::NUMERIC, p.price),
      currency_code = COALESCE(p_input->>'currency_code', p.currency_code),
      data          = COALESCE(p_input->'data',           p.data),
      product_type  = COALESCE(NULLIF(p_input->>'product_type', '')::BIGINT, p.product_type),
      "order"       = COALESCE(NULLIF(p_input->>'order', '')::INT,  p."order"),
      maximum       = COALESCE(NULLIF(p_input->>'maximum', '')::INT, p.maximum),
      is_hidden     = COALESCE(NULLIF(p_input->>'is_hidden', '')::BOOLEAN, p.is_hidden),
      updated_at    = NOW()
    WHERE p.id = v_product_id;

    -- Return the ID of the updated product on success.
    IF p_input ? 'inventory_contexts' THEN
      PERFORM public.update_product_inventory_contexts_internal_v1(v_product_id,p_input->'inventory_contexts');
    END IF;
    IF NOT (p_input ? 'inventory_contexts') THEN
      PERFORM public.advance_ticketing_authoring_version_internal_v1('product',v_occasion_id,v_product_id);
    END IF;
    RETURN v_product_id;

  -- CASE 2: Product was NOT found (v_product_id was NULL or was an ID that doesn't exist)
  ELSE
    -- We are CREATING, as per the request.

    -- 1. Get the product_type from the JSON.
    v_product_type_id := (p_input->>'product_type')::BIGINT;

    -- 2. Validate product_type is provided (it's required for creation).
    IF v_product_type_id IS NULL THEN
      RAISE EXCEPTION '%', jsonb_build_object(
          'code', 'PRD422',
          'message', 'Field "product_type" is required when creating a new product.'
      )::text;
    END IF;

    -- 3. Find the occasion for the *new* product_type to check permissions.
    SELECT occasion
    INTO v_occasion_id
    FROM eshop.product_types
    WHERE id = v_product_type_id;

    -- 4. Handle invalid product_type.
    IF NOT FOUND THEN
      RAISE EXCEPTION '%', jsonb_build_object(
          'code', 'PTY404',
          'message', 'Product type with ID ' || v_product_type_id || ' not found.'
      )::text;
    END IF;

    -- 5. Ensure the caller has permission to create a product on this occasion.
    PERFORM public.check_is_editor_order_on_occasion(v_occasion_id);

    -- 6. VALIDATION: deposit amount must be less than price (both from input on CREATE)
    v_input_price := NULLIF(p_input->>'price', '')::NUMERIC;
    v_input_deposit := NULLIF(p_input->'data'->'deposit'->>'amount', '')::NUMERIC;
    IF v_input_deposit IS NOT NULL AND v_input_deposit > 0
       AND v_input_price IS NOT NULL AND v_input_deposit >= v_input_price THEN
      RAISE EXCEPTION '%', jsonb_build_object(
          'code', 'DEPOSIT_AMOUNT_TOO_HIGH',
          'message', 'Deposit amount (' || v_input_deposit || ') must be less than price (' || v_input_price || ').'
      )::text;
    END IF;

    PERFORM public.validate_product_price(v_input_price,p_input->'data',p_input->>'currency_code');

    -- 7. Insert the new product.
    -- We ignore the `id` from the JSON (v_product_id) and let the sequence generate a new one.
    -- We use NULLIF to safely cast potentially empty strings.
    INSERT INTO eshop.products (
      occasion,
      title,
      description,
      price,
      currency_code,
      data,
      product_type,
      "order",
      maximum,
      is_hidden
      -- created_at and updated_at are assumed to have defaults (e.g., NOW())
    )
    VALUES (
      v_occasion_id,
      p_input->>'title',
      p_input->>'description',
      NULLIF(p_input->>'price', '')::NUMERIC,
      p_input->>'currency_code',
      p_input->'data',
      v_product_type_id, -- We already extracted and validated this
      NULLIF(p_input->>'order', '')::INT,
      NULLIF(p_input->>'maximum', '')::INT,
      -- Default to 'false' if is_hidden is not provided on create
      COALESCE(NULLIF(p_input->>'is_hidden', '')::BOOLEAN, false)
    )
    RETURNING id INTO v_product_id; -- Get the newly created ID

    -- Return the ID of the newly created product.
    IF p_input ? 'inventory_contexts' THEN
      PERFORM public.update_product_inventory_contexts_internal_v1(v_product_id,p_input->'inventory_contexts');
    END IF;
    IF NOT (p_input ? 'inventory_contexts') THEN
      PERFORM public.advance_ticketing_authoring_version_internal_v1('product',v_occasion_id,v_product_id);
    END IF;
    RETURN v_product_id;

  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.update_product_inventory_contexts_client_sync_v1(p_product_id bigint, p_contexts jsonb, p_command_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_occasion bigint; v_begin jsonb; v_hash text;
  v_users uuid[]; v_expected bigint; v_version bigint; v_versioned boolean:=false;
BEGIN
  IF jsonb_typeof(p_contexts)='object' THEN
    IF jsonb_typeof(p_contexts->'contexts') IS DISTINCT FROM 'array'
      OR NOT p_contexts ? 'expected_aggregate_version'
      OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_contexts) k WHERE k NOT IN ('contexts','expected_aggregate_version')) THEN
      RAISE invalid_parameter_value USING MESSAGE='invalid context revision envelope'; END IF;
    v_versioned:=true;v_expected:=(p_contexts->>'expected_aggregate_version')::bigint;
    p_contexts:=p_contexts->'contexts';
  END IF;
  SELECT occasion INTO v_occasion FROM public.client_mutation_receipts WHERE command_id=p_command_id AND actor_id=v_actor AND command_name='inventory.product.contexts';
  IF NOT FOUND THEN
  SELECT p.occasion INTO v_occasion FROM eshop.products p WHERE p.id=p_product_id;
  END IF;
  IF v_actor IS NULL OR v_occasion IS NULL OR p_contexts IS NULL
    OR jsonb_typeof(p_contexts)<>'array' OR jsonb_array_length(p_contexts)>1000
    OR octet_length(p_contexts::text)>1048576
    OR NOT public.get_is_editor_order_on_occasion(v_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='inventory editor required'; END IF;
  SELECT coalesce(jsonb_agg(c ORDER BY (c->>'inventory_context_id')::bigint),'[]') INTO p_contexts FROM jsonb_array_elements(p_contexts) c;
  v_hash:=encode(extensions.digest(convert_to((jsonb_build_object(
    'productId',p_product_id,'contexts',p_contexts) || CASE WHEN v_versioned THEN jsonb_build_object('expectedVersion',v_expected) ELSE '{}'::jsonb END)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,
    'inventory.product.contexts',v_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  IF EXISTS (SELECT 1 FROM jsonb_array_elements(p_contexts) c
      LEFT JOIN public.inventory_contexts ic
        ON ic.id=(c->>'inventory_context_id')::bigint
      LEFT JOIN public.inventory_pools ip ON ip.id=ic.inventory_pool
      WHERE ip.occasion IS DISTINCT FROM v_occasion
        OR COALESCE((c->>'quantity')::integer,0)<0)
 THEN RAISE insufficient_privilege USING MESSAGE='foreign inventory context'; END IF;

  SELECT COALESCE(array_agg(DISTINCT ou."user"),'{}'::uuid[]) INTO v_users
  FROM eshop.order_product_ticket opt JOIN public.occasion_users ou
    ON ou.ticket=opt.ticket AND ou.occasion=v_occasion
  WHERE opt.product=p_product_id;
  PERFORM public.lock_product_order_dependencies_internal_v1(p_product_id);
  PERFORM 1 FROM eshop.products WHERE id=p_product_id AND occasion=v_occasion FOR UPDATE;
  SELECT coalesce(v.version,0) INTO v_version FROM (SELECT 1) seed LEFT JOIN public.client_aggregate_versions v
    ON v.aggregate_type='product' AND v.scope_type='occasion' AND v.scope_id=v_occasion AND v.aggregate_id=p_product_id::text;
  IF v_versioned AND v_expected IS DISTINCT FROM v_version THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'conflict',409,
      jsonb_build_object('productId',p_product_id,'aggregate_version',v_version)); END IF;
  PERFORM public.update_product_inventory_contexts_internal_v1(
    p_product_id,p_contexts);
  RETURN public.complete_private_inventory_mutation_v1(p_command_id,v_occasion,
    'inventory.product.contexts',jsonb_build_array(jsonb_build_object(
      'entityType','product_inventory_context','entityId',p_product_id,
      'operation','update','safeLabel','Product inventory contexts',
      'changedFields',jsonb_build_array('contexts'))),v_users,
    jsonb_build_object('productId',p_product_id,'aggregate_version',v_version+1));
END; $function$

CREATE OR REPLACE FUNCTION public.update_resource(p_input jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_id bigint:=(p_input->>'id')::bigint; pool bigint:=(p_input->>'inventory_pool')::bigint; oc bigint; v bigint; current_row jsonb:='{}'; normalized jsonb; result jsonb;
BEGIN
 SELECT occasion INTO oc FROM public.inventory_pools WHERE inventory_pools.id=pool;
 PERFORM public.check_is_editor_order_on_occasion(oc);
 PERFORM public.lock_resource_pools_internal_v1(v_id,pool);
 IF v_id IS NOT NULL THEN
  SELECT to_jsonb(r) INTO current_row FROM public.resources r WHERE r.id=v_id AND r.occasion=oc FOR UPDATE;
  IF current_row IS NULL THEN RAISE invalid_parameter_value USING MESSAGE='resource unavailable'; END IF;
  SELECT coalesce((SELECT version FROM public.client_aggregate_versions WHERE aggregate_type='resource' AND scope_type='occasion' AND scope_id=oc AND aggregate_id=v_id::text),0) INTO v;
 END IF;
 normalized:=coalesce(current_row,'{}')||p_input;
 SELECT jsonb_object_agg(key,value) INTO normalized FROM jsonb_each(normalized)
 WHERE key IN ('id','title','capacity','booking_rules','inventory_pool');
 result:=public.save_resource_client_sync_v1(oc,extensions.gen_random_uuid(),v,normalized);
 IF result->>'code'<>'200' THEN RAISE serialization_failure USING MESSAGE='resource save rejected'; END IF;
END $function$

CREATE OR REPLACE FUNCTION public.update_scan_code(occasion_link text, new_scan_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
    v_occasion_id BIGINT;
    occasions_hidden_id BIGINT;
BEGIN
    -- 1. Retrieve occasion_id using occasion_link
    SELECT id
    INTO v_occasion_id
    FROM public.occasions
    WHERE id = public.resolve_occasion_link_internal(occasion_link);

    -- 2. Check if occasion_link is valid
    IF v_occasion_id IS NULL THEN
        RETURN jsonb_build_object(
            'code', 404,
            'message', 'Occasion link does not exist.'
        );
    END IF;

    -- 3. Verify if the user is an editor on the occasion
    IF NOT get_is_editor_order_on_occasion(v_occasion_id) THEN
        RETURN jsonb_build_object(
            'code', 403,
            'message', 'User is not authorized to edit this occasion.'
        );
    END IF;

    PERFORM 1 FROM public.scanner_settings WHERE scanner_settings.occasion_id=v_occasion_id FOR UPDATE;
    UPDATE public.scanner_settings SET epoch=epoch+1 WHERE scanner_settings.occasion_id=v_occasion_id;
    -- 4. Check if occasions_hidden exists for the occasion
    SELECT o.occasion_hidden
    INTO occasions_hidden_id
    FROM public.occasions o
    WHERE o.id = v_occasion_id;

    IF occasions_hidden_id IS NOT NULL THEN
        -- Update existing scan_code
        UPDATE public.occasions_hidden
        SET secret = new_scan_code
        WHERE id = occasions_hidden_id;
    ELSE
        -- Insert new occasions_hidden record
        INSERT INTO public.occasions_hidden (secret)
        VALUES (new_scan_code)
        RETURNING id INTO occasions_hidden_id;

        -- Update the occasion to link to the new occasions_hidden
        UPDATE public.occasions
        SET occasion_hidden = occasions_hidden_id
        WHERE id = v_occasion_id;
    END IF;

    -- 5. Return a success message
    RETURN jsonb_build_object(
        'code', 200,
        'message', 'Scan code updated successfully.'
    );

EXCEPTION
    WHEN OTHERS THEN
        -- Handle any unexpected exceptions
        RETURN jsonb_build_object(
            'code', 500,
            'message', 'An unexpected error occurred.',
            'detail', SQLERRM
        );
END;
$function$

CREATE OR REPLACE FUNCTION public.update_scanner_settings(p_occasion bigint, p_expected_revision bigint, p_config jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE s public.scanner_settings;
BEGIN
 PERFORM public.scanner_require_settings_editor_internal(p_occasion); PERFORM public.check_occasion_writable(p_occasion);
 PERFORM public.scanner_validate_settings_internal(p_occasion,p_config);
 SELECT * INTO s FROM public.scanner_settings WHERE occasion_id=p_occasion FOR UPDATE;
 IF NOT FOUND OR s.revision IS DISTINCT FROM p_expected_revision THEN RETURN jsonb_build_object('code',409,'reason','settings_changed','server_time',now()); END IF;
 UPDATE public.scanner_settings SET config=p_config,revision=revision+1,
 epoch=epoch+CASE WHEN (config-'fields'-'products') IS DISTINCT FROM (p_config-'fields'-'products') OR config->'products' IS DISTINCT FROM p_config->'products'
 OR (SELECT coalesce(jsonb_agg(f-'label'-'default_visible'-'hide_empty' ORDER BY f->>'key'),'[]'::jsonb) FROM jsonb_array_elements(config->'fields') f)
 IS DISTINCT FROM (SELECT coalesce(jsonb_agg(f-'label'-'default_visible'-'hide_empty' ORDER BY f->>'key'),'[]'::jsonb) FROM jsonb_array_elements(p_config->'fields') f) THEN 1 ELSE 0 END,
 updated_at=now(),updated_by=auth.uid() WHERE occasion_id=p_occasion;
 RETURN public.get_scanner_settings(p_occasion);
END $function$

CREATE OR REPLACE FUNCTION public.update_service_item_client_sync_v1(p_occasion bigint, p_type text, p_code text, p_title text, p_reference bigint, p_command_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_begin jsonb; v_hash text; v_result jsonb;
  v_before jsonb; v_after jsonb;
BEGIN
  IF v_actor IS NULL OR p_type NOT IN ('food','accommodation')
    OR nullif(btrim(p_code),'') IS NULL OR length(p_code)>100
    OR length(COALESCE(p_title,''))>500
    OR NOT public.get_is_manager_on_occasion(p_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='occasion manager required'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'occasion',p_occasion,'type',p_type,'code',p_code,'title',p_title,
    'reference',p_reference)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,
    'occasion.service.update',p_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  SELECT o.services INTO v_before FROM public.occasions o
    WHERE o.id=p_occasion FOR UPDATE;
  v_result:=public.update_service_item_internal_v1(
    p_occasion,p_type,p_code,p_title,p_reference);
  IF COALESCE((v_result->>'code')::integer,500)<>200 THEN
    RETURN public.complete_client_mutation_outcome_v1(p_command_id,'rejected',
      404,v_result); END IF;
  SELECT o.services INTO v_after FROM public.occasions o WHERE o.id=p_occasion;
  IF v_before IS NOT DISTINCT FROM v_after THEN
    RETURN public.complete_client_mutation_outcome_v1(
      p_command_id,'unchanged',200,v_result); END IF;
  INSERT INTO public.client_aggregate_versions(aggregate_type,scope_type,scope_id,aggregate_id,version)
  VALUES('occasion','occasion',p_occasion,p_occasion::text,1)
  ON CONFLICT(aggregate_type,scope_type,scope_id,aggregate_id) DO UPDATE
  SET version=public.client_aggregate_versions.version+1,updated_at=clock_timestamp();
  RETURN public.complete_client_mutation_applied_v1(p_command_id,p_occasion,
    'occasion.service.update','configuration',jsonb_build_array(jsonb_build_object(
      'entityType','occasion_service','entityId',p_code,'operation','update',
      'safeLabel',left(p_title,240),'changedFields',jsonb_build_array('services'))),
    ARRAY['occasion_config'],'[]','[]',v_result);
END; $function$

CREATE OR REPLACE FUNCTION public.update_speaker(p_occasion bigint, p_speaker jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_id bigint:=(p_speaker->>'id')::bigint; v_version bigint; v_payload jsonb; r jsonb;
BEGIN
 IF auth.uid() IS NULL OR NOT public.get_is_editor_on_occasion(p_occasion) THEN
  RETURN jsonb_build_object('code',403); END IF;
 IF v_id IS NOT NULL THEN
  PERFORM 1 FROM public.speakers WHERE id=v_id AND occasion=p_occasion FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('code',404); END IF;
  v_payload:=public.get_speaker_command_data_v1(v_id);
  SELECT coalesce(v.version,0) INTO v_version FROM (SELECT 1) seed
   LEFT JOIN public.client_aggregate_versions v ON v.aggregate_type='speaker'
   AND v.scope_type='occasion' AND v.scope_id=p_occasion AND v.aggregate_id=v_id::text;
 ELSE v_payload:=jsonb_build_object('title','','order',0,'is_hidden',false)||jsonb_build_object('data','{}'::jsonb,'topics','[]'::jsonb); END IF;
 v_payload:=v_payload||p_speaker;
 -- Historical patch API ignores foreign topic IDs and collapses duplicates.
 -- Canonical callers validate their full aggregate strictly.
 IF p_speaker ? 'topics' THEN
  v_payload:=jsonb_set(v_payload,'{topics}',coalesce((SELECT jsonb_agg(t.id ORDER BY t.id)
   FROM public.speaker_topics t WHERE t.occasion=p_occasion AND t.id IN
    (SELECT value::bigint FROM jsonb_array_elements_text(p_speaker->'topics'))),'[]'));
 END IF;
 IF nullif(btrim(v_payload->>'title'),'') IS NULL THEN RETURN jsonb_build_object('code',400); END IF;
 r:=public.save_speaker_client_sync_v1(p_occasion,extensions.gen_random_uuid(),v_version,jsonb_build_object('id',v_payload->'id','title',v_payload->'title','subtitle',v_payload->'subtitle','description',v_payload->'description','image',v_payload->'image','order',v_payload->'order','is_hidden',v_payload->'is_hidden','data',v_payload->'data','topics',v_payload->'topics'));
 RETURN jsonb_build_object('code',r->'code','data',r#>'{data,speaker}');
END $function$

CREATE OR REPLACE FUNCTION public.update_speaker_topic(p_occasion bigint, p_topic jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_id bigint:=(p_topic->>'id')::bigint; v_version bigint; v_payload jsonb; r jsonb;
BEGIN
 IF auth.uid() IS NULL OR NOT public.get_is_editor_on_occasion(p_occasion) THEN
  RETURN jsonb_build_object('code',403); END IF;
 IF v_id IS NOT NULL THEN
  PERFORM 1 FROM public.speaker_topics WHERE id=v_id AND occasion=p_occasion FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('code',404); END IF;
  v_payload:=(SELECT to_jsonb(t) FROM public.speaker_topics t WHERE t.id=v_id);
  SELECT coalesce(v.version,0) INTO v_version FROM (SELECT 1) seed
   LEFT JOIN public.client_aggregate_versions v ON v.aggregate_type='speaker_topic'
   AND v.scope_type='occasion' AND v.scope_id=p_occasion AND v.aggregate_id=v_id::text;
 ELSE v_payload:=jsonb_build_object('title','','order',0,'is_hidden',false); END IF;
 v_payload:=v_payload||p_topic;
 IF nullif(btrim(v_payload->>'title'),'') IS NULL THEN RETURN jsonb_build_object('code',400); END IF;
 r:=public.save_speaker_topic_client_sync_v1(p_occasion,extensions.gen_random_uuid(),v_version,jsonb_build_object('id',v_payload->'id','title',v_payload->'title','order',v_payload->'order','is_hidden',v_payload->'is_hidden'));
 RETURN jsonb_build_object('code',r->'code','data',r#>'{data,topic}');
END $function$

CREATE OR REPLACE FUNCTION public.update_spot_assignments_internal_v1(p_changes jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE change jsonb; oc bigint; resource_id bigint; slot_id bigint; context_id bigint; old_id bigint; new_id bigint;
 spot_ids bigint[]; resource_ids bigint[];
BEGIN
 IF p_changes IS NULL OR jsonb_typeof(p_changes)<>'array' OR jsonb_array_length(p_changes) NOT BETWEEN 1 AND 1000 THEN
  RAISE invalid_parameter_value USING MESSAGE='invalid spot assignment batch'; END IF;
 SELECT ARRAY(SELECT DISTINCT e.value::bigint FROM jsonb_array_elements(p_changes) c CROSS JOIN LATERAL jsonb_each_text(c) e
  WHERE e.key IN('old_spot_id','new_spot_id') AND nullif(e.value,'') IS NOT NULL),
  ARRAY(SELECT DISTINCT (c->>'resource_id')::bigint FROM jsonb_array_elements(p_changes) c) INTO spot_ids,resource_ids;
 PERFORM public.lock_spot_assignment_scope_internal_v1(spot_ids,resource_ids);
 SELECT min(occasion) INTO oc FROM public.resources WHERE id=ANY(resource_ids);
 IF oc IS NULL OR public.get_is_editor_order_on_occasion(oc) IS NOT TRUE THEN RAISE insufficient_privilege USING MESSAGE='inventory editor required'; END IF;
 IF EXISTS(SELECT 1 FROM public.resources WHERE id=ANY(resource_ids) AND occasion<>oc)
 OR (SELECT count(*) FROM public.resources WHERE id=ANY(resource_ids))<>cardinality(resource_ids)
 OR (SELECT count(*) FROM eshop.spots WHERE id=ANY(spot_ids) AND occasion=oc)<>cardinality(spot_ids) THEN
  RAISE invalid_parameter_value USING MESSAGE='assignment outside occasion'; END IF;
 -- Validate every change before writing the first one. Old IDs are the editor's
 -- original assignment, not a fresh baseline fetched immediately before save.
 FOR change IN SELECT value FROM jsonb_array_elements(p_changes) LOOP
  resource_id:=(change->>'resource_id')::bigint;slot_id:=(change->>'resource_slot_id')::bigint;
  context_id:=(change->>'inventory_context_id')::bigint;old_id:=(change->>'old_spot_id')::bigint;new_id:=(change->>'new_spot_id')::bigint;
  IF resource_id IS NULL OR (old_id IS NULL AND new_id IS NULL)
  OR (slot_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.resource_slots WHERE id=slot_id AND resource=resource_id))
  OR EXISTS(SELECT 1 FROM eshop.spots s LEFT JOIN public.inventory_contexts c ON c.id=s.inventory_context
    JOIN public.resources r ON r.id=resource_id WHERE s.id=ANY(ARRAY[old_id,new_id])
    AND (c.inventory_pool IS DISTINCT FROM r.inventory_pool OR (context_id IS NOT NULL AND s.inventory_context IS DISTINCT FROM context_id))) THEN
   RAISE invalid_parameter_value USING MESSAGE='invalid resource, slot or inventory context'; END IF;
  IF old_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM eshop.spots WHERE id=old_id AND resource=resource_id AND resource_slot IS NOT DISTINCT FROM slot_id) THEN
   RAISE serialization_failure USING MESSAGE='original spot assignment changed; reload editor'; END IF;
  IF EXISTS(SELECT 1 FROM eshop.spots WHERE id=ANY(ARRAY[old_id,new_id]) AND secret IS NOT NULL AND secret_expiration_time>clock_timestamp()) THEN
   RAISE object_not_in_prerequisite_state USING MESSAGE='SPOT_HELD'; END IF;
 END LOOP;
 FOR change IN SELECT value FROM jsonb_array_elements(p_changes) LOOP
  UPDATE eshop.spots SET resource=NULL,resource_slot=NULL,updated_at=now() WHERE id=(change->>'old_spot_id')::bigint;
  UPDATE eshop.spots SET resource=(change->>'resource_id')::bigint,resource_slot=(change->>'resource_slot_id')::bigint,updated_at=now() WHERE id=(change->>'new_spot_id')::bigint;
 END LOOP;
 IF EXISTS(SELECT 1 FROM eshop.spots s JOIN public.resources r ON r.id=s.resource WHERE r.id=ANY(resource_ids)
  GROUP BY r.id,r.capacity,s.inventory_context HAVING count(*)>r.capacity)
 OR EXISTS(SELECT 1 FROM eshop.spots WHERE resource=ANY(resource_ids) AND resource_slot IS NOT NULL GROUP BY resource_slot,inventory_context HAVING count(*)>1) THEN
  RAISE object_not_in_prerequisite_state USING MESSAGE='RESOURCE_CAPACITY_EXCEEDED'; END IF;
END $function$

CREATE OR REPLACE FUNCTION public.update_ticket_note_hidden(ticket_id bigint, new_note_hidden text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
    occasion_id bigint;
BEGIN
    -- Retrieve the occasion_id from the ticket
    SELECT occasion INTO occasion_id FROM eshop.tickets WHERE id = ticket_id;

    -- Check if occasion_id was successfully retrieved
    IF occasion_id IS NULL THEN
        RETURN jsonb_build_object('code', 404, 'message', 'Ticket not found or occasion not specified');
    END IF;

    -- Check if the user has the right to edit the given occasion
    IF (get_is_editor_order_on_occasion(occasion_id)) <> TRUE THEN
        -- Return an error if the user is not authorized
        RETURN jsonb_build_object('code', 403, 'message', 'User is not authorized to edit this occasion');
    END IF;

    PERFORM public.check_ticket_is_mutable(ticket_id);

    -- Proceed to update note_hidden if the user is authorized
    UPDATE eshop.tickets
    SET note_hidden = new_note_hidden, updated_at = now()
    WHERE id = ticket_id;

    -- Check if the update was successful
    IF FOUND THEN
        RETURN jsonb_build_object('code', 200, 'message', 'Update successful');
    ELSE
        RETURN jsonb_build_object('code', 404, 'message', 'Ticket not found');
    END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.update_ticket_products_client_sync_v1(p_ticket bigint, p_products jsonb, p_command_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_occasion bigint; v_begin jsonb; v_hash text;
  v_users uuid[]; v_result jsonb;
BEGIN
  SELECT t.occasion INTO v_occasion FROM eshop.tickets t WHERE t.id=p_ticket;
  IF v_actor IS NULL OR v_occasion IS NULL OR p_products IS NULL
    OR jsonb_typeof(p_products)<>'array' OR jsonb_array_length(p_products)>1000
    OR octet_length(p_products::text)>1048576
    OR NOT public.get_is_editor_order_on_occasion(v_occasion) THEN
    RAISE insufficient_privilege USING MESSAGE='order editor required'; END IF;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'ticket',p_ticket,'products',p_products)::text,'UTF8'),'sha256'),'hex');
  v_begin:=public.begin_client_mutation_v1(p_command_id,
    'inventory.ticket.products',v_occasion,v_actor,v_hash);
  IF v_begin->>'disposition'='replay' THEN RETURN v_begin->'response'; END IF;
  SELECT COALESCE(array_agg(ou."user"),'{}'::uuid[]) INTO v_users
    FROM public.occasion_users ou
    WHERE ou.occasion=v_occasion AND ou.ticket=p_ticket;
  v_result:=public.update_ticket_products_internal_v1(p_ticket,p_products);
  RETURN public.complete_private_inventory_mutation_v1(p_command_id,v_occasion,
    'inventory.ticket.products',jsonb_build_array(jsonb_build_object(
      'entityType','ticket_products','entityId',p_ticket,'operation','update',
      'safeLabel','Ticket products','changedFields',jsonb_build_array(
        'products','allocations'))),v_users,v_result);
END; $function$

CREATE OR REPLACE FUNCTION public.update_ticket_products_ws(p_ticket_id bigint, p_product_ids bigint[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_order_id         bigint;
  v_occasion_id      bigint;
  v_payment_info_id  bigint;
  v_currency_code    char(3);
  v_state            text;
  v_old_data         jsonb;
  v_new_data         jsonb;
  v_sum_old          numeric := 0;
  v_sum_new          numeric := 0;
  v_diff             numeric;
  v_products_json    jsonb;
  v_old_ids          bigint[];
  v_new_ids          bigint[];
  v_paid             numeric;
  v_price            numeric;
  v_new_state        text;
  v_occasion_features jsonb;
  v_form_settings     jsonb;
  v_deadline_duration_seconds bigint;
  v_new_deadline      timestamptz;
BEGIN
  /* 0) Lookup & permission */
  SELECT opt."order", o.occasion, o.payment_info, o.currency_code, o.data, o.state, occ.features
    INTO v_order_id, v_occasion_id, v_payment_info_id, v_currency_code, v_old_data, v_state, v_occasion_features
  FROM eshop.order_product_ticket AS opt
  JOIN eshop.orders              AS o   ON o.id = opt."order"
  JOIN public.occasions          AS occ ON occ.id = o.occasion
  WHERE opt.ticket = p_ticket_id
  LIMIT 1;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('code',404,'message','Ticket not linked to any order');
  END IF;
  IF NOT get_is_editor_order_on_occasion(v_occasion_id) THEN
    RETURN jsonb_build_object('code',403,'message','Not authorized');
  END IF;

  /* compute old/new ID arrays and bail early if identical */
  SELECT array_agg((product_obj->>'id')::bigint ORDER BY (product_obj->>'id')::bigint)
    INTO v_old_ids
  FROM jsonb_array_elements(
         CASE WHEN jsonb_typeof(v_old_data->'tickets') = 'array'
              THEN v_old_data->'tickets'
              ELSE '[]'::jsonb END
       ) AS ticket(ticket_obj)
  CROSS JOIN LATERAL jsonb_array_elements(
         CASE WHEN jsonb_typeof(ticket.ticket_obj->'products') = 'array'
              THEN ticket.ticket_obj->'products'
              ELSE '[]'::jsonb END
       ) AS prod(product_obj)
  WHERE (ticket.ticket_obj->>'id')::bigint = p_ticket_id;

  SELECT array_agg(pid ORDER BY pid)
    INTO v_new_ids
  FROM unnest(p_product_ids) AS pid;

  IF v_old_ids IS NOT DISTINCT FROM v_new_ids THEN
    RETURN jsonb_build_object('code',200,'data',v_old_data);
  END IF;

  /* 1) old subtotal */
  SELECT COALESCE(SUM((product_obj->>'price')::numeric),0)
    INTO v_sum_old
  FROM jsonb_array_elements(
         CASE WHEN jsonb_typeof(v_old_data->'tickets') = 'array'
              THEN v_old_data->'tickets'
              ELSE '[]'::jsonb END
       ) AS ticket(ticket_obj)
  CROSS JOIN LATERAL jsonb_array_elements(
         CASE WHEN jsonb_typeof(ticket.ticket_obj->'products') = 'array'
              THEN ticket.ticket_obj->'products'
              ELSE '[]'::jsonb END
       ) AS prod(product_obj)
  WHERE (ticket.ticket_obj->>'id')::bigint = p_ticket_id;

  /* 2) new products JSON + subtotal */
  SELECT
    jsonb_agg(jsonb_build_object(
      'id',            p.id,
      'type',          pt.type,
      'price',         p.price,
      'title',         p.title,
      'type_title',    pt.title,
      'currency_code', p.currency_code
    )),
    COALESCE(SUM(p.price),0)
  INTO v_products_json, v_sum_new
  FROM unnest(p_product_ids) AS pid
  JOIN eshop.products           AS p  ON p.id = pid
  LEFT JOIN eshop.product_types AS pt ON pt.id = p.product_type
  WHERE p.occasion = v_occasion_id;

  /* 3) rewrite just that ticket’s products array in orders.data */
  SELECT jsonb_set(
    v_old_data,
    '{tickets}',
    COALESCE(
      (
        SELECT jsonb_agg(
          CASE WHEN (tckt->>'id')::bigint = p_ticket_id
               THEN tckt || jsonb_build_object('products', COALESCE(v_products_json, '[]'::jsonb))
               ELSE tckt
          END
        )
        FROM jsonb_array_elements(
               CASE WHEN jsonb_typeof(v_old_data->'tickets') = 'array'
                    THEN v_old_data->'tickets'
                    ELSE '[]'::jsonb END
             ) AS tckt
      ),
      '[]'::jsonb
    )
  ) INTO v_new_data;

  UPDATE eshop.orders
     SET data = v_new_data
   WHERE id = v_order_id;

  /* 4) granularly update the link‐table rows */
  UPDATE eshop.spots
     SET order_product_ticket = NULL
   WHERE order_product_ticket IN (
      SELECT opt.id
      FROM eshop.order_product_ticket opt
      WHERE opt.ticket = p_ticket_id
        AND opt.product IN (
          SELECT unnest FROM unnest(v_old_ids)
          EXCEPT
          SELECT unnest FROM unnest(p_product_ids)
        )
   );

  DELETE FROM eshop.order_product_ticket
   WHERE ticket = p_ticket_id
     AND product IN (
        SELECT unnest FROM unnest(v_old_ids)
        EXCEPT
        SELECT unnest FROM unnest(p_product_ids)
     );

  IF cardinality(p_product_ids) > 0 THEN
    DELETE FROM eshop.order_product_ticket
    WHERE ticket = p_ticket_id AND product IS NULL;
  END IF;

  INSERT INTO eshop.order_product_ticket ("order", ticket, product)
  SELECT v_order_id, p_ticket_id, new_pid
    FROM (
      SELECT unnest FROM unnest(p_product_ids)
      EXCEPT
      SELECT unnest FROM unnest(v_old_ids)
    ) AS t(new_pid);

  IF cardinality(p_product_ids) = 0 THEN
    INSERT INTO eshop.order_product_ticket("order", ticket, product)
      SELECT v_order_id, p_ticket_id, NULL
      WHERE NOT EXISTS (SELECT 1 FROM eshop.order_product_ticket WHERE ticket = p_ticket_id);
  END IF;

  /* 5) adjust payment_info.amount and order.price by the delta */
  v_diff := v_sum_new - v_sum_old;
  UPDATE eshop.payment_info
     SET amount = amount + v_diff
   WHERE id = v_payment_info_id;
  UPDATE eshop.orders
     SET price      = COALESCE(price,0) + v_diff,
         updated_at = now()
   WHERE id = v_order_id;

  /* 5a) decide new state based on money received */
  SELECT COALESCE(paid,0) INTO v_paid
    FROM eshop.payment_info
   WHERE id = v_payment_info_id;
  SELECT price INTO v_price
    FROM eshop.orders
   WHERE id = v_order_id;

  v_new_state := CASE
                   WHEN v_paid >= v_price THEN 'paid'
                   ELSE 'ordered'
                 END;

  IF v_new_state = 'paid' THEN
    IF NOT EXISTS (
      SELECT 1 FROM eshop.tickets t
      JOIN eshop.order_product_ticket opt ON opt.ticket = t.id
      WHERE opt."order" = v_order_id AND t.state <> 'sent'
    ) THEN
      v_new_state := 'sent';
    END IF;
  END IF;

  UPDATE eshop.orders
     SET state      = v_new_state,
         updated_at = now()
   WHERE id = v_order_id;

  -- if we just rolled a formerly‐paid/sent order back into 'ordered' because price increased,
  -- call the dedicated function to set a new deadline and requeue the reminder.
  IF v_new_state = 'ordered' THEN
    -- Find the 'form' feature settings to get the deadline duration
    SELECT elem INTO v_form_settings
    FROM jsonb_array_elements(v_occasion_features) AS elem
    WHERE elem->>'code' = 'form';

    -- Extract duration, with a default of 7 days (604800 seconds) if not specified
    v_deadline_duration_seconds := COALESCE(
        (v_form_settings->>'deadline_duration_seconds')::bigint,
        604800
    );

    v_new_deadline := now() + make_interval(secs => v_deadline_duration_seconds);

    -- Call the dedicated function to set the deadline and requeue the reminder
    PERFORM public.set_payment_deadline(v_payment_info_id, v_new_deadline);
  END IF;

  /* 6) append history */
  INSERT INTO eshop.orders_history("order", data, state, price, currency_code)
  VALUES (
    v_order_id,
    v_new_data,
    (SELECT state FROM eshop.orders WHERE id = v_order_id),
    v_price,
    v_currency_code
  );

  RETURN jsonb_build_object('code',200,'data',v_new_data);

EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('code',500,'message',SQLERRM);
END;
$function$

CREATE OR REPLACE FUNCTION public.update_ticket_products_wsv2(p_ticket_id bigint, p_products jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_order_id         bigint;
  v_occasion_id      bigint;
  v_payment_info_id  bigint;
  v_currency_code    char(3);
  v_state            text;
  v_old_data         jsonb;
  v_new_data         jsonb;
  v_sum_old          numeric := 0;
  v_sum_new          numeric := 0;
  v_diff             numeric;
  v_products_json    jsonb;
  v_old_products     jsonb;
  v_old_ids          bigint[];
  v_new_ids          bigint[];
  v_paid             numeric;
  v_price            numeric;
  v_new_state        text;
  v_occasion_features jsonb;
  v_form_settings     jsonb;
  v_deadline_duration_seconds bigint;
  v_new_deadline      timestamptz;
  v_current_products_for_compare jsonb;
BEGIN
  PERFORM public.lock_order_capacity_scope_internal(ARRAY(SELECT DISTINCT "order" FROM eshop.order_product_ticket WHERE ticket=p_ticket_id));
  /* 0) Lookup & permission */
  SELECT opt."order", o.occasion, o.payment_info, o.currency_code, o.data, o.state, occ.features
    INTO v_order_id, v_occasion_id, v_payment_info_id, v_currency_code, v_old_data, v_state, v_occasion_features
  FROM eshop.order_product_ticket AS opt
  JOIN eshop.orders              AS o   ON o.id = opt."order"
  JOIN public.occasions          AS occ ON occ.id = o.occasion
  WHERE opt.ticket = p_ticket_id
  LIMIT 1 FOR UPDATE OF o;

  IF NOT FOUND THEN
    RAISE EXCEPTION '%', jsonb_build_object('code', 404, 'message', 'Ticket not linked to any order')::text;
  END IF;

  IF NOT public.get_is_editor_order_on_occasion(v_occasion_id) THEN
    RAISE EXCEPTION '%', jsonb_build_object('code', 403, 'message', 'Not authorized')::text;
  END IF;

  PERFORM public.check_ticket_is_mutable(p_ticket_id);

  /* Check for negative prices in the input */
  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(p_products) AS p
    WHERE (p.value->>'price')::numeric < 0
  ) THEN
    RAISE EXCEPTION '%', jsonb_build_object('code', 400, 'message', 'Product prices cannot be negative.')::text;
  END IF;

  PERFORM public.lock_ticket_order_products_internal(v_order_id,jsonb_build_object('ticket',jsonb_build_array(jsonb_build_object('fields',
    (SELECT coalesce(jsonb_agg(jsonb_build_object('product_type',x->'id')),'[]') FROM jsonb_array_elements(p_products) x)))));
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_products) x JOIN eshop.products p ON p.id=(x->>'id')::bigint
    WHERE p.maximum>0 AND (SELECT count(*) FROM eshop.order_product_ticket WHERE product=p.id)+
      CASE WHEN EXISTS(SELECT 1 FROM eshop.order_product_ticket WHERE ticket=p_ticket_id AND product=p.id) THEN 0 ELSE 1 END>p.maximum) THEN
    RAISE EXCEPTION 'PRODUCT_CAPACITY_EXCEEDED'; END IF;
  /* get old products for the ticket */
  SELECT jsonb_path_query_first(v_old_data, '$.tickets[*] ? (@.id == $tid).products', jsonb_build_object('tid', p_ticket_id))
  INTO v_old_products;
  v_old_products := COALESCE(v_old_products, '[]'::jsonb);

  /* compute old/new ID arrays and check for changes */
  SELECT array_agg((p->>'id')::bigint) INTO v_old_ids FROM jsonb_array_elements(v_old_products) p;
  SELECT array_agg((p->>'id')::bigint) INTO v_new_ids FROM jsonb_array_elements(p_products) p;

  -- Create a comparable representation of products (id and price)
  SELECT COALESCE(jsonb_agg(jsonb_build_object('id', p->'id', 'price', p->'price') ORDER BY (p->>'id')::int), '[]'::jsonb)
  INTO v_current_products_for_compare
  FROM jsonb_array_elements(v_old_products) p;

  -- If product sets (ID and price) are identical, bail early.
  IF v_current_products_for_compare = (
    SELECT COALESCE(jsonb_agg(jsonb_build_object('id', p->'id', 'price', p->'price') ORDER BY (p->>'id')::int), '[]'::jsonb)
    FROM jsonb_array_elements(p_products) p
  ) THEN
    RETURN jsonb_build_object('code',200,'data',v_old_data, 'message', 'No changes detected.');
  END IF;

  /* 1) old subtotal */
  SELECT COALESCE(SUM((p->>'price')::numeric), 0)
  INTO v_sum_old
  FROM jsonb_array_elements(v_old_products) AS p;

  /* 2) new products JSON + subtotal (FIXED HERE) */
  -- We now find the matching old product and merge it (||) with the new data.
  -- This preserves 'spot_title', 'spot_id' or any other extra fields.
  SELECT
    jsonb_agg(
      -- Start with the old product object if it exists (for this ID)
      COALESCE(
        (
           SELECT old_p
           FROM jsonb_array_elements(v_old_products) AS old_p
           WHERE (old_p->>'id')::bigint = p_info.id
           LIMIT 1
        ),
        '{}'::jsonb
      )
      ||
      -- Overwrite with refreshed/new standard fields
      jsonb_build_object(
        'id',            p_info.id,
        'type',          pt.type,
        'price',         (p_new.data->>'price')::numeric, -- Use price from input
        'title',         p_info.title,
        'type_title',    pt.title,
        'currency_code', p_info.currency_code
      )
    ),
    COALESCE(SUM((p_new.data->>'price')::numeric), 0)
  INTO v_products_json, v_sum_new
  FROM jsonb_array_elements(p_products) AS p_new(data)
  JOIN eshop.products           AS p_info ON p_info.id = (p_new.data->>'id')::bigint
  LEFT JOIN eshop.product_types AS pt     ON pt.id = p_info.product_type
  WHERE p_info.occasion = v_occasion_id;

  v_products_json := COALESCE(v_products_json, '[]'::jsonb);

  /* 3) rewrite just that ticket’s products array in orders.data */
  SELECT jsonb_set(
    v_old_data,
    '{tickets}',
    (
      SELECT jsonb_agg(
        CASE WHEN (tckt->>'id')::bigint = p_ticket_id
             THEN jsonb_set(tckt, '{products}', v_products_json)
             ELSE tckt
        END
      )
      FROM jsonb_array_elements(v_old_data->'tickets') AS tckt
    )
  ) INTO v_new_data;

  UPDATE eshop.orders
     SET data = v_new_data
   WHERE id = v_order_id;

  /* Update the ticket timestamp */
  UPDATE eshop.tickets
     SET updated_at = now()
   WHERE id = p_ticket_id;

  /* 4) granularly update the link‐table rows */
  v_old_ids := COALESCE(v_old_ids, ARRAY[]::bigint[]);
  v_new_ids := COALESCE(v_new_ids, ARRAY[]::bigint[]);

  -- Before deleting order_product_ticket rows, nullify the reference in eshop.spots
  UPDATE eshop.spots s
     SET order_product_ticket = NULL
  WHERE s.order_product_ticket IN (
      SELECT opt.id
      FROM eshop.order_product_ticket opt
      WHERE opt.ticket = p_ticket_id
        AND opt.product IN (SELECT unnest FROM unnest(v_old_ids) EXCEPT SELECT unnest FROM unnest(v_new_ids))
  );

  -- Delete link-table rows for products that were removed.
  DELETE FROM eshop.order_product_ticket
  WHERE ticket = p_ticket_id
    AND product IN (SELECT unnest FROM unnest(v_old_ids) EXCEPT SELECT unnest FROM unnest(v_new_ids));

  -- Insert new link-table rows for products that were added.
  INSERT INTO eshop.order_product_ticket ("order", ticket, product)
  SELECT v_order_id, p_ticket_id, new_pid
    FROM (SELECT unnest FROM unnest(v_new_ids) EXCEPT SELECT unnest FROM unnest(v_old_ids)) AS t(new_pid)
  ON CONFLICT DO NOTHING;

  /* 5) adjust payment_info.amount and order.price by the delta */
  v_diff := v_sum_new - v_sum_old;
  IF v_diff <> 0 THEN
      UPDATE eshop.payment_info
         SET amount = amount + v_diff
       WHERE id = v_payment_info_id;
      UPDATE eshop.orders
         SET price      = COALESCE(price,0) + v_diff,
             updated_at = now()
       WHERE id = v_order_id;
  END IF;

  /* 5a) decide new state based on money received */
  SELECT COALESCE(pi.paid,0), o.price
    INTO v_paid, v_price
    FROM eshop.orders o
    LEFT JOIN eshop.payment_info pi ON o.payment_info = pi.id
   WHERE o.id = v_order_id;

  v_new_state := CASE
                   WHEN v_paid >= v_price AND v_price > 0 THEN 'paid'
                   WHEN v_price <= 0 THEN 'paid'
                   ELSE 'ordered'
                 END;

  IF v_new_state = 'paid' THEN
    IF NOT EXISTS (
      SELECT 1 FROM eshop.tickets t
      JOIN eshop.order_product_ticket opt ON opt.ticket = t.id
      WHERE opt."order" = v_order_id AND t.state <> 'sent'
    ) THEN
      v_new_state := 'sent';
    END IF;
  END IF;

  PERFORM public.cancel_order_email_intents(v_order_id);
  UPDATE eshop.orders
     SET email_payment_version=email_payment_version+1, state      = v_new_state,
         updated_at = now()
   WHERE id = v_order_id;

  -- A price edit can pay off the order without the usual paid transition.
  -- Email acceptance only projects paid tickets to sent, so keep eligible
  -- tickets in step with the order before creating its delivery intent.
  IF v_new_state = 'paid' THEN
    UPDATE eshop.tickets t
       SET state = 'paid', updated_at = now()
      FROM eshop.order_product_ticket opt
     WHERE opt.ticket = t.id AND opt."order" = v_order_id
       AND t.state IN ('ordered', 'expired');
  END IF;

  IF v_price > 0 THEN
    -- If there's a balance due, set/update the payment deadline.
    SELECT elem INTO v_form_settings
    FROM jsonb_array_elements(v_occasion_features) AS elem
    WHERE elem->>'code' = 'form';

    v_deadline_duration_seconds := COALESCE(
        (v_form_settings->>'deadline_duration_seconds')::bigint,
        604800 -- Default to 7 days (604800 seconds) if not specified
    );

    v_new_deadline := now() + make_interval(secs => v_deadline_duration_seconds);
    PERFORM public.set_payment_deadline(v_payment_info_id, v_new_deadline);
  ELSE
    -- If the order is free or paid off, clear the payment deadline.
    PERFORM public.set_payment_deadline(v_payment_info_id, NULL);
  END IF;

  PERFORM public.apply_allocations(v_order_id);
  PERFORM public.enqueue_paid_order_tickets(v_order_id);

  /* 6) append history */
  INSERT INTO eshop.orders_history("order", data, state, price, currency_code)
  VALUES (
    v_order_id,
    v_new_data,
    v_new_state,
    (SELECT price FROM eshop.orders WHERE id = v_order_id),
    v_currency_code
  );

  RETURN jsonb_build_object('code',200,'data',v_new_data);
END;
$function$

CREATE OR REPLACE FUNCTION public.update_ticket_to_unused_ws(ticket_id bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
    occasion_id bigint;
    updated_count integer;
BEGIN
    SELECT occasion
    INTO STRICT occasion_id
    FROM eshop.tickets
    WHERE id = ticket_id;

    PERFORM public.check_is_editor_order_on_occasion(occasion_id);

    IF NOT public.admit_scan_access_v1(occasion_id,true) THEN
        RAISE SQLSTATE 'PT429' USING MESSAGE='abuse_limit_exceeded';
    END IF;
    PERFORM public.check_ticket_is_mutable(ticket_id);

    UPDATE eshop.tickets
    SET
        -- `sent` is the canonical unused state that can be scanned again.
        state = 'sent',
        updated_at = clock_timestamp()
    WHERE id = ticket_id
      AND state = 'used';

    GET DIAGNOSTICS updated_count = ROW_COUNT;
    IF updated_count <> 1 THEN
        RAISE EXCEPTION 'Ticket % is not used.', ticket_id;
    END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.update_ticket_to_used(ticket_id bigint, scan_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
    occasion_id bigint;
    current_state text;
    expected_scan_code text;
BEGIN
    IF NOT public.check_scan_attempt_budget_v1((SELECT occasion FROM eshop.tickets WHERE id=ticket_id)) THEN
        RETURN jsonb_build_object('code',429,'message','abuse_limit_exceeded');
    END IF;
    -- 1. Validate Ticket Existence
    IF NOT EXISTS (
        SELECT 1 FROM eshop.tickets WHERE id = ticket_id
    ) THEN
        PERFORM public.admit_scan_access_v1(NULL,false);
        RETURN jsonb_build_object(
            'code', 404,
            'message', 'Ticket not found.'
        );
    END IF;

    -- 2. Retrieve Associated Occasion ID AND Current State
    SELECT occasion, state
    INTO occasion_id, current_state
    FROM eshop.tickets
    WHERE id = ticket_id;

    -- Check if occasion_id is present (Integrity check)
    IF occasion_id IS NULL THEN
        RETURN jsonb_build_object(
            'code', 404,
            'message', 'Occasion associated with ticket not found.'
        );
    END IF;

    -- 3. Retrieve Expected Scan Code from occasions_hidden via foreign key
    SELECT oh.secret
    INTO expected_scan_code
    FROM public.occasions_hidden oh
    JOIN public.occasions o ON o.occasion_hidden = oh.id
    WHERE o.id = occasion_id
    LIMIT 1;

    -- Check if scan_code is defined
    IF expected_scan_code IS NULL THEN
        PERFORM public.admit_scan_access_v1(occasion_id,false);
        RETURN jsonb_build_object(
            'code', 400,
            'message', 'Scan code not defined for occasion.'
        );
    END IF;

    -- 4. Validate Provided Scan Code
    IF scan_code IS DISTINCT FROM expected_scan_code THEN
        PERFORM public.admit_scan_access_v1(occasion_id,false);
        RETURN jsonb_build_object(
            'code', 401,
            'message', 'Scan code is not correct.'
        );
    END IF;

    IF NOT public.admit_scan_access_v1(occasion_id,true) THEN
        RETURN jsonb_build_object('code',429,'message','abuse_limit_exceeded');
    END IF;

    PERFORM public.scanner_lock_ticket_internal(ticket_id);
    SELECT state INTO current_state FROM eshop.tickets WHERE id=ticket_id;

    -- 2a. Validate Ticket State (New Check)
    IF current_state = 'used' THEN
        RETURN jsonb_build_object(
            'code', 409,
            'message', 'Ticket has already been used.'
        );
    ELSIF current_state = 'storno' THEN
        RETURN jsonb_build_object(
            'code', 409,
            'message', 'Ticket is cancelled (storno).'
        );
    END IF;

    PERFORM public.check_ticket_is_mutable(ticket_id);

    -- 5. Update Ticket State to 'used' AND update timestamp
    PERFORM public.scanner_admit_ticket_internal(ticket_id);

    -- 6. Return Success Message
    RETURN jsonb_build_object(
        'code', 200,
        'message', 'Ticket state updated to used successfully.'
    );

EXCEPTION
    WHEN OTHERS THEN
        -- Handle any unexpected exceptions
        RETURN jsonb_build_object(
            'code', 500,
            'message', 'An unexpected error occurred.',
            'detail', SQLERRM
        );
END;
$function$

CREATE OR REPLACE FUNCTION public.update_ticket_to_used_ws(ticket_id bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
    occasion_id bigint;
    current_state text;
BEGIN
    -- 1. Retrieve the occasion ID and State from the ticket.
    -- If the ticket does not exist, this will raise a NO_DATA_FOUND exception (due to STRICT).
    SELECT occasion, state
    INTO STRICT occasion_id, current_state
    FROM eshop.tickets
    WHERE id = ticket_id;

    -- 2. Check if the current user has editor permissions for the occasion.
    -- This function will raise an exception if the user is not an editor.
    PERFORM public.check_is_editor_order_on_occasion(occasion_id);

    PERFORM public.scanner_lock_ticket_internal(ticket_id);
    SELECT state INTO current_state FROM eshop.tickets WHERE id=ticket_id;

    -- 1a. Check State Validity (New Check)
    IF current_state = 'used' THEN
        RAISE EXCEPTION 'Ticket % is already used.', ticket_id;
    ELSIF current_state = 'storno' THEN
        RAISE EXCEPTION 'Ticket % is cancelled (storno).', ticket_id;
    END IF;



    IF NOT public.admit_scan_access_v1(occasion_id,true) THEN
        RAISE SQLSTATE 'PT429' USING MESSAGE='abuse_limit_exceeded';
    END IF;
    PERFORM public.check_ticket_is_mutable(ticket_id);

    -- 3. Update the ticket state to 'used' AND update timestamp.
    -- This is only reached if the previous checks pass without raising an exception.
    PERFORM public.scanner_admit_ticket_internal(ticket_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.update_unit(p_unit_id bigint, p_title text, p_data jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_version bigint; v_result jsonb;
BEGIN
 IF auth.uid() IS NULL OR NOT public.get_is_manager_on_unit(p_unit_id) THEN
  RAISE insufficient_privilege USING MESSAGE='unit manager required'; END IF;
 PERFORM 1 FROM public.units WHERE id=p_unit_id FOR UPDATE;
 SELECT coalesce(v.version,0) INTO v_version FROM (SELECT 1) seed
 LEFT JOIN public.client_aggregate_versions v ON v.aggregate_type='unit'
 AND v.scope_type='unit' AND v.scope_id=p_unit_id AND v.aggregate_id=p_unit_id::text;
 v_result:=public.save_unit_client_sync_v1(p_unit_id,extensions.gen_random_uuid(),v_version,
  jsonb_build_object('id',p_unit_id,'title',p_title,'data',coalesce(p_data,'{}')));
 IF v_result->>'status' NOT IN ('applied','unchanged') THEN
  RAISE EXCEPTION 'unit save rejected: %',v_result->>'code'; END IF;
END $function$

CREATE OR REPLACE FUNCTION public.update_unit_user(input_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
    -- Variables extracted from input_data
    v_user uuid;
    v_unit bigint;
    v_is_manager boolean;
    v_is_editor boolean;
    v_is_editor_view boolean;
    v_data jsonb;

    -- Internal helper variables
    v_update_user_payload jsonb;
    v_update_user_result jsonb;
    v_final_user_uuid uuid;
BEGIN
    -- 1. Extract and validate fields from the input JSONB
    v_user := (input_data->>'user')::uuid;
    v_unit := (input_data->>'unit')::bigint;
    v_is_manager := (input_data->>'is_manager')::boolean;
    v_is_editor := (input_data->>'is_editor')::boolean;
    v_is_editor_view := (input_data->>'is_editor_view')::boolean;

    -- Default the 'data' field to an empty jsonb object if it's null or an empty string
    v_data := CASE
                WHEN input_data->>'data' IS NULL OR input_data->>'data' = ''
                THEN '{}'::jsonb
                ELSE input_data->'data'
              END;

    -- 2. Perform initial validation
    IF v_unit IS NULL THEN
        RETURN jsonb_build_object('code', 400, 'message', 'The "unit" field is required.');
    END IF;

    IF NOT EXISTS (SELECT 1 FROM public.units WHERE id = v_unit) THEN
      RETURN jsonb_build_object('code', 404, 'message', 'Unit not found');
    END IF;

    -- 3. Authorization Check: Verify the calling user is a manager for the specified unit
    IF NOT EXISTS (
      SELECT 1 FROM public.unit_users
      WHERE "user" = auth.uid()
        AND unit = v_unit
        AND is_manager = true
    ) THEN
      RETURN jsonb_build_object('code', 403, 'message', 'Unauthorized: You must be a manager of this unit.');
    END IF;

    -- 4. Prepare payload to call the update_user function
    -- The `update_user` function expects email, name, surname etc., to be inside its 'data' payload.
    -- We will ensure these fields are present in v_data before making the call.
    IF input_data ? 'name' THEN v_data := v_data || jsonb_build_object('name', input_data->>'name'); END IF;
    IF input_data ? 'surname' THEN v_data := v_data || jsonb_build_object('surname', input_data->>'surname'); END IF;
    IF input_data ? 'sex' THEN v_data := v_data || jsonb_build_object('sex', input_data->>'sex'); END IF;
    IF v_user IS NULL AND input_data ? 'email' THEN
        v_data := v_data || jsonb_build_object('email', input_data->>'email');
    END IF;

    v_update_user_payload := jsonb_build_object(
        'user', v_user,
        'unit', v_unit,
        'data', v_data
    );

    -- 5. Call update_user and handle its response
    v_update_user_result := update_user(v_update_user_payload);

    -- If the sub-function did not return a success code (200 or 201), pass its error response through.
    IF (v_update_user_result->>'code')::int NOT IN (200, 201) THEN
        RETURN v_update_user_result;
    END IF;

    -- Extract the definitive user UUID returned from the update_user function
    v_final_user_uuid := (v_update_user_result->>'user')::uuid;

    -- Sanity check in case update_user succeeds but doesn't return a UUID
    IF v_final_user_uuid IS NULL THEN
      RETURN jsonb_build_object('code', 500, 'message', 'Failed to retrieve user UUID after profile update.', 'lol', (v_update_user_result));
    END IF;

    -- 6. Insert or Update the user's roles in the unit (UPSERT)
    INSERT INTO public.unit_users("user", unit, is_manager, is_editor, is_editor_view, data)
    VALUES (v_final_user_uuid, v_unit, v_is_manager, v_is_editor, v_is_editor_view, v_data)
    ON CONFLICT ("user", unit) DO UPDATE
    SET is_manager     = EXCLUDED.is_manager,
        is_editor      = EXCLUDED.is_editor,
        is_editor_view = EXCLUDED.is_editor_view,
        data           = EXCLUDED.data;

    -- 7. Return a final success response
    RETURN jsonb_build_object(
      'code', 200,
      'message', 'User role in unit updated successfully',
      'user', v_final_user_uuid::text
    );

EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object(
      'code', 500,
      'message', SQLERRM
    );
END;
$function$

