CREATE OR REPLACE FUNCTION public.update_user_internal_v1(input_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_user uuid;
  v_occasion bigint;
  v_unit_input bigint;
  v_is_manager boolean;
  v_is_editor boolean;
  v_data jsonb;
  v_email text;
  v_password text;
  v_org bigint;
  v_unit bigint;
  new_user uuid;
  existing_user_id uuid;
  v_global_before jsonb;
  v_create_response jsonb;
BEGIN
  -- Extract main fields from the input_data jsonb object
  v_user := (input_data->>'user')::uuid;
  v_occasion := (input_data->>'occasion')::bigint;
  v_unit_input := (input_data->>'unit')::bigint;
  v_is_manager := COALESCE((input_data->>'is_manager')::boolean, false);
  v_is_editor := COALESCE((input_data->>'is_editor')::boolean, false);

  -- Ensure 'data' field is a valid jsonb
  v_data := CASE
        WHEN input_data->>'data' IS NULL OR input_data->>'data' = ''
        THEN '{}'::jsonb
        ELSE input_data->'data'
       END;

  -- Determine the unit
  IF v_occasion IS NOT NULL THEN
    SELECT unit INTO v_unit FROM public.occasions WHERE id = v_occasion;
    IF v_unit IS NULL THEN
     RETURN jsonb_build_object('code', 404, 'message', 'Occasion not found');
    END IF;
  ELSIF v_unit_input IS NOT NULL THEN
    v_unit := v_unit_input;
    IF NOT EXISTS (SELECT 1 FROM public.units WHERE id = v_unit) THEN
        RETURN jsonb_build_object('code', 404, 'message', 'Unit not found');
    END IF;
  ELSE
    RETURN jsonb_build_object('code', 400, 'message', 'Either an occasion or a unit must be provided');
  END IF;

  -- Get the organization
  SELECT organization INTO v_org FROM public.units WHERE id = v_unit;
  IF v_org IS NULL THEN
    RETURN jsonb_build_object('code', 404, 'message', 'Organization not found for the specified unit');
  END IF;

  -- Authorization check
  IF v_occasion IS NOT NULL THEN
    IF NOT EXISTS (
     SELECT 1 FROM public.occasion_users
     WHERE "user" = auth.uid()
      AND occasion = v_occasion
      AND is_manager = true
    ) THEN
     RETURN jsonb_build_object('code', 403, 'message', 'Unauthorized: Caller is not a manager for this occasion');
    END IF;
  ELSE
    IF NOT EXISTS (
        SELECT 1 FROM public.unit_users
        WHERE "user" = auth.uid()
        AND unit = v_unit
        AND is_manager = true
    ) THEN
        RETURN jsonb_build_object('code', 403, 'message', 'Unauthorized: Caller is not a manager for this unit');
    END IF;
  END IF;

  -- Logic for finding or creating user
  IF v_user IS NULL THEN
    v_email := input_data->'data'->>'email';

    IF v_email IS NULL OR v_email = '' THEN
      RETURN jsonb_build_object('code', 400, 'message', 'Email is required to find or create a user.');
    END IF;

    -- Check if user exists
    SELECT id INTO existing_user_id
    FROM auth.users
    WHERE email = v_org::text || '+' || v_email;

    IF existing_user_id IS NOT NULL THEN
      IF EXISTS(SELECT 1 FROM public.user_info WHERE id=existing_user_id AND organization IS DISTINCT FROM v_org) THEN
        RETURN jsonb_build_object('code',403,'message','User is outside the unit organization'); END IF;
      -- Create profile if missing
      IF NOT EXISTS (SELECT 1 FROM public.user_info WHERE id = existing_user_id) THEN
        INSERT INTO public.user_info (
          id, organization, email_readonly, data, name, surname, sex, phone,
          birth_date
        )
        VALUES (
            existing_user_id,
            v_org,
            v_email,
            v_data,
            v_data->>'name',
            v_data->>'surname',
            v_data->>'sex',
            v_data->>'phone',
            NULLIF(v_data->>'birthDate', '')::date
        );
      END IF;

      RETURN jsonb_build_object('code', 200, 'message', 'User found', 'user', existing_user_id::text);

    ELSE
      -- User does not exist, create new one
      v_password := encode(gen_random_bytes(16), 'hex');

      -- 1. Capture the JSONB response
      v_create_response := create_user_in_organization_with_data_ws(v_org, v_email, v_password, v_data);

      -- 2. Check if creation was successful (code 200)
      IF (v_create_response->>'code')::int != 200 THEN
          RETURN v_create_response; -- Return the error from the creation function
      END IF;

      -- 3. Extract the UUID string and cast it to UUID type
      new_user := (v_create_response->>'id')::uuid;

      RETURN jsonb_build_object(
       'code', 201,
       'message', 'User created successfully',
       'user', new_user::text
      );
    END IF;
  END IF;

  -- Global profile is the parent of its occasion projections.
  SELECT to_jsonb(ui) INTO v_global_before FROM public.user_info ui WHERE id=v_user AND organization=v_org FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('code',403,'message','User is outside the unit organization'); END IF;
  -- Update existing user logic
  UPDATE public.user_info
  SET
    data = COALESCE(user_info.data, '{}'::jsonb)
           || public.get_user_profile_data_patch(v_data),
    name = COALESCE(v_data->>'name', user_info.name),
    surname = COALESCE(v_data->>'surname', user_info.surname),
    sex = COALESCE(v_data->>'sex', user_info.sex),
    phone = CASE
      WHEN v_data ? 'phone' THEN v_data->>'phone'
      ELSE user_info.phone
    END,
    birth_date = CASE
      WHEN v_data ? 'birthDate'
        THEN NULLIF(v_data->>'birthDate', '')::date
      ELSE user_info.birth_date
    END
  WHERE id = v_user;

  PERFORM public.publish_user_profile_change_internal_v1(v_user,v_occasion,v_global_before);
  RETURN jsonb_build_object(
   'code', 200,
   'message', 'User details updated successfully',
   'user', v_user
  );

EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('code', 500, 'message', SQLERRM);
END;
$function$

CREATE OR REPLACE FUNCTION public.update_user(usr uuid, oc bigint, data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
    oc_unit bigint;
    usr_info user_info%rowtype;
BEGIN
    -- Retrieve the unit for the given occasion
    SELECT unit INTO oc_unit FROM occasions WHERE id = oc;
    IF oc_unit IS NULL THEN
        RETURN jsonb_build_object('code', 404, 'msg', 'Unit not found');
    END IF;

    -- Allow update if the caller is a manager, admin, or unit editor for the occasion’s unit.
    IF (SELECT get_is_manager_on_occasion(oc)) IS NOT TRUE
       AND (SELECT get_is_admin_on_occasion(oc)) IS NOT TRUE
       AND (SELECT get_is_editor_on_unit(oc_unit)) IS NOT TRUE
    THEN
        RETURN jsonb_build_object('code', 403);
    END IF;

    -- Check if the user exists for the occasion
    IF (SELECT get_exists_on_occasion_user(usr, oc)) IS NOT TRUE THEN
         RETURN jsonb_build_object('code', 403);
    END IF;

    -- Retrieve user information
    SELECT * INTO usr_info FROM user_info WHERE id = usr;

    -- If the user does not exist, insert a new user record
    IF usr_info IS NULL THEN
        RETURN jsonb_build_object('code', 404);
    END IF;

    -- Initialize usr_info.data if it is null
    IF usr_info.data IS NULL THEN
        usr_info.data := '{}'::jsonb;
    END IF;

    -- Merge the input data with the existing user data
    usr_info.data := usr_info.data || data;

    -- Update individual columns if they are provided in the input JSON data
    IF usr_info.data ? 'name' THEN
        UPDATE user_info SET name = usr_info.data->>'name' WHERE id = usr;
    END IF;

    IF usr_info.data ? 'surname' THEN
        UPDATE user_info SET surname = usr_info.data->>'surname' WHERE id = usr;
    END IF;

    IF usr_info.data ? 'sex' THEN
        UPDATE user_info SET sex = usr_info.data->>'sex' WHERE id = usr;
    END IF;

    -- Update the user_info.data column with the modified JSON data
    UPDATE user_info SET data = usr_info.data WHERE id = usr;

    -- Return a success code
    RETURN jsonb_build_object('code', 200);
END;
$function$

CREATE OR REPLACE FUNCTION public.upsert_event_user(event_id integer, user_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
AS $function$
declare
  i_max_participants integer;
  current_participants integer;
  event_group_count integer;
  event_group integer;
  exclusive_event_count integer;
  already_in_count integer;
  current_men_participants integer;
  current_women_participants integer;
  b_split_for_men_women boolean;
  is_current_user_male boolean;

begin

  if CURRENT_TIMESTAMP AT TIME ZONE 'UTC' < '2023-08-10 07:00:00' then
    return 104;
  end if;

  select count(*) from event_users eu where eu.event = event_id and eu."user" = user_id into already_in_count;
  if already_in_count > 0 then
    return 103;
  end if;

  select count(*) from exclusive_events where event = event_id into event_group_count;
  if event_group_count > 0 then
    select "group" from exclusive_events where event = event_id into event_group;
    select count(*) from exclusive_events ee join event_users eu on ee.event = eu.event
    where ee."group" = event_group and eu."user" = user_id into exclusive_event_count;
    if exclusive_event_count > 0 then
      return 102;
    end if;
  end if;

  -- Check if event_table doesnt have more records with event_id than is in table event in column max_participants
  select max_participants from events where id = event_id into i_max_participants;
  select split_for_men_women from events where id = event_id into b_split_for_men_women;

  if b_split_for_men_women then
    select exists (select sex from user_info where id = user_id and sex = 'male') into is_current_user_male;
    select count(*) from event_users eu join user_info ei on eu."user" = ei.id where event = upsert_event_user.event_id and ei.sex = 'male' into current_men_participants;
    select count(*) from event_users eu join user_info ei on eu."user" = ei.id where event = upsert_event_user.event_id and ei.sex <> 'male' into current_women_participants;
    if is_current_user_male and current_men_participants >= (i_max_participants / 2) then
      return 105;
    elsif not is_current_user_male and current_women_participants >= (i_max_participants / 2) then
      return 106;
    end if;
  end if;

  select count(*) from event_users where event = upsert_event_user.event_id into current_participants;

  select count(*) from event_users where event = upsert_event_user.event_id into current_participants;
  if current_participants >= i_max_participants then
    -- If it is more return false
    return 101;
  else
    -- otherwise return true
    insert into event_users (event, "user") values (event_id, user_id);
    return 100;
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.validate_blueprint_canonical_declarations_internal(p_doc jsonb)
 RETURNS void
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE meta jsonb:=public.blueprint_contract_metadata_internal(); entry record; n jsonb; next_node jsonb; a jsonb; placement jsonb; index_nodes jsonb; attachment_seats text[]:='{}'; seat_node jsonb; target_node jsonb; field text;value jsonb;graphic jsonb;crop jsonb;
BEGIN
 IF jsonb_typeof(p_doc) IS DISTINCT FROM 'object' OR p_doc->>'schemaVersion' IS DISTINCT FROM '2' OR p_doc->>'symbolSetVersion' IS DISTINCT FROM '1' OR jsonb_typeof(p_doc->'nodes') IS DISTINCT FROM 'array' OR jsonb_typeof(p_doc->'styles') IS DISTINCT FROM 'object' OR jsonb_typeof(p_doc->'textPolicy') IS DISTINCT FROM 'object' OR jsonb_typeof(p_doc->'seatingDefaults') IS DISTINCT FROM 'object' OR octet_length(p_doc::text)>8388608 OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_doc) key WHERE key NOT IN ('schemaVersion','symbolSetVersion','canvas','styles','seatingDefaults','textPolicy','nodes','attachments','selectionUnits','sections','presets','background')) THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_CANONICAL_LAYOUT';END IF;
 IF EXISTS(SELECT 1 FROM jsonb_object_keys(p_doc->'styles') key WHERE key NOT IN ('label','kinds')) THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_STYLE_SCOPE';END IF;
 IF p_doc->'styles' ? 'label' THEN PERFORM public.blueprint_validate_leaves_internal(p_doc#>'{styles,label}',meta->'label');END IF;
 IF p_doc->'styles' ? 'kinds' THEN
  IF jsonb_typeof(p_doc#>'{styles,kinds}')<>'object' THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_STYLE_SCOPE';END IF;
  FOR entry IN SELECT * FROM jsonb_each(p_doc#>'{styles,kinds}') LOOP
   IF NOT(meta->'styleKinds' ? entry.key) THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_STYLE_KIND';END IF;
   PERFORM public.blueprint_validate_style_internal(entry.value,entry.key);
  END LOOP;
 END IF;
 PERFORM public.blueprint_validate_leaves_internal(p_doc->'seatingDefaults',meta->'seating');
 PERFORM public.blueprint_validate_leaves_internal(p_doc->'textPolicy',jsonb_build_object('language',meta#>'{label,language}','direction',meta#>'{label,direction}'));
 IF NOT(p_doc->'textPolicy' ?& ARRAY['language','direction']) THEN RAISE check_violation USING MESSAGE='BLUEPRINT_MISSING_TEXT_POLICY';END IF;
 FOR n IN SELECT * FROM jsonb_array_elements(p_doc->'nodes') LOOP
  IF jsonb_typeof(n)<>'object' OR (n->>'kind'<>'group' AND NOT(meta->'styleKinds' ? (n->>'kind'))) OR EXISTS(SELECT 1 FROM jsonb_object_keys(n) key WHERE key NOT IN ('id','kind','parentId','transform','width','height','z','locked','label','style','childStyles','seating','surface','assembly','graphic','originalSource') AND NOT(meta->'nodeGeometryKeys' ? key)) THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_CANONICAL_NODE';END IF;
  IF n ? 'originalSource' THEN
   value:=n->'originalSource';
   IF n->>'kind'<>'vector' THEN RAISE check_violation USING MESSAGE='BLUEPRINT_UNEXPECTED_ORIGINAL_SOURCE';END IF;
   PERFORM public.blueprint_validate_leaves_internal(value,meta->'originalSource');
   IF NOT(value ?& ARRAY['format','text','sha256']) OR octet_length(convert_to(value->>'text','UTF8'))>(meta->>'originalSourceBytesMax')::bigint
    OR encode(extensions.digest(convert_to(value->>'text','UTF8'),'sha256'),'hex') IS DISTINCT FROM value->>'sha256' THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_ORIGINAL_SOURCE';END IF;
  END IF;
  PERFORM public.blueprint_validate_style_internal(coalesce(n->'style','{}'),n->>'kind');
  IF n->>'kind'='table' THEN
   IF n ? 'shape' OR n ? 'points' OR n ? 'holes' THEN RAISE check_violation USING MESSAGE='BLUEPRINT_LEGACY_SURFACE_FORBIDDEN';END IF;
   PERFORM public.blueprint_validate_leaves_internal(coalesce(n->'seating','{}'),meta->'seating');
   IF n ? 'childStyles' THEN
    IF jsonb_typeof(n->'childStyles')<>'object' OR EXISTS(SELECT 1 FROM jsonb_object_keys(n->'childStyles') k WHERE k<>'seat') THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_CHILD_STYLE';END IF;
    IF n->'childStyles' ? 'seat' THEN PERFORM public.blueprint_validate_style_internal(n#>'{childStyles,seat}','seat');END IF;
   END IF;
   next_node:=public.blueprint_canonical_surface_projection_internal(n);
  ELSE
   IF n ? 'surface' OR n ? 'childStyles' OR (n ? 'seating' AND NOT(n->>'kind' IN ('group','furniture') AND coalesce(n#>>'{assembly,kind}','') IN ('rows','bus','compartments','couch'))) THEN RAISE check_violation USING MESSAGE='BLUEPRINT_TABLE_RECORD_ON_OTHER_KIND';END IF;
   IF n ? 'seating' THEN PERFORM public.blueprint_validate_leaves_internal(n->'seating',meta->'seating');END IF;
   next_node:=n;
  END IF;
  IF n ? 'assembly' THEN PERFORM public.blueprint_validate_assembly_internal(n->'assembly',n->>'kind');END IF;
  IF n->>'kind'='vector' THEN
   PERFORM public.blueprint_validate_vector_internal(n->'graphic');next_node:=jsonb_set(next_node,'{kind}','"shape"');
  ELSIF n->>'kind'='image' THEN
   graphic:=n->'graphic';crop:=graphic->'crop';
   IF jsonb_typeof(graphic) IS DISTINCT FROM 'object' OR graphic->>'type' IS DISTINCT FROM 'bitmap' OR nullif(graphic->>'assetRef','') IS NULL OR coalesce(graphic->>'hash','') !~ '^[a-f0-9]{64}$' OR EXISTS(SELECT 1 FROM jsonb_object_keys(graphic) k WHERE k NOT IN ('type','assetRef','hash','crop')) OR jsonb_typeof(crop) IS DISTINCT FROM 'object' OR EXISTS(SELECT 1 FROM jsonb_object_keys(crop) k WHERE k NOT IN ('x','y','width','height')) THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_BITMAP';END IF;
   FOREACH field IN ARRAY ARRAY['x','y','width','height'] LOOP IF jsonb_typeof(crop->field) IS DISTINCT FROM 'number' THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_BITMAP_CROP';END IF;END LOOP;
   IF (crop->>'x')::numeric<0 OR (crop->>'y')::numeric<0 OR (crop->>'width')::numeric<=0 OR (crop->>'height')::numeric<=0 OR (crop->>'x')::numeric+(crop->>'width')::numeric>1 OR (crop->>'y')::numeric+(crop->>'height')::numeric>1 THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_BITMAP_CROP';END IF;
   next_node:=jsonb_set(next_node,'{kind}','"shape"');
  ELSIF n ? 'graphic' THEN RAISE check_violation USING MESSAGE='BLUEPRINT_UNEXPECTED_GRAPHIC';END IF;
 END LOOP;
 SELECT coalesce(jsonb_object_agg(item->>'id',item),'{}') INTO index_nodes FROM jsonb_array_elements(p_doc->'nodes') item;
 FOR a IN SELECT * FROM jsonb_array_elements(coalesce(p_doc->'attachments','[]')) LOOP
  seat_node:=index_nodes->(a->>'seatId');target_node:=index_nodes->(a->>'targetId');
  IF coalesce(seat_node->>'kind','')<>'seat' OR seat_node->>'parentId' IS DISTINCT FROM a->>'targetId'
   OR NOT(coalesce(target_node->>'kind','')='table' OR (coalesce(target_node->>'kind','') IN ('group','furniture') AND coalesce(target_node#>>'{assembly,kind}','') IN ('rows','bus','compartments','couch')))
   OR a->>'seatId'=ANY(attachment_seats) THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_ATTACHMENT';END IF;
  attachment_seats:=array_append(attachment_seats,a->>'seatId');
  placement:=a->'placement';
  IF jsonb_typeof(a)<>'object' OR EXISTS(SELECT 1 FROM jsonb_object_keys(a) k WHERE k NOT IN ('id','seatId','targetId','placement','rotationMode')) OR coalesce(a->>'rotationMode','') NOT IN ('auto','manual') OR jsonb_typeof(placement) IS DISTINCT FROM 'object' THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_PLACEMENT';END IF;
  IF placement->>'mode' IN ('automatic','free') THEN
   IF placement-'mode'<>'{}' THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_PLACEMENT';END IF;
  ELSIF placement->>'mode'='sidePinned' THEN
   IF target_node->>'kind'<>'table' THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_SIDE_PIN';END IF;
   IF placement ? 'cell' THEN
    IF EXISTS(SELECT 1 FROM jsonb_object_keys(placement) k WHERE k NOT IN ('mode','cell','face')) OR jsonb_typeof(placement->'cell')<>'array' OR jsonb_array_length(placement->'cell')<>2 OR coalesce(placement->>'face','') NOT IN ('top','right','bottom','left') THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_GRID_PIN';END IF;
    FOR value IN SELECT * FROM jsonb_array_elements(placement->'cell') LOOP IF jsonb_typeof(value)<>'number' OR value::numeric<>trunc(value::numeric) THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_GRID_PIN';END IF;END LOOP;
    IF target_node#>>'{surface,type}' IS DISTINCT FROM 'grid'
     OR NOT public.blueprint_grid_cell_filled_internal(target_node->'surface',(placement#>>'{cell,0}')::numeric,(placement#>>'{cell,1}')::numeric)
     OR public.blueprint_grid_cell_filled_internal(target_node->'surface',(placement#>>'{cell,0}')::numeric+CASE placement->>'face' WHEN 'right' THEN 1 WHEN 'left' THEN -1 ELSE 0 END,(placement#>>'{cell,1}')::numeric+CASE placement->>'face' WHEN 'bottom' THEN 1 WHEN 'top' THEN -1 ELSE 0 END)
     THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_GRID_PIN_BOUNDARY';END IF;
   ELSE
    IF EXISTS(SELECT 1 FROM jsonb_object_keys(placement) k WHERE k NOT IN ('mode','side','t')) OR coalesce(placement->>'side','') NOT IN ('top','right','bottom','left','perimeter') OR jsonb_typeof(placement->'t') IS DISTINCT FROM 'number' OR (placement->>'t')::numeric NOT BETWEEN 0 AND 1 THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_SIDE_PIN';END IF;
    IF (placement->>'side'='perimeter' AND target_node#>>'{surface,type}' IS DISTINCT FROM 'circle') OR (placement->>'side'<>'perimeter' AND target_node#>>'{surface,type}' IS DISTINCT FROM 'rect') THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_SIDE_PIN_SURFACE';END IF;
   END IF;
  ELSE RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_PLACEMENT';END IF;
 END LOOP;
 FOR a IN SELECT * FROM jsonb_array_elements(coalesce(p_doc->'presets','[]')) LOOP
  IF EXISTS(SELECT 1 FROM jsonb_object_keys(a) k WHERE k NOT IN ('id','title','description','document','version')) OR (a->'document' ? 'presets' AND jsonb_array_length(a#>'{document,presets}')>0) THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_PRESET';END IF;
  PERFORM public.validate_blueprint_canonical_declarations_internal(a->'document');
 END LOOP;
 RETURN;
END $function$

CREATE OR REPLACE FUNCTION public.validate_blueprint_geometry_internal(p_doc jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE n jsonb; value jsonb; field text; index_nodes jsonb; current_node jsonb; seen text[]; depth int; a jsonb; ids text[]; referenced text; shape text;
 geometry_keys text[];
BEGIN
 SELECT array_agg(keys.key) INTO geometry_keys FROM jsonb_array_elements_text(public.blueprint_contract_metadata_internal()->'nodeGeometryKeys') keys(key);
 IF jsonb_typeof(p_doc) IS DISTINCT FROM 'object' OR p_doc->>'schemaVersion' IS DISTINCT FROM '2' OR p_doc->>'symbolSetVersion' IS DISTINCT FROM '1'
  OR jsonb_typeof(p_doc->'nodes') IS DISTINCT FROM 'array' OR jsonb_typeof(p_doc->'canvas') IS DISTINCT FROM 'object' THEN
  RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_LAYOUT'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_object_keys(p_doc) key WHERE key<>ALL(ARRAY['schemaVersion','symbolSetVersion','canvas','styles','textPolicy','seatingDefaults','nodes','sections','selectionUnits','attachments','background','presets'])) THEN
  RAISE check_violation USING MESSAGE='BLUEPRINT_UNKNOWN_LAYOUT_FIELD'; END IF;
 IF jsonb_array_length(p_doc->'nodes')>25000 OR (SELECT count(*) FROM jsonb_array_elements(p_doc->'nodes') x WHERE x->>'kind'='seat')>20000 THEN
  RAISE check_violation USING MESSAGE='BLUEPRINT_LAYOUT_LIMIT'; END IF;
 IF EXISTS(WITH RECURSIVE entries(value,key,depth) AS (
   SELECT p_doc,''::text,0 UNION ALL SELECT child.value,child.key,entries.depth+1 FROM entries CROSS JOIN LATERAL (
    SELECT object.value,object.key FROM jsonb_each(CASE WHEN jsonb_typeof(entries.value)='object' THEN entries.value ELSE '{}'::jsonb END) object
    UNION ALL SELECT element.value,''::text FROM jsonb_array_elements(CASE WHEN jsonb_typeof(entries.value)='array' THEN entries.value ELSE '[]'::jsonb END) element
   ) child WHERE entries.depth<=64)
   SELECT 1 FROM entries WHERE entries.depth>64 OR lower(regexp_replace(key,'[_-]','','g')) IN
    ('spot','spotid','product','productid','price','unitprice','currency','orderid','ticket','ticketid','secret','secretid','token','accesstoken','refreshtoken','customer','customerid','email','payment','paymentid','reservation','reservationid','hold','holdid','selected','pending','status','camera','viewport') LIMIT 1) THEN
  RAISE check_violation USING MESSAGE='BLUEPRINT_NON_PORTABLE_LAYOUT'; END IF;
 FOREACH field IN ARRAY ARRAY['sections','selectionUnits','attachments','generators','presets'] LOOP
  IF p_doc ? field AND jsonb_typeof(p_doc->field) IS DISTINCT FROM 'array' THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_LAYOUT_COLLECTION'; END IF;
 END LOOP;
 FOREACH field IN ARRAY ARRAY['x','y','width','height'] LOOP
  value:=p_doc->'canvas'->field;
  IF jsonb_typeof(value) IS DISTINCT FROM 'number' OR abs(value::numeric)>1000000000
   OR (field IN ('width','height') AND (value::numeric<64 OR value::numeric>1000000)) THEN
   RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_CANVAS'; END IF;
 END LOOP;
 IF coalesce(p_doc#>>'{canvas,fill}','') !~ '^#[0-9a-fA-F]{8}$'
  OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_doc->'canvas') key WHERE key<>ALL(ARRAY['x','y','width','height','fill','floorStyle']))
  OR (p_doc#>>'{canvas,floorStyle}' IS NOT NULL AND p_doc#>>'{canvas,floorStyle}' NOT IN ('plain','wood','tile','carpet')) THEN
  RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_CANVAS'; END IF;
 SELECT coalesce(jsonb_object_agg(x->>'id',x),'{}') INTO index_nodes FROM jsonb_array_elements(p_doc->'nodes') x;
 IF (SELECT count(*) FROM jsonb_array_elements(p_doc->'nodes'))<>(SELECT count(DISTINCT x->>'id') FROM jsonb_array_elements(p_doc->'nodes') x) THEN
  RAISE check_violation USING MESSAGE='BLUEPRINT_DUPLICATE_NODE'; END IF;
 FOR n IN SELECT * FROM jsonb_array_elements(p_doc->'nodes') LOOP
  IF jsonb_typeof(n) IS DISTINCT FROM 'object' OR coalesce(n->>'id','') !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
   OR coalesce(n->>'kind','') NOT IN ('group','table','seat','furniture','capacityArea','shape','text','vector','image')
   OR EXISTS(SELECT 1 FROM jsonb_object_keys(n) key WHERE key<>ALL(geometry_keys||ARRAY['id','kind','parentId','transform','width','height','z','locked','label','style','childStyles','seating','surface','assembly','graphic','originalSource'])) THEN
   RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_NODE',DETAIL=jsonb_build_object('nodeId',n->>'id')::text; END IF;
  IF jsonb_typeof(n->'transform') IS DISTINCT FROM 'object'
   OR EXISTS(SELECT 1 FROM jsonb_object_keys(n->'transform') key WHERE key NOT IN ('x','y','rotation')) THEN
   RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_GEOMETRY'; END IF;
  FOREACH field IN ARRAY ARRAY['width','height','x','y','rotation'] LOOP
   value:=CASE WHEN field IN ('width','height') THEN n->field ELSE n->'transform'->field END;
   IF jsonb_typeof(value) IS DISTINCT FROM 'number' OR abs(value::numeric)>1000000000 OR (field IN ('width','height') AND value::numeric<=0) THEN
    RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_GEOMETRY',DETAIL=jsonb_build_object('nodeId',n->>'id')::text; END IF;
  END LOOP;
  IF n ? 'z' AND (jsonb_typeof(n->'z')<>'number' OR (n->>'z')::numeric<>trunc((n->>'z')::numeric)) THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_Z'; END IF;
  IF n ? 'locked' AND jsonb_typeof(n->'locked')<>'boolean' THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_NODE_BOOLEAN';END IF;
  IF n ? 'obstacle' AND jsonb_typeof(n->'obstacle')<>'boolean' THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_NODE_BOOLEAN';END IF;
  IF n ? 'capacity' AND (jsonb_typeof(n->'capacity')<>'number' OR (n->>'capacity')::numeric<0 OR (n->>'capacity')::numeric<>trunc((n->>'capacity')::numeric)) THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_CAPACITY'; END IF;
  shape:=n->>'shape';
  IF shape IS NOT NULL AND shape NOT IN ('rect','rectangle','roundedRect','ellipse','oval','circle','round','polygon','polyline','line','arrow') THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_SHAPE'; END IF;
  IF n->>'symbol' IS NOT NULL AND n->>'symbol' NOT IN ('chair','bench','sofa','wheelchair','driver') THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_SYMBOL'; END IF;
  IF n->>'text' IS NOT NULL AND (jsonb_typeof(n->'text')<>'string' OR length(n->>'text')>4096) OR n->>'kind'='text' AND n->>'text' IS NULL THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_TEXT'; END IF;
  IF n ? 'label' AND jsonb_typeof(n->'label')<>'string' THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_LABEL'; END IF;
  IF n ? 'points' THEN PERFORM public.validate_blueprint_polygon_internal(n->'points',shape='polygon');
  ELSIF shape='polygon' THEN RAISE check_violation USING MESSAGE='BLUEPRINT_MISSING_VERTICES'; END IF;
  IF n ? 'holes' THEN
   IF shape<>'polygon' OR jsonb_typeof(n->'holes')<>'array' OR jsonb_array_length(n->'holes')>128 THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_HOLES'; END IF;
   FOR value IN SELECT * FROM jsonb_array_elements(n->'holes') LOOP PERFORM public.validate_blueprint_polygon_internal(value,true); END LOOP;
  END IF;
  current_node:=n; seen:=ARRAY[n->>'id'];depth:=1;
  WHILE current_node->>'parentId' IS NOT NULL LOOP
   referenced:=current_node->>'parentId';
   IF referenced=ANY(seen) THEN RAISE check_violation USING MESSAGE='BLUEPRINT_PARENT_CYCLE'; END IF;
   current_node:=index_nodes->referenced;
   IF current_node IS NULL OR current_node->>'kind' NOT IN ('group','table','furniture') THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_PARENT'; END IF;
   seen:=array_append(seen,referenced);depth:=depth+1;
   IF depth>16 THEN RAISE check_violation USING MESSAGE='BLUEPRINT_DEPTH_LIMIT'; END IF;
  END LOOP;
 END LOOP;
 -- All authoring IDs use a common UUID namespace, including sections/units.
 SELECT array_agg(x->>'id') INTO ids FROM jsonb_array_elements(p_doc->'nodes') x;
 FOR n IN SELECT item.value FROM jsonb_array_elements(coalesce(p_doc->'sections','[]')) item UNION ALL SELECT item.value FROM jsonb_array_elements(coalesce(p_doc->'selectionUnits','[]')) item
 UNION ALL SELECT item.value FROM jsonb_array_elements(coalesce(p_doc->'presets','[]')) item LOOP
  IF coalesce(n->>'id','') !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' OR n->>'id'=ANY(ids) THEN RAISE check_violation USING MESSAGE='BLUEPRINT_DUPLICATE_OR_INVALID_ID'; END IF;
  ids:=array_append(ids,n->>'id');
 END LOOP;
 FOR a IN SELECT * FROM jsonb_array_elements(coalesce(p_doc->'sections','[]')) LOOP
  IF coalesce(index_nodes->(a->>'rootId')->>'kind','')<>'group' OR coalesce(a->>'title','')='' THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_SECTION'; END IF;
  IF a->'outline' IS NOT NULL AND a->'outline'<>'null'::jsonb THEN PERFORM public.validate_blueprint_polygon_internal(a->'outline',true); END IF;
 END LOOP;
 IF EXISTS(SELECT attachment->>'seatId' FROM jsonb_array_elements(coalesce(p_doc->'attachments','[]')) attachment GROUP BY attachment->>'seatId' HAVING count(*)>1)
  OR EXISTS(SELECT section->>'rootId' FROM jsonb_array_elements(coalesce(p_doc->'sections','[]')) section GROUP BY section->>'rootId' HAVING count(*)>1) THEN
  RAISE check_violation USING MESSAGE='BLUEPRINT_DUPLICATE_AUTHORING_REFERENCE'; END IF;
 IF jsonb_array_length(coalesce(p_doc->'presets','[]'))>100 THEN RAISE check_violation USING MESSAGE='BLUEPRINT_PRESET_LIMIT'; END IF;
 FOR a IN SELECT * FROM jsonb_array_elements(coalesce(p_doc->'presets','[]')) LOOP
  IF coalesce(a->>'title','')='' OR jsonb_typeof(a->'document') IS DISTINCT FROM 'object' OR jsonb_array_length(coalesce(a#>'{document,nodes}','[]'))>2000 THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_PRESET'; END IF;
  PERFORM public.validate_blueprint_geometry_internal(a->'document');
 END LOOP;
END $function$

CREATE OR REPLACE FUNCTION public.validate_blueprint_polygon_internal(p_points jsonb, p_closed boolean)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE i int;j int;size int; a jsonb;b jsonb;c jsonb;d jsonb;ab_c numeric;ab_d numeric;cd_a numeric;cd_b numeric; area numeric:=0;
BEGIN
 IF jsonb_typeof(p_points) IS DISTINCT FROM 'array' OR jsonb_array_length(p_points) NOT BETWEEN (CASE WHEN p_closed THEN 3 ELSE 2 END) AND 512 THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_VERTICES'; END IF;
 size:=jsonb_array_length(p_points);
 FOR a IN SELECT * FROM jsonb_array_elements(p_points) LOOP
  IF jsonb_typeof(a)<>'array' OR jsonb_array_length(a)<>2 OR jsonb_typeof(a->0)<>'number' OR jsonb_typeof(a->1)<>'number' OR abs((a->>0)::numeric)>1000000000 OR abs((a->>1)::numeric)>1000000000 THEN RAISE check_violation USING MESSAGE='BLUEPRINT_INVALID_VERTICES'; END IF;
 END LOOP;
 IF NOT p_closed THEN RETURN; END IF;
 FOR i IN 0..size-1 LOOP
  a:=p_points->i;b:=p_points->((i+1)%size);
  area:=area+(a->>0)::numeric*(b->>1)::numeric-(b->>0)::numeric*(a->>1)::numeric;
  FOR j IN i+1..size-1 LOOP
   IF j=i+1 OR (i=0 AND j=size-1) THEN CONTINUE; END IF;
   c:=p_points->j;d:=p_points->((j+1)%size);
   ab_c:=((b->>0)::numeric-(a->>0)::numeric)*((c->>1)::numeric-(a->>1)::numeric)-((b->>1)::numeric-(a->>1)::numeric)*((c->>0)::numeric-(a->>0)::numeric);
   ab_d:=((b->>0)::numeric-(a->>0)::numeric)*((d->>1)::numeric-(a->>1)::numeric)-((b->>1)::numeric-(a->>1)::numeric)*((d->>0)::numeric-(a->>0)::numeric);
   cd_a:=((d->>0)::numeric-(c->>0)::numeric)*((a->>1)::numeric-(c->>1)::numeric)-((d->>1)::numeric-(c->>1)::numeric)*((a->>0)::numeric-(c->>0)::numeric);
   cd_b:=((d->>0)::numeric-(c->>0)::numeric)*((b->>1)::numeric-(c->>1)::numeric)-((d->>1)::numeric-(c->>1)::numeric)*((b->>0)::numeric-(c->>0)::numeric);
   IF ab_c*ab_d<=0 AND cd_a*cd_b<=0 AND greatest(least((a->>0)::numeric,(b->>0)::numeric),least((c->>0)::numeric,(d->>0)::numeric))<=least(greatest((a->>0)::numeric,(b->>0)::numeric),greatest((c->>0)::numeric,(d->>0)::numeric))
    AND greatest(least((a->>1)::numeric,(b->>1)::numeric),least((c->>1)::numeric,(d->>1)::numeric))<=least(greatest((a->>1)::numeric,(b->>1)::numeric),greatest((c->>1)::numeric,(d->>1)::numeric)) THEN RAISE check_violation USING MESSAGE='BLUEPRINT_SELF_INTERSECTION'; END IF;
  END LOOP;
 END LOOP;
 IF abs(area)<0.000000001 THEN RAISE check_violation USING MESSAGE='BLUEPRINT_DEGENERATE_POLYGON'; END IF;
END $function$

CREATE OR REPLACE FUNCTION public.validate_occasion_user_csv_import_v1(p_occasion_id bigint, p_rows jsonb, p_delete_user_ids jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
    v_unit_id bigint;
BEGIN
    SELECT o.unit INTO v_unit_id
      FROM public.occasions o
     WHERE o.id = p_occasion_id;
    IF v_unit_id IS NULL THEN
        RAISE EXCEPTION 'OCCASION_NOT_FOUND';
    END IF;
    IF NOT (
        public.get_is_manager_on_occasion(p_occasion_id)
        OR public.get_is_admin_on_occasion(p_occasion_id)
        OR public.get_is_editor_on_unit(v_unit_id)
    ) THEN
        RAISE EXCEPTION 'NOT_AUTHORIZED';
    END IF;
    IF COALESCE(jsonb_typeof(p_rows), 'null') <> 'array'
       OR COALESCE(jsonb_typeof(p_delete_user_ids), 'null') <> 'array' THEN
        RAISE EXCEPTION 'INVALID_IMPORT_PAYLOAD';
    END IF;
    IF jsonb_array_length(p_rows) > 10000
       OR jsonb_array_length(p_delete_user_ids) > 10000 THEN
        RAISE EXCEPTION 'IMPORT_PAYLOAD_TOO_LARGE';
    END IF;
    IF EXISTS (
        SELECT 1 FROM jsonb_array_elements(p_rows) item
         WHERE jsonb_typeof(item) <> 'object'
            OR jsonb_typeof(item->'data') <> 'object'
    ) THEN
        RAISE EXCEPTION 'INVALID_IMPORT_ROW';
    END IF;
    IF EXISTS (
        SELECT 1 FROM jsonb_array_elements(p_rows) item
         WHERE NULLIF(btrim(item->'data'->>'email'), '') IS NULL
    ) THEN
        RAISE EXCEPTION 'EMAIL_REQUIRED';
    END IF;
    IF EXISTS (
        SELECT 1 FROM jsonb_array_elements(p_rows) item
         WHERE length(btrim(item->'data'->>'email')) > 254
            OR lower(btrim(item->'data'->>'email'))
               !~ '^[^[:space:]@]+@[^[:space:]@]+$'
            OR (
                item ? 'email_delivery'
                AND (
                    NULLIF(btrim(item->>'email_delivery'), '') IS NULL
                    OR length(btrim(item->>'email_delivery')) > 254
                    OR lower(btrim(item->>'email_delivery'))
                       !~ '^[^[:space:]@]+@[^[:space:]@]+$'
                )
            )
    ) THEN
        RAISE EXCEPTION 'INVALID_EMAIL';
    END IF;
    IF EXISTS (
        SELECT 1 FROM jsonb_array_elements(p_rows) item
         GROUP BY lower(btrim(item->'data'->>'email'))
        HAVING count(*) > 1
    ) THEN
        RAISE EXCEPTION 'DUPLICATE_ACCOUNT_EMAIL';
    END IF;
    IF EXISTS (
        SELECT 1 FROM jsonb_array_elements(p_rows) item
         WHERE NULLIF(item->>'user_id', '') IS NOT NULL
         GROUP BY item->>'user_id'
        HAVING count(*) > 1
    ) THEN
        RAISE EXCEPTION 'DUPLICATE_USER_ID';
    END IF;
    IF EXISTS (
        SELECT 1
          FROM jsonb_array_elements(p_rows) item
          JOIN jsonb_array_elements_text(p_delete_user_ids) deleted(id)
            ON deleted.id = item->>'user_id'
    ) THEN
        RAISE EXCEPTION 'CONFLICTING_IMPORT_OPERATION';
    END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_product_price(p_price numeric, p_data jsonb, p_currency text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_deposit numeric; v_digits integer;
BEGIN
  -- Match ISO currency minor units, including currencies without cents.
  v_digits := CASE WHEN p_currency IN ('JPY','KRW','VND','CLP','ISK','BIF','DJF','GNF','KMF','PYG','RWF','UGX','VUV','XAF','XOF','XPF') THEN 0
    WHEN p_currency IN ('BHD','IQD','JOD','KWD','LYD','OMR','TND') THEN 3 ELSE 2 END;
  -- Current products.price is numeric(10,2); never schedule an unrepresentable target.
  v_digits := least(v_digits,2);
  IF p_price IS NULL OR p_price::text IN ('NaN','Infinity','-Infinity') OR p_price < 0 OR p_price > 99999999.99
    OR p_price <> round(p_price,v_digits) THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='INVALID_PRODUCT_PRICE';
  END IF;
  v_deposit := NULLIF(p_data->'deposit'->>'amount','')::numeric;
  IF v_deposit > 0 AND v_deposit >= p_price THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='DEPOSIT_AMOUNT_TOO_HIGH';
  END IF;
END; $function$

CREATE OR REPLACE FUNCTION public.validate_product_price_update(p_id bigint, p_price numeric, p_data jsonb, p_currency text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_product eshop.products%ROWTYPE;
BEGIN
  SELECT * INTO STRICT v_product FROM eshop.products WHERE id=p_id FOR UPDATE;
  PERFORM public.validate_product_price(p_price,p_data,p_currency);
  IF p_currency IS DISTINCT FROM v_product.currency_code AND EXISTS (
    SELECT 1 FROM eshop.planned_changes WHERE subject_id=p_id AND change_type='products.price' AND NOT applied
  ) THEN RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='CANCEL_PRICE_CHANGES_BEFORE_CURRENCY_CHANGE'; END IF;
END; $function$

CREATE OR REPLACE FUNCTION public.validate_product_type(product_id bigint, required_type text)
 RETURNS boolean
 LANGUAGE plpgsql
AS $function$
DECLARE
    product_type RECORD;
BEGIN
    -- Retrieve the product's type
    SELECT it.*
    INTO product_type
    FROM eshop.products i
    JOIN eshop.product_types it ON i.product_type = it.id
    WHERE i.id = product_id;

    -- Check if the type matches
    IF product_type IS NULL THEN
        RAISE EXCEPTION 'product with ID % not found or has no type.', product_id;
    END IF;

    IF product_type.type = required_type THEN
        RETURN TRUE;
    ELSE
        RAISE EXCEPTION 'product with ID % is not of type %. Found type: %', product_id, required_type, product_type.type;
    END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_ticket_layout(p_layout jsonb)
 RETURNS void
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE t jsonb; e jsonb; b jsonb; s jsonb; a jsonb; q jsonb; kind text; k text; ids text[]; bindings text[]; luminance double precision; background_luminance double precision;
BEGIN
  IF p_layout IS NULL OR jsonb_typeof(p_layout) <> 'object' OR p_layout->'schemaVersion' IS DISTINCT FROM '3'::jsonb OR NOT (p_layout ? 'schemaVersion')
    OR jsonb_typeof(p_layout->'templates') IS DISTINCT FROM 'object' OR p_layout->'templates'='{}'::jsonb OR octet_length(p_layout::text)>32768
  THEN RAISE EXCEPTION 'Invalid ticket layout'; END IF;
  IF EXISTS(SELECT 1 FROM jsonb_object_keys(p_layout) AS keys(key) WHERE keys.key NOT IN ('schemaVersion','templates')) THEN RAISE EXCEPTION 'Invalid layout metadata'; END IF;
  IF (SELECT count(DISTINCT id) FROM (
    SELECT value->>'fontId' id FROM jsonb_each(p_layout->'templates')
    UNION ALL SELECT elem.value->'style'->>'fontId' FROM jsonb_each(p_layout->'templates') tmpl CROSS JOIN LATERAL jsonb_array_elements(tmpl.value->'elements') elem
  ) fonts WHERE id IS NOT NULL)>12 THEN RAISE EXCEPTION 'Too many ticket fonts'; END IF;
  FOR kind,t IN SELECT * FROM jsonb_each(p_layout->'templates') LOOP
    IF EXISTS(SELECT 1 FROM jsonb_object_keys(t) AS keys(key) WHERE keys.key NOT IN ('canvasColor','canvasOpacity','backgroundCrop','pageMargin','backgroundTransform','fontId','flow','flowStep','qrAppearance','border','pageFit','page','ticketArea','elements')) THEN RAISE EXCEPTION 'Invalid template metadata'; END IF;
    IF kind NOT IN ('wide','named') OR jsonb_typeof(t->'elements') IS DISTINCT FROM 'array'
      OR jsonb_array_length(t->'elements') NOT BETWEEN 2 AND 32
      OR (t ? 'pageFit' AND t->'pageFit' IS DISTINCT FROM '"ticket"'::jsonb)
      OR (NOT (t ? 'pageFit')
          AND t->'page' IS DISTINCT FROM '{"width":595.28,"height":841.89}'::jsonb
          AND t->'page' IS DISTINCT FROM '{"width":212.5,"height":387.5}'::jsonb)
    THEN RAISE EXCEPTION 'Invalid ticket template'; END IF;
    IF t ? 'canvasOpacity' AND (jsonb_typeof(t->'canvasOpacity') IS DISTINCT FROM 'number'
      OR (t->>'canvasOpacity')::numeric NOT BETWEEN 0 AND 1)
    THEN RAISE EXCEPTION 'Invalid ticket canvas opacity'; END IF;
    IF t ? 'canvasColor' AND (jsonb_typeof(t->'canvasColor') IS DISTINCT FROM 'string'
      OR (t->>'canvasColor' <> 'transparent' AND t->>'canvasColor' !~ '^[a-fA-F0-9]{6}$'))
    THEN RAISE EXCEPTION 'Invalid ticket canvas color'; END IF;
    IF t ? 'pageMargin' THEN
      IF t->>'pageFit' IS DISTINCT FROM 'ticket' OR jsonb_typeof(t->'pageMargin') IS DISTINCT FROM 'number'
      THEN RAISE EXCEPTION 'Invalid ticket page margin'; END IF;
      IF (t->>'pageMargin')::numeric NOT BETWEEN 0 AND 72 THEN RAISE EXCEPTION 'Invalid ticket page margin'; END IF;
    END IF;
    IF t->>'pageFit'='ticket' THEN
      IF jsonb_typeof(t->'page'->'width') IS DISTINCT FROM 'number'
        OR jsonb_typeof(t->'page'->'height') IS DISTINCT FROM 'number'
      THEN RAISE EXCEPTION 'Invalid ticket page'; END IF;
      IF (t->'page'->>'width')::numeric NOT BETWEEN 60 AND 842
        OR (t->'page'->>'height')::numeric NOT BETWEEN 60 AND 842
        OR t->'ticketArea'->'x' IS DISTINCT FROM COALESCE(t->'pageMargin','0'::jsonb)
        OR t->'ticketArea'->'y' IS DISTINCT FROM COALESCE(t->'pageMargin','0'::jsonb)
        OR abs((t->'ticketArea'->>'width')::numeric+2*COALESCE((t->>'pageMargin')::numeric,0)-(t->'page'->>'width')::numeric)>.001
        OR abs((t->'ticketArea'->>'height')::numeric+2*COALESCE((t->>'pageMargin')::numeric,0)-(t->'page'->>'height')::numeric)>.001
      THEN RAISE EXCEPTION 'Ticket page must match ticket area'; END IF;
    END IF;
    IF t ? 'font' AND COALESCE(t->>'font','') NOT IN ('futura','robotoSlab','roboto','russoOne') THEN RAISE EXCEPTION 'Invalid ticket font'; END IF;
    IF t ? 'border' AND jsonb_typeof(t->'border') IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'Invalid ticket border'; END IF;
    IF t ? 'flowStep' AND (jsonb_typeof(t->'flowStep') IS DISTINCT FROM 'number' OR (t->>'flowStep')::numeric NOT BETWEEN 1 AND 842) THEN RAISE EXCEPTION 'Invalid ticket flow spacing'; END IF;
    IF t ? 'flow' THEN
      IF jsonb_typeof(t->'flow') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'Invalid ticket flow'; END IF;
      IF EXISTS(SELECT 1 FROM jsonb_array_elements_text(t->'flow') AS flow_item(value) WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(t->'elements') AS flow_element(value) WHERE flow_element.value->>'id'=flow_item.value AND flow_element.value->>'binding' NOT IN ('qr','logo')))
        OR (SELECT count(*)<>count(DISTINCT flow_item.value) FROM jsonb_array_elements_text(t->'flow') AS flow_item(value))
      THEN RAISE EXCEPTION 'Invalid ticket flow'; END IF;
    END IF;
    IF t ? 'qrAppearance' THEN
      IF jsonb_typeof(t->'qrAppearance') IS DISTINCT FROM 'object'
        OR COALESCE(t->'qrAppearance'->>'background','') !~ '^[a-fA-F0-9]{6}$'
        OR jsonb_typeof(t->'qrAppearance'->'opacity') IS DISTINCT FROM 'number'
        OR jsonb_typeof(t->'qrAppearance'->'margin') IS DISTINCT FROM 'number'
      THEN RAISE EXCEPTION 'Invalid QR appearance'; END IF;
      IF (t->'qrAppearance'->>'opacity')::numeric NOT BETWEEN 0 AND 1 OR (t->'qrAppearance'->>'margin')::numeric NOT BETWEEN 0 AND 8 THEN RAISE EXCEPTION 'Invalid QR appearance'; END IF;
    END IF;
    IF t ? 'font' THEN RAISE EXCEPTION 'Legacy font field in schema 2'; END IF;
    IF t ? 'fontId' THEN
      IF jsonb_typeof(t->'fontId')<>'string'
        OR NOT EXISTS(SELECT 1 FROM public.ticket_font_assets WHERE id=t->>'fontId')
      THEN RAISE EXCEPTION 'Invalid ticket font'; END IF;
    END IF;
    IF t ? 'backgroundCrop' THEN
      b:=t->'backgroundCrop';
      IF jsonb_typeof(b) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'Invalid background crop'; END IF;
      FOREACH k IN ARRAY ARRAY['x','y','width','height'] LOOP
        IF jsonb_typeof(b->k) IS DISTINCT FROM 'number' THEN RAISE EXCEPTION 'Invalid background crop'; END IF;
      END LOOP;
      IF (b->>'x')::numeric<0 OR (b->>'y')::numeric<0
        OR (b->>'width')::numeric<.001 OR (b->>'height')::numeric<.001
        OR (b->>'x')::numeric+(b->>'width')::numeric>1.000001
        OR (b->>'y')::numeric+(b->>'height')::numeric>1.000001
      THEN RAISE EXCEPTION 'Invalid background crop'; END IF;
    END IF;
    IF t ? 'backgroundTransform' THEN
      b:=t->'backgroundTransform';
      IF jsonb_typeof(b) IS DISTINCT FROM 'object'
        OR jsonb_typeof(b->'scale') IS DISTINCT FROM 'number'
        OR jsonb_typeof(b->'x') IS DISTINCT FROM 'number'
        OR jsonb_typeof(b->'y') IS DISTINCT FROM 'number'
      THEN RAISE EXCEPTION 'Invalid background transform'; END IF;
      IF (b->>'scale')::numeric NOT BETWEEN .1 AND 10
        OR abs((b->>'x')::numeric)>10 OR abs((b->>'y')::numeric)>10
      THEN RAISE EXCEPTION 'Invalid background transform'; END IF;
    END IF;
    a:=t->'ticketArea'; ids:='{}'; bindings:='{}';
    FOR b IN SELECT a UNION ALL SELECT value->'box' FROM jsonb_array_elements(t->'elements') LOOP
      FOR k IN SELECT unnest(ARRAY['x','y','width','height']) LOOP
        IF jsonb_typeof(b->k) IS DISTINCT FROM 'number' OR (b->>k)::numeric<0 OR (b->>k)::numeric>842
        THEN RAISE EXCEPTION 'Invalid layout box'; END IF;
      END LOOP;
      IF (b->>'width')::numeric<1 OR (b->>'height')::numeric<1 THEN RAISE EXCEPTION 'Empty layout box'; END IF;
    END LOOP;
    IF (a->>'x')::numeric+(a->>'width')::numeric>(t->'page'->>'width')::numeric+.001
      OR (a->>'y')::numeric+(a->>'height')::numeric>(t->'page'->>'height')::numeric+.001
    THEN RAISE EXCEPTION 'Ticket outside page'; END IF;
    FOR e IN SELECT * FROM jsonb_array_elements(t->'elements') LOOP
      b:=e->'box'; s:=e->'style';
      IF s ? 'fontId' THEN
        IF e->>'binding' IN ('qr','logo') OR jsonb_typeof(s->'fontId')<>'string'
          OR NOT EXISTS(SELECT 1 FROM public.ticket_font_assets WHERE id=s->>'fontId')
        THEN RAISE EXCEPTION 'Invalid ticket font'; END IF;
      END IF;
      IF e->>'binding' IS NULL OR e->>'binding' NOT IN ('qr','ticketSymbol','spotGroup','productType','note','price','occasionTitle','occasionDatePlace','occasionStartTime','occasionPlace','orderName','logo','footer','text')
        OR (e->>'binding' NOT IN ('productType','text') AND e->>'binding'=ANY(bindings)) OR e->>'id'=ANY(ids) OR COALESCE(e->>'id','') !~ '^[a-zA-Z0-9_-]{1,40}$'
        OR jsonb_typeof(e->'visible') IS DISTINCT FROM 'boolean' OR jsonb_typeof(e->'locked') IS DISTINCT FROM 'boolean'
        OR (b->>'x')::numeric+(b->>'width')::numeric>(a->>'width')::numeric+.001
        OR (b->>'y')::numeric+(b->>'height')::numeric>(a->>'height')::numeric+.001
      THEN RAISE EXCEPTION 'Invalid layout element'; END IF;
      IF EXISTS(SELECT 1 FROM jsonb_object_keys(e) AS keys(key) WHERE keys.key NOT IN ('id','binding','productTypeId','label','text','box','visible','locked','style')) THEN RAISE EXCEPTION 'Invalid element metadata'; END IF;
      IF e->>'binding'='productType' THEN
        IF jsonb_typeof(e->'productTypeId') IS DISTINCT FROM 'number' OR jsonb_typeof(e->'label') IS DISTINCT FROM 'string' THEN RAISE EXCEPTION 'Invalid product field'; END IF;
        IF (e->>'productTypeId')::numeric NOT BETWEEN 1 AND 9007199254740991 OR trunc((e->>'productTypeId')::numeric)<>(e->>'productTypeId')::numeric
          OR e->>'label'<>btrim(e->>'label',U&'\0009\000A\000B\000C\000D\0020\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000\FEFF') OR length(e->>'label')>120
          OR (SELECT count(*) FROM jsonb_array_elements(t->'elements') x WHERE x->'productTypeId'=e->'productTypeId')<>1
        THEN RAISE EXCEPTION 'Invalid product field'; END IF;
      ELSIF e ? 'productTypeId' OR e ? 'label' THEN RAISE EXCEPTION 'Invalid product metadata'; END IF;
      IF e->>'binding'='text' THEN
        IF jsonb_typeof(e->'text') IS DISTINCT FROM 'string' OR length(e->>'text')>2000 THEN RAISE EXCEPTION 'Invalid free text'; END IF;
      ELSIF e ? 'text' THEN RAISE EXCEPTION 'Unexpected free text'; END IF;
      ids:=array_append(ids,e->>'id'); bindings:=array_append(bindings,e->>'binding');
      IF jsonb_typeof(s->'fontSize') IS DISTINCT FROM 'number' OR jsonb_typeof(s->'minFontSize') IS DISTINCT FROM 'number'
        OR jsonb_typeof(s->'maxLines') IS DISTINCT FROM 'number' OR COALESCE(s->>'color','') !~ '^[a-fA-F0-9]{6}$'
        OR COALESCE(s->>'align','') NOT IN ('left','center','right')
        OR (s ? 'bold' AND jsonb_typeof(s->'bold') IS DISTINCT FROM 'boolean')
        OR (s ? 'italic' AND jsonb_typeof(s->'italic') IS DISTINCT FROM 'boolean')
        OR (s ? 'underline' AND jsonb_typeof(s->'underline') IS DISTINCT FROM 'boolean')
      THEN RAISE EXCEPTION 'Invalid layout style'; END IF;
      IF (s->>'fontSize')::numeric NOT BETWEEN 6 AND 72 OR (s->>'minFontSize')::numeric NOT BETWEEN 6 AND (s->>'fontSize')::numeric
        OR (s->>'maxLines')::numeric NOT BETWEEN 1 AND 12 OR (s->>'maxLines')::numeric<>trunc((s->>'maxLines')::numeric)
      THEN RAISE EXCEPTION 'Invalid text size'; END IF;
      IF e->>'binding' IN ('qr','ticketSymbol') AND e->'visible'<>'true'::jsonb THEN RAISE EXCEPTION 'Required ticket element hidden'; END IF;
      IF e->>'binding'='qr' THEN
        q:=b;
        SELECT sum((CASE WHEN channel<=.04045 THEN channel/12.92 ELSE power((channel+.055)/1.055,2.4) END)*weight)
          INTO luminance FROM (SELECT get_byte(decode(s->>'color','hex'),i)/255.0 AS channel, weight
            FROM (VALUES (0,.2126),(1,.7152),(2,.0722)) AS rgb(i,weight)) AS linear;
        SELECT sum((CASE WHEN channel<=.04045 THEN channel/12.92 ELSE power((channel+.055)/1.055,2.4) END)*weight)
          INTO background_luminance FROM (SELECT get_byte(decode(COALESCE(t->'qrAppearance'->>'background','FFFFFF'),'hex'),i)/255.0 AS channel, weight
            FROM (VALUES (0,.2126),(1,.7152),(2,.0722)) AS rgb(i,weight)) AS linear;
        IF b->'width'<>b->'height' OR (b->>'width')::numeric<60 OR (greatest(luminance,background_luminance)+.05)/(least(luminance,background_luminance)+.05)<4.5 THEN RAISE EXCEPTION 'Invalid QR dimensions or contrast'; END IF;
      END IF;
    END LOOP;
    IF NOT bindings @> ARRAY['qr','ticketSymbol'] THEN RAISE EXCEPTION 'Missing required ticket elements'; END IF;
    FOR e IN SELECT * FROM jsonb_array_elements(t->'elements') LOOP
      b:=e->'box';
      IF e->'visible'='true'::jsonb AND e->>'binding' NOT IN ('qr','logo')
        AND (b->>'x')::numeric<(q->>'x')::numeric+(q->>'width')::numeric
        AND (b->>'x')::numeric+(b->>'width')::numeric>(q->>'x')::numeric
        AND (b->>'y')::numeric<(q->>'y')::numeric+(q->>'height')::numeric
        AND (b->>'y')::numeric+(b->>'height')::numeric>(q->>'y')::numeric
      THEN RAISE EXCEPTION 'Text overlaps QR quiet zone'; END IF;
    END LOOP;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_waitlist_answers_internal(p_form bigint, p_input jsonb, p_people jsonb, p_waitlist boolean)
 RETURNS void
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE f public.form_fields; person jsonb; values jsonb; k text; max_people integer;
BEGIN
 IF jsonb_typeof(p_people)<>'array' OR jsonb_array_length(p_people)<1 OR jsonb_array_length(p_people)>public.ticket_order_limit() THEN
  RAISE EXCEPTION 'Invalid participant count'; END IF;
 SELECT min((data->>'max_tickets')::integer) INTO max_people FROM public.form_fields WHERE form=p_form AND type='ticket';
 IF jsonb_array_length(p_people)>coalesce(max_people,public.ticket_order_limit()) THEN RAISE EXCEPTION 'Maximum participants exceeded'; END IF;
 FOR f IN SELECT * FROM public.form_fields WHERE form=p_form AND is_required AND NOT is_hidden
 AND type NOT IN ('ticket','html','product_type') AND (NOT p_waitlist OR product_type IS NULL) LOOP
  k:=f.id::text;
  IF f.is_ticket_field THEN
   FOR person IN SELECT * FROM jsonb_array_elements(p_people) LOOP
    -- Selected seats use the ticket's top-level spot transport. The finalizer
    -- checks occasion ownership, availability and reservation secret afterward.
    IF f.type='spot' AND (p_waitlist OR nullif(person->>'spot','') IS NOT NULL) THEN
     CONTINUE;
    END IF;
    IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(person->'fields','[]')) answer WHERE answer ? k AND nullif(answer->>k,'') IS NOT NULL) THEN
     RAISE EXCEPTION '%',jsonb_build_object('code',400,'errorCode','REQUIRED_FIELD_MISSING','fieldId',f.id)::text; END IF;
   END LOOP;
  ELSE
   IF nullif(p_input->>f.type,'') IS NULL AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(p_input->'fields','[]')) answer WHERE answer ? k AND nullif(answer->>k,'') IS NOT NULL) THEN
    RAISE EXCEPTION '%',jsonb_build_object('code',400,'errorCode','REQUIRED_FIELD_MISSING','fieldId',f.id)::text; END IF;
  END IF;
 END LOOP;
END $function$

CREATE OR REPLACE FUNCTION public.wake_email_worker()
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_url text;
BEGIN
 IF current_user NOT IN ('postgres','service_role') THEN PERFORM public.require_service_role(); END IF;
 IF current_setting('festapp.email_wake',true)='scheduled' THEN RETURN; END IF;
 SELECT worker_url INTO v_url FROM public.email_capacity WHERE NOT paused;
 IF v_url IS NULL OR NOT (EXISTS(SELECT 1 FROM public.email_messages WHERE workflow_state IN ('pending','retry_wait') AND target_time<=now())
  OR EXISTS(SELECT 1 FROM public.email_capacity WHERE quota_at IS NULL OR quota_at<now()-interval '5 minutes')) THEN RETURN; END IF;
 PERFORM set_config('festapp.email_wake','scheduled',true);
 BEGIN
  PERFORM net.http_post(url:=v_url,body:=jsonb_build_object('requestSecret',public.generate_request_secret(120)),timeout_milliseconds:=5000);
 EXCEPTION WHEN OTHERS THEN
  -- Do not invert producer order/message locks against gateway capacity/order locks.
  UPDATE public.email_capacity SET wake_error='wake_failed' WHERE ctid IN (SELECT ctid FROM public.email_capacity FOR UPDATE SKIP LOCKED);
 END;
END $function$

CREATE OR REPLACE FUNCTION public.write_activity_history_internal_v1(p_occasion bigint, p_actor uuid, p_data jsonb, p_type text, p_parent bigint, p_note text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE hid bigint;
BEGIN
 IF p_type NOT IN ('AUTOSAVE','PUBLISH') OR (p_parent IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.activity_history WHERE id=p_parent AND occasion_id=p_occasion AND history_type='PUBLISH')) THEN RAISE invalid_parameter_value USING MESSAGE='invalid history parent or type'; END IF;
 IF p_type='AUTOSAVE' THEN PERFORM public.clear_activity_draft_internal_v1(p_occasion,p_actor,NULL,false); END IF;
 INSERT INTO public.activity_history(occasion_id,user_id,activities_data,history_type,note,parent_history_id) VALUES(p_occasion,p_actor,p_data,p_type,p_note,p_parent) RETURNING id INTO hid;
 RETURN hid;
END $function$

CREATE OR REPLACE FUNCTION public.write_user_group_members_internal_v1(p_occasion bigint, p_group bigint, p_members jsonb, p_replace boolean)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE affected integer;
BEGIN
 PERFORM 1 FROM public.user_group_info WHERE id=p_group AND occasion=p_occasion FOR UPDATE;
 IF NOT FOUND THEN RAISE invalid_parameter_value USING MESSAGE='foreign group'; END IF;
 IF p_members IS NULL OR jsonb_typeof(p_members) IS DISTINCT FROM 'array' OR jsonb_array_length(p_members)>5000
  OR EXISTS(SELECT 1 FROM jsonb_to_recordset(p_members) x(user_id uuid,is_admin boolean)
   LEFT JOIN public.occasion_users ou ON ou.occasion=p_occasion AND ou."user"=x.user_id WHERE ou."user" IS NULL)
  OR jsonb_array_length(p_members)<>(SELECT count(DISTINCT x.user_id) FROM jsonb_to_recordset(p_members) x(user_id uuid)) THEN
  RAISE invalid_parameter_value USING MESSAGE='invalid group members'; END IF;
 IF p_replace THEN DELETE FROM public.user_groups WHERE "group"=p_group; END IF;
 INSERT INTO public.user_groups("group","user",is_admin)
 SELECT p_group,x.user_id,coalesce(x.is_admin,false) FROM jsonb_to_recordset(p_members) x(user_id uuid,is_admin boolean)
 ON CONFLICT("group","user") DO NOTHING;
 GET DIAGNOSTICS affected=ROW_COUNT;
 RETURN affected;
END $function$
